class OrderFlowEngine:
    """Aggregates cross-exchange and derivatives signals into a probability adjustment."""

    def __init__(self, cross_feed=None, coinglass=None, kalshi_oft=None):
        self._cross = cross_feed
        self._coinglass = coinglass
        self._kalshi_oft = kalshi_oft

    def get_signals(self, asset: str, **kwargs) -> Dict:
        """Compute order flow adjustment for the given asset.

        Returns:
            {
                "prob_adjustment": float,
                "confidence": "high"|"moderate"|"low"|"none",
                "signals": {
                    "cross_exchange": {...lead_lag dict...},
                    "funding": {"rate": float|None, "level": str},
                },
                "adjustments_applied": [str, ...],
            }
        """
        adjustments: List[Tuple[str, float]] = []
        cross_exchange = {}
        funding_info = {"rate": None, "level": "unknown"}

        # 1. Cross-exchange consensus
        if self._cross is not None:
            try:
                lead_lag = self._cross.get_lead_lag(asset)
                cross_exchange = lead_lag
                direction = lead_lag.get("consensus_direction", "none")
                above = lead_lag.get("exchanges_above", 0)
                below = lead_lag.get("exchanges_below", 0)

                if direction == "above" and above >= CROSS_EXCHANGE_CONSENSUS_MIN:
                    adjustments.append((
                        f"consensus_above_{above}ex",
                        OFA_CONSENSUS_BOOST,
                    ))
                elif direction == "below" and below >= CROSS_EXCHANGE_CONSENSUS_MIN:
                    adjustments.append((
                        f"consensus_below_{below}ex",
                        OFA_CONSENSUS_REDUCE,
                    ))
                elif direction == "mixed":
                    # Weaker signal: at least one exchange leads
                    if above > below:
                        adjustments.append(("lead_above_mixed", OFA_LEAD_BOOST))
                    elif below > above:
                        adjustments.append(("lead_below_mixed", -OFA_LEAD_BOOST))
            except Exception:
                logging.debug("CrossExchangeFeed.get_lead_lag failed", exc_info=True)

        # 2. Funding rate
        if self._coinglass is not None:
            try:
                rate = self._coinglass.get_funding_rate(asset)
                if rate is not None:
                    abs_rate = abs(rate)
                    if abs_rate >= FUNDING_RATE_EXTREME:
                        funding_info = {"rate": rate, "level": "extreme"}
                        adjustments.append((
                            f"extreme_funding_{rate:+.6f}",
                            OFA_EXTREME_FUNDING_REDUCE,
                        ))
                    elif abs_rate >= FUNDING_RATE_ELEVATED:
                        funding_info = {"rate": rate, "level": "elevated"}
                        adjustments.append((
                            f"elevated_funding_{rate:+.6f}",
                            OFA_ELEVATED_FUNDING_REDUCE,
                        ))
                    else:
                        funding_info = {"rate": rate, "level": "normal"}
                else:
                    funding_info = {"rate": None, "level": "unknown"}
            except Exception:
                logging.debug("CoinGlassFetcher.get_funding_rate failed", exc_info=True)

        # 3. Kalshi orderbook flow
        kalshi_flow = {}
        if self._kalshi_oft is not None:
            try:
                ticker = kwargs.get("ticker")
                if ticker:
                    koft = self._kalshi_oft.get_signals(ticker)
                    if koft is not None:
                        kalshi_flow = koft
                        if not KALSHI_OFT_SHADOW_MODE and koft["prob_adjustment"] != 0:
                            adjustments.append(("kalshi_oft", koft["prob_adjustment"]))
            except Exception:
                logging.debug("KalshiOFT.get_signals failed", exc_info=True)

        # 4. Sum and clamp
        total = sum(v for _, v in adjustments)
        total = max(-OFA_MAX_ADJUSTMENT, min(OFA_MAX_ADJUSTMENT, total))

        # 5. Confidence
        abs_total = abs(total)
        if abs_total >= 0.015:
            confidence = "high"
        elif abs_total >= 0.005:
            confidence = "moderate"
        elif abs_total > 0:
            confidence = "low"
        else:
            confidence = "none"

        return {
            "prob_adjustment": total,
            "confidence": confidence,
            "signals": {
                "cross_exchange": cross_exchange,
                "funding": funding_info,
                "kalshi_orderbook": kalshi_flow,
            },
            "adjustments_applied": [
                f"{name}: {val:+.3f}" for name, val in adjustments
            ],
        }


class KalshiOrderFlowTracker:
    """Tracks Kalshi orderbook snapshots over time for flow signals.

    Records full depth-5 snapshots from the scanner's existing orderbook
    fetches (no additional API calls). Computes:
    - Bid/ask imbalance ratio (YES depth vs total)
    - Depth velocity (total depth change rate)
    - Spread dynamics (bid-ask spread trend)
    - Ask convergence velocity (cents/sec)
    """

    def __init__(self):
        self._snapshots: Dict[str, deque] = {}
        self._last_seen: Dict[str, float] = {}
        self._last_log: Dict[str, float] = {}

    def record_snapshot(self, ticker: str, ob_data: Dict, best_ask: int):
        """Record orderbook snapshot. Called from scanner after each OB fetch.

        ob_data format: {"no": [[price_cents, qty], ...], "yes": [[price_cents, qty], ...]}
        """
        now = time.time()
        if ticker not in self._snapshots:
            self._snapshots[ticker] = deque(maxlen=KALSHI_OFT_BUFFER_SIZE)

        # Sum depth per side
        yes_total_qty = 0
        no_total_qty = 0
        best_yes_bid_price = 0

        for entry in (ob_data.get("yes") or []):
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price, qty = int(entry[0]), int(entry[1])
                yes_total_qty += qty
                if price > best_yes_bid_price:
                    best_yes_bid_price = price

        for entry in (ob_data.get("no") or []):
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                no_total_qty += int(entry[1])

        spread = (best_ask - best_yes_bid_price) if best_yes_bid_price > 0 else 99

        self._snapshots[ticker].append({
            "ts": now,
            "best_ask": best_ask,
            "best_yes_bid": best_yes_bid_price,
            "yes_total_qty": yes_total_qty,
            "no_total_qty": no_total_qty,
            "total_depth": yes_total_qty + no_total_qty,
            "spread": spread,
        })
        self._last_seen[ticker] = now

    def get_signals(self, ticker: str) -> Optional[Dict]:
        """Compute order flow signals from snapshot history. Returns None if insufficient data."""
        snaps = self._snapshots.get(ticker)
        if not snaps or len(snaps) < KALSHI_OFT_MIN_SNAPSHOTS:
            return None

        snap_list = list(snaps)
        latest = snap_list[-1]
        earliest = snap_list[0]
        time_span = latest["ts"] - earliest["ts"]
        if time_span <= 0:
            return None

        # 1. Imbalance: YES bids / total depth
        total_qty = latest["yes_total_qty"] + latest["no_total_qty"]
        imbalance = latest["yes_total_qty"] / total_qty if total_qty > 0 else 0.5

        if imbalance >= KALSHI_OFT_IMBALANCE_STRONG:
            imbalance_level = "strong_buy"
        elif imbalance <= KALSHI_OFT_IMBALANCE_WEAK:
            imbalance_level = "strong_sell"
        else:
            imbalance_level = "neutral"

        # 2. Depth velocity
        depth_velocity = (latest["total_depth"] - earliest["total_depth"]) / time_span
        depth_pct_change = ((latest["total_depth"] - earliest["total_depth"])
                           / earliest["total_depth"]) if earliest["total_depth"] > 0 else 0.0
        depth_drain = depth_pct_change < KALSHI_OFT_DEPTH_DRAIN_PCT

        # 3. Spread trend
        spread_trend = (latest["spread"] - earliest["spread"]) / time_span

        # 4. Ask velocity
        ask_velocity = (latest["best_ask"] - earliest["best_ask"]) / time_span

        # 5. Prob adjustment (shadow or live)
        adjustments = []
        if imbalance_level == "strong_buy":
            adjustments.append(("kalshi_imbalance_buy", OFA_KALSHI_IMBALANCE_BOOST))
        elif imbalance_level == "strong_sell":
            adjustments.append(("kalshi_imbalance_sell", OFA_KALSHI_IMBALANCE_REDUCE))
        if depth_drain and ask_velocity > 0:
            adjustments.append(("kalshi_depth_drain", OFA_KALSHI_DEPTH_DRAIN_BOOST))
        if ask_velocity > 0.5:
            adjustments.append(("kalshi_convergence", OFA_KALSHI_CONVERGENCE_BOOST))

        total_adj = max(-0.02, min(0.02, sum(v for _, v in adjustments)))

        # Confidence
        n_snaps = len(snap_list)
        if n_snaps >= 30 and total_qty >= 20:
            confidence = "high"
        elif n_snaps >= 15 or total_qty >= 10:
            confidence = "moderate"
        else:
            confidence = "low"

        result = {
            "imbalance_ratio": round(imbalance, 4),
            "imbalance_level": imbalance_level,
            "depth_velocity": round(depth_velocity, 2),
            "depth_drain": depth_drain,
            "depth_pct_change": round(depth_pct_change, 4),
            "spread_current": latest["spread"],
            "spread_trend": round(spread_trend, 4),
            "ask_velocity": round(ask_velocity, 4),
            "prob_adjustment": round(total_adj, 6),
            "adjustments_applied": [f"{n}: {v:+.3f}" for n, v in adjustments],
            "n_snapshots": n_snaps,
            "confidence": confidence,
        }

        # Periodic per-ticker diagnostic logging
        now = time.time()
        last_log = self._last_log.get(ticker, 0.0)
        if now - last_log >= KALSHI_OFT_LOG_INTERVAL:
            self._last_log[ticker] = now
            adj_str = ", ".join(f"{n}: {v:+.3f}" for n, v in adjustments) if adjustments else "none"
            logging.info(
                "KalshiOFT %s: imbal=%.3f (%s) depth_vel=%.1f depth_pct=%.1f%% "
                "spread=%d trend=%.3f ask_vel=%.3f adj=%.4f [%s] snaps=%d conf=%s shadow=%s",
                ticker, imbalance, imbalance_level, depth_velocity,
                depth_pct_change * 100, latest["spread"], spread_trend,
                ask_velocity, total_adj, adj_str, n_snaps, confidence,
                KALSHI_OFT_SHADOW_MODE,
            )

        return result

    def cleanup_stale(self, active_tickers: Set[str]):
        """Evict tickers no longer in active windows."""
        now = time.time()
        stale = [t for t, ts in self._last_seen.items()
                 if now - ts > KALSHI_OFT_STALE_SECONDS or t not in active_tickers]
        for t in stale:
            self._snapshots.pop(t, None)
            self._last_seen.pop(t, None)

    def get_tracked_count(self) -> int:
        return len(self._snapshots)


# ═════════════════════════════════════════════════════════════════════════════
#  VolatilityEngine
# ═════════════════════════════════════════════════════════════════════════════

class VolatilityEngine:
    """Realized Kernel + Deribit DVOL volatility engine.

    Uses microstructure-noise-robust Realized Kernel (Barndorff-Nielsen 2008),
    bipower variation for jump separation, and optional Deribit DVOL blending.
    Maintains its own rolling buffer of log returns per asset (up to 15 min).
    """

    def __init__(self, feed: CoinbaseFeed, dvol_fetcher: Optional[DeribitDVOLFetcher] = None,
                 egarch_estimator: Optional['EGARCHEstimator'] = None,
                 mz_tracker: Optional['MincerZarnowitzTracker'] = None):
        self._feed = feed
        self._dvol = dvol_fetcher
        self._egarch = egarch_estimator
        self._mz = mz_tracker
        self._egarch_blend_last_log: Dict[str, float] = {}
        self._returns: Dict[str, deque] = {
            a: deque(maxlen=VOL_WINDOW_15MIN) for a in ASSETS
        }
        self._last_return_time: Dict[str, float] = {}
        self._jump_events: Dict[str, List[float]] = {a: [] for a in ASSETS}
        self._cache: Dict[str, Optional[Dict]] = {}
        # ── Adaptive jump detection state ──
        self._adaptive_tick_counter: Dict[str, int] = {a: 0 for a in ASSETS}
        self._adaptive_returns_15s: Dict[str, deque] = {
            a: deque(maxlen=JUMP_ADAPTIVE_PCTILE_WINDOW) for a in ASSETS
        }
        self._adaptive_ewma_var: Dict[str, Optional[float]] = {a: None for a in ASSETS}
        self._adaptive_abs_returns: Dict[str, deque] = {
            a: deque(maxlen=JUMP_ADAPTIVE_PCTILE_WINDOW) for a in ASSETS
        }
        self._adaptive_jump_events: Dict[str, List] = {a: [] for a in ASSETS}
        self._adaptive_last_save: float = 0.0
        self._adaptive_total_jumps: Dict[str, int] = {a: 0 for a in ASSETS}
        self._load_adaptive_state()
        # Adaptive RK bandwidth diagnostics
        self._rk_noise_history: Dict[str, deque] = {
            a: deque(maxlen=720) for a in ASSETS  # 720 = 1h of 5s ticks
        }
        self._rk_prev_omega_sq: Dict[str, float] = {}
        self._rk_last_summary: Dict[str, float] = {a: 0.0 for a in ASSETS}
        self._rk_adaptive_diff_count: Dict[str, int] = {a: 0 for a in ASSETS}
        self._rk_delta_5_accum: Dict[str, deque] = {a: deque(maxlen=720) for a in ASSETS}
        self._rk_delta_15_accum: Dict[str, deque] = {a: deque(maxlen=720) for a in ASSETS}
        self._rk_last_save: float = 0.0
        self._load_rk_state()

    # ── RK state persistence (prevents cold-start vol underestimation) ──

    RK_STATE_PATH = "rk_state.json"
    RK_SAVE_INTERVAL = 60.0  # seconds between saves

    def _load_rk_state(self):
        """Load RK return buffers from disk. Restores blended vol instantly on restart."""
        if not os.path.exists(self.RK_STATE_PATH):
            logging.info("RK state: no file, starting cold")
            return
        try:
            with open(self.RK_STATE_PATH, "r") as f:
                state = json.load(f)
            loaded = 0
            for asset in ASSETS:
                returns = state.get(asset, {}).get("returns", [])
                if returns:
                    self._returns[asset].clear()
                    for r in returns:
                        self._returns[asset].append(r)
                    loaded += 1
            age = time.time() - state.get("saved_at", 0)
            logging.info("RK state loaded: %d assets restored, age=%.0fs (BTC=%d ETH=%d SOL=%d XRP=%d returns)",
                         loaded, age,
                         len(self._returns["BTC"]), len(self._returns["ETH"]),
                         len(self._returns["SOL"]), len(self._returns["XRP"]))
        except Exception as e:
            logging.warning("RK state load failed: %s (starting cold)", e)

    def save_rk_state(self):
        """Persist RK return buffers to disk (atomic write)."""
        state = {"saved_at": time.time()}
        for asset in ASSETS:
            state[asset] = {"returns": list(self._returns[asset])}
        tmp = self.RK_STATE_PATH + ".tmp"
        try:
            with open(tmp, "w") as f:
                json.dump(state, f)
            os.replace(tmp, self.RK_STATE_PATH)
        except Exception as e:
            logging.warning("RK state save failed: %s", e)

    def _maybe_save_rk_state(self):
        """Throttled periodic save."""
        now = time.time()
        if now - self._rk_last_save >= self.RK_SAVE_INTERVAL:
            self.save_rk_state()
            self._rk_last_save = now

    def update(self, asset: str, seconds_to_close: Optional[float] = None) -> Optional[Dict]:
        """Called every tick. Computes a new log return every 5s, returns vol estimate."""
        buf = self._feed.get_buffer(asset)
        if len(buf) < VOL_RETURN_INTERVAL + 1:
            return None

        now = time.time()
        last_time = self._last_return_time.get(asset, 0)

        # Only compute a new return every VOL_RETURN_INTERVAL seconds
        if now - last_time >= VOL_RETURN_INTERVAL:
            current_ts, current_price = buf[-1]
            target_ts = current_ts - VOL_RETURN_INTERVAL

            # Find the snapshot closest to 5 seconds ago
            past_price = None
            for ts, p in reversed(buf):
                if ts <= target_ts:
                    past_price = p
                    break

            if past_price and past_price > 0 and current_price > 0:
                log_return = math.log(current_price / past_price)
                self._returns[asset].append(log_return)
                self._last_return_time[asset] = now
                self._maybe_save_rk_state()

                # Feed return to EGARCH
                if self._egarch is not None:
                    self._egarch.record_return(asset, log_return)

                # Adaptive jump detection (Tier 1: subsample to 15s)
                adaptive_result = None
                return_15s = self._adaptive_subsample_return(asset, log_return, now)
                if return_15s is not None:
                    adaptive_result = self._adaptive_jump_test(asset, return_15s, now)
                    if adaptive_result["is_jump"]:
                        boost = (JUMP_ADAPTIVE_DECAY_MAX_BOOST
                                 * min(JUMP_ADAPTIVE_MAG_CAP, adaptive_result["magnitude_ratio"])
                                 / JUMP_ADAPTIVE_MAG_SCALE_BASE)
                        self._record_adaptive_jump_event(asset, now, adaptive_result["magnitude_ratio"])
                        if JUMP_ADAPTIVE_SHADOW_MODE:
                            logging.info(
                                "Jump detected [adaptive-shadow]: %s r_15s=%.6f "
                                "ewma_σ=%.6f threshold=%.6f ratio=%.2f n=%d boost=%.3f",
                                asset, adaptive_result["return_15s"],
                                adaptive_result["ewma_sigma"],
                                adaptive_result["effective_threshold"],
                                adaptive_result["magnitude_ratio"],
                                adaptive_result["n_obs_15s"], boost)
                        else:
                            self._record_jump_event(asset, now)
                            logging.info(
                                "Jump detected [adaptive]: %s r_15s=%.6f "
                                "ewma_σ=%.6f threshold=%.6f ratio=%.2f n=%d boost=%.3f",
                                asset, adaptive_result["return_15s"],
                                adaptive_result["ewma_sigma"],
                                adaptive_result["effective_threshold"],
                                adaptive_result["magnitude_ratio"],
                                adaptive_result["n_obs_15s"], boost)
                    elif adaptive_result["n_obs_15s"] % 60 == 0 and adaptive_result["n_obs_15s"] > 0:
                        logging.info(
                            "Adaptive jump health %s: ewma_σ=%.6f pctile=%.6f "
                            "sigma_thresh=%.6f n=%d total_jumps=%d",
                            asset, adaptive_result["ewma_sigma"],
                            adaptive_result["pctile_threshold"]
                            if adaptive_result["pctile_threshold"] != float('inf') else 0.0,
                            adaptive_result["sigma_threshold"]
                            if adaptive_result["sigma_threshold"] != float('inf') else 0.0,
                            adaptive_result["n_obs_15s"],
                            self._adaptive_total_jumps.get(asset, 0))
                    # Periodic save
                    now_save = time.time()
                    if now_save - self._adaptive_last_save >= JUMP_ADAPTIVE_SAVE_INTERVAL:
                        self._save_adaptive_state()
                        self._adaptive_last_save = now_save

                # Check for jump against current estimate (before updating cache)
                estimate = self._compute(asset, now, seconds_to_close)
                if estimate and estimate["blended_rv"] > 0:
                    legacy_jump = abs(log_return) > JUMP_THRESHOLD_MULTIPLIER * estimate["blended_rv"]

                    # Legacy jump detection (3x blended_rv threshold)
                    if JUMP_ADAPTIVE_SHADOW_MODE:
                        # Adaptive in shadow: legacy test drives regime
                        if legacy_jump:
                            self._record_jump_event(asset, now)
                            logging.info(
                                "Jump detected [legacy]: %s return=%.6f rv=%.6f",
                                asset, log_return, estimate["blended_rv"])
                    else:
                        # Adaptive drives regime — legacy logged at DEBUG only
                        logging.debug(
                            "Jump test [legacy-debug]: %s return=%.6f rv=%.6f legacy=%s",
                            asset, log_return, estimate["blended_rv"], legacy_jump)

                # Seed EGARCH variance from RK if needed, then recursive update
                if self._egarch is not None:
                    if self._egarch._log_var.get(asset) is None and estimate and estimate.get("rv_5min", 0) > 0:
                        self._egarch.seed_variance(asset, estimate["rv_5min"] ** 2)
                    egarch_sigma = self._egarch.recursive_update(asset, log_return)
                    # Anomaly: sigma/rv ratio extreme (throttled to 1 per asset per 5 min)
                    if egarch_sigma and estimate and estimate.get("blended_rv", 0) > 0:
                        ratio = egarch_sigma / estimate["blended_rv"]
                        if ratio > 5.0 or ratio < 0.2:
                            throttle_key = f"egarch_ratio_{asset}"
                            if now - self._rk_last_summary.get(throttle_key, 0) >= 300:
                                self._rk_last_summary[throttle_key] = now
                                logging.warning(
                                    "EGARCH %s: sigma/rv ratio extreme (%.4f) — model may be diverging",
                                    asset, ratio)

                self._cache[asset] = self._compute(asset, now, seconds_to_close)
            else:
                self._cache.setdefault(asset, None)
        elif asset not in self._cache:
            self._cache[asset] = self._compute(asset, now, seconds_to_close)

        return self._cache.get(asset)

    def _record_jump_event(self, asset: str, timestamp: float):
        """Append jump timestamp, trim to JUMP_MAX_HISTORY."""
        events = self._jump_events.get(asset)
        if events is None:
            events = []
            self._jump_events[asset] = events
        events.append(timestamp)
        if len(events) > JUMP_MAX_HISTORY:
            del events[:-JUMP_MAX_HISTORY]

    # ── Adaptive jump detection methods ──────────────────────────────────

    def _adaptive_subsample_return(self, asset: str, log_return_5s: float, now: float) -> Optional[float]:
        """Subsample to 15s returns by summing every 3rd group of 5s returns."""
        self._adaptive_tick_counter[asset] = self._adaptive_tick_counter.get(asset, 0) + 1
        if self._adaptive_tick_counter[asset] % JUMP_ADAPTIVE_SUBSAMPLE != 0:
            return None
        # Sum the last SUBSAMPLE entries from the 5s return buffer
        returns = self._returns.get(asset)
        if returns is None or len(returns) < JUMP_ADAPTIVE_SUBSAMPLE:
            return None
        return sum(list(returns)[-JUMP_ADAPTIVE_SUBSAMPLE:])

    def _adaptive_jump_test(self, asset: str, return_15s: float, now: float) -> dict:
        """Core adaptive jump detection: EWMA variance + rolling percentile."""
        abs_r = abs(return_15s)

        # Compute thresholds from HISTORICAL data (before appending current return)
        n_hist = len(self._adaptive_abs_returns[asset])

        # Sigma threshold from pre-update EWMA
        pre_ewma_var = self._adaptive_ewma_var.get(asset)
        if pre_ewma_var is not None and pre_ewma_var > 0:
            ewma_sigma = math.sqrt(pre_ewma_var)
            sigma_threshold = JUMP_ADAPTIVE_SIGMA_MULT * ewma_sigma
        else:
            ewma_sigma = 0.0
            sigma_threshold = float('inf')

        # Rolling percentile from historical |returns| (before appending current)
        if n_hist >= JUMP_ADAPTIVE_PCTILE_MIN_OBS:
            sorted_abs = sorted(self._adaptive_abs_returns[asset])
            idx = min(int(JUMP_ADAPTIVE_PCTILE_LEVEL * len(sorted_abs)), len(sorted_abs) - 1)
            pctile_threshold = sorted_abs[idx]
        else:
            pctile_threshold = float('inf')

        # Now append current return to buffers
        self._adaptive_returns_15s[asset].append(return_15s)
        self._adaptive_abs_returns[asset].append(abs_r)
        n_obs = len(self._adaptive_returns_15s[asset])

        # EWMA variance update (after threshold computation)
        r_sq = return_15s * return_15s
        if pre_ewma_var is None:
            if n_obs >= 2:
                # Initialize from sample variance
                buf = list(self._adaptive_returns_15s[asset])
                mean_r = sum(buf) / len(buf)
                ewma_var = sum((x - mean_r) ** 2 for x in buf) / (len(buf) - 1)
                self._adaptive_ewma_var[asset] = ewma_var
        else:
            ewma_var = JUMP_ADAPTIVE_EWMA_LAMBDA * pre_ewma_var + (1 - JUMP_ADAPTIVE_EWMA_LAMBDA) * r_sq
            self._adaptive_ewma_var[asset] = ewma_var

        effective_threshold = max(sigma_threshold, pctile_threshold)

        # Jump detection (guarded by warmup)
        if n_obs >= JUMP_ADAPTIVE_EWMA_INIT_RETURNS and effective_threshold > 0 and effective_threshold != float('inf'):
            is_jump = abs_r > effective_threshold
        else:
            is_jump = False

        magnitude_ratio = abs_r / effective_threshold if effective_threshold > 0 and effective_threshold != float('inf') else 0.0

        return {
            "is_jump": is_jump,
            "ewma_sigma": ewma_sigma,
            "sigma_threshold": sigma_threshold,
            "pctile_threshold": pctile_threshold,
            "effective_threshold": effective_threshold,
            "magnitude_ratio": magnitude_ratio,
            "n_obs_15s": n_obs,
            "return_15s": return_15s,
        }

    def _record_adaptive_jump_event(self, asset: str, timestamp: float, magnitude_ratio: float):
        """Record an adaptive jump event with magnitude-scaled boost."""
        capped_ratio = min(JUMP_ADAPTIVE_MAG_CAP, magnitude_ratio)
        boost = JUMP_ADAPTIVE_DECAY_MAX_BOOST * capped_ratio / JUMP_ADAPTIVE_MAG_SCALE_BASE
        self._adaptive_jump_events[asset].append((timestamp, boost))
        if len(self._adaptive_jump_events[asset]) > JUMP_ADAPTIVE_MAX_HISTORY:
            del self._adaptive_jump_events[asset][:-JUMP_ADAPTIVE_MAX_HISTORY]
        self._adaptive_total_jumps[asset] = self._adaptive_total_jumps.get(asset, 0) + 1

    def _adaptive_decay_multiplier(self, asset: str, now: float) -> Tuple[float, str]:
        """Compute adaptive jump decay multiplier from event history."""
        events = self._adaptive_jump_events.get(asset, [])
        if not events:
            return (1.0, "normal")
        total_boost = sum(
            boost * math.exp(-(now - ts) / JUMP_ADAPTIVE_DECAY_TAU)
            for ts, boost in events if ts <= now
        )
        if total_boost > JUMP_ADAPTIVE_DECAY_MIN_BOOST:
            return (min(JUMP_ADAPTIVE_DECAY_CAP, 1.0 + total_boost), "elevated")
        return (1.0, "normal")

    def _save_adaptive_state(self):
        """Persist adaptive jump detection state to JSON (atomic write)."""
        state = {}
        for asset in ASSETS:
            state[asset] = {
                "ewma_var": self._adaptive_ewma_var.get(asset),
                "tick_counter": self._adaptive_tick_counter.get(asset, 0),
                "total_jumps": self._adaptive_total_jumps.get(asset, 0),
                "returns_15s": list(self._adaptive_returns_15s.get(asset, [])),
                "abs_returns": list(self._adaptive_abs_returns.get(asset, [])),
                "jump_events": list(self._adaptive_jump_events.get(asset, [])),
            }
        state["saved_at"] = time.time()
        tmp_path = JUMP_ADAPTIVE_STATE_PATH + ".tmp"
        try:
            with open(tmp_path, "w") as f:
                json.dump(state, f)
            os.replace(tmp_path, JUMP_ADAPTIVE_STATE_PATH)
            file_size = os.path.getsize(JUMP_ADAPTIVE_STATE_PATH) / 1024.0
            logging.info(
                "Adaptive jump state saved: BTC=%d ETH=%d SOL=%d XRP=%d obs (file_size=%.1fKB)",
                len(self._adaptive_returns_15s["BTC"]),
                len(self._adaptive_returns_15s["ETH"]),
                len(self._adaptive_returns_15s["SOL"]),
                len(self._adaptive_returns_15s["XRP"]),
                file_size)
        except Exception as e:
            logging.warning("Failed to save adaptive jump state: %s", e)

    def _load_adaptive_state(self):
        """Restore adaptive jump detection state from JSON on startup."""
        if not os.path.exists(JUMP_ADAPTIVE_STATE_PATH):
            logging.info("No adaptive jump state file found, starting fresh")
            return
        try:
            with open(JUMP_ADAPTIVE_STATE_PATH, "r") as f:
                state = json.load(f)
        except Exception as e:
            logging.warning("Failed to load adaptive jump state: %s (starting fresh)", e)
            return
        saved_at = state.get("saved_at", 0)
        for asset in ASSETS:
            try:
                adata = state.get(asset)
                if not isinstance(adata, dict):
                    continue
                ev = adata.get("ewma_var")
                if ev is not None and isinstance(ev, (int, float)):
                    self._adaptive_ewma_var[asset] = float(ev)
                tc = adata.get("tick_counter")
                if isinstance(tc, (int, float)):
                    self._adaptive_tick_counter[asset] = int(tc)
                tj = adata.get("total_jumps")
                if isinstance(tj, (int, float)):
                    self._adaptive_total_jumps[asset] = int(tj)
                r15 = adata.get("returns_15s")
                if isinstance(r15, list):
                    self._adaptive_returns_15s[asset] = deque(
                        [float(x) for x in r15 if isinstance(x, (int, float))],
                        maxlen=JUMP_ADAPTIVE_PCTILE_WINDOW)
                ar = adata.get("abs_returns")
                if isinstance(ar, list):
                    self._adaptive_abs_returns[asset] = deque(
                        [float(x) for x in ar if isinstance(x, (int, float))],
                        maxlen=JUMP_ADAPTIVE_PCTILE_WINDOW)
                je = adata.get("jump_events")
                if isinstance(je, list):
                    events = []
                    for item in je:
                        if isinstance(item, (list, tuple)) and len(item) == 2:
                            events.append((float(item[0]), float(item[1])))
                    self._adaptive_jump_events[asset] = events[-JUMP_ADAPTIVE_MAX_HISTORY:]
            except Exception as e:
                logging.warning("Adaptive jump state load failed for %s: %s (starting fresh)", asset, e)
        logging.info(
            "Adaptive jump state restored: BTC=%d ETH=%d SOL=%d XRP=%d obs, ewma_age=%.0fs",
            len(self._adaptive_returns_15s["BTC"]),
            len(self._adaptive_returns_15s["ETH"]),
            len(self._adaptive_returns_15s["SOL"]),
            len(self._adaptive_returns_15s["XRP"]),
            time.time() - saved_at if saved_at else 0)

    # ── Kernel & statistical methods ─────────────────────────────────────

    @staticmethod
    def _parzen_kernel(x: float) -> float:
        """Flat-top Parzen kernel for Realized Kernel estimator."""
        ax = abs(x)
        if ax <= 0.5:
            return 1.0
        if ax <= 1.0:
            # Smooth cubic taper: Hermite basis h00 maps [0.5, 1] → [1, 0]
            u = 2.0 * (ax - 0.5)  # maps [0.5, 1] → [0, 1]
            return 1.0 - 3.0 * u * u + 2.0 * u * u * u
        return 0.0

    @staticmethod
    def _estimate_noise_variance(returns: List[float]) -> float:
        """Estimate microstructure noise variance ω² from first-order autocovariance.

        ω² = max(FLOOR, -γ̂(1)) where γ̂(1) = (1/(n-1)) × Σ r_i × r_{i+1}
        Non-negative autocovariance (momentum) floors to RK_NOISE_VAR_FLOOR.
        """
        n = len(returns)
        if n < 2:
            return RK_NOISE_VAR_FLOOR
        gamma1 = sum(returns[i] * returns[i + 1] for i in range(n - 1)) / (n - 1)
        return max(RK_NOISE_VAR_FLOOR, -gamma1)

    @staticmethod
    def _realized_quarticity(returns: List[float], window: int) -> float:
        """Realized Quarticity: RQ = (n/3) × Σ r_i⁴ over the window subset."""
        subset = returns[-window:] if len(returns) >= window else returns
        n = len(subset)
        if n < 1:
            return 0.0
        return (n / 3.0) * sum(r ** 4 for r in subset)

    @staticmethod
    def _optimal_rk_bandwidth(returns: List[float], window: int, omega_sq: float) -> int:
        """BN (2008/2009) optimal bandwidth for flat-top Parzen kernel.

        H* = ceil(c* × ξ^(4/5) × n^(3/5)) where ξ² = ω² / √RQ.
        Falls back to ceil(√n) if insufficient data or degenerate inputs.
        """
        subset = returns[-window:] if len(returns) >= window else returns
        n = len(subset)
        if n < 2:
            return 0
        H_floor = math.ceil(math.sqrt(n))
        H_cap = math.floor(n * RK_BANDWIDTH_MAX_FRACTION)
        if n < RK_MIN_RETURNS_FOR_ADAPTIVE or omega_sq <= RK_NOISE_VAR_FLOOR:
            return H_floor
        rq = VolatilityEngine._realized_quarticity(returns, window)
        if rq <= 0.0:
            return H_floor
        sqrt_rq = math.sqrt(rq)
        xi_sq = omega_sq / sqrt_rq
        if xi_sq <= 0.0:
            return H_floor
        H_star = math.ceil(RK_CSTAR_FLAT_TOP_PARZEN * (xi_sq ** 0.8) * (n ** 0.6))
        return max(H_floor, min(H_star, H_cap))

    @staticmethod
    def _realized_kernel(returns: List[float], window: int, bandwidth: Optional[int] = None) -> float:
        """Realized Kernel (Barndorff-Nielsen 2008) — microstructure-noise robust.

        RK = Σ_{h=-H}^{H} k(h/(H+1)) × γ(h)
        where γ(h) is the autocovariance at lag h.
        Returns per-return scale volatility (same unit as old _window_rv).
        """
        subset = returns[-window:] if len(returns) >= window else returns
        n = len(subset)
        if n < 2:
            return 0.0

        H = bandwidth if bandwidth is not None else math.ceil(math.sqrt(n))

        rk = 0.0
        for h in range(-H, H + 1):
            weight = VolatilityEngine._parzen_kernel(h / (H + 1))
            if weight == 0.0:
                continue
            # Compute autocovariance γ(h)
            gamma_h = 0.0
            ah = abs(h)
            count = 0
            for j in range(ah, n):
                gamma_h += subset[j] * subset[j - ah]
                count += 1
            if count > 0:
                gamma_h /= count
            rk += weight * gamma_h

        return math.sqrt(max(0.0, rk))

    @staticmethod
    def _bipower_variation(returns: List[float], window: int) -> float:
        """Bipower variation — robust to jumps, estimates continuous-path vol.

        BV = (π/2) × (1/(n-1)) × Σ |r_j| × |r_{j+1}|
        Returns per-return scale volatility.
        """
        subset = returns[-window:] if len(returns) >= window else returns
        n = len(subset)
        if n < 2:
            return 0.0

        bv_sum = 0.0
        for j in range(n - 1):
            bv_sum += abs(subset[j]) * abs(subset[j + 1])

        bv = (math.pi / 2.0) * bv_sum / (n - 1)
        return math.sqrt(max(0.0, bv))

    def _estimate_beta(self, asset: str, reference: str = "BTC") -> float:
        """Cross-asset beta: cov(r_asset, r_ref) / var(r_ref). Clamped [0.5, 3.0]."""
        if asset == reference:
            return 1.0

        r_asset = list(self._returns.get(asset, []))
        r_ref = list(self._returns.get(reference, []))

        # Use last BETA_LOOKBACK_RETURNS from each
        r_asset = r_asset[-BETA_LOOKBACK_RETURNS:]
        r_ref = r_ref[-BETA_LOOKBACK_RETURNS:]

        n = min(len(r_asset), len(r_ref))
        if n < 10:
            return 1.0

        # Align to same length (most recent)
        r_asset = r_asset[-n:]
        r_ref = r_ref[-n:]

        mean_a = sum(r_asset) / n
        mean_r = sum(r_ref) / n

        cov = sum((r_asset[i] - mean_a) * (r_ref[i] - mean_r) for i in range(n)) / n
        var_r = sum((r_ref[i] - mean_r) ** 2 for i in range(n)) / n

        if var_r <= 0:
            return 1.0

        beta = cov / var_r
        return max(0.5, min(3.0, beta))

    def _get_implied_vol(self, asset: str) -> Optional[float]:
        """Get implied vol in per-5-second scale. BTC/ETH direct, SOL/XRP via beta."""
        if self._dvol is None:
            return None

        if asset in DERIBIT_DVOL_CURRENCIES:
            return self._dvol.get_dvol(asset)

        # SOL/XRP: scale BTC DVOL by cross-asset beta
        btc_dvol = self._dvol.get_dvol("BTC")
        if btc_dvol is None:
            return None
        beta = self._estimate_beta(asset, "BTC")
        return btc_dvol * beta

    def _get_implied_vol_hourly(self, asset: str) -> Optional[float]:
        """Get hourly-averaged implied vol in per-5-second scale. BTC/ETH direct, SOL/XRP via beta."""
        if self._dvol is None:
            return None

        if asset in DERIBIT_DVOL_CURRENCIES:
            return self._dvol.get_dvol_hourly_avg(asset)

        # SOL/XRP: scale BTC hourly avg DVOL by cross-asset beta
        btc_dvol_hourly = self._dvol.get_dvol_hourly_avg("BTC")
        if btc_dvol_hourly is None:
            return None
        beta = self._estimate_beta(asset, "BTC")
        return btc_dvol_hourly * beta

    # ── Core computation ─────────────────────────────────────────────────

    def _compute(self, asset: str, now: float, seconds_to_close: Optional[float] = None) -> Optional[Dict]:
        returns = self._returns[asset]
        if len(returns) < 2:
            return None

        returns_list = list(returns)

        # Noise variance estimation (once for all windows)
        omega_sq = self._estimate_noise_variance(returns_list)

        # Step 1: Fixed-bandwidth RK (always — production path)
        rk_1min = self._realized_kernel(returns_list, VOL_WINDOW_1MIN)
        rk_5min = self._realized_kernel(returns_list, VOL_WINDOW_5MIN)
        rk_15min = self._realized_kernel(returns_list, VOL_WINDOW_15MIN)

        # Adaptive bandwidth computation
        H_fixed_5 = math.ceil(math.sqrt(min(len(returns_list), VOL_WINDOW_5MIN))) if len(returns_list) >= 2 else 0
        H_fixed_15 = math.ceil(math.sqrt(min(len(returns_list), VOL_WINDOW_15MIN))) if len(returns_list) >= 2 else 0
        H_adaptive_5 = self._optimal_rk_bandwidth(returns_list, VOL_WINDOW_5MIN, omega_sq)
        H_adaptive_15 = self._optimal_rk_bandwidth(returns_list, VOL_WINDOW_15MIN, omega_sq)

        # Adaptive RK — compute with optimal bandwidth H*
        rk_fixed_5 = rk_5min   # Save fixed-H values for diagnostics
        rk_fixed_15 = rk_15min
        ark_5min = self._realized_kernel(returns_list, VOL_WINDOW_5MIN, bandwidth=H_adaptive_5) if H_adaptive_5 != H_fixed_5 else rk_5min
        ark_15min = self._realized_kernel(returns_list, VOL_WINDOW_15MIN, bandwidth=H_adaptive_15) if H_adaptive_15 != H_fixed_15 else rk_15min

        # When shadow mode is off, use adaptive values for all downstream
        if not RK_ADAPTIVE_SHADOW_MODE:
            rk_5min = ark_5min
            rk_15min = ark_15min

        # ── Adaptive RK logging ───────────────────────────────────────────
        # Track noise history for diagnostics
        self._rk_noise_history[asset].append(omega_sq)

        # Per-tick DEBUG: when adaptive H differs from fixed
        if H_adaptive_5 != H_fixed_5 or H_adaptive_15 != H_fixed_15:
            delta_5 = round((ark_5min - rk_fixed_5) / rk_fixed_5, 4) if rk_fixed_5 > 0 and H_adaptive_5 != H_fixed_5 else 0.0
            delta_15 = round((ark_15min - rk_fixed_15) / rk_fixed_15, 4) if rk_fixed_15 > 0 and H_adaptive_15 != H_fixed_15 else 0.0
            logging.debug(
                "RK adaptive %s: H_5=%d→%d H_15=%d→%d ω²=%.2e delta_5=%.4f delta_15=%.4f",
                asset, H_fixed_5, H_adaptive_5, H_fixed_15, H_adaptive_15,
                omega_sq, delta_5, delta_15
            )
            self._rk_adaptive_diff_count[asset] = self._rk_adaptive_diff_count.get(asset, 0) + 1
            if H_adaptive_5 != H_fixed_5 and rk_fixed_5 > 0:
                self._rk_delta_5_accum[asset].append(abs((ark_5min - rk_fixed_5) / rk_fixed_5))
            if H_adaptive_15 != H_fixed_15 and rk_fixed_15 > 0:
                self._rk_delta_15_accum[asset].append(abs((ark_15min - rk_fixed_15) / rk_fixed_15))

        # Noise regime change (INFO): ω² changes by >10× from previous tick
        prev_omega = self._rk_prev_omega_sq.get(asset)
        if prev_omega is not None and prev_omega > 0 and omega_sq > 0:
            omega_ratio = omega_sq / prev_omega
            if omega_ratio > 10.0 or omega_ratio < 0.1:
                logging.info(
                    "RK noise shift %s: ω²=%.2e (prev=%.2e, ratio=%.1f×)",
                    asset, omega_sq, prev_omega, omega_ratio
                )
        self._rk_prev_omega_sq[asset] = omega_sq

        # Bandwidth divergence alert (WARNING): adaptive > 2× fixed
        if H_adaptive_5 > 2 * H_fixed_5 and H_fixed_5 > 0:
            logging.warning(
                "RK bandwidth divergence %s: H_adaptive=%d vs H_fixed=%d (%.1f×) ω²=%.2e — high noise session",
                asset, H_adaptive_5, H_fixed_5, H_adaptive_5 / H_fixed_5, omega_sq
            )
        if H_adaptive_15 > 2 * H_fixed_15 and H_fixed_15 > 0:
            logging.warning(
                "RK bandwidth divergence %s: H_adaptive=%d vs H_fixed=%d (%.1f×) ω²=%.2e — high noise session",
                asset, H_adaptive_15, H_fixed_15, H_adaptive_15 / H_fixed_15, omega_sq
            )

        # Periodic summary (INFO, every 5 min)
        if now - self._rk_last_summary.get(asset, 0) >= 300:
            H_fixed_1 = math.ceil(math.sqrt(min(len(returns_list), VOL_WINDOW_1MIN))) if len(returns_list) >= 2 else 0
            H_adaptive_1 = H_fixed_1  # 1min always same (n < RK_MIN_RETURNS_FOR_ADAPTIVE)
            logging.info(
                "RK bandwidth %s: H_fixed=[%d,%d,%d] H_adaptive=[%d,%d,%d] ω²=%.2e ark_5=%.8f rk_5=%.8f ratio=%.4f",
                asset, H_fixed_1, H_fixed_5, H_fixed_15,
                H_adaptive_1, H_adaptive_5, H_adaptive_15,
                omega_sq, ark_5min, rk_5min,
                ark_5min / rk_5min if rk_5min > 0 else 0.0
            )
            self._rk_last_summary[asset] = now

        # Step 2: Bipower variation for jump separation
        bv_1min = self._bipower_variation(returns_list, VOL_WINDOW_1MIN)
        bv_5min = self._bipower_variation(returns_list, VOL_WINDOW_5MIN)
        bv_15min = self._bipower_variation(returns_list, VOL_WINDOW_15MIN)

        # DVOL squared for VRP diagnostic
        dvol_hourly = self._get_implied_vol_hourly(asset)
        dvol_sq = (dvol_hourly ** 2) if dvol_hourly is not None else None

        # Step 3: RK blend (TV weights when promoted, fixed weights when shadow)
        if not RK_TV_SHADOW_MODE and seconds_to_close is not None:
            w1, w5, w15 = compute_tv_rk_weights(seconds_to_close)
        else:
            w1, w5, w15 = VOL_BLEND_WEIGHTS
        continuous_rv = w1 * rk_1min + w5 * rk_5min + w15 * rk_15min
        bv_blended = w1 * bv_1min + w5 * bv_5min + w15 * bv_15min
        jump_var = max(0.0, continuous_rv ** 2 - bv_blended ** 2)
        fixed_blend_rv = math.sqrt(bv_blended ** 2 + jump_var)
        rv_blended = fixed_blend_rv

        # Step 3a: Counterfactual RK weights (opposite of live path)
        shadow_tv_blend_rv = None
        shadow_tv_weights = None
        if RK_TV_SHADOW_MODE and seconds_to_close is not None:
            # Shadow: TV weights not live, show what they would do
            tw1, tw5, tw15 = compute_tv_rk_weights(seconds_to_close)
            shadow_tv_weights = (round(tw1, 3), round(tw5, 3), round(tw15, 3))
            tv_continuous = tw1 * rk_1min + tw5 * rk_5min + tw15 * rk_15min
            tv_bv = tw1 * bv_1min + tw5 * bv_5min + tw15 * bv_15min
            tv_jump_var = max(0.0, tv_continuous ** 2 - tv_bv ** 2)
            shadow_tv_blend_rv = math.sqrt(tv_bv ** 2 + tv_jump_var)
        elif not RK_TV_SHADOW_MODE:
            # Promoted: TV weights ARE live, compute what fixed weights would do
            fw1, fw5, fw15 = VOL_BLEND_WEIGHTS
            shadow_tv_weights = (round(fw1, 3), round(fw5, 3), round(fw15, 3))
            fc = fw1 * rk_1min + fw5 * rk_5min + fw15 * rk_15min
            fb = fw1 * bv_1min + fw5 * bv_5min + fw15 * bv_15min
            fj = max(0.0, fc ** 2 - fb ** 2)
            shadow_tv_blend_rv = math.sqrt(fb ** 2 + fj)

        # Step 3b: EGARCH conditional volatility
        egarch_sigma = None
        if self._egarch is not None:
            egarch_sigma = self._egarch.get_sigma(asset)

        # Track RV-only blended for diagnostics
        rv_only_blended = rv_blended
        blended = rv_blended

        # Step 3c: EGARCH-RV variance-space blend
        egarch_blend_weight = 0.0
        egarch_blend_var = None
        egarch_blend_sigma = rv_blended  # safe default if blend not computed
        try:
            if (egarch_sigma is not None and egarch_sigma > 0
                    and rv_blended > 0 and self._mz is not None):
                ratio = egarch_sigma / rv_blended
                # Safety clamp: reject extreme divergence
                if 1.0 / EGARCH_RV_RATIO_CLAMP <= ratio <= EGARCH_RV_RATIO_CLAMP:
                    # Record MZ pair: EGARCH forecast var vs RV realized var
                    egarch_var = egarch_sigma ** 2
                    rv_var = rv_blended ** 2
                    self._mz.record(asset, egarch_var, rv_var)

                    # Get adaptive weight from MZ R²
                    w_eg = self._mz.maybe_recompute(asset, now)
                    egarch_blend_weight = w_eg

                    if w_eg > 0:
                        # Variance-space blend: avoids Jensen's inequality bias
                        egarch_blend_var = w_eg * egarch_var + (1.0 - w_eg) * rv_var
                        egarch_blend_sigma = math.sqrt(egarch_blend_var)

                        if not math.isfinite(egarch_blend_sigma) or egarch_blend_sigma <= 0:
                            egarch_blend_var = None
                            egarch_blend_sigma = rv_blended
                        elif not EGARCH_BLEND_SHADOW_MODE:
                            blended = egarch_blend_sigma

                    # Periodic logging + state save
                    if now - self._egarch_blend_last_log.get(asset, 0) >= EGARCH_BLEND_LOG_INTERVAL:
                        mz_r2 = self._mz._r_squared.get(asset)
                        mz_qlike = self._mz._qlike.get(asset)
                        logging.info(
                            "EGARCH blend %s: w_eg=%.3f ratio=%.3f R²=%s QLIKE=%s "
                            "rv=%.8f eg=%.8f blended=%.8f shadow=%s",
                            asset, w_eg, ratio,
                            f"{mz_r2:.4f}" if mz_r2 is not None else "warmup",
                            f"{mz_qlike:.6f}" if mz_qlike is not None else "n/a",
                            rv_blended, egarch_sigma,
                            egarch_blend_sigma if egarch_blend_var else rv_blended,
                            EGARCH_BLEND_SHADOW_MODE,
                        )
                        self._egarch_blend_last_log[asset] = now
                        self._mz.save_state()
                else:
                    if now - self._egarch_blend_last_log.get(asset, 0) >= EGARCH_BLEND_LOG_INTERVAL:
                        logging.warning(
                            "EGARCH blend %s: CLAMPED ratio=%.3f (limit=%.1f) — skipping blend",
                            asset, ratio, EGARCH_RV_RATIO_CLAMP,
                        )
                        self._egarch_blend_last_log[asset] = now
        except Exception:
            logging.warning("EGARCH blend %s failed, using rv_blended", asset, exc_info=True)

        # Sigmoid QLIKE counterfactual: what blended_rv would be using sigmoid weight
        mz_sigmoid_improvement = None
        mz_sigmoid_blend_rv = None
        egarch_ratio_clamped = False
        if egarch_sigma is not None and egarch_sigma > 0 and rv_blended > 0:
            ratio_check = egarch_sigma / rv_blended
            egarch_ratio_clamped = not (1.0 / EGARCH_RV_RATIO_CLAMP <= ratio_check <= EGARCH_RV_RATIO_CLAMP)
        if self._mz is not None and egarch_sigma is not None and egarch_sigma > 0 and rv_blended > 0:
            sig_w = self._mz._shadow_sigmoid_w.get(asset)
            if sig_w is not None and sig_w > 0:
                sig_blend_var = sig_w * (egarch_sigma ** 2) + (1.0 - sig_w) * (rv_blended ** 2)
                mz_sigmoid_blend_rv = math.sqrt(sig_blend_var)
            bl_q = self._mz._baseline_qlike.get(asset)
            eg_q = self._mz._qlike.get(asset)
            if bl_q is not None and eg_q is not None and bl_q > 1e-10:
                mz_sigmoid_improvement = round(max(0.0, (bl_q - eg_q) / bl_q), 6)

        # VRP diagnostic (variance risk premium)
        vrp = None
        if dvol_sq is not None and rk_5min > 0:
            vrp = dvol_sq - rk_5min ** 2

        # VRP regime logging (every 5 min)
        if vrp is not None and now - self._rk_last_summary.get(f"vrp_{asset}", 0) >= 300:
            premium = "positive" if vrp > 0 else "negative"
            rv5_sq = rk_5min ** 2
            ratio = dvol_sq / rv5_sq if rv5_sq > 0 else 0.0
            logging.info(
                "VRP %s: vrp=%.2e dvol_sq=%.2e rv5_sq=%.2e ratio=%.2f (premium=%s)",
                asset, vrp, dvol_sq, rv5_sq, ratio, premium,
            )
            self._rk_last_summary[f"vrp_{asset}"] = now

        # DVOL hourly average health logging (every 5 min)
        if self._dvol is not None and now - self._rk_last_summary.get(f"dvol_h_{asset}", 0) >= 300:
            dvol_hourly = self._get_implied_vol_hourly(asset)
            dvol_raw = self._get_implied_vol(asset)
            if dvol_hourly is not None and asset in DERIBIT_DVOL_CURRENCIES:
                buf = self._dvol._hourly_dvol.get(asset)
                n_samples = len(buf) if buf else 0
                if n_samples > 0 and dvol_hourly > 0:
                    spread = (max(buf) - min(buf)) / dvol_hourly
                    logging.info(
                        "DVOL hourly %s: avg=%.8f raw=%.8f samples=%d spread=%.4f",
                        asset, dvol_hourly, dvol_raw if dvol_raw else 0.0, n_samples, spread,
                    )
            self._rk_last_summary[f"dvol_h_{asset}"] = now

        # Step 4: DVOL blending (if available)
        iv = self._get_implied_vol(asset)
        dvol_5s = iv  # for diagnostics
        iv_rv_spread = None
        iv_rv_blend_method = "rv_only"

        if iv is not None and iv > 0 and rv_blended > 0:
            # Inverse-variance weighting
            var_rv = (rk_1min - rk_15min) ** 2   # spread as proxy for RV uncertainty
            var_iv = (iv * 0.10) ** 2             # 10% uncertainty on IV
            # Avoid division by zero
            if var_rv + var_iv > 0:
                w_rv = var_iv / (var_rv + var_iv)
                w_iv = var_rv / (var_rv + var_iv)
                blended = w_rv * rv_blended + w_iv * iv
                iv_rv_blend_method = "inverse_variance"

            # Step 5: IV-RV regime detection
            iv_rv_spread = (iv - rv_blended) / rv_blended
            if iv_rv_spread > IV_RV_SPREAD_THRESHOLD:
                blended = 0.3 * rv_blended + 0.7 * iv
                iv_rv_blend_method = "stress_override"

        # Step 6: Jump regime — exponential decay (legacy)
        regime = "normal"
        jump_multiplier = 1.0
        jump_events = self._jump_events.get(asset, [])
        if jump_events:
            total_boost = sum(
                JUMP_DECAY_MAX_BOOST * math.exp(-(now - ts) / JUMP_DECAY_TAU)
                for ts in jump_events if ts <= now
            )
            if total_boost > JUMP_DECAY_MIN_BOOST:
                regime = "elevated"
                jump_multiplier = min(4.0, 1.0 + total_boost)
                blended *= jump_multiplier

        # Step 6b: Adaptive jump decay
        adaptive_multiplier, adaptive_regime = self._adaptive_decay_multiplier(asset, now)
        if not JUMP_ADAPTIVE_SHADOW_MODE:
            # Adaptive drives regime — undo legacy and apply adaptive
            if jump_multiplier > 1.0:
                blended /= jump_multiplier
            regime = adaptive_regime
            jump_multiplier = adaptive_multiplier
            if adaptive_multiplier > 1.0:
                blended *= adaptive_multiplier

        # Backward-compat: compute approximate seconds remaining
        jump_seconds_remaining = 0.0
        if jump_events:
            age = now - max(jump_events)
            full_decay = -JUMP_DECAY_TAU * math.log(JUMP_DECAY_MIN_BOOST / JUMP_DECAY_MAX_BOOST)
            jump_seconds_remaining = max(0.0, full_decay - age)

        # Adaptive seconds remaining
        adaptive_seconds_remaining = 0.0
        adaptive_events = self._adaptive_jump_events.get(asset, [])
        if adaptive_events:
            newest_ts = max(ts for ts, _ in adaptive_events)
            # Time until the largest single boost decays below threshold
            max_boost = max(b for _, b in adaptive_events)
            if max_boost > JUMP_ADAPTIVE_DECAY_MIN_BOOST:
                full_decay_adaptive = -JUMP_ADAPTIVE_DECAY_TAU * math.log(
                    JUMP_ADAPTIVE_DECAY_MIN_BOOST / max_boost)
                adaptive_seconds_remaining = max(0.0, full_decay_adaptive - (now - newest_ts))

        return {
            # Original 7 fields (backward-compatible)
            "rv_1min": rk_1min,
            "rv_5min": rk_5min,
            "rv_15min": rk_15min,
            "blended_rv": blended,
            "regime": regime,
            "num_returns": len(returns),
            "jump_seconds_remaining": round(jump_seconds_remaining, 1),
            # New diagnostic fields
            "bv_1min": bv_1min,
            "bv_5min": bv_5min,
            "bv_15min": bv_15min,
            "jump_component": math.sqrt(jump_var) if jump_var > 0 else 0.0,
            "dvol_5s": dvol_5s,
            "iv_rv_spread": iv_rv_spread,
            "iv_rv_blend_method": iv_rv_blend_method,
            "rv_only_blended": rv_only_blended,
            "fixed_blend_rv": fixed_blend_rv,
            "jump_multiplier": round(jump_multiplier, 4),
            "jump_event_count": len(jump_events),
            # Adaptive jump diagnostics
            "adaptive_jump_multiplier": round(adaptive_multiplier, 4),
            "adaptive_jump_regime": adaptive_regime,
            "adaptive_jump_event_count": len(self._adaptive_jump_events.get(asset, [])),
            "adaptive_seconds_remaining": round(adaptive_seconds_remaining, 1),
            "adaptive_ewma_sigma": math.sqrt(self._adaptive_ewma_var[asset]) if self._adaptive_ewma_var.get(asset) else None,
            "adaptive_n_obs_15s": len(self._adaptive_returns_15s.get(asset, [])),
            # EGARCH diagnostics
            "egarch_sigma": egarch_sigma,
            "egarch_constrained_sigma": self._egarch.get_constrained_sigma(asset) if self._egarch else None,
            "egarch_n_updates": self._egarch._n_updates.get(asset, 0) if self._egarch else 0,
            "egarch_log_var": self._egarch._log_var.get(asset) if self._egarch else None,
            # EGARCH blend diagnostics
            "egarch_blend_weight": egarch_blend_weight,
            "egarch_blend_var": egarch_blend_var,
            "egarch_blend_shadow": EGARCH_BLEND_SHADOW_MODE,
            "mz_r_squared": self._mz._r_squared.get(asset) if self._mz else None,
            "mz_qlike": self._mz._qlike.get(asset) if self._mz else None,
            "mz_baseline_qlike": self._mz._baseline_qlike.get(asset) if self._mz else None,
            "mz_shadow_sigmoid_w": self._mz._shadow_sigmoid_w.get(asset) if self._mz else None,
            # Adaptive RK bandwidth diagnostics
            "omega_sq": omega_sq,
            "rk_H_fixed_5": H_fixed_5,
            "rk_H_fixed_15": H_fixed_15,
            "rk_H_adaptive_5": H_adaptive_5,
            "rk_H_adaptive_15": H_adaptive_15,
            "ark_5min": ark_5min,
            "ark_15min": ark_15min,
            "rk_adaptive_delta_5": round((ark_5min - rk_fixed_5) / rk_fixed_5, 6) if rk_fixed_5 > 0 and H_adaptive_5 != H_fixed_5 else 0.0,
            "rk_adaptive_delta_15": round((ark_15min - rk_fixed_15) / rk_fixed_15, 6) if rk_fixed_15 > 0 and H_adaptive_15 != H_fixed_15 else 0.0,
            # DVOL diagnostics
            "dvol_sq_hourly": dvol_sq,
            "vrp": vrp,
            # Shadow time-varying RK weights
            "shadow_tv_blend_rv": shadow_tv_blend_rv,
            "shadow_tv_weights": shadow_tv_weights,
            # Sigmoid QLIKE counterfactual
            "mz_sigmoid_improvement": mz_sigmoid_improvement,
            "mz_sigmoid_blend_rv": mz_sigmoid_blend_rv,
            "egarch_ratio_clamped": egarch_ratio_clamped,
        }


# EGARCHEstimator, MincerZarnowitzTracker, PositionSizer, _student_t_e_abs_z,
# _compute_qlike, fee helpers, compute_tv_rk_weights → imported from models.py
# ═════════════════════════════════════════════════════════════════════════════
#  ProbabilityEngine
# ═════════════════════════════════════════════════════════════════════════════

class ProbabilityEngine:
    """Compute win probability from spot price, strike, time, and volatility.

    Supports per-asset distribution selection via dist_config.json:
    - Student-t CDF with configurable df per asset (default df=4)
    - NIG (Normal Inverse Gaussian) CDF with fitted parameters
    Falls back to Student-t(df=4) if no config file is present.
    """

    @staticmethod
    def _cdf_complement(z_score: float, asset: Optional[str] = None) -> float:
        """Compute 1 - CDF(z_score) using per-asset distribution config."""
        cfg = DIST_CONFIG.get(asset) if asset else None
        if cfg is None:
            return 1.0 - student_t.cdf(z_score, df=STUDENT_T_DF)

        if cfg.get("distribution") == "nig" and "nig_a" in cfg:
            val = 1.0 - norminvgauss.cdf(
                z_score, cfg["nig_a"], cfg["nig_b"],
                loc=cfg.get("nig_loc", 0.0),
                scale=cfg.get("nig_scale", 1.0),
            )
            return max(0.0, min(1.0, val))  # clamp float rounding
        return 1.0 - student_t.cdf(z_score, df=cfg.get("student_t_df", STUDENT_T_DF))

    @staticmethod
    def compute(spot: float, threshold: float, seconds_remaining: float,
                blended_rv: float,
                market_price_cents: Optional[int] = None,
                asset: Optional[str] = None,
                product_type: Optional[str] = None) -> Dict:
        """
        Compute calibrated win probability for a "price stays above threshold" bet.

        Args:
            spot: current price (e.g. 68500.0 for BTC)
            threshold: strike/threshold price the market resolves against
            seconds_remaining: seconds until market close
            blended_rv: blended realized vol (per-5-second log return scale)
            market_price_cents: current Kalshi YES price in cents (for sanity check)

        Returns dict with: z_score, raw_prob, calibrated_prob, tradeable, reason
        """
        result: Dict = {
            "z_score": None,
            "raw_prob": None,
            "calibrated_prob": None,
            "calibration_method": None,
            "tradeable": False,
            "reason": "",
        }

        # ── Guard: need valid inputs ─────────────────────────────────────
        if spot <= 0 or seconds_remaining <= 0 or blended_rv <= 0:
            result["reason"] = "invalid inputs (spot/time/vol <= 0)"
            return result

        # ── Annualize vol and compute z-score ────────────────────────────
        # blended_rv is std dev of 5-second log returns.
        # σ_annual = blended_rv × sqrt(seconds_per_year / 5)
        # σ_annual × sqrt(t_years) = blended_rv × sqrt(t_seconds / 5)
        # Denominator for z: spot × blended_rv × sqrt(t_seconds / 5)
        sigma_move = spot * blended_rv * math.sqrt(seconds_remaining / 5.0)

        if sigma_move <= 0:
            result["reason"] = "sigma_move is zero"
            return result

        z_score = (threshold - spot) / sigma_move
        result["z_score"] = round(z_score, 4)

        # ── Raw probability via configurable distribution CDF ────────────
        # P(price stays above threshold) = P(move > threshold - spot)
        # = P(Z > z_score) = 1 - CDF(z_score)
        raw_prob = ProbabilityEngine._cdf_complement(z_score, asset)
        result["raw_prob"] = round(raw_prob, 6)

        # ── Calibration: adaptive (if trained) or fixed β=0.85 ──────────
        dynamic_cap = ProbabilityEngine._dynamic_cap(seconds_remaining, product_type=product_type)
        _cal_cfg2 = get_market_config(product_type)
        _reg_engine = _resolve_cal_engine(product_type, asset, require_enabled=True)
        if _reg_engine is not None and _reg_engine.is_learned_method_active():
            calibrated_prob = _reg_engine.calibrate(raw_prob, cap=dynamic_cap,
                                                     seconds_to_close=seconds_remaining)
            result["calibration_method"] = f"{product_type}_{_reg_engine.active_method}"
            # Shadow: what passthrough + temperature would have produced
            _pt_shadow = min(raw_prob, dynamic_cap)
            _temp_cfg = _cal_cfg2.temperature_t if _cal_cfg2.temperature_enabled else None
            if _temp_cfg and _temp_cfg != 1.0:
                _sp = max(0.001, min(0.999, _pt_shadow))
                _sz = math.log(_sp / (1.0 - _sp))
                _pt_shadow = 1.0 / (1.0 + math.exp(-_sz / _temp_cfg))
            result["shadow_cal_prob"] = round(_pt_shadow, 6)
            result["shadow_cal_temperature"] = _temp_cfg
        elif _cal_cfg2.cal_eligible and _CALIBRATION_ENGINE is not None:
            if FIFTEEN_M_CALIBRATION_ENABLED and _CALIBRATION_ENGINE.is_learned_method_active():
                calibrated_prob = _CALIBRATION_ENGINE.calibrate(raw_prob, cap=dynamic_cap,
                                                               seconds_to_close=seconds_remaining)
                result["calibration_method"] = _CALIBRATION_ENGINE.active_method
            else:
                calibrated_prob = min(raw_prob, dynamic_cap)
                result["calibration_method"] = "passthrough"
                # Diagnostic: log what BLR would have produced (remove after validation)
                _blr_would = _CALIBRATION_ENGINE.calibrate(raw_prob, cap=dynamic_cap,
                                                           seconds_to_close=seconds_remaining)
                if abs(_blr_would - calibrated_prob) > 0.02:
                    logging.info(
                        "BLR_BYPASS: raw=%.4f passthrough=%.4f blr_would=%.4f delta=%.3f",
                        raw_prob, calibrated_prob, _blr_would, _blr_would - calibrated_prob)
        elif not _cal_cfg2.cal_eligible:
            calibrated_prob = min(raw_prob, dynamic_cap)
            result["calibration_method"] = "passthrough"
        else:
            calibrated_prob = ProbabilityEngine._calibrate(raw_prob, cap=dynamic_cap)
            result["calibration_method"] = "fixed_beta"
        # ── Clamped BLR: prevent extreme inflation in low raw_prob zone ──
        # BLR extrapolates badly when raw_prob < 0.70 (training data is 85c+).
        # Clamp cal_prob to max raw_prob + 5pp, with linear transition 70-85%.
        # Does NOT affect shadow CalEngine, CalEngine retraining, or high-raw signals.
        _cal_clamp_delta = calibrated_prob - raw_prob
        if raw_prob < 0.70 and _cal_clamp_delta > 0.05:
            _original_cal = calibrated_prob
            calibrated_prob = min(calibrated_prob, raw_prob + 0.05)
            logging.info(
                "CAL_CLAMP: raw=%.3f blr=%.3f clamped=%.3f delta=%.3f",
                raw_prob, _original_cal, calibrated_prob,
                _original_cal - calibrated_prob)
        elif raw_prob < 0.85 and _cal_clamp_delta > 0.05:
            _alpha = (raw_prob - 0.70) / 0.15
            _clamped = min(calibrated_prob, raw_prob + 0.05)
            _original_cal = calibrated_prob
            calibrated_prob = _alpha * calibrated_prob + (1.0 - _alpha) * _clamped
            if abs(calibrated_prob - _original_cal) > 0.005:
                logging.info(
                    "CAL_CLAMP_BLEND: raw=%.3f blr=%.3f clamped=%.3f alpha=%.2f delta=%.3f",
                    raw_prob, _original_cal, calibrated_prob, _alpha,
                    _original_cal - calibrated_prob)

        result["calibrated_prob"] = round(calibrated_prob, 6)

        # ── Sanity: model vs market discrepancy ──────────────────────────
        if market_price_cents is not None:
            if calibrated_prob > DISCREPANCY_PROB and market_price_cents < DISCREPANCY_PRICE:
                result["reason"] = (
                    f"model says {calibrated_prob:.1%} but market is "
                    f"{market_price_cents}¢ (< {DISCREPANCY_PRICE}¢) — refusing"
                )
                logging.warning(f"ProbabilityEngine: {result['reason']}")
                return result

        # ── All checks passed ────────────────────────────────────────────
        result["tradeable"] = True
        result["reason"] = "ok"
        return result

    @staticmethod
    def counterfactual_prob(spot: float, threshold: float, seconds_remaining: float,
                            alt_blended_rv: float, asset: Optional[str] = None,
                            product_type: Optional[str] = None) -> Optional[float]:
        """Compute calibrated_prob for a counterfactual blended_rv. Lightweight — no logging."""
        if spot <= 0 or seconds_remaining <= 0 or alt_blended_rv <= 0:
            return None
        sigma_move = spot * alt_blended_rv * math.sqrt(seconds_remaining / 5.0)
        if sigma_move <= 0:
            return None
        z = (threshold - spot) / sigma_move
        raw = ProbabilityEngine._cdf_complement(z, asset)
        cap = ProbabilityEngine._dynamic_cap(seconds_remaining, product_type=product_type)
        if _CALIBRATION_ENGINE is not None:
            return round(_CALIBRATION_ENGINE.calibrate(raw, cap=cap,
                                                       seconds_to_close=seconds_remaining), 6)
        return round(ProbabilityEngine._calibrate(raw, cap=cap), 6)

    @staticmethod
    def _dynamic_cap(seconds_remaining: float, product_type: str = None) -> float:
        """Return probability cap based on time to close."""
        schedule = (HOURLY_DYNAMIC_CAP_SCHEDULE
                    if product_type in ("hourly", "spx_hourly", "weather")
                    else DYNAMIC_CAP_SCHEDULE)
        for threshold_secs, cap in schedule:
            if seconds_remaining > threshold_secs:
                return cap
        return schedule[-1][1]  # smallest TTC bracket

    @staticmethod
    def _calibrate(raw_prob: float, cap: float = MAX_EFFECTIVE_PROB) -> float:
        """Apply logistic compression then hard cap.

        Maps raw_prob through: logit → scale by BETA_SLOPE → inverse logit → cap.
        This pulls extreme probabilities toward 0.5 and caps at 93%.
        """
        # Clamp to avoid log(0) in logit
        p = max(0.001, min(0.999, raw_prob))
        logit = math.log(p / (1.0 - p))
        scaled_logit = BETA_SLOPE * logit
        compressed = 1.0 / (1.0 + math.exp(-scaled_logit))
        return min(compressed, cap)


# ═════════════════════════════════════════════════════════════════════════════
#  CalibrationEngine
# ═════════════════════════════════════════════════════════════════════════════

class CalibrationEngine:
    """Data-driven calibration replacing fixed β=0.85 Platt scaling.

    Implements three calibration methods:
    - Platt Scaling: 2-parameter logistic (A, B) — default, needs 200+ samples
    - Beta Calibration: 3-parameter (a, b, c) — needs 500+ samples
    - Online BLR: Bayesian linear regression with Laplace approx — needs 50+ samples

    Until enough data is collected, falls back to the existing fixed β=0.85.
    """

    def __init__(self, state_path: str = CALIBRATION_STATE_PATH,
                 label: str = "CalibrationEngine",
                 accepted_stages: Optional[tuple] = None):
        self.state_path = state_path
        self._label = label
        self._accepted_stages = accepted_stages  # None = accept all stages
        self.active_method: str = "fixed_beta"  # current method in use
        self._observations: deque = deque(maxlen=500)  # (raw_prob, binary_outcome)
        self._brier_scores: deque = deque(maxlen=CALIBRATION_BRIER_WINDOW)
        self._last_retrain: float = 0.0

        # Platt parameters: P_cal = 1 / (1 + exp(A * logit(p) + B))
        self._platt_A: float = BETA_SLOPE  # default = current fixed β
        self._platt_B: float = 0.0
        self._platt_trained: bool = False

        # Beta Cal parameters: logit(P_cal) = c + a * log(p) + b * log(1-p)
        self._beta_a: float = 1.0
        self._beta_b: float = -1.0
        self._beta_c: float = 0.0
        self._beta_trained: bool = False

        # Online BLR parameters: sigmoid(w * logit(p) + b)
        # Prior centered on identity: w=1, b=0
        self._blr_mu = [1.0, 0.0]  # [w, b] posterior mean
        self._blr_precision = [[1.0, 0.0], [0.0, 1.0]]  # 2x2 precision matrix (prior)
        self._blr_trained: bool = False

        # STC-aware Platt: sigmoid(A * logit(p) + B + C * log(STC/300))
        self._stc_platt_A: float = BETA_SLOPE
        self._stc_platt_B: float = 0.0
        self._stc_platt_C: float = 0.0  # STC coefficient (negative = reduce prob at high STC)
        self._stc_platt_trained: bool = False

        # Previous Brier score for regression check
        self._prev_brier: Optional[float] = None

        # Temperature scaling (shadow pipeline)
        self._temperature: Optional[float] = None
        self._temperature_brier: Optional[float] = None

        # Empirical bucket tracking: keyed by prob range string
        self._empirical_buckets: Dict[str, deque] = {
            "0.80-0.85": deque(maxlen=200),
            "0.85-0.90": deque(maxlen=200),
            "0.90-0.93": deque(maxlen=200),
            "0.93-0.95": deque(maxlen=200),
            "0.95-0.97": deque(maxlen=200),
            "0.97-1.00": deque(maxlen=200),
        }

        self._load_state()

    # ── Persistence ────────────────────────────────────────────────────────

    def _load_state(self):
        """Load learned parameters from calibration_state.json."""
        try:
            with open(self.state_path, "r") as f:
                state = json.load(f)

            self.active_method = state.get("active_method", "fixed_beta")

            if "platt" in state:
                self._platt_A = state["platt"]["A"]
                self._platt_B = state["platt"]["B"]
                self._platt_trained = state["platt"].get("trained", False)

            if "beta_cal" in state:
                self._beta_a = state["beta_cal"]["a"]
                self._beta_b = state["beta_cal"]["b"]
                self._beta_c = state["beta_cal"]["c"]
                self._beta_trained = state["beta_cal"].get("trained", False)

            if "blr" in state:
                self._blr_mu = state["blr"]["mu"]
                self._blr_precision = state["blr"]["precision"]
                self._blr_trained = state["blr"].get("trained", False)

            if "temperature" in state:
                self._temperature = state["temperature"].get("value")
                self._temperature_brier = state["temperature"].get("brier")

            if "stc_platt" in state:
                self._stc_platt_A = state["stc_platt"].get("A", BETA_SLOPE)
                self._stc_platt_B = state["stc_platt"].get("B", 0.0)
                self._stc_platt_C = state["stc_platt"].get("C", 0.0)
                self._stc_platt_trained = state["stc_platt"].get("trained", False)

            # observations are loaded from DB in load_training_data_from_db()

            if "prev_brier" in state:
                self._prev_brier = state["prev_brier"]

            logging.info(
                "%s loaded: method=%s, observations=%d, "
                "platt_trained=%s, beta_trained=%s, blr_trained=%s",
                self._label, self.active_method, len(self._observations),
                self._platt_trained, self._beta_trained, self._blr_trained,
            )
        except FileNotFoundError:
            logging.info("%s: No state found, starting fresh (fixed_beta fallback)", self._label)
        except Exception as e:
            logging.warning("%s: Error loading state: %s", self._label, e)

    def _save_state(self):
        """Atomically persist learned parameters."""
        state = {
            "active_method": self.active_method,
            "platt": {
                "A": self._platt_A,
                "B": self._platt_B,
                "trained": self._platt_trained,
            },
            "beta_cal": {
                "a": self._beta_a,
                "b": self._beta_b,
                "c": self._beta_c,
                "trained": self._beta_trained,
            },
            "blr": {
                "mu": self._blr_mu,
                "precision": self._blr_precision,
                "trained": self._blr_trained,
            },
            "temperature": {
                "value": self._temperature,
                "brier": self._temperature_brier,
            },
            "stc_platt": {
                "A": self._stc_platt_A,
                "B": self._stc_platt_B,
                "C": self._stc_platt_C,
                "trained": self._stc_platt_trained,
            },
            "prev_brier": self._prev_brier,
            "saved_at": datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
            "n_observations": len(self._observations),
        }
        tmp_path = self.state_path + ".tmp"
        try:
            with open(tmp_path, "w") as f:
                json.dump(state, f, indent=2)
            os.replace(tmp_path, self.state_path)
        except Exception as e:
            logging.warning("%s: failed to save state: %s", self._label, e)

    # ── Inference ──────────────────────────────────────────────────────────

    def calibrate(self, raw_prob: float, cap: float,
                  seconds_to_close: Optional[float] = None) -> float:
        """Calibrate raw_prob using the active method. Sub-ms, called per evaluation."""
        if self.active_method == "stc_platt" and self._stc_platt_trained:
            result = self._stc_platt_predict(raw_prob, seconds_to_close)
        elif self.active_method == "platt" and self._platt_trained:
            result = self._platt_predict(raw_prob)
        elif self.active_method == "beta_cal" and self._beta_trained:
            result = self._beta_cal_predict(raw_prob)
        elif self.active_method == "temperature" and self._temperature is not None:
            result = self._temperature_predict(raw_prob, self._temperature)
        elif self.active_method == "blr" and self._blr_trained:
            result = self._blr_predict(raw_prob)
        else:
            return CalibrationEngine._fallback_calibrate(raw_prob, cap)
        # Learned method active: apply cap, uncertainty shrinkage, safety ceiling
        result = min(result, cap)
        result = self._apply_uncertainty_shrinkage(result)
        return max(0.001, min(NUMERICAL_SAFETY_CEILING, result))

    @staticmethod
    def _fallback_calibrate(raw_prob: float, cap: float) -> float:
        """Identical to ProbabilityEngine._calibrate — fixed β=0.85."""
        p = max(0.001, min(0.999, raw_prob))
        logit_p = math.log(p / (1.0 - p))
        scaled = BETA_SLOPE * logit_p
        compressed = 1.0 / (1.0 + math.exp(-scaled))
        return min(compressed, cap)

    # ── Temperature Scaling (Shadow Pipeline) ─────────────────────────────

    def _fit_temperature(self) -> Optional[float]:
        """Fit temperature parameter T minimizing Brier score. T>0, monotonic."""
        if len(self._observations) < CALIBRATION_MIN_SAMPLES_BLR:
            return None
        obs = list(self._observations)
        best_t, best_brier = 1.0, float('inf')
        # Grid search + refinement (fast, <100 evaluations)
        for t_candidate in [x / 100.0 for x in range(50, 200, 5)]:  # 0.50 to 1.95
            brier_sum = 0.0
            for _obs_item in obs:
                raw_p, outcome = _obs_item[0], _obs_item[1]

                p = max(0.001, min(0.999, raw_p))
                logit_p = math.log(p / (1.0 - p))
                pred = 1.0 / (1.0 + math.exp(-logit_p / t_candidate))
                brier_sum += (pred - outcome) ** 2
            avg_brier = brier_sum / len(obs)
            if avg_brier < best_brier:
                best_brier = avg_brier
                best_t = t_candidate
        # Refine around best
        for t_candidate in [best_t + d / 1000.0 for d in range(-50, 51, 5)]:
            if t_candidate <= 0.01:
                continue
            brier_sum = 0.0
            for _obs_item in obs:
                raw_p, outcome = _obs_item[0], _obs_item[1]

                p = max(0.001, min(0.999, raw_p))
                logit_p = math.log(p / (1.0 - p))
                pred = 1.0 / (1.0 + math.exp(-logit_p / t_candidate))
                brier_sum += (pred - outcome) ** 2
            avg_brier = brier_sum / len(obs)
            if avg_brier < best_brier:
                best_brier = avg_brier
                best_t = t_candidate
        return best_t

    def _temperature_predict(self, raw_prob: float, temperature: float) -> float:
        """Apply temperature scaling: sigmoid(logit(p) / T)."""
        p = max(0.001, min(0.999, raw_prob))
        logit_p = math.log(p / (1.0 - p))
        return 1.0 / (1.0 + math.exp(-logit_p / temperature))

    def shadow_calibration_pipeline(self, raw_prob: float, best_ask: int,
                                     seconds_remaining: float,
                                     ofa_adjustment: float = 0.0) -> Optional[Dict]:
        """Compute alternative calibration pipeline in shadow mode.

        Changes vs production:
        1. Temperature scaling instead of Beta Cal
        2. No market-price blending (SHADOW_BLEND_W=0.0)
        3. Excludes cap-era data (handled by _fit_temperature using filtered obs)
        """
        if not SHADOW_CAL_PIPELINE or raw_prob is None:
            return None
        try:
            # Step 1: Temperature scaling (or raw if not fitted)
            if self._temperature is not None:
                cal_prob = self._temperature_predict(raw_prob, self._temperature)
            else:
                cal_prob = raw_prob

            # Apply uncertainty shrinkage (same as production)
            cal_prob = self._apply_uncertainty_shrinkage(cal_prob)
            cal_prob = max(0.001, min(NUMERICAL_SAFETY_CEILING, cal_prob))

            # Step 2: OFA adjustment
            cal_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, cal_prob + ofa_adjustment))

            # Step 3: No market blend (or reduced blend)
            shadow_final = cal_prob  # SHADOW_BLEND_W = 0.0, no blend

            # Compute edge
            edge = shadow_final - best_ask / 100.0
            est_fee_1c = calculate_taker_fee(1, best_ask)
            fee_edge = edge - est_fee_1c / 100.0

            return {
                "prob": round(shadow_final, 6),
                "cal_prob_pre_blend": round(cal_prob, 6),
                "temperature": self._temperature,
                "temperature_brier": self._temperature_brier,
                "edge": round(edge, 6),
                "fee_edge": round(fee_edge, 6),
                "would_trade": fee_edge >= MIN_EDGE_PCT / 100.0,
                "blend_w": SHADOW_BLEND_W,
                "prod_blend_w": MARKET_BLEND_W,
            }
        except Exception:
            logging.warning("shadow_calibration_pipeline failed", exc_info=True)
            return None

    # ── Training Data Management ───────────────────────────────────────────

    def add_observation(self, raw_prob: float, outcome: int,
                        filter_stage: Optional[str] = None,
                        seconds_to_close: Optional[float] = None):
        """Append a (raw_prob, outcome, stc) triple and update rolling Brier.
        If accepted_stages is configured, silently skip non-accepted stages."""
        if self._accepted_stages and filter_stage and filter_stage not in self._accepted_stages:
            return
        self._observations.append((raw_prob, outcome, seconds_to_close))
        # Update rolling Brier with the *current* calibration prediction
        pred = self.calibrate(raw_prob, cap=1.0, seconds_to_close=seconds_to_close)
        brier = (pred - outcome) ** 2
        self._brier_scores.append(brier)
        # Bucket the calibrated prediction for empirical tracking
        self._bucket_observation(pred, outcome)

    def maybe_retrain(self) -> bool:
        """Hourly retrain check. Trains all eligible methods, promotes best Brier."""
        now = time.time()
        if now - self._last_retrain < CALIBRATION_RETRAIN_INTERVAL:
            return False
        self._last_retrain = now

        n = len(self._observations)
        if n < CALIBRATION_MIN_SAMPLES_BLR:
            return False

        # ── Train all eligible methods ────────────────────────────────────
        trained_methods: Dict[str, float] = {}  # method -> Brier

        if n >= CALIBRATION_MIN_SAMPLES_PLATT:
            try:
                self._train_platt()
                self._platt_trained = True
                trained_methods["platt"] = self._compute_brier_for_method("platt")
                logging.info(
                    "%s: Platt trained — A=%.4f, B=%.4f, Brier=%.4f, n=%d",
                    self._label, self._platt_A, self._platt_B, trained_methods["platt"], n,
                )
            except Exception as e:
                logging.warning("%s: Platt training failed: %s", self._label, e)

        if n >= CALIBRATION_MIN_SAMPLES_BETA:
            try:
                self._train_beta_cal()
                self._beta_trained = True
                trained_methods["beta_cal"] = self._compute_brier_for_method("beta_cal")
                logging.info(
                    "%s: Beta Cal trained — a=%.4f, b=%.4f, c=%.4f, "
                    "Brier=%.4f, n=%d",
                    self._label, self._beta_a, self._beta_b, self._beta_c,
                    trained_methods["beta_cal"], n,
                )
            except Exception as e:
                logging.warning("%s: Beta Cal training failed: %s", self._label, e)

        if n >= CALIBRATION_MIN_SAMPLES_BLR:
            try:
                self._train_blr()
                self._blr_trained = True
                trained_methods["blr"] = self._compute_brier_for_method("blr")
                logging.info(
                    "%s: BLR trained — mu=[%.4f, %.4f], Brier=%.4f, n=%d",
                    self._label, self._blr_mu[0], self._blr_mu[1], trained_methods["blr"], n,
                )
            except Exception as e:
                logging.warning("%s: BLR training failed: %s", self._label, e)

        # ── Fit temperature scaling and include in competition ────────────
        try:
            temp = self._fit_temperature()
            if temp is not None:
                self._temperature = temp
                brier_sum = sum((self._temperature_predict(item[0], temp) - item[1]) ** 2
                                for item in self._observations)
                self._temperature_brier = brier_sum / len(self._observations)
                trained_methods["temperature"] = self._temperature_brier
                logging.info(
                    "%s: Temperature scaling fitted — T=%.4f, Brier=%.4f, n=%d",
                    self._label, temp, self._temperature_brier, n,
                )
        except Exception as e:
            logging.warning("%s: Temperature scaling failed: %s", self._label, e)

        # STC-aware Platt (needs observations with valid seconds_to_close)
        if n >= CALIBRATION_MIN_SAMPLES_PLATT:
            try:
                self._train_stc_platt()
                if self._stc_platt_C != 0.0:  # Only count if C was learned (not stuck at 0)
                    self._stc_platt_trained = True
                    trained_methods["stc_platt"] = self._compute_brier_for_method("stc_platt")
                    logging.info(
                        "%s: STC-Platt trained — A=%.4f, B=%.4f, C=%.4f, Brier=%.4f, n=%d",
                        self._label, self._stc_platt_A, self._stc_platt_B,
                        self._stc_platt_C, trained_methods["stc_platt"], n,
                    )
            except Exception as e:
                logging.warning("%s: STC-Platt training failed: %s", self._label, e)

        if not trained_methods:
            return False

        # ── Promote best Brier method ─────────────────────────────────────
        best_method = min(trained_methods, key=trained_methods.get)
        best_brier = trained_methods[best_method]

        # Regression guard: reject if best is worse than previous + margin
        if self._prev_brier is not None and best_brier > self._prev_brier + 0.01:
            logging.warning(
                "%s: promotion REJECTED — best Brier %.4f > prev %.4f + 0.01 "
                "(methods: %s)",
                self._label, best_brier, self._prev_brier, trained_methods,
            )
            return False

        old_method = self.active_method
        self.active_method = best_method
        self._prev_brier = best_brier

        logging.info(
            "%s: PROMOTED %s -> %s (Brier=%.4f, alternatives=%s)",
            self._label, old_method, best_method, best_brier,
            {k: round(v, 4) for k, v in trained_methods.items()},
        )

        self._save_state()
        return True

    def load_training_data_from_db(self, state: "StateManager",
                                   product_type_include: Optional[str] = None,
                                   asset_filter=None):
        """Rebuild training data from evaluated opportunities on startup.

        Args:
            product_type_include: If set, load ONLY this product type (for
                dedicated hourly/spx engines). Default None = existing behavior
                (exclude non-15M types).
            asset_filter: If set, additionally filter by asset column.
                str → single asset, list → IN clause. Default None = no asset filter.

        Note: rejected_opportunities (z-score rejections) are excluded because
        their bimodal raw_prob distribution (clustered at 0 and 1) contaminates
        Platt training — 2 NO outcomes at raw_prob≈1.0 create extreme log-loss
        pressure that drives Platt A well below 1.0, compressing all high-end
        calibrated probabilities (e.g. raw 0.95 → cal 0.89 instead of ~0.96).
        """
        try:
            self._observations.clear()

            cutoff = (datetime.datetime.now(timezone.utc)
                      - datetime.timedelta(days=14)).strftime("%Y-%m-%dT%H:%M:%S")
            if product_type_include:
                if asset_filter is not None:
                    if isinstance(asset_filter, list):
                        _placeholders = ",".join("?" for _ in asset_filter)
                        _cal_filter = f"AND product_type = ? AND asset IN ({_placeholders}) "
                        _cal_query_params = (product_type_include, *asset_filter, cutoff)
                    else:
                        _cal_filter = "AND product_type = ? AND asset = ? "
                        _cal_query_params = (product_type_include, asset_filter, cutoff)
                else:
                    # Existing behavior: filter by product_type only
                    _cal_filter = "AND product_type = ? "
                    _cal_query_params = (product_type_include, cutoff)
            else:
                # Existing behavior: exclude non-15M types
                _cal_excluded = get_cal_excluded_types()
                if _cal_excluded:
                    _excl_sorted = sorted(_cal_excluded)
                    _placeholders = ",".join("?" for _ in _excl_sorted)
                    _cal_filter = f"AND (product_type IS NULL OR product_type NOT IN ({_placeholders})) "
                    _cal_query_params = (*_excl_sorted, cutoff)
                else:
                    _cal_filter = ""
                    _cal_query_params = (cutoff,)
            # Stage filter: only accept specified stages (e.g., candidates for 15M)
            _stage_filter = ""
            _stage_params = ()
            if self._accepted_stages:
                _stage_placeholders = ",".join("?" for _ in self._accepted_stages)
                _stage_filter = f"AND filter_stage IN ({_stage_placeholders}) "
                _stage_params = tuple(self._accepted_stages)

            rows = state.conn.execute(
                "SELECT raw_prob, market_result, seconds_to_close "
                "FROM evaluated_opportunities "
                "WHERE status='settled' AND raw_prob IS NOT NULL "
                "AND market_result IS NOT NULL "
                + _cal_filter + _stage_filter +
                "AND evaluation_time > ? "
                "ORDER BY evaluation_time DESC LIMIT 500",
                (*_cal_query_params[:-1], *_stage_params, _cal_query_params[-1])
            ).fetchall()

            loaded = 0
            for row in rows:
                raw_p = row["raw_prob"]
                result = row["market_result"]
                stc = row["seconds_to_close"]
                if result in ("yes", "all_yes"):
                    binary = 1
                elif result in ("no", "all_no"):
                    binary = 0
                else:
                    continue
                self._observations.append((raw_p, binary, stc))
                loaded += 1

            logging.info(
                "%s: loaded %d observations from DB (total: %d)",
                self._label, loaded, len(self._observations),
            )

            # Attempt initial training if enough data
            if loaded > 0:
                self._last_retrain = 0.0  # force retrain check
                self.maybe_retrain()

        except Exception as e:
            logging.warning("%s: failed to load from DB: %s", self._label, e)

    # ── Platt Scaling ──────────────────────────────────────────────────────

    def _platt_predict(self, raw_prob: float) -> float:
        """P_cal = 1 / (1 + exp(A * logit(p) + B))"""
        p = max(0.001, min(0.999, raw_prob))
        logit_p = math.log(p / (1.0 - p))
        return 1.0 / (1.0 + math.exp(-(self._platt_A * logit_p + self._platt_B)))

    def _train_platt(self):
        """Newton-Raphson optimization of (A, B) minimizing log-loss.

        Objective: minimize -sum[ y*log(q) + (1-y)*log(1-q) ]
        where q = sigmoid(A * logit(p) + B)
        """
        if not self._observations:
            return

        A, B = self._platt_A, self._platt_B

        # Precompute logits
        logits = []
        targets = []
        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            p = max(0.001, min(0.999, raw_p))
            logits.append(math.log(p / (1.0 - p)))
            targets.append(float(outcome))

        n = len(logits)

        for iteration in range(50):
            # Compute gradient and Hessian
            g_A = 0.0
            g_B = 0.0
            h_AA = 0.0
            h_AB = 0.0
            h_BB = 0.0

            for i in range(n):
                z = A * logits[i] + B
                # Numerically stable sigmoid
                if z >= 0:
                    q = 1.0 / (1.0 + math.exp(-z))
                else:
                    ez = math.exp(z)
                    q = ez / (1.0 + ez)
                q = max(1e-10, min(1 - 1e-10, q))

                err = q - targets[i]
                g_A += err * logits[i]
                g_B += err
                w = q * (1.0 - q)
                h_AA += w * logits[i] * logits[i]
                h_AB += w * logits[i]
                h_BB += w

            # Solve 2x2 system: H @ delta = -g
            det = h_AA * h_BB - h_AB * h_AB
            if abs(det) < 1e-12:
                break

            dA = -(h_BB * g_A - h_AB * g_B) / det
            dB = -(h_AA * g_B - h_AB * g_A) / det

            A += dA
            B += dB

            if abs(dA) < 1e-8 and abs(dB) < 1e-8:
                break

        # Guardrail: reject if parameters are extreme
        if abs(A) > 5.0 or abs(B) > 5.0:
            logging.warning(
                "%s: Platt params extreme (A=%.4f, B=%.4f), rejecting",
                self._label,
                A, B,
            )
            return

        self._platt_A = A
        self._platt_B = B

    # ── STC-Aware Platt ───────────────────────────────────────────────────

    def _stc_platt_predict(self, raw_prob: float,
                           seconds_to_close: Optional[float] = None) -> float:
        """P_cal = sigmoid(A * logit(p) + B + C * log(STC/300))."""
        p = max(0.001, min(0.999, raw_prob))
        logit_p = math.log(p / (1.0 - p))
        z = self._stc_platt_A * logit_p + self._stc_platt_B
        if seconds_to_close is not None and seconds_to_close > 0:
            z += self._stc_platt_C * math.log(seconds_to_close / 300.0)
        z = max(-20.0, min(20.0, z))
        return 1.0 / (1.0 + math.exp(-z))

    def _train_stc_platt(self):
        """Newton-Raphson for sigmoid(A * logit(p) + B + C * log(STC/300))."""
        valid = [(item[0], item[1], item[2]) for item in self._observations
                 if len(item) > 2 and item[2] is not None and item[2] > 0]
        if len(valid) < CALIBRATION_MIN_SAMPLES_PLATT:
            return
        A = self._stc_platt_A
        B = self._stc_platt_B
        C = self._stc_platt_C
        # Precompute features
        logits = []
        log_stcs = []
        targets = []
        for raw_p, outcome, stc in valid:
            p = max(0.001, min(0.999, raw_p))
            logits.append(math.log(p / (1.0 - p)))
            log_stcs.append(math.log(stc / 300.0))
            targets.append(float(outcome))
        n = len(logits)
        for _ in range(50):
            g = [0.0, 0.0, 0.0]
            H = [[0.0] * 3 for _ in range(3)]
            for i in range(n):
                z = A * logits[i] + B + C * log_stcs[i]
                z = max(-20.0, min(20.0, z))
                q = 1.0 / (1.0 + math.exp(-z))
                q = max(1e-10, min(1.0 - 1e-10, q))
                err = q - targets[i]
                w = q * (1.0 - q)
                phi = [logits[i], 1.0, log_stcs[i]]
                for j in range(3):
                    g[j] += err * phi[j]
                    for k in range(3):
                        H[j][k] += w * phi[j] * phi[k]
            # Solve 3x3 via Cramer's rule
            det = (H[0][0] * (H[1][1] * H[2][2] - H[1][2] * H[2][1])
                   - H[0][1] * (H[1][0] * H[2][2] - H[1][2] * H[2][0])
                   + H[0][2] * (H[1][0] * H[2][1] - H[1][1] * H[2][0]))
            if abs(det) < 1e-12:
                break
            rhs = [-g[0], -g[1], -g[2]]
            d0 = (rhs[0] * (H[1][1] * H[2][2] - H[1][2] * H[2][1])
                  - H[0][1] * (rhs[1] * H[2][2] - H[1][2] * rhs[2])
                  + H[0][2] * (rhs[1] * H[2][1] - H[1][1] * rhs[2])) / det
            d1 = (H[0][0] * (rhs[1] * H[2][2] - H[1][2] * rhs[2])
                  - rhs[0] * (H[1][0] * H[2][2] - H[1][2] * H[2][0])
                  + H[0][2] * (H[1][0] * rhs[2] - rhs[1] * H[2][0])) / det
            d2 = (H[0][0] * (H[1][1] * rhs[2] - rhs[1] * H[2][1])
                  - H[0][1] * (H[1][0] * rhs[2] - rhs[1] * H[2][0])
                  + rhs[0] * (H[1][0] * H[2][1] - H[1][1] * H[2][0])) / det
            A += d0
            B += d1
            C += d2
            if max(abs(d0), abs(d1), abs(d2)) < 1e-8:
                break
        if abs(A) > 5.0 or abs(B) > 5.0 or abs(C) > 5.0:
            logging.warning(
                "%s: STC-Platt params extreme (A=%.4f B=%.4f C=%.4f), rejecting",
                self._label, A, B, C)
            return
        self._stc_platt_A = A
        self._stc_platt_B = B
        self._stc_platt_C = C

    # ── Beta Calibration ───────────────────────────────────────────────────

    def _beta_cal_predict(self, raw_prob: float) -> float:
        """logit(P_cal) = c + a * log(p) + b * log(1-p)"""
        p = max(0.001, min(0.999, raw_prob))
        logit_out = self._beta_c + self._beta_a * math.log(p) + self._beta_b * math.log(1.0 - p)
        # Clamp to avoid overflow
        logit_out = max(-20.0, min(20.0, logit_out))
        return 1.0 / (1.0 + math.exp(-logit_out))

    def _train_beta_cal(self):
        """Newton-Raphson optimization of (a, b, c) minimizing log-loss.

        Model: q = sigmoid(a * log(p) + b * log(1-p) + c)
        """
        if not self._observations:
            return

        a, b, c = self._beta_a, self._beta_b, self._beta_c

        # Precompute features
        log_p = []
        log_1mp = []
        targets = []
        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            p = max(0.001, min(0.999, raw_p))
            log_p.append(math.log(p))
            log_1mp.append(math.log(1.0 - p))
            targets.append(float(outcome))

        n = len(log_p)

        for iteration in range(100):
            # Gradient and 3x3 Hessian
            g = [0.0, 0.0, 0.0]  # d/d(a, b, c)
            H = [[0.0]*3 for _ in range(3)]

            for i in range(n):
                z = a * log_p[i] + b * log_1mp[i] + c
                if z >= 0:
                    q = 1.0 / (1.0 + math.exp(-z))
                else:
                    ez = math.exp(z)
                    q = ez / (1.0 + ez)
                q = max(1e-10, min(1 - 1e-10, q))

                err = q - targets[i]
                feats = [log_p[i], log_1mp[i], 1.0]

                for j in range(3):
                    g[j] += err * feats[j]
                    for k in range(3):
                        H[j][k] += q * (1.0 - q) * feats[j] * feats[k]

            # Solve 3x3 via Cramer's rule
            delta = CalibrationEngine._solve_3x3(H, [-g[0], -g[1], -g[2]])
            if delta is None:
                break

            a += delta[0]
            b += delta[1]
            c += delta[2]

            if all(abs(d) < 1e-8 for d in delta):
                break

        self._beta_a = a
        self._beta_b = b
        self._beta_c = c

    @staticmethod
    def _solve_3x3(A_mat, b_vec):
        """Solve 3x3 linear system using Cramer's rule. Returns None if singular."""
        def det3(m):
            return (m[0][0] * (m[1][1]*m[2][2] - m[1][2]*m[2][1])
                    - m[0][1] * (m[1][0]*m[2][2] - m[1][2]*m[2][0])
                    + m[0][2] * (m[1][0]*m[2][1] - m[1][1]*m[2][0]))

        d = det3(A_mat)
        if abs(d) < 1e-15:
            return None

        result = []
        for col in range(3):
            mod = [list(row) for row in A_mat]
            for row in range(3):
                mod[row][col] = b_vec[row]
            result.append(det3(mod) / d)
        return result

    # ── Online BLR ─────────────────────────────────────────────────────────

    def _blr_predict(self, raw_prob: float) -> float:
        """Posterior mean prediction: sigmoid(w * logit(p) + b)"""
        p = max(0.001, min(0.999, raw_prob))
        logit_p = math.log(p / (1.0 - p))
        z = self._blr_mu[0] * logit_p + self._blr_mu[1]
        z = max(-20.0, min(20.0, z))
        return 1.0 / (1.0 + math.exp(-z))

    def _train_blr(self):
        """Laplace approximation for Bayesian logistic regression.

        Prior: N([1, 0], I) — centered on identity calibration.
        Posterior: Laplace approximation at MAP estimate.
        """
        if not self._observations:
            return

        mu = list(self._blr_mu)

        # Precompute logits
        logits = []
        targets = []
        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            p = max(0.001, min(0.999, raw_p))
            logits.append(math.log(p / (1.0 - p)))
            targets.append(float(outcome))

        n = len(logits)
        # Prior precision (identity)
        prior_mu = [1.0, 0.0]
        lam = 1.0  # prior precision scalar

        for iteration in range(50):
            g = [lam * (mu[0] - prior_mu[0]), lam * (mu[1] - prior_mu[1])]
            H = [[lam, 0.0], [0.0, lam]]

            for i in range(n):
                z = mu[0] * logits[i] + mu[1]
                if z >= 0:
                    q = 1.0 / (1.0 + math.exp(-z))
                else:
                    ez = math.exp(z)
                    q = ez / (1.0 + ez)
                q = max(1e-10, min(1 - 1e-10, q))

                err = q - targets[i]
                feats = [logits[i], 1.0]

                for j in range(2):
                    g[j] += err * feats[j]
                    for k in range(2):
                        H[j][k] += q * (1.0 - q) * feats[j] * feats[k]

            # Solve 2x2
            det = H[0][0] * H[1][1] - H[0][1] * H[1][0]
            if abs(det) < 1e-12:
                break

            d0 = -(H[1][1] * g[0] - H[0][1] * g[1]) / det
            d1 = -(H[0][0] * g[1] - H[1][0] * g[0]) / det

            mu[0] += d0
            mu[1] += d1

            if abs(d0) < 1e-8 and abs(d1) < 1e-8:
                break

        self._blr_mu = mu
        # Store posterior precision (Hessian at MAP)
        self._blr_precision = H

    # ── Metrics ────────────────────────────────────────────────────────────

    def rolling_brier_score(self) -> float:
        """Rolling Brier score over the last N outcomes."""
        if not self._brier_scores:
            return 1.0
        return sum(self._brier_scores) / len(self._brier_scores)

    def _compute_brier_on_observations(self) -> float:
        """Compute Brier score over all observations using current model."""
        if not self._observations:
            return 1.0
        total = 0.0
        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            pred = self.calibrate(raw_p, cap=1.0)
            total += (pred - outcome) ** 2
        return total / len(self._observations)

    def is_learned_method_active(self) -> bool:
        """Return True if a data-driven calibration method is active (not fixed_beta fallback)."""
        if self.active_method == "stc_platt" and self._stc_platt_trained:
            return True
        if self.active_method == "platt" and self._platt_trained:
            return True
        if self.active_method == "beta_cal" and self._beta_trained:
            return True
        if self.active_method == "temperature" and self._temperature is not None:
            return True
        if self.active_method == "blr" and self._blr_trained:
            return True
        return False

    def _apply_uncertainty_shrinkage(self, cal_prob: float) -> float:
        """Shrink calibrated probability toward 0.5 based on model uncertainty.

        p_adj = 0.5 + (p_cal - 0.5) * (1 - u)
        where u = brier / sqrt(n). Well-calibrated model with plenty of data
        → nearly no shrinkage. High Brier or scarce data → conservative.
        """
        n = len(self._observations)
        if n < 50:
            u = 0.05  # conservative default when data is scarce
        else:
            u = self.rolling_brier_score() / math.sqrt(n)
        u = max(0.0, min(0.5, u))
        return 0.5 + (cal_prob - 0.5) * (1.0 - u)

    def _compute_brier_for_method(self, method: str) -> float:
        """Compute Brier score over all observations for a specific method."""
        if not self._observations:
            return 1.0
        total = 0.0
        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            stc = _obs_item[2] if len(_obs_item) > 2 else None
            if method == "stc_platt":
                pred = self._stc_platt_predict(raw_p, stc)
            elif method == "platt":
                pred = self._platt_predict(raw_p)
            elif method == "beta_cal":
                pred = self._beta_cal_predict(raw_p)
            elif method == "temperature" and self._temperature is not None:
                pred = self._temperature_predict(raw_p, self._temperature)
            elif method == "blr":
                pred = self._blr_predict(raw_p)
            else:
                pred = CalibrationEngine._fallback_calibrate(raw_p, cap=1.0)
            total += (max(0.001, min(0.999, pred)) - outcome) ** 2
        return total / len(self._observations)

    def _bucket_observation(self, pred: float, outcome: int):
        """Place a (pred, outcome) pair into the appropriate empirical bucket."""
        bucket_edges = [
            (0.80, 0.85, "0.80-0.85"),
            (0.85, 0.90, "0.85-0.90"),
            (0.90, 0.93, "0.90-0.93"),
            (0.93, 0.95, "0.93-0.95"),
            (0.95, 0.97, "0.95-0.97"),
            (0.97, 1.00, "0.97-1.00"),
        ]
        for lo, hi, key in bucket_edges:
            if lo <= pred < hi or (key == "0.97-1.00" and pred >= 0.97):
                self._empirical_buckets[key].append((pred, outcome))
                break

    def get_empirical_bucket_stats(self) -> Dict[str, dict]:
        """Return per-bucket stats: count, win_rate, avg_pred, calibration_gap."""
        stats = {}
        for key, bucket in self._empirical_buckets.items():
            if not bucket:
                stats[key] = {"count": 0, "win_rate": None, "avg_pred": None, "calibration_gap": None}
                continue
            preds = [p for p, _ in bucket]
            outcomes = [o for _, o in bucket]
            win_rate = sum(outcomes) / len(outcomes)
            avg_pred = sum(preds) / len(preds)
            stats[key] = {
                "count": len(bucket),
                "win_rate": round(win_rate, 4),
                "avg_pred": round(avg_pred, 4),
                "calibration_gap": round(win_rate - avg_pred, 4),
            }
        return stats

    def get_diagnostics(self) -> dict:
        """Return diagnostic info for logging."""
        diag = {
            "active_method": self.active_method,
            "n_observations": len(self._observations),
            "rolling_brier": round(self.rolling_brier_score(), 6),
            "platt_A": round(self._platt_A, 6),
            "platt_B": round(self._platt_B, 6),
            "platt_trained": self._platt_trained,
            "beta_a": round(self._beta_a, 6),
            "beta_b": round(self._beta_b, 6),
            "beta_c": round(self._beta_c, 6),
            "beta_trained": self._beta_trained,
            "blr_mu": [round(m, 6) for m in self._blr_mu],
            "blr_trained": self._blr_trained,
            "learned_method_active": self.is_learned_method_active(),
        }
        diag["empirical_buckets"] = self.get_empirical_bucket_stats()
        return diag

    def backtest_adaptive_vs_fixed(self) -> dict:
        """Replay all observations through old (fixed cap) vs new (learned + shrinkage) system.

        Called once on startup for diagnostics. Returns comparison dict.
        """
        if not self._observations or not self.is_learned_method_active():
            return {}

        old_brier_sum = 0.0
        new_brier_sum = 0.0
        cap_truncated = 0
        high_prob_markets = 0  # predictions > 0.93 under new system

        for _obs_item in self._observations:
            raw_p, outcome = _obs_item[0], _obs_item[1]
            # Old system: fixed beta fallback with 0.93 cap
            old_pred = CalibrationEngine._fallback_calibrate(raw_p, cap=MAX_EFFECTIVE_PROB)
            old_brier_sum += (old_pred - outcome) ** 2

            # New system: learned method + uncertainty shrinkage
            new_pred = self.calibrate(raw_p, cap=NUMERICAL_SAFETY_CEILING)
            new_brier_sum += (new_pred - outcome) ** 2

            # How many predictions were truncated by old cap?
            uncapped = CalibrationEngine._fallback_calibrate(raw_p, cap=1.0)
            if uncapped > MAX_EFFECTIVE_PROB:
                cap_truncated += 1

            if new_pred > MAX_EFFECTIVE_PROB:
                high_prob_markets += 1

        n = len(self._observations)
        result = {
            "n_observations": n,
            "old_brier": round(old_brier_sum / n, 6),
            "new_brier": round(new_brier_sum / n, 6),
            "brier_improvement": round((old_brier_sum - new_brier_sum) / n, 6),
            "cap_truncated_count": cap_truncated,
            "high_prob_new_count": high_prob_markets,
            "active_method": self.active_method,
        }

        logging.info(
            "%s BACKTEST: old_brier=%.4f, new_brier=%.4f, "
            "improvement=%.4f, cap_truncated=%d/%d, high_prob_new=%d",
            self._label, result["old_brier"], result["new_brier"], result["brier_improvement"],
            cap_truncated, n, high_prob_markets,
        )
        return result


# ═════════════════════════════════════════════════════════════════════════════
#  OpportunityScanner
# ═════════════════════════════════════════════════════════════════════════════

class OpportunityScanner:
    """Evaluate all markets across active windows and return the best trade candidate.

    Filters by: time-to-close, one-asset-per-window, probability pre-filter,
    orderbook price range, edge threshold, and position sizing.
    """

    def __init__(self, client: KalshiClient, state: StateManager,
                 feed: CoinbaseFeed, vol: VolatilityEngine, logger: Logger,
                 sizer: PositionSizer, order_flow: Optional[OrderFlowEngine] = None,
                 kalshi_oft: Optional[KalshiOrderFlowTracker] = None,
                 kalshi_feed=None, main_loop=None):
        self._client = client
        self._state = state
        self._feed = feed
        self._vol = vol
        self._logger = logger
        self._sizer = sizer
        self._order_flow = order_flow
        self._kalshi_oft = kalshi_oft
        self._kalshi_feed = kalshi_feed
        self._ml = main_loop
        # Orderbook cache: ticker -> (data, fetch_time)
        self._ob_cache: Dict[str, Tuple[Optional[Dict], float]] = {}
        # WS-bypass cooldown: ticker -> expiry_unix_ts. During cooldown,
        # _get_orderbook_cached skips WS and goes straight to REST. Set by
        # flag_ticker_drifted when scan silent-bails. Fix #1a from
        # kb/failures/ws-cache-drift-silent-scan-2026-04-24.md.
        self._ws_drift_cooldown: Dict[str, float] = {}
        # Balance cache: (balance_cents, fetch_time)
        self._balance_cache: Tuple[Optional[int], float] = (None, 0.0)
        # Scan stats from last scan() call
        self._last_scan_stats: Optional[Dict] = None
        # Session-level counters for dashboard
        self._session_strategy_counts: Dict[str, int] = {
            STRATEGY_WAIT: 0, STRATEGY_MAKER_PATIENT: 0,
            STRATEGY_MAKER_AGGRESSIVE: 0, STRATEGY_TAKER_NOW: 0,
            STRATEGY_PANIC_CAPTURE: 0,
        }
        self._session_asset_perf: Dict[str, Dict[str, int]] = {
            a: {"opportunities_found": 0, "times_selected": 0, "times_rejected": 0}
            for a in ASSETS
        }
        self._session_total_scanned: int = 0
        self._session_total_candidates: int = 0
        self._last_opportunity_ts: Optional[str] = None
        self._recent_opportunities: deque = deque(maxlen=20)
        self._ticker_ask_history: Dict[str, deque] = {}
        self._eval_opp_seen: set = set()  # 2-tuples (ticker, stage) or 3-tuples (ticker, stage, side)
        # Scan-productivity heartbeat — updated each tick when scan() actually
        # iterates a 15M window body. Watchdog reads this instead of DB row
        # count: dedup at insert sites can suppress writes for a window's
        # entire 15-min lifetime once each (ticker, stage) tuple is seen,
        # producing watchdog false positives even though scan is healthy.
        # See ws-cache-drift-silent-scan-2026-04-24 PM Apr 24 incident #3.
        self._scan_15m_iter_heartbeat_ts: float = 0.0
        self._dc_skip_cooldown: Dict[str, float] = {}  # ticker → expiry timestamp (60s after "no asks" skip)
        self._shadow_cal_last_log: Dict[str, float] = {}
        # Hourly per-window tracking (reset each scan tick)
        self._hourly_window_counts: Dict[str, int] = {}
        self._hourly_window_risk: Dict[str, float] = {}

        # Overnight LP shadow: per-asset vol history for circuit breaker
        # Stores (timestamp, blended_rv) tuples during overnight hours
        # ~8640 obs/night at 5s ticks × 7 days ≈ 60K max
        self._overnight_rv_history: Dict[str, deque] = {
            a: deque(maxlen=70000) for a in ASSETS
        }
        self._overnight_lp_vol_skip_count: int = 0  # session counter for dashboard

        # Low-price shadow: per-window and per-hour correlation tracking (reset each tick)
        self._lp_window_counts: Dict[str, int] = {}
        self._lp_hour_signals: Dict[str, int] = {}  # key = "HH" UTC hour string

        # ── Phase 2 extended feature state ──
        # Per-ticker window state: {ticker: {first_above_since, max_buf, min_buf,
        #   crossings_deque, spot_at_open, last_above_strike}}.
        # Bounded: cleaned up when ticker is beyond scan window (hook in scan()).
        # Max memory: ~100 tickers × ~200 bytes = 20KB.
        self._window_states: Dict[str, Dict[str, Any]] = {}
        # Bot state cache: 1-min TTL to avoid SQL contention on every insert.
        # Keyed by asset for active_positions / bot_pnl / drawdown / ioc_fill_rate.
        self._bot_state_cache: Dict[str, Any] = {"ts": 0.0, "features_by_asset": {}}
        # WS vs REST drift probe (H-NEW diagnostic). Once per minute, pick a
        # random subscribed 15M ticker, fetch REST /orderbook depth=100, diff
        # against WS cache. Measures the cache-vs-truth gap that produces
        # WS delta underflow warnings. Observation-only; no state mutation.
        # See kb/failures/kalshi-ws-schema-drift.md § "WS delta underflow".
        self._drift_probe_last_run: float = 0.0
        # Attach the extended feature provider callback to StateManager so
        # insert_evaluated_opportunity auto-populates Tier 1/2/3/6 for 15M rows.
        self._state._extended_feature_provider = self._get_extended_features_for_ticker

        # ── Startup assertion: _shadow_diag keys must be accepted by DB insert fns ──
        # Prevents the bug class where a new key in _shadow_diag causes a crash
        # at every **_shadow_diag splat into insert_rejection/insert_evaluated_opportunity.
        _SHADOW_DIAG_KEYS = {
            "egarch_sigma", "egarch_blend_sigma", "egarch_blend_weight",
            "mz_r_squared", "shadow_tv_blend_rv", "mz_shadow_sigmoid_w",
            "mz_baseline_qlike", "mz_qlike", "no_ask_cents",
            # Phase 7 cal_mlp audit fields (added by Edit 4 hook to _shadow_diag).
            # insert_rejection's signature does NOT receive cal_mlp_* params,
            # so the assertion only enforces acceptance on
            # insert_evaluated_opportunity. Phase D (2026-05-02) moved the
            # hook earlier in the scan iteration; the one post-annotate
            # insert_rejection site (tradeable_false with_market) strips
            # cal_mlp_* inline at its splat to satisfy this constraint.
        }
        _SHADOW_DIAG_KEYS_EVAL_OPP_ONLY = _SHADOW_DIAG_KEYS | {
            "cal_mlp_p_mean", "cal_mlp_p_std", "cal_mlp_final_lo",
            "cal_mlp_final_hi", "cal_mlp_train_id", "cal_mlp_skipped_reason",
            "cal_mlp_request_id",  # R-p7-deploy-r8: async-predict uuid
        }
        for _fn_name, _fn, _expected in [
            ("insert_rejection", self._state.insert_rejection, _SHADOW_DIAG_KEYS),
            ("insert_evaluated_opportunity", self._state.insert_evaluated_opportunity, _SHADOW_DIAG_KEYS_EVAL_OPP_ONLY),
        ]:
            _accepted = set(inspect.signature(_fn).parameters.keys())
            _unknown = _expected - _accepted
            assert not _unknown, (
                f"_shadow_diag keys {_unknown} not accepted by {_fn_name}(). "
                f"Add them to the function signature + SQL or remove from _shadow_diag."
            )

        # ── Startup assertion: DB busy_timeout must be set ──
        # Prevents the bug class where a new sqlite3.connect() call forgets
        # PRAGMA busy_timeout, causing "database is locked" under contention.
        # (Learned: sports_engine.py missing busy_timeout → ~2000 errors/8hr, Mar 2 2026)
        _bt = self._state.conn.execute("PRAGMA busy_timeout").fetchone()[0]
        assert _bt >= 5000, (
            f"StateManager busy_timeout={_bt}ms is too low (need ≥5000). "
            f"Add: conn.execute('PRAGMA busy_timeout=30000')"
        )

        # ── Startup assertion: critical config values ──
        assert MARKET_BLEND_W == 0.40, f"MARKET_BLEND_W misconfigured: {MARKET_BLEND_W}"
        assert SHADOW_CAL_PIPELINE is True, "SHADOW_CAL_PIPELINE should be True"
        assert MAX_RISK_PER_TRADE == 0.25, f"MAX_RISK_PER_TRADE misconfigured: {MAX_RISK_PER_TRADE}"
        assert XRP_MAX_RISK_PER_TRADE <= MAX_RISK_PER_TRADE, (
            f"XRP risk {XRP_MAX_RISK_PER_TRADE} > 15M risk {MAX_RISK_PER_TRADE}")
        assert XRP_MAX_RISK_PER_TRADE >= 0.05, f"XRP_MAX_RISK_PER_TRADE too low: {XRP_MAX_RISK_PER_TRADE}"
        assert BTC_MAX_RISK_PER_TRADE <= MAX_RISK_PER_TRADE, (
            f"BTC risk {BTC_MAX_RISK_PER_TRADE} > 15M risk {MAX_RISK_PER_TRADE}")
        assert BTC_MAX_RISK_PER_TRADE >= 0.05, f"BTC_MAX_RISK_PER_TRADE too low: {BTC_MAX_RISK_PER_TRADE}"
        logging.info(
            "CONFIG_VERIFY: MARKET_BLEND_W=%.2f SHADOW_CAL_PIPELINE=%s "
            "MAX_RISK=%s XRP_MAX_RISK=%s BTC_MAX_RISK=%s XRP_15M_SHADOW=%s SIZING_TIERS=%s DRAWDOWN_HALF=%.2f DRAWDOWN_QUARTER=%.2f "
            "DRAWDOWN_HALT=%.2f MAKER_ONLY_THRESHOLD=%.0f",
            MARKET_BLEND_W, SHADOW_CAL_PIPELINE, MAX_RISK_PER_TRADE, XRP_MAX_RISK_PER_TRADE, BTC_MAX_RISK_PER_TRADE,
            XRP_15M_SHADOW, SIZING_TIERS, DRAWDOWN_HALF_THRESHOLD, DRAWDOWN_QUARTER_THRESHOLD,
            DRAWDOWN_HALT_THRESHOLD, MAKER_ONLY_THRESHOLD)

        # ── Hourly config verify ──
        if HOURLY_OBSERVATION_ENABLED:
            assert HOURLY_MARKET_BLEND_W >= 0.30, (
                f"HOURLY_MARKET_BLEND_W={HOURLY_MARKET_BLEND_W} too low")
            assert HOURLY_MIN_ENTRY_PRICE >= 50, (
                f"HOURLY_MIN_ENTRY_PRICE={HOURLY_MIN_ENTRY_PRICE} too low")
            assert HOURLY_MIN_ENTRY_PRICE <= MIN_ENTRY_PRICE, (
                f"HOURLY floor {HOURLY_MIN_ENTRY_PRICE} > 15M floor {MIN_ENTRY_PRICE}")
            assert HOURLY_MAX_RISK_PER_TRADE <= MAX_RISK_PER_TRADE, (
                f"HOURLY risk {HOURLY_MAX_RISK_PER_TRADE} > 15M risk {MAX_RISK_PER_TRADE}")
            assert HOURLY_TEMPERATURE_T > 0, "HOURLY_TEMPERATURE_T must be positive"
            assert 0 < HOURLY_KELLY_FRACTION <= 1.0, "HOURLY_KELLY_FRACTION must be in (0, 1]"
            assert HOURLY_MIN_STC_ENTRY < HOURLY_MAX_STC_ENTRY, "STC entry window invalid"
            assert HOURLY_MAX_POSITIONS_PER_WINDOW >= 1, "Must allow at least 1 position per window"
            logging.info(
                "CONFIG_VERIFY (hourly): ENABLED=%s OBS_ONLY=%s BLEND_W=%.2f "
                "MIN_ENTRY=%dc MAX_RISK=%.2f MAX_STC=%ds MIN_STC=%ds "
                "TEMP_T=%.2f KELLY_F=%.2f MIN_EDGE=%.3f%%",
                HOURLY_OBSERVATION_ENABLED, HOURLY_OBSERVATION_ONLY,
                HOURLY_MARKET_BLEND_W, HOURLY_MIN_ENTRY_PRICE,
                HOURLY_MAX_RISK_PER_TRADE, HOURLY_MAX_SECONDS_BEFORE_CLOSE,
                HOURLY_MIN_STC_ENTRY,
                HOURLY_TEMPERATURE_T, HOURLY_KELLY_FRACTION,
                HOURLY_MIN_EDGE_PCT * 100)

        # ── Dip addon config verify ──
        if DIP_ADDON_ENABLED:
            assert DIP_ADDON_MIN_DROP_CENTS >= 2, "dip addon drop too small"
            assert DIP_ADDON_MAX_TOTAL_RISK <= MAX_RISK_PER_TRADE * 2, (
                "dip addon risk too high")
            logging.info(
                "CONFIG_VERIFY (dip_addon): ENABLED=%s SHADOW=%s "
                "DROP=%dc STC=%.0fs RISK=%.2f FLOOR=%dc",
                DIP_ADDON_ENABLED, DIP_ADDON_SHADOW_MODE,
                DIP_ADDON_MIN_DROP_CENTS, DIP_ADDON_MIN_STC_REMAINING,
                DIP_ADDON_MAX_TOTAL_RISK, DIP_ADDON_MIN_ENTRY_PRICE)

        # ── Sports config verify ──
        if SPORTS_ENABLED:
            assert SPORTS_OBSERVATION_ONLY is True, (
                "SPORTS_OBSERVATION_ONLY must be True — never live without explicit promotion")
            logging.info(
                "CONFIG_VERIFY (sports): ENABLED=%s OBS_ONLY=%s",
                SPORTS_ENABLED, SPORTS_OBSERVATION_ONLY)

        # ── Validate market_config.py matches bot/_impl.py constants ──
        validate_market_configs()

    # ── V2 variant helper (shadow cal pipeline: temperature + no blend) ──

    def _insert_hourly_v2_variant(
        self, ticker: str, window: Dict, asset: str,
        raw_prob: Optional[float], best_ask: int, seconds_remaining: float,
        spot: float, threshold: float, blended_rv: float,
        ofa_adjustment: float, z_score: float, vol_est: Dict,
        calibrated_prob_raw: float, est_fee_1c: float,
        ask_depth: Optional[int], best_ask_source: Optional[str],
        _cf: Dict, _shadow_diag: Dict,
    ):
        """Insert a V2 variant row for hourly signals using the shadow cal pipeline.

        V2 uses temperature scaling + no market blend (vs V1's beta cal + 40% blend).
        Gets its own edge, sizing, and filter_stage for independent PnL simulation.
        Settlement works automatically since it shares the same table + ticker.
        """
        _v2_data = _cf.get("cal_pipeline") or _cf.get("old_cal_system")
        if not _v2_data:
            return
        _v2_prob = _v2_data.get("prob")
        if _v2_prob is None:
            return
        _v2_dedup = (ticker, "hourly_observation_v2")
        if _v2_dedup in self._eval_opp_seen:
            return
        self._eval_opp_seen.add(_v2_dedup)

        _v2_edge = _v2_prob - best_ask / 100.0
        _v2_fee_edge = _v2_data.get("fee_edge")
        if _v2_fee_edge is None:
            _v2_fee_edge = _v2_edge - est_fee_1c / 100.0
        _v2_ev = (_v2_prob * (100 - best_ask)) - ((1 - _v2_prob) * best_ask) - est_fee_1c

        # V2 sizing (Kelly with V2 probability)
        _v2_contracts = 0
        _v2_kelly_f = None
        _v2_drawdown = None
        _v2_balance = self._get_balance_cached()
        if _v2_balance and _v2_balance > 0:
            _v2_sizing = self._sizer.compute(_v2_prob, best_ask, _v2_balance)
            _v2_kelly_f = _v2_sizing["kelly_f"]
            _v2_contracts = _v2_sizing["contracts"]
            _v2_drawdown = _v2_sizing["drawdown_scaler"]
            _v2_scfg = get_market_config("hourly")
            if _v2_scfg.kelly_fraction < 1.0:
                _v2_contracts = max(1, int(_v2_contracts * _v2_scfg.kelly_fraction))
            _v2_max = int((_v2_balance * _v2_scfg.max_risk_per_trade) / best_ask)
            if _v2_contracts > _v2_max:
                _v2_contracts = max(1, _v2_max)

        try:
            self._state.insert_evaluated_opportunity(
                ticker, window["event_ticker"], asset,
                "hourly_observation_v2",
                spot_price=spot, threshold=threshold,
                volatility=blended_rv, market_price=best_ask,
                seconds_to_close=seconds_remaining,
                calibrated_prob=_v2_prob, edge=_v2_edge,
                ofa_adjustment=ofa_adjustment,
                z_score=z_score,
                vol_regime=vol_est["regime"],
                calibrated_prob_raw=calibrated_prob_raw,
                kelly_f=_v2_kelly_f,
                position_size=_v2_contracts,
                drawdown_scaler=_v2_drawdown,
                breakeven_wr=best_ask / 100.0,
                expected_value=round(_v2_ev, 2),
                ask_depth=ask_depth,
                best_ask_source=best_ask_source,
                raw_prob=raw_prob,
                calibration_method="shadow_cal_v2",
                fee_adjusted_edge=_v2_fee_edge,
                product_type="hourly",
                shadow_cal_temperature=_v2_data.get("temperature"),
                **_shadow_diag)
        except Exception:
            logging.warning("insert_evaluated_opportunity failed (hourly_observation_v2)", exc_info=True)

    # ── Phase 2: Extended Feature Computation ─────────────────────────────
    # These methods populate Tier 1/2/3/6 features on the insert callback.
    # Called from self._get_extended_features_for_ticker() which is hooked
    # into StateManager.insert_evaluated_opportunity via _extended_feature_provider.

    def _update_window_state(self, ticker: str, spot: Optional[float],
                              threshold: Optional[float]) -> None:
        """Update per-window spot-path state. Call once per scan tick per ticker.

        Tracks: first_above_strike timestamp, max/min buffer seen, crossings
        in last 5 min, spot at window open, last above/below state.
        """
        if spot is None or threshold is None or threshold <= 0:
            return
        now = time.time()
        state = self._window_states.get(ticker)
        if state is None:
            # Bound dict size — evict oldest if we hit cap
            if len(self._window_states) >= 100:
                oldest = min(self._window_states,
                             key=lambda k: self._window_states[k].get("last_ts", 0))
                self._window_states.pop(oldest, None)
            state = {
                "spot_at_open": spot,
                "first_above_since": None,
                "max_buf": None,
                "min_buf": None,
                "crossings": deque(maxlen=50),  # (timestamp,) per crossing event
                "was_above": None,  # last observed state
                "last_ts": now,
                # Phase F (shadow coverage expansion 2026-05-02): cumulative
                # time-above/below accumulators + threshold for excursion
                # price-unit conversion. See
                # kb/decisions/shadow-coverage-expansion-may01.md.
                "time_above_total_s": 0.0,
                "time_below_total_s": 0.0,
                "threshold": threshold,
                # Phase F-3: window-open timestamp pinned ONCE on creation —
                # never overwritten on subsequent ticks. Used by
                # _compute_knockout_time_relative to normalize "time decided"
                # by total observation window elapsed.
                "window_open_ts": now,
            }
            self._window_states[ticker] = state

        buf_pct = (spot - threshold) / threshold * 100
        is_above = spot >= threshold

        # Update max/min
        if state["max_buf"] is None or buf_pct > state["max_buf"]:
            state["max_buf"] = buf_pct
        if state["min_buf"] is None or buf_pct < state["min_buf"]:
            state["min_buf"] = buf_pct

        # Detect crossings (transition between above/below)
        if state["was_above"] is not None and is_above != state["was_above"]:
            state["crossings"].append(now)

        # Phase F: accumulate time above/below using prior was_above and
        # time delta since last_ts. Skips the first call (was_above=None);
        # subsequent calls add the dt to whichever bucket the spot was in
        # PRIOR to this update.
        if state["was_above"] is not None:
            dt = max(0.0, now - state["last_ts"])
            if state["was_above"]:
                state["time_above_total_s"] += dt
            else:
                state["time_below_total_s"] += dt
        state["was_above"] = is_above

        # Track contiguous time above strike
        if is_above:
            if state["first_above_since"] is None:
                state["first_above_since"] = now
        else:
            state["first_above_since"] = None

        # Phase F: refresh threshold so the excursion calc uses the most
        # current strike (15M strikes are static per window — this is a
        # no-op for the second+ tick — but defensive against future
        # multi-strike paths).
        state["threshold"] = threshold
        state["last_ts"] = now

    def _compute_window_features(self, ticker: str) -> Dict[str, Any]:
        """Tier 1 features from _window_states."""
        state = self._window_states.get(ticker)
        if state is None:
            return {}
        now = time.time()
        minutes_above = None
        if state.get("first_above_since") is not None:
            minutes_above = (now - state["first_above_since"]) / 60.0
        cutoff = now - 300  # 5 min
        recent_crossings = sum(1 for t in state["crossings"] if t >= cutoff)
        # Phase F (shadow coverage expansion 2026-05-02): resolution
        # metadata. max_excursion is signed price (max above wins if its
        # |buf_pct| > |min_buf|; otherwise min_buf wins with negative sign).
        # See kb/decisions/shadow-coverage-expansion-may01.md.
        max_excursion_from_strike = None
        max_buf = state.get("max_buf")
        min_buf = state.get("min_buf")
        threshold = state.get("threshold")
        if threshold is not None and threshold > 0 and (
            max_buf is not None or min_buf is not None
        ):
            mb = max_buf if max_buf is not None else 0.0
            nb = min_buf if min_buf is not None else 0.0
            picked = mb if abs(mb) >= abs(nb) else nb
            max_excursion_from_strike = picked * threshold / 100.0
        return {
            "minutes_above_strike": minutes_above,
            "window_max_buf_pct": max_buf,
            "window_min_buf_pct": min_buf,
            "recent_crossings_5m": recent_crossings,
            "spot_at_window_open": state.get("spot_at_open"),
            "time_above_strike_seconds": state.get("time_above_total_s"),
            "time_below_strike_seconds": state.get("time_below_total_s"),
            "max_excursion_from_strike": max_excursion_from_strike,
            # Phase F-3: decision-time approximation of knockout-time-relative.
            "knockout_time_relative": self._compute_knockout_time_relative(state, now),
        }

    def _compute_momentum_features(self, asset: str) -> Dict[str, Any]:
        """Tier 2: spot momentum from CoinbaseFeed buffer."""
        try:
            buf = self._feed.get_buffer(asset)
        except Exception:
            return {}
        if not buf or len(buf) < 2:
            return {}
        now = time.time()
        current_price = buf[-1][1]

        def _price_at(seconds_ago: float) -> Optional[float]:
            """Find closest buffer entry to (now - seconds_ago)."""
            target = now - seconds_ago
            best = None
            best_dt = float("inf")
            for ts, price in buf:
                if ts > now:
                    continue
                dt = abs(ts - target)
                if dt < best_dt:
                    best_dt = dt
                    best = price
                if ts >= target:  # passed target, early exit
                    break
            # Tolerate up to 30s mismatch on lookup
            if best_dt > 30:
                return None
            return best

        def _pct_bps(current: Optional[float], past: Optional[float]) -> Optional[float]:
            if current is None or past is None or past == 0:
                return None
            return (current - past) / past * 10000.0

        mom_60s = _pct_bps(current_price, _price_at(60))
        mom_5m = _pct_bps(current_price, _price_at(300))

        # 15-min range: iterate buffer once
        cutoff_15m = now - 900
        prices_15m = [p for t, p in buf if t >= cutoff_15m]
        range_15m_bps = None
        if len(prices_15m) >= 2:
            hi = max(prices_15m)
            lo = min(prices_15m)
            mid = (hi + lo) / 2
            if mid > 0:
                range_15m_bps = (hi - lo) / mid * 10000.0

        return {
            "spot_momentum_60s_bps": mom_60s,
            "spot_momentum_5m_bps": mom_5m,
            "spot_realized_range_15m_bps": range_15m_bps,
        }

    def _compute_cross_asset_features(self, asset: str) -> Dict[str, Any]:
        """Tier 3: BTC momentum + relative return vs BTC.

        For BTC itself, returns BTC self-momentum (still useful). For non-BTC,
        also computes relative return vs BTC over 30m.
        """
        result: Dict[str, Any] = {}
        try:
            btc_buf = self._feed.get_buffer("BTC")
        except Exception:
            return result
        if not btc_buf or len(btc_buf) < 2:
            return result
        now = time.time()
        btc_now = btc_buf[-1][1]

        def _price_at(buf_list, seconds_ago: float) -> Optional[float]:
            target = now - seconds_ago
            best = None
            best_dt = float("inf")
            for ts, price in buf_list:
                if ts > now:
                    continue
                dt = abs(ts - target)
                if dt < best_dt:
                    best_dt = dt
                    best = price
            if best_dt > 60:
                return None
            return best

        def _pct_bps(cur, past):
            if cur is None or past is None or past == 0:
                return None
            return (cur - past) / past * 10000.0

        btc_30m_ago = _price_at(btc_buf, 1800)
        btc_5m_ago = _price_at(btc_buf, 300)
        btc_15m_ago = _price_at(btc_buf, 900)
        result["btc_spot_change_30m_bps"] = _pct_bps(btc_now, btc_30m_ago)
        result["btc_spot_change_5m_bps"] = _pct_bps(btc_now, btc_5m_ago)

        # BTC realized vol (15m): std of 60s log returns within the window
        try:
            cutoff = now - 900
            recent = [(t, p) for t, p in btc_buf if t >= cutoff]
            if len(recent) >= 10:
                # Sample at ~60s intervals by taking every Nth
                step = max(1, len(recent) // 15)
                sampled = recent[::step]
                import math as _math
                returns = []
                for i in range(1, len(sampled)):
                    p0 = sampled[i - 1][1]
                    p1 = sampled[i][1]
                    if p0 > 0 and p1 > 0:
                        returns.append(_math.log(p1 / p0))
                if len(returns) >= 3:
                    mean = sum(returns) / len(returns)
                    var = sum((r - mean) ** 2 for r in returns) / len(returns)
                    result["btc_realized_vol_15m"] = _math.sqrt(var)
        except Exception:
            pass

        # Relative return: non-BTC assets only
        if asset != "BTC":
            try:
                asset_buf = self._feed.get_buffer(asset)
                if asset_buf and len(asset_buf) >= 2:
                    asset_now = asset_buf[-1][1]
                    asset_30m_ago = _price_at(asset_buf, 1800)
                    asset_ret = _pct_bps(asset_now, asset_30m_ago)
                    btc_ret = result.get("btc_spot_change_30m_bps")
                    if asset_ret is not None and btc_ret is not None:
                        result["sol_btc_relative_return_30m_bps"] = asset_ret - btc_ret
            except Exception:
                pass

        return result

    def _compute_knockout_time_relative(
        self, state: Dict[str, Any], now: float,
    ) -> Optional[float]:
        """Phase F-3 (shadow coverage expansion 2026-05-02): approximate
        decision-time knockout-time-relative from a window state.

        Formula: (now - last_crossing_ts) / (now - window_open_ts).
        Bounded [0, 1]. Higher = market has been on one side longer
        relative to total observation window.
          - 1.0 = no crossings since window open (perfectly decided)
          - ~0.0 = crossing JUST happened (still in flux)
          - intermediate = X% of window-elapsed has been "decided"

        Returns None if `window_open_ts` is missing (pre-Phase-F-3 state)
        or in the future (clock skew).

        DEFERRED to a Phase F-3b: a settlement-time backfill via
        SettlementTracker would produce a more accurate value relative to
        the FULL window (including post-decision-tick activity). Phase F-3
        ships the decision-tick approximation. Master plan:
        kb/decisions/shadow-coverage-expansion-may01.md.
        """
        window_open_ts = state.get("window_open_ts")
        if window_open_ts is None:
            return None
        elapsed = now - window_open_ts
        if elapsed <= 0:
            return None
        crossings = state.get("crossings") or ()
        # Pull the most recent crossing — `crossings` is a deque appended
        # in chronological order, so [-1] is the latest.
        try:
            last_crossing = crossings[-1] if len(crossings) > 0 else None
        except Exception:
            last_crossing = None
        if last_crossing is None:
            # Never crossed since window open → fully decided since open.
            return 1.0
        decided_seconds = now - last_crossing
        # Clamp into [0, 1] — last_crossing < window_open_ts shouldn't
        # happen in well-formed state but defends against legacy data.
        return max(0.0, min(1.0, decided_seconds / elapsed))

    @staticmethod
    def _compute_maker_counterfactual(
        best_yes_bid: Optional[int],
        best_yes_ask: Optional[int],
        ladder_json: Optional[str],
    ) -> Dict[str, Any]:
        """Phase F-2 (shadow coverage expansion 2026-05-02): snapshot half
        of the maker-counterfactual fields. Computes:

          - `maker_price_cents` = best_yes_bid + 1 (a "1-cent improve"
            maker post that becomes the new top of book). NULL if either
            best_yes_bid or best_yes_ask is unavailable, OR if the implied
            maker price would cross the ask (in which case a "maker post"
            is mathematically a taker — better to mark NULL than mislabel).

          - `maker_depth_at_post` = sum of YES-bid quantities at the
            target maker price level in the current ladder. 0 if no level
            (typical for an improve maker) or ladder unparseable; ladder
            None / non-JSON also returns 0 (the conservative answer for
            "level didn't exist" — distinct from NULL price which signals
            "the question itself doesn't apply").

        DEFERRED to a future Phase F-2b: `maker_would_fill_within_30s`
        requires a post-hoc fillability daemon tracking ask depletion +
        trade prints over 30s. Master plan:
        kb/decisions/shadow-coverage-expansion-may01.md.
        """
        out: Dict[str, Any] = {
            "maker_price_cents": None,
            "maker_depth_at_post": None,
        }
        if best_yes_bid is None or best_yes_ask is None:
            return out
        maker_price = best_yes_bid + 1
        if maker_price >= best_yes_ask:
            # Post would cross the ask → not a maker at all.
            return out
        out["maker_price_cents"] = maker_price
        # Depth lookup. Default 0 (the answer for "level not in ladder").
        depth = 0
        if ladder_json:
            try:
                ladder = json.loads(ladder_json)
                for entry in (ladder.get("yes_bids") or []):
                    if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                        if int(entry[0]) == maker_price:
                            depth += int(entry[1])
            except Exception:
                # Malformed JSON → treat as level-absent (depth 0).
                pass
        out["maker_depth_at_post"] = depth
        return out

    def _compute_cross_asset_spot_snapshot(self) -> Dict[str, Any]:
        """Phase F (shadow coverage expansion 2026-05-02): absolute spot
        snapshot of all 4 crypto assets at the current decision tick.

        Distinct from `_compute_cross_asset_features` (which returns
        relative `*_bps` changes) — these are LEVELS. Used to enable
        cross-asset interaction analysis on shadow rows post-hoc, where
        the relative-change features alone are insufficient (e.g.,
        "what was BTC spot when this XRP signal fired?"). One feed lookup
        per asset (cheap; CoinbaseFeed caches in-memory). Missing prices
        return None — caller will write NULL.

        Master plan: kb/decisions/shadow-coverage-expansion-may01.md.
        """
        # Single get_all_prices() acquires the feed lock once vs 4
        # acquires for per-asset get_price (Phase F adversarial round 2 LOW-2).
        # ASSETS is the module-level constant from config.py (NOT an
        # OpportunityScanner attribute) — Phase F adversarial round 4
        # caught a `self.ASSETS` typo that would have silently NULL'd
        # all 4 cross-asset spot columns in production (the per-helper
        # try/except in _get_extended_features_for_ticker would swallow
        # the AttributeError).
        try:
            prices = self._feed.get_all_prices()
        except Exception:
            prices = {}
        return {f"{a.lower()}_spot_at_decision": prices.get(a) for a in ASSETS}

    def _compute_bot_state_features(self, asset: str) -> Dict[str, Any]:
        """Tier 6: active positions, recent PnL, drawdown, IOC fill rate.

        Cached at 1-min resolution to avoid SQL contention on every insert.
        """
        now = time.time()
        cache = self._bot_state_cache
        if now - cache.get("ts", 0) < 60:
            return cache.get("features_by_asset", {}).get(asset, {})
        try:
            features_by_asset = {}
            conn = self._state.conn
            # Active positions per asset
            pos_rows = conn.execute(
                "SELECT asset, COUNT(*) FROM positions "
                "WHERE status IN ('open', 'pending') GROUP BY asset"
            ).fetchall()
            pos_counts = {r[0]: r[1] for r in pos_rows}

            # Recent PnL last 30m
            pnl_row = conn.execute(
                "SELECT SUM(pnl_cents - COALESCE(fee_cents, 0)) FROM settled_trades "
                "WHERE settled_at > datetime('now', '-30 minutes')"
            ).fetchone()
            recent_pnl = pnl_row[0] if pnl_row and pnl_row[0] is not None else 0

            # Drawdown: current_balance vs _session_hwm_balance if tracked, else 0
            # Use main loop balance tracking if available
            drawdown_pct = 0.0
            if self._ml is not None:
                cur = getattr(self._ml, "_last_known_balance", None)
                hwm = getattr(self._ml, "_session_hwm_balance", None)
                if cur is not None and hwm is not None and hwm > 0:
                    drawdown_pct = max(0.0, (1 - cur / hwm) * 100)

            # IOC fill success rate last 1h: evaluated_opportunities with order_outcome
            ioc_row = conn.execute(
                "SELECT SUM(CASE WHEN order_outcome='filled' THEN 1 ELSE 0 END), COUNT(*) "
                "FROM evaluated_opportunities "
                "WHERE order_submitted_at > datetime('now', '-1 hour') "
                "AND order_outcome IS NOT NULL"
            ).fetchone()
            ioc_rate = None
            if ioc_row and ioc_row[1] and ioc_row[1] > 0:
                ioc_rate = ioc_row[0] / ioc_row[1]

            # Phase E (shadow coverage expansion 2026-05-02): state-at-
            # decision-time fields. All three are GLOBAL (not per-asset)
            # but stored uniformly in the per-asset cache for reuse.
            # Master plan: kb/decisions/shadow-coverage-expansion-may01.md.
            #
            # n_open_positions: total open positions across ALL assets
            # (distinct from active_positions_same_asset which is
            # same-asset only — already exposed above).
            n_open_positions = sum(pos_counts.values())

            # Phase H-2: also publish to MainLoop._open_positions_count_cache
            # so the bot microstate snapshot avoids per-insert SQL hits.
            # 60s cache (this whole block is gated by `now - cache.get('ts',
            # 0) < 60` above) — approximate, NOT decision-tick-exact. v2
            # training treats `open_positions_count` as approximate.
            if self._ml is not None:
                try:
                    self._ml._open_positions_count_cache = int(n_open_positions)
                except (TypeError, ValueError):
                    pass

            # time_since_last_fill_s: seconds since the most recent fill
            # event. Uses MAX across positions.opened_at AND
            # settled_trades.settled_at because (a) `positions` is
            # mutated by reconciliation — bot/_impl.py issues `DELETE FROM
            # positions WHERE ticker=?` when Kalshi REST reports
            # position_count=0 — so a quiet-period reconciliation can
            # drop all rows and turn `MAX(opened_at)` into NULL despite
            # recent activity; (b) `settled_trades` is append-only, so
            # `MAX(settled_at)` survives reconciliation. settled_at
            # slightly UNDERSTATES the actual fill-to-now duration (the
            # fill happened earlier than settlement) but that's a small
            # bias < the position's hold time. NULL only if there has
            # never been a fill OR settlement on this DB.
            tslf_row = conn.execute(
                "SELECT MAX(t) FROM ("
                "  SELECT MAX(opened_at) AS t FROM positions"
                "  UNION ALL"
                "  SELECT MAX(settled_at) AS t FROM settled_trades"
                ") WHERE t IS NOT NULL"
            ).fetchone()
            time_since_last_fill_s = None
            if tslf_row and tslf_row[0] is not None:
                # Compute via julianday so SQLite's ISO-8601 parser handles
                # the same timestamp formats (`datetime('now')` writes UTC).
                tslf_calc = conn.execute(
                    "SELECT (julianday('now') - julianday(?)) * 86400.0",
                    (tslf_row[0],),
                ).fetchone()
                if tslf_calc and tslf_calc[0] is not None:
                    # max(0,) defends against clock skew producing tiny negatives.
                    time_since_last_fill_s = max(0.0, float(tslf_calc[0]))

            # recent_n_outcome_streak: signed streak count from the most
            # recent settlement. Outcome semantics on net PnL
            # (pnl_cents - COALESCE(fee_cents,0)):
            #   net > 0 → WIN  (contributes +1)
            #   net < 0 → LOSS (contributes -1)
            #   net = 0 → PUSH (breaks streak; contributes 0)
            # Returns: positive int = consecutive wins, negative int =
            # consecutive losses, 0 = no trades OR most-recent is a push.
            # Bound to last 50 trades to limit sort cost (no index on
            # settled_at). 50 covers any operationally-relevant streak;
            # streaks longer than 50 would warrant a dedicated "regime
            # alert" signal, not just a count.
            streak = 0
            try:
                streak_rows = conn.execute(
                    "SELECT pnl_cents - COALESCE(fee_cents, 0) AS net_pnl "
                    "FROM settled_trades "
                    "ORDER BY settled_at DESC LIMIT 50"
                ).fetchall()
                if streak_rows:
                    first_net = streak_rows[0][0] or 0
                    if first_net != 0:
                        sign = 1 if first_net > 0 else -1
                        for r in streak_rows:
                            net = r[0] or 0
                            if (sign > 0 and net > 0) or (sign < 0 and net < 0):
                                streak += sign
                            else:
                                # PUSH (net=0) or sign change → break.
                                break
            except Exception:
                pass

            for a in ASSETS:
                features_by_asset[a] = {
                    "active_positions_same_asset": pos_counts.get(a, 0),
                    "recent_bot_pnl_30m_cents": int(recent_pnl),
                    "current_drawdown_pct": drawdown_pct,
                    "recent_ioc_fill_success_rate_1h": ioc_rate,
                    "n_open_positions": n_open_positions,
                    "time_since_last_fill_s": time_since_last_fill_s,
                    "recent_n_outcome_streak": streak,
                }
            cache["features_by_asset"] = features_by_asset
            cache["ts"] = now
            return features_by_asset.get(asset, {})
        except Exception as e:
            logging.debug("bot_state_features compute failed: %s", e)
            return {}

    def _get_extended_features_for_ticker(
        self, ticker: str, asset: Optional[str],
        spot_price: Optional[float], threshold: Optional[float],
        product_type: Optional[str],
    ) -> Dict[str, Any]:
        """Provider callback for StateManager.insert_evaluated_opportunity.

        Returns Tier 1/2/3/6 feature dict for 15M rows only. Fast (no SQL
        except for bot state which is cached at 1-min). Must not raise.
        """
        if product_type not in (None, "15m"):
            return {}
        if asset is None:
            return {}
        out: Dict[str, Any] = {}
        # Phase F (shadow coverage expansion 2026-05-02): each helper
        # gets its own try/except so a failure in one (e.g. bot state
        # SQL hits a transient DB lock) doesn't drop the others. Pre-
        # Phase-F a single shared try/except meant a bot_state DB
        # error wiped all 4 helpers' output. See
        # kb/decisions/shadow-coverage-expansion-may01.md.
        for _helper in (
            lambda: self._compute_window_features(ticker),
            lambda: self._compute_momentum_features(asset),
            lambda: self._compute_cross_asset_features(asset),
            lambda: self._compute_bot_state_features(asset),
            lambda: self._compute_cross_asset_spot_snapshot(),
        ):
            try:
                out.update(_helper())
            except Exception as e:
                logging.debug("extended_features helper failed for %s: %s", ticker, e)
        return out

    # ── Public entry point ────────────────────────────────────────────────

    def scan(self, active_windows: List[Dict]) -> Optional[List[Dict]]:
        """Evaluate all windows/markets, return best candidate or None."""
        now = time.time()
        _scan_tick_start_perf = time.perf_counter()
        # Phase H-2: per-tick monotonic counter + scan-loop-start pin for
        # the bot microstate snapshot. These attributes live on MainLoop
        # (this method runs in OpportunityScanner; `self._ml` is the
        # MainLoop ref). Round-1 wiring review caught this — writing to
        # `self._scan_iter` here would AttributeError on every tick.
        if self._ml is not None:
            try:
                self._ml._scan_iter += 1
                self._ml._scan_loop_start = _scan_tick_start_perf
            except Exception:
                # Defensive: a missing attr or non-int would not crash scan
                # (insert_evaluated_opportunity already tolerates None).
                pass
        ob_fetches_this_tick = 0
        candidates: List[Dict] = []

        # WS vs REST drift probe (self-throttles to 60s cadence). See
        # _drift_probe_tick docstring and kb/failures/kalshi-ws-schema-drift.md.
        try:
            self._drift_probe_tick()
        except Exception:
            logging.debug("drift probe failed", exc_info=True)

        # 15M silence watchdog (2026-04-24 17:30 UTC outage defense).
        # If no 15M evaluation has been inserted in 10+ min, alert on
        # Telegram. Self-throttled to one alert per 10 min via dedup_key.
        # See kb/failures/ws-15m-silence-2026-04-24.md.
        try:
            self._check_15m_silence_alert(active_windows)
        except Exception:
            logging.debug("15M silence alert check failed", exc_info=True)

        # Slow-tick instrumentation — log when gap between consecutive
        # scan() entries exceeds 2s. Diagnoses event-loop / main-thread
        # stalls (PM Fix 5 deferred — clock_drift_detected pattern).
        _prev_tick_start_perf = getattr(self, "_last_tick_start_perf", None)
        if _prev_tick_start_perf is not None:
            _gap = _scan_tick_start_perf - _prev_tick_start_perf
            if _gap > 2.0:
                logging.warning(
                    "SLOW_SCAN_TICK: %.2fs since previous tick start "
                    "(suggests main-thread stall — see PM Fix 5)", _gap)
        self._last_tick_start_perf = _scan_tick_start_perf

        # Scan-productive watchdog (fix #3 — 2026-04-24 22:12 UTC defense).
        # Checks whether the PREVIOUS tick wrote any 15m DB rows OR
        # iterated a 15M window body (heartbeat). Fires Telegram after
        # 5 consecutive silent-bail ticks (~2.5 min). See
        # kb/failures/ws-cache-drift-silent-scan-2026-04-24.md.
        _prev_tick_ts = getattr(self, "_last_tick_start_iso", None)
        _now_iso = datetime.datetime.now(timezone.utc).strftime(
            "%Y-%m-%dT%H:%M:%S.%fZ")
        self._last_tick_start_iso = _now_iso
        if _prev_tick_ts is not None:
            try:
                self._check_scan_productive_15m(active_windows, _prev_tick_ts)
            except Exception:
                logging.debug(
                    "scan-productive watchdog check failed", exc_info=True)

        # Reset hourly per-window tracking each tick, seeded from existing positions
        self._hourly_window_counts = {}
        self._hourly_window_risk = {}
        self._config_b_window_counts = {}  # Config B (BTC 70-89c wl2) separate counter
        self._dc_window_risk = {}  # Decided contract per-window risk tracker
        self._dc_window_cap_skips = 0  # Session counter for window cap skips
        self._lp_window_counts = {}  # Low-price shadow: per-window signal count
        # Weather NO-side kill switch: auto-disable if cumulative PnL below threshold
        # Check once per tick, uses module-level _weather_no_killed flag
        if WEATHER_NO_SIDE_LIVE:
            try:
                _wx_no_pnl = self._state.conn.execute(
                    "SELECT COALESCE(SUM(pnl_cents - COALESCE(fee_cents, 0)), 0) FROM settled_trades "
                    "WHERE product_type='weather' AND side='no'"
                ).fetchone()[0]
                if _wx_no_pnl < WEATHER_NO_KILL_THRESHOLD:
                    import bot._impl as _self_module
                    _self_module.WEATHER_NO_SIDE_LIVE = False
                    logging.error(
                        "WEATHER_NO_KILL: cumulative PnL=%dc < %dc — auto-disabling",
                        _wx_no_pnl, WEATHER_NO_KILL_THRESHOLD)
                    if _TELEGRAM:
                        _TELEGRAM.send(
                            f"\U0001f6a8 *WEATHER NO-SIDE AUTO-KILLED*\n"
                            f"Cumulative PnL: ${_wx_no_pnl/100:.2f} "
                            f"(threshold: ${WEATHER_NO_KILL_THRESHOLD/100:.2f})")
            except Exception:
                pass  # Non-critical
        # Hourly NO kill switch
        if HOURLY_NO_SIDE_LIVE:
            try:
                _hno_pnl = self._state.conn.execute(
                    "SELECT COALESCE(SUM(pnl_cents - COALESCE(fee_cents, 0)), 0) FROM settled_trades "
                    "WHERE product_type='hourly' AND side='no'"
                ).fetchone()[0]
                if _hno_pnl < HOURLY_NO_KILL_THRESHOLD:
                    import bot._impl as _self_module
                    _self_module.HOURLY_NO_SIDE_LIVE = False
                    logging.error(
                        "HOURLY_NO_KILL: cumulative PnL=%dc < %dc — auto-disabling",
                        _hno_pnl, HOURLY_NO_KILL_THRESHOLD)
                    if _TELEGRAM:
                        _TELEGRAM.send(
                            f"\U0001f6a8 *HOURLY NO-SIDE AUTO-KILLED*\n"
                            f"Cumulative PnL: ${_hno_pnl/100:.2f} "
                            f"(threshold: ${HOURLY_NO_KILL_THRESHOLD/100:.2f})")
            except Exception:
                pass  # Non-critical
        # Bracket NO kill switch (separate from general weather NO)
        if BRACKET_NO_ENABLED:
            try:
                _bn_pnl = self._state.conn.execute(
                    "SELECT COALESCE(SUM(pnl_cents - COALESCE(fee_cents, 0)), 0) FROM settled_trades "
                    "WHERE strategy='bracket_no'"
                ).fetchone()[0]
                if _bn_pnl < BRACKET_NO_KILL_THRESHOLD:
                    import bot._impl as _self_module
                    _self_module.BRACKET_NO_ENABLED = False
                    logging.error(
                        "BRACKET_NO_KILL: cumulative PnL=%dc < %dc — auto-disabling",
                        _bn_pnl, BRACKET_NO_KILL_THRESHOLD)
                    if _TELEGRAM:
                        _TELEGRAM.send(
                            f"\U0001f6a8 *BRACKET NO AUTO-KILLED*\n"
                            f"Cumulative PnL: ${_bn_pnl/100:.2f} "
                            f"(threshold: ${BRACKET_NO_KILL_THRESHOLD/100:.2f})")
            except Exception:
                pass  # Non-critical
        self._lp_hour_signals = {}  # Low-price shadow: per-hour signal count

        # Loss burst cooldown: build per-asset lockout set (see kb/failures/loss-clustering.md)
        # Any 15M loss in the last LOSS_COOLDOWN_SECONDS locks out that asset's 15M entries.
        # CRITICAL: use julianday() comparison, NOT string/`datetime('now',...)`. settled_at is
        # stored in ISO-T format ('2026-04-11T00:45:30.365339Z') and datetime('now',...) returns
        # space-format ('2026-04-11 09:28:14'). Lex-comparing them matches by ASCII where
        # 'T' (84) > ' ' (32), so a naive `settled_at > datetime('now','-2 hours')` returns TRUE
        # for ANY same-UTC-date loss, silently blocking the asset until UTC midnight.
        self._cooldown_assets = set()
        if LOSS_COOLDOWN_ENABLED:
            try:
                _cd_rows = self._state.conn.execute(
                    "SELECT DISTINCT asset FROM settled_trades "
                    "WHERE product_type='15m' AND pnl_cents < 0 "
                    "AND julianday(settled_at) > julianday('now') - ?/86400.0",
                    (LOSS_COOLDOWN_SECONDS,)
                ).fetchall()
                self._cooldown_assets = {r[0] for r in _cd_rows if r[0]}
                if self._cooldown_assets and self._cooldown_assets != getattr(self, "_cooldown_assets_last_logged", None):
                    logging.info("LOSS_COOLDOWN_ACTIVE: %s (window=%ds)",
                                 sorted(self._cooldown_assets), LOSS_COOLDOWN_SECONDS)
                    self._cooldown_assets_last_logged = set(self._cooldown_assets)
            except Exception:
                pass  # Non-critical

        try:
            for pos in self._state.get_open_positions():
                evt = pos.get("event_ticker", "")
                if evt:
                    self._hourly_window_counts[evt] = self._hourly_window_counts.get(evt, 0) + 1
                    # Seed DC window risk from existing decided positions
                    strat = pos.get("strategy", "")
                    if strat in ("decided_t1", "decided_t1b", "decided_t2"):
                        _dc_cost = pos.get("count", 0) * pos.get("avg_price_cents", 0)
                        self._dc_window_risk[evt] = self._dc_window_risk.get(evt, 0.0) + _dc_cost
        except Exception:
            pass  # Non-critical: worst case is slight over-allocation

        # Clean up ask history and dedup set for tickers no longer in active windows
        active_tickers = set()
        for w in active_windows:
            for m in w.get("markets", []):
                active_tickers.add(m.get("ticker", ""))
        expired = [t for t in self._ticker_ask_history if t not in active_tickers]
        for t in expired:
            del self._ticker_ask_history[t]
        expired_ob = [t for t in self._ob_cache if t not in active_tickers]
        for t in expired_ob:
            del self._ob_cache[t]
        # Unsubscribe expired tickers from WS orderbook_delta
        if self._kalshi_feed:
            ws_expired = set(expired) | set(expired_ob)
            for t in ws_expired:
                try:
                    self._kalshi_feed.unsubscribe_ticker(t)
                except Exception:
                    pass
        self._eval_opp_seen = {
            key for key in self._eval_opp_seen if key[0] in active_tickers
        }
        # Clean expired DC skip cooldowns
        _now_cd = time.time()
        self._dc_skip_cooldown = {
            t: exp for t, exp in self._dc_skip_cooldown.items()
            if exp > _now_cd and t in active_tickers
        }
        # Clean expired API error counters (prevent memory growth)
        if self._ml and hasattr(self._ml, "executor"):
            self._ml.executor._ticker_api_errors = {
                t: c for t, c in self._ml.executor._ticker_api_errors.items()
                if t in active_tickers
            }
        if self._kalshi_oft is not None:
            try:
                self._kalshi_oft.cleanup_stale(active_tickers)
            except Exception:
                pass
        if self._ml and getattr(self._ml, "fifteenm_shadow", None):
            try:
                self._ml.fifteenm_shadow.cleanup_expired(active_tickers)
            except Exception:
                pass
        if self._ml and getattr(self._ml, "hourly_alt_shadow", None):
            try:
                self._ml.hourly_alt_shadow.cleanup_expired(active_tickers)
            except Exception:
                pass

        # Build ticker set for product types that skip WS orderbook subscription (too many strikes)
        _hourly_tickers = set()
        for w in active_windows:
            if w.get("product_type") in ("hourly", "spx_hourly", "weather"):
                for m in w.get("markets", []):
                    _hourly_tickers.add(m.get("ticker", ""))

        # Pre-subscribe all active tickers to WS and feed OFT from WS orderbooks
        if self._kalshi_feed and self._kalshi_feed.is_connected:
            for t in active_tickers:
                if t in _hourly_tickers:
                    continue  # skip WS subscription for hourly (too many strikes per event)
                try:
                    self._kalshi_feed.subscribe_ticker(t)
                except Exception:
                    pass
            # Feed OFT with any available WS orderbook data (zero API cost)
            if self._kalshi_oft is not None:
                for t in active_tickers:
                    try:
                        ws_ob = self._kalshi_feed.get_orderbook(t)
                        if ws_ob and now - ws_ob.get("ts", 0) < 30:
                            best_ask = self._best_yes_ask_cents(ws_ob)
                            if best_ask is not None:
                                self._kalshi_oft.record_snapshot(t, ws_ob, best_ask)
                    except Exception:
                        pass

        # Dynamic scan_stats: include all assets from active windows (SPX, weather, etc.)
        _all_scan_assets = set(ASSETS)
        for w in active_windows:
            _all_scan_assets.add(w["asset"])
        scan_stats: Dict[str, Dict[str, int]] = {
            a: {"evaluated": 0, "low_prob": 0, "no_orderbook": 0, "no_best_ask": 0,
                "price_out_of_range": 0, "insufficient_edge": 0, "zero_sizing": 0,
                "strategy_wait": 0, "candidates": 0}
            for a in _all_scan_assets
        }

        _price_shadow_queue = []
        _no_side_queue = []  # NO-side shadow: markets queued for NO evaluation
        _overnight_lp_queue = []  # Overnight low-price shadow: 50-85c YES during overnight hours
        _low_price_shadow_queue = []  # Low-price shadow: 20-79c 15M signals (Phase C)

        # 1. Filter windows by time range (config-driven thresholds)
        time_ok_windows = []
        for w in active_windows:
            stc = w["seconds_to_close"]
            _tcfg = get_market_config(w.get("product_type"))
            if _tcfg.min_seconds_before_close <= stc <= _tcfg.max_seconds_before_close:
                time_ok_windows.append(w)
        # SPX diagnostic: log when SPX windows are filtered by STC
        _spx_in = [w for w in active_windows if w.get("product_type") == "spx_hourly"]
        _spx_ok = [w for w in time_ok_windows if w.get("product_type") == "spx_hourly"]
        if _spx_in and not _spx_ok:
            logging.warning("SPX_DIAG_STC: %d SPX windows ALL filtered — stc=[%s]",
                            len(_spx_in), ", ".join(f"{w['seconds_to_close']:.0f}" for w in _spx_in))
        elif _spx_ok:
            logging.info("SPX_DIAG_STC: %d/%d SPX windows passed time filter (stc=[%s])",
                         len(_spx_ok), len(_spx_in),
                         ", ".join(f"{w['seconds_to_close']:.0f}" for w in _spx_ok))
        # F/U 6 diagnostic: log when ALL 15M windows are filtered out
        # at the time-range gate but other product types survive. This
        # is the silent path that leaves the 15M heartbeat blind while
        # scan() body still iterates hourly/weather. Throttled to once
        # per 30s per code-path — see kb/failures (when written).
        _15m_in = [w for w in active_windows if w.get("product_type") == "15m"]
        _15m_time_ok = [w for w in time_ok_windows if w.get("product_type") == "15m"]
        if _15m_in and not _15m_time_ok:
            _now = time.time()
            _last = getattr(self, "_last_15m_time_filter_log_ts", 0.0)
            if _now - _last >= 30.0:
                self._last_15m_time_filter_log_ts = _now
                logging.warning(
                    "F_U6_15M_TIME_FILTER_DROPPED_ALL: %d 15M windows ALL "
                    "filtered by time range — details=[%s] (scan iterates "
                    "non-15M; heartbeat blind for this tick)",
                    len(_15m_in),
                    ", ".join(
                        f"{w.get('asset', '?')}={w.get('seconds_to_close', '?'):.1f}s"
                        for w in _15m_in))
        if not time_ok_windows:
            return None

        # 2. Get occupied timeslots (positions + resting orders)
        occupied = self._get_occupied_timeslots()

        # 3. Filter out windows whose timeslot already has this SAME asset
        eligible_windows = []
        for w in time_ok_windows:
            if w.get("product_type") in ("hourly", "spx_hourly", "weather"):
                eligible_windows.append(w)
                continue  # hourly/spx/weather windows bypass timeslot logic
            ts = self._window_timeslot(w["event_ticker"])
            if ts in occupied and w["asset"] in occupied[ts]:
                continue  # this asset already has a position/order in this timeslot
            eligible_windows.append(w)

        # F/U 6 diagnostic: log when ALL 15M survived the time filter
        # but were dropped by the timeslot-occupancy filter. Throttled
        # to once per 30s.
        _15m_eligible = [w for w in eligible_windows if w.get("product_type") == "15m"]
        if _15m_time_ok and not _15m_eligible:
            _now = time.time()
            _last = getattr(self, "_last_15m_eligible_filter_log_ts", 0.0)
            if _now - _last >= 30.0:
                self._last_15m_eligible_filter_log_ts = _now
                logging.warning(
                    "F_U6_15M_ELIGIBLE_FILTER_DROPPED_ALL: %d 15M windows "
                    "passed time but ALL filtered by timeslot occupancy — "
                    "details=[%s] occupied=%s (scan iterates non-15M; "
                    "heartbeat blind)",
                    len(_15m_time_ok),
                    ", ".join(
                        f"{w.get('asset', '?')}={w.get('seconds_to_close', '?'):.1f}s"
                        for w in _15m_time_ok),
                    {k: sorted(list(v)) for k, v in occupied.items()})

        if not eligible_windows:
            return None

        # 4. Evaluate each market in each surviving window.
        # Per-section timing — `SCAN_LOOP_SLOW` fires when the for-loop
        # body alone exceeds 1.5s. Distinguishes "main loop is slow"
        # from "post-loop processing is slow" (price_shadow, candidate
        # selection, etc.) under the SCAN_BODY_SLOW umbrella.
        # Apr 25 01:09 incident: SCAN_BODY_SLOW 5.64s — need to
        # localize within scan() body.
        _scan_loop_start = time.perf_counter()
        for window in eligible_windows:
            # Per-window timer (Phase 1 of scan-loop optimization).
            # SCAN_WINDOW_SLOW fires when one window's iteration body
            # exceeds 500ms. Localizes which window is the cost: if
            # several windows hit ~300-500ms each, orderbook REST is
            # the bottleneck (Phase 2: parallel prefetch). If one
            # window hits multi-second, a specific op in it is slow
            # (different fix needed). See Apr 25 01:17 incident.
            _window_start = time.perf_counter()
            asset = window["asset"]
            _pt = window.get("product_type")

            # Productivity heartbeat — set as soon as scan() reaches a 15M
            # window iteration body. Decoupled from DB writes because dedup
            # at insert sites can silence rows for an entire window's
            # lifetime even though scan is iterating normally.
            if _pt in (None, "15m"):
                self._scan_15m_iter_heartbeat_ts = time.time()

            # Loss burst cooldown: skip 15M entries for assets with a recent loss.
            # Bursts are driven by correlated macro moves; pausing 2h after any
            # loss prevents the 2nd-7th trades of the burst from entering.
            if (LOSS_COOLDOWN_ENABLED
                    and _pt in (None, "15m")
                    and asset in self._cooldown_assets):
                try:
                    if asset in scan_stats:
                        scan_stats[asset]["loss_cooldown"] = (
                            scan_stats[asset].get("loss_cooldown", 0) + 1)
                except Exception:
                    pass
                # Trace row so this silent-bail isn't a diagnostic black
                # hole. ws-cache-drift-silent-scan-2026-04-24 PM Prevention #3.
                try:
                    self._state.insert_evaluated_opportunity(
                        ticker=window["event_ticker"],
                        event_ticker=window["event_ticker"],
                        asset=asset,
                        filter_stage="silent_loss_cooldown",
                        rejection_reason="asset in cooldown_assets",
                        seconds_to_close=window.get("seconds_to_close"),
                        product_type=_pt or "15m")
                except Exception:
                    logging.debug(
                        "silent_loss_cooldown trace insert failed",
                        exc_info=True)
                continue

            # Route price/vol to appropriate engine based on product type
            if _pt == "spx_hourly" and self._ml and getattr(self._ml, "spx_engine", None):
                spot = self._ml.spx_engine.get_spot_price(asset)
                if spot is None or spot <= 0:
                    logging.warning("SPX_DIAG_SPOT: spot=%s for %s — skipping window", spot, asset)
                    continue
                seconds_remaining = window["seconds_to_close"]
                vol_est = self._ml.spx_engine.get_vol_estimate(asset, seconds_remaining)
            elif _pt == "weather" and self._ml and getattr(self._ml, "weather_engine", None):
                spot = self._ml.weather_engine.get_spot_price(asset)
                if spot is None or spot <= 0:
                    continue
                seconds_remaining = window["seconds_to_close"]
                vol_est = self._ml.weather_engine.get_vol_estimate(asset, seconds_remaining)
            else:
                _vol_start = time.perf_counter()
                spot = self._feed.get_price(asset)
                if spot is None or spot <= 0:
                    # Trace row — Coinbase price feed gap or restart warmup.
                    # ws-cache-drift-silent-scan-2026-04-24 PM Prevention #3.
                    try:
                        self._state.insert_evaluated_opportunity(
                            ticker=window["event_ticker"],
                            event_ticker=window["event_ticker"],
                            asset=asset,
                            filter_stage="silent_spot_none",
                            rejection_reason=f"spot={spot} from feed",
                            spot_price=spot if spot is not None else None,
                            seconds_to_close=window.get("seconds_to_close"),
                            product_type=_pt or "15m")
                    except Exception:
                        logging.debug(
                            "silent_spot_none trace insert failed",
                            exc_info=True)
                    continue
                seconds_remaining = window["seconds_to_close"]
                vol_est = self._vol.update(asset, seconds_to_close=seconds_remaining)
                # Per-section timing — SCAN_VOL_SLOW fires when the
                # spot fetch + vol.update call exceeds 300ms. Apr 25
                # 01:35: 10.43s BTC window stall with no slow OB
                # fetch — vol compute is a top suspect.
                _vol_dt = time.perf_counter() - _vol_start
                if _vol_dt > 0.3:
                    logging.warning(
                        "SCAN_VOL_SLOW: asset=%s took %.2fs", asset, _vol_dt)

            if vol_est is None or vol_est["blended_rv"] <= 0:
                if _pt == "spx_hourly":
                    logging.warning("SPX_DIAG_VOL: vol_est=%s blended_rv=%s — skipping window",
                                    "None" if vol_est is None else "ok",
                                    vol_est.get("blended_rv") if vol_est else "N/A")
                # Post-warmup escalation — first ~30s post-restart is
                # benign vol-engine warmup (RK + EGARCH need a few price
                # ticks). After 60s, vol_est=None is a real bug and must
                # log loudly so the next outage class self-announces.
                # See Apr 25 00:43 silent_vol_none investigation — all
                # 6 silent_vol_none events fired at 18.3s post-restart
                # in a single tick, then never again.
                _proc_start = getattr(self, "_scan_15m_process_start_ts", None)
                if (_proc_start is not None
                        and (time.time() - _proc_start) > 60.0
                        and _pt in (None, "15m", "hourly")):
                    logging.warning(
                        "VOL_NONE_POST_WARMUP: %s vol_est=None at "
                        "uptime=%.0fs (past warmup) — vol engine may "
                        "be stalled, see kb/failures/"
                        "ws-cache-drift-silent-scan-2026-04-24.md",
                        asset, time.time() - _proc_start)
                # Trace row for 15M/hourly — vol engine warmup or divergence.
                # ws-cache-drift-silent-scan-2026-04-24 PM Prevention #3.
                if _pt in (None, "15m", "hourly"):
                    try:
                        _br = vol_est.get("blended_rv") if vol_est else None
                        # Apr 25 2026: enrich rejection_reason so we can
                        # tell warmup (uptime<30s) from feed-blip
                        # (buf_len short post-Coinbase-reconnect) from
                        # real bug (uptime>>warmup AND buf_len adequate).
                        # Pre-enrichment we just saw "vol_est=None" 132×/day
                        # with no way to triage. See ws-cache-drift-silent-
                        # scan-2026-04-24.md PM Prevention #3.
                        try:
                            _buf_len = (
                                len(self._feed.get_buffer(asset))
                                if self._feed else 0)
                        except Exception:
                            _buf_len = -1
                        _uptime_s = (
                            (time.time() - _proc_start)
                            if _proc_start is not None else -1)
                        self._state.insert_evaluated_opportunity(
                            ticker=window["event_ticker"],
                            event_ticker=window["event_ticker"],
                            asset=asset,
                            filter_stage="silent_vol_none",
                            rejection_reason=(
                                f"vol_est=None buf_len={_buf_len} "
                                f"uptime={_uptime_s:.0f}s"
                                if vol_est is None
                                else f"blended_rv={_br} buf_len={_buf_len}"),
                            spot_price=spot,
                            seconds_to_close=seconds_remaining,
                            product_type=_pt or "15m")
                    except Exception:
                        logging.debug(
                            "silent_vol_none trace insert failed",
                            exc_info=True)
                continue

            blended_rv = vol_est["blended_rv"]

            # Extract shadow diagnostics for per-evaluation logging
            # _shadow_diag: fields that match insert_evaluated_opportunity/insert_rejection params
            _ebs_var = vol_est.get("egarch_blend_var")
            # Fallback: if engine didn't compute egarch_blend_var but has constituents, compute here
            if _ebs_var is None:
                _fb_sigma = vol_est.get("egarch_sigma")
                _fb_bw = vol_est.get("egarch_blend_weight")
                _fb_rk = vol_est.get("rk_rv")
                _fb_sf = vol_est.get("seasonal_factor", 1.0)
                if _fb_sigma and _fb_bw and _fb_bw > 0 and _fb_rk and _fb_rk > 0 and _fb_sf:
                    _fb_erv = _fb_sigma * _fb_sf
                    _ebs_var = _fb_bw * (_fb_erv ** 2) + (1 - _fb_bw) * (_fb_rk ** 2)
            # Settlement divergence measurement: 60s trailing avg + multi-exchange
            # These are logged for analysis — do NOT affect probability or sizing.
            _spot_60s_avg = None
            _spot_multi_exchange = None
            if _pt not in ("spx_hourly", "weather"):
                _spot_60s_avg = self._feed.get_price_trailing_avg(asset, 60)
                try:
                    _kraken_price = self._ml.cross_feed.get_prices(asset).get("kraken") \
                        if hasattr(self._ml, "cross_feed") and self._ml.cross_feed else None
                    if _kraken_price is not None and spot is not None:
                        _spot_multi_exchange = round((spot + _kraken_price) / 2, 6)
                        # Phase 1: cache per-asset gap in bps (Kraken − Coinbase).
                        # Read by insert_evaluated_opportunity via _scan_cx_gap_cache.
                        # See kb/concepts/feature-engineering-phase1.md.
                        if spot > 0:
                            self._state._scan_cx_gap_cache[asset] = round(
                                (_kraken_price - spot) / spot * 10000, 4)
                except Exception:
                    pass
            _shadow_diag = {
                "egarch_sigma": vol_est.get("egarch_sigma"),
                "egarch_blend_sigma": math.sqrt(_ebs_var) if _ebs_var and _ebs_var > 0 else None,
                "egarch_blend_weight": vol_est.get("egarch_blend_weight"),
                "mz_r_squared": vol_est.get("mz_r_squared"),
                "shadow_tv_blend_rv": vol_est.get("shadow_tv_blend_rv"),
                "mz_shadow_sigmoid_w": vol_est.get("mz_shadow_sigmoid_w"),
                "mz_baseline_qlike": vol_est.get("mz_baseline_qlike"),
                "mz_qlike": vol_est.get("mz_qlike"),
            }
            # _shadow_extra_base: additional fields for log_opportunity (not in DB insert params)
            # Copied per-market to avoid OFT field bleed between tickers
            _shadow_extra_base = {
                "shadow_tv_weights": vol_est.get("shadow_tv_weights"),
                "mz_sigmoid_improvement": vol_est.get("mz_sigmoid_improvement"),
                "mz_sigmoid_blend_rv": vol_est.get("mz_sigmoid_blend_rv"),
                "egarch_n_updates": vol_est.get("egarch_n_updates"),
                "egarch_ratio_clamped": vol_est.get("egarch_ratio_clamped"),
                # Settlement divergence: logged for analysis, not used for trading
                "spot_60s_avg": round(_spot_60s_avg, 6) if _spot_60s_avg is not None else None,
                "spot_coinbase_kraken_avg": _spot_multi_exchange,
            }

            for mkt in window["markets"]:
                ticker = mkt.get("ticker", "")
                # Phase D (shadow coverage expansion 2026-05-02): _shadow_diag
                # is window-scoped (built at line ~11247) and reused per
                # market. The pre-Phase-D `_calmlp_annotate_async` only
                # mutated cal_mlp_* keys on the success path AND only in
                # one branch — so iterations N+1...K inherited a stale
                # cal_mlp_request_id from iteration N until N+1's annotate
                # ran. Inserts firing BEFORE the annotate (price_out_of_range,
                # floor_raise_shadow, queue snapshots, etc.) carried the
                # prior ticker's uuid. Reset here defensively.
                # See kb/decisions/shadow-coverage-expansion-may01.md.
                for _cmk in [
                    "cal_mlp_request_id", "cal_mlp_skipped_reason",
                    "cal_mlp_p_mean", "cal_mlp_p_std",
                    "cal_mlp_final_lo", "cal_mlp_final_hi",
                    "cal_mlp_train_id",
                ]:
                    _shadow_diag.pop(_cmk, None)
                threshold = self._parse_threshold(mkt)
                if threshold is None:
                    # R1 [P0-1] / R2 [A1]: previously silent. Schema
                    # drift on floor_strike/yes_sub_title could fire
                    # on EVERY market simultaneously → 15M scan
                    # silent with no trace. Dedup per (ticker, reason)
                    # to avoid the PM-001 commit-in-loop / lock
                    # contention pattern. INSERT OR IGNORE alone
                    # bounds row count but still acquires DB lock
                    # every tick.
                    _dk_thr = (ticker, "threshold_unparsable")
                    if _dk_thr not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dk_thr)
                        try:
                            self._state.insert_rejection(
                                ticker, window.get("event_ticker", ""),
                                asset, "threshold_unparsable",
                                None, spot, None, blended_rv, None,
                                seconds_remaining, None,
                                product_type=window.get("product_type"))
                        except Exception:
                            logging.warning(
                                "threshold_unparsable insert_rejection failed",
                                exc_info=True)
                    continue

                # Threshold sanity gate — defensive against upstream data corruption.
                # On 2026-04-13 15:00-15:35 UTC, Kalshi API returned floor_strike values
                # scaled by 10^-1 (XRP) or 10^-4 (BTC/ETH) for 6 crypto 15M markets,
                # causing 2 live trades (XRP -$49.98, BTC -$3.26) to fill on garbage
                # probabilities (model saturated to 0.97). Max |thr/spot - 1| observed
                # in 1,795 historical wins is 1.59% — 0.05 is 3x safety margin.
                # See kb/failures/apr13-threshold-corruption.md.
                #
                # 15M ONLY — hourly/spx_hourly are multi-strike ladders where strikes
                # legitimately span ±5% around spot. Early NBBO price filter (above)
                # already rejects out-of-range hourly strikes. Applying this gate to
                # hourly blocked 319 legit candidates in 2h after Apr 15 deploy.
                if _pt == "15m" and spot > 0 and threshold > 0:
                    _thr_ratio = abs(threshold - spot) / spot
                    if _thr_ratio > 0.05:
                        logging.warning(
                            "THRESHOLD_IMPLAUSIBLE: %s threshold=%.6f spot=%.4f ratio=%.2f%% "
                            "raw_floor_strike=%r yes_sub_title=%r",
                            ticker, threshold, spot, _thr_ratio * 100,
                            mkt.get("floor_strike"), mkt.get("yes_sub_title"))
                        _dedup_key_ti = (ticker, "threshold_implausible")
                        if _dedup_key_ti not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key_ti)
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker=ticker,
                                    event_ticker=window.get("event_ticker", ""),
                                    asset=asset, product_type=_pt,
                                    filter_stage="threshold_implausible",
                                    rejection_reason=f"|thr-spot|/spot={_thr_ratio:.4f} > 0.05",
                                    spot_price=spot, threshold=threshold,
                                )
                            except Exception:
                                logging.debug("threshold_implausible log failed", exc_info=True)
                        continue

                # Phase 2: update per-window spot-path state for 15M (feeds Tier 1 features)
                if _pt in (None, "15m"):
                    self._update_window_state(ticker, spot, threshold)

                # Early NBBO price filter for multi-strike events (SPX: 60-400 markets).
                # Skip probability computation for strikes clearly outside entry range.
                if _pt in ("spx_hourly", "hourly", "weather"):
                    _nbbo_raw = mkt.get("yes_ask_dollars") or mkt.get("yes_ask")
                    if _nbbo_raw is not None:
                        _nbbo = dollars_str_to_cents(_nbbo_raw) if isinstance(_nbbo_raw, str) else int(_nbbo_raw)
                        _pcfg_early = get_market_config(_pt)
                        if _nbbo > 0 and not (_pcfg_early.min_entry_price <= _nbbo <= _pcfg_early.max_entry_price):
                            # R1 [P0-1] / R2 [A1]: previously silent.
                            # SPX has 60-400 strikes per event — most
                            # fall outside entry range and silently
                            # bail. Dedup per (ticker, reason) — see
                            # threshold_unparsable site for rationale.
                            _dk_oor = (ticker, "price_out_of_range_early")
                            if _dk_oor not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dk_oor)
                                try:
                                    self._state.insert_rejection(
                                        ticker,
                                        window.get("event_ticker", ""),
                                        asset, "price_out_of_range_early",
                                        None, spot, threshold,
                                        blended_rv, _nbbo,
                                        seconds_remaining, None,
                                        product_type=_pt)
                                except Exception:
                                    logging.warning(
                                        "price_out_of_range_early insert_rejection failed",
                                        exc_info=True)
                            continue

                # Per-market copy of shadow extras (OFT fields added per-ticker below)
                _shadow_extra = dict(_shadow_extra_base)
                # OFT fields for DB insert — populated after ofa_signals computed
                _oft_db = {}

                scan_stats[asset]["evaluated"] += 1
                self._session_total_scanned += 1

                # Pre-filter: compute probability without market price
                if _pt == "weather" and self._ml and getattr(self._ml, "weather_engine", None):
                    # Weather uses ensemble-based Gaussian model, NOT lognormal ProbabilityEngine
                    _wx_city = asset.replace("_TEMP", "")
                    _wx_info = self._parse_weather_market_info(mkt)
                    _wx_mtype = _wx_info[0] if _wx_info else None
                    _wx_bounds = (_wx_info[1], _wx_info[2]) if (_wx_info and _wx_info[0] == "bracket") else None
                    _shadow_extra["wx_market_type"] = _wx_mtype
                    _wx_prob = self._ml.weather_engine.get_probability(
                        _wx_city, threshold,
                        market_type=_wx_mtype, bracket_bounds=_wx_bounds)
                    if _wx_prob is None:
                        # R1 [P0-1] / R2 [A1]: previously silent.
                        # Dedup per (ticker, reason).
                        _dk_wxp = (ticker, "weather_prob_none")
                        if _dk_wxp not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dk_wxp)
                            try:
                                self._state.insert_rejection(
                                    ticker,
                                    window.get("event_ticker", ""),
                                    asset, "weather_prob_none",
                                    None, spot, threshold,
                                    blended_rv, None,
                                    seconds_remaining, None,
                                    product_type=_pt)
                            except Exception:
                                logging.warning(
                                    "weather_prob_none insert_rejection failed",
                                    exc_info=True)
                        continue
                    # R3: Ensemble quality gate — skip if no ensemble data available
                    if not _wx_prob.get("n_members"):
                        logging.debug("WEATHER_SKIP: %s no ensemble data (n_members=None/0)", ticker)
                        _shadow_extra["wx_ensemble_mean"] = None
                        _shadow_extra["wx_ensemble_std"] = None
                        _shadow_extra["wx_n_members"] = 0
                        _fs = "data_unavailable"
                        _dedup_key_ens = (ticker, _fs)
                        if _dedup_key_ens not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key_ens)
                            _nbbo_val = int(_nbbo) if _nbbo_raw is not None else None
                            self._state.insert_evaluated_opportunity(
                                ticker=ticker, event_ticker=window.get("event_ticker", ""),
                                asset=asset, product_type=_pt, filter_stage=_fs,
                                market_price=_nbbo_val,
                                wx_ensemble_mean=None, wx_ensemble_std=None,
                                wx_n_members=0,
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                            )
                        continue
                    prob_result = {
                        "calibrated_prob": _wx_prob.get("calibrated_prob"),
                        "raw_prob": _wx_prob.get("raw_prob"),
                        "calibration_method": "weather_ensemble",
                        "tradeable": True,  # weather ensemble always tradeable (no z-score gate)
                        "z_score": 0.0,
                    }
                    # Store weather ensemble diagnostics for DB
                    _shadow_extra["wx_ensemble_mean"] = _wx_prob.get("ensemble_mean")
                    _shadow_extra["wx_ensemble_std"] = _wx_prob.get("ensemble_std")
                    _shadow_extra["wx_bias_correction"] = _wx_prob.get("bias_correction")
                    _shadow_extra["wx_n_members"] = _wx_prob.get("n_members")
                    _shadow_extra["wx_hrrr_temp"] = _wx_prob.get("hrrr_temp")
                    _shadow_extra["wx_corrected_mean"] = _wx_prob.get("corrected_mean")
                    logging.info(
                        "WEATHER_PROB: %s thresh=%.1fF ens_mean=%.1fF ens_std=%.2fF prob=%.4f type=%s",
                        ticker, threshold,
                        _wx_prob.get("ensemble_mean") or 0.0,
                        _wx_prob.get("ensemble_std") or 0.0,
                        _wx_prob.get("calibrated_prob") or 0.0,
                        _wx_mtype or "unknown")
                else:
                    prob_result = ProbabilityEngine.compute(
                        spot, threshold, seconds_remaining, blended_rv,
                        asset=asset, product_type=window.get("product_type")
                    )
                cal_prob = prob_result.get("calibrated_prob")
                raw_prob_pre = prob_result.get("raw_prob")
                calibration_method_pre = prob_result.get("calibration_method")
                if not prob_result.get("tradeable"):
                    reason = prob_result.get("reason", "tradeable_false")
                    # Apr 25 2026 (Phase 1 / Prevention #3): write a DB
                    # row for EVERY tradeable=False reason, not just
                    # z_score/refusing. Pre-fix, reasons like 'invalid
                    # inputs' and 'sigma_move is zero' silently continued
                    # — the proximate cause of recurring 15M scan-silence
                    # outages. With every continue writing a row, the
                    # scan-productive watchdog becomes 100% reliable
                    # AND the rejection_reason field tells us exactly
                    # what's going wrong upstream.
                    # R1 [P1-3]: use cheap NBBO from `mkt` rather than
                    # an orderbook fetch on the fail-fast path. The
                    # downstream z_score/refusing branch keeps a richer
                    # log_rejection JSONL with the OB-derived ask.
                    _nbbo_for_row = (
                        mkt.get("yes_ask_dollars") or mkt.get("yes_ask"))
                    try:
                        if isinstance(_nbbo_for_row, str):
                            rej_ask = dollars_str_to_cents(_nbbo_for_row)
                        elif _nbbo_for_row is not None:
                            rej_ask = int(_nbbo_for_row)
                        else:
                            rej_ask = None
                    except Exception:
                        rej_ask = None
                    # R2 [A1]: dedup per (ticker, reason_class) to
                    # avoid commit-in-loop. Use a stable reason CLASS
                    # (the prefix before any dynamic detail) so
                    # different float values for the same root cause
                    # share a single dedup slot.
                    _reason_class = reason.split(" — ")[0].split(" (")[0][:64]
                    _dk_tf1 = (ticker, "tf1:" + _reason_class)
                    if _dk_tf1 not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dk_tf1)
                        try:
                            self._state.insert_rejection(
                                ticker, window["event_ticker"], asset, reason,
                                prob_result.get("z_score"), spot, threshold,
                                blended_rv, rej_ask, seconds_remaining, cal_prob,
                                raw_prob=raw_prob_pre,
                                product_type=window.get("product_type"),
                                **_oft_db, **_shadow_diag)
                        except Exception:
                            logging.warning(
                                "tradeable_false insert_rejection failed",
                                exc_info=True)
                    if "z_score" in reason or "refusing" in reason:
                        rej_data = {
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": reason,
                            "z_score": prob_result.get("z_score"),
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": rej_ask,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": cal_prob,
                            "raw_prob": raw_prob_pre,
                            **_shadow_diag,
                            **_shadow_extra,
                        }
                        self._logger.log_rejection(rej_data)
                        logging.info(
                            f"Rejected opportunity: {ticker} — {reason}")
                    continue

                # Skip if calibrated prob too low to ever produce an edge.
                # Observation-mode products bypass entirely — data collection is the goal.
                _pcfg = get_market_config(window.get("product_type"))
                _min_price = _pcfg.min_entry_price
                min_prob_needed = (_min_price + MIN_EDGE_PCT) / 100.0
                if cal_prob < min_prob_needed and not _pcfg.observation_only:
                    scan_stats[asset]["low_prob"] += 1
                    if window.get("product_type") in ("hourly", "spx_hourly", "weather"):
                        # Volume control: count but don't log (many strikes are low_prob)
                        if _pt == "spx_hourly":
                            _spx_lp_key = "_spx_diag_lowprob_" + window["event_ticker"]
                            _spx_lp_cnt = getattr(self, _spx_lp_key, 0) + 1
                            setattr(self, _spx_lp_key, _spx_lp_cnt)
                            if _spx_lp_cnt == 1:
                                logging.warning(
                                    "SPX_DIAG_LOWPROB: %s cal=%.4f < needed=%.4f (price=%s)",
                                    ticker, cal_prob, min_prob_needed,
                                    mkt.get("yes_ask_dollars") or mkt.get("yes_ask") or "?")
                        continue
                    # Apr 25 2026 (Phase 1 / Prevention #3): write a DB
                    # row for the 15M low_probability path. Pre-fix
                    # this only logged JSONL via log_opportunity, so
                    # the scan-productive watchdog (which counts DB
                    # rows) was blind to a 15M scan stuck in
                    # low_probability — a candidate root cause for the
                    # Apr 25 outage if cal_prob collapsed across all 4
                    # 15M assets simultaneously.
                    _lowprob_reason = (
                        f"cal_prob {cal_prob:.4f} < "
                        f"min_needed {min_prob_needed:.4f}")
                    # R2 [A1]: dedup per ticker — cal_prob value
                    # changes tick-to-tick but the ROOT CAUSE
                    # ("low_probability_15m") is constant.
                    _dk_lp = (ticker, "low_probability_15m")
                    if _dk_lp not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dk_lp)
                        try:
                            self._state.insert_rejection(
                                ticker, window["event_ticker"], asset,
                                "low_probability_15m",
                                None, spot, threshold,
                                blended_rv, best_ask, seconds_remaining,
                                cal_prob, raw_prob=raw_prob_pre,
                                product_type=window.get("product_type"),
                                **_oft_db, **_shadow_diag)
                        except Exception:
                            logging.warning(
                                "low_probability_15m insert_rejection failed",
                                exc_info=True)
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "low_probability",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": _lowprob_reason,
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(cal_prob, 6),
                            "raw_prob": round(raw_prob_pre, 6) if raw_prob_pre is not None else None,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                    except Exception:
                        pass
                    continue

                # SPX diagnostic: market passed low_prob check
                if _pt == "spx_hourly":
                    logging.info("SPX_DIAG_PASS: %s cal=%.4f spot=%.1f thresh=%.1f rv=%.6f stc=%.0f",
                                 ticker, cal_prob, spot, threshold, blended_rv, seconds_remaining)

                # Fetch orderbook (cached, rate-limited).
                # Per-fetch timing — SCAN_OB_FETCH_SLOW fires when one
                # cache-or-REST orderbook fetch exceeds 500ms. Apr 25
                # 01:28: single XRP window took 5.73s; suspect this
                # call is the dominant cost on certain tickers (REST
                # retry, Kalshi rate limit, network).
                _ob_fetch_start = time.perf_counter()
                ob_data, was_fresh = self._get_orderbook_cached(ticker)
                _ob_fetch_dt = time.perf_counter() - _ob_fetch_start
                if _ob_fetch_dt > 0.5:
                    logging.warning(
                        "SCAN_OB_FETCH_SLOW: ticker=%s fresh=%s took %.2fs",
                        ticker, was_fresh, _ob_fetch_dt)
                if was_fresh:
                    ob_fetches_this_tick += 1
                if ob_data is None:
                    # Try NBBO fallback before giving up (prefer *_dollars field)
                    mkt_yes_ask_raw = mkt.get("yes_ask_dollars") or mkt.get("yes_ask")
                    if mkt_yes_ask_raw:
                        if isinstance(mkt_yes_ask_raw, str):
                            mkt_yes_ask = dollars_str_to_cents(mkt_yes_ask_raw)
                        else:
                            mkt_yes_ask = int(mkt_yes_ask_raw)
                    else:
                        mkt_yes_ask = None
                    if mkt_yes_ask and mkt_yes_ask > 0:
                        ob_data = {}  # empty dict so downstream code works
                        logging.info(
                            "Orderbook unavailable for %s, will use market NBBO yes_ask=%d¢",
                            ticker, mkt_yes_ask,
                        )
                    else:
                        scan_stats[asset]["no_orderbook"] += 1
                        # Flag ticker for WS-bypass so next tick uses REST
                        # directly — gives corrupt WS cache a chance to
                        # re-snapshot. Fix #1a from PM.
                        self.flag_ticker_drifted(ticker)
                        # DB rejection row so silent-bail paths leave a trace
                        # (ws-cache-drift-silent-scan-2026-04-24 PM)
                        try:
                            self._state.insert_rejection(
                                ticker, window["event_ticker"], asset,
                                "no_orderbook",
                                prob_result.get("z_score"), spot, threshold,
                                blended_rv, None, seconds_remaining, cal_prob,
                                raw_prob=raw_prob_pre,
                                product_type=window.get("product_type"),
                                **_oft_db, **_shadow_diag)
                        except Exception:
                            logging.debug(
                                "insert_rejection no_orderbook failed",
                                exc_info=True)
                        try:
                            self._logger.log_opportunity({
                                "filter_stage": "no_orderbook",
                                "ticker": ticker,
                                "event_ticker": window["event_ticker"],
                                "asset": asset,
                                "rejection_reason": "orderbook data unavailable and no market NBBO",
                                "spot_price": spot,
                                "threshold": threshold,
                                "volatility": blended_rv,
                                "seconds_to_close": round(seconds_remaining, 1),
                                "calibrated_prob": round(cal_prob, 6),
                                "mkt_yes_ask": mkt_yes_ask,
                                "raw_prob": round(raw_prob_pre, 6) if raw_prob_pre is not None else None,
                                **_shadow_diag,
                                **_shadow_extra,
                            })
                        except Exception:
                            pass
                        continue

                best_ask = self._best_yes_ask_cents(ob_data)
                best_ask_source = "orderbook"
                if best_ask is None:
                    # Fallback: use market's NBBO yes_ask (prefer *_dollars field)
                    mkt_yes_ask_raw = mkt.get("yes_ask_dollars") or mkt.get("yes_ask")
                    if mkt_yes_ask_raw:
                        if isinstance(mkt_yes_ask_raw, str):
                            mkt_yes_ask = dollars_str_to_cents(mkt_yes_ask_raw)
                        else:
                            mkt_yes_ask = int(mkt_yes_ask_raw)
                    else:
                        mkt_yes_ask = None
                    if mkt_yes_ask and mkt_yes_ask > 0:
                        best_ask = mkt_yes_ask
                        best_ask_source = "market_nbbo"
                        logging.info(
                            "Using market NBBO yes_ask=%d¢ for %s (orderbook NO bids empty)",
                            best_ask, ticker,
                        )
                # Read NO ask for pricing analysis (logged to evaluated_opportunities via _shadow_diag)
                _mkt_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                _mkt_no_ask_cents = (dollars_str_to_cents(_mkt_no_ask_raw) if isinstance(_mkt_no_ask_raw, str)
                                     else int(_mkt_no_ask_raw)) if _mkt_no_ask_raw is not None else None
                _shadow_diag["no_ask_cents"] = _mkt_no_ask_cents
                if best_ask is not None:
                    if ticker not in self._ticker_ask_history:
                        self._ticker_ask_history[ticker] = deque(maxlen=300)
                    self._ticker_ask_history[ticker].append((time.time(), best_ask))
                if best_ask is None:
                    scan_stats[asset]["no_best_ask"] += 1
                    # Flag ticker for WS-bypass so next tick uses REST
                    # directly — gives corrupt WS cache a chance to
                    # re-snapshot. Fix #1a from PM.
                    self.flag_ticker_drifted(ticker)
                    # DB rejection row so silent-bail paths leave a trace
                    # (ws-cache-drift-silent-scan-2026-04-24 PM)
                    try:
                        self._state.insert_rejection(
                            ticker, window["event_ticker"], asset,
                            "no_best_ask",
                            prob_result.get("z_score"), spot, threshold,
                            blended_rv, None, seconds_remaining, cal_prob,
                            raw_prob=raw_prob_pre,
                            product_type=window.get("product_type"),
                            **_oft_db, **_shadow_diag)
                    except Exception:
                        logging.debug(
                            "insert_rejection no_best_ask failed",
                            exc_info=True)
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "no_best_ask",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": "no best ask in orderbook or market NBBO",
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(cal_prob, 6),
                            "mkt_yes_ask": mkt.get("yes_ask"),
                            "raw_prob": round(raw_prob_pre, 6) if raw_prob_pre is not None else None,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                    except Exception:
                        pass
                    continue

                # Phase D (shadow coverage expansion 2026-05-02): annotate
                # cal_mlp_request_id on _shadow_diag EARLY — before any
                # downstream insert_evaluated_opportunity / queue snapshot
                # splats _shadow_diag. The pre-Phase-D annotate at the
                # post-`prob_with_market` candidate path only stamped uuids
                # on the candidate row; shadow stages (low_price_shadow,
                # floor_raise_shadow, overnight_lp_shadow, weekend_discount,
                # no_side, etc.) had NULL cal_mlp_request_id and the
                # post-hoc daemon never predicted on them. Stamping here
                # fans the uuid out to every downstream **_shadow_diag
                # splat in this iteration. side="yes" is the iteration's
                # primary side; NO-side rows inherit the same uuid via
                # queue snapshot — the post-hoc daemon dispatches features
                # by the row's stored `side` column, so the uuid is just a
                # "predict me" marker (master plan caveat: v1 may not be
                # calibrated for NO-side; capture anyway).
                # entry_price_cents is documented as ignored by the
                # post-hoc processor (re-derives features from DB row);
                # passed for API stability with the v1.5 signature.
                # See kb/decisions/shadow-coverage-expansion-may01.md.
                #
                # Phase D adversarial review (round 1, MEDIUM-1): gate is
                # `_pt == "15m"` only — strict-equal to the daemon's
                # `WHERE product_type = '15m'` filter at
                # scripts/cal_mlp/post_hoc_processor.py:172. Pre-Phase-D
                # the gate was `_pt in (None, "15m")` to allow legacy
                # null-product-type 15M rows; in current production
                # 15M markets always have product_type="15m" set by
                # discover_active_windows(). Tighter gate prevents
                # stamping cal_mlp_request_id on rows the daemon will
                # never read (orphaned annotations).
                if _pt == "15m":
                    _calmlp_annotate_async(
                        _shadow_diag, raw_prob=raw_prob_pre, ticker=ticker,
                        side="yes", entry_price_cents=best_ask, row_features={},
                        predictor=_calmlp_predictors.get(asset), db_path=DB_PATH,
                    )

                # Diagnostic: log when orderbook and market NBBO disagree
                try:
                    mkt_yes_ask_raw = mkt.get("yes_ask")
                    if mkt_yes_ask_raw and best_ask_source == "orderbook":
                        mkt_nbbo = int(mkt_yes_ask_raw)
                        if mkt_nbbo != best_ask:
                            logging.debug(
                                "NBBO mismatch %s: orderbook=%d¢ market_nbbo=%d¢ (diff=%d¢)",
                                ticker, best_ask, mkt_nbbo, abs(best_ask - mkt_nbbo),
                            )
                except Exception:
                    pass

                # Compute orderbook depth early (used in logging + strategy)
                ask_depth = OrderExecutor._best_ask_depth(ob_data)
                total_depth = OrderExecutor._total_ob_depth(ob_data)
                # Extract YES bid for buy-low-sell-higher and exit-price analysis.
                # Stored in StateManager._scan_bid_cache so all insert_evaluated_opportunity
                # calls within this scan tick automatically pick it up — no need to thread
                # the value through 50+ call sites.
                yes_bid_cents = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                if yes_bid_cents is not None:
                    self._state._scan_bid_cache[ticker] = yes_bid_cents
                # Per-level orderbook ladder snapshot (top 10 each side).
                # Cached as (monotonic_ts, json) so insert_evaluated_opportunity
                # can enforce a freshness gate when auto-filling — stale
                # entries write NULL instead of a misleading old ladder.
                # None if ob_data missing this tick.
                _ob_levels = OrderExecutor._extract_book_levels(ob_data)
                if _ob_levels is not None:
                    self._state._scan_ob_cache[ticker] = (
                        time.monotonic(), _ob_levels)
                # Eviction runs UNCONDITIONALLY (outside the ob_data guard) —
                # otherwise a quiet-market scenario where every ticker stops
                # returning ob_data leaves the cache permanently stale.
                # Same failure class as failure_15m_silence_apr24_second.
                self._state._evict_stale_ob_cache()

                # ── MM fill simulation: check if shadow buy orders would fill ──
                # For hourly tickers with active MM shadow orders, check if the
                # current ask has dropped to/below the shadow buy price.
                if (_pt == "hourly"
                        and self._ml and getattr(self._ml, "hourly_alt_shadow", None)):
                    try:
                        _mm_bid = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                        self._ml.hourly_alt_shadow.check_mm_fills(
                            ticker, best_ask, _mm_bid or 0)
                    except Exception:
                        pass  # Fill check is advisory, don't break scan

                # Record orderbook snapshot for flow tracking
                try:
                    if self._kalshi_oft is not None and ob_data:
                        self._kalshi_oft.record_snapshot(ticker, ob_data, best_ask)
                except Exception:
                    pass

                # Phase 1 feature capture: microstructure + Kalshi flow signals.
                # Populates self._state._scan_ms_cache[ticker] so all
                # insert_evaluated_opportunity calls within this tick auto-fill.
                # See kb/concepts/feature-engineering-phase1.md.
                try:
                    _bid_depth = (OrderExecutor._best_yes_bid_depth(ob_data)
                                  if ob_data else None)
                    _spread = ((best_ask - yes_bid_cents)
                               if (best_ask is not None and yes_bid_cents is not None)
                               else None)
                    _ms: Dict[str, Any] = {
                        "yes_spread_cents": _spread,
                        "bid_depth": _bid_depth,
                    }
                    # Phase F-2 (shadow coverage expansion 2026-05-02):
                    # maker counterfactual snapshot. Reuses _ob_levels JSON
                    # already extracted above, so no extra orderbook fetch.
                    # See kb/decisions/shadow-coverage-expansion-may01.md.
                    _maker = self._compute_maker_counterfactual(
                        best_yes_bid=yes_bid_cents,
                        best_yes_ask=best_ask,
                        ladder_json=_ob_levels,
                    )
                    _ms["maker_price_cents"] = _maker["maker_price_cents"]
                    _ms["maker_depth_at_post"] = _maker["maker_depth_at_post"]
                    if self._kalshi_oft is not None:
                        _flow = self._kalshi_oft.get_signals(ticker)
                        if _flow:
                            _ms["kalshi_flow_imbalance_level"] = _flow.get("imbalance_level")
                            _ms["kalshi_flow_depth_velocity"] = _flow.get("depth_velocity")
                            _drain = _flow.get("depth_drain")
                            _ms["kalshi_flow_depth_drain"] = (
                                1 if _drain else 0 if _drain is False else None)
                    self._state._scan_ms_cache[ticker] = _ms
                except Exception:
                    pass  # Feature capture is advisory — never break scan

                # Log price snapshot for all markets with orderbook data
                try:
                    self._logger.log_scan({
                        "type": "price_snapshot",
                        "ticker": ticker,
                        "asset": asset,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "best_ask": best_ask,
                        "best_ask_source": best_ask_source,
                        "best_ask_depth": ask_depth,
                        "total_ob_depth": total_depth,
                        "convergence_velocity": self._scanner_convergence_velocity(ticker),
                        "calibrated_prob": round(cal_prob, 6),
                    })
                except Exception:
                    pass

                # ── 15M Shadow Engine (pre-filter: all signals) ──
                # Evaluate shadow approaches for ALL 15M signals, not just those
                # passing the price filter.  _seen dedup in shadow engine prevents
                # double-eval if the signal also passes filters and hits the
                # post-filter call below.  Uses cal_prob (pre-temperature/blend)
                # as live_prob approximation — shadow approaches do their own cal.
                if (window.get("product_type") in (None, "15m")
                        and self._ml and getattr(self._ml, "fifteenm_shadow", None)
                        and best_ask is not None and cal_prob is not None):
                    try:
                        _15m_pre_bid = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                        _15m_pre_edge = cal_prob - best_ask / 100.0
                        _15m_pre_fee = calculate_fee(
                            1, best_ask, is_taker=True,
                            fee_mult_taker=get_market_config("15m").fee_multiplier_taker,
                            fee_mult_maker=get_market_config("15m").fee_multiplier_maker)
                        _15m_pre_fee_edge = _15m_pre_edge - _15m_pre_fee / 100.0
                        _15m_pre_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                        _15m_pre_no_ask = (dollars_str_to_cents(_15m_pre_no_ask_raw) if isinstance(_15m_pre_no_ask_raw, str)
                                           else int(_15m_pre_no_ask_raw)) if _15m_pre_no_ask_raw is not None else None
                        self._ml.fifteenm_shadow.evaluate_strike(
                            asset=asset, ticker=ticker,
                            event_ticker=window["event_ticker"],
                            spot_price=spot, threshold=threshold,
                            seconds_to_close=seconds_remaining,
                            market_price=best_ask,
                            best_bid=_15m_pre_bid, best_ask=best_ask,
                            blended_rv=blended_rv,
                            egarch_sigma=vol_est.get("egarch_sigma"),
                            z_score=prob_result.get("z_score", 0.0),
                            live_prob=cal_prob,
                            live_edge=_15m_pre_edge,
                            live_fee_edge=_15m_pre_fee_edge,
                            egarch_blend_weight=_shadow_diag.get("egarch_blend_weight"),
                            fee_adjusted_edge=_15m_pre_fee_edge,
                            no_ask=_15m_pre_no_ask)
                    except Exception:
                        logging.warning("fifteenm_shadow pre-filter evaluate failed", exc_info=True)

                # Filter: ask must be in entry price range
                _pricecfg = get_market_config(window.get("product_type"))
                _entry_floor = _pricecfg.min_entry_price
                _entry_ceil = _pricecfg.max_entry_price
                if not (_entry_floor <= best_ask <= _entry_ceil):
                    scan_stats[asset]["price_out_of_range"] += 1
                    # Compute raw edge for instrumentation (pre-temperature, pre-blend)
                    _por_edge = cal_prob - best_ask / 100.0
                    _por_fee = calculate_fee(
                        1, best_ask, is_taker=True,
                        fee_mult_taker=_pricecfg.fee_multiplier_taker,
                        fee_mult_maker=_pricecfg.fee_multiplier_maker)
                    _por_fee_edge = _por_edge - _por_fee / 100.0
                    _por_z = prob_result.get("z_score")
                    self._recent_opportunities.append({
                        "ticker": ticker, "asset": asset,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "best_ask": best_ask, "edge_bps": round(_por_edge * 10000) if _por_edge else None,
                        "chosen_strategy": None,
                        "rejection_reason": "price_out_of_range",
                        "ts": datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                    })
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "price_out_of_range",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": f"best_ask {best_ask}¢ outside [{_entry_floor}, {MAX_ENTRY_PRICE}]",
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": best_ask,
                            "best_ask_source": best_ask_source,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(cal_prob, 6),
                            "best_ask_depth": ask_depth,
                            "total_ob_depth": total_depth,
                            "convergence_velocity": self._scanner_convergence_velocity(ticker),
                            "raw_prob": round(raw_prob_pre, 6) if raw_prob_pre is not None else None,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                        _dedup_key = (ticker, "price_out_of_range")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "price_out_of_range",
                                rejection_reason=f"best_ask {best_ask}¢ outside range",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=cal_prob,
                                edge=_por_edge,
                                fee_adjusted_edge=_por_fee_edge,
                                z_score=_por_z,
                                vol_regime=vol_est["regime"],
                                breakeven_wr=best_ask / 100.0,
                                ask_depth=ask_depth,
                                best_ask_source=best_ask_source,
                                raw_prob=raw_prob_pre,
                                calibration_method=calibration_method_pre,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                hourly_pre_temp_prob=None, hourly_applied_temp_t=None,
                                hourly_shadow_temp_2_0=None, hourly_shadow_temp_1_0=None,
                                hourly_shadow_temp_2_5=None, hourly_shadow_blend_50=None,
                                hourly_shadow_temp_1_75=None, hourly_shadow_temp_3_0=None,
                                hourly_shadow_blend_20=None, hourly_shadow_blend_30=None,
                                hourly_shadow_blend_60=None, hourly_post_temp_prob=None,
                                **_oft_db, **_shadow_diag)
                    except Exception:
                        logging.warning("insert_evaluated_opportunity failed (price_out_of_range)", exc_info=True)
                    if PRICE_SHADOW_ENABLED and PRICE_SHADOW_FLOOR <= best_ask < _entry_floor:
                        _price_shadow_queue.append({
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "best_ask": best_ask,
                            "spot": spot,
                            "threshold": threshold,
                            "blended_rv": blended_rv,
                            "seconds_remaining": seconds_remaining,
                            "vol_regime": vol_est["regime"],
                            "ask_depth": ask_depth,
                            "best_ask_source": best_ask_source,
                            "product_type": window.get("product_type"),
                            "_shadow_diag": _shadow_diag.copy(),
                            "_oft_db": _oft_db.copy(),
                        })
                    # Overnight LP shadow: queue 50-85c 15M contracts during overnight hours
                    _olp_utc_hour = datetime.datetime.now(timezone.utc).hour
                    if (OVERNIGHT_LP_SHADOW
                            and _pt in (None, "15m")
                            and OVERNIGHT_LP_HOURS_START <= _olp_utc_hour < OVERNIGHT_LP_HOURS_END
                            and OVERNIGHT_LP_MIN_ENTRY_PRICE <= best_ask <= OVERNIGHT_LP_MAX_ENTRY_PRICE
                            and OVERNIGHT_LP_MIN_STC <= seconds_remaining <= OVERNIGHT_LP_MAX_STC):
                        _overnight_lp_queue.append({
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "best_ask": best_ask,
                            "best_bid": mkt.get("yes_bid") or (100 - (mkt.get("no_ask") or 100)),
                            "spot": spot,
                            "threshold": threshold,
                            "blended_rv": blended_rv,
                            "seconds_remaining": seconds_remaining,
                            "vol_regime": vol_est["regime"],
                            "ask_depth": ask_depth,
                            "best_ask_source": best_ask_source,
                            "product_type": window.get("product_type"),
                            "_shadow_diag": _shadow_diag.copy(),
                            "_oft_db": _oft_db.copy(),
                        })
                    # Low-price shadow: queue 20-79c 15M signals for dual-sizing analysis
                    if (LOW_PRICE_SHADOW_ENABLED
                            and _pt in (None, "15m")
                            and LOW_PRICE_SHADOW_MIN_PRICE <= best_ask <= LOW_PRICE_SHADOW_MAX_PRICE
                            and seconds_remaining <= LOW_PRICE_SHADOW_MAX_STC):
                        _low_price_shadow_queue.append({
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "best_ask": best_ask,
                            "spot": spot,
                            "threshold": threshold,
                            "blended_rv": blended_rv,
                            "seconds_remaining": seconds_remaining,
                            "vol_regime": vol_est["regime"],
                            "ask_depth": ask_depth,
                            "best_ask_source": best_ask_source,
                            "product_type": window.get("product_type"),
                            "_shadow_diag": _shadow_diag.copy(),
                            "_oft_db": _oft_db.copy(),
                            "has_prob": False,
                        })
                    # NO-side shadow: read actual NO ask from market NBBO
                    _no_ask_por = None
                    _no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                    if _no_ask_raw is not None:
                        _no_ask_por = dollars_str_to_cents(_no_ask_raw) if isinstance(_no_ask_raw, str) else int(_no_ask_raw)
                    if _no_ask_por is not None and _no_ask_por <= 0:
                        _no_ask_por = None
                    if _no_ask_por is not None and NO_SIDE_MIN_ENTRY_PRICE <= _no_ask_por <= _entry_ceil:
                        _no_side_queue.append({
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "best_ask": best_ask,
                            "no_ask": _no_ask_por,
                            "spot": spot,
                            "threshold": threshold,
                            "blended_rv": blended_rv,
                            "seconds_remaining": seconds_remaining,
                            "vol_regime": vol_est["regime"],
                            "ask_depth": ask_depth,
                            "best_ask_source": best_ask_source,
                            "product_type": window.get("product_type"),
                            "_shadow_diag": _shadow_diag.copy(),
                            "_oft_db": _oft_db.copy(),
                            "_shadow_extra": _shadow_extra.copy(),
                            "final_prob": None,  # needs computation
                            "cal_prob": cal_prob,
                            "raw_prob": raw_prob_pre,
                            "calibration_method": calibration_method_pre,
                            "hourly_pre_temp_prob": None,  # POR path — before temp computation
                            "hourly_applied_temp_t": None,
                            "hourly_post_temp_prob": None,
                        })

                    # DC NO-side shadow: z≥5 means spot is FAR above strike (YES worthless, NO is the bet)
                    # Must run here because price_out_of_range blocks the main DC shadow block downstream.
                    # These tickers have best_ask=0-1c (YES side) but NO side may have real depth.
                    # Uses _por_z (computed at line 6711) — z_score is not defined until later in the loop.
                    if (DECIDED_CONTRACT_SHADOW
                            and _pt in (None, "15m")
                            and _por_z is not None
                            and _por_z >= 5.0
                            and best_ask <= 20
                            and seconds_remaining < DECIDED_CONTRACT_MAX_STC):
                        _no_ask_dc_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                        _no_ask_dc = None
                        if _no_ask_dc_raw is not None:
                            _no_ask_dc = (dollars_str_to_cents(_no_ask_dc_raw)
                                          if isinstance(_no_ask_dc_raw, str)
                                          else int(_no_ask_dc_raw))
                        if _no_ask_dc is not None and _no_ask_dc > 0 and _no_ask_dc <= 93:
                            _dcs_dedup_no = (ticker, "dc_shadow_no_side")
                            if _dcs_dedup_no not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dcs_dedup_no)
                                _no_fee_dc = calculate_fee(1, _no_ask_dc, is_taker=True,
                                                           fee_mult_taker=get_market_config("15m").fee_multiplier_taker,
                                                           fee_mult_maker=get_market_config("15m").fee_multiplier_maker)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset, "dc_shadow_no_side",
                                        rejection_reason="shadow: z={:.1f} no_ask={}c yes_price={}c (NO-side decided, POR path)".format(
                                            _por_z, _no_ask_dc, best_ask),
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=_no_ask_dc,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=1.0 - (best_ask / 100.0),
                                        edge=round((1.0 - best_ask / 100.0) - _no_ask_dc / 100.0, 6),
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=_por_z, vol_regime=vol_est["regime"],
                                        raw_prob=raw_prob_pre,
                                        fee_adjusted_edge=round(
                                            (1.0 - best_ask / 100.0) - _no_ask_dc / 100.0 - _no_fee_dc / 100.0, 6),
                                        product_type=window.get("product_type"),
                                        side="no",
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (dc_shadow_no_side POR)", exc_info=True)

                    continue

                # ── Per-asset price floor (15M only) ─────────────────────────
                # BTC 89c+: 86-88c below taker BE. ETH 75c+ (30-contract cap sub-80c).
                # SOL 80c+. XRP 92c+: PnL-negative at every floor below 90c.
                _asset_floor = MIN_ENTRY_PRICE  # default
                if _pt in (None, "15m"):
                    if asset == "BTC":
                        _asset_floor = BTC_MIN_ENTRY_PRICE
                    elif asset == "ETH":
                        _asset_floor = ETH_MIN_ENTRY_PRICE
                    elif asset == "SOL":
                        _asset_floor = SOL_MIN_ENTRY_PRICE
                    elif asset == "XRP":
                        _asset_floor = XRP_MIN_ENTRY_PRICE
                if _pt in (None, "15m") and best_ask < _asset_floor:
                    # ── LPNE intercept: BTC 80-87c near-expiry ──────────────
                    # Data: BTC 80-87c at STC<=120s = 97.6% WR (42 obs), p=0.031.
                    # Intercept BEFORE floor rejection. BTC ONLY — see LPNE_ASSETS.
                    if (LPNE_ENABLED
                            and not OBSERVATION_MODE
                            and asset in LPNE_ASSETS
                            and LPNE_MIN_PRICE <= best_ask <= LPNE_MAX_PRICE
                            and LPNE_MIN_STC <= seconds_remaining <= LPNE_MAX_STC
                            and cal_prob >= best_ask / 100.0):  # model must believe at least break-even
                        _lpne_dc_overlap = any(
                            c["ticker"] == ticker and c.get("strategy", "").startswith("decided_")
                            for c in candidates)
                        if not _lpne_dc_overlap:
                            _lpne_has_position = any(
                                p["ticker"] == ticker
                                for p in self._state.get_open_positions())
                            if not _lpne_has_position:
                                _lpne_count = sum(1 for c in candidates if c.get("strategy") == "low_price_near_expiry")
                                if _lpne_count < LPNE_MAX_CONCURRENT:
                                    logging.info(
                                        "LPNE_CANDIDATE: %s %s %dx@%dc prob=%.3f stc=%.0fs",
                                        asset, ticker, LPNE_FIXED_CONTRACTS, best_ask,
                                        cal_prob, seconds_remaining)
                                    candidates.append({
                                        "ticker": ticker,
                                        "event_ticker": window["event_ticker"],
                                        "asset": asset,
                                        "product_type": window.get("product_type"),
                                        "spot": spot,
                                        "threshold": threshold,
                                        "seconds_to_close": round(seconds_remaining, 1),
                                        "blended_rv": blended_rv,
                                        "calibrated_prob": round(cal_prob, 6),
                                        "z_score": prob_result.get("z_score"),
                                        "best_yes_ask": best_ask,
                                        "best_ask_source": best_ask_source,
                                        "edge": round(cal_prob - best_ask / 100.0, 6),
                                        "fee_adjusted_edge": round((cal_prob - best_ask / 100.0) - (calculate_fee(1, best_ask, is_taker=True, fee_mult_taker=_pricecfg.fee_multiplier_taker, fee_mult_maker=_pricecfg.fee_multiplier_maker) / 100.0), 6),
                                        "position_size": LPNE_FIXED_CONTRACTS,
                                        "kelly_f": 0.0,
                                        "drawdown_scaler": 1.0,
                                        "vol_regime": vol_est["regime"],
                                        "balance_at_scan": self._get_balance_cached(),
                                        "strategy": "low_price_near_expiry",
                                        "strategy_scores": {"certainty": 1.0, "certainty_detail": "lpne",
                                                            "orderbook": 0.5, "orderbook_detail": "n/a",
                                                            "urgency": 1.0, "urgency_detail": "lpne",
                                                            "composite": 1.0, "reason": "low_price_near_expiry"},
                                        "ob_snapshot": {
                                            "best_ask": best_ask,
                                            "ask_depth": ask_depth,
                                            "total_depth": total_depth,
                                            "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                                            "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                                            "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                                      if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                                        },
                                        "calibrated_prob_raw": round(cal_prob, 6),
                                        "ofa_adjustment": 0.0,
                                        "ofa_confidence": "none",
                                        "raw_prob": raw_prob_pre,
                                    })
                                    _lpne_dedup = (ticker, "low_price_near_expiry")
                                    if _lpne_dedup not in self._eval_opp_seen:
                                        self._eval_opp_seen.add(_lpne_dedup)
                                        try:
                                            self._state.insert_evaluated_opportunity(
                                                ticker, window["event_ticker"], asset,
                                                "low_price_near_expiry",
                                                spot_price=spot, threshold=threshold,
                                                volatility=blended_rv, market_price=best_ask,
                                                seconds_to_close=seconds_remaining,
                                                calibrated_prob=final_prob,
                                                edge=cal_prob - best_ask / 100.0,
                                                z_score=prob_result.get("z_score"),
                                                vol_regime=vol_est["regime"],
                                                raw_prob=raw_prob_pre,
                                                calibration_method=calibration_method_pre,
                                                fee_adjusted_edge=round((cal_prob - best_ask / 100.0) - (calculate_fee(1, best_ask, is_taker=True, fee_mult_taker=_pricecfg.fee_multiplier_taker, fee_mult_maker=_pricecfg.fee_multiplier_maker) / 100.0), 6),
                                                breakeven_wr=best_ask / 100.0,
                                                ask_depth=ask_depth,
                                                best_ask_source=best_ask_source,
                                                position_size=LPNE_FIXED_CONTRACTS,
                                                kelly_f=0.0,
                                                drawdown_scaler=1.0,
                                                strategy="low_price_near_expiry",
                                                product_type=window.get("product_type"),
                                                **_oft_db, **_shadow_diag)
                                        except Exception:
                                            logging.warning("insert_evaluated_opportunity failed (lpne)", exc_info=True)
                                    continue  # Skip floor rejection — this is now an LPNE candidate

                    _frs_edge = cal_prob - best_ask / 100.0
                    _frs_fee = calculate_fee(
                        1, best_ask, is_taker=True,
                        fee_mult_taker=_pricecfg.fee_multiplier_taker,
                        fee_mult_maker=_pricecfg.fee_multiplier_maker)
                    _frs_fee_edge = _frs_edge - _frs_fee / 100.0
                    # Tag aggressive-floor shadow variants for forward validation
                    _frs_stage = "floor_raise_shadow"
                    if asset == "ETH" and best_ask >= 70:
                        _frs_stage = "eth_low_floor_shadow"
                    _dedup_key = (ticker, _frs_stage)
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset,
                            _frs_stage,
                            rejection_reason=f"{asset} floor {_asset_floor}c (global {MIN_ENTRY_PRICE}c), ask={best_ask}c",
                            spot_price=spot, threshold=threshold,
                            volatility=blended_rv, market_price=best_ask,
                            seconds_to_close=seconds_remaining,
                            calibrated_prob=cal_prob,
                            edge=_frs_edge,
                            fee_adjusted_edge=_frs_fee_edge,
                            z_score=prob_result.get("z_score"),
                            vol_regime=vol_est["regime"],
                            breakeven_wr=best_ask / 100.0,
                            ask_depth=ask_depth,
                            best_ask_source=best_ask_source,
                            raw_prob=raw_prob_pre,
                            calibration_method=calibration_method_pre,
                            product_type=window.get("product_type"),
                            **_oft_db, **_shadow_diag)
                    continue

                # Re-run probability with market price for sanity check
                if _pt == "weather":
                    # Weather: ensemble model doesn't use market price; skip z-score sanity check
                    prob_with_market = prob_result.copy()
                    prob_with_market["tradeable"] = True
                    prob_with_market["z_score"] = 0.0
                else:
                    prob_with_market = ProbabilityEngine.compute(
                        spot, threshold, seconds_remaining, blended_rv,
                        market_price_cents=best_ask,
                        asset=asset, product_type=window.get("product_type")
                    )
                if not prob_with_market.get("tradeable"):
                    reason = prob_with_market.get(
                        "reason", "tradeable_false")
                    # Apr 25 2026 (Phase 1 / Prevention #3): always write
                    # a DB row regardless of reason. R2 [A1]: dedup per
                    # (ticker, reason_class) to avoid commit-in-loop.
                    _reason_class2 = reason.split(" — ")[0].split(" (")[0][:64]
                    _dk_tf2 = (ticker, "tf2:" + _reason_class2)
                    if _dk_tf2 not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dk_tf2)
                        try:
                            # Phase D (shadow coverage expansion 2026-05-02):
                            # this is the ONLY insert_rejection that fires
                            # AFTER the new early annotate site. Strip
                            # cal_mlp_* keys so the splat doesn't TypeError
                            # against insert_rejection's signature (which
                            # never accepted cal_mlp_* per the
                            # _SHADOW_DIAG_KEYS startup assertion at
                            # line ~10254).
                            self._state.insert_rejection(
                                ticker, window["event_ticker"], asset, reason,
                                prob_with_market.get("z_score"), spot, threshold,
                                blended_rv, best_ask, seconds_remaining,
                                prob_with_market.get("calibrated_prob"),
                                raw_prob=prob_with_market.get("raw_prob"),
                                product_type=window.get("product_type"),
                                **_oft_db,
                                **{k: v for k, v in _shadow_diag.items()
                                   if not k.startswith("cal_mlp_")})
                        except Exception:
                            logging.warning(
                                "tradeable_false (with_market) insert_rejection failed",
                                exc_info=True)
                    if "z_score" in reason or "refusing" in reason:
                        rej_data = {
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": reason,
                            "z_score": prob_with_market.get("z_score"),
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": best_ask,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": prob_with_market.get("calibrated_prob"),
                            "raw_prob": prob_with_market.get("raw_prob"),
                            **_shadow_diag,
                            **_shadow_extra,
                        }
                        self._logger.log_rejection(rej_data)
                        logging.info(
                            f"Rejected opportunity: {ticker} — {reason}")
                    continue

                final_prob = prob_with_market["calibrated_prob"]
                z_score = prob_with_market["z_score"]
                raw_prob = prob_with_market.get("raw_prob")
                calibration_method = prob_with_market.get("calibration_method")

                # cal_mlp_request_id annotation moved EARLIER in the
                # iteration (Phase D shadow coverage expansion 2026-05-02)
                # so shadow-stage inserts/queue snapshots that fire BEFORE
                # this point get cal_mlp_request_id stamped via _shadow_diag
                # splat. See the new annotate site after no_best_ask, plus
                # kb/decisions/shadow-coverage-expansion-may01.md.

                # ── Temperature scaling (Layer 1) ──────────────
                _hourly_pre_temp_prob = None
                _tempcfg = get_market_config(window.get("product_type"))
                _temp_t = _tempcfg.temperature_t if _tempcfg.temperature_enabled else None
                _configured_temp_t = _temp_t  # record configured T for instrumentation (before CalEngine override)
                # T=1.0 is identity — skip scaling
                if _temp_t is not None and _temp_t == 1.0:
                    _temp_t = None
                # Skip temperature if registered engine is active (already calibrated)
                _reg_engine_t = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine_t is not None and _reg_engine_t.is_learned_method_active():
                    _temp_t = None
                    _hourly_pre_temp_prob = final_prob  # still record for shadow instrumentation
                if _temp_t is not None:
                    _hourly_pre_temp_prob = final_prob
                    _p = max(0.001, min(0.999, final_prob))
                    _z = math.log(_p / (1.0 - _p))
                    _z_scaled = _z / _temp_t
                    final_prob = 1.0 / (1.0 + math.exp(-_z_scaled))

                # ── Shadow temperature + blend instrumentation (hourly + SPX) ──
                _hourly_shadow_temp_2_0 = None
                _hourly_shadow_temp_1_0 = None
                _hourly_shadow_temp_2_5 = None
                _hourly_shadow_temp_1_75 = None
                _hourly_shadow_temp_3_0 = None
                _hourly_shadow_blend_50 = None
                _hourly_shadow_blend_20 = None
                _hourly_shadow_blend_30 = None
                _hourly_shadow_blend_60 = None
                _hourly_post_temp_prob = None

                _shadow_base = _hourly_pre_temp_prob
                if _shadow_base is None and _pt == "spx_hourly":
                    _shadow_base = final_prob
                    _hourly_pre_temp_prob = final_prob
                    _temp_t = 1.0

                if _shadow_base is not None:
                    _sp = max(0.001, min(0.999, _shadow_base))
                    _sz = math.log(_sp / (1.0 - _sp))

                    # Temperature shadows (pre-blend)
                    _hourly_shadow_temp_2_0 = 1.0 / (1.0 + math.exp(-_sz / 2.0))
                    _hourly_shadow_temp_2_5 = 1.0 / (1.0 + math.exp(-_sz / 2.5))
                    _hourly_shadow_temp_1_75 = 1.0 / (1.0 + math.exp(-_sz / 1.75))
                    _hourly_shadow_temp_3_0 = 1.0 / (1.0 + math.exp(-_sz / 3.0))
                    if _pt == "spx_hourly":
                        _hourly_shadow_temp_1_0 = 1.0 / (1.0 + math.exp(-_sz / 1.5))
                    else:
                        _hourly_shadow_temp_1_0 = _shadow_base

                    # Post-temp prob: tempered value before OFA and blend
                    # For offline analysis: (1-W) * post_temp + W * (mkt/100) = any blend
                    _hourly_post_temp_prob = final_prob

                    # Blend shadows: full final = liveT + shadowW
                    # Uses final_prob (tempered, pre-OFA) — isolates T×W effect
                    if best_ask < ENDGAME_BLEND_PRICE:
                        _mkt_p = best_ask / 100.0
                        _hourly_shadow_blend_20 = 0.80 * final_prob + 0.20 * _mkt_p
                        _hourly_shadow_blend_30 = 0.70 * final_prob + 0.30 * _mkt_p
                        _hourly_shadow_blend_50 = 0.50 * final_prob + 0.50 * _mkt_p
                        _hourly_shadow_blend_60 = 0.40 * final_prob + 0.60 * _mkt_p

                # Order flow adjustment
                ofa_signals = None
                ofa_adjustment = 0.0
                if self._order_flow is not None:
                    try:
                        ofa_signals = self._order_flow.get_signals(asset, ticker=ticker)
                        ofa_adjustment = ofa_signals["prob_adjustment"]
                    except Exception:
                        logging.debug("OrderFlowEngine.get_signals failed", exc_info=True)
                calibrated_prob_raw = final_prob
                # Always compute dynamic cap for counterfactual logging
                _dyn_cap = ProbabilityEngine._dynamic_cap(seconds_remaining, product_type=window.get("product_type"))
                _reg_engine_c = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine_c is not None and _reg_engine_c.is_learned_method_active():
                    _active_cal = _reg_engine_c
                elif get_market_config(_pt).cal_eligible:
                    _active_cal = _CALIBRATION_ENGINE
                else:
                    _active_cal = None
                if _active_cal is not None and _active_cal.is_learned_method_active():
                    # Learned method: no dynamic cap, use safety ceiling only
                    final_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, final_prob + ofa_adjustment))
                else:
                    final_prob = max(0.01, min(_dyn_cap, final_prob + ofa_adjustment))
                # Counterfactual: calibrated prob with dynamic cap applied
                # (after temp promotion, CF5 "old_cal_system" has the full Beta Cal + blend counterfactual)
                _old_system_prob = max(0.01, min(_dyn_cap, calibrated_prob_raw + ofa_adjustment))
                if best_ask < ENDGAME_BLEND_PRICE:
                    _mkt = best_ask / 100.0
                    _old_system_prob = (1.0 - MARKET_BLEND_W) * _old_system_prob + MARKET_BLEND_W * _mkt

                # ── Market-price blending ──────────────────────────────────
                # For mid-range prices, blend model with market to temper overconfidence.
                # Skip blending for endgame (≥96c) where dynamic cap provides the edge.
                _mcfg = get_market_config(window.get("product_type"))
                _effective_blend_w = _mcfg.market_blend_w
                if best_ask < ENDGAME_BLEND_PRICE:
                    market_implied_prob = best_ask / 100.0
                    final_prob = (1.0 - _effective_blend_w) * final_prob + _effective_blend_w * market_implied_prob

                edge = final_prob - best_ask / 100.0

                # Fee-adjusted edge: subtract taker fee per contract.
                # 15M/SPX/weather: conservative 1-contract fee (more contracts = lower per-unit).
                # Hourly: use actual 10-contract batch fee ÷ 10, because fixed sizing means
                # the 1-contract ceiling inflation (ceil(1.75)=2c vs 18c/10=1.8c) kills
                # every sub-60c signal that the observation data showed is profitable.
                if _pt == "hourly":
                    _hourly_batch_fee = calculate_fee(HOURLY_FIXED_CONTRACTS, best_ask, is_taker=True,
                                                      fee_mult_taker=_mcfg.fee_multiplier_taker,
                                                      fee_mult_maker=_mcfg.fee_multiplier_maker)
                    est_fee_1c = _hourly_batch_fee / HOURLY_FIXED_CONTRACTS
                else:
                    est_fee_1c = calculate_fee(1, best_ask, is_taker=True,
                                               fee_mult_taker=_mcfg.fee_multiplier_taker,
                                               fee_mult_maker=_mcfg.fee_multiplier_maker)
                fee_adjusted_edge = edge - est_fee_1c / 100.0

                # ── Weather NO-side shadow edge ──
                if _pt == "weather":
                    _no_prob = 1.0 - final_prob
                    # NO ask from market NBBO
                    _wx_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                    _wx_no_ask = (dollars_str_to_cents(_wx_no_ask_raw) if isinstance(_wx_no_ask_raw, str)
                                  else int(_wx_no_ask_raw)) if _wx_no_ask_raw is not None else None
                    if _wx_no_ask is not None and _wx_no_ask <= 0:
                        _wx_no_ask = None
                    if _wx_no_ask is not None:
                        _no_fee = calculate_fee(1, _wx_no_ask, is_taker=True,
                                                fee_mult_taker=_mcfg.fee_multiplier_taker,
                                                fee_mult_maker=_mcfg.fee_multiplier_maker)
                        _shadow_extra["wx_no_side_edge"] = round(
                            _no_prob - _wx_no_ask / 100.0 - _no_fee / 100.0, 6)

                # ── NO-side shadow queue (all markets that reach edge computation) ──
                # NO ask from market NBBO
                _no_ask_eq_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                _no_ask_eq = (dollars_str_to_cents(_no_ask_eq_raw) if isinstance(_no_ask_eq_raw, str)
                              else int(_no_ask_eq_raw)) if _no_ask_eq_raw is not None else None
                if _no_ask_eq is not None and _no_ask_eq <= 0:
                    _no_ask_eq = None
                if _no_ask_eq is not None:
                    _no_side_queue.append({
                        "ticker": ticker,
                        "event_ticker": window["event_ticker"],
                        "asset": asset,
                        "best_ask": best_ask,
                        "no_ask": _no_ask_eq,
                        "spot": spot,
                        "threshold": threshold,
                        "blended_rv": blended_rv,
                        "seconds_remaining": seconds_remaining,
                        "vol_regime": vol_est["regime"],
                        "ask_depth": ask_depth,
                        "best_ask_source": best_ask_source,
                        "product_type": window.get("product_type"),
                        # Phase D (shadow coverage expansion 2026-05-02):
                        # PROPAGATE cal_mlp_request_id to NO-side shadow rows
                        # so the post-hoc daemon predicts on them too. The
                        # pre-Phase-D R-p7-deploy-r2#MED1 strip was the
                        # opposite design (shadow rows kept raw); master
                        # plan now requires shadow coverage. NO-side gets
                        # the iteration's YES uuid; daemon dispatches per
                        # row's stored `side` column.
                        "_shadow_diag": _shadow_diag.copy(),
                        "_oft_db": _oft_db.copy(),
                        "_shadow_extra": _shadow_extra.copy(),
                        "final_prob": final_prob,  # already computed (temp+blend+cap)
                        "cal_prob": None,  # not needed — final_prob available
                        "raw_prob": raw_prob,
                        "calibration_method": calibration_method,
                        "hourly_pre_temp_prob": _hourly_pre_temp_prob,
                        "hourly_applied_temp_t": _configured_temp_t,
                        "hourly_post_temp_prob": _hourly_post_temp_prob,
                    })

                # ── Augment _shadow_diag with Kalshi OFT fields ──
                if ofa_signals:
                    # Kalshi-specific signals are nested under signals.kalshi_orderbook
                    _koft = ofa_signals.get("signals", {}).get("kalshi_orderbook", {})
                    _shadow_extra["oft_imbalance_ratio"] = _koft.get("imbalance_ratio")
                    _shadow_extra["oft_imbalance_level"] = _koft.get("imbalance_level")
                    _shadow_extra["oft_prob_adjustment"] = _koft.get("prob_adjustment")
                    _shadow_extra["oft_confidence"] = _koft.get("confidence")
                    _shadow_extra["oft_n_snapshots"] = _koft.get("n_snapshots")
                    _shadow_extra["oft_depth_velocity"] = _koft.get("depth_velocity")
                    # OFT fields for DB persistence
                    _oft_db = {
                        "oft_prob_adjustment": _koft.get("prob_adjustment"),
                        "oft_imbalance_ratio": _koft.get("imbalance_ratio"),
                        "oft_n_snapshots": _koft.get("n_snapshots"),
                    }
                    _shadow_extra["oft_ask_velocity"] = _koft.get("ask_velocity")

                # ── Counterfactual analysis: what would each shadow feature produce? ──
                _cf = {}

                # CF1: EGARCH blend ↔ RV-only counterfactual (bidirectional)
                if EGARCH_BLEND_SHADOW_MODE:
                    # Shadow: EGARCH blend not live, show what it would do
                    _cf_ebs = _shadow_diag.get("egarch_blend_sigma")
                    if _cf_ebs and _cf_ebs > 0:
                        _cf_prob = ProbabilityEngine.counterfactual_prob(
                            spot, threshold, seconds_remaining, _cf_ebs, asset, product_type=_pt)
                        if _cf_prob is not None:
                            _cf_edge = _cf_prob - best_ask / 100.0
                            _cf_fee_edge = _cf_edge - est_fee_1c / 100.0
                            _cf["egarch_blend"] = {
                                "prob": _cf_prob, "edge": round(_cf_edge, 6),
                                "fee_edge": round(_cf_fee_edge, 6),
                                "would_trade": _cf_fee_edge >= MIN_EDGE_PCT / 100.0,
                            }
                else:
                    # Promoted: EGARCH blend IS live, show what RV-only would do
                    _cf_rvo = vol_est.get("rv_only_blended")
                    if _cf_rvo and _cf_rvo > 0:
                        _cf_prob = ProbabilityEngine.counterfactual_prob(
                            spot, threshold, seconds_remaining, _cf_rvo, asset, product_type=_pt)
                        if _cf_prob is not None:
                            _cf_edge = _cf_prob - best_ask / 100.0
                            _cf_fee_edge = _cf_edge - est_fee_1c / 100.0
                            _cf["rv_only"] = {
                                "prob": _cf_prob, "edge": round(_cf_edge, 6),
                                "fee_edge": round(_cf_fee_edge, 6),
                                "would_trade": _cf_fee_edge >= MIN_EDGE_PCT / 100.0,
                            }

                # CF2: TV-RK ↔ fixed-RK counterfactual (bidirectional)
                _cf_tv = _shadow_diag.get("shadow_tv_blend_rv")
                if _cf_tv and _cf_tv > 0:
                    _cf_prob = ProbabilityEngine.counterfactual_prob(
                        spot, threshold, seconds_remaining, _cf_tv, asset, product_type=_pt)
                    if _cf_prob is not None:
                        _cf_edge = _cf_prob - best_ask / 100.0
                        _cf_fee_edge = _cf_edge - est_fee_1c / 100.0
                        _cf_key = "tv_rk" if RK_TV_SHADOW_MODE else "fixed_rk"
                        _cf[_cf_key] = {
                            "prob": _cf_prob, "edge": round(_cf_edge, 6),
                            "fee_edge": round(_cf_fee_edge, 6),
                            "would_trade": _cf_fee_edge >= MIN_EDGE_PCT / 100.0,
                        }

                # CF3: Sigmoid QLIKE blend as primary
                _cf_sig = _shadow_extra.get("mz_sigmoid_blend_rv")
                if _cf_sig and _cf_sig > 0:
                    _cf_prob = ProbabilityEngine.counterfactual_prob(
                        spot, threshold, seconds_remaining, _cf_sig, asset, product_type=_pt)
                    if _cf_prob is not None:
                        _cf_edge = _cf_prob - best_ask / 100.0
                        _cf_fee_edge = _cf_edge - est_fee_1c / 100.0
                        _cf["sigmoid_qlike"] = {
                            "prob": _cf_prob, "edge": round(_cf_edge, 6),
                            "fee_edge": round(_cf_fee_edge, 6),
                            "would_trade": _cf_fee_edge >= MIN_EDGE_PCT / 100.0,
                        }

                # CF4: Kalshi OFT adjusted prob
                if ofa_signals and KALSHI_OFT_SHADOW_MODE:
                    _koft_cf = ofa_signals.get("signals", {}).get("kalshi_orderbook", {})
                    _koft_adj = _koft_cf.get("prob_adjustment", 0)
                    if _koft_adj != 0:
                        _cf["kalshi_oft"] = {
                            "prob_adjustment": round(_koft_adj, 6),
                            "adj_prob": round(final_prob + _koft_adj, 6),
                            "imbalance_ratio": _koft_cf.get("imbalance_ratio"),
                            "imbalance_level": _koft_cf.get("imbalance_level"),
                            "depth_velocity": _koft_cf.get("depth_velocity"),
                            "ask_velocity": _koft_cf.get("ask_velocity"),
                            "confidence": _koft_cf.get("confidence"),
                            "n_snapshots": _koft_cf.get("n_snapshots"),
                        }

                # CF5: Old system counterfactual (Beta Cal + 50% market blend)
                if not SHADOW_CAL_PIPELINE and _CALIBRATION_ENGINE is not None and _CALIBRATION_ENGINE._beta_trained:
                    try:
                        _cf5_cal = _CALIBRATION_ENGINE._beta_cal_predict(raw_prob)
                        _cf5_cal = min(_cf5_cal, _dyn_cap)
                        _cf5_cal = _CALIBRATION_ENGINE._apply_uncertainty_shrinkage(_cf5_cal)
                        _cf5_cal = max(0.001, min(NUMERICAL_SAFETY_CEILING, _cf5_cal))
                        _cf5_cal = max(0.01, min(NUMERICAL_SAFETY_CEILING, _cf5_cal + ofa_adjustment))
                        if best_ask < ENDGAME_BLEND_PRICE:
                            _cf5_cal = 0.50 * _cf5_cal + 0.50 * (best_ask / 100.0)
                        _cf5_edge = _cf5_cal - best_ask / 100.0
                        _cf5_fee_edge = _cf5_edge - est_fee_1c / 100.0
                        _cf["old_cal_system"] = {
                            "prob": round(_cf5_cal, 6),
                            "edge": round(_cf5_edge, 6),
                            "fee_edge": round(_cf5_fee_edge, 6),
                            "would_trade": _cf5_fee_edge >= MIN_EDGE_PCT / 100.0,
                        }
                    except Exception:
                        pass
                elif SHADOW_CAL_PIPELINE and _CALIBRATION_ENGINE is not None:
                    _cf_cal = _CALIBRATION_ENGINE.shadow_calibration_pipeline(
                        raw_prob, best_ask, seconds_remaining, ofa_adjustment)
                    if _cf_cal is not None:
                        _cf["cal_pipeline"] = _cf_cal

                _cf_json = json.dumps(_cf) if _cf else None

                # Log divergences: cases where a shadow feature disagrees with production
                _live_would_trade = (fee_adjusted_edge >= MIN_EDGE_PCT / 100.0)
                for _cf_name, _cf_data in _cf.items():
                    _shadow_would = _cf_data.get("would_trade")
                    if _shadow_would is not None and _shadow_would != _live_would_trade:
                        logging.info(
                            "COUNTERFACTUAL DIVERGENCE %s %s: live=%s shadow=%s "
                            "live_edge=%.4f shadow_edge=%.4f",
                            ticker, _cf_name, _live_would_trade, _shadow_would,
                            fee_adjusted_edge, _cf_data.get("fee_edge", 0),
                        )

                # Log shadow calibration pipeline summary every 5 minutes per asset
                if SHADOW_CAL_PIPELINE and "cal_pipeline" in _cf:
                    try:
                        _cp = _cf["cal_pipeline"]
                        if now - self._shadow_cal_last_log.get(asset, 0) >= 300:
                            logging.info(
                                "shadow_cal_pipeline %s: prob=%.4f edge=%.4f fee_edge=%.4f "
                                "would_trade=%s temp=%.3f temp_brier=%.4f "
                                "prod_prob=%.4f prod_edge=%.4f blend_w=%.2f",
                                ticker, _cp["prob"], _cp["edge"], _cp["fee_edge"],
                                _cp["would_trade"], _cp.get("temperature") or 0,
                                _cp.get("temperature_brier") or 0,
                                final_prob, fee_adjusted_edge, MARKET_BLEND_W)
                            self._shadow_cal_last_log[asset] = now
                    except Exception:
                        pass

                # ── DC Shadow Variants (edge-independent) ─────────────────
                # These evaluate BEFORE the edge gate so they see all signals,
                # not just edge-rejected ones. Targets where z-score implies
                # near-certain outcome but price/tier rules exclude from live DC.
                if (DECIDED_CONTRACT_SHADOW
                        and _pt in (None, "15m")
                        and z_score is not None
                        and seconds_remaining < DECIDED_CONTRACT_MAX_STC):

                    def _dc_shadow_insert_pre(stage, rej_detail, **kwargs):
                        _dcs_dedup = (ticker, stage)
                        if _dcs_dedup not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dcs_dedup)
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset, stage,
                                    rejection_reason=rej_detail,
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv,
                                    market_price=kwargs.get("market_price", best_ask),
                                    seconds_to_close=seconds_remaining,
                                    calibrated_prob=kwargs.get("calibrated_prob", final_prob),
                                    edge=kwargs.get("edge", edge),
                                    ofa_adjustment=ofa_adjustment,
                                    z_score=z_score,
                                    vol_regime=vol_est["regime"],
                                    raw_prob=raw_prob,
                                    fee_adjusted_edge=kwargs.get("fee_adjusted_edge", fee_adjusted_edge),
                                    product_type=window.get("product_type"),
                                    side=kwargs.get("side"),
                                    **_shadow_diag)
                            except Exception:
                                logging.warning("insert_evaluated_opportunity failed (%s)", stage, exc_info=True)

                    # T1B at 93-94c (live T1B fires at 95c+, this captures 93-94c)
                    if (DECIDED_CONTRACT_Z_T1 < z_score <= DECIDED_CONTRACT_Z_T1B
                            and 93 <= best_ask < DECIDED_CONTRACT_T1B_MIN_PRICE):
                        _dc_shadow_insert_pre("dc_shadow_t1b_93c",
                                              "shadow: z={:.1f} price={}c (T1B 93-94c expansion)".format(z_score, best_ask))

                    # T2 price floor 90c for BTC/ETH/SOL (live T2 requires 93c+)
                    if (z_score <= DECIDED_CONTRACT_Z_T2
                            and 90 <= best_ask < DECIDED_CONTRACT_MIN_PRICE
                            and asset in ("BTC", "ETH", "SOL")):
                        _dc_shadow_insert_pre("dc_shadow_t2_90c",
                                              "shadow: z={:.1f} price={}c asset={} (T2 90c floor)".format(z_score, best_ask, asset))

                    # T2 price floor 90c for XRP only
                    if (z_score <= DECIDED_CONTRACT_Z_T2
                            and 90 <= best_ask < DECIDED_CONTRACT_MIN_PRICE
                            and asset == "XRP"):
                        _dc_shadow_insert_pre("dc_shadow_t2_90c_xrp",
                                              "shadow: z={:.1f} price={}c (T2 90c XRP)".format(z_score, best_ask))

                    # NO-side decided (z≥5 → YES nearly worthless, NO is the bet)
                    if z_score >= 5.0 and best_ask <= 20:
                        _no_ask_dc_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                        _no_ask_dc = None
                        if _no_ask_dc_raw is not None:
                            _no_ask_dc = (dollars_str_to_cents(_no_ask_dc_raw)
                                          if isinstance(_no_ask_dc_raw, str)
                                          else int(_no_ask_dc_raw))
                        if _no_ask_dc is not None and _no_ask_dc > 0 and _no_ask_dc <= 93:
                            _no_fee = calculate_fee(1, _no_ask_dc, is_taker=True,
                                                    fee_mult_taker=get_market_config("15m").fee_multiplier_taker,
                                                    fee_mult_maker=get_market_config("15m").fee_multiplier_maker)
                            _dc_shadow_insert_pre("dc_shadow_no_side",
                                                  "shadow: z={:.1f} no_ask={}c yes_price={}c fee={}c (NO-side decided)".format(
                                                      z_score, _no_ask_dc, best_ask, _no_fee),
                                                  market_price=_no_ask_dc,
                                                  calibrated_prob=1.0 - (best_ask / 100.0),
                                                  edge=round((1.0 - best_ask / 100.0) - _no_ask_dc / 100.0, 6),
                                                  fee_adjusted_edge=round(
                                                      (1.0 - best_ask / 100.0) - _no_ask_dc / 100.0 - _no_fee / 100.0, 6),
                                                  side="no")

                # Filter: fee-adjusted edge must meet price-dependent minimum
                if _pt == "weather":
                    _min_edge = WEATHER_MIN_EDGE_PCT
                elif _pt == "hourly":
                    _min_edge = HOURLY_MIN_EDGE_PCT
                else:
                    _min_edge = get_min_edge(best_ask)
                    if asset == "SOL":
                        _min_edge = max(_min_edge, SOL_MIN_EDGE)
                # SOL high-edge shadow: log but don't block (5%+ band is 80% WR, PnL-negative)
                _sol_high_edge_shadow = (asset == "SOL" and fee_adjusted_edge > SOL_HIGH_EDGE_SHADOW
                                         and _pt in (None, "15m"))
                if fee_adjusted_edge < _min_edge:
                    # ── Terminal Momentum intercept ──────────────────────────
                    # Before rejecting as insufficient_edge, check if this contract
                    # qualifies for the terminal momentum strategy: extreme price,
                    # high model confidence, final minutes before expiry.
                    _tm_intercepted = False
                    # R-p7-deploy-r10 Round-2 H1: init at outer scope. The
                    # nested-block init (deep inside TM eligibility chain)
                    # caused UnboundLocalError on the dominant path: any
                    # insufficient-edge candidate that DIDN'T match TM
                    # eligibility (price not in {96,98,99}, etc.) reached
                    # the read site without the local being assigned.
                    _tm96_gate_blocked_trade = False
                    if (TERMINAL_MOMENTUM_ENABLED
                            and not OBSERVATION_MODE
                            and _pt in (None, "15m")
                            and best_ask in TM_PRICE_SET
                            and final_prob >= TM_MIN_PROB
                            and TM_MIN_STC <= seconds_remaining <= TM_MAX_STC):
                        # Check DC overlap: skip if ticker already claimed by DC
                        _tm_dc_overlap = any(c["ticker"] == ticker and c.get("strategy", "").startswith("decided_")
                                             for c in candidates)
                        if not _tm_dc_overlap:
                            # Check position overlap: skip if we already hold TM at THIS price
                            # Stacking at different prices is allowed — rising prices = confirmation signal.
                            # Data: 40/40 stackable tickers settled YES, 0/4 losses had stacking opportunities.
                            _tm_target_group = f"terminal_momentum_{best_ask}"
                            if STACKING_ENABLED:
                                from models import strategy_to_group
                                _tm_has_position = any(
                                    p["ticker"] == ticker
                                    and p.get("strategy_group",
                                        strategy_to_group(p.get("strategy", "")))
                                        == _tm_target_group
                                    for p in self._state.get_open_positions())
                            else:
                                _tm_has_position = any(
                                    p["ticker"] == ticker
                                    for p in self._state.get_open_positions())
                            if not _tm_has_position:
                                # Check concurrent TM position cap
                                _tm_count = sum(1 for c in candidates if c.get("strategy", "").startswith("terminal_momentum"))
                                if _tm_count < TM_MAX_CONCURRENT:
                                    # NBBO gate: two layers.
                                    # 1) Block 96-97c on NBBO entirely (data: 181 trades -$326; orderbook 21/21 +$60)
                                    # 2) At 98-99c, require minimum buffer on NBBO (thin buf = stale pricing)
                                    # Orderbook-sourced TM trades pass freely at all prices.
                                    _tm_buf_pct = (spot - threshold) / threshold * 100 if threshold and threshold > 0 else 0
                                    _tm_nbbo_blocked = False
                                    if best_ask_source == "market_nbbo":
                                        if best_ask in TM_NBBO_BLOCKED_PRICES:
                                            _tm_nbbo_blocked = True
                                        elif _tm_buf_pct < TM_NBBO_MIN_BUFFER_PCT:
                                            _tm_nbbo_blocked = True
                                    if _tm_nbbo_blocked:
                                        _tm_nbbo_reason = (f"price {best_ask}c in BLOCKED_PRICES"
                                                           if best_ask in TM_NBBO_BLOCKED_PRICES
                                                           else f"buf={_tm_buf_pct:.3f}% < {TM_NBBO_MIN_BUFFER_PCT}%")
                                        logging.info(
                                            "TM_NBBO_GATE: %s %s @%dc buf=%.3f%% (%s, skipping)",
                                            asset, ticker, best_ask, _tm_buf_pct, _tm_nbbo_reason)
                                        # Log as shadow for counterfactual tracking
                                        _tm_dedup_shadow = (ticker, "tm_nbbo_buffer_shadow")
                                        if _tm_dedup_shadow not in self._eval_opp_seen:
                                            self._eval_opp_seen.add(_tm_dedup_shadow)
                                            try:
                                                self._state.insert_evaluated_opportunity(
                                                    ticker, window["event_ticker"], asset,
                                                    "tm_nbbo_buffer_shadow",
                                                    rejection_reason=f"TM NBBO {_tm_nbbo_reason} (ask={best_ask}c stc={seconds_remaining:.0f}s)",
                                                    spot_price=spot, threshold=threshold,
                                                    volatility=blended_rv, market_price=best_ask,
                                                    seconds_to_close=seconds_remaining,
                                                    calibrated_prob=final_prob, edge=edge,
                                                    ofa_adjustment=ofa_adjustment,
                                                    strategy=f"terminal_momentum_{best_ask}",
                                                    z_score=z_score, raw_prob=raw_prob,
                                                    fee_adjusted_edge=fee_adjusted_edge,
                                                    best_ask_source=best_ask_source,
                                                    product_type="15m", **_shadow_diag)
                                            except Exception:
                                                logging.warning("insert_evaluated_opportunity failed (tm_nbbo_buffer)", exc_info=True)
                                    else:
                                        _tm_intercepted = True
                                    # R-p7-deploy-r10: cal_mlp lower-bound gate for TM-96.
                                    # Evaluated whenever _tm_intercepted (i.e., we'd otherwise
                                    # trade) AND best_ask == 96. ALWAYS shadow-logs when
                                    # would_block=True (independent of env-flag, so we have
                                    # data to validate the gate's PnL impact before flipping
                                    # live). Only the trade-block (_tm_intercepted=False) is
                                    # env-gated by TM96_CALMLP_GATE_ENABLED.
                                    # R-p7-deploy-r10 Round-1 #1: pass calibrated_prob (final_prob,
                                    # post-CalEngine) so gate's prob_breakeven_gap matches the
                                    # training-time formula. Round-1 #2: shadow row writes
                                    # on would_block regardless of env-flag. Round-2 H1:
                                    # _tm96_gate_blocked_trade init moved to outer scope.
                                    if _tm_intercepted and best_ask == 96:
                                        from integration import should_block_tm96
                                        _tm96_would_block, _tm96_diag = should_block_tm96(
                                            predictor=_calmlp_predictors.get(asset),
                                            raw_prob=raw_prob, calibrated_prob=final_prob,
                                            ticker=ticker, market_price=best_ask,
                                            seconds_to_close=seconds_remaining,
                                            spot=spot, threshold=threshold,
                                            blended_rv=blended_rv,
                                            vol_regime=(vol_est or {}).get("regime", "normal"),
                                        )
                                        logging.info(
                                            "TM96_CALMLP_GATE: %s %s @%dc raw=%.4f "
                                            "p_mean=%s lo=%s would_block=%s enabled=%s",
                                            asset, ticker, best_ask, raw_prob,
                                            _tm96_diag.get('cal_mlp_p_mean'),
                                            _tm96_diag.get('cal_mlp_final_lo'),
                                            _tm96_would_block, TM96_CALMLP_GATE_ENABLED)
                                        # ALWAYS write the shadow row on would_block — even
                                        # when env-flag is off — so the validation query
                                        # `WHERE filter_stage='tm96_calmlp_gate_blocked'`
                                        # has data to join with settlement outcomes.
                                        if _tm96_would_block:
                                            _tm96_dedup_shadow = (ticker, "tm96_calmlp_gate_blocked")
                                            if _tm96_dedup_shadow not in self._eval_opp_seen:
                                                self._eval_opp_seen.add(_tm96_dedup_shadow)
                                                try:
                                                    _tm96_diag_clean = {k: v for k, v in _tm96_diag.items()
                                                                          if k.startswith('cal_mlp_')}
                                                    self._state.insert_evaluated_opportunity(
                                                        ticker, window["event_ticker"], asset,
                                                        "tm96_calmlp_gate_blocked",
                                                        rejection_reason=(
                                                            f"cal_mlp_final_lo={_tm96_diag.get('cal_mlp_final_lo')} "
                                                            f"< market_price/100={best_ask/100} "
                                                            f"(env_enabled={TM96_CALMLP_GATE_ENABLED}, "
                                                            f"shadow_only={not TM96_CALMLP_GATE_ENABLED}, "
                                                            f"trade_actually_blocked={TM96_CALMLP_GATE_ENABLED})"),
                                                        spot_price=spot, threshold=threshold,
                                                        volatility=blended_rv, market_price=best_ask,
                                                        seconds_to_close=seconds_remaining,
                                                        calibrated_prob=final_prob, edge=edge,
                                                        ofa_adjustment=ofa_adjustment,
                                                        strategy=f"terminal_momentum_{best_ask}",
                                                        z_score=z_score, raw_prob=raw_prob,
                                                        fee_adjusted_edge=fee_adjusted_edge,
                                                        best_ask_source=best_ask_source,
                                                        product_type="15m",
                                                        **{k: v for k, v in _shadow_diag.items()
                                                           if not k.startswith('cal_mlp_')},
                                                        **_tm96_diag_clean)
                                                except Exception:
                                                    logging.warning("insert_evaluated_opportunity failed (tm96_calmlp_gate)", exc_info=True)
                                            # Round-1 #3: distinguish "trade was actually
                                            # blocked" from "would-have-been-blocked" so the
                                            # outer `if _tm_intercepted` falls-through-to-
                                            # insufficient_edge logic doesn't double-count.
                                            if TM96_CALMLP_GATE_ENABLED:
                                                _tm_intercepted = False
                                                _tm96_gate_blocked_trade = True
                                    if _tm_intercepted:
                                        _tm_balance = self._get_balance_cached() or 100000
                                        # Adversary A6: when sweep is live, size against worst-case fill
                                        # price (MAX_ENTRY_PRICE) so per-asset risk cap respects the
                                        # actual capital-at-risk after a sweep up to 99c.
                                        _tm_risk_price = (MAX_ENTRY_PRICE
                                                          if TM_SWEEP_LIVE_ENABLED else None)
                                        _tm_size = tm_compute_contracts(
                                            best_ask, seconds_remaining, _tm_balance, asset,
                                            buf_pct=_tm_buf_pct, risk_cap_price=_tm_risk_price)
                                        logging.info(
                                            "TM_CANDIDATE: %s %s %dx@%dc prob=%.3f stc=%.0fs edge=%.4f margin=%dc stc_zone=%s buf=%.3f%% src=%s",
                                            asset, ticker, _tm_size, best_ask,
                                            final_prob, seconds_remaining, fee_adjusted_edge,
                                            100 - best_ask,
                                            "safe" if seconds_remaining < TM_STC_SAFE_THRESHOLD else
                                            ("danger" if seconds_remaining < TM_STC_DANGER_HI else "normal"),
                                            _tm_buf_pct, best_ask_source)
                                        candidates.append({
                                            "ticker": ticker,
                                            "event_ticker": window["event_ticker"],
                                            "asset": asset,
                                            "product_type": window.get("product_type"),
                                            "spot": spot,
                                            "threshold": threshold,
                                            "seconds_to_close": round(seconds_remaining, 1),
                                            "blended_rv": blended_rv,
                                            "calibrated_prob": round(final_prob, 6),
                                            "z_score": z_score,
                                            "best_yes_ask": best_ask,
                                            "best_ask_source": best_ask_source,
                                            "edge": round(edge, 6),
                                            "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                            "position_size": _tm_size,
                                            "kelly_f": 0.0,
                                            "drawdown_scaler": 1.0,
                                            "vol_regime": vol_est["regime"],
                                            "balance_at_scan": self._get_balance_cached(),
                                            "spot_buffer_pct": round(_tm_buf_pct, 4),
                                            "strategy": f"terminal_momentum_{best_ask}",
                                            "strategy_scores": {"certainty": 1.0, "certainty_detail": "terminal_momentum",
                                                                "orderbook": 0.5, "orderbook_detail": "n/a",
                                                                "urgency": 1.0, "urgency_detail": "terminal_momentum",
                                                                "composite": 1.0, "reason": "terminal_momentum"},
                                            "ob_snapshot": {
                                                "best_ask": best_ask,
                                                "ask_depth": ask_depth,
                                                "total_depth": total_depth,
                                                "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                                                "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                                                "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                                          if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                                            },
                                            "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                                            "ofa_adjustment": round(ofa_adjustment, 6),
                                            "ofa_confidence": ofa_signals["confidence"] if ofa_signals else "none",
                                            "raw_prob": raw_prob,
                                            "calibration_method": calibration_method,
                                            "old_system_prob": round(_old_system_prob, 6),
                                            **_shadow_diag,
                                            **_shadow_extra,
                                        })
                                        # Log to evaluated_opportunities
                                        _tm_dedup = (ticker, f"terminal_momentum_{best_ask}")
                                        if _tm_dedup not in self._eval_opp_seen:
                                            self._eval_opp_seen.add(_tm_dedup)
                                            try:
                                                self._state.insert_evaluated_opportunity(
                                                    ticker, window["event_ticker"], asset,
                                                    "terminal_momentum",
                                                    rejection_reason=None,
                                                    spot_price=spot, threshold=threshold,
                                                    volatility=blended_rv, market_price=best_ask,
                                                    seconds_to_close=seconds_remaining,
                                                    calibrated_prob=final_prob, edge=edge,
                                                    ofa_adjustment=ofa_adjustment,
                                                    strategy=f"terminal_momentum_{best_ask}",
                                                    z_score=z_score,
                                                    vol_regime=vol_est["regime"],
                                                    calibrated_prob_raw=calibrated_prob_raw,
                                                    kelly_f=0.0,
                                                    position_size=_tm_size,
                                                    breakeven_wr=best_ask / 100.0,
                                                    ask_depth=ask_depth,
                                                    best_ask_source=best_ask_source,
                                                    raw_prob=raw_prob,
                                                    calibration_method=calibration_method,
                                                    fee_adjusted_edge=fee_adjusted_edge,
                                                    product_type=window.get("product_type"),
                                                    **_shadow_diag)
                                            except Exception:
                                                logging.warning("insert_evaluated_opportunity failed (terminal_momentum)", exc_info=True)

                    if _tm_intercepted:
                        continue  # Skip insufficient_edge rejection — this is now a TM candidate

                    # R-p7-deploy-r10 Round-1 #3: when TM-96 gate blocks the
                    # trade, _tm_intercepted=False but the candidate has
                    # already been logged as `tm96_calmlp_gate_blocked`.
                    # Falling through to `insufficient_edge` would double-
                    # count the funnel (one row + one JSONL entry both
                    # claiming the same window). Skip the insufficient_edge
                    # path for gate-blocked candidates.
                    if _tm96_gate_blocked_trade:
                        continue

                    scan_stats[asset]["insufficient_edge"] += 1
                    self._recent_opportunities.append({
                        "ticker": ticker, "asset": asset,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "best_ask": best_ask,
                        "edge_bps": round(fee_adjusted_edge * 10000),
                        "gross_edge_bps": round(edge * 10000),
                        "chosen_strategy": None,
                        "rejection_reason": "insufficient_edge",
                        "ts": datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                    })
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "insufficient_edge",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": f"net_edge {fee_adjusted_edge:.4f} < min {_min_edge:.4f} @{best_ask}c (gross {edge:.4f}, fee {est_fee_1c}c)",
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": best_ask,
                            "best_ask_source": best_ask_source,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(final_prob, 6),
                            "edge": round(edge, 6),
                            "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                            "ofa_adjustment": round(ofa_adjustment, 6),
                            "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                            "old_system_prob": round(_old_system_prob, 6),
                            "kalshi_oft": (ofa_signals or {}).get("signals", {}).get("kalshi_orderbook", {}),
                            "counterfactual": _cf,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                        _dedup_key = (ticker, "insufficient_edge")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            # Compute sizing for instrumentation (pure math, no side effects)
                            _ie_kelly_f = None
                            _ie_position = None
                            _ie_drawdown = None
                            _ie_balance = self._get_balance_cached()
                            if _ie_balance and _ie_balance > 0:
                                _ie_sizing = self._sizer.compute(final_prob, best_ask, _ie_balance)
                                _ie_kelly_f = _ie_sizing["kelly_f"]
                                _ie_position = _ie_sizing["contracts"]
                                _ie_drawdown = _ie_sizing["drawdown_scaler"]
                                # Apply product-type Kelly fraction + risk cap
                                _ie_scfg = get_market_config(window.get("product_type"))
                                if _ie_scfg.kelly_fraction < 1.0:
                                    _ie_position = max(1, int(_ie_position * _ie_scfg.kelly_fraction))
                                _ie_type_max = int((_ie_balance * _ie_scfg.max_risk_per_trade) / best_ask)
                                if _ie_position > _ie_type_max:
                                    _ie_position = max(1, _ie_type_max)
                            # Compute strategy for instrumentation (pure computation, no side effects)
                            _ie_strategy = None
                            try:
                                _ie_scfg2 = get_market_config(window.get("product_type"))
                                _ie_strat_data = {
                                    "z_score": z_score,
                                    "calibrated_prob": final_prob,
                                    "spot": spot, "threshold": threshold,
                                    "seconds_to_close": seconds_remaining,
                                    "blended_rv": blended_rv,
                                    "vol_regime": vol_est["regime"],
                                    "best_yes_ask": best_ask,
                                    "best_ask_depth": ask_depth,
                                    "total_ob_depth": total_depth,
                                    "convergence_velocity": self._scanner_convergence_velocity(ticker),
                                    "edge": edge,
                                    "min_entry_price": _ie_scfg2.min_entry_price,
                                    "max_entry_price": _ie_scfg2.max_entry_price,
                                }
                                _ie_strategy, _ = evaluate_execution_strategy(_ie_strat_data)
                            except Exception:
                                logging.debug("IE strategy computation failed", exc_info=True)
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "insufficient_edge",
                                rejection_reason=f"net_edge {fee_adjusted_edge:.4f} < min",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge,
                                ofa_adjustment=ofa_adjustment,
                                strategy=_ie_strategy,
                                z_score=z_score,
                                vol_regime=vol_est["regime"],
                                calibrated_prob_raw=calibrated_prob_raw,
                                kelly_f=_ie_kelly_f,
                                position_size=_ie_position,
                                drawdown_scaler=_ie_drawdown,
                                breakeven_wr=best_ask / 100.0,
                                expected_value=round(_ev, 2),
                                ask_depth=ask_depth,
                                best_ask_source=best_ask_source,
                                ofa_confidence=ofa_signals["confidence"] if ofa_signals else "none",
                                raw_prob=raw_prob,
                                calibration_method=calibration_method,
                                old_system_prob=_old_system_prob,
                                fee_adjusted_edge=fee_adjusted_edge,
                                counterfactual=_cf_json,
                                shadow_cal_prob=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("prob") if _cf else None,
                                shadow_cal_fee_edge=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("fee_edge") if _cf else None,
                                shadow_cal_temperature=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("temperature") if _cf else None,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                                **_oft_db, **_shadow_diag)
                    except Exception:
                        logging.warning("insert_evaluated_opportunity failed (hourly_observation)", exc_info=True)
                    # V2 variant: shadow cal pipeline (temperature + no blend)
                    if _pt == "hourly" and _cf:
                        self._insert_hourly_v2_variant(
                            ticker, window, asset, raw_prob, best_ask,
                            seconds_remaining, spot, threshold, blended_rv,
                            ofa_adjustment, z_score, vol_est,
                            calibrated_prob_raw, est_fee_1c,
                            ask_depth, best_ask_source, _cf, _shadow_diag)

                    # ── Low-price shadow: queue IE signals at 20-79c ──
                    if (LOW_PRICE_SHADOW_ENABLED
                            and _pt in (None, "15m")
                            and LOW_PRICE_SHADOW_MIN_PRICE <= best_ask <= LOW_PRICE_SHADOW_MAX_PRICE
                            and seconds_remaining <= LOW_PRICE_SHADOW_MAX_STC):
                        _low_price_shadow_queue.append({
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "best_ask": best_ask,
                            "spot": spot,
                            "threshold": threshold,
                            "blended_rv": blended_rv,
                            "seconds_remaining": seconds_remaining,
                            "vol_regime": vol_est["regime"],
                            "ask_depth": ask_depth,
                            "best_ask_source": best_ask_source,
                            "product_type": window.get("product_type"),
                            # Phase D (shadow coverage expansion 2026-05-02):
                            # propagate cal_mlp_request_id so the post-hoc
                            # daemon predicts on low_price_shadow rows too.
                            # See kb/decisions/shadow-coverage-expansion-may01.md.
                            "_shadow_diag": _shadow_diag.copy(),
                            "_oft_db": _oft_db.copy(),
                            "has_prob": True,
                            "final_prob": final_prob,
                            "raw_prob": raw_prob,
                            "calibration_method": calibration_method,
                            "edge": edge,
                            "fee_adjusted_edge": fee_adjusted_edge,
                            "z_score": z_score,
                            "est_fee_1c": est_fee_1c,
                            "calibrated_prob_raw": calibrated_prob_raw,
                        })

                    # ── Weekend Edge Discount (Live + Shadow) ────────────────
                    # On Sat/Sun, re-evaluate 15M insufficient_edge rejections
                    # at relaxed thresholds (0.6x MIN_EDGE_BY_PRICE).
                    # Live: 89c+, STC ≤ 600s, no DC overlap → candidate
                    # Shadow: sub-89c, high STC, or DC overlap → log only
                    if (_pt in (None, "15m")
                            and datetime.datetime.now(timezone.utc).weekday() >= 5
                            and best_ask >= MIN_ENTRY_PRICE):
                        _wknd_discounted_min = _min_edge * WEEKEND_EDGE_DISCOUNT
                        _wknd_discounted_min = min(_wknd_discounted_min, WEEKEND_EDGE_FLOOR)
                        if fee_adjusted_edge >= _wknd_discounted_min:
                            # Compute sizing (shared by live and shadow paths)
                            _wknd_balance = self._get_balance_cached()
                            _wknd_kelly_f = None
                            _wknd_position = None
                            _wknd_ev = None
                            _wknd_drawdown = None
                            if _wknd_balance and _wknd_balance > 0:
                                _wknd_sizing = self._sizer.compute(final_prob, best_ask, _wknd_balance)
                                _wknd_kelly_f = _wknd_sizing["kelly_f"]
                                _wknd_position = _wknd_sizing["contracts"]
                                _wknd_drawdown = _wknd_sizing["drawdown_scaler"]
                                # Apply product-type Kelly fraction + risk cap
                                _wknd_scfg = get_market_config(window.get("product_type"))
                                if _wknd_scfg.kelly_fraction < 1.0:
                                    _wknd_position = max(1, int(_wknd_position * _wknd_scfg.kelly_fraction))
                                _wknd_type_max = int((_wknd_balance * _wknd_scfg.max_risk_per_trade) / best_ask)
                                if _wknd_position > _wknd_type_max:
                                    _wknd_position = max(1, _wknd_type_max)
                                # STC sizing scaler (consistent with main pipeline)
                                if (STC_SIZING_SCALER_ENABLED
                                        and seconds_remaining > STC_SIZING_SCALER_KNEE
                                        and _wknd_position > 0):
                                    _wknd_position = max(1, int(_wknd_position * (STC_SIZING_SCALER_KNEE / seconds_remaining)))
                                _wknd_ev = round((final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c, 2)
                                # Fixed sizing fallback when Kelly produces 0 (edge near zero)
                                if _wknd_position == 0:
                                    _wknd_fixed_raw = max(1, int((_wknd_balance * WEEKEND_FIXED_RISK) / best_ask))
                                    # Apply drawdown scaler to fixed sizing
                                    if _wknd_drawdown is not None and _wknd_drawdown < 1.0:
                                        _wknd_fixed_raw = max(1, int(_wknd_fixed_raw * _wknd_drawdown))
                                    _wknd_position = _wknd_fixed_raw
                                    logging.info(
                                        "WEEKEND_FIXED_SIZE: %s edge=%.4f kelly=0 fixed=%dct risk=%.0f%% balance=%d scaler=%.2f",
                                        ticker, fee_adjusted_edge, _wknd_position,
                                        WEEKEND_FIXED_RISK * 100, _wknd_balance,
                                        _wknd_drawdown if _wknd_drawdown else 1.0)

                            # Check live eligibility gates
                            _wknd_dc_overlap = (z_score is not None
                                                and z_score <= DECIDED_CONTRACT_Z_T2
                                                and best_ask >= DECIDED_CONTRACT_MIN_PRICE
                                                and seconds_remaining < DECIDED_CONTRACT_MAX_STC)
                            _wknd_live_eligible = (
                                WEEKEND_DISCOUNT_LIVE
                                and not OBSERVATION_MODE
                                and best_ask >= WEEKEND_DISCOUNT_MIN_PRICE
                                and seconds_remaining <= WEEKEND_DISCOUNT_MAX_STC
                                and not _wknd_dc_overlap
                                and _wknd_balance and _wknd_balance > 0
                                and _wknd_position and _wknd_position > 0)

                            # Determine filter stage for DB insert
                            _wknd_stage = "weekend_discount" if _wknd_live_eligible else "weekend_discount_shadow"

                            # JSONL log (always — both live and shadow)
                            try:
                                self._logger.log_opportunity({
                                    "filter_stage": _wknd_stage,
                                    "ticker": ticker,
                                    "event_ticker": window["event_ticker"],
                                    "asset": asset,
                                    "side": "yes",
                                    "market_price": best_ask,
                                    "model_prob": round(final_prob, 6),
                                    "edge": round(edge, 6),
                                    "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                    "kelly_f": round(_wknd_kelly_f, 6) if _wknd_kelly_f else None,
                                    "position_size": _wknd_position,
                                    "expected_value": _wknd_ev,
                                    "seconds_to_close": round(seconds_remaining, 1),
                                    "spot_price": spot,
                                    "threshold": threshold,
                                    "volatility": blended_rv,
                                    "vol_regime": vol_est["regime"],
                                    "discount_factor": WEEKEND_EDGE_DISCOUNT,
                                    "original_min_edge": round(_min_edge, 6),
                                    "discounted_min_edge": round(_wknd_discounted_min, 6),
                                    "edge_vs_discounted": round(fee_adjusted_edge - _wknd_discounted_min, 6),
                                    "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                                    "ofa_adjustment": round(ofa_adjustment, 6),
                                    "z_score": z_score,
                                })
                            except Exception:
                                logging.debug("weekend_discount log failed", exc_info=True)

                            # DB insert (always — for settlement tracking)
                            _wknd_dedup = (ticker, _wknd_stage)
                            if _wknd_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_wknd_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        _wknd_stage,
                                        rejection_reason=f"{'live' if _wknd_live_eligible else 'shadow'}: edge {fee_adjusted_edge:.4f} >= discounted_min {_wknd_discounted_min:.4f} (orig {_min_edge:.4f} x {WEEKEND_EDGE_DISCOUNT})",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score,
                                        vol_regime=vol_est["regime"],
                                        calibrated_prob_raw=calibrated_prob_raw,
                                        kelly_f=_wknd_kelly_f,
                                        position_size=_wknd_position,
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_wknd_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        raw_prob=raw_prob,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        product_type=window.get("product_type"),
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (%s)", _wknd_stage, exc_info=True)

                            # Live path: append to candidates for execution
                            if _wknd_live_eligible:
                                logging.info(
                                    "WKND_DISCOUNT_CANDIDATE: %s %dx@%dc edge=%.4f disc_min=%.4f stc=%.0fs",
                                    ticker, _wknd_position, best_ask,
                                    fee_adjusted_edge, _wknd_discounted_min, seconds_remaining)
                                candidates.append({
                                    "ticker": ticker,
                                    "event_ticker": window["event_ticker"],
                                    "asset": asset,
                                    "product_type": window.get("product_type"),
                                    "spot": spot,
                                    "threshold": threshold,
                                    "seconds_to_close": round(seconds_remaining, 1),
                                    "blended_rv": blended_rv,
                                    "calibrated_prob": round(final_prob, 6),
                                    "z_score": z_score,
                                    "best_yes_ask": best_ask,
                                    "best_ask_source": best_ask_source,
                                    "edge": round(edge, 6),
                                    "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                    "position_size": _wknd_position,
                                    "kelly_f": _wknd_kelly_f,
                                    "drawdown_scaler": _wknd_drawdown or 1.0,
                                    "vol_regime": vol_est["regime"],
                                    "balance_at_scan": _wknd_balance,
                                    "strategy": "weekend_discount",
                                    "ob_snapshot": {
                                        "best_ask": best_ask,
                                        "ask_depth": ask_depth,
                                        "total_depth": total_depth,
                                        "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                                        "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                                        "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                                  if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                                    },
                                    "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                                    "ofa_adjustment": round(ofa_adjustment, 6),
                                    "ofa_confidence": ofa_signals["confidence"] if ofa_signals else "none",
                                    "raw_prob": raw_prob,
                                    "calibration_method": calibration_method,
                                    "old_system_prob": round(_old_system_prob, 6),
                                    **_shadow_diag,
                                    **_shadow_extra,
                                })

                    # ── Overnight Edge Discount (Live + Shadow) ────────────────
                    # On weekday quiet hours (04-11 UTC), re-evaluate 15M
                    # insufficient_edge at relaxed thresholds (0.6x).
                    # Live: 89c+, STC ≤ 600s, no DC overlap → candidate
                    # Shadow: sub-89c, high STC, or DC overlap → log only
                    # Skip if weekend discount already applied (don't double-count).
                    _now_utc = datetime.datetime.now(timezone.utc)
                    _is_weekend = _now_utc.weekday() >= 5
                    if (_pt in (None, "15m")
                            and not _is_weekend
                            and OVERNIGHT_QUIET_START <= _now_utc.hour <= OVERNIGHT_QUIET_END
                            and best_ask >= MIN_ENTRY_PRICE):
                        _ovn_discounted_min = _min_edge * OVERNIGHT_EDGE_DISCOUNT
                        if fee_adjusted_edge >= _ovn_discounted_min:
                            _ovn_balance = self._get_balance_cached()
                            _ovn_kelly_f = None
                            _ovn_position = None
                            _ovn_ev = None
                            _ovn_drawdown = None
                            if _ovn_balance and _ovn_balance > 0:
                                _ovn_sizing = self._sizer.compute(final_prob, best_ask, _ovn_balance)
                                _ovn_kelly_f = _ovn_sizing["kelly_f"]
                                _ovn_position = _ovn_sizing["contracts"]
                                _ovn_drawdown = _ovn_sizing["drawdown_scaler"]
                                _ovn_scfg = get_market_config(window.get("product_type"))
                                if _ovn_scfg.kelly_fraction < 1.0:
                                    _ovn_position = max(1, int(_ovn_position * _ovn_scfg.kelly_fraction))
                                _ovn_type_max = int((_ovn_balance * _ovn_scfg.max_risk_per_trade) / best_ask)
                                if _ovn_position > _ovn_type_max:
                                    _ovn_position = max(1, _ovn_type_max)
                                # STC sizing scaler (consistent with main pipeline)
                                if (STC_SIZING_SCALER_ENABLED
                                        and seconds_remaining > STC_SIZING_SCALER_KNEE
                                        and _ovn_position > 0):
                                    _ovn_position = max(1, int(_ovn_position * (STC_SIZING_SCALER_KNEE / seconds_remaining)))
                                _ovn_ev = round((final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c, 2)

                            # Check live eligibility gates
                            _ovn_dc_overlap = (z_score is not None
                                               and z_score <= DECIDED_CONTRACT_Z_T2_Z2
                                               and best_ask >= DECIDED_CONTRACT_MIN_PRICE
                                               and seconds_remaining < DECIDED_CONTRACT_MAX_STC)
                            _ovn_live_eligible = (
                                OVERNIGHT_DISCOUNT_LIVE
                                and not OBSERVATION_MODE
                                and best_ask >= OVERNIGHT_DISCOUNT_MIN_PRICE
                                and seconds_remaining <= OVERNIGHT_DISCOUNT_MAX_STC
                                and not _ovn_dc_overlap
                                and _ovn_balance and _ovn_balance > 0
                                and _ovn_position and _ovn_position > 0)

                            # Determine filter stage for DB insert
                            _ovn_stage = "overnight_discount" if _ovn_live_eligible else "overnight_discount_shadow"

                            try:
                                self._logger.log_opportunity({
                                    "filter_stage": _ovn_stage,
                                    "ticker": ticker,
                                    "event_ticker": window["event_ticker"],
                                    "asset": asset,
                                    "side": "yes",
                                    "market_price": best_ask,
                                    "model_prob": round(final_prob, 6),
                                    "edge": round(edge, 6),
                                    "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                    "kelly_f": round(_ovn_kelly_f, 6) if _ovn_kelly_f else None,
                                    "position_size": _ovn_position,
                                    "expected_value": _ovn_ev,
                                    "seconds_to_close": round(seconds_remaining, 1),
                                    "spot_price": spot,
                                    "threshold": threshold,
                                    "volatility": blended_rv,
                                    "vol_regime": vol_est["regime"],
                                    "discount_factor": OVERNIGHT_EDGE_DISCOUNT,
                                    "original_min_edge": round(_min_edge, 6),
                                    "discounted_min_edge": round(_ovn_discounted_min, 6),
                                    "edge_vs_discounted": round(fee_adjusted_edge - _ovn_discounted_min, 6),
                                    "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                                    "ofa_adjustment": round(ofa_adjustment, 6),
                                    "z_score": z_score,
                                })
                            except Exception:
                                logging.debug("overnight_discount log failed", exc_info=True)

                            # DB insert (always — for settlement tracking)
                            _ovn_dedup = (ticker, _ovn_stage)
                            if _ovn_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_ovn_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        _ovn_stage,
                                        rejection_reason=f"{'live' if _ovn_live_eligible else 'shadow'}: edge {fee_adjusted_edge:.4f} >= discounted_min {_ovn_discounted_min:.4f} (orig {_min_edge:.4f} x {OVERNIGHT_EDGE_DISCOUNT})",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score,
                                        vol_regime=vol_est["regime"],
                                        calibrated_prob_raw=calibrated_prob_raw,
                                        kelly_f=_ovn_kelly_f,
                                        position_size=_ovn_position,
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_ovn_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        raw_prob=raw_prob,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        product_type=window.get("product_type"),
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (%s)", _ovn_stage, exc_info=True)

                            # Live path: append to candidates for execution
                            if _ovn_live_eligible:
                                logging.info(
                                    "OVN_DISCOUNT_CANDIDATE: %s %dx@%dc edge=%.4f disc_min=%.4f stc=%.0fs",
                                    ticker, _ovn_position, best_ask,
                                    fee_adjusted_edge, _ovn_discounted_min, seconds_remaining)
                                candidates.append({
                                    "ticker": ticker,
                                    "event_ticker": window["event_ticker"],
                                    "asset": asset,
                                    "product_type": window.get("product_type"),
                                    "spot": spot,
                                    "threshold": threshold,
                                    "seconds_to_close": round(seconds_remaining, 1),
                                    "blended_rv": blended_rv,
                                    "calibrated_prob": round(final_prob, 6),
                                    "z_score": z_score,
                                    "best_yes_ask": best_ask,
                                    "best_ask_source": best_ask_source,
                                    "edge": round(edge, 6),
                                    "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                    "position_size": _ovn_position,
                                    "kelly_f": _ovn_kelly_f,
                                    "drawdown_scaler": _ovn_drawdown or 1.0,
                                    "vol_regime": vol_est["regime"],
                                    "balance_at_scan": _ovn_balance,
                                    "strategy": "overnight_discount",
                                    "ob_snapshot": {
                                        "best_ask": best_ask,
                                        "ask_depth": ask_depth,
                                        "total_depth": total_depth,
                                        "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                                        "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                                        "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                                  if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                                    },
                                    "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                                    "est_fee_1c": est_fee_1c,
                                })

                    # ── Decided Contract (overlay strategy + shadow) ─────────
                    # When z-score is very negative (spot far above strike) near expiry,
                    # the contract is essentially decided. EGARCH can't compute edge
                    # because calibration squashes prob below market price.
                    # T1 (z ≤ -5, 93c+), T1B (z ≤ -4, 95c+), T2 (z ≤ -3, 93-96c).
                    # Shadow always runs. Live overlay fires when DECIDED_T1/T1B/T2_ENABLED.
                    if (DECIDED_CONTRACT_SHADOW
                            and _pt in (None, "15m")
                            and z_score is not None
                            and best_ask >= DECIDED_CONTRACT_MIN_PRICE
                            and best_ask <= MAX_ENTRY_PRICE
                            and seconds_remaining < DECIDED_CONTRACT_MAX_STC):
                        _dc_tier = None
                        if z_score <= DECIDED_CONTRACT_Z_T1:
                            _dc_tier = "decided_contract_t1"
                        elif (z_score <= DECIDED_CONTRACT_Z_T1B
                              and best_ask >= DECIDED_CONTRACT_T1B_MIN_PRICE):
                            _dc_tier = "decided_contract_t1b"
                        elif (z_score <= DECIDED_CONTRACT_Z_T2
                              and best_ask <= DECIDED_CONTRACT_T2_MAX_PRICE):
                            _dc_tier = "decided_contract_t2"
                        elif (z_score <= DECIDED_CONTRACT_Z_T2_Z25
                              and best_ask <= DECIDED_CONTRACT_T2_MAX_PRICE):
                            _dc_tier = "decided_contract_t2_z25"
                        elif (z_score <= DECIDED_CONTRACT_Z_T2_Z2
                              and best_ask <= DECIDED_CONTRACT_T2_MAX_PRICE):
                            _dc_tier = "decided_contract_t2_z2"

                        if _dc_tier:
                            # Fixed sizing per tier (not Kelly — model edge is negative)
                            _dc_balance = self._get_balance_cached()
                            _dc_position = None
                            _dc_kelly_f = None
                            _dc_ev = None
                            if _dc_balance and _dc_balance > 0:
                                _dc_risk = (DECIDED_CONTRACT_T2_Z25_RISK if _dc_tier == "decided_contract_t2_z25"
                                            else DECIDED_CONTRACT_T2_Z2_RISK if _dc_tier == "decided_contract_t2_z2"
                                            else DECIDED_CONTRACT_RISK)
                                # SOL price-tiered risk: reduce sizing at high prices to contain loss asymmetry
                                if asset == "SOL":
                                    for _sol_floor, _sol_risk in SOL_DC_RISK_TIERS:
                                        if best_ask >= _sol_floor:
                                            _dc_risk = _sol_risk
                                            break
                                _dc_position = max(1, int((_dc_balance * _dc_risk) / best_ask))
                                # Per-asset risk caps (DC uses DECIDED_CONTRACT_RISK=20%
                                # which can exceed per-asset caps like SOL 15%, BTC 15%)
                                if asset == "SOL":
                                    _dc_asset_max = int((_dc_balance * SOL_MAX_RISK_PER_TRADE) / best_ask)
                                    if _dc_position > _dc_asset_max >= 1:
                                        _dc_position = _dc_asset_max
                                elif asset == "BTC":
                                    _dc_asset_max = int((_dc_balance * BTC_MAX_RISK_PER_TRADE) / best_ask)
                                    if _dc_position > _dc_asset_max >= 1:
                                        _dc_position = _dc_asset_max
                                elif asset == "XRP":
                                    _dc_asset_max = int((_dc_balance * XRP_MAX_RISK_PER_TRADE) / best_ask)
                                    if _dc_position > _dc_asset_max >= 1:
                                        _dc_position = _dc_asset_max
                                # EV with assumed win prob — calibrated from 14-day settlement data:
                                # T1: 92/92 (100%) at 95-98c → 0.99 (unchanged)
                                # T1B: 47/47 (100%) at 95-98c → 0.98 (was 0.97, unlocks 97c)
                                # T2: 106/106 (100%) at 95-98c → 0.97 (was 0.96, unlocks 96c)
                                # T2-Z25: 69/71 (97.2%) has 2 losses → 0.96 (unchanged, conservative)
                                # T2-Z2: 144/144 (100%) at 95-98c → 0.97 (was 0.95, unlocks 96c)
                                _dc_assumed_p = (0.99 if _dc_tier == "decided_contract_t1"
                                                 else 0.98 if _dc_tier == "decided_contract_t1b"
                                                 else 0.97 if _dc_tier == "decided_contract_t2"
                                                 else 0.96 if _dc_tier == "decided_contract_t2_z25"
                                                 else 0.97)
                                _dc_ev = round((_dc_assumed_p * (100 - best_ask))
                                               - ((1 - _dc_assumed_p) * best_ask) - est_fee_1c, 2)
                                _dc_kelly_f = round((_dc_assumed_p - best_ask / 100.0), 6)

                            # Always log shadow signal (continues accumulating shadow stats)
                            _dc_dedup = (ticker, _dc_tier)
                            if _dc_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dc_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        _dc_tier,
                                        rejection_reason=f"shadow: z={z_score:.1f} stc={seconds_remaining:.0f}s price={best_ask}c",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score,
                                        vol_regime=vol_est["regime"],
                                        calibrated_prob_raw=calibrated_prob_raw,
                                        kelly_f=_dc_kelly_f,
                                        position_size=_dc_position,
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_dc_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        raw_prob=raw_prob,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        product_type=window.get("product_type"),
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (%s)", _dc_tier, exc_info=True)

                            # ── Phase 1 re-promotion shadow (T2-Z2 BTC+ETH @ 10%) ──
                            # Logs the exact cohort of the rejected Apr 22 promotion
                            # proposal so clean Kelly-actual cf_pnl can be computed at
                            # the PROPOSED 10% sizing (not the current 20%).
                            # See kb/decisions/t2-z2-shadowed.md Apr 22 section.
                            if (_dc_tier == "decided_contract_t2_z2"
                                    and asset in ("BTC", "ETH")
                                    and _dc_balance and _dc_balance > 0):
                                _p1_dedup = (ticker, "dc_t2_z2_phase1_shadow")
                                if _p1_dedup not in self._eval_opp_seen:
                                    self._eval_opp_seen.add(_p1_dedup)
                                    _p1_position = max(1, int((_dc_balance * DC_T2_Z2_PHASE1_RISK) / best_ask))
                                    try:
                                        self._state.insert_evaluated_opportunity(
                                            ticker, window["event_ticker"], asset,
                                            "dc_t2_z2_phase1_shadow",
                                            rejection_reason=f"phase1 sim: BTC+ETH {int(DC_T2_Z2_PHASE1_RISK*100)}% sizing pos={_p1_position} @ {best_ask}c",
                                            spot_price=spot, threshold=threshold,
                                            volatility=blended_rv, market_price=best_ask,
                                            seconds_to_close=seconds_remaining,
                                            calibrated_prob=final_prob, edge=edge,
                                            ofa_adjustment=ofa_adjustment,
                                            z_score=z_score,
                                            vol_regime=vol_est["regime"],
                                            calibrated_prob_raw=calibrated_prob_raw,
                                            kelly_f=_dc_kelly_f,
                                            position_size=_p1_position,
                                            breakeven_wr=best_ask / 100.0,
                                            expected_value=_dc_ev,
                                            ask_depth=ask_depth,
                                            best_ask_source=best_ask_source,
                                            raw_prob=raw_prob,
                                            calibration_method=calibration_method,
                                            fee_adjusted_edge=fee_adjusted_edge,
                                            product_type=window.get("product_type"),
                                            **_shadow_diag)
                                    except Exception:
                                        logging.warning("insert_evaluated_opportunity failed (dc_t2_z2_phase1_shadow)", exc_info=True)

                            # ── Live overlay: queue as candidate if tier enabled ──
                            _dc_live_enabled = (
                                (_dc_tier == "decided_contract_t1" and DECIDED_T1_ENABLED)
                                or (_dc_tier == "decided_contract_t1b" and DECIDED_T1B_ENABLED)
                                or (_dc_tier == "decided_contract_t2" and DECIDED_T2_ENABLED)
                                or (_dc_tier == "decided_contract_t2_z25" and DECIDED_T2_Z25_ENABLED)
                                or (_dc_tier == "decided_contract_t2_z2" and DECIDED_T2_Z2_ENABLED))
                            if (_dc_live_enabled
                                    and not OBSERVATION_MODE
                                    and _dc_balance and _dc_balance > 0
                                    and _dc_position and _dc_position > 0):
                                # Per-window risk cap: 25% bankroll across all DC signals
                                _dc_wkey = window["event_ticker"]
                                _dc_existing_risk = self._dc_window_risk.get(_dc_wkey, 0.0)
                                _dc_this_cost = _dc_position * best_ask
                                _dc_max_cost = _dc_balance * DECIDED_CONTRACT_MAX_WINDOW_RISK
                                if _dc_existing_risk + _dc_this_cost > _dc_max_cost:
                                    # Reduce position to fit within cap
                                    _dc_remaining = _dc_max_cost - _dc_existing_risk
                                    if _dc_remaining >= best_ask:
                                        _dc_position = max(1, int(_dc_remaining / best_ask))
                                        _dc_this_cost = _dc_position * best_ask
                                    else:
                                        # Window cap exceeded — log skip and don't trade
                                        _dc_skip_dedup = (ticker, "decided_window_cap_skip")
                                        if _dc_skip_dedup not in self._eval_opp_seen:
                                            self._eval_opp_seen.add(_dc_skip_dedup)
                                            try:
                                                self._state.insert_evaluated_opportunity(
                                                    ticker, window["event_ticker"], asset,
                                                    "decided_window_cap_skip",
                                                    rejection_reason=f"window cap: existing={_dc_existing_risk:.0f}c max={_dc_max_cost:.0f}c tier={_dc_tier}",
                                                    spot_price=spot, threshold=threshold,
                                                    volatility=blended_rv, market_price=best_ask,
                                                    seconds_to_close=seconds_remaining,
                                                    calibrated_prob=final_prob, edge=edge,
                                                    z_score=z_score,
                                                    vol_regime=vol_est["regime"],
                                                    raw_prob=raw_prob,
                                                    fee_adjusted_edge=fee_adjusted_edge,
                                                    product_type=window.get("product_type"),
                                                    **_shadow_diag)
                                            except Exception:
                                                logging.warning("insert_evaluated_opportunity failed (decided_window_cap_skip)", exc_info=True)
                                        self._dc_window_cap_skips += 1
                                        logging.info("DC_WINDOW_CAP: %s %s skipped (existing=%.0fc max=%.0fc)",
                                                     _dc_tier, ticker, _dc_existing_risk, _dc_max_cost)
                                        _dc_live_enabled = False  # skip candidate below

                                # Cap by existing exposure on same ticker
                                if _dc_live_enabled:
                                    _dc_existing_exposure = 0
                                    if STACKING_ENABLED:
                                        from models import strategy_to_group
                                        for pos in self._state.get_open_positions():
                                            if pos["ticker"] == ticker and \
                                               pos.get("strategy_group",
                                                   strategy_to_group(pos.get("strategy"))) == "decided":
                                                _dc_existing_exposure += pos["count"]
                                                break
                                    else:
                                        for pos in self._state.get_open_positions():
                                            if pos["ticker"] == ticker:
                                                _dc_existing_exposure += pos["count"]
                                                break
                                        for resting in self._state.get_resting_orders(ticker=ticker):
                                            _dc_existing_exposure += resting["count"]
                                    if _dc_existing_exposure > 0:
                                        _dc_position = max(0, _dc_position - _dc_existing_exposure)

                                if _dc_live_enabled and _dc_position > 0:
                                    # Cooldown: skip if this ticker was recently skipped due to "no asks"
                                    if ticker in self._dc_skip_cooldown and time.time() < self._dc_skip_cooldown[ticker]:
                                        _dc_live_enabled = False
                                if _dc_live_enabled and _dc_position > 0:
                                    _dc_strat = {"decided_contract_t1": "decided_t1",
                                                 "decided_contract_t1b": "decided_t1b",
                                                 "decided_contract_t2": "decided_t2",
                                                 "decided_contract_t2_z25": "decided_t2_z25",
                                                 "decided_contract_t2_z2": "decided_t2_z2"}[_dc_tier]
                                    self._dc_window_risk[_dc_wkey] = _dc_existing_risk + _dc_position * best_ask
                                    logging.info("DC_CANDIDATE: %s %s %dx@%dc z=%.1f stc=%.0fs",
                                                 _dc_strat, ticker, _dc_position, best_ask, z_score, seconds_remaining)
                                    candidates.append({
                                        "ticker": ticker,
                                        "event_ticker": window["event_ticker"],
                                        "asset": asset,
                                        "product_type": window.get("product_type"),
                                        "spot": spot,
                                        "threshold": threshold,
                                        "seconds_to_close": round(seconds_remaining, 1),
                                        "blended_rv": blended_rv,
                                        "calibrated_prob": round(_dc_assumed_p, 6),
                                        "z_score": z_score,
                                        "best_yes_ask": best_ask,
                                        "best_ask_source": best_ask_source,
                                        "edge": round(_dc_assumed_p - best_ask / 100.0, 6),
                                        "position_size": _dc_position,
                                        "kelly_f": _dc_kelly_f,
                                        "drawdown_scaler": 1.0,
                                        "vol_regime": vol_est["regime"],
                                        "balance_at_scan": _dc_balance,
                                        "strategy": _dc_strat,
                                        "strategy_scores": {"certainty": 1.0, "certainty_detail": "decided",
                                                            "orderbook": 0.5, "orderbook_detail": "n/a",
                                                            "urgency": 1.0, "urgency_detail": "decided",
                                                            "composite": 1.0, "reason": "decided_contract"},
                                        "ob_snapshot": {
                                            "best_ask": best_ask,
                                            "ask_depth": ask_depth,
                                            "total_depth": total_depth,
                                            "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                                            "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                                            "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                                      if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                                        },
                                        "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                                        "ofa_adjustment": round(ofa_adjustment, 6),
                                        "ofa_confidence": ofa_signals["confidence"] if ofa_signals else "none",
                                        "raw_prob": raw_prob,
                                        "calibration_method": calibration_method,
                                        "old_system_prob": round(_old_system_prob, 6),
                                        "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                        **_shadow_diag,
                                        **_shadow_extra,
                                    })

                    # ── DC Shadow z-score expansion (edge-dependent) ─────────
                    # These two variants target z-scores near -2 to -2.5 where
                    # edge is genuinely insufficient. They correctly live here.
                    if (DECIDED_CONTRACT_SHADOW
                            and _pt in (None, "15m")
                            and z_score is not None
                            and seconds_remaining < DECIDED_CONTRACT_MAX_STC):
                        def _dc_shadow_insert(stage, rej_detail):
                            _dcs_dedup = (ticker, stage)
                            if _dcs_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dcs_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset, stage,
                                        rejection_reason=rej_detail,
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score,
                                        vol_regime=vol_est["regime"],
                                        raw_prob=raw_prob,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        product_type=window.get("product_type"),
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (%s)", stage, exc_info=True)

                        # T2 z≤-2.5 at 93-96c (loosening from z≤-3)
                        if (DECIDED_CONTRACT_Z_T2 < z_score <= -2.5
                                and 93 <= best_ask <= DECIDED_CONTRACT_T2_MAX_PRICE):
                            _dc_shadow_insert("dc_shadow_t2_z25",
                                              f"shadow: z={z_score:.1f} price={best_ask}c (T2 z≤-2.5 expansion)")

                        # T2 z≤-1.5 at 93-96c (shadow for next expansion beyond live -1.75)
                        if (DECIDED_CONTRACT_Z_T2_Z2 < z_score <= -1.5
                                and 93 <= best_ask <= DECIDED_CONTRACT_T2_MAX_PRICE):
                            _dc_shadow_insert("dc_shadow_t2_z2",
                                              f"shadow: z={z_score:.1f} price={best_ask}c (T2 z≤-1.5 expansion)")

                    # ── HOURLY DECIDED CONTRACTS ──────────────────────────────
                    # Same DC thesis on hourly BTC tickers. Separate from sub-60c.
                    # Conservative: z≤-4, 93-96c, BTC only, sigma gate, 1 per window.
                    if (_pt == "hourly"
                            and HOURLY_DC_ENABLED
                            and asset in HOURLY_DC_ASSETS
                            and z_score is not None
                            and z_score <= HOURLY_DC_Z_THRESHOLD
                            and best_ask >= HOURLY_DC_MIN_PRICE
                            and best_ask <= HOURLY_DC_MAX_PRICE):
                        # Sigma gate: block cold-RK false signals
                        _hdc_sigma = vol_est.get("egarch_sigma") if vol_est else None
                        if _hdc_sigma is not None and _hdc_sigma >= HOURLY_DC_MIN_SIGMA:
                            _hdc_dedup = (ticker, "hourly_dc")
                            if _hdc_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_hdc_dedup)
                                _hdc_ev = round((HOURLY_DC_ASSUMED_PROB * (100 - best_ask))
                                                - ((1 - HOURLY_DC_ASSUMED_PROB) * best_ask) - est_fee_1c, 2)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset, "hourly_dc",
                                        spot_price=spot, threshold=threshold, volatility=blended_rv,
                                        market_price=best_ask, seconds_to_close=seconds_remaining,
                                        calibrated_prob=HOURLY_DC_ASSUMED_PROB, edge=HOURLY_DC_ASSUMED_PROB - best_ask / 100.0,
                                        z_score=z_score, vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                        fee_adjusted_edge=HOURLY_DC_ASSUMED_PROB - best_ask / 100.0 - est_fee_1c / 100.0,
                                        breakeven_wr=best_ask / 100.0, expected_value=_hdc_ev,
                                        ask_depth=ask_depth, best_ask_source=best_ask_source,
                                        position_size=HOURLY_DC_CONTRACTS,
                                        product_type="hourly",
                                        **_oft_db, **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (hourly_dc)", exc_info=True)

                                # Shadow only — 87% WR at 93-96c is below breakeven.
                                # Keep logging for comparison data but never execute.
                                # (Execution path removed Mar 25 — was live but never fired)

                    # ── HOURLY DC SHADOW: 97c+ z≤-3 STC≤600s ──────────────────
                    # New variant targeting the profitable zone. Data: 37/37 (100% WR)
                    # at z≤-3, STC≤600s, price≥97c, sig≥250 over 23 days.
                    # All 12 losses in the broader z≤-3 97c+ pool were at STC>600s.
                    # Runs alongside existing hourly DC shadow — separate evaluation.
                    if (_pt == "hourly"
                            and HOURLY_DC_ENABLED
                            and z_score is not None
                            and z_score <= -3.0
                            and best_ask >= 97
                            and best_ask <= 99
                            and seconds_remaining <= 600):
                        _hdc2_sigma = vol_est.get("egarch_sigma") if vol_est else None
                        if _hdc2_sigma is not None and _hdc2_sigma >= HOURLY_DC_MIN_SIGMA:
                            _hdc2_dedup = (ticker, "hourly_dc_97c_stc600")
                            if _hdc2_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_hdc2_dedup)
                                _hdc2_ev = round((0.99 * (100 - best_ask))
                                                 - (0.01 * best_ask) - est_fee_1c, 2)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "hourly_dc_97c_stc600",
                                        rejection_reason=f"shadow: z={z_score:.1f} price={best_ask}c stc={seconds_remaining:.0f}s sig={_hdc2_sigma:.6f}",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=0.99,
                                        edge=round(0.99 - best_ask / 100.0, 6),
                                        z_score=z_score, vol_regime=vol_est["regime"],
                                        raw_prob=raw_prob,
                                        fee_adjusted_edge=round(0.99 - best_ask / 100.0 - est_fee_1c / 100.0, 6),
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_hdc2_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        position_size=25,
                                        product_type="hourly",
                                        egarch_sigma=_hdc2_sigma,
                                        **_oft_db)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (hourly_dc_97c_stc600)", exc_info=True)

                    # ── HOURLY DC SHADOW TIER 2: 93-96c z≤-3 STC≤300s ────────
                    # Data: 8/8 (100% WR) at z≤-3, STC≤300s, 93-96c, sig≥250.
                    # All 10 losses in the broader 93-96c pool are at STC>300s.
                    # Does NOT overlap with Tier 1 (97c+): only fires on 93-96c.
                    if (_pt == "hourly"
                            and HOURLY_DC_ENABLED
                            and z_score is not None
                            and z_score <= -3.0
                            and best_ask >= 93
                            and best_ask <= 96
                            and seconds_remaining <= 300):
                        _hdc3_sigma = vol_est.get("egarch_sigma") if vol_est else None
                        if _hdc3_sigma is not None and _hdc3_sigma >= HOURLY_DC_MIN_SIGMA:
                            _hdc3_dedup = (ticker, "hourly_dc_93c_stc300")
                            if _hdc3_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_hdc3_dedup)
                                _hdc3_assumed = 0.97
                                _hdc3_ev = round((_hdc3_assumed * (100 - best_ask))
                                                 - ((1 - _hdc3_assumed) * best_ask) - est_fee_1c, 2)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "hourly_dc_93c_stc300",
                                        rejection_reason=f"shadow: z={z_score:.1f} price={best_ask}c stc={seconds_remaining:.0f}s sig={_hdc3_sigma:.6f}",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=_hdc3_assumed,
                                        edge=round(_hdc3_assumed - best_ask / 100.0, 6),
                                        z_score=z_score, vol_regime=vol_est["regime"],
                                        raw_prob=raw_prob,
                                        fee_adjusted_edge=round(_hdc3_assumed - best_ask / 100.0 - est_fee_1c / 100.0, 6),
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_hdc3_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        position_size=25,
                                        product_type="hourly",
                                        egarch_sigma=_hdc3_sigma,
                                        **_oft_db)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (hourly_dc_93c_stc300)", exc_info=True)

                    # ── SPX DECIDED CONTRACTS SHADOW ──────────────────────────
                    # Shadow-only: log signals, never trade. Mon-Wed, z≤-3, 93-96c.
                    # 1-week validation before promotion. No sigma gate (SPX EGARCH
                    # produces sigma=0 on 97% of signals — z-score still valid via
                    # raw spot-vs-strike distance).
                    if (_pt == "spx_hourly"
                            and SPX_DC_SHADOW_ENABLED
                            and z_score is not None
                            and z_score <= SPX_DC_Z_THRESHOLD
                            and best_ask >= SPX_DC_MIN_PRICE
                            and best_ask <= SPX_DC_MAX_PRICE):
                        # Day-of-week filter: Mon-Wed only (all 6 losses were Thu-Fri)
                        import datetime as _dt
                        _spx_dc_day = _dt.datetime.now(_dt.timezone.utc).weekday()
                        if _spx_dc_day in SPX_DC_VALID_DAYS:
                            _spx_dc_dedup = (ticker, "spx_dc_shadow")
                            if _spx_dc_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_spx_dc_dedup)
                                _spx_dc_sigma = vol_est.get("egarch_sigma") if vol_est else None
                                _spx_dc_spot = spot
                                _spx_dc_thresh = threshold
                                _spx_dc_dist = abs(_spx_dc_spot - _spx_dc_thresh) if _spx_dc_spot and _spx_dc_thresh else None
                                _spx_dc_dist_pct = (_spx_dc_dist / _spx_dc_spot * 100) if _spx_dc_dist and _spx_dc_spot else None
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset, "spx_dc_shadow",
                                        spot_price=spot, threshold=threshold, volatility=blended_rv,
                                        market_price=best_ask, seconds_to_close=seconds_remaining,
                                        calibrated_prob=0.97, edge=0.97 - best_ask / 100.0,
                                        z_score=z_score, vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                        fee_adjusted_edge=0.97 - best_ask / 100.0 - est_fee_1c / 100.0,
                                        breakeven_wr=best_ask / 100.0,
                                        ask_depth=ask_depth, best_ask_source=best_ask_source,
                                        product_type="spx_hourly",
                                        **_oft_db, **_shadow_diag)
                                    logging.info(
                                        "SPX_DC_SHADOW: %s %dc z=%.1f sig=%s spot=%.1f thresh=%.1f dist=$%.0f (%.2f%%) stc=%.0f day=%d",
                                        ticker, best_ask, z_score,
                                        f"{_spx_dc_sigma:.6f}" if _spx_dc_sigma else "0",
                                        _spx_dc_spot or 0, _spx_dc_thresh or 0,
                                        _spx_dc_dist or 0, _spx_dc_dist_pct or 0,
                                        seconds_remaining, _spx_dc_day)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (spx_dc_shadow)", exc_info=True)

                    # ── Relaxed Edge Shadow (Fix #1) ──────────────────────────
                    # Edge thresholds at 88-93c may be too conservative.
                    # Data: insufficient_edge rejections at 88c=97.2% WR, 89c=93.3%,
                    # 91c=94.4% — all well above breakeven. Shadow with halved thresholds.
                    if (RELAXED_EDGE_SHADOW
                            and _pt in (None, "15m")
                            and best_ask >= RELAXED_EDGE_MIN_PRICE
                            and best_ask < RELAXED_EDGE_MAX_PRICE):
                        _rel_min_edge = _min_edge * RELAXED_EDGE_DISCOUNT
                        if fee_adjusted_edge >= _rel_min_edge:
                            _rel_balance = self._get_balance_cached()
                            _rel_position = None
                            _rel_kelly_f = None
                            _rel_ev = None
                            if _rel_balance and _rel_balance > 0:
                                _rel_sizing = self._sizer.compute(final_prob, best_ask, _rel_balance)
                                _rel_kelly_f = _rel_sizing["kelly_f"]
                                _rel_position = _rel_sizing["contracts"]
                                _rel_scfg = get_market_config(window.get("product_type"))
                                if _rel_scfg.kelly_fraction < 1.0:
                                    _rel_position = max(1, int(_rel_position * _rel_scfg.kelly_fraction))
                                _rel_type_max = int((_rel_balance * _rel_scfg.max_risk_per_trade) / best_ask)
                                if _rel_position > _rel_type_max:
                                    _rel_position = max(1, _rel_type_max)
                                _rel_ev = round((final_prob * (100 - best_ask))
                                                - ((1 - final_prob) * best_ask) - est_fee_1c, 2)

                            _rel_dedup = (ticker, "relaxed_edge_shadow")
                            if _rel_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_rel_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "relaxed_edge_shadow",
                                        rejection_reason=f"shadow: edge {fee_adjusted_edge:.4f} >= relaxed {_rel_min_edge:.4f} (orig {_min_edge:.4f} x {RELAXED_EDGE_DISCOUNT})",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score,
                                        vol_regime=vol_est["regime"],
                                        calibrated_prob_raw=calibrated_prob_raw,
                                        kelly_f=_rel_kelly_f,
                                        position_size=_rel_position,
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=_rel_ev,
                                        ask_depth=ask_depth,
                                        best_ask_source=best_ask_source,
                                        raw_prob=raw_prob,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        product_type=window.get("product_type"),
                                        **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (relaxed_edge_shadow)", exc_info=True)

                    continue

                # Compute position size via Kelly criterion
                balance = self._get_balance_cached()
                if balance is None or balance <= 0:
                    continue
                # Capital allocator: per-strategy budget (defaults to full balance)
                _strategy_key = window.get("product_type") or "crypto_15m"
                if _strategy_key == "15m":
                    _strategy_key = "crypto_15m"
                elif _strategy_key == "hourly":
                    _strategy_key = "crypto_hourly"
                _sizing_balance = balance
                # Product-specific bankroll fractions: size off a virtual sub-bankroll
                # so secondary products can never reduce 15M's available capital
                if _pt == "spx_hourly":
                    _sizing_balance = int(balance * SPX_HOURLY_BANKROLL_FRACTION)
                    if _sizing_balance <= 0:
                        _sizing_balance = 1  # safety: never zero
                elif _pt == "hourly":
                    _sizing_balance = int(balance * HOURLY_BANKROLL_FRACTION)
                    if _sizing_balance <= 0:
                        _sizing_balance = 1
                elif self._ml and getattr(self._ml, "capital_allocator", None):
                    try:
                        _sizing_balance = self._ml.capital_allocator.get_budget_cents(
                            _strategy_key, balance, locked_by_strategy=None)
                        if _sizing_balance <= 0:
                            _sizing_balance = balance  # fallback: never zero out live trading
                    except Exception:
                        _sizing_balance = balance
                _sizing_start = time.perf_counter()
                sizing = self._sizer.compute(final_prob, best_ask, _sizing_balance)
                _sizing_dt = time.perf_counter() - _sizing_start
                if _sizing_dt > 0.2:
                    logging.warning(
                        "SCAN_SIZING_SLOW: asset=%s ticker=%s took %.2fs",
                        asset, ticker, _sizing_dt)

                # Product-type-specific sizing: fractional Kelly + conservative per-trade risk cap
                _scfg = get_market_config(window.get("product_type"))
                if _pt == "hourly":
                    # Hourly: fixed 10-contract sizing — bypass Kelly entirely
                    sizing["contracts"] = HOURLY_FIXED_CONTRACTS
                elif _scfg.kelly_fraction < 1.0:
                    _full_kelly_contracts = sizing["contracts"]
                    sizing["contracts"] = max(1, int(sizing["contracts"] * _scfg.kelly_fraction))
                    _type_max = int((_sizing_balance * _scfg.max_risk_per_trade) / best_ask)
                    if sizing["contracts"] > _type_max:
                        sizing["contracts"] = max(1, _type_max)

                # Asset-specific risk caps (15M only — hourly has fixed sizing)
                # DC candidates don't flow through this code path (separate sizing at line 8231).
                if asset == "XRP" and _pt in (None, "15m"):
                    _xrp_max = int((_sizing_balance * XRP_MAX_RISK_PER_TRADE) / best_ask)
                    if sizing["contracts"] > _xrp_max >= 1:
                        logging.info("ASSET_CAP: XRP raw=%d capped=%d balance=$%.2f",
                                     sizing["contracts"], _xrp_max, _sizing_balance / 100)
                        sizing["contracts"] = _xrp_max
                elif asset == "BTC" and _pt in (None, "15m"):
                    _btc_max = int((_sizing_balance * BTC_MAX_RISK_PER_TRADE) / best_ask)
                    if sizing["contracts"] > _btc_max >= 1:
                        logging.info("ASSET_CAP: BTC raw=%d capped=%d balance=$%.2f",
                                     sizing["contracts"], _btc_max, _sizing_balance / 100)
                        sizing["contracts"] = _btc_max
                elif asset == "SOL" and _pt in (None, "15m"):
                    _sol_max = int((_sizing_balance * SOL_MAX_RISK_PER_TRADE) / best_ask)
                    if sizing["contracts"] > _sol_max >= 1:
                        logging.info("ASSET_CAP: SOL raw=%d capped=%d balance=$%.2f",
                                     sizing["contracts"], _sol_max, _sizing_balance / 100)
                        sizing["contracts"] = _sol_max
                elif asset == "ETH" and _pt in (None, "15m"):
                    _eth_max = int((_sizing_balance * ETH_MAX_RISK_PER_TRADE) / best_ask)
                    if sizing["contracts"] > _eth_max >= 1:
                        logging.info("ASSET_CAP: ETH raw=%d capped=%d balance=$%.2f",
                                     sizing["contracts"], _eth_max, _sizing_balance / 100)
                        sizing["contracts"] = _eth_max

                # ETH sub-80c position cap: clamp to [20, 50] contracts
                # Half-Kelly at 75c/87% WR = 322-645 contracts — uncapped is reckless.
                # Cap at 50 (half-Kelly ceiling), floor at 20 (minimum meaningful size).
                # Will right-size from orderbook depth data after 1 week.
                if (asset == "ETH" and _pt in (None, "15m") and best_ask < 80):
                    _eth_sub80_capped = max(20, min(ETH_SUB80_POSITION_CAP, sizing["contracts"]))
                    if _eth_sub80_capped != sizing["contracts"]:
                        logging.info("ETH sub-80c clamp: %d -> %d contracts (ask=%dc, cap=%d)",
                                     sizing["contracts"], _eth_sub80_capped, best_ask, ETH_SUB80_POSITION_CAP)
                        sizing["contracts"] = _eth_sub80_capped

                # Low-STC sizing cap: halve position when STC < 100s
                # Data: 0-100s STC is -$84/14d (12W/2L, catastrophic losses wipe gains)
                if (_pt in (None, "15m") and seconds_remaining < LOW_STC_SIZING_CAP_THRESHOLD
                        and LOW_STC_SIZING_CAP < 1.0 and sizing["contracts"] > 0):
                    _pre_stc_cap = sizing["contracts"]
                    sizing["contracts"] = max(1, int(sizing["contracts"] * LOW_STC_SIZING_CAP))
                    if sizing["contracts"] < _pre_stc_cap:
                        logging.info("Low-STC cap: %d -> %d contracts (STC=%.0fs, cap=%.1fx)",
                                     _pre_stc_cap, sizing["contracts"], seconds_remaining, LOW_STC_SIZING_CAP)

                # High-STC sizing scaler: reduce position for far-from-expiry trades
                # Data: 3-5m 94.6% WR (+$667), 5-7m 90.8% (+$35), 7m+ net negative
                # Scaler: 300/STC — monotonic, one parameter, no trades cut
                if (STC_SIZING_SCALER_ENABLED
                        and _pt in (None, "15m")
                        and seconds_remaining > STC_SIZING_SCALER_KNEE
                        and sizing["contracts"] > 0):
                    _stc_scaler = STC_SIZING_SCALER_KNEE / seconds_remaining
                    _pre_stc_scale = sizing["contracts"]
                    sizing["contracts"] = max(1, int(sizing["contracts"] * _stc_scaler))
                    if sizing["contracts"] < _pre_stc_scale:
                        logging.info("STC_SCALER: %d -> %d contracts (STC=%.0fs, scaler=%.2fx)",
                                     _pre_stc_scale, sizing["contracts"], seconds_remaining, _stc_scaler)

                # Buffer-aware sizing: scale contracts by spot buffer at entry
                # (infrastructure — disabled until PPO data matures, ~10+ losses)
                _spot_buffer_pct = None
                if threshold and threshold > 0:
                    _spot_buffer_pct = (spot - threshold) / threshold * 100
                if (BUFFER_SIZING_ENABLED
                        and _pt in (None, "15m")
                        and _spot_buffer_pct is not None
                        and sizing["contracts"] > 0):
                    _buf_mult = buffer_sizing_multiplier(_spot_buffer_pct)
                    _pre_buf = sizing["contracts"]
                    sizing["contracts"] = max(1, int(sizing["contracts"] * _buf_mult))
                    if sizing["contracts"] != _pre_buf:
                        logging.info("BUFFER_SIZING: %d -> %d contracts (buf=%.3f%%, mult=%.2fx)",
                                     _pre_buf, sizing["contracts"], _spot_buffer_pct, _buf_mult)

                # Cap by existing exposure (positions + resting orders) to prevent
                # accumulation across scan ticks on the same ticker
                existing_exposure = 0
                for pos in self._state.get_open_positions():
                    if pos["ticker"] == ticker:
                        existing_exposure += pos["count"]
                        break
                for resting in self._state.get_resting_orders(ticker=ticker):
                    existing_exposure += resting["count"]
                if existing_exposure > 0:
                    sizing["contracts"] = max(0, sizing["contracts"] - existing_exposure)

                if sizing["contracts"] <= 0:
                    scan_stats[asset]["zero_sizing"] += 1
                    self._recent_opportunities.append({
                        "ticker": ticker, "asset": asset,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "best_ask": best_ask,
                        "edge_bps": round(edge * 10000),
                        "chosen_strategy": None,
                        "rejection_reason": "zero_sizing",
                        "ts": datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                    })
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "zero_sizing",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": "position sizing yielded 0 contracts",
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": best_ask,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(final_prob, 6),
                            "edge": round(edge, 6),
                            "ofa_adjustment": round(ofa_adjustment, 6),
                            "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                            "old_system_prob": round(_old_system_prob, 6),
                            "counterfactual": _cf,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                        _dedup_key = (ticker, "zero_sizing")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            _dbw_start = time.perf_counter()
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "zero_sizing",
                                rejection_reason="0 contracts from sizing",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge,
                                ofa_adjustment=ofa_adjustment,
                                z_score=z_score,
                                vol_regime=vol_est["regime"],
                                calibrated_prob_raw=calibrated_prob_raw,
                                kelly_f=sizing["kelly_f"],
                                position_size=0,
                                breakeven_wr=best_ask / 100.0,
                                expected_value=round(_ev, 2),
                                drawdown_scaler=sizing["drawdown_scaler"],
                                ask_depth=ask_depth,
                                best_ask_source=best_ask_source,
                                ofa_confidence=ofa_signals["confidence"] if ofa_signals else "none",
                                raw_prob=raw_prob,
                                calibration_method=calibration_method,
                                old_system_prob=_old_system_prob,
                                fee_adjusted_edge=fee_adjusted_edge,
                                counterfactual=_cf_json,
                                shadow_cal_prob=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("prob") if _cf else None,
                                shadow_cal_fee_edge=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("fee_edge") if _cf else None,
                                shadow_cal_temperature=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("temperature") if _cf else None,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                                **_oft_db, **_shadow_diag)
                            _dbw_dt = time.perf_counter() - _dbw_start
                            if _dbw_dt > 0.2:
                                logging.warning(
                                    "SCAN_DBWRITE_SLOW: zero_sizing "
                                    "insert ticker=%s took %.2fs",
                                    ticker, _dbw_dt)
                    except Exception:
                        logging.warning("insert_evaluated_opportunity failed (spx/weather observation)", exc_info=True)
                    continue

                # Evaluate execution strategy for this market
                strategy_data = {
                    "z_score": z_score,
                    "calibrated_prob": final_prob,
                    "spot": spot,
                    "threshold": threshold,
                    "seconds_to_close": seconds_remaining,
                    "blended_rv": blended_rv,
                    "vol_regime": vol_est["regime"],
                    "best_yes_ask": best_ask,
                    "best_ask_depth": ask_depth,
                    "total_ob_depth": total_depth,
                    "convergence_velocity": self._scanner_convergence_velocity(ticker),
                    "edge": edge,
                    "min_entry_price": _entry_floor,
                    "max_entry_price": _entry_ceil,
                }
                strategy, strategy_scores = evaluate_execution_strategy(
                    strategy_data
                )
                if strategy in self._session_strategy_counts:
                    self._session_strategy_counts[strategy] += 1

                # Log strategy evaluation for every market evaluated
                self._logger.log_scan({
                    "type": "strategy_eval",
                    "ticker": ticker,
                    "asset": asset,
                    "seconds_to_close": round(seconds_remaining, 1),
                    "spot": spot,
                    "threshold": threshold,
                    "best_yes_ask": best_ask,
                    "edge": round(edge, 6),
                    "outcome_certainty_score": strategy_scores["certainty"],
                    "outcome_certainty_detail": strategy_scores["certainty_detail"],
                    "orderbook_state_score": strategy_scores["orderbook"],
                    "orderbook_state_detail": strategy_scores["orderbook_detail"],
                    "urgency_score": strategy_scores["urgency"],
                    "urgency_detail": strategy_scores["urgency_detail"],
                    "composite_score": strategy_scores["composite"],
                    "chosen_strategy": strategy,
                    "reason": strategy_scores["reason"],
                    "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                    "ofa_adjustment": round(ofa_adjustment, 6),
                    "ofa_confidence": ofa_signals["confidence"] if ofa_signals else "none",
                    "ofa_adjustments_applied": ofa_signals["adjustments_applied"] if ofa_signals else [],
                })

                if strategy == STRATEGY_WAIT:
                    scan_stats[asset]["strategy_wait"] += 1
                    self._recent_opportunities.append({
                        "ticker": ticker, "asset": asset,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "best_ask": best_ask,
                        "edge_bps": round(edge * 10000),
                        "chosen_strategy": "WAIT",
                        "rejection_reason": "strategy_wait",
                        "ts": datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                    })
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "strategy_wait",
                            "ticker": ticker,
                            "event_ticker": window["event_ticker"],
                            "asset": asset,
                            "rejection_reason": "strategy engine returned WAIT",
                            "spot_price": spot,
                            "threshold": threshold,
                            "volatility": blended_rv,
                            "market_price": best_ask,
                            "seconds_to_close": round(seconds_remaining, 1),
                            "calibrated_prob": round(final_prob, 6),
                            "edge": round(edge, 6),
                            "ofa_adjustment": round(ofa_adjustment, 6),
                            "composite_score": strategy_scores.get("composite"),
                            "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                            "old_system_prob": round(_old_system_prob, 6),
                            "counterfactual": _cf,
                            **_shadow_diag,
                            **_shadow_extra,
                        })
                        _dedup_key = (ticker, "strategy_wait")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "strategy_wait",
                                rejection_reason="WAIT strategy",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge,
                                ofa_adjustment=ofa_adjustment,
                                strategy=strategy,
                                z_score=z_score,
                                vol_regime=vol_est["regime"],
                                calibrated_prob_raw=calibrated_prob_raw,
                                kelly_f=sizing["kelly_f"],
                                position_size=sizing["contracts"],
                                breakeven_wr=best_ask / 100.0,
                                expected_value=round(_ev, 2),
                                drawdown_scaler=sizing["drawdown_scaler"],
                                ask_depth=ask_depth,
                                best_ask_source=best_ask_source,
                                ofa_confidence=ofa_signals["confidence"] if ofa_signals else "none",
                                raw_prob=raw_prob,
                                calibration_method=calibration_method,
                                old_system_prob=_old_system_prob,
                                fee_adjusted_edge=fee_adjusted_edge,
                                counterfactual=_cf_json,
                                shadow_cal_prob=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("prob") if _cf else None,
                                shadow_cal_fee_edge=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("fee_edge") if _cf else None,
                                shadow_cal_temperature=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("temperature") if _cf else None,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                                **_oft_db, **_shadow_diag)
                    except Exception:
                        logging.warning("insert_evaluated_opportunity failed (strategy_wait)", exc_info=True)
                    # For observation-only product types, let signal flow through
                    # to observation gate — strategy timing isn't relevant for
                    # data collection.  strategy_wait is still logged above for
                    # counterfactual analysis.
                    _sw_cfg = get_market_config(window.get("product_type"))
                    if not _sw_cfg.observation_only:
                        continue
                    # else: fall through to config-driven filters → observation gate

                # ── Config-driven per-window filters (any market type can opt in) ──
                _fltcfg = get_market_config(window.get("product_type"))
                _flt_pt = _fltcfg.product_type

                # Layer 3a: Asset exclusion (config-driven)
                if _fltcfg.excluded_assets and asset in _fltcfg.excluded_assets:
                    _dedup_key = (ticker, f"{_flt_pt}_asset_excluded")
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset, f"{_flt_pt}_asset_excluded",
                            spot_price=spot, threshold=threshold, volatility=blended_rv,
                            market_price=best_ask, seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge, z_score=z_score,
                            vol_regime=vol_est["regime"], raw_prob=raw_prob,
                            calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                            breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                            ask_depth=ask_depth, best_ask_source=best_ask_source,
                            product_type=window.get("product_type"),
                            hourly_pre_temp_prob=_hourly_pre_temp_prob,
                            hourly_applied_temp_t=_configured_temp_t,
                            hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                            hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                            hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                            hourly_shadow_blend_50=_hourly_shadow_blend_50,
                            hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                            hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                            hourly_shadow_blend_20=_hourly_shadow_blend_20,
                            hourly_shadow_blend_30=_hourly_shadow_blend_30,
                            hourly_shadow_blend_60=_hourly_shadow_blend_60,
                            hourly_post_temp_prob=_hourly_post_temp_prob,
                            **_oft_db, **_shadow_diag)
                    continue

                # Layer 2: STC timing restriction (config-driven)
                if (_fltcfg.min_stc_entry is not None
                        and (seconds_remaining < _fltcfg.min_stc_entry
                             or seconds_remaining > _fltcfg.max_stc_entry)):
                    _dedup_key = (ticker, f"{_flt_pt}_timing_restricted")
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset, f"{_flt_pt}_timing_restricted",
                            spot_price=spot, threshold=threshold, volatility=blended_rv,
                            market_price=best_ask, seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge, z_score=z_score,
                            vol_regime=vol_est["regime"], raw_prob=raw_prob,
                            calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                            breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                            ask_depth=ask_depth, best_ask_source=best_ask_source,
                            product_type=window.get("product_type"),
                            wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                            wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                            wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                            wx_n_members=_shadow_extra.get("wx_n_members"),
                            wx_market_type=_shadow_extra.get("wx_market_type"),
                            wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                            wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                            wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                            hourly_pre_temp_prob=_hourly_pre_temp_prob,
                            hourly_applied_temp_t=_configured_temp_t,
                            hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                            hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                            hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                            hourly_shadow_blend_50=_hourly_shadow_blend_50,
                            hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                            hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                            hourly_shadow_blend_20=_hourly_shadow_blend_20,
                            hourly_shadow_blend_30=_hourly_shadow_blend_30,
                            hourly_shadow_blend_60=_hourly_shadow_blend_60,
                            hourly_post_temp_prob=_hourly_post_temp_prob,
                            **_oft_db, **_shadow_diag)
                    continue

                # Layer 3b: Per-window position limit (config-driven)
                if _fltcfg.max_positions_per_window is not None:
                    _wkey = window["event_ticker"]
                    if self._hourly_window_counts.get(_wkey, 0) >= _fltcfg.max_positions_per_window:
                        _dedup_key = (ticker, f"{_flt_pt}_window_limit")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset, f"{_flt_pt}_window_limit",
                                spot_price=spot, threshold=threshold, volatility=blended_rv,
                                market_price=best_ask, seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                                ask_depth=ask_depth, best_ask_source=best_ask_source,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                                **_oft_db, **_shadow_diag)
                        continue

                # Layer 3c: Per-window aggregate risk cap (config-driven)
                if _fltcfg.max_window_risk is not None:
                    _wkey = window["event_ticker"]
                    _wrisk = self._hourly_window_risk.get(_wkey, 0.0)
                    _this_risk = (sizing["contracts"] * best_ask) / (balance if balance > 0 else 1)
                    if _wrisk + _this_risk > _fltcfg.max_window_risk:
                        _dedup_key = (ticker, f"{_flt_pt}_window_risk_cap")
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset, f"{_flt_pt}_window_risk_cap",
                                spot_price=spot, threshold=threshold, volatility=blended_rv,
                                market_price=best_ask, seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                                ask_depth=ask_depth, best_ask_source=best_ask_source,
                                product_type=window.get("product_type"),
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                                **_oft_db, **_shadow_diag)
                        continue

                # ── WEATHER FOCUS FILTER ──
                # Shadow trade signals only for lower_tail in NE/Midwest cities.
                # Other weather markets still logged as raw data in earlier filter stages
                # (price_out_of_range, insufficient_edge, timing_restricted) but don't
                # reach the observation gate for shadow trade simulation.
                if _pt == "weather":
                    from weather_engine import WEATHER_SHADOW_FOCUS_MARKET_TYPES, WEATHER_SHADOW_FOCUS_CITIES
                    _wx_mtype_here = _shadow_extra.get("wx_market_type")
                    _wx_city_here = asset.replace("_TEMP", "") if asset else ""
                    _wx_excluded_reason = None
                    if _wx_mtype_here and _wx_mtype_here not in WEATHER_SHADOW_FOCUS_MARKET_TYPES:
                        _wx_excluded_reason = f"weather_excluded_mtype_{_wx_mtype_here}"
                    elif _wx_city_here not in WEATHER_SHADOW_FOCUS_CITIES:
                        _wx_excluded_reason = "weather_excluded_city"
                    if _wx_excluded_reason:
                        _dedup_key = (ticker, _wx_excluded_reason)
                        if _dedup_key not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_dedup_key)
                            _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset, _wx_excluded_reason,
                                spot_price=spot, threshold=threshold, volatility=blended_rv,
                                market_price=best_ask, seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                                ask_depth=ask_depth, best_ask_source=best_ask_source,
                                product_type=_pt,
                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                kelly_f=sizing.get("kelly_f") if sizing else None,
                                position_size=sizing.get("contracts") if sizing else None,
                                drawdown_scaler=sizing.get("drawdown_scaler") if sizing else None,
                                **_oft_db, **_shadow_diag)
                        continue

                # ── HOURLY EDGE CAP ──
                # Reject hourly signals with edge > 5% — the 10%+ zone has 24.2% WR (edge inversion).
                # Log rejection and continue. Does NOT affect 15M (gated on _pt == "hourly").
                if _pt == "hourly" and fee_adjusted_edge > HOURLY_MAX_EDGE:
                    _hecap_dedup = (ticker, "hourly_edge_cap")
                    if _hecap_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_hecap_dedup)
                        try:
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset, "hourly_edge_cap",
                                spot_price=spot, threshold=threshold, volatility=blended_rv,
                                market_price=best_ask, seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                breakeven_wr=best_ask / 100.0,
                                product_type="hourly", **_oft_db, **_shadow_diag)
                        except Exception:
                            logging.warning("insert_evaluated_opportunity failed (hourly_edge_cap)", exc_info=True)
                    continue

                # ── GENERIC OBSERVATION GATE ──
                # Config-driven: any market type with observation_only=True is blocked here
                if _fltcfg.observation_only and _fltcfg.observation_filter_label:
                    _obs_label = _fltcfg.observation_filter_label
                    _obs_pt = window.get("product_type")
                    # Hourly-specific: journal logging with extra detail
                    if _obs_pt == "hourly":
                        try:
                            self._logger.log_opportunity({
                                "filter_stage": _obs_label,
                                "product_type": _obs_pt,
                                "ticker": ticker,
                                "event_ticker": window["event_ticker"],
                                "asset": asset,
                                "spot_price": spot, "threshold": threshold,
                                "volatility": blended_rv, "market_price": best_ask,
                                "seconds_to_close": round(seconds_remaining, 1),
                                "calibrated_prob": round(final_prob, 6),
                                "edge": round(edge, 6),
                                "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                                "position_size": sizing["contracts"],
                                "kelly_f": sizing["kelly_f"],
                                "drawdown_scaler": sizing["drawdown_scaler"],
                                "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                                "ofa_adjustment": round(ofa_adjustment, 6),
                                "strategy": strategy,
                                "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                                "hourly_pre_temp_prob": round(_hourly_pre_temp_prob, 6) if _hourly_pre_temp_prob is not None else None,
                                "hourly_temp_t": _fltcfg.temperature_t if _fltcfg.temperature_enabled else None,
                                "old_system_prob": round(_old_system_prob, 6),
                                "counterfactual": _cf,
                                **_shadow_diag,
                            })
                        except Exception:
                            pass
                    _dedup_key = (ticker, _obs_label)
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        # Build type-specific extra kwargs for DB insert
                        _obs_extra = {}
                        if _obs_pt == "hourly":
                            _obs_extra.update(
                                counterfactual=_cf_json,
                                shadow_cal_prob=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("prob") if _cf else None,
                                shadow_cal_fee_edge=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("fee_edge") if _cf else None,
                                shadow_cal_temperature=(_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("temperature") if _cf else None,
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                            )
                        elif _obs_pt == "spx_hourly":
                            # SPX-specific diagnostics: VIX, seasonal, data quality
                            _spx_diag = {
                                "vix_implied_rv": vol_est.get("vix_implied_rv"),
                                "seasonal_factor": vol_est.get("seasonal_factor"),
                                "n_returns": vol_est.get("n_returns"),
                                "rk_rv": vol_est.get("rk_rv"),
                            }
                            _obs_extra.update(
                                counterfactual=json.dumps(_spx_diag),
                                hourly_pre_temp_prob=_hourly_pre_temp_prob,
                                hourly_applied_temp_t=_configured_temp_t,
                                hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                                hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                                hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                                hourly_shadow_blend_50=_hourly_shadow_blend_50,
                                hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                                hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                                hourly_shadow_blend_20=_hourly_shadow_blend_20,
                                hourly_shadow_blend_30=_hourly_shadow_blend_30,
                                hourly_shadow_blend_60=_hourly_shadow_blend_60,
                                hourly_post_temp_prob=_hourly_post_temp_prob,
                            )
                        elif _obs_pt == "weather":
                            _obs_extra.update(
                                wx_ensemble_mean=vol_est.get("ensemble_mean"),
                                wx_ensemble_std=vol_est.get("ensemble_std"),
                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                wx_n_members=vol_est.get("n_members"),
                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                            )
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset, _obs_label,
                            spot_price=spot, threshold=threshold, volatility=blended_rv,
                            market_price=best_ask, seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge, z_score=z_score,
                            vol_regime=vol_est["regime"], raw_prob=raw_prob,
                            calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                            breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                            ask_depth=ask_depth, best_ask_source=best_ask_source,
                            position_size=sizing["contracts"],
                            kelly_f=sizing["kelly_f"],
                            drawdown_scaler=sizing["drawdown_scaler"],
                            calibrated_prob_raw=calibrated_prob_raw,
                            ofa_adjustment=ofa_adjustment,
                            strategy=strategy,
                            old_system_prob=_old_system_prob,
                            product_type=_obs_pt, **_obs_extra, **_oft_db, **_shadow_diag)
                    _obs_log_prefix = {"hourly": "HOURLY_OBS", "spx_hourly": "SPX_OBS", "weather": "WEATHER_OBS"}.get(_obs_pt, "OBS")
                    logging.info("%s: %s ask=%d edge=%.2f%% prob=%.1f%% stc=%.0fs",
                                 _obs_log_prefix, ticker, best_ask, fee_adjusted_edge * 100, final_prob * 100, seconds_remaining)
                    # ── SPX NO-side observation ──
                    # Log NO-side data for offline analysis when YES is in 65-85c range
                    if _obs_pt == "spx_hourly" and 65 <= best_ask <= 85 and seconds_remaining >= 600:
                        _no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                        _spx_no_price = None
                        if _no_ask_raw is not None:
                            _spx_no_price = (dollars_str_to_cents(_no_ask_raw) if isinstance(_no_ask_raw, str)
                                             else int(_no_ask_raw))
                            if _spx_no_price <= 0:
                                _spx_no_price = None
                        if _spx_no_price and 0 < _spx_no_price < 100:
                            _spx_no_prob = 1.0 - final_prob
                            _spx_no_edge = _spx_no_prob - _spx_no_price / 100.0
                            _spx_no_dedup = (ticker, "spx_no_side_observation")
                            if _spx_no_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_spx_no_dedup)
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "spx_no_side_observation",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv,
                                        market_price=_spx_no_price,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=round(_spx_no_prob, 6),
                                        edge=round(_spx_no_edge, 6),
                                        z_score=z_score, raw_prob=round(1.0 - raw_prob, 6) if raw_prob else None,
                                        product_type="spx_hourly",
                                        side="no",
                                        **_shadow_diag)
                                except Exception:
                                    logging.debug("spx_no_side_observation insert failed", exc_info=True)
                    # ── Weather Shadow Variants (capped30, short_stc) ──
                    if _obs_pt == "weather":
                        for _wscfg in WEATHER_SHADOW_CONFIGS:
                            _wsname = _wscfg["name"]
                            if "max_price" in _wscfg and best_ask > _wscfg["max_price"]:
                                continue
                            if "max_stc" in _wscfg and seconds_remaining > _wscfg["max_stc"]:
                                continue
                            _ws_dedup = (ticker, _wsname)
                            if _ws_dedup in self._eval_opp_seen:
                                continue
                            self._eval_opp_seen.add(_ws_dedup)
                            _ws_ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset,
                                    _wsname,
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv, market_price=best_ask,
                                    seconds_to_close=seconds_remaining,
                                    calibrated_prob=final_prob, edge=edge,
                                    ofa_adjustment=ofa_adjustment,
                                    z_score=z_score, vol_regime=vol_est["regime"],
                                    raw_prob=raw_prob,
                                    calibrated_prob_raw=calibrated_prob_raw,
                                    calibration_method=calibration_method,
                                    fee_adjusted_edge=fee_adjusted_edge,
                                    breakeven_wr=best_ask / 100.0,
                                    expected_value=round(_ws_ev, 2),
                                    ask_depth=ask_depth, best_ask_source=best_ask_source,
                                    position_size=sizing["contracts"],
                                    kelly_f=sizing["kelly_f"],
                                    drawdown_scaler=sizing["drawdown_scaler"],
                                    strategy=strategy, old_system_prob=_old_system_prob,
                                    product_type="weather",
                                    wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                    wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                    wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                    wx_n_members=_shadow_extra.get("wx_n_members"),
                                    wx_market_type=_shadow_extra.get("wx_market_type"),
                                    wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                    wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                    wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                    **_oft_db, **_shadow_diag)
                            except Exception:
                                logging.warning("insert_evaluated_opportunity failed (%s)", _wsname, exc_info=True)
                        # ── Bracket NO intercept ──────────────────────────
                        # Buy NO on bracket contracts when YES is 88-96c. Computes NO cost
                        # from YES price (bypasses corrupted _no_ask_eq). 91.7% NO rate on
                        # 157 single-strike contracts, breakeven 4-12%.
                        if (BRACKET_NO_ENABLED
                                and _wx_mtype == "bracket"
                                and BRACKET_NO_YES_MIN <= best_ask <= BRACKET_NO_YES_MAX
                                and seconds_remaining >= BRACKET_NO_MIN_STC):
                            _bn_no_cost = 100 - best_ask  # 4-12c (bypasses corrupted _no_ask_eq)
                            _bn_edge = BRACKET_NO_ASSUMED_PROB - _bn_no_cost / 100.0
                            # Count existing bracket NO positions + candidates this scan
                            _bn_existing = sum(1 for p in self._state.get_open_positions()
                                               if p.get("side") == "no" and (p.get("ticker") or "").startswith("KXHIGH"))
                            _bn_in_scan = sum(1 for c in candidates if c.get("strategy") == "bracket_no")
                            if _bn_existing + _bn_in_scan < BRACKET_NO_MAX_CONCURRENT:
                                # Per-ticker dedup: skip if already holding this specific bracket strike
                                _bn_has_pos = any(p.get("ticker") == ticker for p in self._state.get_open_positions())
                                if not _bn_has_pos:
                                    _bn_dedup = (ticker, "bracket_no")
                                    _bn_fee = calculate_fee(BRACKET_NO_FIXED_CONTRACTS, _bn_no_cost,
                                                            is_taker=True,
                                                            fee_mult_taker=_mcfg.fee_multiplier_taker,
                                                            fee_mult_maker=_mcfg.fee_multiplier_maker)
                                    _bn_fee_edge = _bn_edge - _bn_fee / (BRACKET_NO_FIXED_CONTRACTS * 100.0)
                                    logging.info(
                                        "BRACKET_NO_CANDIDATE: %s yes=%dc no_cost=%dc edge=%.2f%% "
                                        "fee_edge=%.2f%% stc=%.0fs mtype=%s",
                                        ticker, best_ask, _bn_no_cost, _bn_edge * 100,
                                        _bn_fee_edge * 100, seconds_remaining, _wx_mtype)
                                    candidates.append({
                                        "ticker": ticker,
                                        "event_ticker": window["event_ticker"],
                                        "asset": asset,
                                        "product_type": "weather",
                                        "side": "no",
                                        "spot": spot,
                                        "threshold": threshold,
                                        "seconds_to_close": round(seconds_remaining, 1),
                                        "blended_rv": blended_rv,
                                        "calibrated_prob": BRACKET_NO_ASSUMED_PROB,
                                        "z_score": z_score,
                                        "best_yes_ask": _bn_no_cost,  # NO cost for execution (mirrors existing pattern)
                                        "best_ask_source": best_ask_source,
                                        "edge": round(_bn_edge, 6),
                                        "fee_adjusted_edge": round(_bn_fee_edge, 6),
                                        "position_size": BRACKET_NO_FIXED_CONTRACTS,
                                        "kelly_f": 0.0,
                                        "drawdown_scaler": 1.0,
                                        "vol_regime": vol_est["regime"],
                                        "balance_at_scan": balance,
                                        "strategy": "bracket_no",
                                        "strategy_scores": {},
                                        "ob_snapshot": {},
                                        "calibrated_prob_raw": round(1.0 - calibrated_prob_raw, 6) if calibrated_prob_raw is not None else None,
                                        "ofa_adjustment": round(ofa_adjustment, 6),
                                        "ofa_confidence": "none",
                                        "raw_prob": 1.0 - raw_prob if raw_prob is not None else None,
                                        "calibration_method": "assumed_prob",
                                        "old_system_prob": round(1.0 - _old_system_prob, 6),
                                        "kalshi_oft_signals": {},
                                        "counterfactual_json": None,
                                        "_bracket_yes_price": best_ask,  # Store original YES price for logging
                                    })
                                    # DB insert (deduped per ticker)
                                    if _bn_dedup not in self._eval_opp_seen:
                                        self._eval_opp_seen.add(_bn_dedup)
                                        try:
                                            self._state.insert_evaluated_opportunity(
                                                ticker, window["event_ticker"], asset,
                                                "bracket_no",
                                                spot_price=spot, threshold=threshold,
                                                volatility=blended_rv, market_price=best_ask,
                                                seconds_to_close=seconds_remaining,
                                                calibrated_prob=BRACKET_NO_ASSUMED_PROB,
                                                edge=round(_bn_edge, 6),
                                                ofa_adjustment=ofa_adjustment,
                                                z_score=z_score, vol_regime=vol_est["regime"],
                                                raw_prob=1.0 - raw_prob if raw_prob is not None else None,
                                                calibrated_prob_raw=1.0 - calibrated_prob_raw if calibrated_prob_raw is not None else None,
                                                calibration_method="assumed_prob",
                                                fee_adjusted_edge=round(_bn_fee_edge, 6),
                                                breakeven_wr=_bn_no_cost / 100.0,
                                                ask_depth=ask_depth, best_ask_source=best_ask_source,
                                                position_size=BRACKET_NO_FIXED_CONTRACTS,
                                                kelly_f=0.0, drawdown_scaler=1.0,
                                                strategy="bracket_no", old_system_prob=_old_system_prob,
                                                product_type="weather", side="no",
                                                wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                                wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                                wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                                wx_n_members=_shadow_extra.get("wx_n_members"),
                                                wx_market_type=_shadow_extra.get("wx_market_type"),
                                                wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                                wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                                **_oft_db, **_shadow_diag)
                                        except Exception:
                                            logging.warning("insert_evaluated_opportunity failed (bracket_no)", exc_info=True)

                        # ── Weather NO-side (shadow + live candidate) ──
                        # Model is structurally wrong on NO (predicts 3-16%, actual 79.7% WR).
                        # The shadow log uses MODEL edge (almost always negative).
                        # The live candidate uses an ASSUMED 0.70 prob to bypass the broken model.
                        # CRITICAL: the live candidate must NOT be nested inside the shadow
                        # edge-gate (_wn_no_fee_edge > 0) — that branch essentially never fires
                        # because the model is broken, which would suppress the live candidate
                        # entirely. This was the bug that kept weather at 0 trades Apr 4-11.
                        # See kb/failures/weather-no-candidate-never-fires.md
                        if final_prob >= WEATHER_NO_SHADOW_MIN_YES_PROB and _no_ask_eq is not None:
                            # Compute NO-side economics once (cheap, used by both paths).
                            _wn_no_prob = 1.0 - final_prob
                            _wn_no_fee = calculate_fee(1, _no_ask_eq, is_taker=True,
                                                       fee_mult_taker=_mcfg.fee_multiplier_taker,
                                                       fee_mult_maker=_mcfg.fee_multiplier_maker)
                            _wn_no_edge = _wn_no_prob - _no_ask_eq / 100.0
                            _wn_no_fee_edge = _wn_no_edge - _wn_no_fee / 100.0

                            # Shadow path: model-edge gated (rarely fires; model is wrong on NO).
                            _wn_dedup = (ticker, "weather_no_shadow")
                            if _wn_dedup not in self._eval_opp_seen and _wn_no_fee_edge > 0:
                                self._eval_opp_seen.add(_wn_dedup)
                                _wn_ev = (_wn_no_prob * (100 - _no_ask_eq)) - ((1 - _wn_no_prob) * _no_ask_eq) - _wn_no_fee
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "weather_no_shadow",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=_no_ask_eq,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=_wn_no_prob, edge=_wn_no_edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score, vol_regime=vol_est["regime"],
                                        raw_prob=1.0 - raw_prob if raw_prob is not None else None,
                                        calibrated_prob_raw=1.0 - calibrated_prob_raw if calibrated_prob_raw is not None else None,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=_wn_no_fee_edge,
                                        breakeven_wr=_no_ask_eq / 100.0,
                                        expected_value=round(_wn_ev, 2),
                                        ask_depth=ask_depth, best_ask_source=best_ask_source,
                                        position_size=1,  # Fixed 1-contract sizing
                                        kelly_f=0.0,
                                        drawdown_scaler=1.0,
                                        strategy=strategy, old_system_prob=_old_system_prob,
                                        product_type="weather", side="no",
                                        wx_ensemble_mean=_shadow_extra.get("wx_ensemble_mean"),
                                        wx_ensemble_std=_shadow_extra.get("wx_ensemble_std"),
                                        wx_bias_correction=_shadow_extra.get("wx_bias_correction"),
                                        wx_n_members=_shadow_extra.get("wx_n_members"),
                                        wx_market_type=_shadow_extra.get("wx_market_type"),
                                        wx_hrrr_temp=_shadow_extra.get("wx_hrrr_temp"),
                                        wx_corrected_mean=_shadow_extra.get("wx_corrected_mean"),
                                        wx_no_side_edge=_shadow_extra.get("wx_no_side_edge"),
                                        **_oft_db, **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (weather_no_shadow)", exc_info=True)
                            # Note: the weather NO LIVE CANDIDATE was previously here, nested
                            # inside the YES-side observation gate. That location was dead code
                            # because weather YES evals almost always fail the insufficient_edge
                            # check before reaching this branch, and the 1050+ NO-side evals
                            # flow through _process_no_side_shadow() instead. The live candidate
                            # has been moved there. See kb/failures/weather-no-candidate-never-fires.md
                    # V2 variant: shadow cal pipeline (temperature + no blend)
                    if _obs_pt == "hourly" and _cf:
                        self._insert_hourly_v2_variant(
                            ticker, window, asset, raw_prob, best_ask,
                            seconds_remaining, spot, threshold, blended_rv,
                            ofa_adjustment, z_score, vol_est,
                            calibrated_prob_raw, est_fee_1c,
                            ask_depth, best_ask_source, _cf, _shadow_diag)
                    # ── Config A shadow variant (no_XRP + edge ≤ 0.7%) ──
                    if (_obs_pt == "hourly"
                            and asset not in HOURLY_CONFIG_A_EXCLUDED
                            and fee_adjusted_edge <= HOURLY_CONFIG_A_MAX_EDGE):
                        _ca_dedup = (ticker, "hourly_config_a")
                        if _ca_dedup not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_ca_dedup)
                            _ca_ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset,
                                    "hourly_config_a",
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv, market_price=best_ask,
                                    seconds_to_close=seconds_remaining,
                                    calibrated_prob=final_prob, edge=edge,
                                    ofa_adjustment=ofa_adjustment,
                                    z_score=z_score, vol_regime=vol_est["regime"],
                                    raw_prob=raw_prob,
                                    calibrated_prob_raw=calibrated_prob_raw,
                                    calibration_method=calibration_method,
                                    fee_adjusted_edge=fee_adjusted_edge,
                                    breakeven_wr=best_ask / 100.0,
                                    expected_value=round(_ca_ev, 2),
                                    ask_depth=ask_depth, best_ask_source=best_ask_source,
                                    position_size=sizing["contracts"],
                                    kelly_f=sizing["kelly_f"],
                                    drawdown_scaler=sizing["drawdown_scaler"],
                                    strategy=strategy, old_system_prob=_old_system_prob,
                                    product_type="hourly",
                                    **_oft_db, **_shadow_diag)
                            except Exception:
                                logging.warning("insert_evaluated_opportunity failed (hourly_config_a)", exc_info=True)
                    # ── Config B: BTC 70-89c wl2 (promotion candidate) ──
                    # Tracks the high-alpha low-price tier for BTC hourly.
                    # Uses its own per-window counter (_cb_window_counts) with price-sorted
                    # top-2 selection (same as backtest methodology).
                    if (_obs_pt == "hourly"
                            and asset == HOURLY_CONFIG_B_ASSET
                            and HOURLY_CONFIG_B_MIN_PRICE <= best_ask <= HOURLY_CONFIG_B_MAX_PRICE
                            and fee_adjusted_edge > 0):
                        _cb_wkey = window["event_ticker"]
                        _cb_count = self._config_b_window_counts.get(_cb_wkey, 0)
                        if _cb_count < HOURLY_CONFIG_B_MAX_PER_WINDOW:
                            _cb_dedup = (ticker, "hourly_config_b")
                            if _cb_dedup not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_cb_dedup)
                                self._config_b_window_counts[_cb_wkey] = _cb_count + 1
                                _cb_ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, window["event_ticker"], asset,
                                        "hourly_config_b",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=best_ask,
                                        seconds_to_close=seconds_remaining,
                                        calibrated_prob=final_prob, edge=edge,
                                        ofa_adjustment=ofa_adjustment,
                                        z_score=z_score, vol_regime=vol_est["regime"],
                                        raw_prob=raw_prob,
                                        calibrated_prob_raw=calibrated_prob_raw,
                                        calibration_method=calibration_method,
                                        fee_adjusted_edge=fee_adjusted_edge,
                                        breakeven_wr=best_ask / 100.0,
                                        expected_value=round(_cb_ev, 2),
                                        ask_depth=ask_depth, best_ask_source=best_ask_source,
                                        position_size=sizing["contracts"],
                                        kelly_f=sizing["kelly_f"],
                                        drawdown_scaler=sizing["drawdown_scaler"],
                                        strategy=strategy, old_system_prob=_old_system_prob,
                                        product_type="hourly",
                                        **_oft_db, **_shadow_diag)
                                except Exception:
                                    logging.warning("insert_evaluated_opportunity failed (hourly_config_b)", exc_info=True)
                    # ── Configs C–G: data-driven shadow variants ──
                    if _obs_pt == "hourly":
                        for _scfg in HOURLY_SHADOW_CONFIGS:
                            _sname = _scfg["name"]
                            if "included_assets" in _scfg and asset not in _scfg["included_assets"]:
                                continue
                            if "excluded_assets" in _scfg and asset in _scfg["excluded_assets"]:
                                continue
                            if "min_stc" in _scfg and seconds_remaining < _scfg["min_stc"]:
                                continue
                            if "max_stc" in _scfg and seconds_remaining > _scfg["max_stc"]:
                                continue
                            if "max_edge" in _scfg and fee_adjusted_edge > _scfg["max_edge"]:
                                continue
                            _s_dedup = (ticker, _sname)
                            if _s_dedup in self._eval_opp_seen:
                                continue
                            self._eval_opp_seen.add(_s_dedup)
                            # Recompute prob for configs with custom temperature/blend
                            _s_final = final_prob
                            _s_edge = edge
                            _s_fee_edge = fee_adjusted_edge
                            if "temperature" in _scfg or "blend_w" in _scfg:
                                _s_base = _hourly_pre_temp_prob
                                if _s_base is not None:
                                    _s_t = _scfg.get("temperature", _configured_temp_t or 1.0)
                                    _sp = max(0.001, min(0.999, _s_base))
                                    _slz = math.log(_sp / (1.0 - _sp))
                                    _s_final = 1.0 / (1.0 + math.exp(-_slz / _s_t))
                                    _s_final = max(0.01, min(NUMERICAL_SAFETY_CEILING, _s_final + ofa_adjustment))
                                    _s_bw = _scfg.get("blend_w", _effective_blend_w)
                                    if best_ask < ENDGAME_BLEND_PRICE and _s_bw > 0:
                                        _s_final = (1.0 - _s_bw) * _s_final + _s_bw * (best_ask / 100.0)
                                    _s_edge = _s_final - best_ask / 100.0
                                    _s_fee_edge = _s_edge - est_fee_1c / 100.0
                            _s_ev = (_s_final * (100 - best_ask)) - ((1 - _s_final) * best_ask) - est_fee_1c
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset,
                                    _sname,
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv, market_price=best_ask,
                                    seconds_to_close=seconds_remaining,
                                    calibrated_prob=_s_final, edge=_s_edge,
                                    ofa_adjustment=ofa_adjustment,
                                    z_score=z_score, vol_regime=vol_est["regime"],
                                    raw_prob=raw_prob,
                                    calibrated_prob_raw=calibrated_prob_raw,
                                    calibration_method=calibration_method,
                                    fee_adjusted_edge=_s_fee_edge,
                                    breakeven_wr=best_ask / 100.0,
                                    expected_value=round(_s_ev, 2),
                                    ask_depth=ask_depth, best_ask_source=best_ask_source,
                                    position_size=sizing["contracts"],
                                    kelly_f=sizing["kelly_f"],
                                    drawdown_scaler=sizing["drawdown_scaler"],
                                    strategy=strategy, old_system_prob=_old_system_prob,
                                    product_type="hourly",
                                    **_oft_db, **_shadow_diag)
                            except Exception:
                                logging.warning("insert_evaluated_opportunity failed (%s)", _sname, exc_info=True)
                    # Increment per-window counters even in observation mode so Layer 3b/3c
                    # limits work for counterfactual analysis (without this, counter stays 0
                    # and the limit is dead code — bug found by audit: 11 SPX positions in one window)
                    if _fltcfg.max_positions_per_window is not None:
                        _wkey = window["event_ticker"]
                        self._hourly_window_counts[_wkey] = self._hourly_window_counts.get(_wkey, 0) + 1
                        self._hourly_window_risk[_wkey] = self._hourly_window_risk.get(_wkey, 0.0) + \
                            (sizing["contracts"] * best_ask) / (balance if balance > 0 else 1)

                    # ── Hourly Alt Shadow Strategies (BTC/ETH/SOL/XRP) ──
                    # Evaluate Market-Making and HAR-RV shadow strategies in parallel
                    # with the existing EGARCH pipeline. Shadow-only, cannot place orders.
                    if (_obs_pt == "hourly"
                            and self._ml and getattr(self._ml, "hourly_alt_shadow", None)):
                        try:
                            _alt_bid = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                            _alt_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                            _alt_no_ask = (dollars_str_to_cents(_alt_no_ask_raw) if isinstance(_alt_no_ask_raw, str)
                                           else int(_alt_no_ask_raw)) if _alt_no_ask_raw is not None else None
                            self._ml.hourly_alt_shadow.evaluate_strike(
                                asset=asset, ticker=ticker,
                                event_ticker=window["event_ticker"],
                                spot_price=spot, threshold=threshold,
                                seconds_to_close=seconds_remaining,
                                best_bid=_alt_bid, best_ask=best_ask,
                                market_price=best_ask, ob_data=ob_data,
                                egarch_prob=final_prob,
                                egarch_edge=fee_adjusted_edge,
                                no_ask=_alt_no_ask)
                        except Exception:
                            logging.debug("hourly_alt_shadow evaluate failed", exc_info=True)

                    # ── SPX HAR-RV Shadow Strategy ──
                    # Evaluate HAR-RV shadow strategy in parallel with EGARCH
                    if (_obs_pt == "spx_hourly"
                            and self._ml and getattr(self._ml, "spx_harrv_shadow", None)):
                        try:
                            _harv_bid = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                            _harv_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                            _harv_no_ask = (dollars_str_to_cents(_harv_no_ask_raw) if isinstance(_harv_no_ask_raw, str)
                                            else int(_harv_no_ask_raw)) if _harv_no_ask_raw is not None else None
                            self._ml.spx_harrv_shadow.evaluate_strike(
                                ticker=ticker,
                                event_ticker=window["event_ticker"],
                                spot_price=spot, threshold=threshold,
                                seconds_to_close=seconds_remaining,
                                best_bid=_harv_bid, best_ask=best_ask,
                                market_price=best_ask,
                                egarch_prob=final_prob,
                                egarch_edge=fee_adjusted_edge,
                                no_ask=_harv_no_ask)
                        except Exception:
                            logging.debug("spx_harrv_shadow evaluate failed", exc_info=True)

                    continue  # DO NOT add to candidates — observation gate

                # ── 15M Shadow Engine (post-filter) ──
                # _seen dedup in shadow engine prevents double-eval with pre-filter call.
                if (window.get("product_type") in (None, "15m")
                        and self._ml and getattr(self._ml, "fifteenm_shadow", None)):
                    try:
                        _15m_bid = OrderExecutor._best_yes_bid(ob_data) if ob_data else None
                        _15m_no_ask_raw = mkt.get("no_ask_dollars") or mkt.get("no_ask")
                        _15m_no_ask = (dollars_str_to_cents(_15m_no_ask_raw) if isinstance(_15m_no_ask_raw, str)
                                       else int(_15m_no_ask_raw)) if _15m_no_ask_raw is not None else None
                        self._ml.fifteenm_shadow.evaluate_strike(
                            asset=asset, ticker=ticker,
                            event_ticker=window["event_ticker"],
                            spot_price=spot, threshold=threshold,
                            seconds_to_close=seconds_remaining,
                            market_price=best_ask,
                            best_bid=_15m_bid, best_ask=best_ask,
                            blended_rv=blended_rv,
                            egarch_sigma=vol_est.get("egarch_sigma"),
                            z_score=z_score, live_prob=final_prob,
                            live_edge=edge, live_fee_edge=fee_adjusted_edge,
                            egarch_blend_weight=_shadow_diag.get("egarch_blend_weight"),
                            fee_adjusted_edge=fee_adjusted_edge,
                            no_ask=_15m_no_ask)
                    except Exception:
                        logging.warning("fifteenm_shadow evaluate failed", exc_info=True)

                # ── STC SHADOW GATE (15M only, >600s) ──
                # Outer boundary: everything above 600s is shadow-only.
                _stc_limit = STC_SHADOW_THRESHOLD
                if window.get("product_type") in (None, "15m") and seconds_remaining > _stc_limit:
                    _stc_stage = "stc_shadow_no_xrp" if asset != "XRP" else "stc_shadow_xrp"
                    _dedup_key = (ticker, _stc_stage)
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset, _stc_stage,
                            spot_price=spot, threshold=threshold, volatility=blended_rv,
                            market_price=best_ask, seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge, z_score=z_score,
                            vol_regime=vol_est["regime"], raw_prob=raw_prob,
                            calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                            breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                            ask_depth=ask_depth, best_ask_source=best_ask_source,
                            position_size=sizing["contracts"],
                            kelly_f=sizing["kelly_f"],
                            drawdown_scaler=sizing["drawdown_scaler"],
                            calibrated_prob_raw=calibrated_prob_raw,
                            ofa_adjustment=ofa_adjustment,
                            strategy=strategy,
                            old_system_prob=_old_system_prob,
                            product_type=window.get("product_type"),
                            **_oft_db, **_shadow_diag)
                    continue

                # ── STC EXTENDED ZONE FLOOR (300-600s, 15M only) ──
                # Model is 9pp overconfident at 300-600s at low prices, but
                # high-price trades are profitable. Per-asset higher floors
                # extract the safe segment: ETH 90c+, BTC 93c+, XRP 92c+, SOL 95c+.
                # STC sizing scaler (300/STC) already reduces position sizes here.
                if (window.get("product_type") in (None, "15m")
                        and seconds_remaining > STC_EXTENDED_LIVE_FLOOR):
                    _stc_ext_floor = {"BTC": STC_EXTENDED_BTC_MIN_PRICE, "ETH": STC_EXTENDED_ETH_MIN_PRICE,
                                      "SOL": STC_EXTENDED_SOL_MIN_PRICE, "XRP": STC_EXTENDED_XRP_MIN_PRICE}.get(asset, MAX_ENTRY_PRICE)
                    if best_ask < _stc_ext_floor:
                        # Buffer rescue: fat buffer overrides the floor check.
                        # Data (Apr 1-8): buf>=0.25% at 300-600s = 21/21 100% WR,
                        # Wilson LB 88.6% > 87% breakeven. Uses scanner's computed
                        # size (Kelly × STC scaler × asset cap already applied).
                        _ext_buf = (spot - threshold) / threshold * 100 if threshold and threshold > 0 else 0
                        if _ext_buf >= STC_EXTENDED_BUFFER_RESCUE:
                            # SOL-only sizing cap: data (Apr 8-19, n=46) shows SOL rescue losses
                            # average 56ct vs wins 37ct — Kelly sizes UP on thin-buffer high-prob
                            # setups that fail. Cap to 25ct limits tail loss to ~$22 vs $45-72.
                            # BTC rescue (13/13 clean) unaffected.
                            if asset == "SOL" and sizing["contracts"] > SOL_RESCUE_CONTRACT_CAP:
                                _pre_cap = sizing["contracts"]
                                sizing["contracts"] = SOL_RESCUE_CONTRACT_CAP
                                logging.info(
                                    "SOL_RESCUE_CAP: %s capped %d→%d contracts (rescue buf=%.3f%%)",
                                    ticker, _pre_cap, SOL_RESCUE_CONTRACT_CAP, _ext_buf)
                            logging.info(
                                "STC_EXTENDED_BUFFER_RESCUE: %s %s @%dc buf=%.3f%% >= %.2f%% "
                                "(floor=%dc, STC=%.0fs) — allowing trade",
                                asset, ticker, best_ask, _ext_buf,
                                STC_EXTENDED_BUFFER_RESCUE, _stc_ext_floor, seconds_remaining)
                            pass  # fall through to normal candidate path
                        else:
                            _stc_ext_stage = "stc_extended_floor_shadow"
                            _dedup_key = (ticker, _stc_ext_stage)
                            if _dedup_key not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dedup_key)
                                _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset, _stc_ext_stage,
                                    rejection_reason=f"STC extended floor: ask={best_ask}c < {asset} floor {_stc_ext_floor}c (STC={seconds_remaining:.0f}s buf={_ext_buf:.3f}%)",
                                    spot_price=spot, threshold=threshold, volatility=blended_rv,
                                    market_price=best_ask, seconds_to_close=seconds_remaining,
                                    calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                    vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                    calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                    breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                                    ask_depth=ask_depth, best_ask_source=best_ask_source,
                                    position_size=sizing["contracts"],
                                    kelly_f=sizing["kelly_f"],
                                    drawdown_scaler=sizing["drawdown_scaler"],
                                    calibrated_prob_raw=calibrated_prob_raw,
                                    ofa_adjustment=ofa_adjustment,
                                    strategy=strategy,
                                    old_system_prob=_old_system_prob,
                                    product_type=window.get("product_type"),
                                    **_oft_db, **_shadow_diag)
                            continue

                # ── XRP SHADOW GATE (15M only) ──
                # XRP 15M: -$32.97 all-time. Log for counterfactual, don't trade.
                if XRP_15M_SHADOW and asset == "XRP" and window.get("product_type") in (None, "15m"):
                    _dedup_key = (ticker, "xrp_shadow")
                    if _dedup_key not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_dedup_key)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        _xrp_88_tag = "xrp_88_eligible" if best_ask >= XRP_SHADOW_MIN_PRICE else "xrp_88_ineligible"
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset, "xrp_shadow",
                            spot_price=spot, threshold=threshold, volatility=blended_rv,
                            market_price=best_ask, seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge, z_score=z_score,
                            vol_regime=vol_est["regime"], raw_prob=raw_prob,
                            calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                            breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                            ask_depth=ask_depth, best_ask_source=best_ask_source,
                            position_size=sizing["contracts"],
                            kelly_f=sizing["kelly_f"],
                            drawdown_scaler=sizing["drawdown_scaler"],
                            calibrated_prob_raw=calibrated_prob_raw,
                            ofa_adjustment=ofa_adjustment,
                            strategy=strategy,
                            old_system_prob=_old_system_prob,
                            product_type=window.get("product_type"),
                            counterfactual=_xrp_88_tag,
                            **_oft_db, **_shadow_diag)
                    continue

                # ── SOL SUB-86c TIME GATE (15M only) ──
                # SOL ≤85c far-from-expiry: 78.3% WR, -$289 (STC≥300s).
                # Near-expiry (<300s): 100% WR, +$228. Block the far, keep the near.
                if (SOL_LOW_ENTRY_STC_GATE
                        and asset == "SOL"
                        and window.get("product_type") in (None, "15m")
                        and best_ask <= 85
                        and seconds_remaining >= 300):
                    _sol_low_dedup = (ticker, "sol_low_entry_high_stc")
                    if _sol_low_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_sol_low_dedup)
                        _ev = (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c
                        try:
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset, "sol_low_entry_high_stc",
                                rejection_reason=f"SOL sub-86c gate: ask={best_ask}c stc={seconds_remaining:.0f}s",
                                spot_price=spot, threshold=threshold, volatility=blended_rv,
                                market_price=best_ask, seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge, z_score=z_score,
                                vol_regime=vol_est["regime"], raw_prob=raw_prob,
                                calibration_method=calibration_method, fee_adjusted_edge=fee_adjusted_edge,
                                breakeven_wr=best_ask / 100.0, expected_value=round(_ev, 2),
                                ask_depth=ask_depth, best_ask_source=best_ask_source,
                                position_size=sizing["contracts"],
                                kelly_f=sizing["kelly_f"],
                                drawdown_scaler=sizing["drawdown_scaler"],
                                calibrated_prob_raw=calibrated_prob_raw,
                                ofa_adjustment=ofa_adjustment,
                                strategy=strategy,
                                old_system_prob=_old_system_prob,
                                product_type=window.get("product_type"),
                                **_oft_db, **_shadow_diag)
                        except Exception:
                            logging.warning("insert_evaluated_opportunity failed (sol_low_entry_high_stc)", exc_info=True)
                    continue

                # Track per-window counts for Layer 3b/3c limits (config-driven)
                if _fltcfg.max_positions_per_window is not None:
                    _wkey = window["event_ticker"]
                    self._hourly_window_counts[_wkey] = self._hourly_window_counts.get(_wkey, 0) + 1
                    self._hourly_window_risk[_wkey] = self._hourly_window_risk.get(_wkey, 0.0) + \
                        (sizing["contracts"] * best_ask) / (balance if balance > 0 else 1)

                scan_stats[asset]["candidates"] += 1
                self._session_total_candidates += 1
                self._session_asset_perf.setdefault(
                    asset, {"opportunities_found": 0, "times_selected": 0, "times_rejected": 0}
                )["opportunities_found"] += 1
                self._last_opportunity_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
                self._recent_opportunities.append({
                    "ticker": ticker,
                    "asset": asset,
                    "seconds_to_close": round(seconds_remaining, 1),
                    "best_ask": best_ask,
                    "edge_bps": round(edge * 10000),
                    "chosen_strategy": strategy,
                    "rejection_reason": None,
                    "ts": self._last_opportunity_ts,
                })
                _cand_filter_stage = "hourly_live" if _pt == "hourly" else "candidate"
                try:
                    self._logger.log_opportunity({
                        "filter_stage": _cand_filter_stage,
                        "ticker": ticker,
                        "event_ticker": window["event_ticker"],
                        "asset": asset,
                        "spot_price": spot,
                        "threshold": threshold,
                        "volatility": blended_rv,
                        "market_price": best_ask,
                        "best_ask_source": best_ask_source,
                        "seconds_to_close": round(seconds_remaining, 1),
                        "calibrated_prob": round(final_prob, 6),
                        "edge": round(edge, 6),
                        "position_size": sizing["contracts"],
                        "strategy": strategy,
                        "ofa_adjustment": round(ofa_adjustment, 6),
                        "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                        "old_system_prob": round(_old_system_prob, 6),
                        "kalshi_oft": (ofa_signals or {}).get("signals", {}).get("kalshi_orderbook", {}),
                        "counterfactual": _cf,
                        **_shadow_diag,
                        **_shadow_extra,
                    })
                except Exception:
                    logging.warning("insert_evaluated_opportunity failed (%s)", _cand_filter_stage, exc_info=True)

                # SOL high-edge shadow: log additional entry for 5%+ edge analysis
                if _sol_high_edge_shadow:
                    try:
                        self._state.insert_evaluated_opportunity(
                            ticker, window["event_ticker"], asset,
                            "sol_high_edge_shadow",
                            rejection_reason=f"SOL edge {fee_adjusted_edge:.4f} > {SOL_HIGH_EDGE_SHADOW} (shadow only, trade NOT blocked)",
                            spot_price=spot, threshold=threshold,
                            volatility=blended_rv, market_price=best_ask,
                            seconds_to_close=seconds_remaining,
                            calibrated_prob=final_prob, edge=edge,
                            z_score=z_score, raw_prob=raw_prob,
                            fee_adjusted_edge=fee_adjusted_edge,
                            product_type=window.get("product_type"),
                            **_shadow_diag)
                    except Exception:
                        logging.debug("sol_high_edge_shadow insert failed", exc_info=True)

                candidates.append({
                    "ticker": ticker,
                    "event_ticker": window["event_ticker"],
                    "asset": asset,
                    "product_type": window.get("product_type"),
                    "spot": spot,
                    "threshold": threshold,
                    "seconds_to_close": round(seconds_remaining, 1),
                    "blended_rv": blended_rv,
                    "calibrated_prob": round(final_prob, 6),
                    "z_score": z_score,
                    "best_yes_ask": best_ask,
                    "best_ask_source": best_ask_source,
                    "edge": round(edge, 6),
                    "position_size": sizing["contracts"],
                    "kelly_f": sizing["kelly_f"],
                    "drawdown_scaler": sizing["drawdown_scaler"],
                    "vol_regime": vol_est["regime"],
                    "balance_at_scan": balance,
                    "spot_buffer_pct": round(_spot_buffer_pct, 4) if _spot_buffer_pct is not None else None,
                    "strategy": strategy,
                    "strategy_scores": strategy_scores,
                    "ob_snapshot": {
                        "best_ask": best_ask,
                        "ask_depth": ask_depth,
                        "total_depth": total_depth,
                        "best_bid": OrderExecutor._best_yes_bid(ob_data) if ob_data else None,
                        "bid_depth": OrderExecutor._best_yes_bid_depth(ob_data) if ob_data else 0,
                        "spread": (best_ask - OrderExecutor._best_yes_bid(ob_data))
                                  if ob_data and OrderExecutor._best_yes_bid(ob_data) is not None else None,
                    },
                    "calibrated_prob_raw": round(calibrated_prob_raw, 6),
                    "ofa_adjustment": round(ofa_adjustment, 6),
                    "ofa_confidence": ofa_signals["confidence"] if ofa_signals else "none",
                    "raw_prob": raw_prob,
                    "calibration_method": calibration_method,
                    "old_system_prob": round(_old_system_prob, 6),
                    "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                    "kalshi_oft_signals": (ofa_signals or {}).get("signals", {}).get("kalshi_orderbook", {}),
                    "counterfactual_json": _cf_json,
                    "shadow_cal_prob": (_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("prob") if _cf else None,
                    "shadow_cal_fee_edge": (_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("fee_edge") if _cf else None,
                    "shadow_cal_temperature": (_cf.get("old_cal_system") or _cf.get("cal_pipeline", {})).get("temperature") if _cf else None,
                    "hourly_pre_temp_prob": _hourly_pre_temp_prob,
                    "hourly_applied_temp_t": _configured_temp_t,
                    "hourly_shadow_temp_2_0": _hourly_shadow_temp_2_0,
                    "hourly_shadow_temp_1_0": _hourly_shadow_temp_1_0,
                    "hourly_shadow_temp_2_5": _hourly_shadow_temp_2_5,
                    "hourly_shadow_blend_50": _hourly_shadow_blend_50,
                    "hourly_shadow_temp_1_75": _hourly_shadow_temp_1_75,
                    "hourly_shadow_temp_3_0": _hourly_shadow_temp_3_0,
                    "hourly_shadow_blend_20": _hourly_shadow_blend_20,
                    "hourly_shadow_blend_30": _hourly_shadow_blend_30,
                    "hourly_shadow_blend_60": _hourly_shadow_blend_60,
                    "hourly_post_temp_prob": _hourly_post_temp_prob,
                    **_shadow_diag,
                    **_shadow_extra,
                })

                # ── Time-of-day shadow: tag dead-zone and golden-hour candidates ──
                # Dead zones: 14, 16, 18, 22 UTC (data: 82-89% WR, negative PnL)
                # Golden hours: 3, 5, 6, 11 UTC (data: 96-100% WR, +$300/trade)
                # Shadow only — does NOT change live trading. Logs what 1.5x and 2.0x
                # thresholds would have done, for forward validation.
                if _pt in (None, "15m"):
                    _tod_hour = datetime.datetime.now(timezone.utc).hour
                    _tod_dead = _tod_hour in (14, 16, 18, 22)
                    _tod_golden = _tod_hour in (3, 5, 6, 11)
                    if _tod_dead or _tod_golden:
                        if _tod_golden:
                            _tod_stage = "golden_hour_shadow"
                        elif fee_adjusted_edge < _min_edge * 2.0:
                            if fee_adjusted_edge < _min_edge * 1.5:
                                _tod_stage = "dead_hour_shadow_1.5x"
                            else:
                                _tod_stage = "dead_hour_shadow_2.0x"
                        else:
                            _tod_stage = "dead_hour_passed"
                        _tod_dedup = (ticker, _tod_stage)
                        if _tod_dedup not in self._eval_opp_seen:
                            self._eval_opp_seen.add(_tod_dedup)
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, window["event_ticker"], asset,
                                    _tod_stage,
                                    rejection_reason=f"hour={_tod_hour} edge={fee_adjusted_edge:.4f} thresh={_min_edge:.4f}",
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv, market_price=best_ask,
                                    seconds_to_close=seconds_remaining,
                                    calibrated_prob=final_prob, edge=edge,
                                    ofa_adjustment=ofa_adjustment,
                                    z_score=z_score,
                                    vol_regime=vol_est["regime"],
                                    calibrated_prob_raw=calibrated_prob_raw,
                                    kelly_f=sizing.get("kelly_f"),
                                    position_size=sizing.get("contracts"),
                                    breakeven_wr=best_ask / 100.0,
                                    ask_depth=ask_depth,
                                    best_ask_source=best_ask_source,
                                    raw_prob=raw_prob,
                                    calibration_method=calibration_method,
                                    fee_adjusted_edge=fee_adjusted_edge,
                                    product_type=window.get("product_type"),
                                    **_shadow_diag)
                            except Exception:
                                logging.warning("insert_evaluated_opportunity failed (%s)", _tod_stage, exc_info=True)

                # ── Forward observation tags: collect data under current config ──
                # Tag 1: SOL sub-88c during US morning (UTC 12-17)
                # Data: 60% WR pre-BLR, only 5 trades post-BLR — need forward data
                if (_pt in (None, "15m") and asset == "SOL" and best_ask < 88
                        and 12 <= _tod_hour <= 17):
                    _obs_dedup = (ticker, "sol_usmorn_sub88")
                    if _obs_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_obs_dedup)
                        try:
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "sol_usmorn_sub88",
                                rejection_reason=f"SOL {best_ask}c hour={_tod_hour} (observation only)",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge,
                                z_score=z_score, raw_prob=raw_prob,
                                fee_adjusted_edge=fee_adjusted_edge,
                                position_size=sizing.get("contracts"),
                                product_type=window.get("product_type"),
                                **_shadow_diag)
                        except Exception:
                            logging.debug("sol_usmorn_sub88 insert failed", exc_info=True)

                # Tag 2: Sub-2-min STC during US afternoon (UTC 18-23), non-DC only
                # Data: 19W/7L, avg win $2.91 vs avg loss $46.87 — need forward data
                if (_pt in (None, "15m") and seconds_remaining < 120
                        and 18 <= _tod_hour <= 23
                        and strategy not in ("decided_t1", "decided_t1b", "decided_t2",
                                             "decided_t2_z25", "decided_t2_z2")):
                    _obs_dedup = (ticker, "usaft_short_stc")
                    if _obs_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_obs_dedup)
                        try:
                            self._state.insert_evaluated_opportunity(
                                ticker, window["event_ticker"], asset,
                                "usaft_short_stc",
                                rejection_reason=f"STC={seconds_remaining:.0f}s hour={_tod_hour} (observation only)",
                                spot_price=spot, threshold=threshold,
                                volatility=blended_rv, market_price=best_ask,
                                seconds_to_close=seconds_remaining,
                                calibrated_prob=final_prob, edge=edge,
                                z_score=z_score, raw_prob=raw_prob,
                                fee_adjusted_edge=fee_adjusted_edge,
                                position_size=sizing.get("contracts"),
                                product_type=window.get("product_type"),
                                **_shadow_diag)
                        except Exception:
                            logging.debug("usaft_short_stc insert failed", exc_info=True)

                # Respect per-tick orderbook fetch cap
                if ob_fetches_this_tick >= MAX_OB_FETCHES_PER_TICK:
                    break
            # Per-window timing — captures iterations that reach the
            # natural end (slow iterations doing orderbook fetch +
            # filter checks + maybe candidate stage). Fast `continue`
            # exits are skipped, but those are sub-ms anyway.
            _window_dt = time.perf_counter() - _window_start
            if _window_dt > 0.5:
                logging.warning(
                    "SCAN_WINDOW_SLOW: asset=%s ticker=%s took %.2fs",
                    asset, window.get("event_ticker", "?"), _window_dt)
            if ob_fetches_this_tick >= MAX_OB_FETCHES_PER_TICK:
                break

        _scan_loop_dt = time.perf_counter() - _scan_loop_start
        if _scan_loop_dt > 1.5:
            logging.warning(
                "SCAN_LOOP_SLOW: per-window for-loop took %.2fs "
                "(eligible_windows=%d)",
                _scan_loop_dt, len(eligible_windows))

        # Post-loop section timing — `SCAN_POSTLOOP_SLOW` fires when
        # the work AFTER the per-window loop (shadow processors +
        # candidate selection) exceeds 1.5s. Logged via nested helper
        # so each of the 3 post-loop returns can call it.
        _scan_postloop_start = time.perf_counter()

        def _log_postloop_dt():
            _dt = time.perf_counter() - _scan_postloop_start
            if _dt > 1.5:
                logging.warning(
                    "SCAN_POSTLOOP_SLOW: post-loop processing took "
                    "%.2fs", _dt)

        if PRICE_SHADOW_ENABLED and _price_shadow_queue:
            self._process_price_shadow(_price_shadow_queue)

        # NO-side shadow evaluation for all queued markets
        if _no_side_queue:
            self._process_no_side_shadow(_no_side_queue, candidates)

        # Overnight LP shadow evaluation for 50-85c contracts during overnight hours
        if _overnight_lp_queue:
            self._process_overnight_lp_shadow(_overnight_lp_queue)

        # Low-price shadow: dual-sizing sim for 20-79c expansion analysis
        if LOW_PRICE_SHADOW_ENABLED and _low_price_shadow_queue:
            self._process_low_price_shadow(_low_price_shadow_queue)

        if not candidates:
            self._last_scan_stats = scan_stats
            _log_postloop_dt()
            return None

        # ── Separate overlay candidates (bypass single-asset filter) ──
        _dc_candidates = [c for c in candidates if c.get("strategy", "").startswith("decided_")]
        _tm_candidates = [c for c in candidates if c.get("strategy", "").startswith("terminal_momentum")]
        _bn_candidates = [c for c in candidates if c.get("strategy") == "bracket_no"]
        _lpne_candidates = [c for c in candidates if c.get("strategy") == "low_price_near_expiry"]
        _dc_tickers = {c["ticker"] for c in _dc_candidates}
        _tm_tickers = {c["ticker"] for c in _tm_candidates}
        # Remove weekend/overnight discount candidates that overlap with DC (DC takes priority)
        _main_candidates = [c for c in candidates
                            if not c.get("strategy", "").startswith("decided_")
                            and not c.get("strategy", "").startswith("terminal_momentum")
                            and c.get("strategy") not in ("bracket_no", "low_price_near_expiry")
                            and not (c.get("strategy") in ("weekend_discount", "overnight_discount") and c["ticker"] in (_dc_tickers | _tm_tickers))]
        candidates = _main_candidates  # single-asset filter only applies to main pipeline

        # ── Single-asset-per-timeslot: pick highest edge per 15-min window ──
        if ONE_ASSET_PER_WINDOW:
            # Group candidates by timeslot (shared across assets)
            by_timeslot: Dict[str, List[Dict]] = {}
            for c in candidates:
                ts = self._window_timeslot(c["event_ticker"])
                by_timeslot.setdefault(ts, []).append(c)

            # Keep only the single best-edge candidate per timeslot
            filtered: List[Dict] = []
            for ts, slot_candidates in by_timeslot.items():
                slot_candidates.sort(key=lambda c: c["edge"], reverse=True)
                winner = slot_candidates[0]
                filtered.append(winner)
                self._session_asset_perf[winner["asset"]]["times_selected"] += 1

                # Log which assets were rejected in favor of the winner
                if len(slot_candidates) > 1:
                    for c in slot_candidates[1:]:
                        self._session_asset_perf[c["asset"]]["times_rejected"] += 1
                    rejected = [
                        {"asset": c["asset"], "ticker": c["ticker"],
                         "edge": round(c["edge"], 6), "calibrated_prob": c["calibrated_prob"]}
                        for c in slot_candidates[1:]
                    ]
                    self._logger.log_scan({
                        "type": "single_asset_selection",
                        "timeslot": ts,
                        "chosen_asset": winner["asset"],
                        "chosen_ticker": winner["ticker"],
                        "chosen_edge": round(winner["edge"], 6),
                        "rejected_assets": rejected,
                        "reason": "single best asset per window (correlation-adjusted)",
                    })
                    for c in slot_candidates[1:]:
                        try:
                            self._logger.log_opportunity({
                                "filter_stage": "single_asset_selection",
                                "ticker": c["ticker"],
                                "event_ticker": c["event_ticker"],
                                "asset": c["asset"],
                                "rejection_reason": f"lost to {winner['asset']} (edge {winner['edge']:.4f} vs {c['edge']:.4f})",
                                "spot_price": c["spot"],
                                "threshold": c["threshold"],
                                "volatility": c["blended_rv"],
                                "market_price": c["best_yes_ask"],
                                "seconds_to_close": c["seconds_to_close"],
                                "calibrated_prob": c["calibrated_prob"],
                                "edge": c["edge"],
                                "ofa_adjustment": c.get("ofa_adjustment"),
                                "raw_prob": round(c["raw_prob"], 6) if c.get("raw_prob") is not None else None,
                                "old_system_prob": c.get("old_system_prob"),
                                "egarch_sigma": c.get("egarch_sigma"),
                                "egarch_blend_sigma": c.get("egarch_blend_sigma"),
                                "egarch_blend_weight": c.get("egarch_blend_weight"),
                                "mz_r_squared": c.get("mz_r_squared"),
                                "shadow_tv_blend_rv": c.get("shadow_tv_blend_rv"),
                                "mz_sigmoid_blend_rv": c.get("mz_sigmoid_blend_rv"),
                                "mz_sigmoid_improvement": c.get("mz_sigmoid_improvement"),
                                "shadow_tv_weights": c.get("shadow_tv_weights"),
                                "egarch_n_updates": c.get("egarch_n_updates"),
                                "egarch_ratio_clamped": c.get("egarch_ratio_clamped"),
                                "counterfactual": c.get("counterfactual_json"),
                            })
                            _dedup_key = (c["ticker"], "single_asset_selection")
                            if _dedup_key not in self._eval_opp_seen:
                                self._eval_opp_seen.add(_dedup_key)
                                _ba = c["best_yes_ask"]
                                _cp = c["calibrated_prob"]
                                _fee1 = calculate_taker_fee(1, _ba)
                                _ev = (_cp * (100 - _ba)) - ((1 - _cp) * _ba) - _fee1
                                self._state.insert_evaluated_opportunity(
                                    c["ticker"], c["event_ticker"], c["asset"],
                                    "single_asset_selection",
                                    rejection_reason=f"lost to {winner['asset']}",
                                    spot_price=c["spot"], threshold=c["threshold"],
                                    volatility=c["blended_rv"], market_price=_ba,
                                    seconds_to_close=c["seconds_to_close"],
                                    calibrated_prob=_cp, edge=c["edge"],
                                    ofa_adjustment=c.get("ofa_adjustment"),
                                    strategy=c.get("strategy"),
                                    z_score=c.get("z_score"),
                                    vol_regime=c.get("vol_regime"),
                                    calibrated_prob_raw=c.get("calibrated_prob_raw"),
                                    kelly_f=c.get("kelly_f"),
                                    position_size=c.get("position_size"),
                                    breakeven_wr=_ba / 100.0,
                                    expected_value=round(_ev, 2),
                                    drawdown_scaler=c.get("drawdown_scaler"),
                                    ask_depth=c.get("ob_snapshot", {}).get("ask_depth"),
                                    best_ask_source=c.get("best_ask_source"),
                                    ofa_confidence=c.get("ofa_confidence"),
                                    raw_prob=c.get("raw_prob"),
                                    calibration_method=c.get("calibration_method"),
                                    old_system_prob=c.get("old_system_prob"),
                                    fee_adjusted_edge=c.get("fee_adjusted_edge"),
                                    egarch_sigma=c.get("egarch_sigma"),
                                    egarch_blend_sigma=c.get("egarch_blend_sigma"),
                                    egarch_blend_weight=c.get("egarch_blend_weight"),
                                    mz_r_squared=c.get("mz_r_squared"),
                                    shadow_tv_blend_rv=c.get("shadow_tv_blend_rv"),
                                    mz_shadow_sigmoid_w=c.get("mz_shadow_sigmoid_w"),
                                    mz_baseline_qlike=c.get("mz_baseline_qlike"),
                                    mz_qlike=c.get("mz_qlike"),
                                    counterfactual=c.get("counterfactual_json"),
                                    shadow_cal_prob=c.get("shadow_cal_prob"),
                                    shadow_cal_fee_edge=c.get("shadow_cal_fee_edge"),
                                    shadow_cal_temperature=c.get("shadow_cal_temperature"),
                                    oft_prob_adjustment=c.get("oft_prob_adjustment"),
                                    oft_imbalance_ratio=c.get("oft_imbalance_ratio"),
                                    oft_n_snapshots=c.get("oft_n_snapshots"),
                                    hourly_pre_temp_prob=c.get("hourly_pre_temp_prob"),
                                    hourly_applied_temp_t=c.get("hourly_applied_temp_t"),
                                    hourly_shadow_temp_2_0=c.get("hourly_shadow_temp_2_0"),
                                    hourly_shadow_temp_1_0=c.get("hourly_shadow_temp_1_0"),
                                    hourly_shadow_temp_2_5=c.get("hourly_shadow_temp_2_5"),
                                    hourly_shadow_blend_50=c.get("hourly_shadow_blend_50"),
                                    hourly_shadow_temp_1_75=c.get("hourly_shadow_temp_1_75"),
                                    hourly_shadow_temp_3_0=c.get("hourly_shadow_temp_3_0"),
                                    hourly_shadow_blend_20=c.get("hourly_shadow_blend_20"),
                                    hourly_shadow_blend_30=c.get("hourly_shadow_blend_30"),
                                    hourly_shadow_blend_60=c.get("hourly_shadow_blend_60"),
                                    hourly_post_temp_prob=c.get("hourly_post_temp_prob"))
                        except Exception:
                            logging.warning("single_asset_selection insert failed for %s", c.get("ticker"), exc_info=True)
        else:
            filtered = candidates

        # ── Per-asset selection: best strike per asset for hourly ──
        hourly_cands = [c for c in filtered if c.get("product_type") == "hourly"]
        fifteenm_cands = [c for c in filtered if c.get("product_type") != "hourly"]

        selected: List[Dict] = []

        # Hourly: best edge per asset (up to 4 simultaneous)
        hourly_by_asset: Dict[str, List[Dict]] = {}
        for c in hourly_cands:
            hourly_by_asset.setdefault(c["asset"], []).append(c)
        for asset_key, asset_cands in hourly_by_asset.items():
            selected.append(max(asset_cands, key=lambda c: c["edge"]))

        # 15M: single global best (existing behavior)
        if fifteenm_cands:
            selected.append(max(fifteenm_cands, key=lambda c: c["edge"]))

        # Decided contract overlay: add all DC candidates (already window-capped in scan)
        # Priority by payoff: lower price = higher payoff, so sort ascending by price
        _dc_candidates.sort(key=lambda c: c["best_yes_ask"])
        selected.extend(_dc_candidates)

        # Terminal momentum overlay: add all TM candidates (bypass single-asset filter)
        selected.extend(_tm_candidates)

        # Bracket NO overlay: add all bracket NO candidates
        selected.extend(_bn_candidates)

        # LPNE overlay: add all low-price near-expiry candidates
        selected.extend(_lpne_candidates)

        # ── 96¢ × {SOL,XRP} × 2-5min STC danger-band filter (strategy-aware) ──
        # Strips bleeder-strategy candidates from the cell while preserving
        # profitable strategies (TM-96, TAKER_NOW, decided_t1*, etc.).
        # See kb/decisions/96c-sol-xrp-2to5min-block-2026-04-26.md
        if HIGH_PRICE_STC_BLOCK_ENABLED:
            _hpsb_kept: List[Dict] = []
            _hpsb_dropped: List[Dict] = []
            for _cand in selected:
                _cand_pt = _cand.get("product_type")
                # Side convention (verified 2026-04-26 by grep):
                #   - NO-side candidates ALWAYS set "side": "no" explicitly
                #     (lines 13964, 15867, 15960 — scan_no_side path).
                #   - YES-side candidates may omit "side" or set it to "yes" explicitly
                #     (DC, TM overlays in scan() omit it; other paths set it).
                # Therefore default="yes" is correct for missing-key candidates.
                # If a future NO-side path forgets to set side="no", the gate would
                # incorrectly fire — invariant guarded by the convention test below.
                _cand_strat = _cand.get("strategy")
                _cand_side = _cand.get("side", "yes")
                if (_cand_pt in (None, "15m")
                        and should_block_high_price_stc_candidate(
                            asset=_cand.get("asset"),
                            side=_cand_side,
                            entry_price_cents=_cand.get("best_yes_ask"),
                            seconds_to_close=_cand.get("seconds_to_close"),
                            strategy=_cand_strat)):
                    _hpsb_dropped.append(_cand)
                else:
                    _hpsb_kept.append(_cand)
            if _hpsb_dropped:
                selected = _hpsb_kept
                for _drop in _hpsb_dropped:
                    _drop_strat = _drop.get("strategy")
                    _drop_asset = _drop.get("asset")
                    _drop_ticker = _drop.get("ticker")
                    _drop_stc_raw = _drop.get("seconds_to_close")
                    _drop_stc = int(_drop_stc_raw) if _drop_stc_raw is not None else None
                    _drop_price = _drop.get("best_yes_ask")
                    _drop_side = _drop.get("side") or "yes"
                    _drop_reason = (
                        f"96c {_drop_asset} {_drop_side.upper()} {_drop_strat} blocked: "
                        f"stc={_drop_stc}s in danger band (calibrator over-confident, see KB)")
                    logging.info("HPSB_DROP: %s strat=%s asset=%s stc=%s",
                                 _drop_ticker, _drop_strat, _drop_asset, _drop_stc)
                    # setdefault guards against scan_stats not being pre-populated
                    # for an unexpected asset key (defense for adversarial review A2)
                    _stats_bucket = scan_stats.setdefault(_drop_asset, {})
                    _stats_bucket[HIGH_PRICE_STC_BLOCK_FILTER_STAGE] = \
                        _stats_bucket.get(HIGH_PRICE_STC_BLOCK_FILTER_STAGE, 0) + 1
                    # Breakeven WR only meaningful for YES-side fills; for NO-side it
                    # would be (1 - price/100). Compute conditionally.
                    _bewr = (_drop_price / 100.0) if (_drop_side == "yes" and _drop_price) else None
                    _hpsb_dedup = (_drop_ticker, HIGH_PRICE_STC_BLOCK_FILTER_STAGE)
                    if _hpsb_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_hpsb_dedup)
                        try:
                            self._state.insert_evaluated_opportunity(
                                _drop_ticker, _drop.get("event_ticker"), _drop_asset,
                                HIGH_PRICE_STC_BLOCK_FILTER_STAGE,
                                rejection_reason=_drop_reason,
                                spot_price=_drop.get("spot"),
                                threshold=_drop.get("threshold"),
                                volatility=_drop.get("blended_rv"),
                                market_price=_drop_price,
                                seconds_to_close=_drop_stc_raw,
                                calibrated_prob=_drop.get("calibrated_prob"),
                                edge=_drop.get("edge"),
                                ofa_adjustment=_drop.get("ofa_adjustment"),
                                strategy=_drop_strat,
                                z_score=_drop.get("z_score"),
                                vol_regime=_drop.get("vol_regime"),
                                calibrated_prob_raw=_drop.get("calibrated_prob_raw"),
                                kelly_f=_drop.get("kelly_f"),
                                position_size=_drop.get("position_size"),
                                breakeven_wr=_bewr,
                                ask_depth=_drop.get("ob_snapshot", {}).get("ask_depth"),
                                best_ask_source=_drop.get("best_ask_source"),
                                raw_prob=_drop.get("raw_prob"),
                                calibration_method=_drop.get("calibration_method"),
                                fee_adjusted_edge=_drop.get("fee_adjusted_edge"),
                                product_type=_drop.get("product_type"),
                                cal_mlp_request_id=_drop.get("cal_mlp_request_id"),
                                cal_mlp_skipped_reason=_drop.get("cal_mlp_skipped_reason"),
                                cal_mlp_p_mean=_drop.get("cal_mlp_p_mean"),
                                cal_mlp_p_std=_drop.get("cal_mlp_p_std"),
                                cal_mlp_final_lo=_drop.get("cal_mlp_final_lo"),
                                cal_mlp_final_hi=_drop.get("cal_mlp_final_hi"),
                                cal_mlp_train_id=_drop.get("cal_mlp_train_id"))
                        except Exception:
                            logging.warning(
                                "insert_evaluated_opportunity failed (%s)",
                                HIGH_PRICE_STC_BLOCK_FILTER_STAGE, exc_info=True)
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": HIGH_PRICE_STC_BLOCK_FILTER_STAGE,
                            "ticker": _drop_ticker,
                            "asset": _drop_asset,
                            "strategy": _drop_strat,
                            "side": _drop_side,
                            "rejection_reason": _drop_reason,
                            "market_price": _drop_price,
                            "seconds_to_close": _drop_stc,
                            "calibrated_prob": _drop.get("calibrated_prob"),
                            "edge": _drop.get("edge"),
                            "fee_adjusted_edge": _drop.get("fee_adjusted_edge"),
                            "position_size": _drop.get("position_size"),
                        })
                    except Exception:
                        logging.debug("high_price_stc_band log failed", exc_info=True)

        # ── R-bleed-1: TM98 high-price + SOL TAKER low-price bleed cells ──
        # Strategy-aware blocks targeting two cells identified in 7d
        # post-WS-fix data as catastrophic-tail dominators. Each cell has
        # its own env flag so operators can roll back independently.
        # Blocked candidates STILL get a shadow row written for v2/v3
        # training data continuity.
        for _bleed_predicate, _bleed_stage, _bleed_log_tag in (
            (should_block_tm98_highprice_bleed_candidate,
             TM98_HIGHPRICE_BLEED_BLOCK_FILTER_STAGE, "TM98_BLEED_DROP"),
            (should_block_sol_taker_lowprice_bleed_candidate,
             SOL_TAKER_LOWPRICE_BLEED_BLOCK_FILTER_STAGE, "SOL_TAKER_BLEED_DROP"),
        ):
            _bleed_kept: List[Dict] = []
            _bleed_dropped: List[Dict] = []
            for _cand in selected:
                _cand_pt = _cand.get("product_type")
                _cand_strat = _cand.get("strategy")
                _cand_side = _cand.get("side", "yes")
                if (_cand_pt in (None, "15m")
                        and _bleed_predicate(
                            asset=_cand.get("asset"),
                            side=_cand_side,
                            entry_price_cents=_cand.get("best_yes_ask"),
                            seconds_to_close=_cand.get("seconds_to_close"),
                            strategy=_cand_strat)):
                    _bleed_dropped.append(_cand)
                else:
                    _bleed_kept.append(_cand)
            if _bleed_dropped:
                selected = _bleed_kept
                for _drop in _bleed_dropped:
                    _drop_strat = _drop.get("strategy")
                    _drop_asset = _drop.get("asset")
                    _drop_ticker = _drop.get("ticker")
                    _drop_stc_raw = _drop.get("seconds_to_close")
                    _drop_stc = int(_drop_stc_raw) if _drop_stc_raw is not None else None
                    _drop_price = _drop.get("best_yes_ask")
                    _drop_side = _drop.get("side") or "yes"
                    _drop_reason = (
                        f"{_bleed_stage}: {_drop_asset} {_drop_side.upper()} "
                        f"{_drop_strat} @{_drop_price}c stc={_drop_stc}s "
                        f"(7d data: catastrophic-tail cell, see "
                        f"kb/decisions/bleed-cell-blocks-2026-04-30.md)")
                    logging.info(
                        "%s: %s strat=%s asset=%s stc=%s price=%s",
                        _bleed_log_tag, _drop_ticker, _drop_strat,
                        _drop_asset, _drop_stc, _drop_price)
                    _stats_bucket = scan_stats.setdefault(_drop_asset, {})
                    _stats_bucket[_bleed_stage] = _stats_bucket.get(_bleed_stage, 0) + 1
                    _bewr = (_drop_price / 100.0) if (_drop_side == "yes" and _drop_price) else None
                    _bleed_dedup = (_drop_ticker, _bleed_stage)
                    if _bleed_dedup not in self._eval_opp_seen:
                        self._eval_opp_seen.add(_bleed_dedup)
                        try:
                            self._state.insert_evaluated_opportunity(
                                _drop_ticker, _drop.get("event_ticker"), _drop_asset,
                                _bleed_stage,
                                rejection_reason=_drop_reason,
                                spot_price=_drop.get("spot"),
                                threshold=_drop.get("threshold"),
                                volatility=_drop.get("blended_rv"),
                                market_price=_drop_price,
                                seconds_to_close=_drop_stc_raw,
                                calibrated_prob=_drop.get("calibrated_prob"),
                                edge=_drop.get("edge"),
                                ofa_adjustment=_drop.get("ofa_adjustment"),
                                strategy=_drop_strat,
                                z_score=_drop.get("z_score"),
                                vol_regime=_drop.get("vol_regime"),
                                calibrated_prob_raw=_drop.get("calibrated_prob_raw"),
                                kelly_f=_drop.get("kelly_f"),
                                position_size=_drop.get("position_size"),
                                breakeven_wr=_bewr,
                                ask_depth=_drop.get("ob_snapshot", {}).get("ask_depth"),
                                best_ask_source=_drop.get("best_ask_source"),
                                raw_prob=_drop.get("raw_prob"),
                                calibration_method=_drop.get("calibration_method"),
                                fee_adjusted_edge=_drop.get("fee_adjusted_edge"),
                                product_type=_drop.get("product_type"),
                                cal_mlp_request_id=_drop.get("cal_mlp_request_id"),
                                cal_mlp_skipped_reason=_drop.get("cal_mlp_skipped_reason"),
                                cal_mlp_p_mean=_drop.get("cal_mlp_p_mean"),
                                cal_mlp_p_std=_drop.get("cal_mlp_p_std"),
                                cal_mlp_final_lo=_drop.get("cal_mlp_final_lo"),
                                cal_mlp_final_hi=_drop.get("cal_mlp_final_hi"),
                                cal_mlp_train_id=_drop.get("cal_mlp_train_id"))
                        except Exception:
                            logging.warning(
                                "insert_evaluated_opportunity failed (%s)",
                                _bleed_stage, exc_info=True)

        if not selected:
            self._last_scan_stats = scan_stats
            _log_postloop_dt()
            return None

        # Log top pick for scan journal
        best = max(selected, key=lambda c: c["edge"])
        self._logger.log_scan({
            "type": "opportunity",
            "candidates_evaluated": len(candidates),
            "candidates_after_single_asset": len(filtered),
            "selected_count": len(selected),
            "chosen_strategy": best.get("strategy"),
            **{k: v for k, v in best.items() if k not in ("strategy_scores", "ob_snapshot")},
        })
        self._last_scan_stats = scan_stats
        _log_postloop_dt()
        return selected

    # ── Price shadow processor ───────────────────────────────────────────
    def _process_price_shadow(self, queue: list) -> None:
        """Shadow-evaluate 70-85c POR rejections to collect edge data.

        Runs AFTER both scan loops complete. Entire body in try/except —
        a crash here cannot affect candidate selection or trading.
        """
        try:
            for item in queue:
                ticker = item["ticker"]
                best_ask = item["best_ask"]
                spot = item["spot"]
                threshold = item["threshold"]
                blended_rv = item["blended_rv"]
                stc = item["seconds_remaining"]
                asset = item["asset"]
                _pt = item["product_type"]

                # Re-run probability with market price (z-score sanity check)
                prob_with_market = ProbabilityEngine.compute(
                    spot, threshold, stc, blended_rv,
                    market_price_cents=best_ask,
                    asset=asset, product_type=_pt,
                )
                if not prob_with_market.get("tradeable"):
                    continue

                final_prob = prob_with_market["calibrated_prob"]
                raw_prob = prob_with_market.get("raw_prob")
                calibration_method = prob_with_market.get("calibration_method")

                # Temperature scaling (Layer 1)
                _hourly_pre_temp_prob = None
                _tempcfg = get_market_config(_pt)
                _temp_t = _tempcfg.temperature_t if _tempcfg.temperature_enabled else None
                _configured_temp_t = _temp_t  # record configured T for instrumentation (before CalEngine override)
                if _temp_t is not None and _temp_t == 1.0:
                    _temp_t = None
                _reg_engine_t = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine_t is not None and _reg_engine_t.is_learned_method_active():
                    _temp_t = None
                    _hourly_pre_temp_prob = final_prob
                if _temp_t is not None:
                    _hourly_pre_temp_prob = final_prob
                    _p = max(0.001, min(0.999, final_prob))
                    _z = math.log(_p / (1.0 - _p))
                    final_prob = 1.0 / (1.0 + math.exp(-_z / _temp_t))

                # Dynamic cap / learned ceiling
                _dyn_cap = ProbabilityEngine._dynamic_cap(stc, product_type=_pt)
                _reg_engine_c = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine_c is not None and _reg_engine_c.is_learned_method_active():
                    final_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, final_prob))
                else:
                    final_prob = max(0.01, min(_dyn_cap, final_prob))

                # ── Shadow instrumentation ──
                _hourly_shadow_temp_2_0 = None
                _hourly_shadow_temp_1_0 = None
                _hourly_shadow_temp_2_5 = None
                _hourly_shadow_temp_1_75 = None
                _hourly_shadow_temp_3_0 = None
                _hourly_shadow_blend_50 = None
                _hourly_shadow_blend_20 = None
                _hourly_shadow_blend_30 = None
                _hourly_shadow_blend_60 = None
                _hourly_post_temp_prob = None

                _shadow_base_ps = _hourly_pre_temp_prob
                if _shadow_base_ps is None and _pt == "spx_hourly":
                    _shadow_base_ps = prob_with_market["calibrated_prob"]
                    _hourly_pre_temp_prob = _shadow_base_ps
                    _temp_t = 1.0

                if _shadow_base_ps is not None:
                    _sp = max(0.001, min(0.999, _shadow_base_ps))
                    _sz = math.log(_sp / (1.0 - _sp))
                    _hourly_shadow_temp_2_0 = 1.0 / (1.0 + math.exp(-_sz / 2.0))
                    _hourly_shadow_temp_2_5 = 1.0 / (1.0 + math.exp(-_sz / 2.5))
                    _hourly_shadow_temp_1_75 = 1.0 / (1.0 + math.exp(-_sz / 1.75))
                    _hourly_shadow_temp_3_0 = 1.0 / (1.0 + math.exp(-_sz / 3.0))
                    if _pt == "spx_hourly":
                        _hourly_shadow_temp_1_0 = 1.0 / (1.0 + math.exp(-_sz / 1.5))
                    else:
                        _hourly_shadow_temp_1_0 = _shadow_base_ps
                    _hourly_post_temp_prob = final_prob
                    # 70-85c always < ENDGAME_BLEND_PRICE
                    _mkt_p = best_ask / 100.0
                    _hourly_shadow_blend_20 = 0.80 * final_prob + 0.20 * _mkt_p
                    _hourly_shadow_blend_30 = 0.70 * final_prob + 0.30 * _mkt_p
                    _hourly_shadow_blend_50 = 0.50 * final_prob + 0.50 * _mkt_p
                    _hourly_shadow_blend_60 = 0.40 * final_prob + 0.60 * _mkt_p

                # Market blend (70-85c always < ENDGAME_BLEND_PRICE)
                _mcfg = get_market_config(_pt)
                _effective_blend_w = _mcfg.market_blend_w
                market_implied_prob = best_ask / 100.0
                final_prob = (1.0 - _effective_blend_w) * final_prob + _effective_blend_w * market_implied_prob

                edge = final_prob - best_ask / 100.0

                # Fee-adjusted edge
                est_fee_1c = calculate_fee(1, best_ask, is_taker=True,
                                           fee_mult_taker=_mcfg.fee_multiplier_taker,
                                           fee_mult_maker=_mcfg.fee_multiplier_maker)
                fee_adjusted_edge = edge - est_fee_1c / 100.0

                # Sizing + strategy for instrumentation (all in try/except — cannot break insert)
                _ps_kelly_f = None
                _ps_position = None
                _ps_drawdown = None
                _ps_strategy = None
                _ps_ev = None
                try:
                    _ps_ev = round(
                        (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c, 2)
                    _ps_balance = self._get_balance_cached()
                    if _ps_balance and _ps_balance > 0:
                        _ps_sizing = self._sizer.compute(final_prob, best_ask, _ps_balance)
                        _ps_kelly_f = _ps_sizing["kelly_f"]
                        _ps_position = _ps_sizing["contracts"]
                        _ps_drawdown = _ps_sizing["drawdown_scaler"]
                        # Apply product-type Kelly fraction + risk cap
                        _ps_scfg = get_market_config(_pt)
                        if _ps_scfg.kelly_fraction < 1.0:
                            _ps_position = max(1, int(_ps_position * _ps_scfg.kelly_fraction))
                        _ps_type_max = int((_ps_balance * _ps_scfg.max_risk_per_trade) / best_ask)
                        if _ps_position > _ps_type_max:
                            _ps_position = max(1, _ps_type_max)
                        _ps_strat_data = {
                            "z_score": prob_with_market.get("z_score"),
                            "calibrated_prob": final_prob,
                            "spot": spot, "threshold": threshold,
                            "seconds_to_close": stc, "blended_rv": blended_rv,
                            "vol_regime": item["vol_regime"],
                            "best_yes_ask": best_ask,
                            "best_ask_depth": item["ask_depth"],
                            "total_ob_depth": 0,
                            "convergence_velocity": 0,
                            "edge": edge,
                            "min_entry_price": _ps_scfg.min_entry_price,
                            "max_entry_price": _ps_scfg.max_entry_price,
                        }
                        _ps_strategy, _ = evaluate_execution_strategy(_ps_strat_data)
                except Exception:
                    logging.debug("price_shadow sizing/strategy failed", exc_info=True)

                # Dedup + DB insert
                _ps_stage = "price_shadow_no_xrp" if asset != "XRP" else "price_shadow_xrp"
                _dedup_key = (ticker, _ps_stage)
                if _dedup_key in self._eval_opp_seen:
                    continue
                self._eval_opp_seen.add(_dedup_key)
                self._state.insert_evaluated_opportunity(
                    ticker, item["event_ticker"], asset,
                    _ps_stage,
                    spot_price=spot, threshold=threshold,
                    volatility=blended_rv, market_price=best_ask,
                    seconds_to_close=stc,
                    calibrated_prob=final_prob,
                    edge=edge, fee_adjusted_edge=fee_adjusted_edge,
                    z_score=prob_with_market.get("z_score"),
                    vol_regime=item["vol_regime"],
                    breakeven_wr=best_ask / 100.0,
                    calibrated_prob_raw=prob_with_market["calibrated_prob"],
                    kelly_f=_ps_kelly_f,
                    position_size=_ps_position,
                    drawdown_scaler=_ps_drawdown,
                    strategy=_ps_strategy,
                    expected_value=_ps_ev,
                    raw_prob=raw_prob,
                    calibration_method=calibration_method,
                    ask_depth=item["ask_depth"],
                    best_ask_source=item["best_ask_source"],
                    product_type=_pt,
                    hourly_pre_temp_prob=_hourly_pre_temp_prob,
                    hourly_applied_temp_t=_configured_temp_t,
                    hourly_shadow_temp_2_0=_hourly_shadow_temp_2_0,
                    hourly_shadow_temp_1_0=_hourly_shadow_temp_1_0,
                    hourly_shadow_temp_2_5=_hourly_shadow_temp_2_5,
                    hourly_shadow_blend_50=_hourly_shadow_blend_50,
                    hourly_shadow_temp_1_75=_hourly_shadow_temp_1_75,
                    hourly_shadow_temp_3_0=_hourly_shadow_temp_3_0,
                    hourly_shadow_blend_20=_hourly_shadow_blend_20,
                    hourly_shadow_blend_30=_hourly_shadow_blend_30,
                    hourly_shadow_blend_60=_hourly_shadow_blend_60,
                    hourly_post_temp_prob=_hourly_post_temp_prob,
                    **item["_oft_db"], **item["_shadow_diag"])
        except Exception:
            logging.warning("price_shadow processing error", exc_info=True)

    def _process_overnight_lp_shadow(self, queue: list) -> None:
        """Shadow-evaluate 50-85c YES contracts during overnight hours (00-12 UTC).

        Thesis: overnight market makers are slow/absent, so cheap YES contracts
        have stale pricing. The model correctly predicts 90%+ probability on
        outcomes the market only quotes at 50-60c.

        Includes vol-spike circuit breaker (2x overnight median → skip asset)
        and dual execution simulation (taker at best_ask, maker at best_bid+1).

        Shadow-only — never places orders. Entire body in try/except so
        a crash here cannot affect candidate selection or live trading.
        """
        try:
            now_ts = time.time()
            _cutoff_ts = now_ts - OVERNIGHT_LP_VOL_HISTORY_DAYS * 86400

            for item in queue:
                ticker = item["ticker"]
                best_ask = item["best_ask"]
                best_bid = item.get("best_bid")
                spot = item["spot"]
                threshold = item["threshold"]
                blended_rv = item["blended_rv"]
                stc = item["seconds_remaining"]
                asset = item["asset"]
                _pt = item["product_type"]

                # ── Vol-spike circuit breaker ──
                # Prune entries older than OVERNIGHT_LP_VOL_HISTORY_DAYS
                while (self._overnight_rv_history[asset]
                       and self._overnight_rv_history[asset][0][0] < _cutoff_ts):
                    self._overnight_rv_history[asset].popleft()
                # Compute median from PRIOR history (before appending current value,
                # so the current observation doesn't bias the median toward itself)
                _rv_vals = [rv for _, rv in self._overnight_rv_history[asset]]
                # Record current blended_rv AFTER extracting prior history
                self._overnight_rv_history[asset].append((now_ts, blended_rv))
                # Need at least 100 prior observations (~8 min of 5s ticks) before
                # the breaker activates. On cold start / night one, the breaker is
                # disabled — we want data collection, not false blocks.
                _rv_median = None
                _vol_breaker_active = len(_rv_vals) >= 100
                if _vol_breaker_active:
                    _rv_sorted = sorted(_rv_vals)
                    _rv_median = _rv_sorted[len(_rv_sorted) // 2]
                if _vol_breaker_active and blended_rv > OVERNIGHT_LP_VOL_SPIKE_MULT * _rv_median:
                    self._overnight_lp_vol_skip_count += 1
                    try:
                        self._logger.log_opportunity({
                            "filter_stage": "overnight_lp_vol_skip",
                            "ticker": ticker,
                            "asset": asset,
                            "blended_rv": round(blended_rv, 8),
                            "overnight_median_rv": round(_rv_median, 8),
                            "spike_ratio": round(blended_rv / _rv_median, 4) if _rv_median > 0 else None,
                            "threshold_mult": OVERNIGHT_LP_VOL_SPIKE_MULT,
                            "seconds_to_close": round(stc, 1),
                            "market_price": best_ask,
                        })
                    except Exception:
                        pass
                    continue

                # Re-run probability engine with market price
                prob_result = ProbabilityEngine.compute(
                    spot, threshold, stc, blended_rv,
                    market_price_cents=best_ask,
                    asset=asset, product_type=_pt,
                )
                if not prob_result.get("tradeable"):
                    continue

                final_prob = prob_result["calibrated_prob"]
                raw_prob = prob_result.get("raw_prob")
                calibration_method = prob_result.get("calibration_method")
                z_score = prob_result.get("z_score")

                # Temperature scaling (same as main pipeline)
                _tempcfg = get_market_config(_pt)
                _temp_t = _tempcfg.temperature_t if _tempcfg.temperature_enabled else None
                if _temp_t is not None and _temp_t == 1.0:
                    _temp_t = None
                _reg_engine = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine is not None and _reg_engine.is_learned_method_active():
                    _temp_t = None
                if _temp_t is not None:
                    _p = max(0.001, min(0.999, final_prob))
                    _z = math.log(_p / (1.0 - _p))
                    final_prob = 1.0 / (1.0 + math.exp(-_z / _temp_t))

                # Dynamic cap / learned ceiling
                _dyn_cap = ProbabilityEngine._dynamic_cap(stc, product_type=_pt)
                _reg_engine_c = _resolve_cal_engine(_pt, asset, require_enabled=True)
                if _reg_engine_c is not None and _reg_engine_c.is_learned_method_active():
                    final_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, final_prob))
                else:
                    final_prob = max(0.01, min(_dyn_cap, final_prob))

                # Market blend
                _mcfg = get_market_config(_pt)
                _effective_blend_w = _mcfg.market_blend_w
                market_implied_prob = best_ask / 100.0
                final_prob = (1.0 - _effective_blend_w) * final_prob + _effective_blend_w * market_implied_prob

                # ── Min cal_prob gate ──
                if final_prob < OVERNIGHT_LP_MIN_CAL_PROB:
                    continue

                # Edge computation
                edge = final_prob - best_ask / 100.0
                est_fee_1c = calculate_fee(1, best_ask, is_taker=True,
                                           fee_mult_taker=_mcfg.fee_multiplier_taker,
                                           fee_mult_maker=_mcfg.fee_multiplier_maker)
                fee_adjusted_edge = edge - est_fee_1c / 100.0

                # ── Min edge gate ──
                if fee_adjusted_edge < OVERNIGHT_LP_MIN_EDGE_PCT:
                    continue

                # ── Sizing (taker simulation — primary metric) ──
                _olp_kelly_f = None
                _olp_position_taker = None
                _olp_ev_taker = None
                _olp_drawdown = None
                _olp_balance = self._get_balance_cached()
                if _olp_balance and _olp_balance > 0:
                    _olp_sizing = self._sizer.compute(final_prob, best_ask, _olp_balance)
                    _olp_kelly_f = _olp_sizing["kelly_f"]
                    _olp_position_taker = _olp_sizing["contracts"]
                    _olp_drawdown = _olp_sizing["drawdown_scaler"]
                    # Apply overnight LP Kelly fraction + risk cap
                    if OVERNIGHT_LP_KELLY_FRACTION < 1.0:
                        _olp_position_taker = max(1, int(_olp_position_taker * OVERNIGHT_LP_KELLY_FRACTION))
                    _olp_type_max = int((_olp_balance * OVERNIGHT_LP_MAX_RISK_PER_TRADE) / best_ask)
                    if _olp_position_taker > _olp_type_max:
                        _olp_position_taker = max(1, _olp_type_max)
                    _olp_ev_taker = round(
                        (final_prob * (100 - best_ask)) - ((1 - final_prob) * best_ask) - est_fee_1c, 2)

                # ── Maker simulation ──
                # Post at best_bid + 1c (penny improvement)
                _olp_maker_price = None
                _olp_position_maker = None
                _olp_ev_maker = None
                _olp_maker_fee_adj_edge = None
                if best_bid is not None and best_bid > 0:
                    _olp_maker_price = best_bid + 1
                    if _olp_maker_price <= best_ask:  # sanity: maker must be below ask
                        _maker_edge = final_prob - _olp_maker_price / 100.0
                        _maker_fee_1c = calculate_fee(1, _olp_maker_price, is_taker=False,
                                                      fee_mult_taker=_mcfg.fee_multiplier_taker,
                                                      fee_mult_maker=_mcfg.fee_multiplier_maker)
                        _olp_maker_fee_adj_edge = _maker_edge - _maker_fee_1c / 100.0
                        if _olp_balance and _olp_balance > 0:
                            _m_sizing = self._sizer.compute(final_prob, _olp_maker_price, _olp_balance)
                            _olp_position_maker = _m_sizing["contracts"]
                            if OVERNIGHT_LP_KELLY_FRACTION < 1.0:
                                _olp_position_maker = max(1, int(_olp_position_maker * OVERNIGHT_LP_KELLY_FRACTION))
                            _m_type_max = int((_olp_balance * OVERNIGHT_LP_MAX_RISK_PER_TRADE) / _olp_maker_price)
                            if _olp_position_maker > _m_type_max:
                                _olp_position_maker = max(1, _m_type_max)
                            _olp_ev_maker = round(
                                (final_prob * (100 - _olp_maker_price)) -
                                ((1 - final_prob) * _olp_maker_price) - _maker_fee_1c, 2)
                    else:
                        _olp_maker_price = None  # bid+1 crossed the ask — no valid maker price

                # ── JSONL log ──
                try:
                    self._logger.log_opportunity({
                        "filter_stage": "overnight_lp_shadow",
                        "ticker": ticker,
                        "event_ticker": item["event_ticker"],
                        "asset": asset,
                        "side": "yes",
                        "market_price": best_ask,
                        "model_prob": round(final_prob, 6),
                        "edge": round(edge, 6),
                        "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                        "kelly_f": round(_olp_kelly_f, 6) if _olp_kelly_f else None,
                        "taker_position_size": _olp_position_taker,
                        "taker_ev": _olp_ev_taker,
                        "maker_price": _olp_maker_price,
                        "maker_position_size": _olp_position_maker,
                        "maker_ev": _olp_ev_maker,
                        "maker_fee_adj_edge": round(_olp_maker_fee_adj_edge, 6) if _olp_maker_fee_adj_edge else None,
                        "best_bid": best_bid,
                        "seconds_to_close": round(stc, 1),
                        "spot_price": spot,
                        "threshold": threshold,
                        "volatility": blended_rv,
                        "vol_regime": item["vol_regime"],
                        "overnight_median_rv": round(_rv_median, 8) if _rv_median is not None else None,
                        "vol_spike_ratio": round(blended_rv / _rv_median, 4) if _rv_median and _rv_median > 0 else None,
                        "vol_breaker_active": _vol_breaker_active,
                        "raw_prob": round(raw_prob, 6) if raw_prob is not None else None,
                        "z_score": z_score,
                        "ask_depth": item["ask_depth"],
                    })
                except Exception:
                    logging.debug("overnight_lp_shadow log failed", exc_info=True)

                # ── DB insert (taker simulation as primary) ──
                _dedup_key = (ticker, "overnight_lp_shadow")
                if _dedup_key in self._eval_opp_seen:
                    continue
                self._eval_opp_seen.add(_dedup_key)
                try:
                    self._state.insert_evaluated_opportunity(
                        ticker, item["event_ticker"], asset,
                        "overnight_lp_shadow",
                        rejection_reason=(
                            f"shadow: cal_prob {final_prob:.4f} >= {OVERNIGHT_LP_MIN_CAL_PROB}, "
                            f"fee_adj_edge {fee_adjusted_edge:.4f} >= {OVERNIGHT_LP_MIN_EDGE_PCT}, "
                            f"taker@{best_ask}c maker@{_olp_maker_price}c"
                        ),
                        spot_price=spot, threshold=threshold,
                        volatility=blended_rv, market_price=best_ask,
                        seconds_to_close=stc,
                        calibrated_prob=final_prob, edge=edge,
                        fee_adjusted_edge=fee_adjusted_edge,
                        ofa_adjustment=None,
                        z_score=z_score,
                        vol_regime=item["vol_regime"],
                        calibrated_prob_raw=prob_result["calibrated_prob"],
                        kelly_f=_olp_kelly_f,
                        position_size=_olp_position_taker,
                        drawdown_scaler=_olp_drawdown,
                        breakeven_wr=best_ask / 100.0,
                        expected_value=_olp_ev_taker,
                        ask_depth=item["ask_depth"],
                        best_ask_source=item["best_ask_source"],
                        raw_prob=raw_prob,
                        calibration_method=calibration_method,
                        product_type=_pt,
                        **item["_oft_db"], **item["_shadow_diag"])
                except Exception:
                    logging.warning("insert_evaluated_opportunity failed (overnight_lp_shadow)", exc_info=True)
        except Exception:
            logging.warning("overnight_lp_shadow processing error", exc_info=True)

    def _process_low_price_shadow(self, queue: list) -> None:
        """Shadow-evaluate 20-79c 15M signals with dual sizing simulation.

        Collects data for potential MIN_ENTRY_PRICE expansion. Logs to both
        evaluated_opportunities (for settlement linking) and low_price_shadow_signals
        (for correlation tracking and capped-sizing counterfactuals).

        Two sizing simulations per signal:
        - Full Kelly: current sizer output (what would happen if we just lowered the floor)
        - Capped Kelly: LP_KELLY_FRACTION × LP_MAX_RISK_PER_TRADE (conservative alternative)

        Correlation tracking: per-window and per-hour signal counts to measure
        simultaneous low-price exposure.

        Shadow-only — never places orders. Entire body in try/except so
        a crash here cannot affect candidate selection or live trading.
        """
        try:
            for item in queue:
                ticker = item["ticker"]
                best_ask = item["best_ask"]
                spot = item["spot"]
                threshold = item["threshold"]
                blended_rv = item["blended_rv"]
                stc = item["seconds_remaining"]
                asset = item["asset"]
                _pt = item["product_type"]
                event_ticker = item["event_ticker"]

                # Dedup: skip if already processed for this ticker
                _dedup_key = (ticker, "low_price_shadow")
                if _dedup_key in self._eval_opp_seen:
                    continue
                self._eval_opp_seen.add(_dedup_key)

                if item.get("has_prob"):
                    # IE path: prob already computed
                    final_prob = item["final_prob"]
                    raw_prob = item["raw_prob"]
                    calibration_method = item["calibration_method"]
                    z_score = item["z_score"]
                    edge = item["edge"]
                    fee_adjusted_edge = item["fee_adjusted_edge"]
                    est_fee_1c = item["est_fee_1c"]
                    calibrated_prob_raw = item["calibrated_prob_raw"]
                else:
                    # POR path: need to compute probability
                    prob_result = ProbabilityEngine.compute(
                        spot, threshold, stc, blended_rv,
                        market_price_cents=best_ask,
                        asset=asset, product_type=_pt,
                    )
                    if not prob_result.get("tradeable"):
                        continue
                    final_prob = prob_result["calibrated_prob"]
                    raw_prob = prob_result.get("raw_prob")
                    calibration_method = prob_result.get("calibration_method")
                    z_score = prob_result.get("z_score")
                    calibrated_prob_raw = final_prob

                    # Temperature scaling
                    _tempcfg = get_market_config(_pt)
                    _temp_t = _tempcfg.temperature_t if _tempcfg.temperature_enabled else None
                    if _temp_t is not None and _temp_t == 1.0:
                        _temp_t = None
                    _reg_engine = _resolve_cal_engine(_pt, asset, require_enabled=True)
                    if _reg_engine is not None and _reg_engine.is_learned_method_active():
                        _temp_t = None
                    if _temp_t is not None:
                        _p = max(0.001, min(0.999, final_prob))
                        _z = math.log(_p / (1.0 - _p))
                        final_prob = 1.0 / (1.0 + math.exp(-_z / _temp_t))

                    # Dynamic cap / learned ceiling
                    _dyn_cap = ProbabilityEngine._dynamic_cap(stc, product_type=_pt)
                    _reg_engine_c = _resolve_cal_engine(_pt, asset, require_enabled=True)
                    if _reg_engine_c is not None and _reg_engine_c.is_learned_method_active():
                        final_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, final_prob))
                    else:
                        final_prob = max(0.01, min(_dyn_cap, final_prob))

                    # Market blend
                    _mcfg = get_market_config(_pt)
                    _effective_blend_w = _mcfg.market_blend_w
                    market_implied_prob = best_ask / 100.0
                    final_prob = (1.0 - _effective_blend_w) * final_prob + _effective_blend_w * market_implied_prob

                    # Edge computation
                    edge = final_prob - best_ask / 100.0
                    est_fee_1c = calculate_fee(1, best_ask, is_taker=True,
                                               fee_mult_taker=_mcfg.fee_multiplier_taker,
                                               fee_mult_maker=_mcfg.fee_multiplier_maker)
                    fee_adjusted_edge = edge - est_fee_1c / 100.0

                # ── Full Kelly sizing (what would happen if we just lowered the floor) ──
                _full_kelly_f = None
                _full_position = None
                _full_drawdown = None
                _lp_balance = self._get_balance_cached()
                if _lp_balance and _lp_balance > 0:
                    _full_sizing = self._sizer.compute(final_prob, best_ask, _lp_balance)
                    _full_kelly_f = _full_sizing["kelly_f"]
                    _full_position = _full_sizing["contracts"]
                    _full_drawdown = _full_sizing["drawdown_scaler"]
                    # Apply standard 15M Kelly fraction + risk cap
                    _scfg = get_market_config(_pt)
                    if _scfg.kelly_fraction < 1.0:
                        _full_position = max(1, int(_full_position * _scfg.kelly_fraction))
                    _type_max = int((_lp_balance * _scfg.max_risk_per_trade) / best_ask)
                    if _full_position > _type_max:
                        _full_position = max(1, _type_max)

                # ── Capped Kelly sizing (conservative alternative) ──
                _capped_kelly_f = None
                _capped_position = None
                if _lp_balance and _lp_balance > 0:
                    _cap_sizing = self._sizer.compute(final_prob, best_ask, _lp_balance)
                    _capped_kelly_f = _cap_sizing["kelly_f"]
                    _capped_position = _cap_sizing["contracts"]
                    # Apply LP-specific caps
                    if LP_KELLY_FRACTION < 1.0:
                        _capped_position = max(1, int(_capped_position * LP_KELLY_FRACTION))
                    _cap_type_max = int((_lp_balance * LP_MAX_RISK_PER_TRADE) / best_ask)
                    if _capped_position > _cap_type_max:
                        _capped_position = max(1, _cap_type_max)

                # ── Correlation tracking ──
                _window_count = self._lp_window_counts.get(event_ticker, 0) + 1
                self._lp_window_counts[event_ticker] = _window_count
                _utc_hour = datetime.datetime.now(timezone.utc).strftime("%H")
                _hour_count = self._lp_hour_signals.get(_utc_hour, 0) + 1
                self._lp_hour_signals[_utc_hour] = _hour_count

                # ── JSONL log ──
                try:
                    self._logger.log_opportunity({
                        "filter_stage": "low_price_shadow",
                        "ticker": ticker,
                        "event_ticker": event_ticker,
                        "asset": asset,
                        "market_price": best_ask,
                        "model_prob": round(final_prob, 6),
                        "edge": round(edge, 6),
                        "fee_adjusted_edge": round(fee_adjusted_edge, 6),
                        "full_kelly_f": round(_full_kelly_f, 6) if _full_kelly_f else None,
                        "full_contracts": _full_position,
                        "capped_kelly_f": round(_capped_kelly_f, 6) if _capped_kelly_f else None,
                        "capped_contracts": _capped_position,
                        "window_signal_count": _window_count,
                        "hour_signal_count": _hour_count,
                        "seconds_to_close": round(stc, 1),
                        "spot_price": spot,
                        "threshold": threshold,
                        "volatility": blended_rv,
                        "vol_regime": item["vol_regime"],
                        "z_score": z_score,
                    })
                except Exception:
                    logging.debug("low_price_shadow log failed", exc_info=True)

                # ── DB insert to evaluated_opportunities (for settlement linking) ──
                try:
                    self._state.insert_evaluated_opportunity(
                        ticker, event_ticker, asset,
                        "low_price_shadow",
                        rejection_reason=(
                            "shadow: 20-79c dual-sizing sim, "
                            "full={} capped={} w_ct={} h_ct={}".format(
                                _full_position, _capped_position,
                                _window_count, _hour_count)
                        ),
                        spot_price=spot, threshold=threshold,
                        volatility=blended_rv, market_price=best_ask,
                        seconds_to_close=stc,
                        calibrated_prob=final_prob, edge=edge,
                        fee_adjusted_edge=fee_adjusted_edge,
                        ofa_adjustment=None,
                        z_score=z_score,
                        vol_regime=item["vol_regime"],
                        calibrated_prob_raw=calibrated_prob_raw,
                        kelly_f=_full_kelly_f,
                        position_size=_full_position,
                        drawdown_scaler=_full_drawdown,
                        breakeven_wr=best_ask / 100.0,
                        expected_value=round(
                            (final_prob * (100 - best_ask)) -
                            ((1 - final_prob) * best_ask) - est_fee_1c, 2),
                        ask_depth=item["ask_depth"],
                        best_ask_source=item["best_ask_source"],
                        raw_prob=raw_prob,
                        calibration_method=calibration_method,
                        product_type=_pt,
                        **item["_oft_db"], **item["_shadow_diag"])
                except Exception:
                    logging.warning("insert_evaluated_opportunity failed (low_price_shadow)", exc_info=True)

                # ── Insert to dedicated table (for correlation & dual-sizing analysis) ──
                try:
                  with tracked_write("opportunity_scanner", "low_price_shadow_signals_insert"):
                    self._state.conn.execute(
                        "INSERT INTO low_price_shadow_signals "
                        "(ticker, event_ticker, asset, window_id, market_price, "
                        "seconds_to_close, calibrated_prob, raw_prob, edge, fee_adjusted_edge, "
                        "z_score, vol_regime, volatility, spot_price, threshold, "
                        "full_kelly_risk_fraction, full_kelly_contracts, "
                        "capped_risk_fraction, capped_contracts, "
                        "window_signal_count, hour_signal_count, evaluation_time) "
                        "VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)",
                        (ticker, event_ticker, asset, event_ticker, best_ask,
                         stc, round(final_prob, 6),
                         round(raw_prob, 6) if raw_prob is not None else None,
                         round(edge, 6), round(fee_adjusted_edge, 6),
                         z_score, item["vol_regime"], blended_rv, spot, threshold,
                         _full_kelly_f, _full_position,
                         _capped_kelly_f, _capped_position,
                         _window_count, _hour_count,
                         datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")))
                    self._state.conn.commit()
                except Exception:
                    # RCA instrumentation (2026-05-09): match the diag fields
                    # from StateManager.insert_evaluated_opportunity so a
                    # post-deploy contention cluster across both sites lines
                    # up cleanly in the journal.
                    _diag_thread = threading.current_thread().name
                    _diag_in_tx = getattr(self._state.conn, "in_transaction", "?")
                    logging.warning(
                        f"low_price_shadow_signals insert failed "
                        f"thread={_diag_thread!r} in_tx={_diag_in_tx!s}",
                        exc_info=True,
                    )
        except Exception:
            logging.warning("low_price_shadow processing error", exc_info=True)

    def _process_no_side_shadow(self, queue: list, candidates: list = None) -> None:
        """Shadow-evaluate NO-side (buy NO contract) for all queued markets.

        Mirrors the YES-side evaluation: NO_prob = 1 - YES_prob,
        NO_ask from market NBBO. Runs through the same filter pipeline
        (price, edge, sizing) and logs to evaluated_opportunities with side='no'.

        Shadow-only by default — never places orders. EXCEPTION: weather NO-side
        live execution bypasses the shadow path when WEATHER_NO_SIDE_LIVE=True
        and NO ≤ 40c, STC ≥ 16h, assumed-prob edge > 0. In that case, a live
        candidate is appended to `candidates` (if provided).

        Entire body in try/except so a crash here cannot affect candidate
        selection or live trading.
        """
        try:
            for item in queue:
                ticker = item["ticker"]
                best_ask = item["best_ask"]
                asset = item["asset"]
                _pt = item["product_type"]
                spot = item["spot"]
                threshold = item["threshold"]
                blended_rv = item["blended_rv"]
                stc = item["seconds_remaining"]

                # ── Compute YES-side final_prob if not pre-computed ──
                # (POR entries don't have final_prob yet — need temp+cap+blend)
                if item["final_prob"] is not None:
                    yes_final_prob = item["final_prob"]
                    raw_prob = item["raw_prob"]
                    calibration_method = item["calibration_method"]
                else:
                    # Re-run probability engine (same as _process_price_shadow)
                    prob_result = ProbabilityEngine.compute(
                        spot, threshold, stc, blended_rv,
                        market_price_cents=best_ask,
                        asset=asset, product_type=_pt,
                    )
                    if not prob_result.get("tradeable"):
                        continue
                    yes_final_prob = prob_result["calibrated_prob"]
                    raw_prob = prob_result.get("raw_prob")
                    calibration_method = prob_result.get("calibration_method")

                    # Temperature scaling (Layer 1)
                    _tempcfg = get_market_config(_pt)
                    _temp_t = _tempcfg.temperature_t if _tempcfg.temperature_enabled else None
                    if _temp_t is not None and _temp_t == 1.0:
                        _temp_t = None
                    _reg_engine = _resolve_cal_engine(_pt, asset, require_enabled=True)
                    if _reg_engine is not None and _reg_engine.is_learned_method_active():
                        _temp_t = None
                    if _temp_t is not None:
                        _p = max(0.001, min(0.999, yes_final_prob))
                        _z = math.log(_p / (1.0 - _p))
                        yes_final_prob = 1.0 / (1.0 + math.exp(-_z / _temp_t))

                    # Dynamic cap / learned ceiling
                    _dyn_cap = ProbabilityEngine._dynamic_cap(stc, product_type=_pt)
                    _reg_engine_c = _resolve_cal_engine(_pt, asset, require_enabled=True)
                    if _reg_engine_c is not None and _reg_engine_c.is_learned_method_active():
                        yes_final_prob = max(0.01, min(NUMERICAL_SAFETY_CEILING, yes_final_prob))
                    else:
                        yes_final_prob = max(0.01, min(_dyn_cap, yes_final_prob))

                    # Market blend
                    _mcfg = get_market_config(_pt)
                    if best_ask < ENDGAME_BLEND_PRICE:
                        mip = best_ask / 100.0
                        yes_final_prob = (1.0 - _mcfg.market_blend_w) * yes_final_prob + _mcfg.market_blend_w * mip

                # ── NO-side computation ──
                no_prob = 1.0 - yes_final_prob
                no_price = item["no_ask"]  # actual NO ask from market NBBO

                # Price filter for NO side (use lower floor for 15M shadow collection)
                _ncfg = get_market_config(_pt)
                _no_price_floor = NO_SIDE_MIN_ENTRY_PRICE  # universal floor for NO-side shadow collection
                if not (_no_price_floor <= no_price <= _ncfg.max_entry_price):
                    # NO price out of range — skip (don't log; too much volume for OOR)
                    continue

                # Edge computation
                no_edge = no_prob - no_price / 100.0
                no_fee_1c = calculate_fee(1, no_price, is_taker=True,
                                          fee_mult_taker=_ncfg.fee_multiplier_taker,
                                          fee_mult_maker=_ncfg.fee_multiplier_maker)
                no_fee_adj_edge = no_edge - no_fee_1c / 100.0

                # ── Weather NO-side LIVE candidate (bypasses observation gate) ──
                # Model is structurally wrong on NO (predicts 3-16%, actual 79.7% WR),
                # so we use an ASSUMED 0.70 probability instead of no_prob.
                # Gates: WEATHER_NO_SIDE_LIVE, NO ≤ 40c, STC ≥ 16h, assumed edge > 0.
                # This is the CORRECT location for this gate — previously it lived in the
                # YES-side observation branch but weather NO evals flow through THIS path,
                # so the previous location was structurally dead.
                # See kb/failures/weather-no-candidate-never-fires.md
                if (_pt == "weather"
                        and WEATHER_NO_SIDE_LIVE
                        and candidates is not None
                        and stc >= WEATHER_NO_SIDE_MIN_STC
                        and no_price >= WEATHER_NO_MIN_PRICE
                        and no_price <= WEATHER_NO_MAX_PRICE
                        and not should_exclude_weather_no_ticker(ticker)):
                    _wnl_assumed_edge = WEATHER_NO_ASSUMED_PROB - no_price / 100.0 - no_fee_1c / 100.0
                    if _wnl_assumed_edge > 0:
                        _wnl_cand_dedup = (ticker, "weather_no_candidate")
                        if _wnl_cand_dedup not in self._eval_opp_seen:
                            # Skip if already holding this ticker
                            _wnl_has_pos = any(
                                p.get("ticker") == ticker
                                for p in self._state.get_open_positions())
                            if not _wnl_has_pos:
                                self._eval_opp_seen.add(_wnl_cand_dedup)
                                _wnl_cand_ev = round(
                                    (WEATHER_NO_ASSUMED_PROB * (100 - no_price))
                                    - ((1 - WEATHER_NO_ASSUMED_PROB) * no_price)
                                    - no_fee_1c, 2)
                                _wnl_sx = item.get("_shadow_extra", {})
                                try:
                                    self._state.insert_evaluated_opportunity(
                                        ticker, item["event_ticker"], asset,
                                        "candidate",
                                        spot_price=spot, threshold=threshold,
                                        volatility=blended_rv, market_price=no_price,
                                        seconds_to_close=stc,
                                        calibrated_prob=WEATHER_NO_ASSUMED_PROB,
                                        edge=round(WEATHER_NO_ASSUMED_PROB - no_price / 100.0, 6),
                                        calibration_method="assumed_prob",
                                        fee_adjusted_edge=round(_wnl_assumed_edge, 6),
                                        breakeven_wr=no_price / 100.0,
                                        expected_value=_wnl_cand_ev,
                                        vol_regime=item.get("vol_regime", "normal"),
                                        ask_depth=item.get("ask_depth"),
                                        best_ask_source=item.get("best_ask_source"),
                                        position_size=WEATHER_NO_CONTRACT_COUNT, kelly_f=0.0, drawdown_scaler=1.0,
                                        strategy="weather_no_live",
                                        product_type="weather", side="no",
                                        raw_prob=1.0 - raw_prob if raw_prob is not None else None,
                                        wx_ensemble_mean=_wnl_sx.get("wx_ensemble_mean"),
                                        wx_ensemble_std=_wnl_sx.get("wx_ensemble_std"),
                                        wx_bias_correction=_wnl_sx.get("wx_bias_correction"),
                                        wx_n_members=_wnl_sx.get("wx_n_members"),
                                        wx_market_type=_wnl_sx.get("wx_market_type"),
                                        wx_hrrr_temp=_wnl_sx.get("wx_hrrr_temp"),
                                        wx_corrected_mean=_wnl_sx.get("wx_corrected_mean"),
                                        wx_no_side_edge=_wnl_sx.get("wx_no_side_edge"),
                                        **item.get("_oft_db", {}),
                                        **item.get("_shadow_diag", {}))
                                except Exception:
                                    logging.warning(
                                        "insert_evaluated_opportunity failed (weather_no_live)",
                                        exc_info=True)
                                candidates.append({
                                    "ticker": ticker,
                                    "event_ticker": item["event_ticker"],
                                    "asset": asset,
                                    "product_type": "weather",
                                    "side": "no",
                                    "spot": spot,
                                    "threshold": threshold,
                                    "seconds_to_close": round(stc, 1),
                                    "blended_rv": blended_rv,
                                    "calibrated_prob": WEATHER_NO_ASSUMED_PROB,
                                    "z_score": 0.0,
                                    "best_yes_ask": no_price,  # NO price for execution
                                    "best_ask_source": item.get("best_ask_source"),
                                    "edge": round(WEATHER_NO_ASSUMED_PROB - no_price / 100.0, 6),
                                    "fee_adjusted_edge": round(_wnl_assumed_edge, 6),
                                    "position_size": WEATHER_NO_CONTRACT_COUNT,
                                    "kelly_f": 0.0,
                                    "drawdown_scaler": 1.0,
                                    "vol_regime": item.get("vol_regime", "normal"),
                                    "balance_at_scan": item.get("balance"),
                                    "strategy": "weather_no_live",
                                    "strategy_scores": {},
                                    "ob_snapshot": {},
                                    "calibrated_prob_raw": None,
                                    "ofa_adjustment": 0.0,
                                    "ofa_confidence": "none",
                                    "raw_prob": raw_prob,
                                    "calibration_method": "assumed_prob",
                                    "old_system_prob": None,
                                    "kalshi_oft_signals": {},
                                    "counterfactual_json": None,
                                })
                                logging.info(
                                    "WEATHER_NO_CANDIDATE: %s count=%d no_price=%dc assumed_edge=%.2f%% "
                                    "stc=%.0fs (model_no_prob=%.1f%%, assumed=%.0f%%)",
                                    ticker, WEATHER_NO_CONTRACT_COUNT, no_price, _wnl_assumed_edge * 100,
                                    stc, no_prob * 100, WEATHER_NO_ASSUMED_PROB * 100)

                # ── Hourly NO-side LIVE candidate ──
                # Uses the MODEL's no_prob (not assumed — model adds 6.9pp: 53.9% flagged vs 47.0% rejected).
                # Gate: HOURLY_NO_SIDE_LIVE, asset not in HOURLY_NO_EXCLUDED_ASSETS (empty by default
                # because all 4 assets show positive NO-side model edge — see constant comment),
                # NO price 40-54c, model edge positive, not already holding.
                # Data: z=2.61, time-split stable (54.8% both halves), all assets positive.
                if (_pt == "hourly"
                        and HOURLY_NO_SIDE_LIVE
                        and asset not in HOURLY_NO_EXCLUDED_ASSETS
                        and candidates is not None
                        and no_price >= HOURLY_NO_MIN_PRICE
                        and no_price <= HOURLY_NO_MAX_PRICE
                        and no_fee_adj_edge >= HOURLY_MIN_EDGE_PCT / 100.0):
                    _hno_cand_dedup = (ticker, "hourly_no_candidate")
                    if _hno_cand_dedup not in self._eval_opp_seen:
                        _hno_has_pos = any(
                            p.get("ticker") == ticker
                            for p in self._state.get_open_positions())
                        if not _hno_has_pos:
                            self._eval_opp_seen.add(_hno_cand_dedup)
                            _hno_ev = round(
                                (no_prob * (100 - no_price))
                                - ((1 - no_prob) * no_price)
                                - no_fee_1c, 2)
                            try:
                                self._state.insert_evaluated_opportunity(
                                    ticker, item["event_ticker"], asset,
                                    "candidate",
                                    spot_price=spot, threshold=threshold,
                                    volatility=blended_rv, market_price=no_price,
                                    seconds_to_close=stc,
                                    calibrated_prob=no_prob,
                                    edge=no_edge,
                                    calibration_method=calibration_method,
                                    fee_adjusted_edge=no_fee_adj_edge,
                                    breakeven_wr=no_price / 100.0,
                                    expected_value=_hno_ev,
                                    vol_regime=item.get("vol_regime", "normal"),
                                    ask_depth=item.get("ask_depth"),
                                    best_ask_source=item.get("best_ask_source"),
                                    position_size=HOURLY_NO_FIXED_CONTRACTS,
                                    kelly_f=0.0, drawdown_scaler=1.0,
                                    strategy="hourly_no_live",
                                    product_type="hourly", side="no",
                                    raw_prob=1.0 - raw_prob if raw_prob is not None else None,
                                    hourly_pre_temp_prob=item.get("hourly_pre_temp_prob"),
                                    hourly_applied_temp_t=item.get("hourly_applied_temp_t"),
                                    hourly_post_temp_prob=item.get("hourly_post_temp_prob"),
                                    **item.get("_oft_db", {}),
                                    **item.get("_shadow_diag", {}))
                            except Exception:
                                logging.warning(
                                    "insert_evaluated_opportunity failed (hourly_no_live)",
                                    exc_info=True)
                            candidates.append({
                                "ticker": ticker,
                                "event_ticker": item["event_ticker"],
                                "asset": asset,
                                "product_type": "hourly",
                                "side": "no",
                                "spot": spot,
                                "threshold": threshold,
                                "seconds_to_close": round(stc, 1),
                                "blended_rv": blended_rv,
                                "calibrated_prob": no_prob,
                                "z_score": 0.0,
                                "best_yes_ask": no_price,
                                "best_ask_source": item.get("best_ask_source"),
                                "edge": no_edge,
                                "fee_adjusted_edge": no_fee_adj_edge,
                                "position_size": HOURLY_NO_FIXED_CONTRACTS,
                                "kelly_f": 0.0,
                                "drawdown_scaler": 1.0,
                                "vol_regime": item.get("vol_regime", "normal"),
                                "balance_at_scan": item.get("balance"),
                                "strategy": "hourly_no_live",
                                "strategy_scores": {},
                                "ob_snapshot": {},
                                "calibrated_prob_raw": None,
                                "ofa_adjustment": 0.0,
                                "ofa_confidence": "none",
                                "raw_prob": raw_prob,
                                "calibration_method": calibration_method,
                                "old_system_prob": None,
                                "kalshi_oft_signals": {},
                                "counterfactual_json": None,
                            })
                            logging.info(
                                "HOURLY_NO_CANDIDATE: %s %s no_price=%dc edge=%.2f%% "
                                "no_prob=%.1f%% stc=%.0fs",
                                ticker, asset, no_price, no_fee_adj_edge * 100,
                                no_prob * 100, stc)

                # Edge filter (same price-dependent schedule, applied to NO price)
                if _pt == "weather":
                    _no_min_edge = WEATHER_MIN_EDGE_PCT
                elif _pt == "hourly":
                    _no_min_edge = HOURLY_MIN_EDGE_PCT
                else:
                    _no_min_edge = get_min_edge(no_price)

                # Determine filter stage
                _no_kelly_f = None
                _no_position = None
                _no_drawdown = None
                _no_ev = None
                if no_fee_adj_edge < _no_min_edge:
                    _no_filter_stage = "insufficient_edge"
                    _no_rej = f"NO net_edge {no_fee_adj_edge:.4f} < min {_no_min_edge:.4f} @{no_price}c"
                else:
                    # Compute sizing for instrumentation
                    _no_ev = round(
                        (no_prob * (100 - no_price)) - ((1 - no_prob) * no_price) - no_fee_1c, 2)
                    try:
                        _no_balance = self._get_balance_cached()
                        if _no_balance and _no_balance > 0:
                            _no_sizing = self._sizer.compute(no_prob, no_price, _no_balance)
                            _no_kelly_f = _no_sizing["kelly_f"]
                            _no_position = _no_sizing["contracts"]
                            _no_drawdown = _no_sizing["drawdown_scaler"]
                            if _ncfg.kelly_fraction < 1.0:
                                _no_position = max(1, int(_no_position * _ncfg.kelly_fraction))
                            _no_type_max = int((_no_balance * _ncfg.max_risk_per_trade) / no_price)
                            if _no_position > _no_type_max:
                                _no_position = max(1, _no_type_max)
                    except Exception:
                        logging.warning("no_side sizing failed", exc_info=True)

                    if _no_position is not None and _no_position <= 0:
                        _no_filter_stage = "zero_sizing"
                        _no_rej = "NO sizing yielded 0 contracts"
                    else:
                        # Passed all filters — assign appropriate shadow filter_stage
                        # Mirror YES-side taxonomy with no_side_ prefix
                        if _ncfg.observation_only and _ncfg.observation_filter_label:
                            _no_filter_stage = _ncfg.observation_filter_label
                        elif _pt in (None, "15m"):
                            _is_no_price_shadow = no_price < _ncfg.min_entry_price
                            if _is_no_price_shadow:
                                # NO price in shadow zone (70-85c) — mirrors YES price_shadow
                                _no_filter_stage = "no_side_price_shadow_no_xrp" if asset != "XRP" else "no_side_price_shadow_xrp"
                            elif stc > STC_SHADOW_THRESHOLD:
                                _no_filter_stage = "no_side_stc_shadow_no_xrp" if asset != "XRP" else "no_side_stc_shadow_xrp"
                            elif XRP_15M_SHADOW and asset == "XRP":
                                _no_filter_stage = "no_side_xrp_shadow"
                            else:
                                _no_filter_stage = "no_side_shadow"
                        else:
                            _no_filter_stage = "no_side_shadow"
                        _no_rej = None

                # Dedup + DB insert
                _dedup_key = (ticker, _no_filter_stage, "no")
                if _dedup_key in self._eval_opp_seen:
                    continue
                self._eval_opp_seen.add(_dedup_key)

                _sx = item.get("_shadow_extra", {})
                # Debug: warn if weather NO-side is missing ensemble data
                if _pt == "weather" and not _sx.get("wx_ensemble_mean"):
                    logging.warning(
                        "NO_SIDE_DIAG: weather %s missing wx_ensemble_mean in _shadow_extra, keys=%s",
                        ticker, list(_sx.keys()))
                # Hourly temperature fields (passed through queue)
                _no_hourly_pre = item.get("hourly_pre_temp_prob")
                _no_hourly_t = item.get("hourly_applied_temp_t")
                _no_hourly_post = item.get("hourly_post_temp_prob")
                self._state.insert_evaluated_opportunity(
                    ticker, item["event_ticker"], asset,
                    _no_filter_stage,
                    rejection_reason=_no_rej,
                    spot_price=spot, threshold=threshold,
                    volatility=blended_rv, market_price=no_price,
                    seconds_to_close=stc,
                    calibrated_prob=no_prob,
                    edge=no_edge,
                    fee_adjusted_edge=no_fee_adj_edge,
                    z_score=None,  # z-score is YES-side concept
                    vol_regime=item["vol_regime"],
                    raw_prob=1.0 - raw_prob if raw_prob is not None else None,
                    calibration_method=calibration_method,
                    breakeven_wr=no_price / 100.0,
                    expected_value=_no_ev,
                    kelly_f=_no_kelly_f,
                    position_size=_no_position,
                    drawdown_scaler=_no_drawdown,
                    ask_depth=item["ask_depth"],
                    best_ask_source=item["best_ask_source"],
                    product_type=_pt,
                    side="no",
                    wx_ensemble_mean=_sx.get("wx_ensemble_mean"),
                    wx_ensemble_std=_sx.get("wx_ensemble_std"),
                    wx_bias_correction=_sx.get("wx_bias_correction"),
                    wx_n_members=_sx.get("wx_n_members"),
                    wx_market_type=_sx.get("wx_market_type"),
                    wx_hrrr_temp=_sx.get("wx_hrrr_temp"),
                    wx_corrected_mean=_sx.get("wx_corrected_mean"),
                    wx_no_side_edge=_sx.get("wx_no_side_edge"),
                    hourly_pre_temp_prob=_no_hourly_pre,
                    hourly_applied_temp_t=_no_hourly_t,
                    hourly_post_temp_prob=_no_hourly_post,
                    **item["_oft_db"], **item["_shadow_diag"])
        except Exception:
            logging.warning("no_side_shadow processing error", exc_info=True)

    # ── Threshold parsing ─────────────────────────────────────────────────

    @staticmethod
    def _parse_threshold(market: Dict) -> Optional[float]:
        """Extract strike/threshold price from market data.

        Priority:
        1. floor_strike field (most reliable for strike-level markets)
        2. yes_sub_title "Price to beat: $X,XXX.XX" (15-minute up/down markets)
        3. Ticker pattern: KXBTC-...-B95000 -> 95000.0 (strike-level markets)
        4. Subtitle regex fallback: "above $95,000.00" -> 95000.0
        """
        # 1. floor_strike field
        floor_strike = market.get("floor_strike")
        if floor_strike is not None:
            try:
                val = float(floor_strike)
                if val > 0:
                    return val
            except (ValueError, TypeError):
                pass

        # 2. yes_sub_title: "Price to beat: $68,500.00" (15M markets)
        for field in ("yes_sub_title", "no_sub_title"):
            sub = market.get(field, "") or ""
            if "Price to beat" in sub and "TBD" not in sub:
                m = re.search(r"\$([0-9,]+\.?\d*)", sub)
                if m:
                    try:
                        return float(m.group(1).replace(",", ""))
                    except ValueError:
                        pass

        # 3. Ticker pattern: KXBTC-26FEB2114-B95000 (strike-level markets)
        ticker = market.get("ticker", "")
        parts = ticker.split("-")
        if len(parts) >= 3:
            strike_part = parts[-1]
            if strike_part.startswith("B") or strike_part.startswith("T"):
                try:
                    return float(strike_part[1:])
                except ValueError:
                    pass

        # 4. Subtitle regex: "above $95,000.00" or "above $0.55"
        subtitle = market.get("subtitle", "") or ""
        if subtitle:
            m = re.search(r"\$([0-9,]+\.?\d*)", subtitle)
            if m:
                try:
                    return float(m.group(1).replace(",", ""))
                except ValueError:
                    pass

        return None

    @staticmethod
    def _parse_weather_market_info(market: Dict):
        """Parse weather market type and bracket bounds from market dict.

        Returns (market_type, lower_bound, upper_bound) or None.
        market_type: "bracket" | "lower_tail" | "upper_tail"

        Detection uses floor_strike/cap_strike fields first, ticker prefix as fallback.
        Bracket (B-prefix): P(lower < X < upper)
        Tail (T-prefix): lower_tail if only cap_strike, upper_tail if only floor_strike
        """
        ticker = market.get("ticker", "")
        floor_strike = market.get("floor_strike")
        cap_strike = market.get("cap_strike")

        # Convert to float if present
        floor_val = None
        cap_val = None
        try:
            if floor_strike is not None:
                floor_val = float(floor_strike)
        except (ValueError, TypeError):
            pass
        try:
            if cap_strike is not None:
                cap_val = float(cap_strike)
        except (ValueError, TypeError):
            pass

        # Determine market type from ticker prefix
        parts = ticker.split("-")
        strike_part = parts[-1] if len(parts) >= 3 else ""

        if strike_part.startswith("B"):
            # Bracket market
            if floor_val is not None and cap_val is not None:
                return ("bracket", floor_val, cap_val)
            # Fallback: B{upper}, infer bounds from available data
            try:
                upper = float(strike_part[1:])
            except ValueError:
                return None
            lower = floor_val if floor_val is not None else upper - 2.0
            upper = cap_val if cap_val is not None else upper
            return ("bracket", lower, upper)

        elif strike_part.startswith("T"):
            try:
                t_val = float(strike_part[1:])
            except ValueError:
                return None
            # Use floor_strike/cap_strike to disambiguate tail direction
            # Lower tail (P(X < threshold)): cap_strike present, no floor
            # Upper tail (P(X > threshold)): floor_strike present, no cap
            if cap_val is not None and floor_val is None:
                return ("lower_tail", None, cap_val)
            if floor_val is not None and cap_val is None:
                return ("upper_tail", floor_val, None)
            # Fallback: use subtitle text
            subtitle = (market.get("subtitle") or "").lower()
            if "below" in subtitle or "under" in subtitle:
                return ("lower_tail", None, t_val)
            if "above" in subtitle or "over" in subtitle:
                return ("upper_tail", t_val, None)
            # Last resort: treat as upper tail (legacy behavior)
            return ("upper_tail", t_val, None)

        return None

    # ── Orderbook helpers ─────────────────────────────────────────────────

    @staticmethod
    def _best_yes_ask_cents(ob_data: Dict) -> Optional[int]:
        """Compute best YES ask = 100 - highest NO bid.

        Handles both legacy cents format and floating-point dollar format.
        """
        no_bids = ob_data.get("no", [])
        if not no_bids:
            return None

        # Each bid is [price, quantity]. Find highest NO bid price.
        best_no_bid = None
        for entry in no_bids:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price = entry[0]
            elif isinstance(entry, dict):
                price = entry.get("price", 0)
            else:
                continue

            # Handle FP dollar format (e.g. 0.15) vs cents format (e.g. 15)
            if isinstance(price, float) and price < 1.0:
                price_cents = round(price * 100)
            else:
                price_cents = int(price)

            if best_no_bid is None or price_cents > best_no_bid:
                best_no_bid = price_cents

        if best_no_bid is None or best_no_bid <= 0:
            return None

        return 100 - best_no_bid

    @staticmethod
    def _is_severe_drift(ws_qty: int, rest_qty: int,
                         min_abs_diff: int = 1000,
                         min_ratio: float = 2.0) -> bool:
        """True if WS total qty differs from REST total qty enough to
        indicate cache corruption rather than normal book churn.

        Calibrated against actual 2026-04-24 incident values — see
        kb/failures/ws-cache-drift-silent-scan-2026-04-24.md. Both
        conditions must hold to avoid false-positive flagging during
        heavy but legitimate trading:

        - abs(ws - rest) >= min_abs_diff (meaningful absolute miss)
        - Either: ratio >= min_ratio (2× default), OR one side is
          zero and the other has >= min_abs_diff qty (total disagreement).

        Symmetric in (ws, rest) — we care about magnitude of mismatch,
        not direction. ETH case during the incident had WS < REST;
        others had WS > REST. Both are the same corruption class.
        """
        abs_diff = abs(ws_qty - rest_qty)
        if abs_diff < min_abs_diff:
            return False
        if rest_qty == 0:
            return ws_qty >= min_abs_diff
        if ws_qty == 0:
            return rest_qty >= min_abs_diff
        hi = max(ws_qty, rest_qty)
        lo = min(ws_qty, rest_qty)
        return (hi / lo) >= min_ratio or abs_diff >= min_abs_diff * 5

    def flag_ticker_drifted(self, ticker: str, cooldown_s: float = 60.0) -> None:
        """Flag a ticker to bypass the WS orderbook cache for `cooldown_s`
        seconds. Called from scan() silent-bail paths when WS-derived data
        is unusable (no best ask, no orderbook). During the cooldown,
        `_get_orderbook_cached` routes directly to REST, giving the WS
        cache a chance to re-snapshot cleanly.

        Also evicts `_ob_cache[ticker]` so the shared TTL cache doesn't
        silently serve the WS-corrupt orderbook during the bypass — see
        what-could-go-wrong C3 in
        kb/failures/ws-cache-drift-silent-scan-2026-04-24.md.

        No-op for hourly tickers (they skip WS in the first place).
        """
        _hourly_prefixes = tuple(HOURLY_SERIES_TICKERS.values())
        if ticker.startswith(_hourly_prefixes):
            return
        # Sweep expired entries if the dict has grown — prevents unbounded
        # accumulation from settled markets. Cheap; runs at most per flag.
        if len(self._ws_drift_cooldown) > 32:
            now_sweep = time.time()
            expired = [t for t, exp in self._ws_drift_cooldown.items()
                       if exp <= now_sweep]
            for t in expired:
                del self._ws_drift_cooldown[t]
        self._ws_drift_cooldown[ticker] = time.time() + cooldown_s
        # Evict shared cache so the bypass actually takes effect.
        self._ob_cache.pop(ticker, None)
        # Phase 2 (Apr 25 2026): replace the 60s symptom-bandaid
        # with a real cache reset. force_resubscribe sends a
        # get_snapshot to Kalshi (or falls back to unsub+resub),
        # which atomically replaces the corrupt WS cache. The
        # 60s REST-bypass cooldown above stays as belt-and-suspenders
        # for the brief window between detection and snapshot
        # arrival. Defensive: getattr handles bypassed-init
        # test fixtures.
        #
        # R2 / P1-6: pass purge_cache=False. Atomic replace via
        # _handle_ob_snapshot is strictly better than wipe-then-
        # wait. The drift-detector path was creating ~7-8s of
        # `no_orderbook` rejections during the snapshot+fallback
        # window — exactly when the price is moving. Stale data is
        # better than no data; the next snapshot atomically
        # replaces it. The REST bypass above already handles the
        # "use REST not stale-WS" hot path during the cooldown.
        _ml = getattr(self, "_ml", None)
        _kf = getattr(_ml, "kalshi_feed", None) if _ml else None
        if _kf is not None and getattr(_kf, "is_connected", False):
            try:
                _kf.force_resubscribe(ticker, purge_cache=False)
            except Exception:
                logging.warning(
                    "force_resubscribe from flag_ticker_drifted "
                    "failed for %s", ticker, exc_info=True)

    def _get_orderbook_cached(self, ticker: str) -> Tuple[Optional[Dict], bool]:
        """Return (orderbook_data, was_fresh_fetch). Uses TTL cache.

        Prefers real-time WS orderbook when available (zero API cost),
        falls back to REST fetch if WS data is missing or stale.

        Respects `_ws_drift_cooldown`: flagged tickers skip WS and use
        REST directly. If REST also fails while flagged, falls back to
        whatever WS data exists — stale WS beats no data at all.
        """
        now = time.time()

        # Skip WS subscription for hourly tickers — too many strikes (75/asset),
        # they never get unsubscribed properly, and pollute the dashboard.
        _hourly_prefixes = tuple(HOURLY_SERIES_TICKERS.values())
        is_hourly = ticker.startswith(_hourly_prefixes)

        # WS-bypass for drift-flagged tickers. On expiry, clear the flag
        # and fall back to the normal WS path on the next call.
        skip_ws = False
        _flag_expiry = self._ws_drift_cooldown.get(ticker)
        if _flag_expiry is not None:
            if now < _flag_expiry:
                skip_ws = True
            else:
                del self._ws_drift_cooldown[ticker]

        # Try WS orderbook first (free, real-time) — 15M only
        if (not skip_ws and self._kalshi_feed
                and self._kalshi_feed.is_connected and not is_hourly):
            ws_ob = self._kalshi_feed.get_orderbook(ticker)
            if ws_ob and now - ws_ob.get("ts", 0) < ORDERBOOK_CACHE_TTL * 2:
                # Subscribe if not already (ensures future deltas flow)
                self._kalshi_feed.subscribe_ticker(ticker)
                self._ob_cache[ticker] = (ws_ob, now)
                return (ws_ob, False)
            # No WS data yet — subscribe so it arrives for next scan
            self._kalshi_feed.subscribe_ticker(ticker)

        if not skip_ws:
            cached = self._ob_cache.get(ticker)
            if cached:
                data, fetch_time = cached
                if now - fetch_time < ORDERBOOK_CACHE_TTL:
                    return (data, False)

        # REST fallback
        try:
            ob_data = self._client.get_orderbook(ticker, depth=5)
        except Exception as e:
            # M1: if REST fails while WS is flagged, prefer stale WS over
            # returning None. Losing WS-bypass is less harmful than losing
            # orderbook data entirely.
            if skip_ws and self._kalshi_feed and not is_hourly:
                ws_fallback = self._kalshi_feed.get_orderbook(ticker)
                if ws_fallback:
                    logging.warning(
                        "WS_DRIFT_BYPASS %s: REST failed (%s), using stale "
                        "WS data as fallback", ticker, e)
                    return (ws_fallback, False)
            raise
        # Prefer orderbook_fp (new FP format), fall back to orderbook (legacy)
        orderbook_fp = ob_data.get("orderbook_fp") if ob_data else None
        if orderbook_fp:
            orderbook = self._convert_orderbook_fp(orderbook_fp)
        else:
            orderbook = ob_data.get("orderbook", ob_data) if ob_data else None
        self._ob_cache[ticker] = (orderbook, now)
        return (orderbook, True)

    def _scanner_convergence_velocity(self, ticker: str) -> float:
        """Upward ask movement in cents over convergence window, from scan history."""
        history = self._ticker_ask_history.get(ticker)
        if not history or len(history) < 2:
            return 0.0
        now = time.time()
        cutoff = now - CONVERGENCE_WINDOW_SECONDS
        oldest_price = None
        for ts, price in history:
            if ts >= cutoff:
                oldest_price = price
                break
        if oldest_price is None:
            return 0.0
        return history[-1][1] - oldest_price

    @staticmethod
    def _convert_orderbook_fp(ob_fp: Dict) -> Dict:
        """Convert orderbook_fp format to internal cents format.

        Input:  {"no_dollars": [["0.1100", "205.00"], ...], "yes_dollars": [...]}
        Output: {"no": [[11, 205], ...], "yes": [[77, 200], ...]}
        """
        result = {}
        for side in ("yes", "no"):
            entries = ob_fp.get(f"{side}_dollars") or []
            converted = []
            for entry in entries:
                if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    price_cents = round(float(entry[0]) * 100)
                    count = int(round(float(entry[1])))
                    converted.append([price_cents, count])
            result[side] = converted
        return result

    # Rejection reasons that indicate scan-broken / silent-bail paths.
    # Written by `insert_rejection()` in the bail-shaped branches of
    # scan() (no orderbook, no best ask, unparsable strike) per fix #2
    # of the 2026-04-24 WS-cache-drift PM (commit 9dd396b) so silent
    # scans leave a DB trace. The silence watchdog MUST NOT count
    # these as "scan alive" — counting them would hide the exact
    # failure class the watchdog exists to detect. Any new bail-shaped
    # rejection reason added in scan() MUST be appended here in the
    # same commit. See `tests/test_15m_silence_alert.py`
    # (TestSilent15MAlertSilentBailDetection) for the regression
    # contract.
    _BAIL_REJECTION_REASONS = (
        "no_orderbook", "no_best_ask", "threshold_unparsable",
    )
    # Empty constant would yield SQL `NOT IN ()` syntax error → silent
    # watchdog disable. Catch at module load.
    #
    # Module-load assertion policy (round-8 C3 unifying comment):
    # - HARD-ASSERT (this line): permanent silent-disable contracts.
    #   An empty `_BAIL_REJECTION_REASONS` would silently disable the
    #   watchdog — unrecoverable until the bot restarts AND a fix is
    #   deployed. Crashing at import (→ systemd backoff loop, operator
    #   notices missing PnL within minutes) is strictly better than
    #   running with the watchdog silently broken indefinitely.
    # - TEST-ONLY (e.g., `_WS_SHAPE_BAIL_REASONS` / `_THRESHOLD_SHAPE_BAIL_REASONS`
    #   partition): transient routing-degradation contracts. A
    #   forgotten bucketing mis-classifies the alert message but the
    #   bot continues to trade and the watchdog continues to fire;
    #   crashing at import would be DISPROPORTIONATELY costly because
    #   the Telegram notifier never initializes, depriving the
    #   operator of any failure signal at all.
    # The asymmetry is deliberate. New invariants should be classified
    # with this distinction in mind.
    assert _BAIL_REJECTION_REASONS, (
        "_BAIL_REJECTION_REASONS must not be empty — empty produces "
        "invalid SQL `NOT IN ()` and silently disables the watchdog.")

    # Shape buckets — partition `_BAIL_REJECTION_REASONS` into the two
    # diagnostic shapes the BAIL FLOOD alert routes between. The
    # partition + disjointness invariants are enforced via tests in
    # `tests/test_15m_silence_alert.py::TestBailFloodMessageDifferentiation`
    # (search for `test_shape_buckets_partition_bail_reasons`), NOT
    # via class-body assertions — adversarial round-4 critique C4:
    # module-load assertions on a recoverable contract (a forgotten
    # bucketing only degrades routing accuracy, not correctness)
    # would crash the bot at import → systemd backoff loop, with
    # NO Telegram alert because the Telegram client never initializes.
    # Test-time enforcement preserves the contract without the
    # production-startup risk. The original `assert _BAIL_REJECTION_REASONS`
    # at module load remains because that one guards an unambiguously
    # broken state (`NOT IN ()` SQL syntax error → silent watchdog
    # disable, even worse than crash-loop).
    _WS_SHAPE_BAIL_REASONS = frozenset({"no_orderbook", "no_best_ask"})
    _THRESHOLD_SHAPE_BAIL_REASONS = frozenset({"threshold_unparsable"})

    # Threshold-dominance ratio: classify as threshold-shape when
    # threshold-bucket count >= 3 × WS-bucket count (i.e., ≥75% of
    # bail rows are threshold-shape). Round-3 critique C4: original
    # ratio of 4 (80%) was asymmetric at small n — at n_thr=3,
    # n_ws=1 → 75% threshold but routed to BAIL FLOOD (3 < 4×1).
    # A 3-ticker incident (one asset in catalog-gap) plus a single
    # WS blip would have been the exact misroute the change is
    # meant to prevent. Loosened to 3 so the boundary covers
    # n_thr=3, n_ws=1 (3 >= 3×1). Still rejects n_thr=3, n_ws=2
    # (3 < 6) and any case where WS contributes >25% — those have
    # legitimately mixed signal and conservatively route to BAIL
    # FLOOD with the breakdown line for operator inspection.
    _THRESHOLD_SHAPE_DOMINANCE_RATIO = 3
    # Bail signal triggers when primary is stale/None AND bail rows
    # ≥ `_BAIL_MIN_ROWS_WHEN_STALE` exist in the recent window.
    # Threshold of 3 is the smallest value that:
    #   (a) Catches dedup-bounded `threshold_unparsable` floods
    #       (Kalshi rename hits 4 active tickers → 4 rows). Cap is
    #       4, threshold 3 has 1-row margin.
    #   (b) Rejects single-blip false positives (one ticker fails
    #       one tick during a quiet market right at the 10-min
    #       staleness boundary — would mis-classify as cache-drift
    #       and send the operator to the wrong KB article).
    # `no_orderbook` / `no_best_ask` floods are not deduped, so they
    # easily reach hundreds — threshold has no impact there.
    _BAIL_MIN_ROWS_WHEN_STALE = 3
    # Bail-flood query is non-indexed (LIKE on PK + filters on
    # rejection_time/reason). Throttle to avoid full table scan every
    # scan tick (~2s cadence). 30s resolution is plenty for a 600s
    # staleness check.
    _BAIL_QUERY_THROTTLE_SECONDS = 30.0
    # Hoisted from local scope to a class constant so the bail-window
    # query and the staleness check share ONE source of truth — they
    # MUST stay equal or bail-flood detection becomes inconsistent
    # with the staleness condition that gates it. Same for uptime
    # guard. R6 [A6] DRY drift fix.
    _SILENCE_AGE_THRESHOLD_SECONDS = 600     # 10 min
    _SILENCE_ALERT_MIN_UPTIME_SECONDS = 900  # bot must be up >15 min

    @classmethod
    def _bail_placeholders(cls):
        """Return the SQL placeholder tuple `(?,?,?)` matching
        `_BAIL_REJECTION_REASONS`. DRY helper used by both queries
        (R6 [A8])."""
        return ",".join("?" * len(cls._BAIL_REJECTION_REASONS))

    def _query_last_15m_alive_ts(self):
        # type: () -> Tuple[bool, Optional[str]]
        """Return `(ok, ts)` tuple. `ok=True` and `ts=str|None` on
        success. `ok=False` and `ts=None` on query failure. Tuple
        contract avoids the `False`-sentinel footgun where a future
        `if not ts:` check would conflate failure and no-data
        (R6 [A2]).

        On success, ts is the most recent ISO timestamp of a
        'scan alive' 15M signal: any KX*15M row in
        evaluated_opportunities OR any KX*15M row in
        rejected_opportunities whose reason is NOT in
        `_BAIL_REJECTION_REASONS`.

        Tracks `_silence_watchdog_warned_primary` for
        once-per-failure-burst rate-limited logging.
        """
        bail_reasons = self._BAIL_REJECTION_REASONS
        placeholders = self._bail_placeholders()
        try:
            row = self._state.conn.execute(
                "SELECT MAX(ts) FROM ("
                "  SELECT MAX(evaluation_time) AS ts "
                "  FROM evaluated_opportunities "
                "  WHERE ticker LIKE 'KX%15M%' "
                "  UNION ALL "
                "  SELECT MAX(rejection_time) AS ts "
                "  FROM rejected_opportunities "
                "  WHERE ticker LIKE 'KX%15M%' "
                f"    AND rejection_reason NOT IN ({placeholders})"
                ")",
                bail_reasons,
            ).fetchone()
        except Exception:
            if not getattr(
                    self, "_silence_watchdog_warned_primary", False):
                logging.warning(
                    "silent_15m primary query failed", exc_info=True)
                self._silence_watchdog_warned_primary = True
            return (False, None)
        if getattr(self, "_silence_watchdog_warned_primary", False):
            self._silence_watchdog_warned_primary = False
        return (True, row[0] if row else None)

    def _query_recent_bail_count(self):
        """Return the count of KX*15M bail-rejection rows in the last
        `_SILENCE_AGE_THRESHOLD_SECONDS`. Throttled to once per
        `_BAIL_QUERY_THROTTLE_SECONDS` because it's a non-indexed
        scan.

        On query failure: returns 0 AND advances the throttle clock.
        Returning 0 prevents spurious bail alerts based on a stale
        cached count after the underlying schema breaks (R6 [A1]).
        Advancing the throttle prevents a query storm during permanent
        failure (R6 [A4]). The warning log surfaces the broken state
        for the operator independently.
        """
        now = time.time()
        last = getattr(self, "_silence_bail_query_last_ts", 0.0)
        cached = getattr(self, "_silence_bail_query_last_count", 0)
        if now - last < self._BAIL_QUERY_THROTTLE_SECONDS:
            return cached
        cutoff_dt = (datetime.datetime.now(timezone.utc)
                     - datetime.timedelta(
                         seconds=self._SILENCE_AGE_THRESHOLD_SECONDS))
        cutoff_iso = (
            cutoff_dt.isoformat(timespec="microseconds")
            .replace("+00:00", "Z"))
        bail_reasons = self._BAIL_REJECTION_REASONS
        placeholders = self._bail_placeholders()
        try:
            bail_row = self._state.conn.execute(
                "SELECT COUNT(*) FROM rejected_opportunities "
                "WHERE ticker LIKE 'KX%15M%' "
                "  AND rejection_time >= ? "
                f"  AND rejection_reason IN ({placeholders})",
                (cutoff_iso, *bail_reasons),
            ).fetchone()
        except Exception:
            if not getattr(
                    self,
                    "_silence_watchdog_warned_bail_flood",
                    False):
                logging.warning(
                    "silent_15m bail-flood query failed", exc_info=True)
                self._silence_watchdog_warned_bail_flood = True
            # Both reset cached AND advance throttle: prevents spurious
            # alerts (cached stale → 0) AND query storm (re-query in 30s).
            self._silence_bail_query_last_count = 0
            self._silence_bail_query_last_ts = now
            return 0
        if getattr(
                self, "_silence_watchdog_warned_bail_flood", False):
            self._silence_watchdog_warned_bail_flood = False
        count = bail_row[0] if bail_row else 0
        self._silence_bail_query_last_count = count
        self._silence_bail_query_last_ts = now
        return count

    @classmethod
    def _format_bail_breakdown(cls, breakdown: Dict[str, int]) -> str:
        """Render breakdown dict as a stable, alphabetically-sorted
        string for log + alert display. Iterates over
        `_BAIL_REJECTION_REASONS` so any future bail reason added to
        the constant (and shape-bucketed per the module-load
        assertion) is automatically surfaced — there is no
        separately-maintained literal list of reasons.

        Sort order is alphabetical (not tuple order) — alert messages
        going to operator memory benefit from stable layout
        independent of internal constant ordering. Adversarial round-2
        critique C5: tuple-order coupled display layout to opaque
        internal order, which a maintainer reordering for any reason
        would silently change.

        Round-8 C1: each `reason=count` pair is wrapped in backticks
        so word-internal underscores in reason names (e.g., `no_best_ask`,
        `threshold_unparsable`) are inside an inline-code span and
        cannot be misinterpreted as italic markers by Telegram's
        legacy Markdown parser. Without this, an odd-parity underscore
        count in the rendered message could fail at parse_mode=Markdown
        and the alert would never reach the operator.
        """
        return ", ".join(
            f"`{r}={breakdown.get(r, 0)}`"
            for r in sorted(cls._BAIL_REJECTION_REASONS))

    def _query_recent_bail_breakdown(self):
        """Return Dict[str, int] mapping bail rejection_reason → count
        over the same window as `_query_recent_bail_count`. Used by the
        BAIL FLOOD alert path to differentiate WS-cache-drift signature
        (no_orderbook/no_best_ask, tens-to-hundreds of rows) from the
        Kalshi-side threshold-publish issue (threshold_unparsable,
        ≤4 dedup-bounded rows). May 4 2026 incident: alert message
        hardcoded "WS-cache-drift recurrence" so an operator hit by
        the threshold-only shape was sent to the wrong KB doc.
        See kb/failures/threshold-tbd-stuck-may04.md.

        Throttled by `_BAIL_QUERY_THROTTLE_SECONDS` independent of
        `_query_recent_bail_count` — separate cache state by design
        so a count-query call doesn't inadvertently refresh the
        breakdown cache (or vice versa).

        Returns empty dict on query failure (caller MUST handle missing
        keys defensively via `.get(reason, 0)`). Failure path also
        advances the throttle clock to avoid query storm during
        permanent failure, matching `_query_recent_bail_count`.
        """
        now = time.time()
        last = getattr(self, "_silence_bail_breakdown_last_ts", 0.0)
        cached = getattr(self, "_silence_bail_breakdown_last_dict", {})
        if now - last < self._BAIL_QUERY_THROTTLE_SECONDS:
            return cached
        cutoff_dt = (datetime.datetime.now(timezone.utc)
                     - datetime.timedelta(
                         seconds=self._SILENCE_AGE_THRESHOLD_SECONDS))
        cutoff_iso = (
            cutoff_dt.isoformat(timespec="microseconds")
            .replace("+00:00", "Z"))
        bail_reasons = self._BAIL_REJECTION_REASONS
        placeholders = self._bail_placeholders()
        try:
            rows = self._state.conn.execute(
                "SELECT rejection_reason, COUNT(*) "
                "FROM rejected_opportunities "
                "WHERE ticker LIKE 'KX%15M%' "
                "  AND rejection_time >= ? "
                f"  AND rejection_reason IN ({placeholders}) "
                "GROUP BY rejection_reason",
                (cutoff_iso, *bail_reasons),
            ).fetchall()
        except Exception:
            # Mirror `_query_recent_bail_count` failure handling:
            # rate-limited warning so a permanent failure surfaces in
            # journalctl exactly once (not every tick), AND the alert
            # path can detect the failure via empty-dict return and
            # render an explicit "(breakdown unavailable)" message
            # instead of zero-everywhere (adversarial round-2 C1).
            #
            # Round-3 C1/C5: preserve last-good cache on transient
            # failure. Clobbering to {} on a one-tick locked-DB error
            # caused the alert to flip routing to BAIL FLOOD (with
            # "(breakdown unavailable)") for one throttle window, then
            # back to THRESHOLD when the next tick succeeded — two
            # contradictory dedup_keys for the same incident, sending
            # the operator to opposite KB docs. Now the cache survives
            # transient failures; only a never-successful path returns
            # the empty default.
            if not getattr(
                    self,
                    "_silence_watchdog_warned_breakdown",
                    False):
                logging.warning(
                    "silent_15m bail-breakdown query failed",
                    exc_info=True)
                self._silence_watchdog_warned_breakdown = True
            # Initialize cache to empty if this is the first call ever
            # (no last-good); otherwise preserve the existing dict.
            if not hasattr(self, "_silence_bail_breakdown_last_dict"):
                self._silence_bail_breakdown_last_dict = {}
            # Advance throttle clock so query storm is bounded.
            self._silence_bail_breakdown_last_ts = now
            return self._silence_bail_breakdown_last_dict
        # Reset warn-flag on success so the next failure also logs once
        # (adversarial round-2 C9 — match count query's reset pattern).
        if getattr(
                self, "_silence_watchdog_warned_breakdown", False):
            self._silence_watchdog_warned_breakdown = False
        breakdown = {row[0]: row[1] for row in rows}
        self._silence_bail_breakdown_last_dict = breakdown
        self._silence_bail_breakdown_last_ts = now
        return breakdown

    def _query_recent_threshold_unparsable_tickers(self, limit: int = 4):
        """Return up to `limit` distinct ticker strings that fired
        `threshold_unparsable` rejections in the silence window, most
        recent first. Used to embed actual affected tickers in the
        THRESHOLD UNPARSABLE alert so the operator can paste-and-go
        with the curl probe without a separate DB query — round-3 C3:
        the May 4 incident was only diagnosed by ad-hoc curl, and a
        bare `<ticker>` template recreated that friction.

        Throttled like the breakdown query. Returns empty list on
        failure (caller renders gracefully). The query is non-indexed
        (LIKE on PK + filters), but only runs in the THRESHOLD branch
        of the alert path (not on BAIL FLOOD), so it does not add
        per-tick load during WS-cache-drift incidents.
        """
        now = time.time()
        last = getattr(
            self,
            "_silence_threshold_tickers_last_ts",
            0.0)
        cached = getattr(
            self,
            "_silence_threshold_tickers_last_list",
            [])
        if now - last < self._BAIL_QUERY_THROTTLE_SECONDS:
            return cached
        cutoff_dt = (datetime.datetime.now(timezone.utc)
                     - datetime.timedelta(
                         seconds=self._SILENCE_AGE_THRESHOLD_SECONDS))
        cutoff_iso = (
            cutoff_dt.isoformat(timespec="microseconds")
            .replace("+00:00", "Z"))
        # Round-5 C1: filter from `_THRESHOLD_SHAPE_BAIL_REASONS`
        # rather than the literal `'threshold_unparsable'`. If a future
        # maintainer adds a 2nd member to the bucket (e.g.,
        # `tradeable_false_15m`), the bucket-derived header label and
        # n_thr count both surface it — but the SQL filter would have
        # silently kept showing tickers from the original reason only,
        # masking a fraction of the real affected tickers. Now SQL
        # parallels the breakdown query's `IN ({placeholders})` shape.
        thr_reasons = tuple(sorted(self._THRESHOLD_SHAPE_BAIL_REASONS))
        thr_placeholders = ",".join("?" * len(thr_reasons))
        try:
            rows = self._state.conn.execute(
                "SELECT ticker, MAX(rejection_time) AS most_recent "
                "FROM rejected_opportunities "
                "WHERE ticker LIKE 'KX%15M%' "
                f"  AND rejection_reason IN ({thr_placeholders}) "
                "  AND rejection_time >= ? "
                "GROUP BY ticker "
                "ORDER BY most_recent DESC "
                "LIMIT ?",
                (*thr_reasons, cutoff_iso, limit),
            ).fetchall()
        except Exception:
            # Round-4 C1: failure path now warn-logs once (rate-limited
            # via own flag). The earlier rationale ("breakdown query's
            # warning covers it") was wrong: this query has a different
            # shape (GROUP BY + ORDER BY + LIMIT) and can fail
            # independently — e.g., a corrupted index on `ticker` or a
            # SQLite version regression on the GROUP+ORDER combination.
            # Without its own warn-flag, the operator gets a THRESHOLD
            # alert with empty `Affected tickers` and no journal
            # evidence of the underlying failure.
            if not getattr(
                    self,
                    "_silence_watchdog_warned_tickers",
                    False):
                logging.warning(
                    "silent_15m threshold-tickers query failed",
                    exc_info=True)
                self._silence_watchdog_warned_tickers = True
            # Preserve last-good list to avoid the same dual-alert
            # pathology fixed for the breakdown cache (round-3 C1/C5).
            if not hasattr(
                    self, "_silence_threshold_tickers_last_list"):
                self._silence_threshold_tickers_last_list = []
            self._silence_threshold_tickers_last_ts = now
            return self._silence_threshold_tickers_last_list
        # Reset warn-flag on success (round-4 C1 follow-up to round-3 C9).
        if getattr(
                self, "_silence_watchdog_warned_tickers", False):
            self._silence_watchdog_warned_tickers = False
        tickers = [row[0] for row in rows]
        self._silence_threshold_tickers_last_list = tickers
        self._silence_threshold_tickers_last_ts = now
        return tickers

    def _check_15m_silence_alert(self, active_windows: List[Dict]) -> None:
        """Alert via Telegram if no productive 15M evaluation has been
        produced in the last 10 minutes. Observation-only — doesn't
        touch trading state. Self-throttled (dedup_key) so it can fire
        every scan tick without spamming. See
        kb/failures/ws-15m-silence-2026-04-24.md and
        kb/failures/ws-cache-drift-silent-scan-2026-04-24.md.

        Scope: rows in `evaluated_opportunities` (any filter_stage)
        OR `rejected_opportunities` (any reason EXCEPT
        `_BAIL_REJECTION_REASONS`), filtered by ticker LIKE 'KX%15M%'.
        Healthy rejections (low_probability_15m, edge_too_low,
        tradeable_false, price_out_of_range_early, etc.) count as
        "scan alive". Bail reasons (no_orderbook, no_best_ask,
        threshold_unparsable) do NOT — they are emitted in the exact
        silent-bail paths whose recurrence this watchdog is the
        last line of defense for.

        Known gap (NOT addressed here): a calibration-engine collapse
        that returns cal_prob≈0 for every market would cause
        low_probability_15m rejections to fire for every ticker, and
        this watchdog would stay silent. That failure mode requires a
        separate model-output sanity check — out of scope for a
        liveness watchdog.

        Startup false-positive guard: the "last eval" timestamp persists
        across bot restarts, so right after restart it will look ancient.
        We do NOT fire unless THIS bot process has been running long
        enough (SILENCE_ALERT_MIN_UPTIME_SECONDS = 900 = 15 min) that it
        could plausibly have produced an eval. Otherwise a restart during
        a quiet window would spam the Telegram with a stale-looking age.

        Kalshi catalog-gap guard: Kalshi's /events?status=open returns
        only the currently-trading 15M window per asset, and there is
        often a 10–30 min gap between when one window closes and the next
        becomes "open". `discover_active_windows()` correctly drops the
        expired window (seconds_to_close < 0), leaving the scanner with
        zero 15M windows. This is upstream sparseness, not a bot fault.
        We log it at INFO level (KALSHI_15M_CATALOG_GAP) but don't fire
        the loud Telegram alert. Apr 24 2026: 11 such gaps in 24h, all
        false positives. (kb/failures/kalshi-15m-catalog-gap-2026-04-24.md)
        """
        if not hasattr(self, "_silence_alert_process_start_ts"):
            self._silence_alert_process_start_ts = time.time()
        uptime = time.time() - self._silence_alert_process_start_ts
        if uptime < self._SILENCE_ALERT_MIN_UPTIME_SECONDS:
            return
        n_15m_windows = sum(
            1 for w in (active_windows or [])
            if w.get("product_type") == "15m"
        )
        ws_connected = (
            self._kalshi_feed.is_connected
            if self._kalshi_feed else False)

        # Step 1: primary "scan alive" check. Tuple (ok, ts).
        primary_ok, last_ts_str = self._query_last_15m_alive_ts()
        if not primary_ok:
            # Query failed; warning logged once. Bail this tick.
            return

        # Step 2: compute primary staleness. Single-expression form
        # eliminates the multi-branch hazard (R7 [A1] crashed on
        # unparseable ts because age_sec/last_ts could be undefined
        # when reaching the alert message). Now: parse failure is
        # treated equivalently to None — last_ts stays None,
        # age_sec stays None, both truth-tested explicitly downstream.
        last_ts = None
        age_sec = None
        if last_ts_str is not None:
            try:
                last_ts = datetime.datetime.fromisoformat(
                    last_ts_str.replace("Z", "+00:00"))
                age_sec = (datetime.datetime.now(timezone.utc)
                           - last_ts).total_seconds()
            except (ValueError, AttributeError):
                last_ts = None
                age_sec = None
        is_primary_stale = (
            age_sec is None
            or age_sec >= self._SILENCE_AGE_THRESHOLD_SECONDS)

        if not is_primary_stale:
            # Healthy 15M activity within threshold — silent.
            return

        # Primary is stale or absent. Decide: bail signal or generic
        # silence?
        bail_count = self._query_recent_bail_count()

        if n_15m_windows == 0:
            # Catalog gap — log INFO, no Telegram. Note the bail rows
            # (if any) are stale leftovers from before the gap, not
            # caused by the gap itself; the gap merely masks them
            # diagnostically. R6 [A5] log message clarification.
            ts_repr = (last_ts_str
                       if last_ts_str is not None else "<none>")
            logging.info(
                "KALSHI_15M_CATALOG_GAP: 0 active 15M windows from "
                "Kalshi (upstream catalog gap, not bot fault). "
                "last=%s, recent_bail_rows=%d",
                ts_repr, bail_count)
            return

        if bail_count >= self._BAIL_MIN_ROWS_WHEN_STALE:
            # Bail signal alongside primary staleness — preferred
            # diagnostic. Single transient blips that happen to
            # coincide with a quiet-market staleness boundary stay
            # under threshold and fall through to generic SILENT
            # (correct: not a cache-drift signature). The 04-24
            # WS-cache-drift shape produces hundreds of rows, far
            # above threshold; the dedup-bounded threshold_unparsable
            # case produces ≤4 rows, also above threshold of 3.
            #
            # May 4 2026: alert text was hardcoded to "WS-cache-drift
            # recurrence" but live incident was Kalshi-side TBD strikes
            # (threshold_unparsable only, zero WS rows). Operator was
            # nearly sent to wrong KB doc + would have done a useless
            # restart. Routing now branches on dominant bail-reason
            # shape via `_query_recent_bail_breakdown`. See
            # kb/failures/threshold-tbd-stuck-may04.md.
            #
            # Adversarial review summary (rounds 2-7, see inline
            # comments below + per-method docstrings for per-fix
            # rationale, plus tests/test_15m_silence_alert.py
            # ::TestBailFloodMessageDifferentiation):
            # - R2: single source of truth — breakdown drives routing
            #   AND display; "(breakdown unavailable)" annotation
            #   when query empty; alphabetical breakdown sort.
            # - R3: ratio loosened 4→3 (`_THRESHOLD_SHAPE_DOMINANCE_RATIO`)
            #   to 75% so 3-ticker incident + 1 stray WS blip routes
            #   correctly; affected-tickers embed in THRESHOLD message;
            #   bucket-derived header label; last-good cache preserved
            #   on transient breakdown failure.
            # - R4: warn-once flag for breakdown query failure (mirror
            #   count query); empty-affected probe falls back to a
            #   next-step DB query (no bare `<ticker>` placeholder);
            #   partition assertion moved from class-body to test-only
            #   to avoid systemd backoff on developer mistake.
            # - R5: in-bot tickers SQL filter parameter-bound from
            #   `_THRESHOLD_SHAPE_BAIL_REASONS` via `IN (?,?,...)`;
            #   warn-once flag for tickers query failure.
            # - R6: operator-facing fallback SQL also bucket-derived
            #   via `IN ('a','b',...)`.
            # - R7: operator-facing window cutoff derived from
            #   `_SILENCE_AGE_THRESHOLD_SECONDS` (no `-10 minutes`
            #   literal drift).
            breakdown = self._query_recent_bail_breakdown()
            if breakdown:
                n_thr = sum(breakdown.get(r, 0)
                            for r in self._THRESHOLD_SHAPE_BAIL_REASONS)
                n_ws = sum(breakdown.get(r, 0)
                           for r in self._WS_SHAPE_BAIL_REASONS)
                display_total = n_thr + n_ws
                breakdown_str = self._format_bail_breakdown(breakdown)
                # Ratio-based dominance: threshold count >=
                # `_THRESHOLD_SHAPE_DOMINANCE_RATIO` × WS count AND at
                # least the bail threshold. Constant currently 3 (≥75%
                # threshold); see its definition for rationale and
                # boundary worked examples (round-3 C4 loosened from
                # 4 to 3 to fix asymmetric routing at small n).
                # Boundary pinned by TestBailFloodMessageDifferentiation.
                is_threshold_dominant = (
                    n_thr >= self._BAIL_MIN_ROWS_WHEN_STALE
                    and n_thr >= (
                        self._THRESHOLD_SHAPE_DOMINANCE_RATIO * n_ws))
            else:
                # Breakdown query failed or returned empty. Cannot
                # route by shape — default to BAIL FLOOD with explicit
                # annotation so operator can see the gap rather than
                # be misled by zero-everywhere. Gate already admitted
                # us via cached count, which we surface as display
                # total even though it may be from an older throttle
                # window than the (failed) breakdown query.
                n_thr = 0
                n_ws = 0
                display_total = bail_count
                breakdown_str = "(breakdown unavailable)"
                is_threshold_dominant = False

            if is_threshold_dominant:
                # Round-3 C3: embed actual affected tickers (most
                # recent up to 4) so the operator can paste-and-go
                # with the curl probe without a separate DB query.
                # Round-4 C2+C7: when affected is empty (tickers
                # query failed or cache stale-empty), DO NOT emit
                # the bare `<ticker>` placeholder URL — that
                # recreates exactly the friction the embed was
                # meant to remove. Replace the Probe: line with a
                # next-step DB query so the operator has actionable
                # guidance regardless.
                affected = self._query_recent_threshold_unparsable_tickers(
                    limit=4)
                logging.error(
                    "SILENT_15M_THRESHOLD_UNPARSABLE: primary stale + "
                    "%d threshold rows (ws=%d) in last %d min; "
                    "uptime=%.1fmin (%s); affected=%s",
                    n_thr, n_ws,
                    self._SILENCE_AGE_THRESHOLD_SECONDS // 60,
                    uptime / 60, breakdown_str,
                    (", ".join(affected) if affected
                     else "<empty>"))
                # Header label is derived from the bucket so a future
                # add to `_THRESHOLD_SHAPE_BAIL_REASONS` is reflected
                # without a parallel literal edit (round-3 C2).
                # Round-8 C1: each reason wrapped in backticks so
                # word-internal underscores cannot be misinterpreted
                # as italic markers by Telegram's legacy Markdown
                # parser (would fail HTTP 400, alert never delivered).
                threshold_label = ", ".join(
                    f"`{r}`"
                    for r in sorted(
                        self._THRESHOLD_SHAPE_BAIL_REASONS))
                # Build the affected-tickers + probe sections
                # conditionally on whether tickers are populated.
                if affected:
                    affected_line = (
                        f"Affected tickers: {', '.join(affected)}\n")
                    # Round-8 C1: wrap `floor_strike` field name in
                    # backticks so its word-internal underscore is
                    # neutralized for Markdown parsing. Tickers
                    # themselves are hyphen-only so don't need wrapping.
                    probe_line = (
                        f"Probe: curl https://api.elections.kalshi.com/"
                        f"trade-api/v2/markets/{affected[0]}\n"
                        f"  → if `floor_strike=null` + sub=\"TBD\": "
                        f"wait, Kalshi will populate\n"
                        f"  → if `floor_strike` populated but parser "
                        f"fails: code fix required\n")
                else:
                    # Round-6 C2: operator-facing fallback SQL must
                    # also derive its `IN (...)` clause from the
                    # bucket. Earlier draft hardcoded
                    # `rejection_reason='threshold_unparsable'`,
                    # which would silently mask half the affected
                    # tickers if `_THRESHOLD_SHAPE_BAIL_REASONS`
                    # gained a 2nd member — exactly the drift round-5
                    # C1 fixed in the bot's own SQL.
                    #
                    # Round-7 C1: window cutoff also derives from
                    # `_SILENCE_AGE_THRESHOLD_SECONDS` rather than a
                    # literal `'-10 minutes'`. Same drift class —
                    # if the constant is tuned, the operator's
                    # copy-paste SQL would otherwise reference a
                    # different window than the bot, producing
                    # tickers from a different incident.
                    #
                    # Round-7 C2 (degenerate-case note): if the bucket
                    # is empty, `operator_thr_in` is "" and the
                    # rendered SQL becomes `IN ()` (invalid). This is
                    # unreachable in practice because `n_thr` would be
                    # 0 → `is_threshold_dominant=False` → routes to
                    # BAIL FLOOD, never entering this branch. Bucket
                    # members are also Python module-level constants,
                    # so they cannot contain SQL-special characters
                    # (apostrophe, comma) that would corrupt the
                    # interpolated literal.
                    operator_thr_in = ", ".join(
                        f"'{r}'"
                        for r in sorted(
                            self._THRESHOLD_SHAPE_BAIL_REASONS))
                    # Round-8 C2: render the SQL window in seconds
                    # (full precision) rather than `// 60` minutes
                    # which was lossy for non-multiple-of-60 values
                    # of `_SILENCE_AGE_THRESHOLD_SECONDS`. SQLite
                    # supports the `seconds` modifier; using it
                    # eliminates the bot-vs-operator window drift
                    # that integer-floor minutes introduced.
                    window_seconds = (
                        self._SILENCE_AGE_THRESHOLD_SECONDS)
                    affected_line = (
                        "Affected tickers: (cache empty — query "
                        "`rejected_opportunities` for live list)\n")
                    # Round-8 C1: wrap the SQL in a backtick code span
                    # so identifiers like `rejection_reason` and
                    # `rejected_opportunities` (containing word-internal
                    # underscores) cannot trigger Markdown parser quirks.
                    probe_line = (
                        f"Probe: `SELECT ticker FROM "
                        f"rejected_opportunities WHERE "
                        f"rejection_reason IN ({operator_thr_in}) "
                        f"AND rejection_time >= datetime('now',"
                        f"'-{window_seconds} seconds')` — then curl "
                        f"Kalshi REST for that ticker.\n")
                msg = (
                    f"\U0001f6a8 *15M SCAN SILENT (THRESHOLD "
                    f"UNPARSABLE)*\n"
                    f"Primary stale + {n_thr} {threshold_label} "
                    f"rows in last "
                    f"{self._SILENCE_AGE_THRESHOLD_SECONDS // 60} "
                    f"min.\n"
                    f"Breakdown: {breakdown_str}\n"
                    f"{affected_line}"
                    f"Bot uptime: {uptime/60:.1f} min\n"
                    f"WS connected: {ws_connected}\n"
                    f"Likely: Kalshi delayed publishing strike "
                    f"(\"Target price: TBD\") OR renamed strike "
                    f"fields (parser regression).\n"
                    f"{probe_line}"
                    f"Restart will NOT help.")
                dedup_key = "silent_15m_threshold_unparsable_alert"
            else:
                logging.error(
                    "SILENT_15M_BAIL_FLOOD: primary stale + %d "
                    "silent-bail rejection rows in last %d min; "
                    "uptime=%.1fmin (%s)",
                    display_total,
                    self._SILENCE_AGE_THRESHOLD_SECONDS // 60,
                    uptime / 60, breakdown_str)
                msg = (
                    f"\U0001f6a8 *15M SCAN SILENT (BAIL FLOOD)*\n"
                    f"Primary stale + {display_total} silent-bail "
                    f"rejection rows in last "
                    f"{self._SILENCE_AGE_THRESHOLD_SECONDS // 60} "
                    f"min.\n"
                    f"Breakdown: {breakdown_str}\n"
                    f"Bot uptime: {uptime/60:.1f} min\n"
                    f"WS connected: {ws_connected}\n"
                    f"Likely: WS-cache-drift recurrence — see "
                    f"kb/failures/ws-cache-drift-silent-scan-"
                    f"2026-04-24.md")
                dedup_key = "silent_15m_bail_flood_alert"

            if _TELEGRAM:
                try:
                    _TELEGRAM.send(msg, dedup_key=dedup_key)
                except Exception:
                    logging.debug(
                        "silent_15m bail-flood telegram send failed "
                        "(dedup_key=%s)", dedup_key, exc_info=True)
            return

        # Apr 26 incident #2: heartbeat-based aliveness check. The
        # primary query is DB-row-based, but the `_eval_opp_seen`
        # dedup at insert sites (e.g., per-(ticker, filter_stage)
        # for `low_probability_15m`) suppresses subsequent writes
        # once a tuple has been seen. After 10+ min of unchanged
        # scan outcomes (e.g., dedup-quiet market post-window-
        # rotation), the DB shows stale primary timestamps while
        # scan body is still iterating windows on every tick.
        #
        # Wall-clock dependency: heartbeat is set via `time.time()`
        # at the per-window iteration site. NTP step corrections
        # (Apr 26 incident logged 13.8s drift) shift heartbeat_age
        # by the same magnitude — small relative to the 600s
        # threshold but worth knowing when debugging.
        #
        # `_scan_15m_iter_heartbeat_ts` (set at bot/_impl.py:9909 every
        # 15M window iteration; init=0.0 at bot/_impl.py:9087) decouples
        # "scan is alive" from "DB rows are appearing" — same fix
        # `c1c2096` applied to the productive (2.5-min) watchdog
        # per kb/failures/scan-tick-stall-cluster-2026-04-25.md.
        #
        # Bail-flood detection runs BEFORE this gate, so a real
        # silent-bail recurrence (which writes bail-rejection rows
        # bypassing the healthy-rejection dedup) still fires its
        # diagnostic alert regardless of heartbeat freshness.
        heartbeat_ts = getattr(self, "_scan_15m_iter_heartbeat_ts", 0.0)
        if heartbeat_ts > 0.0:
            heartbeat_age = time.time() - heartbeat_ts
            if heartbeat_age < self._SILENCE_AGE_THRESHOLD_SECONDS:
                # Scan body iterated a 15M window within the
                # staleness window — alive. Dedup may be hiding
                # repetitive outcomes, but that's exactly what dedup
                # is for. Silent-skip the SILENT alert.
                return
        # Generic silence path: primary stale, bail count below
        # threshold, AND heartbeat stale (or never set). Guard
        # against `last_ts is None` (no data) AND against
        # `last_ts_str is not None but unparseable` (data quality
        # blip) — in either case we lack the timestamp/age to render
        # the diagnostic message, so silently bail. (Fresh bot /
        # unparseable ts shouldn't fire a SILENT alert with bogus
        # content.)
        if last_ts is None or age_sec is None:
            return
        msg = (
            f"\U0001f6a8 *15M SCAN SILENT*\n"
            f"No 15M evaluation in {age_sec/60:.1f} min.\n"
            f"Last eval: {last_ts.isoformat(timespec='seconds')}Z\n"
            f"Bot uptime: {uptime/60:.1f} min\n"
            f"WS connected: {ws_connected}\n"
            f"Check logs for WS_SILENCE_WATCHDOG or check Kalshi status."
        )
        logging.error(
            "SILENT_15M: %.1f min since last 15M eval "
            "(last=%s uptime=%.1fmin)",
            age_sec / 60, last_ts_str, uptime / 60)
        if _TELEGRAM:
            try:
                _TELEGRAM.send(msg, dedup_key="silent_15m_alert")
            except Exception:
                logging.debug(
                    "silent_15m telegram send failed", exc_info=True)

    def _check_scan_productive_15m(
        self, active_windows: List[Dict], tick_start_ts: str) -> None:
        """Fire a Telegram alert when 15M scan runs but produces zero DB
        rows for N consecutive ticks. Complementary to
        `_check_15m_silence_alert` (which catches >10-min silences after
        the fact). This one detects the 2026-04-24 22:12 UTC failure
        shape in ~2.5 min instead of 10.

        Logic:
        - If no `product_type='15m'` in active_windows: reset counter and
          skip. Catalog gaps (upstream Kalshi sparseness) aren't a
          productivity issue.
        - If bot uptime < SCAN_UNPRODUCTIVE_MIN_UPTIME_SECONDS: skip
          entirely (and don't increment). RK warmup can legitimately
          produce nothing for ~5 min post-restart.
        - Query eval + rejected tables for 15m rows written
          since `tick_start_ts`. If any: reset counter. If zero:
          increment and alert when >= SCAN_UNPRODUCTIVE_THRESHOLD.

        See kb/failures/ws-cache-drift-silent-scan-2026-04-24.md fix #3.
        """
        SCAN_UNPRODUCTIVE_THRESHOLD = 5         # consecutive ticks
        SCAN_UNPRODUCTIVE_MIN_UPTIME_SECONDS = 420  # 7 min — RK warmup + buffer
        # Was 300 (5 min); 5 min boundary fired false positives at uptime
        # 5.1 min on slow restarts where RK warmup ran 3m 28s+ and the
        # first productive tick landed seconds after grace expired.
        # 7 min gives ~3.5 min buffer over observed warmup ceiling.

        # Snapshot the 15M subset once — `active_windows` may be
        # ref-swapped by the refresh worker mid-call, and the two
        # downstream counts must be consistent (R-review [A3]).
        _15m_windows = [
            w for w in active_windows
            if w.get("product_type") == "15m"
        ]
        n_15m = len(_15m_windows)
        if n_15m == 0:
            # No 15M windows available — reset counter so we don't carry
            # stale state into the next live window. Also clear alert
            # state so a renewed stuck-period after the gap re-fires
            # entry/reconnect; do NOT fire a recovery telegram (the
            # underlying bug is masked by the gap, not actually
            # resolved). Adversarial review [A1].
            self._scan_15m_unproductive_count = 0
            self._scan_15m_unproductive_entry_alerted = False
            self._scan_15m_unproductive_max_count = 0
            return

        # F/U 6 (Apr 26): rotation-boundary false-positive guard. At
        # rotation moments (every :00/:15/:30/:45), cached active_windows
        # briefly holds settled 15M windows with STC<0 between the
        # rotation and the next 30s `_refresh_active_windows()` call.
        # scan()'s time-range filter (line 9863-9866) `min_seconds_before_close
        # <= stc <= max_seconds_before_close` drops them all → for-loop
        # iterates non-15M only → 15M heartbeat at line 9921 (gated to
        # `_pt in (None, '15m')`) never fires → 5 silent ticks → false alert.
        # Apr 26 14:30:00 UTC log evidence (commit 159b411 instrumentation):
        #   F_U6_15M_TIME_FILTER_DROPPED_ALL: 4 15M windows ALL filtered
        #   by time range — details=[BTC=-0.0s, ETH=-0.0s, SOL=-0.0s,
        #   XRP=-0.0s]
        # Fix: extend the catalog-gap branch to also short-circuit when
        # 15M is in active_windows but ALL are time-INELIGIBLE. The
        # F_U6_15M_TIME_FILTER_DROPPED_ALL diagnostic at scan() (commit
        # 159b411) preserves observability for any non-rotation case.
        # Note: range bound MAX_SECONDS_BEFORE_CLOSE must mirror the
        # scan() time filter for 15M product. If a future per-product
        # split changes scan()'s 15M max, update here too.
        # See kb/failures/15m-scan-unproductive-rotation-2026-04-26.md.
        def _stc_in_15m_range(w):
            stc = w.get("seconds_to_close")
            if stc is None:
                # Missing STC → don't suppress the alert (R-review [A2]:
                # alert-bias is safer than silence-bias when data is
                # incomplete).
                return True
            try:
                stc_f = float(stc)
            except (TypeError, ValueError):
                # Non-numeric (R-review [A7] defensiveness) — same as None.
                return True
            return 0 <= stc_f <= MAX_SECONDS_BEFORE_CLOSE
        n_15m_time_eligible = sum(1 for w in _15m_windows if _stc_in_15m_range(w))
        if n_15m_time_eligible == 0:
            # All 15M markets currently outside the trading window —
            # benign rotation transition or catalog edge. Same code
            # path as the n_15m == 0 branch above. Adversarial
            # review [A1]: clear alert state to prevent stranding
            # entry-alerted across the gap; don't fire recovery
            # (benign mask, not real recovery).
            self._scan_15m_unproductive_count = 0
            self._scan_15m_unproductive_entry_alerted = False
            self._scan_15m_unproductive_max_count = 0
            return

        if not hasattr(self, "_scan_15m_process_start_ts"):
            self._scan_15m_process_start_ts = time.time()
        uptime = time.time() - self._scan_15m_process_start_ts
        if uptime < SCAN_UNPRODUCTIVE_MIN_UPTIME_SECONDS:
            return

        # Heartbeat-based productivity check — true when scan() actually
        # iterated a 15M window body since `tick_start_ts`. Decoupled from
        # DB row counts because the dedup at insert sites can suppress
        # writes for a window's entire 15-min lifetime once each
        # (ticker, stage) is seen, producing watchdog false positives
        # even when scan is healthy. (Apr 24 23:53 UTC false positive.)
        #
        # Phase 3 R-review A2 caveat: this OR-logic depends on Phase 1
        # (commit 27196b4 + AST audit task #46) ensuring every
        # silent-bail scan path writes a rejection row. If a future code
        # change introduces a NEW silent-continue without a rejection
        # write, heartbeat-recent could fire while rows_written=0 — the
        # exact pathology Phase 3 targets, but the productivity check
        # would falsely reset the counter. The AST audit test_scan_no_silent_continue.py
        # is the regression guard against that gap reappearing.
        try:
            tick_start_dt = datetime.datetime.strptime(
                tick_start_ts.replace("Z", "+00:00"),
                "%Y-%m-%dT%H:%M:%S.%f%z")
            tick_start_epoch = tick_start_dt.timestamp()
        except Exception:
            tick_start_epoch = 0.0
        heartbeat_recent = (
            self._scan_15m_iter_heartbeat_ts > tick_start_epoch)
        # Fallback: also check DB rows for backward-compat with the
        # original intent. Either signal indicates productive scan.
        try:
            row = self._state.conn.execute(
                "SELECT "
                "(SELECT COUNT(*) FROM evaluated_opportunities "
                " WHERE product_type='15m' AND evaluation_time > ?) + "
                "(SELECT COUNT(*) FROM rejected_opportunities "
                " WHERE product_type='15m' AND rejection_time > ?)",
                (tick_start_ts, tick_start_ts)
            ).fetchone()
        except Exception:
            return
        # Phase 3 R-review A1: detect WS disconnect→reconnect
        # transition. If WS just came back from a disconnected
        # state, the counter accumulated during the dead window
        # and would immediately trip R2 (reconnect-bomb). Reset
        # counter on transition; counter + alerts continue
        # accumulating during a sustained disconnect (operator
        # still wants to know via Telegram) but R1/R2 recovery
        # actions are gated below on WS being live.
        kf_check = getattr(self, "_kalshi_feed", None) or getattr(
            self, "kalshi_feed", None)
        ws_connected = (
            kf_check is not None
            and getattr(kf_check, "is_connected", False))
        prev_ws_connected = getattr(
            self, "_scan_15m_prev_ws_connected", True)
        self._scan_15m_prev_ws_connected = ws_connected
        if not prev_ws_connected and ws_connected:
            # Just reconnected. If a stuck-period had emitted an entry
            # alert, fire recovery NOW before clearing state so the
            # operator sees closure (and the peak count, which would
            # otherwise be clobbered by the reset below). Adversarial
            # review [A3][A5].
            if getattr(
                    self, "_scan_15m_unproductive_entry_alerted", False):
                peak = getattr(
                    self, "_scan_15m_unproductive_max_count", 0)
                logging.warning(
                    "SCAN_UNPRODUCTIVE_15M_RECOVERED (ws_reconnect): "
                    "peak=%d", peak)
                if _TELEGRAM:
                    try:
                        _TELEGRAM.send(
                            f"✅ *15M SCAN RECOVERED*\n"
                            f"Stuck period ended (WS reconnect) after "
                            f"peak {peak} consecutive unproductive ticks.")
                    except Exception:
                        logging.debug(
                            "scan_unproductive_15m recovery telegram "
                            "(ws) failed", exc_info=True)
            # Start fresh. Reset alert state too so a renewed burn
            # after reconnect re-fires entry/reconnect rather than
            # being silently absorbed by stale flags.
            self._scan_15m_unproductive_count = 0
            self._scan_15m_last_recovery_ts = 0.0
            self._scan_15m_reconnect_triggered = False
            self._scan_15m_unproductive_entry_alerted = False
            self._scan_15m_unproductive_max_count = 0

        rows_written = row[0] if row else 0
        if heartbeat_recent or rows_written > 0:
            # Productive tick — reset detection counter AND Phase 3
            # auto-recovery state (throttle + one-shot reconnect flag)
            # so the next stuck period gets fresh recovery cadence.
            #
            # If we previously fired an entry alert, send a recovery
            # telegram naming the peak count so the operator can size
            # the event without grepping journal. (Apr 27 2026
            # incident: 4 escalating telegrams over 3 min were noise;
            # entry + recovery is the right pair.)
            if getattr(
                    self, "_scan_15m_unproductive_entry_alerted", False):
                peak = getattr(
                    self, "_scan_15m_unproductive_max_count",
                    self._scan_15m_unproductive_count)
                logging.warning(
                    "SCAN_UNPRODUCTIVE_15M_RECOVERED: peak=%d", peak)
                if _TELEGRAM:
                    # No dedup_key: state-based flags already prevent
                    # duplicates; the TelegramNotifier 60s TTL would
                    # silently drop a back-to-back recovery within the
                    # same minute. Adversarial review [A4].
                    try:
                        _TELEGRAM.send(
                            f"✅ *15M SCAN RECOVERED*\n"
                            f"Stuck period ended after peak "
                            f"{peak} consecutive unproductive ticks.")
                    except Exception:
                        logging.debug(
                            "scan_unproductive_15m recovery telegram "
                            "failed", exc_info=True)
            self._scan_15m_unproductive_count = 0
            self._scan_15m_last_recovery_ts = 0.0
            self._scan_15m_reconnect_triggered = False
            self._scan_15m_unproductive_entry_alerted = False
            self._scan_15m_unproductive_max_count = 0
            return

        self._scan_15m_unproductive_count = getattr(
            self, "_scan_15m_unproductive_count", 0) + 1
        # Peak tracking so recovery telegram can size the burn.
        self._scan_15m_unproductive_max_count = max(
            getattr(self, "_scan_15m_unproductive_max_count", 0),
            self._scan_15m_unproductive_count)
        if self._scan_15m_unproductive_count < SCAN_UNPRODUCTIVE_THRESHOLD:
            return

        # Always log every above-threshold tick — journal is the
        # ground truth, even though the Telegram is state-deduped.
        logging.error(
            "SCAN_UNPRODUCTIVE_15M: %d consecutive ticks with %d active "
            "15M window(s) but zero DB rows written since %s",
            self._scan_15m_unproductive_count, n_15m, tick_start_ts)
        # State-based Telegram dedup: one entry alert per stuck-period.
        # Reconnect-threshold escalation alert fires later (in the R2
        # block below). Apr 27 2026 incident shipped 4 telegrams over
        # 3 min; this caps the entry path at 1.
        if _TELEGRAM and not getattr(
                self, "_scan_15m_unproductive_entry_alerted", False):
            self._scan_15m_unproductive_entry_alerted = True
            msg = (
                f"\U0001f6a8 *15M SCAN UNPRODUCTIVE*\n"
                f"{self._scan_15m_unproductive_count} consecutive ticks "
                f"with {n_15m} 15M window(s) produced zero DB rows.\n"
                f"Bot uptime: {uptime/60:.1f} min\n"
                f"Scan may be silent-bailing — see "
                f"ws-cache-drift-silent-scan-2026-04-24.md"
            )
            try:
                # No dedup_key: state flag is the dedup. TelegramNotifier
                # 60s TTL would defeat back-to-back stuck-periods.
                _TELEGRAM.send(msg)
            except Exception:
                logging.debug(
                    "scan_unproductive_15m entry telegram failed",
                    exc_info=True)

        # Phase 3 R1 — auto-recovery: force_resubscribe every active
        # 15M ticker. purge_cache=True is the real reset (drops
        # phantom WS state); track_recovery=True so B2 watchdog can
        # surface stuck tickers. Throttled to once per
        # SCAN_UNPRODUCTIVE_RECOVERY_THROTTLE_S (60s) so we don't
        # hammer the WS during a multi-tick burn.
        SCAN_UNPRODUCTIVE_RECOVERY_THROTTLE_S = 60.0
        SCAN_UNPRODUCTIVE_RECONNECT_THRESHOLD = 10  # ~5 min
        now = time.time()
        # Use kf_check (already resolved above for transition detection).
        kf = kf_check
        if not ws_connected:
            return  # no WS to recover; counter+alert already fired
        last_rec = getattr(self, "_scan_15m_last_recovery_ts", 0.0)
        if now - last_rec >= SCAN_UNPRODUCTIVE_RECOVERY_THROTTLE_S:
            self._scan_15m_last_recovery_ts = now
            _15m_tickers = []
            for w in active_windows:
                if w.get("product_type") != "15m":
                    continue
                for mkt in w.get("markets") or []:
                    t = mkt.get("ticker", "")
                    if t:
                        _15m_tickers.append(t)
            for t in _15m_tickers:
                try:
                    kf.force_resubscribe(
                        t, purge_cache=True, track_recovery=True)
                except Exception:
                    logging.debug(
                        "force_resubscribe in scan-recovery failed: %s",
                        t, exc_info=True)
            logging.warning(
                "SCAN_UNPRODUCTIVE_15M_RECOVERY_R1: force_resubscribed "
                "%d 15M tickers (purge=True, track=True) at %d "
                "consecutive unproductive ticks",
                len(_15m_tickers),
                self._scan_15m_unproductive_count)

        # Phase 3 R2 — escalation: if STILL unproductive at 10
        # consecutive ticks (~5 min), set _force_reconnect_requested
        # so silence watchdog forces a fresh WS session. One-shot
        # per stuck-period (cleared on next productive tick).
        if (self._scan_15m_unproductive_count
                >= SCAN_UNPRODUCTIVE_RECONNECT_THRESHOLD
                and not getattr(
                    self, "_scan_15m_reconnect_triggered", False)):
            self._scan_15m_reconnect_triggered = True
            try:
                kf._force_reconnect_requested = True
            except Exception:
                logging.warning(
                    "Failed to set _force_reconnect_requested",
                    exc_info=True)
            logging.error(
                "SCAN_UNPRODUCTIVE_15M_RECOVERY_R2: requesting WS "
                "reconnect at %d consecutive unproductive ticks "
                "(R1 force_resubscribe didn't recover)",
                self._scan_15m_unproductive_count)
            # Surface the escalation to the operator. One-shot per
            # stuck-period via the same flag that gates the action,
            # so the Telegram and the action stay in lockstep.
            if _TELEGRAM:
                try:
                    # No dedup_key: gated by `_reconnect_triggered`
                    # flag (one-shot per stuck-period).
                    _TELEGRAM.send(
                        f"\U0001f6a8 *15M SCAN STILL UNPRODUCTIVE*\n"
                        f"{self._scan_15m_unproductive_count} "
                        f"consecutive ticks — forcing WS reconnect.\n"
                        f"R1 force_resubscribe didn't recover.")
                except Exception:
                    logging.debug(
                        "scan_unproductive_15m reconnect telegram "
                        "failed", exc_info=True)

    def _drift_probe_tick(self) -> None:
        """Once per minute, diff REST orderbook vs WS cache for a random
        subscribed 15M ticker. Logs WS_DRIFT_PROBE summary per side.

        Purpose: empirically measure the cache-vs-truth gap that produces
        WS delta underflow warnings. Pre-existing hypothesis (H-NEW): WS
        snapshot at subscribe time is truncated, so our cache is missing
        deep/stale levels. REST with depth=100 returns the full book at
        request time (no truncation), so REST-WS diff quantifies the miss.

        Observation-only. Does NOT mutate WS cache state. Cadence: 60s.
        Remove after hypothesis confirmed/rejected.
        """
        now = time.time()
        if now - self._drift_probe_last_run < 60:
            return
        self._drift_probe_last_run = now

        if not (self._kalshi_feed and self._kalshi_feed.is_connected):
            return

        # Pick a random subscribed 15M ticker with a non-empty WS cache.
        try:
            all_obs = self._kalshi_feed.get_all_orderbooks()
        except Exception:
            return
        candidates = [
            t for t, ob in all_obs.items()
            if "15M" in t.upper()
            and (ob.get("yes") or ob.get("no"))  # skip empty books
        ]
        if not candidates:
            return

        ticker = random.choice(candidates)
        ws_ob = all_obs[ticker]

        try:
            rest_resp = self._client.get_orderbook(ticker, depth=100)
        except Exception as e:
            logging.warning("WS_DRIFT_PROBE %s fetch_failed: %s", ticker, e)
            return
        if not rest_resp or not isinstance(rest_resp, dict):
            return

        # Kalshi REST returns one of two shapes (same pattern as
        # _get_orderbook_cached at bot/_impl.py:13538-13546):
        #   - New FP format: {"orderbook_fp": {"yes_dollars": [[dollar_str,
        #     fp_qty_str], ...], "no_dollars": [...]}}
        #   - Legacy:        {"orderbook": {"yes": [[cents_int, qty_int],
        #     ...], "no": [...]}}
        rest_ob: Optional[Dict[str, List]] = None
        ob_fp = rest_resp.get("orderbook_fp")
        if ob_fp:
            rest_ob = OpportunityScanner._convert_orderbook_fp(ob_fp)
        else:
            legacy = rest_resp.get("orderbook")
            if isinstance(legacy, dict):
                rest_ob = {
                    "yes": list(legacy.get("yes") or []),
                    "no": list(legacy.get("no") or []),
                }
        if rest_ob is None:
            logging.warning(
                "WS_DRIFT_PROBE %s unknown_rest_shape: keys=%s",
                ticker, sorted(rest_resp.keys()))
            return

        # Fix #1b: if drift exceeds threshold on either side, auto-flag
        # the ticker for WS bypass. Only done once per probe call —
        # flag_ticker_drifted itself is idempotent via dict.pop.
        severe_drift_side: Optional[str] = None
        severe_ws_qty = 0
        severe_rest_qty = 0

        for side in ("yes", "no"):
            ws_levels = {int(lvl[0]): int(lvl[1])
                         for lvl in (ws_ob.get(side) or [])
                         if isinstance(lvl, (list, tuple)) and len(lvl) >= 2}
            rest_levels = {int(lvl[0]): int(lvl[1])
                           for lvl in (rest_ob.get(side) or [])
                           if isinstance(lvl, (list, tuple)) and len(lvl) >= 2}

            all_prices = set(ws_levels) | set(rest_levels)
            only_ws = sum(1 for p in all_prices
                          if p in ws_levels and p not in rest_levels)
            only_rest = sum(1 for p in all_prices
                            if p in rest_levels and p not in ws_levels)
            qty_mismatch = sum(1 for p in all_prices
                               if ws_levels.get(p, 0) != rest_levels.get(p, 0))
            total_ws = sum(ws_levels.values())
            total_rest = sum(rest_levels.values())
            max_missing_level = 0
            max_missing_qty = 0
            for p in all_prices:
                diff = rest_levels.get(p, 0) - ws_levels.get(p, 0)
                if diff > max_missing_qty:
                    max_missing_qty = diff
                    max_missing_level = p

            logging.warning(
                "WS_DRIFT_PROBE %s %s: ws_levels=%d rest_levels=%d "
                "only_ws=%d only_rest=%d qty_mismatch=%d "
                "ws_qty_total=%d rest_qty_total=%d missing_qty=%+d "
                "worst_level=%d¢ worst_missing=%d",
                ticker, side, len(ws_levels), len(rest_levels),
                only_ws, only_rest, qty_mismatch,
                total_ws, total_rest, total_rest - total_ws,
                max_missing_level, max_missing_qty)

            # Check severity — first severe side wins; second side still
            # logs its WS_DRIFT_PROBE but doesn't overwrite the trigger.
            if (severe_drift_side is None
                    and self._is_severe_drift(total_ws, total_rest)):
                severe_drift_side = side
                severe_ws_qty = total_ws
                severe_rest_qty = total_rest

        if severe_drift_side is not None:
            self.flag_ticker_drifted(ticker)
            logging.warning(
                "WS_DRIFT_AUTO_FLAG %s: %s side ws_qty=%d rest_qty=%d "
                "(|diff|=%d) — bypassing WS cache for 60s (fix #1b)",
                ticker, severe_drift_side, severe_ws_qty, severe_rest_qty,
                abs(severe_ws_qty - severe_rest_qty))

        # REST-vs-REST stability probe. Fetch REST again ~2s later and
        # compute delta against the REST we just used. Motivation:
        # WS_DRIFT_PROBE shows WS-vs-REST diverges, but that could mean
        # (a) WS drift, (b) REST drift/caching, or (c) timing race during
        # book churn. If REST_1 vs REST_2 shows big deltas, REST is not
        # stable ground truth and we can't trust it to overwrite WS.
        # See kb/failures/ws-cache-drift-investigation.md.
        #
        # The 2s wait + REST + comparison runs in a daemon thread so it
        # doesn't block the main scan() loop. Apr 25 00:21 incident:
        # synchronous time.sleep(2.0) here cascaded with other periodic
        # tasks into 6-10s main-thread stalls (SLOW_SCAN_TICK). Threaded
        # is safe — Kalshi client is thread-safe and this only logs.
        # See ws-cache-drift-silent-scan-2026-04-24 PM Fix 5.
        def _stability_reprobe_worker(_ticker, _rest_ob1, _client):
            try:
                time.sleep(2.0)
                rest_resp2 = _client.get_orderbook(_ticker, depth=100)
            except Exception as e:
                logging.debug(
                    "WS_DRIFT_PROBE %s rest2_fetch_failed: %s", _ticker, e)
                return
            if not rest_resp2 or not isinstance(rest_resp2, dict):
                return
            rest_ob2: Optional[Dict[str, List]] = None
            ob_fp2 = rest_resp2.get("orderbook_fp")
            if ob_fp2:
                rest_ob2 = OpportunityScanner._convert_orderbook_fp(ob_fp2)
            else:
                legacy2 = rest_resp2.get("orderbook")
                if isinstance(legacy2, dict):
                    rest_ob2 = {
                        "yes": list(legacy2.get("yes") or []),
                        "no": list(legacy2.get("no") or []),
                    }
            if rest_ob2 is None:
                return
            for side in ("yes", "no"):
                r1_levels = {int(lvl[0]): int(lvl[1])
                             for lvl in (_rest_ob1.get(side) or [])
                             if isinstance(lvl, (list, tuple)) and len(lvl) >= 2}
                r2_levels = {int(lvl[0]): int(lvl[1])
                             for lvl in (rest_ob2.get(side) or [])
                             if isinstance(lvl, (list, tuple)) and len(lvl) >= 2}
                all_prices = set(r1_levels) | set(r2_levels)
                only_r1 = sum(1 for p in all_prices
                              if p in r1_levels and p not in r2_levels)
                only_r2 = sum(1 for p in all_prices
                              if p in r2_levels and p not in r1_levels)
                qty_mismatch = sum(1 for p in all_prices
                                   if r1_levels.get(p, 0) != r2_levels.get(p, 0))
                total_r1 = sum(r1_levels.values())
                total_r2 = sum(r2_levels.values())
                _at_cap = max(len(r1_levels), len(r2_levels)) >= 100
                logging.warning(
                    "WS_DRIFT_PROBE_REST_STABILITY %s %s: "
                    "r1_levels=%d r2_levels=%d only_r1=%d only_r2=%d "
                    "qty_mismatch=%d r1_qty_total=%d r2_qty_total=%d "
                    "delta_qty=%+d at_depth_cap=%s",
                    _ticker, side, len(r1_levels), len(r2_levels),
                    only_r1, only_r2, qty_mismatch,
                    total_r1, total_r2, total_r2 - total_r1,
                    "yes" if _at_cap else "no")

        try:
            threading.Thread(
                target=_stability_reprobe_worker,
                args=(ticker, rest_ob, self._client),
                daemon=True,
                name=f"ws_drift_stability_{ticker[:20]}",
            ).start()
        except Exception:
            logging.debug(
                "WS_DRIFT_PROBE stability_thread_spawn_failed",
                exc_info=True)

    # ── Timeslot helpers ──────────────────────────────────────────────────

    @staticmethod
    def _window_timeslot(event_ticker: Optional[str]) -> str:
        """Extract timeslot from event ticker.

        'KXBTC15M-26FEB211545' -> '26FEB211545'
        (same across assets: KXETH15M-26FEB211545 also gives '26FEB211545')
        """
        if not event_ticker:
            # Transient race: position/order/window dict surfaced None event_ticker
            # (see kb/failures/transient-none-event-ticker-may08.md — same class
            # as the 2026-05-08 14:44 tick error at OrderExecutor's per-window
            # cap aggregator). Caller checks `if ts:` so empty string skips
            # this row safely.
            logging.warning("WINDOW_TIMESLOT_NULL: event_ticker is None/empty")
            return ""
        parts = event_ticker.split("-")
        if len(parts) >= 2:
            return parts[1]
        return event_ticker

    def _get_occupied_timeslots(self) -> Dict[str, set]:
        """Return {timeslot: set(assets)} for timeslots with open positions or resting orders."""
        occupied: Dict[str, set] = {}

        for pos in self._state.get_open_positions():
            et = pos.get("event_ticker", "")
            asset = pos.get("asset", "")
            ts = self._window_timeslot(et)
            if ts:
                occupied.setdefault(ts, set()).add(asset)

        for order in self._state.get_resting_orders():
            et = order.get("event_ticker", "")
            asset = order.get("asset", "")
            ts = self._window_timeslot(et)
            if ts:
                occupied.setdefault(ts, set()).add(asset)

        return occupied

    # ── Balance ───────────────────────────────────────────────────────────

    def _get_balance_cached(self) -> Optional[int]:
        """Get balance in cents, cached for BALANCE_CACHE_TTL seconds."""
        now = time.time()
        cached_balance, fetch_time = self._balance_cache
        if cached_balance is not None and now - fetch_time < BALANCE_CACHE_TTL:
            return cached_balance

        resp = self._client.get_balance()
        if resp is None:
            return cached_balance  # return stale if API fails
        balance = resp.get("balance") or 0
        # Absolute sanity cap — catches API glitches without blocking normal settlements
        _BALANCE_SANITY_CAP = int(os.getenv("BALANCE_SANITY_CAP_CENTS", "250000"))  # $2,500 default
        if balance > _BALANCE_SANITY_CAP:
            logging.warning("BALANCE_SANITY_CAP: api_balance=$%.2f capped=$%.2f",
                            balance / 100, _BALANCE_SANITY_CAP / 100)
            balance = _BALANCE_SANITY_CAP
        self._balance_cache = (balance, now)
        return balance


# ═════════════════════════════════════════════════════════════════════════════
#  OrderExecutor
# ═════════════════════════════════════════════════════════════════════════════

class OrderExecutor:
    """Maker-first executor with adaptive taker escalation.

    Always enters via a maker limit order (1-2¢ below fair value).
    tick() polls for fills and, if unfilled, escalates to a taker order
    after an urgency-based wait window:
      - 60-300s to close → wait 15s
      - 30-60s  to close → wait 10s
      - <30s    to close → wait 5s

    On escalation: cancel maker, re-fetch orderbook, validate price
    is in [MIN_ENTRY_PRICE, ESCALATION_MAX_ENTRY], and submit taker.

    UUID client_order_id, persist to SQLite before submission,
    log fills to trade_journal.jsonl, record position on fill.
    """

    def __init__(self, client: KalshiClient, state: StateManager,
                 logger: Logger, main_loop=None, kalshi_feed=None):
        self._client = client
        self._state = state
        self._logger = logger
        self._ml = main_loop
        self._kalshi_feed = kalshi_feed
        self._active_orders: Dict[str, Dict] = {}  # asset → order dict
        # Maker-tail tracking: order_id → record. Each record:
        #   {asset, ticker, strategy, count, price_cents,
        #    posted_monotonic, expires_monotonic}
        # Populated by _maybe_post_maker_tail, swept by
        # _sweep_maker_tails (called from tick()).
        self._maker_tails: Dict[str, Dict] = {}
        self._session_maker_tails_posted: int = 0
        self._session_maker_tails_skipped_cap: int = 0
        self._session_maker_tails_cancelled_ttl: int = 0
        # Ladder-escalation session counter. Mirrors maker-tail.
        # Increments on attempt (not on fill) — pair with success-rate
        # by comparing to settlement-level ladder fill counts.
        self._session_ladder_escalations: int = 0
        self._recent_taker_tickers: Dict[str, float] = {}  # ticker → timestamp (cooldown after IOC)
        # Session counters for execution engine stats
        self._session_amend_attempts: int = 0
        self._session_amend_successes: int = 0
        self._session_ioc_fills: int = 0
        self._session_ioc_unfilled: int = 0
        self._session_ws_fills: int = 0
        self._session_rest_fills: int = 0
        self._session_post_only_rejections: int = 0
        # Post-only rejection → taker escalation tracking
        self._post_only_rejections: Dict[str, Tuple[int, float]] = {}  # ticker → (count, first_rejection_ts)
        # Per-ticker API error cap: stop hammering after 3 consecutive api_errors
        self._ticker_api_errors: Dict[str, int] = {}  # ticker → consecutive error count
        self.TICKER_API_ERROR_CAP = 3
        # Rolling buffer of recent REST best-ask depth observations
        # per ticker, used to smooth the IOC drift-check clamp. Each
        # entry is (ts, depth); samples older than
        # IOC_DRIFT_CHECK_REST_WINDOW_S are pruned at observation time.
        # The clamp authority is `max(depths in window)` rather than
        # a single REST sample — see _rest_best_ask_depth_smoothed.
        self._rest_depth_observations: Dict[str, deque] = {}
        self._session_post_only_degraded_attempts: int = 0
        self._session_post_only_taker_escalations: int = 0
        self._session_post_only_taker_fills: int = 0
        # Direct taker counters (for <60s candidates)
        self._session_direct_taker_attempts: int = 0
        self._session_direct_taker_fills: int = 0
        self._session_direct_taker_unfilled: int = 0
        self._session_direct_taker_skipped: int = 0
        # Confirmation addon state
        self._addon_eligible: Dict[str, Dict] = {}   # ticker → metadata
        self._addon_completed: set = set()            # tickers already addon'd
        self._session_addon_attempts: int = 0
        self._session_addon_fills: int = 0
        self._session_addon_unfilled: int = 0
        self._session_addon_skipped: int = 0
        # Dip addon state
        self._dip_addon_completed: set = set()         # tickers already dip-addon'd
        self._session_dip_addon_attempts: int = 0
        self._session_dip_addon_fills: int = 0
        self._session_dip_addon_shadow: int = 0
        self._session_dip_addon_skipped: int = 0
        self._escalating_assets: set = set()  # Fix 5: guard against re-entry during escalation
        # Order suppression tracking — every gate logs when it blocks
        self._session_suppressed_asset_lock: int = 0
        self._session_suppressed_ticker_cooldown: int = 0
        self._session_suppressed_no_asks: int = 0
        self._session_nbbo_fallback_attempts: int = 0
        self._session_nbbo_fallback_blocked: int = 0
        self._session_suppressed_edge_recalc: int = 0
        self._session_suppressed_zero_size: int = 0
        # SOL empty-book maker fallback counters
        self._session_sol_empty_maker_attempt: int = 0
        self._session_sol_empty_maker_skip_price: int = 0
        self._session_sol_empty_maker_skip_stc: int = 0
        self._session_ioc_retries: int = 0
        self._session_ioc_retry_fills: int = 0
        self._kalshi_oft = None  # populated from scanner if available
        # SOL Path C shadow: pending observations {ticker → dict}
        self._sol_pathc_pending: Dict[str, Dict] = {}
        # DC IOC retry queue: non-blocking retries between scan cycles
        # Each entry: {candidate, original_count, total_filled, remaining, attempt, next_retry_ts, strategy}
        self._dc_retry_queue: List[Dict] = []
        self._session_dc_retries: int = 0
        self._session_dc_retry_fills: int = 0
        # Cancel-404 session counter. Explicit init removes the
        # attribute-missing race the prior `getattr(...)` lazy pattern
        # in `_handle_cancel_404` carried (`+= 1` is still non-atomic
        # under any future multi-thread refactor — explicit init
        # narrows the surface, doesn't make the counter thread-safe).
        # See kb/decisions/cancel-404-fix-v2-design-may04.md
        # "Counter initialization".
        self._cancel_404_count: int = 0

    @property
    def _active_order(self) -> Optional[Dict]:
        """Backwards compat for dashboard_snapshot.py."""
        if not self._active_orders:
            return None
        return next(iter(self._active_orders.values()))

    @property
    def has_active_order(self) -> bool:
        return len(self._active_orders) > 0

    # ── Post-only rejection tracking ────────────────────────────────────

    def _get_post_only_rejection_count(self, ticker: str) -> int:
        """Get active rejection count for ticker. Returns 0 if expired or missing."""
        entry = self._post_only_rejections.get(ticker)
        if entry is None:
            return 0
        count, first_ts = entry
        if time.time() - first_ts > POST_ONLY_REJECTION_EXPIRY:
            self._post_only_rejections.pop(ticker, None)
            return 0
        return count

    def _record_post_only_rejection(self, ticker: str):
        """Increment rejection count for ticker. Starts fresh if expired."""
        now = time.time()
        entry = self._post_only_rejections.get(ticker)
        if entry is None or (now - entry[1] > POST_ONLY_REJECTION_EXPIRY):
            self._post_only_rejections[ticker] = (1, now)
        else:
            self._post_only_rejections[ticker] = (entry[0] + 1, entry[1])

    # ── Pre-submit settlement-race gate ─────────────────────────────────

    def _should_skip_near_close(self, candidate: Dict) -> bool:
        """Return True when candidate STC is too close to settlement
        for a submission to land cleanly. None / non-numeric STC →
        return False (no info, allow submit — this path is shared with
        weather/sports where seconds_to_close may be unset)."""
        stc = candidate.get("seconds_to_close")
        try:
            stc_f = float(stc)
        except (TypeError, ValueError):
            return False
        return stc_f < MIN_ORDER_SUBMIT_STC_S

    def _abort_near_close(self, candidate: Dict, path: str) -> None:
        """Record the skip in evaluated_opportunities + log so the
        forensic trail makes the abort discoverable (a missing
        place_order would otherwise look like 'we never tried')."""
        ticker = candidate.get("ticker", "?")
        stc = candidate.get("seconds_to_close")
        logging.warning(
            "ORDER_ABORT_NEAR_CLOSE: %s path=%s stc=%s "
            "threshold=%.1fs (skip to avoid 409/404 race)",
            ticker, path, stc, MIN_ORDER_SUBMIT_STC_S)
        try:
            self._state.update_evaluated_opportunity_order(
                ticker, order_outcome="skipped_near_close")
        except Exception:
            logging.warning(
                "update_evaluated_opportunity_order(skipped_near_close) "
                "failed for %s", ticker, exc_info=True)

    # ── Hourly taker-only execution ─────────────────────────────────────

    def _execute_hourly_taker(self, candidate: Dict) -> Optional[Dict]:
        """Hourly-only IOC execution. No per-asset lock, no maker, no escalation.

        Completely isolated from 15M execution path:
        - Does NOT write to _active_orders (no maker resting)
        - Does NOT write to _escalating_assets (no escalation)
        - Calls _submit_taker() directly → IOC resolves in <1s
        """
        ticker = candidate["ticker"]
        asset = candidate["asset"]
        best_ask = candidate["best_yes_ask"]
        count = min(candidate["position_size"], HOURLY_FIXED_CONTRACTS)  # Hard cap

        # Ticker cooldown (shared with all products — IOC-specific, safe)
        cooldown_ts = self._recent_taker_tickers.get(ticker)
        if cooldown_ts is not None:
            _cd_remaining = IOC_TICKER_COOLDOWN - (time.time() - cooldown_ts)
            if _cd_remaining > 0:
                logging.info("HOURLY_TAKER: %s cooldown %.0fs remaining", ticker, _cd_remaining)
                return None

        candidate["entry_path"] = "hourly_taker"

        # Apply ask+1c offset for fill certainty (same pattern as SOL taker-first).
        # At sub-60c, 1c worse entry is trivial vs the 20c+ per-trade edge.
        # Verify edge is still positive after the offset before submitting.
        _h_mcfg = get_market_config("hourly")
        ioc_price = min(best_ask + IOC_RETRY_OFFSET, HOURLY_MAX_ENTRY_PRICE)
        if ioc_price != best_ask:
            cal_prob = candidate.get("calibrated_prob", 0)
            _offset_fee = calculate_fee(HOURLY_FIXED_CONTRACTS, ioc_price, is_taker=True,
                                        fee_mult_taker=_h_mcfg.fee_multiplier_taker,
                                        fee_mult_maker=_h_mcfg.fee_multiplier_maker)
            _offset_edge = cal_prob - (ioc_price / 100.0) - (_offset_fee / (HOURLY_FIXED_CONTRACTS * 100.0))
            if _offset_edge >= HOURLY_MIN_EDGE_PCT / 100.0:
                candidate["best_yes_ask"] = ioc_price
                best_ask = ioc_price
            else:
                logging.info("HOURLY_TAKER: %s offset %d→%dc kills edge (%.4f < %.4f), using ask",
                             ticker, best_ask, ioc_price, _offset_edge, HOURLY_MIN_EDGE_PCT / 100.0)

        logging.info("HOURLY_TAKER: %s %dx@%dc edge=%.2f%% prob=%.1f%% stc=%.0fs",
                     ticker, count, best_ask,
                     candidate.get("fee_adjusted_edge", 0) * 100,
                     candidate.get("calibrated_prob", 0) * 100,
                     candidate.get("seconds_to_close", 0))

        if _TELEGRAM:
            _TELEGRAM.send(
                f"HOURLY: {asset} {count}x@{best_ask}c "
                f"edge={candidate.get('fee_adjusted_edge', 0):.2%} "
                f"stc={candidate.get('seconds_to_close', 0):.0f}s")

        result = self._submit_taker(candidate)
        if result is None:
            self._recent_taker_tickers[ticker] = time.time()
        return result

    def _execute_weather_no_taker(self, candidate: Dict) -> Optional[Dict]:
        """Weather NO-side IOC execution. Direct taker, no maker, no escalation.

        Weather NO books are structurally empty — resting NO asks at 30-40c don't
        exist. Maker-first always cancels. Small fixed sizing (WEATHER_NO_CONTRACT_COUNT)
        at ~39-40c keeps taker fee negligible vs the 30%+ assumed-prob edge.
        """
        ticker = candidate["ticker"]
        asset = candidate["asset"]
        best_ask = candidate["best_yes_ask"]  # NO price for NO-side
        count = candidate["position_size"]     # WEATHER_NO_CONTRACT_COUNT (gated, ex-LAS)

        # Ticker cooldown (shared with all products)
        cooldown_ts = self._recent_taker_tickers.get(ticker)
        if cooldown_ts is not None:
            _cd_remaining = IOC_TICKER_COOLDOWN - (time.time() - cooldown_ts)
            if _cd_remaining > 0:
                logging.info("WEATHER_NO_TAKER: %s cooldown %.0fs remaining", ticker, _cd_remaining)
                return None

        candidate["entry_path"] = "weather_no_taker"

        logging.info(
            "WEATHER_NO_TAKER: %s %dx@%dc edge=%.2f%% prob=%.0f%% stc=%.0fs",
            ticker, count, best_ask,
            candidate.get("fee_adjusted_edge", 0) * 100,
            candidate.get("calibrated_prob", 0) * 100,
            candidate.get("seconds_to_close", 0))

        if _TELEGRAM:
            _TELEGRAM.send(
                f"\u2601\ufe0f WX NO: {asset} {count}x@{best_ask}c "
                f"edge={candidate.get('fee_adjusted_edge', 0):.2%} "
                f"stc={candidate.get('seconds_to_close', 0) / 3600:.0f}h")

        result = self._submit_taker(candidate)
        if result is None:
            self._recent_taker_tickers[ticker] = time.time()
        return result

    def _execute_hourly_no_taker(self, candidate: Dict) -> Optional[Dict]:
        """Hourly NO-side IOC execution. 1-contract verification mode.

        Mirrors weather NO taker — direct IOC, no maker, no escalation.
        Completely isolated from 15M and hourly YES execution paths.
        """
        ticker = candidate["ticker"]
        asset = candidate["asset"]
        best_ask = candidate["best_yes_ask"]  # NO price for NO-side
        count = min(candidate["position_size"], HOURLY_NO_FIXED_CONTRACTS)

        # Ticker cooldown
        cooldown_ts = self._recent_taker_tickers.get(ticker)
        if cooldown_ts is not None:
            _cd_remaining = IOC_TICKER_COOLDOWN - (time.time() - cooldown_ts)
            if _cd_remaining > 0:
                logging.info("HOURLY_NO_TAKER: %s cooldown %.0fs remaining", ticker, _cd_remaining)
                return None

        candidate["entry_path"] = "hourly_no_taker"

        logging.info(
            "HOURLY_NO_TAKER: %s %s %dx@%dc edge=%.2f%% no_prob=%.1f%% stc=%.0fs",
            ticker, asset, count, best_ask,
            candidate.get("fee_adjusted_edge", 0) * 100,
            candidate.get("calibrated_prob", 0) * 100,
            candidate.get("seconds_to_close", 0))

        if _TELEGRAM:
            _TELEGRAM.send(
                f"HOURLY NO: {asset} {count}x@{best_ask}c "
                f"edge={candidate.get('fee_adjusted_edge', 0):.2%} "
                f"stc={candidate.get('seconds_to_close', 0):.0f}s")

        result = self._submit_taker(candidate)
        if result is None:
            self._recent_taker_tickers[ticker] = time.time()
        return result

    # ── Public interface ──────────────────────────────────────────────────

    @staticmethod
    def _existing_window_cost_for_timeslot(positions: List[Dict],
                                           timeslot: str) -> int:
        """Sum total_cost_cents across positions whose event_ticker shares
        `timeslot`. Defends against a transiently-None event_ticker (the
        race documented at `_window_timeslot`'s `WINDOW_TIMESLOT_NULL`
        warning and in `kb/failures/transient-none-event-ticker-may08.md`).

        Tick error 2026-05-08 14:44:36 fired here when an inline genexpr
        chained `.split(...)` directly off `p.get("event_ticker", "")` —
        `dict.get` returns the value (None) when the key is present, so
        the default-empty-string never coerced None.

        total_cost_cents is also coerced defensively: schema is INTEGER
        NOT NULL, but the same race that surfaced None event_ticker can
        plausibly surface other transiently-None columns. Skip the row
        rather than TypeError on `total += None`.
        """
        total = 0
        for p in positions:
            et = p.get("event_ticker")
            if not et:
                logging.warning(
                    "WINDOW_CAP_NULL_EVENT_TICKER: ticker=%s asset=%s "
                    "side=%s status=%s cost=%s",
                    p.get("ticker"), p.get("asset"), p.get("side"),
                    p.get("status"), p.get("total_cost_cents"))
                continue
            if et.split("-", 1)[-1] == timeslot:
                cost = p.get("total_cost_cents")
                if cost is None:
                    logging.warning(
                        "WINDOW_CAP_NULL_TOTAL_COST: ticker=%s event_ticker=%s",
                        p.get("ticker"), et)
                    continue
                total += cost
        return total

    def execute(self, candidate: Dict) -> Optional[Dict]:
        """Always submit maker order. Escalation to taker happens in tick()."""
        # Observation safety belt — should never reach here for obs-only types
        # Exceptions:
        #   - weather NO-side bypasses observation_only when WEATHER_NO_SIDE_LIVE=True
        #   - hourly NO-side bypasses observation_only when HOURLY_NO_SIDE_LIVE=True
        #     (NO-side verification runs independently of the YES-side kill switch)
        _exec_cfg = get_market_config(candidate.get("product_type"))
        if _exec_cfg.observation_only:
            _is_weather_no_live = (candidate.get("product_type") == "weather"
                                  and candidate.get("side") == "no"
                                  and WEATHER_NO_SIDE_LIVE)
            _is_hourly_no_live = (candidate.get("product_type") == "hourly"
                                 and candidate.get("side") == "no"
                                 and HOURLY_NO_SIDE_LIVE)
            if not (_is_weather_no_live or _is_hourly_no_live):
                logging.error("SAFETY: %s candidate reached execute() — should never happen. Ticker=%s",
                              _exec_cfg.product_type, candidate.get("ticker"))
                return None

        asset = candidate["asset"]
        ticker = candidate["ticker"]

        # ── Unified exposure caps (always active) ─────────────────────
        _fresh_balance = None
        try:
            if self._ml and hasattr(self._ml, 'scanner'):
                _fresh_balance = self._ml.scanner._get_balance_cached()
            if not isinstance(_fresh_balance, (int, float)) or _fresh_balance <= 0:
                _fresh_balance = candidate.get("balance_at_scan")
        except Exception:
            _fresh_balance = candidate.get("balance_at_scan")

        if isinstance(_fresh_balance, (int, float)) and _fresh_balance > 0:
            # Per-ticker cap: 20% of balance
            _existing_ticker_cost = sum(
                p["total_cost_cents"]
                for p in self._state.get_open_positions()
                if p["ticker"] == ticker
            )
            _candidate_price = candidate.get("best_yes_ask",
                               candidate.get("best_ask", 96))
            _candidate_cost = candidate["position_size"] * _candidate_price
            _ticker_cap = _fresh_balance * MAX_TICKER_RISK

            if _existing_ticker_cost + _candidate_cost > _ticker_cap:
                _remaining = _ticker_cap - _existing_ticker_cost
                _reduced = max(0, int(_remaining / _candidate_price)) if _candidate_price > 0 else 0
                if _reduced <= 0:
                    logging.info(
                        "TICKER_CAP_SKIPPED: %s %s existing=%dc candidate=%dc cap=%dc",
                        ticker, candidate.get("strategy"),
                        _existing_ticker_cost, _candidate_cost, _ticker_cap)
                    return None
                else:
                    logging.info(
                        "TICKER_CAP_REDUCED: %s %s %d->%dct existing=%dc cap=%dc",
                        ticker, candidate.get("strategy"),
                        candidate["position_size"], _reduced,
                        _existing_ticker_cost, _ticker_cap)
                    candidate["position_size"] = _reduced
                    _candidate_cost = _reduced * _candidate_price

            # Per-window cap: cross-asset — sum ALL positions in the same 15-min timeslot
            _event_ticker = candidate.get("event_ticker")
            if _event_ticker:
                # Extract timeslot for cross-asset matching
                # Event tickers: KXBTC15M-26APR021000, KXETH15M-26APR021000 → timeslot=26APR021000
                _et_parts = _event_ticker.split("-", 1)
                _timeslot = _et_parts[1] if len(_et_parts) > 1 else _event_ticker
                _existing_window_cost = (
                    self._existing_window_cost_for_timeslot(
                        self._state.get_open_positions(), _timeslot))
                if _existing_window_cost > 0:
                    logging.debug("WINDOW_XASSET: timeslot=%s existing=$%.2f",
                                  _timeslot, _existing_window_cost / 100)
                _window_cap = _fresh_balance * MAX_WINDOW_RISK
                if _existing_window_cost + _candidate_cost > _window_cap:
                    _w_remaining = _window_cap - _existing_window_cost
                    _w_reduced = max(0, int(_w_remaining / _candidate_price)) if _candidate_price > 0 else 0
                    if _w_reduced <= 0:
                        logging.info(
                            "WINDOW_CAP_SKIPPED: %s %s window=%dc candidate=%dc cap=%dc",
                            _event_ticker, candidate.get("strategy"),
                            _existing_window_cost, _candidate_cost, _window_cap)
                        return None
                    else:
                        logging.info(
                            "WINDOW_CAP_REDUCED: %s %s %d->%dct window=%dc cap=%dc",
                            _event_ticker, candidate.get("strategy"),
                            candidate["position_size"], _w_reduced,
                            _existing_window_cost, _window_cap)
                        candidate["position_size"] = _w_reduced

        # ── HOURLY TAKER-ONLY PATH ──
        # Hourly uses IOC exclusively. No per-asset lock, no maker orders, no escalation.
        # This guarantees zero contention with 15M execution. Gated on product_type == "hourly".
        # Exception: hourly DC uses the DC taker path (strategy="hourly_dc"), not the hourly taker.
        if (candidate.get("product_type") == "hourly"
                and HOURLY_TAKER_ONLY
                and candidate.get("strategy") != "hourly_dc"
                and candidate.get("side") != "no"):
            return self._execute_hourly_taker(candidate)

        # ── HOURLY NO TAKER-ONLY PATH ──
        # Hourly NO-side verification: 1-contract IOC at NO ask price.
        # Same isolation as hourly YES taker — no per-asset lock, no maker, no escalation.
        if (candidate.get("product_type") == "hourly"
                and candidate.get("side") == "no"):
            return self._execute_hourly_no_taker(candidate)

        # ── WEATHER NO TAKER-ONLY PATH ──
        # Weather NO orderbooks are structurally empty — nobody posts resting NO
        # asks at 30-40c. Maker-first always cancels unfilled after escalation
        # timeout (3/3 canceled, 0% fill rate, Apr 12 2026). Direct IOC at ask.
        # 1 contract × 35c = $0.35 cost; ~30% assumed edge makes taker fee trivial.
        if (candidate.get("product_type") == "weather"
                and candidate.get("side") == "no"):
            return self._execute_weather_no_taker(candidate)

        # Gate 1: Per-asset lock for maker-first assets only.
        # Taker-first (SOL): IOC resolves synchronously (<1s), no concurrent order risk.
        # Maker-first (BTC/ETH/XRP): per-asset lock prevents two resting makers.
        if asset not in TAKER_FIRST_ASSETS:
            if asset in self._active_orders or asset in self._escalating_assets:
                logging.warning(
                    "ORDER_SUPPRESSED asset_lock: %s %s active_ticker=%s escalating=%s",
                    asset, ticker,
                    self._active_orders.get(asset, {}).get("ticker", "none"),
                    asset in self._escalating_assets)
                self._session_suppressed_asset_lock += 1
                return None

        # Gate 2: Ticker cooldown — skip tickers recently attempted via IOC
        cooldown_ts = self._recent_taker_tickers.get(ticker)
        if cooldown_ts is not None:
            _cd_remaining = IOC_TICKER_COOLDOWN - (time.time() - cooldown_ts)
            if _cd_remaining > 0:
                logging.warning(
                    "ORDER_SUPPRESSED ticker_cooldown: %s remaining=%.0fs",
                    ticker, _cd_remaining)
                self._session_suppressed_ticker_cooldown += 1
                return None
            del self._recent_taker_tickers[ticker]

        # Gate 3: Per-ticker API error cap — stop hammering after 3 consecutive failures.
        # Prevents hot retry loops on expired/closed markets (21 api_errors in 30s, Mar 23).
        _api_err_count = self._ticker_api_errors.get(ticker, 0)
        if _api_err_count >= self.TICKER_API_ERROR_CAP:
            logging.warning("ORDER_SUPPRESSED api_error_cap: %s errors=%d (capped at %d)",
                            ticker, _api_err_count, self.TICKER_API_ERROR_CAP)
            return None

        if OBSERVATION_MODE:
            logging.info(
                f"OBSERVATION MODE: Would place maker for {candidate['ticker']} "
                f"at {candidate.get('best_yes_ask', '?')}¢ for "
                f"{candidate.get('position_size', '?')} contracts"
            )
            try:
                _fv = candidate.get("best_yes_ask")
                _obs_offset = (MAKER_PRICE_OFFSET if _fv and _fv >= 90
                               else MAKER_PRICE_OFFSET + 1) if _fv else MAKER_PRICE_OFFSET
                self._logger.log_execution({
                    "action": "observation_would_trade",
                    "ticker": candidate["ticker"],
                    "asset": candidate["asset"],
                    "event_ticker": candidate["event_ticker"],
                    "best_yes_ask": candidate.get("best_yes_ask"),
                    "position_size": candidate.get("position_size"),
                    "edge": candidate.get("edge"),
                    "calibrated_prob": candidate.get("calibrated_prob"),
                    "strategy": candidate.get("strategy"),
                    "seconds_to_close": candidate.get("seconds_to_close"),
                    "vol_regime": candidate.get("vol_regime"),
                    "ofa_adjustment": candidate.get("ofa_adjustment"),
                    "balance_at_scan": candidate.get("balance_at_scan"),
                    "execution_params": {
                        "maker_price": (_fv - _obs_offset) if _fv else None,
                        "maker_offset": _obs_offset,
                        "post_only": True,
                        "escalation_strategy": "cancel_replace_ioc",
                        "taker_time_in_force": "ioc",
                    },
                })
                if _TELEGRAM:
                    _ba = candidate.get("best_yes_ask", "?")
                    _edge = candidate.get("edge")
                    _prob = candidate.get("calibrated_prob")
                    _sz = candidate.get("position_size", "?")
                    _asset = candidate.get("asset", "?")
                    _edge_s = f"{_edge:.1%}" if _edge is not None else "?"
                    _prob_s = f"{_prob:.0%}" if _prob is not None else "?"
                    _cost = (_ba * _sz / 100) if isinstance(_ba, (int, float)) and isinstance(_sz, (int, float)) else 0
                    _TELEGRAM.send(
                        f"\U0001f4ca {_asset} {_sz}ct @ {_ba}c "
                        f"(${_cost:.2f}) edge={_edge_s} prob={_prob_s}",
                        dedup_key=candidate["ticker"],
                    )
                if not hasattr(self, '_last_obs_ticker') or self._last_obs_ticker != candidate['ticker']:
                    self._last_obs_ticker = candidate['ticker']
                    _ba = candidate.get("best_yes_ask")
                    _cp = candidate.get("calibrated_prob")
                    _obs_fee_cfg = get_market_config(candidate.get("product_type"))
                    _fee1 = calculate_fee(1, _ba, is_taker=True, fee_mult_taker=_obs_fee_cfg.fee_multiplier_taker) if _ba else 0
                    _ev = (_cp * (100 - _ba)) - ((1 - _cp) * _ba) - _fee1 if (_ba and _cp) else None
                    self._state.insert_evaluated_opportunity(
                        candidate["ticker"], candidate["event_ticker"],
                        candidate["asset"], "observation_trade",
                        spot_price=candidate.get("spot"),
                        threshold=candidate.get("threshold"),
                        volatility=candidate.get("blended_rv"),
                        market_price=_ba,
                        seconds_to_close=candidate.get("seconds_to_close"),
                        calibrated_prob=_cp,
                        edge=candidate.get("edge"),
                        ofa_adjustment=candidate.get("ofa_adjustment"),
                        strategy=candidate.get("strategy"),
                        position_size=candidate.get("position_size"),
                        kelly_f=candidate.get("kelly_f"),
                        z_score=candidate.get("z_score"),
                        vol_regime=candidate.get("vol_regime"),
                        calibrated_prob_raw=candidate.get("calibrated_prob_raw"),
                        breakeven_wr=_ba / 100.0 if _ba else None,
                        expected_value=round(_ev, 2) if _ev is not None else None,
                        drawdown_scaler=candidate.get("drawdown_scaler"),
                        ask_depth=candidate.get("ob_snapshot", {}).get("ask_depth"),
                        best_ask_source=candidate.get("best_ask_source"),
                        ofa_confidence=candidate.get("ofa_confidence"),
                        raw_prob=candidate.get("raw_prob"),
                        calibration_method=candidate.get("calibration_method"),
                        old_system_prob=candidate.get("old_system_prob"),
                        fee_adjusted_edge=candidate.get("fee_adjusted_edge"),
                        egarch_sigma=candidate.get("egarch_sigma"),
                        egarch_blend_sigma=candidate.get("egarch_blend_sigma"),
                        egarch_blend_weight=candidate.get("egarch_blend_weight"),
                        mz_r_squared=candidate.get("mz_r_squared"),
                        shadow_tv_blend_rv=candidate.get("shadow_tv_blend_rv"),
                        mz_shadow_sigmoid_w=candidate.get("mz_shadow_sigmoid_w"),
                        mz_baseline_qlike=candidate.get("mz_baseline_qlike"),
                        mz_qlike=candidate.get("mz_qlike"),
                        counterfactual=candidate.get("counterfactual_json"),
                        shadow_cal_prob=candidate.get("shadow_cal_prob"),
                        shadow_cal_fee_edge=candidate.get("shadow_cal_fee_edge"),
                        shadow_cal_temperature=candidate.get("shadow_cal_temperature"),
                        oft_prob_adjustment=candidate.get("oft_prob_adjustment"),
                        oft_imbalance_ratio=candidate.get("oft_imbalance_ratio"),
                        oft_n_snapshots=candidate.get("oft_n_snapshots"),
                        product_type=candidate.get("product_type"),
                        wx_ensemble_mean=candidate.get("wx_ensemble_mean"),
                        wx_ensemble_std=candidate.get("wx_ensemble_std"),
                        wx_bias_correction=candidate.get("wx_bias_correction"),
                        wx_n_members=candidate.get("wx_n_members"),
                        wx_market_type=candidate.get("wx_market_type"),
                        wx_hrrr_temp=candidate.get("wx_hrrr_temp"),
                        wx_corrected_mean=candidate.get("wx_corrected_mean"),
                        hourly_pre_temp_prob=candidate.get("hourly_pre_temp_prob"),
                        hourly_applied_temp_t=candidate.get("hourly_applied_temp_t"),
                        hourly_shadow_temp_2_0=candidate.get("hourly_shadow_temp_2_0"),
                        hourly_shadow_temp_1_0=candidate.get("hourly_shadow_temp_1_0"),
                        hourly_shadow_temp_2_5=candidate.get("hourly_shadow_temp_2_5"),
                        hourly_shadow_blend_50=candidate.get("hourly_shadow_blend_50"),
                        hourly_shadow_temp_1_75=candidate.get("hourly_shadow_temp_1_75"),
                        hourly_shadow_temp_3_0=candidate.get("hourly_shadow_temp_3_0"),
                        hourly_shadow_blend_20=candidate.get("hourly_shadow_blend_20"),
                        hourly_shadow_blend_30=candidate.get("hourly_shadow_blend_30"),
                        hourly_shadow_blend_60=candidate.get("hourly_shadow_blend_60"),
                        hourly_post_temp_prob=candidate.get("hourly_post_temp_prob"),
                        available_balance_cents=candidate.get("balance_at_scan"),
                        # cal_mlp_* propagation: candidate dict carries these via
                        # **_shadow_diag splat at line ~15425. Without these kwargs
                        # the post-hoc processor's WHERE cal_mlp_request_id IS NOT NULL
                        # never matches the row → 0% annotation on real trades.
                        cal_mlp_request_id=candidate.get("cal_mlp_request_id"),
                        cal_mlp_skipped_reason=candidate.get("cal_mlp_skipped_reason"),
                        cal_mlp_p_mean=candidate.get("cal_mlp_p_mean"),
                        cal_mlp_p_std=candidate.get("cal_mlp_p_std"),
                        cal_mlp_final_lo=candidate.get("cal_mlp_final_lo"),
                        cal_mlp_final_hi=candidate.get("cal_mlp_final_hi"),
                        cal_mlp_train_id=candidate.get("cal_mlp_train_id"))
            except Exception as e:
                logging.error(f"OBSERVATION_DB_INSERT_FAILED: {candidate.get('ticker')}: {e}")
            return None

        # ── Log candidate to evaluated_opportunities (live mode) ──
        try:
            _ba = candidate.get("best_yes_ask")
            _cp = candidate.get("calibrated_prob")
            _cand_fee_cfg = get_market_config(candidate.get("product_type"))
            _fee1 = calculate_fee(1, _ba, is_taker=True, fee_mult_taker=_cand_fee_cfg.fee_multiplier_taker) if _ba else 0
            _ev = (_cp * (100 - _ba)) - ((1 - _cp) * _ba) - _fee1 if (_ba and _cp) else None
            self._state.insert_evaluated_opportunity(
                candidate["ticker"], candidate["event_ticker"],
                candidate["asset"], "candidate",
                spot_price=candidate.get("spot"),
                threshold=candidate.get("threshold"),
                volatility=candidate.get("blended_rv"),
                market_price=_ba,
                seconds_to_close=candidate.get("seconds_to_close"),
                calibrated_prob=_cp,
                edge=candidate.get("edge"),
                ofa_adjustment=candidate.get("ofa_adjustment"),
                strategy=candidate.get("strategy"),
                position_size=candidate.get("position_size"),
                kelly_f=candidate.get("kelly_f"),
                z_score=candidate.get("z_score"),
                vol_regime=candidate.get("vol_regime"),
                calibrated_prob_raw=candidate.get("calibrated_prob_raw"),
                breakeven_wr=_ba / 100.0 if _ba else None,
                expected_value=round(_ev, 2) if _ev is not None else None,
                drawdown_scaler=candidate.get("drawdown_scaler"),
                ask_depth=candidate.get("ob_snapshot", {}).get("ask_depth"),
                best_ask_source=candidate.get("best_ask_source"),
                ofa_confidence=candidate.get("ofa_confidence"),
                raw_prob=candidate.get("raw_prob"),
                calibration_method=candidate.get("calibration_method"),
                old_system_prob=candidate.get("old_system_prob"),
                fee_adjusted_edge=candidate.get("fee_adjusted_edge"),
                egarch_sigma=candidate.get("egarch_sigma"),
                egarch_blend_sigma=candidate.get("egarch_blend_sigma"),
                egarch_blend_weight=candidate.get("egarch_blend_weight"),
                mz_r_squared=candidate.get("mz_r_squared"),
                shadow_tv_blend_rv=candidate.get("shadow_tv_blend_rv"),
                mz_shadow_sigmoid_w=candidate.get("mz_shadow_sigmoid_w"),
                mz_baseline_qlike=candidate.get("mz_baseline_qlike"),
                mz_qlike=candidate.get("mz_qlike"),
                counterfactual=candidate.get("counterfactual_json"),
                shadow_cal_prob=candidate.get("shadow_cal_prob"),
                shadow_cal_fee_edge=candidate.get("shadow_cal_fee_edge"),
                shadow_cal_temperature=candidate.get("shadow_cal_temperature"),
                oft_prob_adjustment=candidate.get("oft_prob_adjustment"),
                oft_imbalance_ratio=candidate.get("oft_imbalance_ratio"),
                oft_n_snapshots=candidate.get("oft_n_snapshots"),
                product_type=candidate.get("product_type"),
                wx_ensemble_mean=candidate.get("wx_ensemble_mean"),
                wx_ensemble_std=candidate.get("wx_ensemble_std"),
                wx_bias_correction=candidate.get("wx_bias_correction"),
                wx_n_members=candidate.get("wx_n_members"),
                wx_market_type=candidate.get("wx_market_type"),
                wx_no_side_edge=candidate.get("wx_no_side_edge"),
                wx_hrrr_temp=candidate.get("wx_hrrr_temp"),
                wx_corrected_mean=candidate.get("wx_corrected_mean"),
                hourly_pre_temp_prob=candidate.get("hourly_pre_temp_prob"),
                hourly_applied_temp_t=candidate.get("hourly_applied_temp_t"),
                hourly_shadow_temp_2_0=candidate.get("hourly_shadow_temp_2_0"),
                hourly_shadow_temp_1_0=candidate.get("hourly_shadow_temp_1_0"),
                hourly_shadow_temp_2_5=candidate.get("hourly_shadow_temp_2_5"),
                hourly_shadow_blend_50=candidate.get("hourly_shadow_blend_50"),
                hourly_shadow_temp_1_75=candidate.get("hourly_shadow_temp_1_75"),
                hourly_shadow_temp_3_0=candidate.get("hourly_shadow_temp_3_0"),
                hourly_shadow_blend_20=candidate.get("hourly_shadow_blend_20"),
                hourly_shadow_blend_30=candidate.get("hourly_shadow_blend_30"),
                hourly_shadow_blend_60=candidate.get("hourly_shadow_blend_60"),
                hourly_post_temp_prob=candidate.get("hourly_post_temp_prob"),
                available_balance_cents=candidate.get("balance_at_scan"),
                cal_mlp_request_id=candidate.get("cal_mlp_request_id"),
                cal_mlp_skipped_reason=candidate.get("cal_mlp_skipped_reason"),
                cal_mlp_p_mean=candidate.get("cal_mlp_p_mean"),
                cal_mlp_p_std=candidate.get("cal_mlp_p_std"),
                cal_mlp_final_lo=candidate.get("cal_mlp_final_lo"),
                cal_mlp_final_hi=candidate.get("cal_mlp_final_hi"),
                cal_mlp_train_id=candidate.get("cal_mlp_train_id"))
        except Exception as e:
            logging.error(f"CANDIDATE_DB_INSERT_FAILED: {candidate.get('ticker')}: {e}")

        seconds_to_close = candidate.get("seconds_to_close")

        # ── Decided contract taker override ─────────────────────────
        # Must be checked BEFORE SOL taker-first and direct taker paths,
        # which apply MIN_EDGE_PCT (0.25%). DC uses -0.01 threshold.
        # Bug fix: SOL DC candidates were hitting SOL taker-first path
        # first, getting edge-gated at 0.25% when DC allows -1%.
        #
        # Non-blocking retry: Kalshi IOCs partial fill (fill whatever's on
        # the book, cancel the rest). On unfilled/partial, queue a retry
        # entry — processed at the TOP of next _tick() cycle (~5s later).
        # Data: 24% of DC tickers recover within 8-32s.
        _dc_strategy = candidate.get("strategy")
        if _dc_strategy in ("decided_t1", "decided_t1b", "decided_t2",
                            "decided_t2_z2", "decided_t2_z25", "hourly_dc"):
            return self._execute_dc_taker(candidate, asset, seconds_to_close)

        # ── Terminal momentum taker override ──────────────────────────
        if _dc_strategy and _dc_strategy.startswith("terminal_momentum"):
            return self._execute_tm_taker(candidate, asset, seconds_to_close)

        # ── LPNE taker override ──────────────────────────────────────
        if _dc_strategy == "low_price_near_expiry":
            return self._execute_lpne_taker(candidate, asset, seconds_to_close)

        # ── Bracket NO taker override ────────────────────────────────
        if _dc_strategy == "bracket_no":
            return self._execute_bracket_no_taker(candidate, asset, seconds_to_close)

        # ── SOL taker-first override ──────────────────────────────
        # SOL: bypass maker entirely, go direct IOC — UNLESS book is empty.
        # Data: 44.7% maker fill rate, $101/wk missed, 95% unfilled WR.
        # Empty-book fallback: post maker bid to attract counterparties (like BTC/ETH).
        # Data: 400 unfilled SOL depth=0 candidates at 87c+ have 95% hypothetical WR.
        _sol_empty_book_fallback = False
        if SOL_TAKER_FIRST and candidate.get("asset") == "SOL":
            _sol_depth = candidate.get("ob_snapshot", {}).get("ask_depth", 0)
            _sol_price = candidate.get("best_yes_ask", 0)
            _sol_stc = seconds_to_close or 0

            # Empty book + price >= 87c: fall through to maker path
            if _sol_depth == 0 and _sol_price >= SOL_EMPTY_BOOK_MAKER_MIN_PRICE:
                if _sol_stc < SOL_EMPTY_BOOK_MIN_STC:
                    logging.info(
                        "sol_empty_book_SKIP_STC: %s price=%dc depth=0 stc=%.0fs < %.0fs",
                        ticker, _sol_price, _sol_stc, SOL_EMPTY_BOOK_MIN_STC)
                    self._session_sol_empty_maker_skip_stc += 1
                    return None
                # Fall through to maker path (PATH 5)
                logging.info(
                    "sol_empty_book_MAKER_FALLBACK: %s price=%dc depth=0 stc=%.0fs",
                    ticker, _sol_price, _sol_stc)
                self._session_sol_empty_maker_attempt += 1
                _sol_empty_book_fallback = True
                # Need per-asset lock check (SOL normally skips it as taker-first)
                if asset in self._active_orders or asset in self._escalating_assets:
                    logging.warning(
                        "ORDER_SUPPRESSED asset_lock: %s %s (sol_empty_book_maker) active=%s",
                        asset, ticker, self._active_orders.get(asset, {}).get("ticker", "none"))
                    self._session_suppressed_asset_lock += 1
                    return None
                # Fall through — will hit PATH 5 (maker) below
            elif _sol_depth == 0:
                # Empty book but price < 87c: skip entirely
                logging.info(
                    "sol_empty_book_SKIP_PRICE: %s price=%dc depth=0 (< %dc floor)",
                    ticker, _sol_price, SOL_EMPTY_BOOK_MAKER_MIN_PRICE)
                self._session_sol_empty_maker_skip_price += 1
                return None

        if SOL_TAKER_FIRST and candidate.get("asset") == "SOL" and not _sol_empty_book_fallback:
            count = candidate["position_size"]
            price = candidate["best_yes_ask"]
            cal_prob = candidate["calibrated_prob"]

            if count <= 0:
                logging.warning("ORDER_SUPPRESSED zero_size: %s asset=SOL price=%d",
                                candidate["ticker"], price)
                self._session_suppressed_zero_size += 1
                return None

            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

            if net_edge < MIN_EDGE_PCT / 100.0:
                logging.warning(
                    "ORDER_SUPPRESSED edge_taker_fee: %s asset=SOL net_edge=%.4f < min=%.4f "
                    "price=%d taker_fee=%d¢ stc=%.0f",
                    candidate["ticker"], net_edge, MIN_EDGE_PCT / 100.0, price, taker_fee,
                    seconds_to_close or 0)
                self._session_suppressed_edge_recalc += 1
                return None

            fresh_ask = self._get_addon_best_ask(candidate["ticker"])
            if fresh_ask is None:
                fresh_ask = self._nbbo_fallback_price(candidate)
                if fresh_ask is None:
                    logging.warning("ORDER_SUPPRESSED no_asks: %s asset=SOL price=%d stc=%.0f",
                                    candidate["ticker"], price, seconds_to_close or 0)
                    self._session_suppressed_no_asks += 1
                    return None

            if fresh_ask != price:
                logging.info("sol_taker_override_price_update: %s scanner=%d¢ fresh=%d¢",
                             candidate["ticker"], price, fresh_ask)
                price = fresh_ask
                candidate["best_yes_ask"] = fresh_ask
                taker_fee = calculate_taker_fee(count, price)
                net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))
                if net_edge < MIN_EDGE_PCT / 100.0:
                    logging.warning(
                        "ORDER_SUPPRESSED edge_recalc: %s asset=SOL fresh_ask=%d net_edge=%.4f < min=%.4f",
                        candidate["ticker"], price, net_edge, MIN_EDGE_PCT / 100.0)
                    self._session_suppressed_edge_recalc += 1
                    return None

            # Apply ask+1c offset for fill certainty on taker-first
            ioc_price = min(price + IOC_RETRY_OFFSET, 99)
            if ioc_price != price:
                _offset_fee = calculate_taker_fee(count, ioc_price)
                _offset_edge = cal_prob - (ioc_price / 100.0) - (_offset_fee / (count * 100.0))
                if _offset_edge >= MIN_EDGE_PCT / 100.0:
                    price = ioc_price
                    candidate["best_yes_ask"] = ioc_price
                    net_edge = _offset_edge
                    taker_fee = _offset_fee

            logging.info(
                "sol_taker_override_ENTRY: %s %dx @ %d¢ "
                "seconds_to_close=%.0f net_edge=%.4f cal_prob=%.4f taker_fee=%d¢",
                candidate["ticker"], count, price,
                seconds_to_close or 0, net_edge, cal_prob, taker_fee)

            candidate["entry_path"] = "sol_taker_override"
            candidate["escalation_type"] = "sol_taker_override"
            self._recent_taker_tickers[candidate["ticker"]] = time.time()
            _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
            self._session_direct_taker_attempts += 1
            result = self._submit_taker(candidate)
            if result is not None:
                logging.info("sol_taker_override_FILLED: %s", candidate["ticker"])
                self._session_direct_taker_fills += 1
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    candidate["ticker"], order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled",
                    taker_ask_at_submit=candidate.get("best_yes_ask"))
            else:
                # IOC retry: refresh ask, try once more at fresh_ask + offset
                _retry_ask = self._get_addon_best_ask(candidate["ticker"])
                _retry_result = None
                if _retry_ask is not None:
                    _retry_price = min(_retry_ask + IOC_RETRY_OFFSET, 99)
                    # Don't chase more than 2c above original submission price
                    if _retry_price <= price + 2:
                        _retry_fee = calculate_taker_fee(count, _retry_price)
                        _retry_edge = cal_prob - (_retry_price / 100.0) - (_retry_fee / (count * 100.0))
                        if _retry_edge >= MIN_EDGE_PCT / 100.0:
                            logging.info("sol_taker_IOC_RETRY: %s retry_price=%d¢ retry_edge=%.4f",
                                         candidate["ticker"], _retry_price, _retry_edge)
                            candidate["best_yes_ask"] = _retry_price
                            candidate["escalation_type"] = "ioc_retry"
                            self._session_ioc_retries += 1
                            _retry_result = self._submit_taker(candidate)
                            if _retry_result is not None:
                                logging.info("sol_taker_IOC_RETRY_FILLED: %s", candidate["ticker"])
                                self._session_ioc_retry_fills += 1
                                result = _retry_result
                                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                                self._state.update_evaluated_opportunity_order(
                                    candidate["ticker"], order_id=_taker_oid,
                                    order_submitted_at=_order_submit_ts, order_outcome="filled",
                                    taker_ask_at_submit=candidate.get("best_yes_ask"))
                if _retry_result is None:
                    logging.warning("sol_taker_override_UNFILLED: %s", candidate["ticker"])
                    self._session_direct_taker_unfilled += 1
                    self._state.update_evaluated_opportunity_order(
                        candidate["ticker"], order_submitted_at=_order_submit_ts,
                        order_outcome="unfilled",
                        taker_ask_at_submit=candidate.get("best_yes_ask"))

            # ── SOL Path C shadow: log what maker path would have done ──
            try:
                _pathc_fv = price  # current best ask (possibly refreshed)
                _pathc_offset = MAKER_PRICE_OFFSET if _pathc_fv >= 90 else MAKER_PRICE_OFFSET + 1
                _pathc_maker_price = _pathc_fv - _pathc_offset

                # Get depth at the hypothetical maker price level
                _pathc_depth = 0
                try:
                    scanner = self._ml.scanner if self._ml else None
                    if scanner:
                        _pc_ob, _ = scanner._get_orderbook_cached(candidate["ticker"])
                        if _pc_ob:
                            _pathc_depth = OpportunityScanner._best_ask_depth(_pc_ob)
                except Exception:
                    pass

                _pathc_pos_size = candidate["position_size"]
                _eval_time = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")

                self._state.insert_sol_pathc_shadow(
                    ticker=candidate["ticker"],
                    evaluation_time=_eval_time,
                    live_ask=price,
                    live_depth=_pathc_depth,
                    live_edge=net_edge,
                    live_stc=seconds_to_close or 0,
                    live_contracts=count,
                    live_entry_price=price,
                    live_cal_prob=cal_prob,
                    pathc_maker_price=_pathc_maker_price,
                    pathc_maker_offset=_pathc_offset,
                    pathc_depth_at_maker=_pathc_depth,
                    position_size=_pathc_pos_size,
                )

                # Schedule for deferred observation (check every tick during escalation window)
                _esc_wait = ESCALATION_WAIT_LONG  # SOL uses default 15s
                self._sol_pathc_pending[candidate["ticker"]] = {
                    "start_time": time.time(),
                    "escalation_wait": _esc_wait,
                    "maker_price": _pathc_maker_price,
                    "position_size": _pathc_pos_size,
                    "cal_prob": cal_prob,
                    "touched": False,
                }
                logging.info(
                    "sol_pathc_shadow_LOGGED: %s maker_price=%d¢ offset=%d depth=%d pos_size=%d",
                    candidate["ticker"], _pathc_maker_price, _pathc_offset, _pathc_depth, _pathc_pos_size)
            except Exception:
                logging.warning("sol_pathc_shadow logging failed", exc_info=True)

            return result

        # ── Direct taker for <180s candidates ───────────────────────
        # Maker-only below 90s: block direct taker, fall through to maker
        if (seconds_to_close is not None
                and seconds_to_close < MAKER_ONLY_THRESHOLD
                and seconds_to_close < DIRECT_TAKER_THRESHOLD):
            logging.info(
                "direct_taker_BLOCKED_maker_only: %s seconds_to_close=%.0f",
                candidate["ticker"], seconds_to_close)
        elif seconds_to_close is not None and seconds_to_close < DIRECT_TAKER_THRESHOLD:
            count = candidate["position_size"]
            price = candidate["best_yes_ask"]
            cal_prob = candidate["calibrated_prob"]

            if count <= 0:
                logging.warning("ORDER_SUPPRESSED zero_size: %s asset=%s path=direct_taker price=%d",
                                candidate["ticker"], asset, price)
                self._session_suppressed_zero_size += 1
                self._session_direct_taker_skipped += 1
                return None

            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

            if net_edge < MIN_EDGE_PCT / 100.0:
                logging.warning(
                    "ORDER_SUPPRESSED edge_taker_fee: %s asset=%s path=direct_taker "
                    "net_edge=%.4f < min=%.4f price=%d taker_fee=%d¢ stc=%.0f",
                    candidate["ticker"], asset, net_edge, MIN_EDGE_PCT / 100.0,
                    price, taker_fee, seconds_to_close)
                self._session_suppressed_edge_recalc += 1
                self._session_direct_taker_skipped += 1
                return None

            # Verify actual liquidity before submitting IOC
            fresh_ask = self._get_addon_best_ask(candidate["ticker"])
            if fresh_ask is None:
                fresh_ask = self._nbbo_fallback_price(candidate)
                if fresh_ask is None:
                    logging.warning(
                        "ORDER_SUPPRESSED no_asks: %s asset=%s path=direct_taker stc=%.0f",
                        candidate["ticker"], asset, seconds_to_close)
                    self._session_suppressed_no_asks += 1
                    self._session_direct_taker_skipped += 1
                    return None

            # Use fresh ask if it differs from scanner's (may be stale NBBO)
            if fresh_ask != price:
                logging.info(
                    "direct_taker_price_update: %s scanner=%d¢ fresh=%d¢",
                    candidate["ticker"], price, fresh_ask)
                price = fresh_ask
                candidate["best_yes_ask"] = fresh_ask
                taker_fee = calculate_taker_fee(count, price)
                net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))
                if net_edge < MIN_EDGE_PCT / 100.0:
                    logging.info(
                        "direct_taker_SKIPPED: %s fresh_ask=%d¢ net_edge=%.4f < min",
                        candidate["ticker"], price, net_edge)
                    self._session_direct_taker_skipped += 1
                    return None

            self._session_direct_taker_attempts += 1
            logging.info(
                "direct_taker_ENTRY: %s %dx @ %d¢ "
                "seconds_to_close=%.0f net_edge=%.4f cal_prob=%.4f taker_fee=%d¢",
                candidate["ticker"], count, price,
                seconds_to_close, net_edge, cal_prob, taker_fee)

            candidate["entry_path"] = "direct_taker"
            candidate["escalation_type"] = "direct_taker"
            self._recent_taker_tickers[candidate["ticker"]] = time.time()
            _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
            result = self._submit_taker(candidate)
            if result is not None:
                self._session_direct_taker_fills += 1
                logging.info("direct_taker_FILLED: %s", candidate["ticker"])
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    candidate["ticker"], order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
            else:
                self._session_direct_taker_unfilled += 1
                logging.warning("direct_taker_UNFILLED: %s", candidate["ticker"])
                self._state.update_evaluated_opportunity_order(
                    candidate["ticker"], order_submitted_at=_order_submit_ts,
                    order_outcome="unfilled")
            return result

        # ── Three-tier post_only rejection escalation ──────────────
        ticker = candidate["ticker"]
        rejections = self._get_post_only_rejection_count(ticker)

        # Tier 3: Taker escalation (2 same-price + 1 degraded all failed)
        # Maker-only below 90s: block post-only taker escalation
        if (rejections >= POST_ONLY_MAX_SAME_PRICE + 1  # 3+
                and not (seconds_to_close is not None and seconds_to_close < MAKER_ONLY_THRESHOLD)):
            count = candidate["position_size"]
            price = candidate["best_yes_ask"]
            cal_prob = candidate["calibrated_prob"]

            if count <= 0:
                logging.warning("post_only_taker_SKIPPED: %s position_size=%d", ticker, count)
                self._post_only_rejections.pop(ticker, None)
                return None

            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

            if net_edge < MIN_EDGE_PCT / 100.0:
                logging.info(
                    "post_only_taker_SKIPPED: %s net_edge=%.4f < min=%.4f "
                    "taker_fee=%d¢ count=%d price=%d¢",
                    ticker, net_edge, MIN_EDGE_PCT / 100.0, taker_fee, count, price)
                self._post_only_rejections.pop(ticker, None)
                return None

            # Verify actual liquidity before submitting IOC
            fresh_ask = self._get_addon_best_ask(ticker)
            if fresh_ask is None:
                logging.info(
                    "post_only_taker_SKIPPED: %s no asks on orderbook", ticker)
                self._post_only_rejections.pop(ticker, None)
                return None

            if fresh_ask != price:
                logging.info(
                    "post_only_taker_price_update: %s scanner=%d¢ fresh=%d¢",
                    ticker, price, fresh_ask)
                price = fresh_ask
                candidate["best_yes_ask"] = fresh_ask
                taker_fee = calculate_taker_fee(count, price)
                net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))
                if net_edge < MIN_EDGE_PCT / 100.0:
                    logging.info(
                        "post_only_taker_SKIPPED: %s fresh_ask=%d¢ net_edge=%.4f < min",
                        ticker, price, net_edge)
                    self._post_only_rejections.pop(ticker, None)
                    return None

            logging.info(
                "post_only_taker_ESCALATION: %s %dx @ %d¢ "
                "rejections=%d net_edge=%.4f cal_prob=%.4f taker_fee=%d¢",
                ticker, count, price, rejections, net_edge, cal_prob, taker_fee)
            self._session_post_only_taker_escalations += 1
            candidate["entry_path"] = "post_only_taker"
            candidate["escalation_type"] = "post_only_taker"
            self._recent_taker_tickers[ticker] = time.time()
            _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
            result = self._submit_taker(candidate)
            if result is not None:
                self._post_only_rejections.pop(ticker, None)
                self._session_post_only_taker_fills += 1
                logging.info("post_only_taker_FILLED: %s", ticker)
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
            else:
                # Clear rejections to prevent hot retry loop on persistent API errors
                self._post_only_rejections.pop(ticker, None)
                logging.warning("post_only_taker_UNFILLED: %s (cleared rejections, will re-evaluate)", ticker)
                self._state.update_evaluated_opportunity_order(
                    ticker, order_submitted_at=_order_submit_ts,
                    order_outcome="unfilled")
            return result

        # Tier 2: Degraded maker (1¢ worse, one attempt)
        if rejections == POST_ONLY_MAX_SAME_PRICE:  # 2
            logging.info(
                "post_only_degraded_maker: %s rejections=%d, trying %d¢ worse",
                ticker, rejections, POST_ONLY_DEGRADED_EXTRA_OFFSET)
            self._session_post_only_degraded_attempts += 1
            self._submit_maker(candidate, degraded=True)
            _active = self._active_orders.get(candidate["asset"])
            if _active:
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_active["order_id"],
                    order_submitted_at=datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                    taker_ask_at_submit=candidate.get("best_yes_ask"))
            return None

        # Tier 1: Normal maker (attempt 1 or 2)
        self._submit_maker(candidate)
        _active = self._active_orders.get(candidate["asset"])
        if _active:
            self._state.update_evaluated_opportunity_order(
                candidate["ticker"], order_id=_active["order_id"],
                order_submitted_at=datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ"),
                taker_ask_at_submit=candidate.get("best_yes_ask"))
        return None

    def tick(self) -> Optional[Dict]:
        """Called each main-loop tick.  Iterates all active orders,
        polls for fills, and handles escalation independently per order.
        Also sweeps maker-tail orders for TTL expiry — must run even
        when _active_orders is empty, since tails outlive the IOC.
        """
        # Maker-tail TTL sweep runs unconditionally (before the
        # active_orders early-out below). A tail can outlive its
        # parent IOC's _active_orders entry, so gating the sweep on
        # active_orders being non-empty would let tails leak past TTL.
        if MAKER_TAIL_AFTER_IOC_PARTIAL and self._maker_tails:
            try:
                self._sweep_maker_tails()
            except Exception:
                logging.warning(
                    "_sweep_maker_tails raised", exc_info=True)
        if not self._active_orders:
            return None

        # Drain WS fills once, group by order_id
        ws_fills_by_oid: Dict[str, list] = {}
        if self._kalshi_feed and self._kalshi_feed.is_connected:
            try:
                for ws_fill in self._kalshi_feed.pop_fills():
                    oid = ws_fill.get("order_id", "")
                    ws_fills_by_oid.setdefault(oid, []).append(ws_fill)
            except Exception:
                logging.warning("WS fill drain failed", exc_info=True)

        result = None
        for asset in list(self._active_orders):
            order = self._active_orders.get(asset)
            if order is None:
                continue  # removed by a prior iteration's escalation
            order_ws = ws_fills_by_oid.get(order.get("order_id", ""), [])
            r = self._tick_one(order, asset, order_ws)
            if r is not None:
                result = r
        return result

    def _tick_sol_pathc_observations(self):
        """Check orderbook every tick for pending SOL Path C shadow entries.

        During the escalation window (default 15s), continuously monitor the
        orderbook. If best ask ever touches the hypothetical maker price,
        set obs_maker_price_touched=1 (sticky). After escalation window expires,
        write final observation snapshot and remove from pending.
        """
        if not self._sol_pathc_pending:
            return

        now = time.time()
        completed = []

        for ticker, info in self._sol_pathc_pending.items():
            elapsed = now - info["start_time"]
            maker_price = info["maker_price"]

            # Fetch current orderbook
            obs_ask = self._get_addon_best_ask(ticker)
            obs_depth = 0
            if obs_ask is not None:
                try:
                    scanner = self._ml.scanner if self._ml else None
                    if scanner:
                        _ob, _ = scanner._get_orderbook_cached(ticker)
                        if _ob:
                            obs_depth = OpportunityScanner._best_ask_depth(_ob)
                except Exception:
                    pass

            # Check if ask has touched maker price (sticky boolean)
            if obs_ask is not None and obs_ask <= maker_price:
                if not info["touched"]:
                    info["touched"] = True
                    try:
                        self._state.update_sol_pathc_touch(ticker)
                    except Exception:
                        logging.warning("sol_pathc_touch update failed for %s", ticker, exc_info=True)

            maker_would_fill = 1 if (obs_ask is not None and obs_ask <= maker_price) else 0

            # After escalation window: write final observation and compute escalation snapshot
            if elapsed >= info["escalation_wait"]:
                # Compute escalation taker edge
                esc_edge = None
                if obs_ask is not None:
                    esc_taker_fee = calculate_taker_fee(info["position_size"], obs_ask)
                    esc_edge = info["cal_prob"] - (obs_ask / 100.0) - (esc_taker_fee / (info["position_size"] * 100.0))

                obs_time = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
                try:
                    self._state.update_sol_pathc_observation(
                        ticker=ticker,
                        obs_time=obs_time,
                        obs_elapsed=round(elapsed, 1),
                        obs_best_ask=obs_ask,
                        obs_depth=obs_depth,
                        obs_maker_would_fill=maker_would_fill,
                        obs_maker_price_touched=1 if info["touched"] else 0,
                        pathc_esc_ask=obs_ask,
                        pathc_esc_depth=obs_depth,
                        pathc_esc_edge=esc_edge,
                    )
                    logging.info(
                        "sol_pathc_obs_FINAL: %s elapsed=%.1fs ask=%s depth=%d touched=%s esc_edge=%s",
                        ticker, elapsed, obs_ask, obs_depth, info["touched"],
                        f"{esc_edge:.4f}" if esc_edge is not None else "None")
                except Exception:
                    logging.warning("sol_pathc_observation write failed for %s", ticker, exc_info=True)

                completed.append(ticker)

        for ticker in completed:
            self._sol_pathc_pending.pop(ticker, None)

    def _tick_one(self, order: Dict, asset: str,
                  ws_fills: list) -> Optional[Dict]:
        """Handle one active order: poll for fill, escalate if needed."""
        now = time.time()

        # Backstop: if more than 60s past expected close and order still
        # tracked, some path failed to clean up (404-variant the
        # targeted fix doesn't anticipate, missed WS expiry, etc.).
        # Force-pop with WARNING. See kb/failures/cancel-404-asset-lockout-may04.md
        elapsed = now - order["submit_time"]
        remaining = order["seconds_to_close_at_submit"] - elapsed
        if remaining < -60.0:
            filled = order.get("filled_so_far", 0)
            if filled > 0:
                db_status = "partial_canceled"
                outcome = "partial_filled"
                fm_label = "partial_canceled"
            else:
                db_status = "expired"
                outcome = "expired"
                fm_label = "expired"
            backstop_reason = (
                f"force_pop_after_close"
                f"_pending={order.get('cancel_pending', False)}"
                f"_esc={order.get('escalated', False)}"
            )
            # POP FIRST. Single outer try wraps audit writes — see
            # _handle_cancel_404 docstring for rationale.
            self._active_orders.pop(asset, None)
            try:
                self._state.mark_order_status(order["order_id"], db_status)
                self._logger.log_order({
                    "action": "maker_canceled",
                    "ticker": order["ticker"],
                    "order_id": order["order_id"],
                    "reason": backstop_reason,
                    "elapsed": round(elapsed, 1),
                    "filled_so_far": filled,
                })
                self._log_fill_model_sample(
                    order, fm_label, cancel_reason=backstop_reason)
                if asset not in self._escalating_assets:
                    self._state.update_evaluated_opportunity_order(
                        order["ticker"], order_outcome=outcome)
            except Exception:
                logging.error(
                    f"force_pop_audit_failed: {order['ticker']} "
                    f"{order['order_id']} — pop complete, audit "
                    f"incomplete.",
                    exc_info=True)
            logging.warning(
                f"force_pop_after_close: {order['ticker']} "
                f"{order['order_id']} remaining={remaining:.1f}s "
                f"filled={filled}/{order['count']} "
                f"reason={backstop_reason} — backstop fired.")
            return None

        if now - order["_last_poll"] < MAKER_POLL_INTERVAL:
            return None
        order["_last_poll"] = now

        # Reconcile cancel_pending orders: retry cancel via Kalshi API
        if order.get("cancel_pending"):
            try:
                cancel_resp = self._client.cancel_order(order["order_id"])
                # 404 sentinel — Kalshi has aged it; route through helper.
                if isinstance(cancel_resp, dict) and cancel_resp.get("_status_code") == 404:
                    self._handle_cancel_404(
                        order, asset, "cancel_pending_retry",
                        source="reconciliation")
                    return None
                if cancel_resp is not None:
                    logging.info(f"cancel_pending resolved: {order['ticker']} cancel succeeded on retry")
                    order.pop("cancel_pending", None)
                    self._state.mark_order_status(order["order_id"], "canceled")
                    self._active_orders.pop(asset, None)
                    self._state.update_evaluated_opportunity_order(
                        order["ticker"], order_outcome="canceled")
                    return None
                # Cancel still failing — check if order was already filled
                fills_resp = self._client.get_fills(ticker=order["ticker"])
                if fills_resp:
                    fills = fills_resp.get("fills", [])
                    for f in fills:
                        if f.get("order_id") == order["order_id"]:
                            logging.info(f"cancel_pending resolved: {order['ticker']} was filled")
                            order.pop("cancel_pending", None)
                            break  # Let normal fill detection handle it below
            except Exception as e:
                logging.error(f"cancel_pending reconciliation error for {order['ticker']}: {e}")

        # 0. Check WebSocket fills (pre-drained, zero API cost)
        for ws_fill in ws_fills:
            order["fill_source"] = "websocket"
            self._session_ws_fills += 1
            latency_ms = round((now - order["submit_time"]) * 1000, 1)
            logging.info(
                f"kalshi_ws_fill: {order['ticker']} order={order['order_id']} "
                f"latency={latency_ms}ms")
            self._on_fill(ws_fill, order)
            ws_trade_id = ws_fill.get("trade_id") or ws_fill.get("id")
            if not ws_trade_id:
                # Synthetic dedup key when trade_id missing — prevents REST double-count
                self._ws_fill_seq = getattr(self, '_ws_fill_seq', 0) + 1
                ws_trade_id = f"syn_{ws_fill.get('order_id','')}_{ws_fill.get('count','')}_{ws_fill.get('price','')}_{self._ws_fill_seq}"
                logging.warning(f"WS fill missing trade_id for {order['ticker']}, using synthetic key: {ws_trade_id}")
            order.setdefault("_seen_fill_ids", set()).add(ws_trade_id)
            if order.get("filled_so_far", 0) >= order["count"]:
                self._active_orders.pop(asset, None)
                self._state.update_evaluated_opportunity_order(
                    order["ticker"], order_outcome="filled")
                return ws_fill
            logging.info(
                f"Partial WS fill — keeping order active "
                f"({order['filled_so_far']}/{order['count']})")

        # 1. Check for maker fill via REST
        fill = self._check_for_fill(order)
        if fill:
            order["fill_source"] = "rest_poll"
            self._session_rest_fills += 1
            self._on_fill(fill, order)
            if order.get("filled_so_far", 0) >= order["count"]:
                self._active_orders.pop(asset, None)
                self._state.update_evaluated_opportunity_order(
                    order["ticker"], order_outcome="filled")
                return fill
            logging.info(
                f"Partial REST fill — keeping order active "
                f"({order['filled_so_far']}/{order['count']})")

        elapsed = now - order["submit_time"]
        remaining = order["seconds_to_close_at_submit"] - elapsed

        # 2. Too close to expiry — cancel, don't escalate
        if remaining < MIN_SECONDS_BEFORE_CLOSE:
            self._cancel_order(asset, "close_approaching")
            return None

        # 2.5 Queue position polling (~every 5s, rate-limit friendly)
        if now - order["_last_queue_poll"] >= 5.0:
            order["_last_queue_poll"] = now
            try:
                qpos = self._client.get_queue_position(order["order_id"])
                if qpos is not None:
                    order["queue_position"] = qpos
                    logging.debug(
                        f"queue_position_check: {order['ticker']} "
                        f"order={order['order_id']} position={qpos}")
            except Exception:
                pass  # Non-critical, don't disrupt flow

        # 3. Escalation: maker waited long enough? (skip if already escalated)
        # Maker-only below 90s: no taker escalation, let maker fill or expire
        if not order.get("escalated") and remaining >= MAKER_ONLY_THRESHOLD:
            # ── Early escalation: ask confirms thesis ──────────────
            current_ask = self._get_addon_best_ask(order["ticker"])
            if current_ask is not None:
                order["_ask_history"].append((now, current_ask))
                ask_move = current_ask - order["price_cents"]
                if ask_move >= 2 and ask_move < EARLY_ESCALATION_MIN_MOVE:
                    # Shadow: log skipped early escalations (2-4c) for data collection
                    if not order.get("_ask_confirmed_skipped_logged"):
                        order["_ask_confirmed_skipped_logged"] = True
                        _skip_candidate = order["candidate"]
                        _skip_count = order["count"]
                        _skip_fee = calculate_taker_fee(_skip_count, current_ask)
                        _skip_edge = _skip_candidate["calibrated_prob"] - (current_ask / 100.0) - (_skip_fee / (_skip_count * 100.0))
                        logging.info(
                            "ask_confirmed_SKIPPED: %s ask=%d¢ (maker=%d¢ +%d¢) "
                            "net_edge=%.4f elapsed=%.1fs threshold=%d¢",
                            order["ticker"], current_ask, order["price_cents"],
                            ask_move, _skip_edge, elapsed, EARLY_ESCALATION_MIN_MOVE)
                if ask_move >= EARLY_ESCALATION_MIN_MOVE:
                    candidate = order["candidate"]
                    cal_prob = candidate["calibrated_prob"]
                    count = order["count"]
                    taker_fee = calculate_taker_fee(count, current_ask)
                    net_edge = cal_prob - (current_ask / 100.0) - (taker_fee / (count * 100.0))
                    if net_edge >= MIN_EDGE_PCT / 100.0:
                        logging.info(
                            "early_escalation_TRIGGER: %s ask=%d¢ (maker=%d¢ +%d¢) "
                            "net_edge=%.4f elapsed=%.1fs",
                            order["ticker"], current_ask, order["price_cents"],
                            ask_move, net_edge, elapsed)
                        return self._escalate_to_taker(order, remaining,
                                                       reason="ask_confirmed")

            # ── Standard time-based escalation (existing code) ─────
            escalation_wait = self._escalation_wait(remaining, asset=order.get("asset", ""))
            # Queue-aware: escalate earlier if deep in queue and time is short
            queue_pos = order.get("queue_position")
            if queue_pos is not None and queue_pos > 20 and remaining < 60:
                escalation_wait = min(escalation_wait, 5.0)
            if elapsed >= escalation_wait:
                return self._escalate_to_taker(order, remaining)

        # 4. Hard timeout fallback
        if elapsed >= MAKER_TIMEOUT_SECONDS:
            self._cancel_order(asset, "timeout")

        return None

    @staticmethod
    def _escalation_wait(remaining: float, asset: str = "") -> float:
        """Urgency-based maker wait before escalating to taker."""
        if remaining >= 180:
            # BTC: shorter wait (7s vs 15s) — ask_confirmed avg 2.7s, slip 3.4c
            if asset == "BTC" and BTC_ESCALATION_WAIT_OVERRIDE is not None:
                return BTC_ESCALATION_WAIT_OVERRIDE
            return ESCALATION_WAIT_LONG     # 15s — ample time, let maker fill
        elif remaining >= 120:
            return ESCALATION_WAIT_MEDIUM   # 7s — 86% of fills happen within 7s
        else:
            return ESCALATION_WAIT_SHORT    # 5s — tight, quick escalation

    # ── Market Intelligence Helpers ───────────────────────────────────────

    @staticmethod
    def _best_ask_depth(ob_data: Dict) -> int:
        """Depth (contracts) at the best YES ask (= highest NO bid level)."""
        no_bids = ob_data.get("no", [])
        if not no_bids:
            return 0
        best_price = -1
        best_qty = 0
        for entry in no_bids:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price, qty = entry[0], int(entry[1])
            elif isinstance(entry, dict):
                price = entry.get("price", 0)
                qty = int(entry.get("quantity", 0))
            else:
                continue
            if isinstance(price, float) and price < 1.0:
                price_cents = round(price * 100)
            else:
                price_cents = int(price)
            if price_cents > best_price:
                best_price = price_cents
                best_qty = qty
        return best_qty

    @staticmethod
    def _compute_ladder_diag(live_ob) -> Dict:
        """F/U TM_99 zero-fill diagnostic. Extract yes_asks_top and
        no_bid_top (price + qty) from cached orderbook, compute the
        cross-side derivation `100 - no_bid_top` and whether the two
        ladders diverge.

        Distinguishes which hypothesis is right when ETH TM_99 IOCs
        fail to fill at 99c:
          - HYP A: Kalshi's matching engine fills only against the
            explicit yes_asks ladder, not synthetic cross-side. If
            yes_asks_top > our bid AND ladders diverge, our IOC
            can't cross.
          - HYP B: Kalshi matches both ladders, but no_bid is too
            thin and gets sniped before our IOC arrives.
        Logged at IOC submit. Pure observability — no behavior change.

        Returns: {yes_ask_top_price, yes_ask_top_qty, no_bid_top_price,
                  no_bid_top_qty, cross_side_ask, diverges}
        See kb/failures (when written).
        """
        out = {
            "yes_ask_top_price": None, "yes_ask_top_qty": 0,
            "no_bid_top_price": None, "no_bid_top_qty": 0,
            "cross_side_ask": None, "diverges": False,
            "one_side_empty": False,
        }
        if not live_ob:
            return out

        def _to_cents(p):
            # Handle: int (already cents), float < 1.0 (dollar format,
            # e.g. 0.99 = 99c), float in [1.0, 100.0] (could be dollar
            # 1.00 = 100c OR cents 1.0 = 1c — Kalshi never sends
            # "1.00 dollars" for binary 0-100c contracts, so treat as
            # cents), string (cast through float first — schema drift
            # defense, see MEMORY: feedback_kalshi_schema_drift).
            try:
                if isinstance(p, str):
                    p = float(p)
                if isinstance(p, float) and 0 < p < 1.0:
                    return round(p * 100)
                return int(p)
            except (TypeError, ValueError):
                return None

        # yes_asks: pick LOWEST price (best ask for buyer).
        for entry in (live_ob.get("yes") or []):
            if not (isinstance(entry, (list, tuple)) and len(entry) >= 2):
                continue
            p = _to_cents(entry[0])
            if p is None:
                continue
            try:
                q = int(entry[1])
            except (TypeError, ValueError):
                q = 0
            if (out["yes_ask_top_price"] is None
                    or p < out["yes_ask_top_price"]):
                out["yes_ask_top_price"] = p
                out["yes_ask_top_qty"] = q

        # no_bids: pick HIGHEST price (best NO bid → best cross-side).
        for entry in (live_ob.get("no") or []):
            if not (isinstance(entry, (list, tuple)) and len(entry) >= 2):
                continue
            p = _to_cents(entry[0])
            if p is None:
                continue
            try:
                q = int(entry[1])
            except (TypeError, ValueError):
                q = 0
            if (out["no_bid_top_price"] is None
                    or p > out["no_bid_top_price"]):
                out["no_bid_top_price"] = p
                out["no_bid_top_qty"] = q

        if out["no_bid_top_price"] is not None:
            out["cross_side_ask"] = 100 - out["no_bid_top_price"]

        if (out["yes_ask_top_price"] is not None
                and out["cross_side_ask"] is not None):
            out["diverges"] = (
                out["yes_ask_top_price"] != out["cross_side_ask"])

        # one_side_empty: tri-state signal for grep — captures the
        # case where one ladder is missing entirely. R-review [A4]:
        # `diverges=False + one_side_empty=False` means real
        # alignment; `diverges=False + one_side_empty=True` means
        # uninformative. Don't conflate.
        out["one_side_empty"] = (
            (out["yes_ask_top_price"] is None)
            != (out["no_bid_top_price"] is None)
        )

        return out

    @staticmethod
    def _pick_ioc_limit_for_depth(
            ob_data: Dict,
            best_yes_ask: int,
            target_qty: int,
            max_bump_cents: int,
            edge_ceiling_price: int,
            max_price: int = 99) -> int:
        """Walk the orderbook from `best_yes_ask` upward, return the
        smallest YES limit price where cumulative fillable depth
        meets `target_qty`. Hard-capped at:
          - `best_yes_ask + max_bump_cents` (operational ceiling)
          - `edge_ceiling_price` (EV ceiling — caller computes
            from `floor(calibrated_prob*100) - fee - reserve_cents`,
            where reserve_cents is per-strategy
            (STRATEGY_LIMIT_BUMP_RESERVE_CENTS, default 0). At
            limit = ceiling, worst-case fill has edge = reserve.
            Default reserve=0 means break-even after fee on worst
            fill; aggressive overrides (-1) tolerate ~1c negative
            edge on worst fill. NOTE: this no longer respects
            MIN_EDGE_PCT — that floor was a SCAN-time gate, not a
            submit-time gate. The submit gate uses per-strategy
            reserve directly.)
          - `max_price` (defaults to MAX_ENTRY_PRICE = 99)

        If no level inside the cap delivers `target_qty`, returns
        the highest level inside the cap (still better than
        best_yes_ask alone — Kalshi auto-cancels surplus at $0).

        If the orderbook has no fillable depth at any level inside
        the cap, returns `best_yes_ask` unchanged (caller will
        discover empty book via PHANTOM_ABORT).

        WHY (Apr 25 2026):
        Pre-Apr 23 the WS schema bug masked the orderbook → bot
        fell back to NBBO yes_ask (typically wider than orderbook
        best_ask) → IOC swept multiple price levels → 64-82ct
        avg fills. Post-Apr 23 fix made the bot use orderbook
        best_ask exactly → matches only top-of-book → 33ct avg.
        Liquidity didn't disappear — just sat 1-3c above our
        IOC limit. Production sample: 1ct at 66c, 151ct at 69c.
        This helper restores access to the deep level when the
        candidate's edge can absorb the bump.

        Mechanics: Kalshi orderbooks store YES asks via the NO
        bid stack — NO bid at price P = YES ask at (100 - P).
        We walk YES ask prices ascending from best_yes_ask, sum
        qty, return first price where cumul ≥ target.

        Sub-floor levels (YES asks below best_yes_ask) are NOT
        included in the walk because the picker only chooses
        the LIMIT, not the fill source — Kalshi's matching engine
        will sweep sub-floor asks at any limit ≥ them, but that's
        Variant B behavior intentional under the no_clamp policy."""
        # Caller's edge_ceiling_price might be below best_yes_ask
        # (defensive — candidate shouldn't have been generated, but
        # never return a price below best_yes_ask).
        if max_bump_cents <= 0 or target_qty <= 0:
            return best_yes_ask
        cap = min(
            best_yes_ask + max_bump_cents,
            max(edge_ceiling_price, best_yes_ask),
            max_price,
        )
        if cap < best_yes_ask:
            return best_yes_ask
        # Build the YES-ask ladder from the NO bid stack, filter to
        # prices in [best_yes_ask, cap], sort ascending.
        no_bids = ob_data.get("no") or []
        levels: list = []
        for entry in no_bids:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price, qty = entry[0], entry[1]
            elif isinstance(entry, dict):
                price = entry.get("price", 0)
                qty = entry.get("quantity", 0)
            else:
                continue
            try:
                qty_int = int(qty)
            except (TypeError, ValueError):
                continue
            if qty_int <= 0:
                continue
            # Normalize price to cents.
            if isinstance(price, float) and price < 1.0:
                price_cents = round(price * 100)
            else:
                try:
                    price_cents = int(price)
                except (TypeError, ValueError):
                    continue
            yes_ask = 100 - price_cents
            if best_yes_ask <= yes_ask <= cap:
                levels.append((yes_ask, qty_int))
        if not levels:
            return best_yes_ask
        levels.sort()  # ascending YES price
        cumul = 0
        for yes_ask, qty in levels:
            cumul += qty
            if cumul >= target_qty:
                return yes_ask
        # Walked everything inside cap without hitting target.
        # Return highest level we reached — better than best_ask.
        return levels[-1][0]

    @staticmethod
    def _total_ob_depth(ob_data: Dict) -> int:
        """Total depth (contracts) across all orderbook levels."""
        total = 0
        for side in ("no", "yes"):
            for entry in (ob_data.get(side) or []):
                if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                    total += int(entry[1])
                elif isinstance(entry, dict):
                    total += int(entry.get("quantity", 0))
        return total

    @staticmethod
    def _best_yes_bid(ob_data: Dict) -> Optional[int]:
        """Highest YES bid price in cents."""
        yes_bids = ob_data.get("yes", [])
        best = None
        for entry in yes_bids:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price = entry[0]
            elif isinstance(entry, dict):
                price = entry.get("price", 0)
            else:
                continue
            price_cents = round(price * 100) if isinstance(price, float) and price < 1.0 else int(price)
            if best is None or price_cents > best:
                best = price_cents
        return best

    @staticmethod
    def _best_yes_bid_depth(ob_data: Dict) -> int:
        """Depth at the highest YES bid."""
        yes_bids = ob_data.get("yes", [])
        best_price = -1
        best_qty = 0
        for entry in yes_bids:
            if isinstance(entry, (list, tuple)) and len(entry) >= 2:
                price, qty = entry[0], int(entry[1])
            elif isinstance(entry, dict):
                price = entry.get("price", 0)
                qty = int(entry.get("quantity", 0))
            else:
                continue
            price_cents = round(price * 100) if isinstance(price, float) and price < 1.0 else int(price)
            if price_cents > best_price:
                best_price = price_cents
                best_qty = qty
        return best_qty

    @staticmethod
    def _extract_book_levels(ob_data: Optional[Dict], n: int = 10) -> Optional[str]:
        """Top-N YES-side ladder as compact JSON for forensic logging.

        Returns: '{"yes_bids":[[p,q],...],"yes_asks":[[p,q],...]}' or None.
        yes_bids sorted desc by price (best bid first).
        yes_asks derived from raw NO bids via 100-p, sorted asc (best ask first).

        Input contract:
        - ob_data must be a coalesced book (dict), not a delta frame.
          Non-dict input (None, list, str) returns None.
        - Float price <= 1.0 treated as probability (× 100 → cents).
          Float price > 1.0 treated as already-cents.

        Dropped (silently): NaN/Inf/negative/missing/bool qty,
        price < 0 or > 100, bool price, malformed entry shapes,
        duplicate price levels are merged (sum qty).
        """
        if not isinstance(ob_data, dict):
            return None

        def _parse_and_merge(entries):
            """Parse entries to {price_cents: total_qty} dict, merging duplicates."""
            out: Dict[int, int] = {}
            for entry in entries or []:
                if isinstance(entry, (list, tuple)):
                    if len(entry) < 2:
                        continue
                    price, qty = entry[0], entry[1]
                elif isinstance(entry, dict):
                    if "quantity" not in entry:
                        continue
                    price = entry.get("price")
                    qty = entry.get("quantity")
                else:
                    continue
                # Reject bools (subclass of int — silently poisons output)
                if isinstance(price, bool) or isinstance(qty, bool):
                    continue
                try:
                    if isinstance(qty, float) and not math.isfinite(qty):
                        continue
                    qty_int = int(qty)
                    if qty_int <= 0:
                        continue
                    if isinstance(price, float):
                        if not math.isfinite(price):
                            continue
                        if price <= 1.0:
                            price_cents = round(price * 100)
                        else:
                            price_cents = int(price)
                    else:
                        price_cents = int(price)
                except (TypeError, ValueError, OverflowError):
                    continue
                if price_cents < 0 or price_cents > 100:
                    continue
                out[price_cents] = out.get(price_cents, 0) + qty_int
            return out

        yes_bids_merged = _parse_and_merge(ob_data.get("yes"))
        no_bids_merged = _parse_and_merge(ob_data.get("no"))

        yes_bids = heapq.nlargest(n, yes_bids_merged.items(), key=lambda kv: kv[0])
        # NO bid >= 100c → derived YES ask <= 0, drop as nonsensical
        yes_asks_iter = ((100 - p, q) for p, q in no_bids_merged.items() if p < 100)
        yes_asks = heapq.nsmallest(n, yes_asks_iter, key=lambda pq: pq[0])

        return json.dumps(
            {"yes_bids": [[p, q] for p, q in yes_bids],
             "yes_asks": [[p, q] for p, q in yes_asks]},
            separators=(",", ":"),
        )

    # ── Repricing ─────────────────────────────────────────────────────────

    def _reprice_maker(self, new_price: int) -> bool:
        """Amend maker order to a new price. Returns True on success."""
        if self._active_order is None:
            return False
        order = self._active_order
        self._session_amend_attempts += 1
        try:
            _side = order.get("side", "yes")
            _price_kwarg = {"no_price": new_price} if _side == "no" else {"yes_price": new_price}
            resp = self._client.amend_order(
                order_id=order["order_id"], ticker=order["ticker"],
                side=_side, action="buy", count=order["count"],
                **_price_kwarg)
            if resp is None:
                logging.warning(
                    f"amend_failed_fallback: {order['ticker']} "
                    f"old={order['price_cents']}¢ new={new_price}¢")
                return False
            old_price = order["price_cents"]
            order["price_cents"] = new_price
            self._session_amend_successes += 1
            logging.info(
                f"amend_success: {order['ticker']} "
                f"{old_price}¢ → {new_price}¢ order={order['order_id']}")
            return True
        except Exception:
            logging.warning("Amend failed with exception", exc_info=True)
            return False

    def _escalate_to_taker(self, order: Dict, remaining: float,
                           reason: str = "escalation_wait") -> Optional[Dict]:
        """Escalate maker to taker via cancel-replace IOC."""
        ticker = order["ticker"]
        asset = order["asset"]
        self._escalating_assets.add(asset)
        try:
            return self._escalate_to_taker_inner(order, remaining, reason)
        finally:
            self._escalating_assets.discard(asset)

    def _escalate_to_taker_inner(self, order: Dict, remaining: float,
                                  reason: str = "escalation_wait") -> Optional[Dict]:
        """Inner escalation logic (guarded by _escalating_assets)."""
        ticker = order["ticker"]
        elapsed = time.time() - order["submit_time"]

        # Re-fetch orderbook for current best ask
        ob_raw = self._client.get_orderbook(ticker, depth=5)
        if ob_raw is None:
            logging.warning(f"Escalation aborted: orderbook fetch failed for {ticker}")
            self._cancel_order(order["asset"], reason)
            self._state.update_evaluated_opportunity_order(ticker, order_outcome="canceled")
            return None

        # Unwrap response envelope (same as _get_orderbook_cached)
        ob_fp = ob_raw.get("orderbook_fp") if ob_raw else None
        if ob_fp:
            ob_data = OpportunityScanner._convert_orderbook_fp(ob_fp)
        else:
            ob_data = ob_raw.get("orderbook") or ob_raw

        best_ask = OpportunityScanner._best_yes_ask_cents(ob_data)
        if best_ask is None:
            logging.warning(f"Escalation aborted: no asks on orderbook for {ticker}")
            self._cancel_order(order["asset"], reason)
            self._state.update_evaluated_opportunity_order(ticker, order_outcome="canceled")
            return None

        # Per-asset price floor for escalation (mirrors scanner + maker)
        _esc_floor = MIN_ENTRY_PRICE
        _esc_asset = order.get("asset")
        if _esc_asset == "BTC":
            _esc_floor = BTC_MIN_ENTRY_PRICE
        elif _esc_asset == "ETH":
            _esc_floor = ETH_MIN_ENTRY_PRICE
        elif _esc_asset == "SOL":
            _esc_floor = SOL_MIN_ENTRY_PRICE
        elif _esc_asset == "XRP":
            _esc_floor = XRP_MIN_ENTRY_PRICE
        if best_ask < _esc_floor or best_ask > ESCALATION_MAX_ENTRY:
            logging.warning(
                f"Escalation aborted: price {best_ask}¢ out of range "
                f"[{_esc_floor}-{ESCALATION_MAX_ENTRY}¢] for {ticker}"
            )
            self._cancel_order(order["asset"], reason)
            self._state.update_evaluated_opportunity_order(ticker, order_outcome="canceled")
            return None

        # Determine urgency tier for logging
        if remaining >= 180:
            tier = "long"
        elif remaining >= 120:
            tier = "medium"
        else:
            tier = "short"

        price_slip = best_ask - order["price_cents"]
        self._logger.log_order({
            "action": "escalate_to_taker",
            "reason": reason,
            "ticker": ticker,
            "maker_price": order["price_cents"],
            "taker_price": best_ask,
            "price_slip": price_slip,
            "wait_time": round(elapsed, 1),
            "urgency_tier": tier,
            "remaining": round(remaining, 1),
            "execution_method": "cancel_replace_ioc",
        })

        # ── Edge recheck at escalated price ──────────────────────────
        # The candidate was evaluated with edge at the maker price. If the
        # taker price is higher, the edge may have evaporated or gone negative.
        # Data: 10 MAKER_PATIENT losses with drift>0 cost $704/2wk.
        _esc_prob = order["candidate"].get("calibrated_prob", 0)
        _esc_fee_1c = calculate_taker_fee(1, best_ask)
        _esc_edge = _esc_prob - best_ask / 100.0 - _esc_fee_1c / 100.0
        _esc_maker_price = order["price_cents"]
        if _esc_edge < 0 and best_ask > _esc_maker_price:
            logging.warning(
                "ESCALATION_EDGE_ABORT: %s prob=%.4f price=%d→%dc edge=%.4f "
                "(negative at escalated price, canceling)",
                ticker, _esc_prob, _esc_maker_price, best_ask, _esc_edge)
            self._cancel_order(order["asset"], "escalation_edge_abort")
            self._state.update_evaluated_opportunity_order(
                ticker, order_outcome="escalation_edge_abort")
            return None

        # Cancel maker + submit taker IOC
        logging.info(
            f"escalation_cancel_replace: {ticker} "
            f"(maker={order['price_cents']}¢ → taker={best_ask}¢ edge={_esc_edge:.4f})")
        cancel_ok = self._cancel_order(order["asset"], reason)
        if not cancel_ok:
            logging.error(f"Cancel failed for {ticker} — NOT submitting taker to prevent double position")
            self._state.update_evaluated_opportunity_order(ticker, order_outcome="canceled")
            return None

        # Build modified candidate with fresh best ask
        candidate = dict(order["candidate"])
        candidate["best_yes_ask"] = best_ask
        candidate["entry_path"] = "escalation_ioc"
        candidate["escalation_type"] = reason
        candidate["maker_price_cents"] = order["price_cents"]
        candidate["maker_wait_seconds"] = round(elapsed, 1)
        filled = order.get("filled_so_far", 0)
        if filled > 0:
            candidate["position_size"] = max(1, candidate["position_size"] - filled)
            logging.info(
                f"escalation_partial_adjust: {ticker} "
                f"original={order['count']} filled={filled} "
                f"ioc_count={candidate['position_size']}")
        self._recent_taker_tickers[ticker] = time.time()

        result = self._submit_taker(candidate)
        if result is not None:
            _esc_oid = result.get("order_id") if isinstance(result, dict) else None
            self._state.update_evaluated_opportunity_order(
                ticker, order_id=_esc_oid, order_outcome="filled")
        else:
            self._state.update_evaluated_opportunity_order(
                ticker, order_outcome="unfilled")
        return result

    # ── DC Taker with Non-Blocking Retry Queue ─────────────────────────

    @staticmethod
    def _dc_retry_delay(seconds_to_close: float) -> float:
        """Adaptive retry delay based on urgency (STC). Shorter near settlement."""
        if seconds_to_close > 600:
            return 20.0
        elif seconds_to_close > 300:
            return 12.0
        elif seconds_to_close > 120:
            return 6.0
        elif seconds_to_close > 30:
            return 3.0
        else:
            return 1.0

    def _rest_best_ask_depth(self, ticker: str) -> Optional[int]:
        """Force-fetch best YES ask depth via REST /orderbook.

        Used as a pre-IOC drift check: the WS cache can diverge from
        Kalshi's real book (see kb/failures/kalshi-ws-schema-drift.md
        § "WS delta underflow"). REST is the ground truth. Returns None
        on any error so caller falls back to cached depth.

        Adds ~30-50ms latency per call. Should only be invoked from IOC
        submit paths where cache claims non-trivial depth — see
        IOC_DRIFT_CHECK_MIN_CACHED_DEPTH.

        Note: callers should prefer `_rest_best_ask_depth_smoothed`
        which records this single sample into the rolling-window
        buffer and returns the peak across recent observations.
        Single REST samples are themselves volatile — see
        WS_DRIFT_PROBE_REST_STABILITY.
        """
        try:
            ob_resp = self._client.get_orderbook(ticker, depth=5)
            if not ob_resp:
                return None
            ob_fp = ob_resp.get("orderbook_fp")
            if ob_fp and self._ml and hasattr(self._ml, 'scanner'):
                fresh_ob = self._ml.scanner._convert_orderbook_fp(ob_fp)
            else:
                fresh_ob = ob_resp.get("orderbook")
            if not fresh_ob:
                return None
            return OrderExecutor._best_ask_depth(fresh_ob)
        except Exception:
            return None

    # Sanity bound for a recorded depth value. Kalshi best-ask
    # depths are typically <50k contracts; rejecting anything past
    # 100k catches realistic schema-drift bugs (e.g., REST returning
    # sum-of-levels rather than top-of-book = ~10–50× inflation).
    # Round 1 P1 + Round 2 [A5] tightening — 1M was too loose to
    # catch any plausible bug class.
    _REST_DEPTH_SAMPLE_MAX = 100_000

    # Minimum samples in the rolling window before the smoothed peak
    # is trusted as the clamp authority. With only 1 sample, the
    # smoothed helper degenerates to single-sample clamping — the
    # exact pre-fix bug. Round 2 [A1] cold-start gate: if the buffer
    # has <2 samples within the window, the drift-check skips the
    # clamp altogether and falls through to the existing policy
    # (cached `_ask_depth` + STRATEGY_CLAMP_POLICY), which is the
    # behavior that worked for months pre-a56ecc7. PHANTOM_ABORT
    # still fires on fresh=0 regardless of cold-start state.
    _REST_DEPTH_MIN_SAMPLES_FOR_CLAMP = 2

    # Threading: `_rest_depth_observations` is read/written ONLY from
    # the main thread (executor's `_submit_taker` and helpers). No
    # WS thread, refresh worker, or engine thread touches it today.
    # If a future engine ever calls into `_submit_taker` from a
    # different thread, wrap the deque ops in a lock — `popleft` is
    # atomic individually but the prune-then-append pattern in
    # `_record_rest_depth_observation` is not. (Round 2 [A3].)

    def _record_rest_depth_observation(self, ticker: str,
                                       depth: int) -> None:
        """Append (monotonic_now, depth) to the per-ticker rolling
        buffer and prune any samples older than
        IOC_DRIFT_CHECK_REST_WINDOW_S. Drops the dict entry entirely
        when the deque becomes empty after prune — bounds memory
        growth across the lifetime of the process (15M markets
        cycle every 15 min × 4 assets = ~16/hr new tickers; without
        cleanup the dict would leak indefinitely).

        Round 1 hardening:
          - `time.monotonic()` (not `time.time()`) — wall-clock NTP
            jumps backwards corrupt window math; the VPS has been
            logging 5–14s clock_drift_detected warnings every 30s.
          - Bounds-check on `depth`: out-of-bound values (negative
            or > _REST_DEPTH_SAMPLE_MAX) are dropped AND a
            once-per-ticker WARNING fires for diagnostics. Round 2
            [A7]: silent drop with no observability would mask a
            schema-drift bug that produced consistently-bad samples."""
        if depth is None or depth < 0 or depth > self._REST_DEPTH_SAMPLE_MAX:
            # Round 2 [A7]: log once per ticker so operators see a
            # signal if schema drift is poisoning the buffer.
            if not hasattr(self, "_rest_depth_drop_logged"):
                self._rest_depth_drop_logged = set()
            if ticker not in self._rest_depth_drop_logged:
                self._rest_depth_drop_logged.add(ticker)
                logging.warning(
                    "REST_DEPTH_SAMPLE_DROPPED: %s depth=%r — out of "
                    "bounds [0, %d]; smoothing buffer not updated. "
                    "Possible schema drift in REST /orderbook.",
                    ticker, depth, self._REST_DEPTH_SAMPLE_MAX)
            return
        now = time.monotonic()
        cutoff = now - IOC_DRIFT_CHECK_REST_WINDOW_S
        buf = self._rest_depth_observations.get(ticker)
        if buf is None:
            buf = deque()
            self._rest_depth_observations[ticker] = buf
        # Prune expired samples from the left.
        while buf and buf[0][0] < cutoff:
            buf.popleft()
        buf.append((now, int(depth)))

    def _rest_depth_window_count(self, ticker: str) -> int:
        """Return the number of unexpired samples in the per-ticker
        buffer. Used as the cold-start gate — when count < 2 the
        smoothed peak is just a rename of the single fresh sample
        and provides no actual smoothing. Round 2 [A1].
        Side-effect-free."""
        now = time.monotonic()
        cutoff = now - IOC_DRIFT_CHECK_REST_WINDOW_S
        buf = self._rest_depth_observations.get(ticker)
        if not buf:
            return 0
        return sum(1 for ts, _ in buf if ts >= cutoff)

    def _rest_depth_window_max(self, ticker: str) -> Optional[int]:
        """Return the peak depth observed for `ticker` within the
        last IOC_DRIFT_CHECK_REST_WINDOW_S seconds, or None if no
        samples are in the window. Pure read — does not record.

        Round 1 hardening: prunes expired samples in-place and
        DELETES the dict entry when its deque becomes empty. This
        bounds memory growth (settled tickers stop sending samples,
        their deque ages out, then this read drops the entry).

        Peak (not mean/median) is the right statistic for this
        clamp because:
          - real phantom WS → REST stays consistently low → peak stays low
          - transient REST noise → some samples high, some low →
            peak preserves the high reading and avoids false-clamp"""
        now = time.monotonic()
        cutoff = now - IOC_DRIFT_CHECK_REST_WINDOW_S
        buf = self._rest_depth_observations.get(ticker)
        if not buf:
            return None
        # Prune expired samples in-place so memory is reclaimed.
        while buf and buf[0][0] < cutoff:
            buf.popleft()
        if not buf:
            # All samples expired — drop the dict entry entirely.
            del self._rest_depth_observations[ticker]
            return None
        return max(d for _, d in buf)

    def _rest_best_ask_depth_smoothed(
            self, ticker: str) -> Tuple[Optional[int], Optional[int]]:
        """REST best-ask depth, smoothed over a rolling window.

        Returns a 2-tuple `(peak, fresh)`:
          - `peak`: max depth observed within
            IOC_DRIFT_CHECK_REST_WINDOW_S, after recording the
            fresh sample. Used as the clamp authority for IOC
            sizing — peak protects against single-sample REST
            volatility (delta_qty=-900 in 1s).
          - `fresh`: the just-fetched REST sample (or None on
            REST error). Required for PHANTOM_ABORT decisions —
            when fresh==0, the book IS empty right now regardless
            of historical peak, so the abort path must check fresh
            independently. Round 1 [P0 #2] regression guard.

        If REST errors, fresh=None and peak falls back to the
        historical buffer (or None if both are absent). The caller
        falls back to cached depth in that case — existing behavior."""
        fresh = self._rest_best_ask_depth(ticker)
        if fresh is not None:
            self._record_rest_depth_observation(ticker, fresh)
        peak = self._rest_depth_window_max(ticker)
        return peak, fresh

    def _dc_get_ask_with_depth(self, ticker: str, candidate: Dict):
        """Get best ask price AND depth for DC execution decisions.

        Returns (price, depth, source) where:
        - price: best YES ask in cents, or None
        - depth: contracts at best ask level, 0 if unknown
        - source: 'orderbook' or 'market_nbbo'
        """
        try:
            scanner = self._ml.scanner if self._ml else None
            if scanner:
                ob_data, _ = scanner._get_orderbook_cached(ticker)
                if ob_data:
                    price = OpportunityScanner._best_yes_ask_cents(ob_data)
                    if price is not None:
                        depth = OpportunityScanner._best_ask_depth(ob_data)
                        return price, depth, "orderbook"
        except Exception:
            pass

        # REST fallback
        try:
            ob_resp = self._client.get_orderbook(ticker, depth=5)
            if ob_resp:
                ob_fp = ob_resp.get("orderbook_fp")
                if ob_fp and self._ml and hasattr(self._ml, 'scanner'):
                    ob_data = self._ml.scanner._convert_orderbook_fp(ob_fp)
                else:
                    ob_data = ob_resp.get("orderbook", ob_resp)
                if ob_data:
                    price = OpportunityScanner._best_yes_ask_cents(ob_data)
                    if price is not None:
                        depth = OpportunityScanner._best_ask_depth(ob_data)
                        return price, depth, "orderbook"
        except Exception:
            pass

        # NBBO fallback
        nbbo_price = self._nbbo_fallback_price(candidate)
        if nbbo_price is not None:
            return nbbo_price, 0, "market_nbbo"

        return None, 0, "none"

    def _execute_dc_taker(self, candidate: Dict, asset: str, seconds_to_close) -> Optional[Dict]:
        """Submit DC IOC. On unfilled/partial, queue non-blocking retry."""
        _dc_strategy = candidate.get("strategy")
        ticker = candidate["ticker"]
        count = candidate["position_size"]
        price = candidate["best_yes_ask"]
        cal_prob = candidate["calibrated_prob"]

        if count <= 0:
            logging.warning("ORDER_SUPPRESSED zero_size: %s asset=%s strategy=%s price=%d",
                            ticker, asset, _dc_strategy, price)
            self._session_suppressed_zero_size += 1
            return None

        taker_fee = calculate_taker_fee(count, price)
        net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

        if net_edge < -0.01:
            logging.warning(
                "ORDER_SUPPRESSED edge_taker_fee: %s asset=%s strategy=%s net_edge=%.4f < -0.01 "
                "price=%d¢ cal_prob=%.4f taker_fee=%d¢",
                ticker, asset, _dc_strategy, net_edge, price, cal_prob, taker_fee)
            self._session_suppressed_edge_recalc += 1
            return None

        # Fresh ask check with depth — verify price, depth, and source
        _dc_scan_price = price  # preserve original scan price for drift check
        fresh_ask, fresh_depth, fresh_source = self._dc_get_ask_with_depth(ticker, candidate)

        if fresh_ask is None:
            logging.warning("ORDER_SUPPRESSED no_asks: %s asset=%s strategy=%s price=%d stc=%.0f",
                            ticker, asset, _dc_strategy, price, seconds_to_close or 0)
            self._session_suppressed_no_asks += 1
            if self._ml and hasattr(self._ml, "scanner"):
                self._ml.scanner._dc_skip_cooldown[ticker] = time.time() + 60
            # Queue retry — book may appear later
            _retry_delay = self._dc_retry_delay(seconds_to_close or 0)
            self._dc_retry_queue.append({
                "candidate": candidate.copy(),
                "original_count": count,
                "total_filled": 0,
                "remaining": count,
                "attempt": 1,
                "next_retry_ts": time.time() + _retry_delay,
                "strategy": _dc_strategy,
                "original_price": _dc_scan_price,
                "_queue_ts": time.time(),
            })
            logging.info("dc_retry_QUEUED: %s %s no_asks attempt=1/%d next_retry=%.0fs",
                         _dc_strategy, ticker, 1 + DC_IOC_MAX_RETRIES, _retry_delay)
            return None

        # Layer 1: Phantom depth flag — LOG ONLY, never block
        # Depth can appear between our check and the IOC hitting the matching engine.
        # Blocking here would kill real fills. Flag for analysis, submit IOC regardless.
        _phantom_depth = (fresh_depth == 0 and fresh_source == "market_nbbo")
        if _phantom_depth:
            logging.info("dc_taker_PHANTOM_FLAG: %s %s fresh_ask=%d¢ depth=0 source=nbbo — submitting anyway",
                         _dc_strategy, ticker, fresh_ask)

        # Price floor gate: refuse if fresh ask dropped below DC qualifying floor
        if fresh_ask < DECIDED_CONTRACT_MIN_PRICE:
            logging.warning("dc_taker_ABORT_PRICE_BELOW_FLOOR: %s fresh_ask=%d¢ < floor=%d¢ (scan=%d¢)",
                            ticker, fresh_ask, DECIDED_CONTRACT_MIN_PRICE, _dc_scan_price)
            return None

        if fresh_ask != price:
            logging.info("dc_taker_price_update: %s scanner=%d¢ fresh=%d¢ depth=%d src=%s",
                         ticker, price, fresh_ask, fresh_depth, fresh_source)
            price = fresh_ask
            candidate["best_yes_ask"] = fresh_ask
            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))
            if net_edge < -0.01:
                logging.info("dc_taker_SKIPPED: %s fresh_ask=%d¢ net_edge=%.4f < -0.01",
                             ticker, price, net_edge)
                return None

        self._session_direct_taker_attempts += 1
        candidate["entry_path"] = "dc_taker"
        candidate["escalation_type"] = "direct_taker"
        self._recent_taker_tickers[ticker] = time.time()

        logging.info(
            "dc_taker_ENTRY: %s %s %dx @ %d¢ "
            "seconds_to_close=%.0f net_edge=%.4f cal_prob=%.4f taker_fee=%d¢ attempt=1/%d",
            _dc_strategy, ticker, count, price,
            seconds_to_close or 0, net_edge, cal_prob, taker_fee, 1 + DC_IOC_MAX_RETRIES)

        _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        result = self._submit_taker(candidate)

        if result is not None:
            fill_count = result.get("filled_count", 0)
            remaining = count - fill_count

            if remaining <= 0:
                # Fully filled on first attempt
                self._session_direct_taker_fills += 1
                logging.info("dc_taker_FILLED: %s %s %d/%d", _dc_strategy, ticker, fill_count, count)
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
                return result

            # Partial fill — queue retry for remaining
            logging.info("dc_taker_PARTIAL: %s %s filled=%d remaining=%d — queuing retry",
                         _dc_strategy, ticker, fill_count, remaining)
            self._dc_retry_queue.append({
                "candidate": candidate.copy(),
                "original_count": count,
                "total_filled": fill_count,
                "remaining": remaining,
                "attempt": 1,
                "next_retry_ts": time.time() + DC_IOC_RETRY_DELAY,
                "strategy": _dc_strategy,
                "original_price": _dc_scan_price,
                "_queue_ts": time.time(),
                "last_order_submit_ts": _order_submit_ts,
                "last_order_id": result.get("order_id"),
            })
            # Return result so the partial fill is tracked
            self._state.update_evaluated_opportunity_order(
                ticker, order_id=result.get("order_id"),
                order_submitted_at=_order_submit_ts, order_outcome="partial_retry")
            return result
        else:
            # Zero fill — queue retry
            self._session_direct_taker_unfilled += 1
            logging.warning("dc_taker_UNFILLED: %s %s — queuing retry", _dc_strategy, ticker)
            self._dc_retry_queue.append({
                "candidate": candidate.copy(),
                "original_count": count,
                "total_filled": 0,
                "remaining": count,
                "attempt": 1,
                "next_retry_ts": time.time() + DC_IOC_RETRY_DELAY,
                "strategy": _dc_strategy,
                "original_price": _dc_scan_price,
                "_queue_ts": time.time(),
                "last_order_submit_ts": _order_submit_ts,
            })
            self._state.update_evaluated_opportunity_order(
                ticker, order_submitted_at=_order_submit_ts,
                order_outcome="unfilled_retry")
            return None

    def _execute_tm_taker(self, candidate: Dict, asset: str, seconds_to_close) -> Optional[Dict]:
        """Execute terminal momentum trade — direct taker, fixed contracts, no retry."""
        ticker = candidate["ticker"]
        count = candidate["position_size"]  # scan-time: tm_compute_contracts(price, stc, balance)
        price = candidate["best_yes_ask"]
        cal_prob = candidate["calibrated_prob"]

        if count <= 0:
            logging.warning("ORDER_SUPPRESSED zero_size: %s asset=%s strategy=terminal_momentum price=%d",
                            ticker, asset, price)
            self._session_suppressed_zero_size += 1
            return None

        taker_fee = calculate_taker_fee(count, price)
        net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

        # Fresh ask check — verify price hasn't moved outside TM_PRICE_SET
        _tm_scan_price = price
        fresh_ask, fresh_depth, fresh_source = self._dc_get_ask_with_depth(ticker, candidate)

        if fresh_ask is None:
            logging.warning("ORDER_SUPPRESSED no_asks: %s asset=%s strategy=terminal_momentum price=%d stc=%.0f",
                            ticker, asset, price, seconds_to_close or 0)
            self._session_suppressed_no_asks += 1
            return None

        if fresh_ask not in TM_PRICE_SET:
            logging.info("tm_taker_SKIP_PRICE: %s fresh_ask=%d¢ not in TM_PRICE_SET (scan=%d¢)",
                         ticker, fresh_ask, _tm_scan_price)
            return None

        if fresh_ask != price:
            logging.info("tm_taker_price_update: %s scanner=%d¢ fresh=%d¢ depth=%d src=%s",
                         ticker, price, fresh_ask, fresh_depth, fresh_source)
            price = fresh_ask
            candidate["best_yes_ask"] = fresh_ask
            # Re-derive sizing from execution-time price (scan price may have drifted)
            _exec_bal = candidate.get("balance_at_scan") or 100000
            _exec_buf_pct = candidate.get("spot_buffer_pct")
            # Adversary A6: sweep-aware risk cap — sizing against worst-case
            # fill price keeps cents-at-risk within the per-asset cap.
            _exec_risk_price = MAX_ENTRY_PRICE if TM_SWEEP_LIVE_ENABLED else None
            count = tm_compute_contracts(fresh_ask, seconds_to_close or 200,
                                         _exec_bal, asset,
                                         buf_pct=_exec_buf_pct,
                                         risk_cap_price=_exec_risk_price)
            candidate["position_size"] = count
            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

        # Race condition guard: check position at this price level
        _tm_exec_group = f"terminal_momentum_{price}"
        if STACKING_ENABLED:
            from models import strategy_to_group
            if any(p.get("ticker") == ticker
                   and p.get("strategy_group", strategy_to_group(p.get("strategy", "")))
                       == _tm_exec_group
                   for p in self._state.get_open_positions()):
                logging.info("tm_taker_SKIP_POSITION: %s already held at %dc by TM", ticker, price)
                return None
        else:
            if any(p.get("ticker") == ticker for p in self._state.get_open_positions()):
                logging.info("tm_taker_SKIP_POSITION: %s already held", ticker)
                return None

        self._session_direct_taker_attempts += 1
        candidate["entry_path"] = "tm_taker"
        candidate["escalation_type"] = "direct_taker"
        self._recent_taker_tickers[ticker] = time.time()

        logging.info(
            "tm_taker_ENTRY: %s %dx @ %d¢ "
            "seconds_to_close=%.0f net_edge=%.4f cal_prob=%.4f taker_fee=%d¢",
            ticker, count, price,
            seconds_to_close or 0, net_edge, cal_prob, taker_fee)

        # tm_sweep_shadow: snapshot pre-fill depths at all four TM-relevant
        # tiers BEFORE the IOC. Wrapped to never break the trade path.
        _tmss_pre = self._tm_sweep_snapshot_depths(ticker) if TM_SWEEP_SHADOW_ENABLED else None

        _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        result = self._submit_taker(candidate)

        # tm_sweep_shadow: snapshot post-fill depths immediately (option A —
        # models what a real sweep would see firing right after the IOC ack).
        # Insert one row regardless of fill outcome (full/partial/zero).
        #
        # Post-fill depth at the entry tier is RACY: we don't know whether the
        # WS delta from our own fill has landed in the local cache yet (adversary
        # A1). Storing raw is safer than guessing — over- or under-correcting at
        # random is worse than a documented bias. cf_pnl is unaffected because
        # it only consults sweep tiers (98/99), and a single-price IOC at the
        # entry tier cannot consume from higher tiers.
        if TM_SWEEP_SHADOW_ENABLED:
            try:
                _tmss_post = self._tm_sweep_snapshot_depths(ticker)
                # Adversary A2: clamp filled_count to non-negative int so
                # neither None (error sentinel) nor a future negative sentinel
                # corrupts unfilled_count.
                _tmss_raw = result.get("filled_count") if isinstance(result, dict) else 0
                _tmss_filled = max(0, int(_tmss_raw or 0))
                # Adversary R3 A1: read direct-bump status from candidate
                # (set by _submit_taker after its gate ran). Single source
                # of truth — eliminates the predicate-duplication that R2
                # A1 caught (capture over-reporting when picker happens to
                # fire and bump).
                _direct_bump = int(bool(candidate.get("_tm_direct_bump_fired", False)))
                self._state.insert_tm_sweep_shadow_row(
                    ticker=ticker,
                    event_ticker=candidate.get("event_ticker", ""),
                    asset=asset,
                    entry_time=_order_submit_ts,
                    entry_price_cents=int(price),
                    requested_count=int(count),
                    filled_count=_tmss_filled,
                    unfilled_count=int(count) - _tmss_filled,
                    depth_at_entry_pre_fill=fresh_depth,
                    depth_96c_pre=(_tmss_pre or {}).get(96),
                    depth_97c_pre=(_tmss_pre or {}).get(97),
                    depth_98c_pre=(_tmss_pre or {}).get(98),
                    depth_99c_pre=(_tmss_pre or {}).get(99),
                    depth_96c_post=(_tmss_post or {}).get(96),
                    depth_97c_post=(_tmss_post or {}).get(97),
                    depth_98c_post=(_tmss_post or {}).get(98),
                    depth_99c_post=(_tmss_post or {}).get(99),
                    seconds_to_close=seconds_to_close,
                    calibrated_prob=cal_prob,
                    buf_pct=candidate.get("spot_buffer_pct"),
                    best_ask_source=fresh_source,
                    direct_bump_applied=_direct_bump)
            except Exception:
                logging.debug("tm_sweep_shadow capture failed", exc_info=True)

        if result is not None:
            fill_count = result.get("filled_count", 0)
            if fill_count > 0:
                self._session_direct_taker_fills += 1
                logging.info("tm_taker_FILLED: %s %d/%d @ %d¢", ticker, fill_count, count, price)
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
                # Telegram alert
                try:
                    _TELEGRAM.send(
                        f"TM: {asset} {fill_count}ct @ {price}c "
                        f"prob={cal_prob:.1%} stc={seconds_to_close or 0:.0f}s "
                        f"edge={net_edge:.2%}",
                        dedup_key=f"tm_{ticker}")
                except Exception:
                    logging.debug("TM telegram alert failed", exc_info=True)
                return result
            else:
                # Zero fill — no retry for TM (next scan cycle will re-evaluate)
                self._session_direct_taker_unfilled += 1
                logging.info("tm_taker_UNFILLED: %s @ %d¢ depth=%d", ticker, price, fresh_depth)
                self._state.update_evaluated_opportunity_order(
                    ticker, order_submitted_at=_order_submit_ts,
                    order_outcome="unfilled")
                return None
        return None

    def _tm_sweep_snapshot_depths(self, ticker: str) -> Optional[Dict[int, int]]:
        """Snapshot YES-ask depths at TM_SWEEP_CAPTURE_TIERS from the scanner's
        cached orderbook. Returns None on any error (caller treats as unknown).
        Never raises — instrumentation must not break the trade path."""
        try:
            scanner = self._ml.scanner if self._ml else None
            if not scanner:
                return None
            ob_data, _ = scanner._get_orderbook_cached(ticker)
            if not ob_data:
                return None
            ladder_json = OrderExecutor._extract_book_levels(ob_data, n=10)
            if not ladder_json:
                return None
            yes_asks = json.loads(ladder_json).get("yes_asks", [])
            return tm_sweep_extract_depths(yes_asks, TM_SWEEP_CAPTURE_TIERS)
        except Exception:
            return None

    def _execute_lpne_taker(self, candidate: Dict, asset: str, seconds_to_close) -> Optional[Dict]:
        """Execute low-price near-expiry trade — direct taker, fixed contracts, no retry.
        BTC 80-87c at STC<=120s. Mirrors _execute_tm_taker with LPNE constants."""
        ticker = candidate["ticker"]
        count = candidate["position_size"]  # LPNE_FIXED_CONTRACTS
        price = candidate["best_yes_ask"]
        cal_prob = candidate["calibrated_prob"]

        if count <= 0:
            logging.warning("ORDER_SUPPRESSED zero_size: %s asset=%s strategy=low_price_near_expiry price=%d",
                            ticker, asset, price)
            self._session_suppressed_zero_size += 1
            return None

        taker_fee = calculate_taker_fee(count, price)
        net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

        # Fresh ask check — verify price hasn't moved outside LPNE range
        _lpne_scan_price = price
        fresh_ask, fresh_depth, fresh_source = self._dc_get_ask_with_depth(ticker, candidate)

        if fresh_ask is None:
            logging.warning("ORDER_SUPPRESSED no_asks: %s asset=%s strategy=low_price_near_expiry price=%d stc=%.0f",
                            ticker, asset, price, seconds_to_close or 0)
            self._session_suppressed_no_asks += 1
            return None

        if not (LPNE_MIN_PRICE <= fresh_ask <= LPNE_MAX_PRICE):
            logging.info("lpne_taker_SKIP_PRICE: %s fresh_ask=%d¢ outside LPNE range %d-%d (scan=%d¢)",
                         ticker, fresh_ask, LPNE_MIN_PRICE, LPNE_MAX_PRICE, _lpne_scan_price)
            return None

        if fresh_ask != price:
            logging.info("lpne_taker_price_update: %s scanner=%d¢ fresh=%d¢ depth=%d src=%s",
                         ticker, price, fresh_ask, fresh_depth, fresh_source)
            price = fresh_ask
            candidate["best_yes_ask"] = fresh_ask
            candidate["position_size"] = LPNE_FIXED_CONTRACTS  # no per-price overrides for LPNE
            count = LPNE_FIXED_CONTRACTS
            taker_fee = calculate_taker_fee(count, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (count * 100.0))

        # Race condition guard: check position one more time
        if any(p.get("ticker") == ticker for p in self._state.get_open_positions()):
            logging.info("lpne_taker_SKIP_POSITION: %s already held", ticker)
            return None

        self._session_direct_taker_attempts += 1
        candidate["entry_path"] = "lpne_taker"
        candidate["escalation_type"] = "direct_taker"
        self._recent_taker_tickers[ticker] = time.time()

        logging.info(
            "lpne_taker_ENTRY: %s %dx @ %d¢ "
            "seconds_to_close=%.0f net_edge=%.4f cal_prob=%.4f taker_fee=%d¢",
            ticker, count, price,
            seconds_to_close or 0, net_edge, cal_prob, taker_fee)

        _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        result = self._submit_taker(candidate)

        if result is not None:
            fill_count = result.get("filled_count", 0)
            if fill_count > 0:
                self._session_direct_taker_fills += 1
                logging.info("lpne_taker_FILLED: %s %d/%d @ %d¢", ticker, fill_count, count, price)
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
                try:
                    _TELEGRAM.send(
                        f"LPNE: {asset} {fill_count}ct @ {price}c "
                        f"prob={cal_prob:.1%} stc={seconds_to_close or 0:.0f}s "
                        f"edge={net_edge:.2%}",
                        dedup_key=f"lpne_{ticker}")
                except Exception:
                    logging.debug("LPNE telegram alert failed", exc_info=True)
                return result
            else:
                self._session_direct_taker_unfilled += 1
                logging.info("lpne_taker_UNFILLED: %s @ %d¢ depth=%d", ticker, price, fresh_depth)
                self._state.update_evaluated_opportunity_order(
                    ticker, order_submitted_at=_order_submit_ts,
                    order_outcome="unfilled")
                return None
        return None

    def _execute_bracket_no_taker(self, candidate: Dict, asset: str, seconds_to_close) -> Optional[Dict]:
        """Execute bracket NO trade — buy NO via IOC taker at computed price."""
        ticker = candidate["ticker"]
        count = candidate["position_size"]  # BRACKET_NO_FIXED_CONTRACTS (5)
        no_cost = candidate["best_yes_ask"]  # NO cost in cents (100 - yes_ask)
        yes_price = candidate.get("_bracket_yes_price", 100 - no_cost)

        if count <= 0:
            logging.warning("ORDER_SUPPRESSED zero_size: %s asset=%s strategy=bracket_no no_cost=%d",
                            ticker, asset, no_cost)
            self._session_suppressed_zero_size += 1
            return None

        # Fresh price check: get current YES ask and re-derive NO cost
        fresh_ask = self._get_addon_best_ask(ticker)
        if fresh_ask is None:
            fresh_ask = self._nbbo_fallback_price(candidate)
        if fresh_ask is not None:
            _fresh_no_cost = 100 - fresh_ask
            if _fresh_no_cost <= 0 or fresh_ask < BRACKET_NO_YES_MIN or fresh_ask > BRACKET_NO_YES_MAX:
                logging.info("bracket_no_SKIP_PRICE: %s fresh_yes=%dc (outside %d-%dc range)",
                             ticker, fresh_ask, BRACKET_NO_YES_MIN, BRACKET_NO_YES_MAX)
                return None
            if _fresh_no_cost != no_cost:
                logging.info("bracket_no_price_update: %s no_cost %dc→%dc (yes %dc→%dc)",
                             ticker, no_cost, _fresh_no_cost, yes_price, fresh_ask)
                no_cost = _fresh_no_cost
                candidate["best_yes_ask"] = no_cost  # Update for _submit_taker
                yes_price = fresh_ask

        # Ceiling check: NO cost must be ≤ 15c (generous margin above 4-12c target)
        if no_cost > 15:
            logging.info("bracket_no_SKIP_EXPENSIVE: %s no_cost=%dc > 15c", ticker, no_cost)
            return None

        # Race condition guard: check position one more time
        if any(p.get("ticker") == ticker for p in self._state.get_open_positions()):
            logging.info("bracket_no_SKIP_POSITION: %s already held", ticker)
            return None

        taker_fee = calculate_taker_fee(count, no_cost)
        net_edge = BRACKET_NO_ASSUMED_PROB - no_cost / 100.0 - taker_fee / (count * 100.0)

        self._session_direct_taker_attempts += 1
        candidate["entry_path"] = "bracket_no_taker"
        candidate["escalation_type"] = "direct_taker"
        self._recent_taker_tickers[ticker] = time.time()

        logging.info(
            "bracket_no_ENTRY: %s %dct NO @ %dc (YES=%dc) "
            "stc=%.0fs edge=%.2f%% assumed_prob=%.0f%% fee=%dc",
            ticker, count, no_cost, yes_price,
            seconds_to_close or 0, net_edge * 100,
            BRACKET_NO_ASSUMED_PROB * 100, taker_fee)

        _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        result = self._submit_taker(candidate)

        if result is not None:
            fill_count = result.get("filled_count", 0)
            if fill_count > 0:
                self._session_direct_taker_fills += 1
                logging.info("bracket_no_FILLED: %s %d/%d NO @ %dc (YES=%dc)",
                             ticker, fill_count, count, no_cost, yes_price)
                _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                self._state.update_evaluated_opportunity_order(
                    ticker, order_id=_taker_oid,
                    order_submitted_at=_order_submit_ts, order_outcome="filled")
                try:
                    _TELEGRAM.send(
                        f"BKT_NO: {ticker} {fill_count}ct NO @ {no_cost}c "
                        f"(YES@{yes_price}c) stc={seconds_to_close or 0:.0f}s",
                        dedup_key=f"bn_{ticker}")
                except Exception:
                    logging.debug("bracket_no telegram alert failed", exc_info=True)
                return result
            else:
                self._session_direct_taker_unfilled += 1
                logging.info("bracket_no_UNFILLED: %s NO @ %dc", ticker, no_cost)
                self._state.update_evaluated_opportunity_order(
                    ticker, order_submitted_at=_order_submit_ts, order_outcome="unfilled")
                return None
        return None

    def process_dc_retries(self):
        """Process queued DC IOC retries. Called at the top of each _tick().

        Non-blocking: each retry is a single IOC submission (<1s).
        Retries are spaced by DC_IOC_RETRY_DELAY (8s) via next_retry_ts.
        """
        if not self._dc_retry_queue:
            return

        now = time.time()
        still_pending = []

        for entry in self._dc_retry_queue:
            if now < entry["next_retry_ts"]:
                still_pending.append(entry)
                continue

            candidate = entry["candidate"]
            ticker = candidate["ticker"]
            _dc_strategy = entry["strategy"]
            attempt = entry["attempt"] + 1
            remaining = entry["remaining"]

            if attempt > 1 + DC_IOC_MAX_RETRIES:
                # Max retries exhausted
                if entry["total_filled"] > 0:
                    logging.info("dc_retry_DONE: %s %s partial_filled=%d/%d after %d attempts",
                                 _dc_strategy, ticker, entry["total_filled"],
                                 entry["original_count"], attempt - 1)
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="partial_filled")
                else:
                    logging.warning("dc_retry_DONE: %s %s unfilled after %d attempts",
                                    _dc_strategy, ticker, attempt - 1)
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="unfilled")
                continue

            # Fresh ask check with depth
            fresh_ask, fresh_depth, fresh_source = self._dc_get_ask_with_depth(ticker, candidate)
            # Coerce None / non-numeric → 0. dict.get only fills default
            # for MISSING key; an explicit None value still passes
            # through, and a JSON-parse string would crash later
            # comparisons. Pre-fix crash: `_dc_retry_delay(None)` raised
            # TypeError on `None > 600`.
            try:
                _stc_now = float(candidate.get("seconds_to_close") or 0)
            except (TypeError, ValueError):
                _stc_now = 0.0
            # Estimate current STC from original eval time
            # _queue_ts is set at every production append site (lines
            # 18833, 18905, 18927). Fallback `now - DC_IOC_RETRY_DELAY`
            # biases toward decay when missing (vs the previous `now`
            # default which kept _eval_age=0 → STC stuck at original
            # → entry could retry forever on a malformed entry). R1 [A5].
            _eval_age = now - entry.get(
                "_queue_ts", now - DC_IOC_RETRY_DELAY)
            if _stc_now and _stc_now > 0:
                _stc_now = max(0, _stc_now - _eval_age)
            _adaptive_delay = self._dc_retry_delay(_stc_now)

            # Apr 26 11:15 incident
            # (kb/failures/dc-retry-post-settlement-burn-2026-04-26.md):
            # candidate fired with STC=5s, hit IOC_ABORT_PHANTOM, queued
            # retry. Retries continued AFTER the 11:15 window close at
            # 1s adaptive delay (=1.0 when STC<30), each hitting
            # phantom + ABORT, burning scan-tick budget across all 11
            # attempts. Once the window has settled, no IOC will fill —
            # drop the entry and stop wasting scan-tick time.
            #
            # Guard: only drop if STC was ORIGINALLY positive AND has
            # decayed to ≤ 0. If `seconds_to_close` was missing or 0
            # at queue time, we cannot bound elapsed → we must NOT
            # drop on STC alone, because the queue's stated purpose
            # (line 18822: "book may appear later") is incompatible
            # with STC-based dropping when STC was never positive to
            # begin with. R1 [A1].
            try:
                _orig_stc = float(
                    candidate.get("seconds_to_close") or 0)
            except (TypeError, ValueError):
                _orig_stc = 0.0
            if _orig_stc > 0 and _stc_now <= 0:
                logging.info(
                    "dc_retry_DROP_WINDOW_CLOSED: %s %s "
                    "orig_stc=%.1fs eval_age=%.1fs (window settled); "
                    "dropping after %d attempts, total_filled=%d/%d",
                    _dc_strategy, ticker, _orig_stc, _eval_age,
                    attempt - 1,
                    entry["total_filled"], entry["original_count"])
                if entry["total_filled"] > 0:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="partial_filled")
                else:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="unfilled_window_closed")
                continue  # drop from queue

            if fresh_ask is None:
                logging.info("dc_retry_no_asks: %s %s attempt=%d/%d",
                             _dc_strategy, ticker, attempt, 1 + DC_IOC_MAX_RETRIES)
                entry["attempt"] = attempt
                entry["next_retry_ts"] = now + _adaptive_delay
                still_pending.append(entry)
                continue

            # Layer 1: Phantom depth flag — LOG ONLY, submit IOC regardless
            _phantom_depth = (fresh_depth == 0 and fresh_source == "market_nbbo")
            if _phantom_depth:
                logging.info("dc_retry_PHANTOM_FLAG: %s %s attempt=%d/%d depth=0 nbbo — submitting anyway",
                             _dc_strategy, ticker, attempt, 1 + DC_IOC_MAX_RETRIES)

            # Price floor gate: abort if ask dropped below DC qualifying floor
            if fresh_ask < DECIDED_CONTRACT_MIN_PRICE:
                _orig_p = entry.get("original_price", 0)
                logging.warning(
                    "dc_retry_ABORT_PRICE_COLLAPSED: %s %s fresh_ask=%d¢ < floor=%d¢ "
                    "(original=%d¢) — dropping from retry queue",
                    _dc_strategy, ticker, fresh_ask, DECIDED_CONTRACT_MIN_PRICE, _orig_p)
                if entry["total_filled"] > 0:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="partial_filled")
                else:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="unfilled_price_collapsed")
                continue  # Drop from queue

            # Price drift gate: abort if ask dropped 3c+ from original signal price
            _orig_price = entry.get("original_price", fresh_ask)
            if fresh_ask < (_orig_price - 3):
                logging.warning(
                    "dc_retry_ABORT_PRICE_DRIFT: %s %s fresh_ask=%d¢ original=%d¢ "
                    "(drift=%d¢) — dropping from retry queue",
                    _dc_strategy, ticker, fresh_ask, _orig_price, _orig_price - fresh_ask)
                if entry["total_filled"] > 0:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="partial_filled")
                else:
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_outcome="unfilled_price_drift")
                continue  # Drop from queue

            # Layer 5: Price tolerance escalation on later retries
            # Retries 0-2: exact price. Retry 3+: widen by 1c per retry, max 3c.
            _retry_num = attempt - 1  # 0-indexed retry count (attempt 2 = retry 1)
            _price_offset = 0
            if _retry_num >= DC_PRICE_TOLERANCE_START_RETRY:
                _price_offset = min(_retry_num - DC_PRICE_TOLERANCE_START_RETRY + 1,
                                    DC_PRICE_TOLERANCE_MAX)

            price = min(fresh_ask + _price_offset, MAX_ENTRY_PRICE)
            candidate["best_yes_ask"] = price
            candidate["position_size"] = remaining
            cal_prob = candidate["calibrated_prob"]

            taker_fee = calculate_taker_fee(remaining, price)
            net_edge = cal_prob - (price / 100.0) - (taker_fee / (remaining * 100.0))
            if net_edge < -0.01:
                logging.info("dc_retry_SKIPPED: %s %s price=%d¢ (ask=%d+%d) net_edge=%.4f attempt=%d",
                             _dc_strategy, ticker, price, fresh_ask, _price_offset, net_edge, attempt)
                continue  # Drop from queue

            self._session_dc_retries += 1
            self._session_direct_taker_attempts += 1
            self._recent_taker_tickers[ticker] = now

            _offset_label = f" (+{_price_offset}c)" if _price_offset > 0 else ""
            logging.info(
                "dc_retry_ENTRY: %s %s %dx @ %d¢%s attempt=%d/%d total_filled=%d/%d depth=%d src=%s",
                _dc_strategy, ticker, remaining, price, _offset_label,
                attempt, 1 + DC_IOC_MAX_RETRIES,
                entry["total_filled"], entry["original_count"],
                fresh_depth, fresh_source)

            _order_submit_ts = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
            result = self._submit_taker(candidate)

            if result is not None:
                fill_count = result.get("filled_count", 0)
                entry["total_filled"] += fill_count
                entry["remaining"] -= fill_count
                self._session_dc_retry_fills += 1

                logging.info("dc_retry_FILL: %s %s filled=%d total=%d/%d remaining=%d attempt=%d",
                             _dc_strategy, ticker, fill_count, entry["total_filled"],
                             entry["original_count"], entry["remaining"], attempt)

                if entry["remaining"] <= 0:
                    # Fully filled across retries
                    self._session_direct_taker_fills += 1
                    _taker_oid = result.get("order_id") if isinstance(result, dict) else None
                    self._state.update_evaluated_opportunity_order(
                        ticker, order_id=_taker_oid,
                        order_submitted_at=_order_submit_ts, order_outcome="filled")
                    continue  # Done — don't re-queue

                # Still more remaining — queue another retry
                entry["attempt"] = attempt
                entry["next_retry_ts"] = now + _adaptive_delay
                entry["last_order_submit_ts"] = _order_submit_ts
                entry["last_order_id"] = result.get("order_id")
                still_pending.append(entry)
            else:
                # Zero fill on retry — queue again
                logging.info("dc_retry_UNFILLED: %s %s attempt=%d/%d",
                             _dc_strategy, ticker, attempt, 1 + DC_IOC_MAX_RETRIES)
                entry["attempt"] = attempt
                entry["next_retry_ts"] = now + _adaptive_delay
                entry["last_order_submit_ts"] = _order_submit_ts
                still_pending.append(entry)

        self._dc_retry_queue = still_pending

    # ── Maker ─────────────────────────────────────────────────────────────

    # Hourly series prefixes — maker orders must NEVER be placed on these tickers.
    _HOURLY_SERIES_PREFIXES = ("KXBTCD-", "KXETHD-", "KXSOLD-", "KXXRPD-")

    def _submit_maker(self, candidate: Dict, aggressive: bool = False, degraded: bool = False):
        """Submit maker limit order below fair value.

        Patient: 1-2¢ below fair value (wider spread).
        Aggressive: always 1¢ below (tighter, more likely to fill).
        Degraded: extra offset after post_only rejections (Tier 2).
        """
        ticker = candidate["ticker"]
        # Settlement-race gate — see MIN_ORDER_SUBMIT_STC_S.
        if self._should_skip_near_close(candidate):
            self._abort_near_close(candidate, path="maker")
            return
        # Block maker orders on hourly tickers — hourly must be taker-only (IOC).
        # Belt-and-suspenders: catches any code path that reaches maker with an hourly ticker.
        if any(ticker.startswith(p) for p in self._HOURLY_SERIES_PREFIXES):
            logging.warning("maker_blocked_hourly_ticker: %s — hourly tickers must use IOC only", ticker)
            return
        count = candidate["position_size"]
        fair_value = candidate["best_yes_ask"]
        balance = candidate["balance_at_scan"]

        if aggressive:
            offset = MAKER_PRICE_OFFSET  # always 1¢
        else:
            # 1¢ offset for prices ≥ 90¢, else 2¢
            offset = MAKER_PRICE_OFFSET if fair_value >= 90 else MAKER_PRICE_OFFSET + 1
        price = fair_value - offset
        if degraded:
            price -= POST_ONLY_DEGRADED_EXTRA_OFFSET
        # Per-asset price floor (mirrors scanner check at ~L6560)
        _pt = candidate.get("product_type")
        _asset = candidate.get("asset")
        _mcfg_exec = get_market_config(_pt)
        _floor = _mcfg_exec.min_entry_price
        if _pt in (None, "15m"):
            if _asset == "BTC":
                _floor = BTC_MIN_ENTRY_PRICE
            elif _asset == "ETH":
                _floor = ETH_MIN_ENTRY_PRICE
            elif _asset == "SOL":
                _floor = SOL_MIN_ENTRY_PRICE
            elif _asset == "XRP":
                _floor = XRP_MIN_ENTRY_PRICE
        if price < _floor:
            logging.warning("Maker price %dc below %s floor %dc for %s — skipping",
                            price, _asset, _floor, ticker)
            return

        client_oid = str(uuid.uuid4())

        # Persist before submission
        _side = candidate.get("side", "yes")
        self._state.insert_bot_order(
            client_oid, ticker, candidate["event_ticker"],
            candidate["asset"], _side, count, price, False
        )

        # Submit with post_only to guarantee maker fees (4x cheaper)
        _price_kwarg = {"no_price": price} if _side == "no" else {"yes_price": price}
        resp = self._client.place_order(
            ticker=ticker, side=_side, action="buy",
            count=count, client_order_id=client_oid,
            post_only=True, **_price_kwarg,
        )

        if resp is None:
            self._state.mark_order_status(client_oid, "api_error")
            self._record_post_only_rejection(ticker)
            # Increment per-ticker api error counter (prevents hot retry loops)
            self._ticker_api_errors[ticker] = self._ticker_api_errors.get(ticker, 0) + 1
            rej_count = self._get_post_only_rejection_count(ticker)
            tier = "degraded" if degraded else "normal"
            logging.warning(
                "Maker order rejected (post_only): %s price=%d¢ tier=%s "
                "rej_count=%d/%d api_errors=%d fair=%d¢",
                ticker, price, tier, rej_count,
                POST_ONLY_MAX_SAME_PRICE + 1,
                self._ticker_api_errors[ticker], fair_value)
            self._session_post_only_rejections += 1
            return

        # Successful submission — reset api error counter for this ticker
        self._ticker_api_errors.pop(ticker, None)
        order_id = (resp.get("order") or {}).get("order_id", client_oid)
        self._state.confirm_order_submitted(client_oid, order_id)
        if self._ml:
            self._ml._session_maker_submissions += 1

        _now = time.time()
        order = {
            "order_id": order_id,
            "client_order_id": client_oid,
            "ticker": ticker,
            "event_ticker": candidate["event_ticker"],
            "asset": candidate["asset"],
            "side": _side,
            "price_cents": price,
            "count": count,
            "is_taker": False,
            "submit_time": _now,
            "seconds_to_close_at_submit": candidate["seconds_to_close"],
            "candidate": candidate,
            "balance_at_entry": balance,
            "entry_path": "maker",
            "_last_poll": _now,
            "_ask_history": deque(maxlen=30),
            "_last_queue_poll": 0.0,
        }
        self._active_orders[candidate["asset"]] = order

        # Clear rejection tracker on successful maker submission
        self._post_only_rejections.pop(ticker, None)

        self._logger.log_order({
            "action": "maker_submitted",
            "ticker": ticker,
            "order_id": order_id,
            "client_order_id": client_oid,
            "price_cents": price,
            "count": count,
            "fair_value": fair_value,
        })
        tier = "degraded" if degraded else ("aggressive" if aggressive else "patient")
        logging.info(
            f"Maker order: {ticker} {count}x @ {price}¢ "
            f"(fair={fair_value}¢, tier={tier})"
        )

    # ── Taker ─────────────────────────────────────────────────────────────

    def _submit_taker(self, candidate: Dict) -> Optional[Dict]:
        """Submit taker order at best ask. Blocks briefly to verify fill."""
        ticker = candidate["ticker"]
        # Settlement-race gate — see MIN_ORDER_SUBMIT_STC_S.
        if self._should_skip_near_close(candidate):
            self._abort_near_close(candidate, path="taker")
            return None
        count = candidate["position_size"]
        price = candidate["best_yes_ask"]
        balance = candidate["balance_at_scan"]
        # Ladder retries: avoid double-counting session-level IOC
        # metrics. The retry IS a new IOC submission to Kalshi, but
        # for SIGNAL-level metrics it's the same trading signal as
        # the parent. Mirrors the existing 'confirmation_addon'
        # exclusion pattern.
        _is_ladder_retry = bool(candidate.get("_is_ladder_retry"))

        # ── Smart IOC limit picker (Apr 25 2026) ──────────────────────────
        # Kalshi's matching engine fills against ALL ask levels at-or-below
        # our IOC limit. Pre-Apr 23 the bot used NBBO yes_ask (typically
        # wider than orderbook best_ask) — IOCs swept multiple levels and
        # filled 64-82ct on average. The 0ddcaf8 schema fix (Apr 23) made
        # the bot use orderbook best_ask exactly, dropping fills to 33ct
        # because liquidity sat 1-3c above our limit.
        #
        # The picker walks the visible orderbook from best_yes_ask upward,
        # finds the smallest limit price where cumulative fillable depth
        # ≥ position_size. Hard caps:
        #   - max_bump = IOC_LIMIT_MAX_BUMP_CENTS (3c default)
        #   - edge_ceiling = floor(prob*100) - fee_1c - reserve_cents
        #     (per-strategy reserve; default 0 = break-even after fee)
        #   - max_price = MAX_ENTRY_PRICE (99)
        # If picker can't fetch the live orderbook (no scanner ref / WS
        # cache empty), or the ticker is currently WS-drift-flagged
        # (cache untrusted), falls through to original `price` — no
        # regression on broken-cache paths.
        # The bumped limit is computed into `_ioc_limit_price` and used
        # ONLY for the place_order call below. We do NOT mutate
        # candidate["best_yes_ask"] — that stays at the scan-time value
        # for downstream telemetry/audit/post-fill analysis.
        _ioc_limit_price = price  # default to original
        # Hoist _bump_strategy so the TM_SWEEP_DIRECT_BUMP branch below
        # can reference it even when the picker block doesn't enter
        # (orderbook unavailable — the exact case the direct-bump fixes).
        _bump_strategy = candidate.get("strategy") or ""
        # Round 2 [P0-A]: picker is YES-side only. For NO-side
        # candidates (bracket_no, hourly_no_live, weather_no_live,
        # dc_shadow_no_side), `candidate["best_yes_ask"]` is set
        # to no_price — feeding it to the YES-side ladder walker
        # produces meaningless results and the bumped price gets
        # submitted as no_price, potentially overpaying. Bypass.
        _is_no_side = candidate.get("side") == "no"
        try:
            _scanner = self._ml.scanner if self._ml else None
            _live_ob = None
            # Bypass picker on drift-flagged tickers — the WS cache
            # the picker reads is the same one that's been wrong
            # (WS_DRIFT_AUTO_FLAG). Don't bump based on phantom data.
            _is_drift_flagged = (
                _scanner is not None
                and ticker in getattr(_scanner, "_ws_drift_cooldown", {}))
            if (_scanner is not None
                    and not _is_drift_flagged
                    and not _is_no_side):
                try:
                    _live_ob, _src = _scanner._get_orderbook_cached(ticker)
                except Exception:
                    _live_ob = None
            if _live_ob and isinstance(price, int) and price > 0:
                _cal_prob = candidate.get("calibrated_prob")
                if _cal_prob is not None and 0 < _cal_prob < 1:
                    _fee_1c = calculate_taker_fee(1, price)
                    # Per-strategy edge reserve — see
                    # STRATEGY_LIMIT_BUMP_RESERVE_CENTS in bot/_impl.py
                    # constants. Default (B) is 0 (break-even after
                    # fee). High-conviction strategies (DC tiers,
                    # addons) override to -1 (tolerate fee-cost on
                    # worst-fill margin).
                    # _bump_strategy hoisted above (used by the TM direct-bump
                    # branch outside this picker block).
                    _reserve_cents = STRATEGY_LIMIT_BUMP_RESERVE_CENTS.get(
                        _bump_strategy,
                        STRATEGY_LIMIT_BUMP_DEFAULT_RESERVE)
                    _edge_ceiling = (
                        int(_cal_prob * 100) - _fee_1c - _reserve_cents)
                    # TM Sweep Live: override edge_ceiling for the exact
                    # terminal_momentum tiers in TM_LIVE_STRATEGIES so the
                    # picker can bump up to MAX_ENTRY_PRICE (99c).
                    #
                    # Ladder-retry guard (adversary A4): the override does
                    # NOT apply on _is_ladder_retry candidates. The ladder
                    # escalation already does limit+1; compounding it with
                    # a fresh smart-picker bump is untested and could
                    # produce IOCs at price levels neither path validated.
                    if (TM_SWEEP_LIVE_ENABLED
                            and _bump_strategy in TM_LIVE_STRATEGIES
                            and not _is_ladder_retry):
                        _edge_ceiling = MAX_ENTRY_PRICE
                    _smart_limit = OrderExecutor._pick_ioc_limit_for_depth(
                        _live_ob,
                        best_yes_ask=int(price),
                        target_qty=int(count),
                        max_bump_cents=IOC_LIMIT_MAX_BUMP_CENTS,
                        edge_ceiling_price=_edge_ceiling,
                        max_price=MAX_ENTRY_PRICE,
                    )
                    if _smart_limit > price:
                        logging.info(
                            "IOC_LIMIT_BUMPED: %s %d→%d¢ "
                            "(target_qty=%d, prob=%.4f, "
                            "edge_ceiling=%d, max_bump=%d, "
                            "reserve=%+d strategy=%s) — sweeping "
                            "deeper levels",
                            ticker, price, _smart_limit,
                            count, _cal_prob, _edge_ceiling,
                            IOC_LIMIT_MAX_BUMP_CENTS, _reserve_cents,
                            _bump_strategy)
                        _ioc_limit_price = _smart_limit
                    elif _smart_limit == price:
                        logging.debug(
                            "IOC_LIMIT_AT_BEST: %s %d¢ (no bump needed "
                            "or no benefit within caps)",
                            ticker, price)
            elif _is_drift_flagged:
                logging.debug(
                    "IOC_LIMIT_PICKER_BYPASS: %s — ws_drift_cooldown "
                    "active; using scan-time best_ask=%d¢ unchanged",
                    ticker, price)
            elif _is_no_side:
                logging.debug(
                    "IOC_LIMIT_PICKER_BYPASS: %s — NO-side IOC "
                    "(picker is YES-side only); using "
                    "scan-time price=%d¢ unchanged",
                    ticker, price)
        except Exception:
            logging.warning(
                "smart_ioc_limit_picker failed", exc_info=True)
        # ── TM Sweep Live: direct limit bump (no orderbook required) ─────
        # The smart picker above is gated on _live_ob from the WS cache
        # and has no REST fallback. TM tickers consistently lack fresh WS
        # cache when TM fires (488/488 production rows showed
        # best_ask_source='market_nbbo' as of 2026-04-28), so the picker
        # silently no-ops for TM and the edge_ceiling override never runs.
        # This branch sets the limit directly when the sweep gates are
        # satisfied — independent of orderbook availability. Kalshi
        # auto-cancels surplus at $0 on unfilled IOC tail.
        # Conditions:
        #   - TM_SWEEP_LIVE_ENABLED env-var-gated kill switch
        #   - exact-set strategy match (no startswith footgun)
        #   - not a ladder retry (don't compound with +1c escalation)
        #   - not _is_no_side (NO-side `best_yes_ask` is no_price; bumping
        #     would submit a 99c NO buy = ~$1/contract overpay; matches
        #     the picker's NO-side bypass)
        #   - price < MAX_ENTRY_PRICE (no bump possible at 99c entry)
        #   - _ioc_limit_price < MAX_ENTRY_PRICE (don't lower a higher
        #     picker-chosen limit on the rare path where picker did fire)
        # Adversary R3 A1: write the gate result to the candidate dict so
        # the shadow capture in _execute_tm_taker reads from a single
        # source of truth — eliminating the predicate-duplication
        # fragility that R2 caught.
        _direct_bump_fired = (
            TM_SWEEP_LIVE_ENABLED
            and _bump_strategy in TM_LIVE_STRATEGIES
            and not _is_ladder_retry
            and not _is_no_side
            and isinstance(price, int)
            and price < MAX_ENTRY_PRICE
            and _ioc_limit_price < MAX_ENTRY_PRICE)
        candidate["_tm_direct_bump_fired"] = _direct_bump_fired
        if _direct_bump_fired:
            # Adversary R2 A3: assign FIRST, log AFTER — log records fact,
            # not intent. A logging handler exception between the log call
            # and the assignment would have created a misleading audit
            # trail (claiming bump while actually submitting scan-time price).
            _prev_limit = _ioc_limit_price
            _ioc_limit_price = MAX_ENTRY_PRICE
            logging.info(
                "TM_SWEEP_DIRECT_BUMP: %s %d→%d¢ strategy=%s "
                "(picker bypassed; orderbook unavailable for TM)",
                ticker, _prev_limit, _ioc_limit_price, _bump_strategy)
        # `_ioc_limit_price` is the actual price submitted to Kalshi.
        # `price` and `candidate["best_yes_ask"]` remain at scan-time
        # values for the downstream drift-check + PHANTOM_ABORT logic
        # and for telemetry/audit.

        # ── Option X v2: per-strategy IOC clamp (Apr 24) ──────────────────
        # Kalshi IOC matches at BEST available price up to our limit,
        # sweeping through the ladder. Variant B (sub-floor phantom-ask
        # sweep) can hand us sub-floor fills when top-of-book is thin and
        # real asks sit way below. Original Option X (Apr 15) clamped ALL
        # orderbook-source IOCs to top-of-book depth to prevent this.
        #
        # Post-WS-fix (0ddcaf8, Apr 23), top-of-book on TM_99 markets is
        # routinely 1-2ct. Pre-fix the clamp was silently bypassed because
        # ob_data came up empty (schema drift) → best_ask_source='market_nbbo'
        # → blind IOC path. Now that orderbook is real, the clamp fires
        # correctly but at a thin level, killing strategies that previously
        # benefited from blind-firing into Kalshi's real book.
        #
        # v2 picks the clamp policy per-strategy (STRATEGY_CLAMP_POLICY):
        #   top_of_book — cap count at quoted best ask depth. Preserves
        #     Variant B protection for sub-floor-risk paths.
        #   no_clamp    — submit full Kelly count. Kalshi IOC auto-cancels
        #     the unfilled remainder ($0 charge), so oversizing is free.
        #     PHANTOM_ABORT (ask_depth=0) still fires as the catastrophic
        #     tail guard. Correct for ceiling-triggered strategies (TM) and
        #     floor-triggered discounts with empirically-zero sweep tail.
        # See kb/decisions/no-floor-relaxation-on-ws-fix.md.
        _ask_src = candidate.get("best_ask_source")
        _ob_snap = candidate.get("ob_snapshot") or {}
        _ask_depth = _ob_snap.get("ask_depth")
        _strategy = candidate.get("strategy") or ""
        _policy = STRATEGY_CLAMP_POLICY.get(_strategy, STRATEGY_CLAMP_DEFAULT)

        # WS cache drift defense: when cache claims non-trivial depth, verify
        # against a fresh REST /orderbook fetch. If REST materially disagrees,
        # prefer REST as authoritative. This is a data-layer correction (not
        # a policy change); a confirmed drift means the book really IS thin
        # regardless of strategy policy, so we clamp even on no_clamp paths.
        # If cache was already thin (< threshold) OR REST agrees, no change.
        # See kb/failures/kalshi-ws-schema-drift.md § "WS delta underflow".
        # Apr 25 2026: clamp uses windowed peak (not single REST sample) for
        # the size decision; PHANTOM_ABORT uses fresh sample so a real-time
        # empty book is still caught regardless of historical peak.
        _drift_corrected = False
        _rest_fresh = None  # for PHANTOM_ABORT (Round 1 P0 #2)
        if (IOC_DRIFT_CHECK_ENABLED
                and _ask_src == "orderbook"
                and isinstance(_ask_depth, int)
                and _ask_depth >= IOC_DRIFT_CHECK_MIN_CACHED_DEPTH):
            # Smoothed helper returns (peak, fresh):
            #   peak — windowed-max for the size clamp (anti-flicker)
            #   fresh — most-recent REST sample for PHANTOM_ABORT
            # See IOC_DRIFT_CHECK_REST_WINDOW_S. A single REST call is
            # volatile — WS_DRIFT_PROBE_REST_STABILITY shows two
            # back-to-back calls disagreeing by hundreds of contracts.
            # Apr 25 2026: single-sample clamp caused a 65% drop in
            # position size across all assets.
            _rest_peak, _rest_fresh = self._rest_best_ask_depth_smoothed(ticker)
            # Round 2 [A1] cold-start gate: if the buffer has <2
            # samples in the window, peak ≈ fresh and the "smoothing"
            # degenerates to single-sample clamping — the exact
            # pre-fix bug. Skip the divergence/clamp branch on cold
            # start and let the existing policy
            # (cached _ask_depth + STRATEGY_CLAMP_POLICY) handle it.
            # _rest_fresh stays exposed for PHANTOM_ABORT below.
            _sample_count = self._rest_depth_window_count(ticker)
            _cold_start = (
                _sample_count
                < OrderExecutor._REST_DEPTH_MIN_SAMPLES_FOR_CLAMP)
            if _rest_peak is not None and not _cold_start:
                if _rest_peak < _ask_depth * IOC_DRIFT_CHECK_DIVERGENCE_RATIO:
                    logging.warning(
                        "IOC_CACHE_DRIFT: %s %dc ws_cache=%d rest_peak=%d "
                        "rest_fresh=%s (ratio=%.2f, samples=%d) "
                        "strategy=%s policy=%s "
                        "— using REST peak as authoritative",
                        ticker, price, _ask_depth, _rest_peak,
                        ("?" if _rest_fresh is None else str(_rest_fresh)),
                        _rest_peak / max(_ask_depth, 1), _sample_count,
                        _strategy, _policy)
                    _ask_depth = _rest_peak  # authoritative for clamp logic below
                    _drift_corrected = True
                else:
                    logging.info(
                        "IOC_CACHE_OK: %s %dc ws_cache=%d rest_peak=%d "
                        "rest_fresh=%s (samples=%d, strategy=%s)",
                        ticker, price, _ask_depth, _rest_peak,
                        ("?" if _rest_fresh is None else str(_rest_fresh)),
                        _sample_count, _strategy)
            elif _rest_peak is not None and _cold_start:
                # Cold-start: smoothed-peak gate isn't authoritative yet
                # (samples < _REST_DEPTH_MIN_SAMPLES_FOR_CLAMP). Default
                # behavior is to fall through to cached-depth policy.
                # ESCAPE HATCH (Apr 25 2026): if the single fresh REST
                # sample shows CATASTROPHIC divergence from cache
                # (≥10× drift, IOC_DRIFT_CHECK_COLD_START_RATIO), apply
                # the clamp anyway. Single-sample flicker risk is real
                # but bounded by the strict ratio; the alternative is
                # what we just measured — Kelly-size IOCs into 1ct books
                # producing 50+ micro-fills/day across freshly-discovered
                # tickers (~16/hr, all hit cold-start path).
                if (_rest_peak
                        < _ask_depth * IOC_DRIFT_CHECK_COLD_START_RATIO):
                    logging.warning(
                        "IOC_CACHE_DRIFT_COLD: %s %dc ws_cache=%d "
                        "rest_fresh=%d ratio=%.3f (samples=%d, "
                        "threshold=%.2f) strategy=%s policy=%s — "
                        "catastrophic drift on cold-start; using REST "
                        "as authoritative",
                        ticker, price, _ask_depth, _rest_peak,
                        _rest_peak / max(_ask_depth, 1), _sample_count,
                        IOC_DRIFT_CHECK_COLD_START_RATIO,
                        _strategy, _policy)
                    _ask_depth = _rest_peak
                    _drift_corrected = True
                else:
                    # Cold-start with non-catastrophic divergence: fall
                    # through to cached policy. Log once for diagnostics
                    # — this branch hits constantly for newly-discovered
                    # 15M tickers, so use INFO not WARNING to avoid log
                    # spam.
                    logging.info(
                        "IOC_CACHE_COLD_START: %s %dc ws_cache=%d "
                        "rest_fresh=%s (samples=%d < %d, ratio=%.3f) "
                        "— falling through to cached-depth policy",
                        ticker, price, _ask_depth,
                        ("?" if _rest_fresh is None else str(_rest_fresh)),
                        _sample_count,
                        OrderExecutor._REST_DEPTH_MIN_SAMPLES_FOR_CLAMP,
                        _rest_peak / max(_ask_depth, 1))

        if _ask_src == "orderbook" and isinstance(_ask_depth, int):
            # Catastrophic tail guard — fires regardless of policy. Uses
            # BOTH the drift-corrected _ask_depth (cached/peak) AND the
            # fresh REST sample. Fresh==0 means the book is empty RIGHT
            # NOW, regardless of any historical peak — the smoothing
            # window must not mask this signal. Round 1 P0 #2.
            if _ask_depth == 0 or _rest_fresh == 0:
                _abort_reason = (
                    "rest_fresh=0" if _rest_fresh == 0 else
                    "ask_depth=0 (orderbook-confirmed)")
                logging.warning(
                    "IOC_ABORT_PHANTOM: %s %dc count=%d %s "
                    "strategy=%s policy=%s — refusing IOC to prevent "
                    "ladder sweep",
                    ticker, price, count, _abort_reason, _strategy, _policy)
                if not _is_ladder_retry:
                    self._session_ioc_unfilled += 1
                return None
            if _policy == "no_clamp":
                # Default no_clamp: submit full Kelly, trust Kalshi auto-cancel.
                # Exception: if drift check corrected depth downward, clamp to
                # the REST-verified depth — that's a data-correctness override.
                if _drift_corrected and _ask_depth < count:
                    if _ask_depth < IOC_MIN_COUNT_AFTER_CLAMP:
                        logging.warning(
                            "IOC_ABORT_THIN_CLAMP: %s %dc rest_depth=%d < min=%d "
                            "(policy=no_clamp + drift, original_count=%d, asset=%s, strategy=%s) "
                            "— book genuinely thin, skipping; next scan retries after cooldown",
                            ticker, price, _ask_depth, IOC_MIN_COUNT_AFTER_CLAMP,
                            count, candidate.get("asset", "?"), _strategy)
                        if not _is_ladder_retry:
                            self._session_ioc_unfilled += 1
                        return None
                    logging.warning(
                        "IOC_DRIFT_CLAMP: %s %dc count %d -> %d "
                        "(policy=no_clamp + REST drift correction, asset=%s, strategy=%s)",
                        ticker, price, count, _ask_depth,
                        candidate.get("asset", "?"), _strategy)
                    count = _ask_depth
                    candidate["position_size"] = count
                else:
                    logging.info(
                        "IOC_NO_CLAMP: %s %dc count=%d (cached_depth=%d, asset=%s, strategy=%s)",
                        ticker, price, count, _ask_depth,
                        candidate.get("asset", "?"), _strategy)
            else:
                # top_of_book (default, conservative). Clamp to verified depth
                # (drift-corrected if REST fired, else cached) to prevent
                # ladder sweeps into sub-floor prices.
                if _ask_depth < count:
                    logging.warning(
                        "IOC_SIZE_CLAMP: %s %dc count %d -> %d "
                        "(policy=top_of_book, verified_depth=%d, drift=%s, asset=%s, strategy=%s)",
                        ticker, price, count, _ask_depth, _ask_depth,
                        _drift_corrected, candidate.get("asset", "?"), _strategy)
                    count = _ask_depth
                    candidate["position_size"] = count
        elif _ask_src == "market_nbbo":
            # NBBO blind path: no orderbook data → no depth signal,
            # no PHANTOM_ABORT possible. Round 2 [A2] / Round 3 [A4]
            # known scope limit — the smoothed-clamp + fresh-zero
            # phantom guard only protects orderbook-source IOCs.
            # If NBBO blind becomes the dominant path again (it was
            # pre-WS-fix), a separate defense is needed here.
            logging.info(
                "IOC_BLIND_SUBMIT: %s %dc count=%d asset=%s strategy=%s (NBBO fallback — no depth)",
                ticker, price, count, candidate.get("asset", "?"), _strategy)
        # ── end Option X v2 ───────────────────────────────────────────────

        client_oid = str(uuid.uuid4())

        # Persist before submission. price_cents records the LIMIT
        # actually submitted to Kalshi (= _ioc_limit_price), not the
        # scan-time best_ask. Round 2 [P1-B]: audit trail must
        # reflect what was actually sent.
        _side = candidate.get("side", "yes")
        self._state.insert_bot_order(
            client_oid, ticker, candidate["event_ticker"],
            candidate["asset"], _side, count, _ioc_limit_price, True
        )

        # F/U TM_99 zero-fill diagnostic (Apr 26): pre-IOC ladder
        # snapshot. Pairs with post-IOC snapshot below (after place_order
        # returns) to discriminate HYP A (Kalshi only matches yes_asks
        # ladder — no_bid stays unchanged on fail) from HYP B (Kalshi
        # matches both, no_bid sniped before our IOC arrives — no_bid
        # qty drops between pre and post). R-review [A1] fix.
        # See tests/test_ioc_submit_ladder_diag.py.
        _diag_pre = None
        try:
            _diag_pre = OrderExecutor._compute_ladder_diag(_live_ob)
        except Exception:
            logging.debug("IOC_SUBMIT_LADDER_DIAG pre failed", exc_info=True)

        # Submit as IOC — exchange auto-cancels any unfilled remainder.
        # Uses _ioc_limit_price (smart picker output) for the actual
        # exchange submission, while `price` and candidate["best_yes_ask"]
        # remain at scan-time values for telemetry/audit/drift-check.
        _price_kwarg = (
            {"no_price": _ioc_limit_price} if _side == "no"
            else {"yes_price": _ioc_limit_price})
        resp = self._client.place_order(
            ticker=ticker, side=_side, action="buy",
            count=count, client_order_id=client_oid,
            time_in_force="immediate_or_cancel", **_price_kwarg,
        )

        # F/U TM_99 zero-fill diagnostic — post-IOC snapshot + outcome.
        # Includes fill_count so the divergence pattern can be
        # correlated with fill outcome via single-line grep
        # (R-review [A5]). Re-fetches the cached orderbook so we
        # observe post-fill state (WS push from Kalshi typically
        # arrives within ms of fill). If no_bid_qty dropped between
        # pre and post, the IOC matched against the no_bid → HYP B.
        # If no_bid_qty unchanged AND fill_count==0, our 99c bid
        # never reached the no_bid → HYP A.
        try:
            _diag_post = None
            if _scanner is not None:
                try:
                    _live_ob_post, _ = _scanner._get_orderbook_cached(ticker)
                    _diag_post = OrderExecutor._compute_ladder_diag(_live_ob_post)
                except Exception:
                    pass
            _fill_ct = 0
            if resp is not None:
                _fill_ct = (
                    fp_str_to_int(
                        (resp.get("order") or {}).get("fill_count_fp"))
                    or ((resp.get("order") or {}).get("fill_count") or 0)
                )
            _pre = _diag_pre or {}
            _post = _diag_post or {}
            logging.info(
                "IOC_SUBMIT_LADDER_DIAG: %s asset=%s strategy=%s "
                "bid=%d req=%d fill=%d "
                "PRE: yes=%s/%d no_bid=%s/%d cross=%s "
                "diverges=%s one_side_empty=%s "
                "POST: yes=%s/%d no_bid=%s/%d",
                ticker, candidate.get("asset", "?"),
                candidate.get("strategy", "?"),
                _ioc_limit_price, count, _fill_ct,
                _pre.get("yes_ask_top_price"), _pre.get("yes_ask_top_qty", 0),
                _pre.get("no_bid_top_price"), _pre.get("no_bid_top_qty", 0),
                _pre.get("cross_side_ask"),
                _pre.get("diverges"), _pre.get("one_side_empty"),
                _post.get("yes_ask_top_price"), _post.get("yes_ask_top_qty", 0),
                _post.get("no_bid_top_price"), _post.get("no_bid_top_qty", 0))
        except Exception:
            logging.debug("IOC_SUBMIT_LADDER_DIAG post failed", exc_info=True)

        if resp is None:
            self._state.mark_order_status(client_oid, "api_error")
            self._ticker_api_errors[ticker] = self._ticker_api_errors.get(ticker, 0) + 1
            logging.error("Taker order submission failed: %s (api_errors=%d)",
                          ticker, self._ticker_api_errors[ticker])
            if (candidate.get("entry_path") != "confirmation_addon"
                    and not _is_ladder_retry):
                self._session_ioc_unfilled += 1
            return None

        # Successful submission — reset api error counter
        self._ticker_api_errors.pop(ticker, None)
        order_id = (resp.get("order") or {}).get("order_id", client_oid)
        remaining_count = (resp.get("order") or {}).get("remaining_count", count)
        _order_fill_count = fp_str_to_int((resp.get("order") or {}).get("fill_count_fp")) or (
            (resp.get("order") or {}).get("fill_count") or 0)
        self._state.confirm_order_submitted(client_oid, order_id)

        order_info = {
            "order_id": order_id,
            "client_order_id": client_oid,
            "ticker": ticker,
            "event_ticker": candidate["event_ticker"],
            "asset": candidate["asset"],
            "side": _side,
            # `price_cents` = limit actually submitted to Kalshi
            # (post smart-picker bump, if any). Round 2 [P1-B].
            "price_cents": _ioc_limit_price,
            "scan_time_best_ask": price,  # original for forensics
            "count": count,
            "is_taker": True,
            "submit_time": time.time(),
            "seconds_to_close_at_submit": candidate["seconds_to_close"],
            "candidate": candidate,
            "balance_at_entry": balance,
            "execution_method": "ioc",
            "entry_path": candidate.get("entry_path", "direct_taker"),
        }

        self._logger.log_order({
            "action": "taker_submitted",
            "ticker": ticker,
            "order_id": order_id,
            "client_order_id": client_oid,
            "price_cents": _ioc_limit_price,
            "scan_time_best_ask": price,
            "count": count,
            "time_in_force": "ioc",
        })
        logging.info(
            "Taker IOC order: %s %dx @ %d¢%s",
            ticker, count, _ioc_limit_price,
            (f" (bumped from {price}¢)"
             if _ioc_limit_price != price else ""))

        # Lifecycle snapshot at IOC submit — captures the book the order
        # was sent into. Pairs with fill snapshots in _on_fill so we can
        # later answer "was the 1ct stub the entire book at submit time
        # or did it shrink between scan and submit?"
        try:
            self._state.insert_order_lifecycle_snapshot(
                order_id=order_id, ticker=ticker, event_type="submit",
                source=candidate.get("strategy"))
        except Exception:
            logging.warning("insert_order_lifecycle_snapshot (submit) failed",
                            exc_info=True)

        # IOC resolves instantly; brief wait + collect ALL fill events.
        # An IOC can match against multiple resting orders, generating
        # multiple fill events.  _check_for_fill() returns one unseen
        # fill per call (tracks seen IDs), so loop until exhausted.
        time.sleep(0.3)
        total_filled = 0
        while True:
            fill = self._check_for_fill(order_info)
            if not fill:
                break
            fill_count = self._on_fill(fill, order_info)
            total_filled += fill_count

        # Second poll pass: catch late fills that arrived after initial 0.3s
        if total_filled > 0:
            time.sleep(0.5)
            while True:
                fill = self._check_for_fill(order_info)
                if not fill:
                    break
                fill_count = self._on_fill(fill, order_info)
                total_filled += fill_count

        if total_filled > 0:
            if (candidate.get("entry_path") != "confirmation_addon"
                    and not _is_ladder_retry):
                self._session_ioc_fills += 1
            unfilled = count - total_filled
            logging.info(
                f"ioc_taker_result: {ticker} filled={total_filled} "
                f"remaining={unfilled}"
                f"{'' if unfilled == 0 else ' [PARTIAL]'}")
            if unfilled > 0:
                logging.warning(
                    f"IOC partial fill: {ticker} wanted {count} got "
                    f"{total_filled} — {unfilled} contracts unfilled")
                # Ladder escalation: actively retry once at +1¢ for the
                # remainder. Runs BEFORE the maker tail so coexistence
                # is layered: active reach first, passive rest second.
                # If escalation fully fills, the maker tail's MIN_
                # REMAINDER gate naturally suppresses the tail. If
                # escalation also partials, fall through to maker tail
                # at ORIGINAL price (where someone may return to).
                # Failures here MUST NOT break the IOC return path.
                _ladder_filled = 0
                if LADDER_ESCALATION_ENABLED:
                    try:
                        _ladder_result = self._maybe_ladder_escalate(
                            candidate=candidate,
                            original_limit=_ioc_limit_price,
                            remaining=unfilled,
                            ioc_filled=total_filled)
                        _ladder_filled = (
                            _ladder_result.get("escalated_filled", 0))
                        unfilled -= _ladder_filled
                    except Exception:
                        logging.warning(
                            "_maybe_ladder_escalate raised; IOC "
                            "result still returned to caller",
                            exc_info=True)
                # Maker-tail: post the unfilled remainder as a
                # post_only GTC limit so benign rotation flow can
                # still fill us. Eligibility, gates, caps all live in
                # _maybe_post_maker_tail. Failures here MUST NOT break
                # the IOC return path — this is a strict additive
                # behavior on top of the IOC outcome.
                if MAKER_TAIL_AFTER_IOC_PARTIAL:
                    try:
                        self._maybe_post_maker_tail(
                            candidate=candidate,
                            ioc_price=_ioc_limit_price,
                            remaining=unfilled,
                            ioc_filled=total_filled)
                    except Exception:
                        logging.warning(
                            "_maybe_post_maker_tail raised; IOC "
                            "result still returned to caller",
                            exc_info=True)
            order_info["filled_count"] = total_filled
            return order_info

        # ── Ghost fill detection (Layer A): remaining_count from order response ──
        # Kalshi's matching engine returns remaining_count=0 when the order was
        # fully matched. If fill polling found nothing, the fills API has latency
        # but the contracts DO exist. Register a defensive position at the limit
        # price (conservative — actual fills are ≤ limit). Reconciliation at next
        # startup will correct prices from Kalshi's positions API.
        #
        # CRITICAL: For IOC orders, remaining_count=0 can also mean the order was
        # auto-canceled with zero fills. Must verify fill_count > 0 from the order
        # response to distinguish real ghost fills from unfilled IOC cancellations.
        # (Bug: false ghost fill on KXSOL15M-26MAR061400-00 cost -$39.16, Mar 6 2026)
        if remaining_count == 0 and _order_fill_count > 0:
            logging.error(
                f"GHOST_FILL_DETECTED: {ticker} remaining_count=0 but no fill "
                f"events from API — Kalshi matched all {count} contracts. "
                f"Registering defensive position at limit price {price}¢")
            self._state.record_position_from_fill(
                ticker=ticker,
                event_ticker=candidate["event_ticker"],
                asset=candidate["asset"],
                side=_side,
                count=count,
                price_cents=price,
                strategy=candidate.get("strategy"),
                seconds_to_close=order_info.get("seconds_to_close_at_submit"),
                fill_latency=round(time.time() - order_info["submit_time"], 3),
                vol_regime=candidate.get("vol_regime"),
                calibrated_prob=candidate.get("calibrated_prob"),
                edge=candidate.get("edge"),
                kelly_f=candidate.get("kelly_f"),
                is_taker=True,
                fill_source="ghost_fill",
                execution_method="ioc",
                escalation_type=candidate.get("escalation_type"),
                maker_price_cents=candidate.get("maker_price_cents"),
                maker_wait_seconds=candidate.get("maker_wait_seconds"),
            )
            self._state.mark_order_status(order_id, "filled")
            if (candidate.get("entry_path") != "confirmation_addon"
                    and not _is_ladder_retry):
                self._session_ioc_fills += 1
            order_info["filled_count"] = count  # Ghost fill = assumed full fill
            return order_info

        # remaining_count=0 but fill_count=0: IOC was auto-canceled, not a ghost fill
        if remaining_count == 0 and _order_fill_count == 0:
            logging.info(
                f"IOC_CANCELED_NO_FILLS: {ticker} remaining_count=0 "
                f"fill_count=0 — order was canceled unfilled, not a ghost fill")

        # ── Ghost fill detection (Layer B): positions API verification ──
        # remaining_count > 0 suggests genuinely unfilled, but verify against
        # Kalshi's positions API in case of any untracked position.
        try:
            _pos_resp = self._client.get_positions()
            if _pos_resp and _pos_resp.get("market_positions"):
                for _pos in _pos_resp["market_positions"]:
                    if _pos.get("ticker") == ticker:
                        _pos_count = fp_str_to_int(_pos.get("position_fp")) or (_pos.get("position") or 0)
                        if _pos_count != 0:
                            _ghost_side = "yes" if _pos_count > 0 else "no"
                            _pos_abs = abs(_pos_count)
                            _pos_cost_d = _pos.get("market_exposure_dollars")
                            _pos_cost = dollars_str_to_cents(_pos_cost_d) if _pos_cost_d else (_pos.get("market_exposure") or 0)
                            _pos_avg = _pos_cost // _pos_abs if _pos_abs else price
                            logging.error(
                                f"GHOST_FILL_DETECTED_VIA_POSITIONS: {ticker} side={_ghost_side} "
                                f"fill polling found nothing, remaining_count={remaining_count}, "
                                f"but positions API shows {_pos_count} contracts "
                                f"(cost={_pos_cost}¢, avg={_pos_avg}¢)")
                            self._state.record_position_from_fill(
                                ticker=ticker,
                                event_ticker=candidate["event_ticker"],
                                asset=candidate["asset"],
                                side=_ghost_side,
                                count=_pos_abs,
                                price_cents=_pos_avg,
                                strategy=candidate.get("strategy"),
                                seconds_to_close=order_info.get("seconds_to_close_at_submit"),
                                fill_latency=round(time.time() - order_info["submit_time"], 3),
                                vol_regime=candidate.get("vol_regime"),
                                calibrated_prob=candidate.get("calibrated_prob"),
                                edge=candidate.get("edge"),
                                kelly_f=candidate.get("kelly_f"),
                                is_taker=True,
                                fill_source="ghost_fill_positions_api",
                                execution_method="ioc",
                                escalation_type=candidate.get("escalation_type"),
                                maker_price_cents=candidate.get("maker_price_cents"),
                                maker_wait_seconds=candidate.get("maker_wait_seconds"),
                            )
                            self._state.mark_order_status(order_id, "filled")
                            if (candidate.get("entry_path") != "confirmation_addon"
                                    and not _is_ladder_retry):
                                self._session_ioc_fills += 1
                            order_info["filled_count"] = _pos_abs  # Ghost fill from positions API
                            return order_info
        except Exception as e:
            logging.warning(f"Ghost fill positions API check failed for {ticker}: {e}")

        # IOC auto-cancels unfilled portion — no manual cancel needed
        self._state.mark_order_status(order_id, "canceled")
        if (candidate.get("entry_path") != "confirmation_addon"
                and not _is_ladder_retry):
            self._session_ioc_unfilled += 1
        self._logger.log_order({
            "action": "taker_ioc_unfilled",
            "ticker": ticker,
            "order_id": order_id,
            "remaining_count": remaining_count,
        })
        logging.warning(f"Taker IOC not filled: {ticker} (remaining={remaining_count})")
        return None

    # ── Maker-tail-after-IOC-partial ──────────────────────────────────────
    # Apr 25 2026: when IOC fills 9 of 50 because top of book is thin,
    # the unfilled 41 used to die on cancel ($0 EV). For high-conviction
    # strategies (DC tiers + TM-99/-98 + weekend/overnight discounts),
    # leaving a post_only=True GTC limit at the IOC price for a short TTL
    # gives benign rotation flow a chance to fill the remainder, with
    # adverse selection as the offsetting risk. Maker fee = $0, so the
    # only cost is escrowed capital + adverse-selection PnL.
    # Caps + min STC + min remainder bound the worst case.
    # See kb/decisions/maker-tail-after-ioc-partial.md (TBD).

    def _strategy_max_entry_price(self, strategy: str) -> int:
        """Per-strategy MAX_ENTRY_PRICE for ladder escalation cap.

        decided_t2 / decided_t2_z25 cap at DECIDED_CONTRACT_T2_MAX_PRICE
        (96¢) — escalating past it would put us in territory the
        strategy never endorsed (T2 only applies 93-96¢).
        All other eligible strategies cap at the global MAX_ENTRY_PRICE.
        """
        if strategy in ("decided_t2", "decided_t2_z25"):
            return DECIDED_CONTRACT_T2_MAX_PRICE
        return MAX_ENTRY_PRICE

    def _maybe_ladder_escalate(self, candidate: Dict, original_limit: int,
                               remaining: int, ioc_filled: int) -> Dict:
        """After an IOC partial fill, retry ONCE at +1¢ for the
        unfilled remainder.

        Returns dict with at least {"escalated": bool}; on success also
        carries {"escalated_filled": int, "escalated_limit": int}.

        Gates (any failure → silent skip, no exception):
          1. LADDER_ESCALATION_ENABLED kill switch
          2. ioc_filled > 0 (zero fill = phantom; don't push into another)
          3. remaining >= LADDER_ESCALATION_MIN_REMAINDER
          4. strategy in LADDER_ESCALATION_ELIGIBLE_STRATEGIES
          5. NOT already a ladder retry (recursion guard)
          6. escalated price ≤ strategy MAX_ENTRY_PRICE AND ≤ global cap
        """
        result = {"escalated": False}
        # Gate 1: kill switch.
        if not LADDER_ESCALATION_ENABLED:
            return result
        # Gate 2: zero fill = phantom-book signal; don't escalate.
        if ioc_filled <= 0:
            return result
        # Gate 3: min remainder.
        if remaining < LADDER_ESCALATION_MIN_REMAINDER:
            return result
        # Gate 4: eligible strategy.
        strategy = candidate.get("strategy") or ""
        if strategy not in LADDER_ESCALATION_ELIGIBLE_STRATEGIES:
            return result
        # Gate 5: recursion guard.
        if candidate.get("_is_ladder_retry"):
            return result
        # Gate 6: per-strategy + global price ceiling.
        strategy_max = self._strategy_max_entry_price(strategy)
        escalated_limit = original_limit + LADDER_ESCALATION_OFFSET
        if escalated_limit > strategy_max or escalated_limit > MAX_ENTRY_PRICE:
            logging.info(
                "LADDER_ESCALATION_AT_CAP: %s strategy=%s original=%dc "
                "would_escalate_to=%dc cap=%dc — skipping",
                candidate.get("ticker", "?"), strategy, original_limit,
                escalated_limit, min(strategy_max, MAX_ENTRY_PRICE))
            return result
        # Gate 7: re-check per-ticker risk cap. The retry adds size
        # to the same ticker; aggregate exposure (existing positions
        # which now include the parent's just-recorded fill +
        # remaining*escalated_limit) must remain inside MAX_TICKER_RISK.
        # Re-checking here is required because callers (execute(),
        # _execute_*_taker) gate at scan time before the parent IOC,
        # but we're inside _submit_taker by the time we reach here —
        # the caller's gate is bypassed for the retry. Fail-closed on
        # any error.
        ticker = candidate.get("ticker", "")
        try:
            balance = candidate.get("balance_at_scan") or 0
            if balance <= 0:
                # No balance signal — fail closed.
                logging.warning(
                    "LADDER_ESCALATION_NO_BALANCE: %s strategy=%s — "
                    "skipping (cannot validate ticker cap)",
                    ticker, strategy)
                return result
            existing_ticker_cost = sum(
                p.get("total_cost_cents", 0)
                for p in self._state.get_open_positions()
                if p.get("ticker") == ticker)
            ticker_cap_cents = balance * MAX_TICKER_RISK
            retry_cost = remaining * escalated_limit
            if existing_ticker_cost + retry_cost > ticker_cap_cents:
                logging.info(
                    "LADDER_ESCALATION_TICKER_CAP_BLOCKED: %s "
                    "strategy=%s existing=%dc retry_cost=%dc cap=%dc",
                    ticker, strategy, existing_ticker_cost,
                    retry_cost, int(ticker_cap_cents))
                return result
        except Exception:
            # Fail-closed on any error reading state.
            logging.warning(
                "LADDER_ESCALATION_CAP_CHECK_RAISED: %s strategy=%s — "
                "skipping defensively", ticker, strategy, exc_info=True)
            return result
        # Gate 8: explicit pre-retry phantom check. The recursive
        # _submit_taker's PHANTOM_ABORT branch only fires when
        # candidate.ob_snapshot.ask_depth is an int — but we set it to
        # None on the retry to avoid stale-depth artifacts (the parent
        # ob_snapshot referred to the original price level). That
        # silent skip would leave the retry with NO catastrophic-tail
        # guard. Round 3 fix: do an explicit fresh REST orderbook
        # fetch here and abort if the escalated level shows zero
        # depth. Failures (None / exception) → fail-closed skip.
        try:
            _ob_raw = self._client.get_orderbook(ticker)
            if not isinstance(_ob_raw, dict):
                logging.info(
                    "LADDER_ESCALATION_OB_UNAVAILABLE: %s strategy=%s "
                    "— skipping retry (cannot verify depth)",
                    ticker, strategy)
                return result
            # Kalshi REST returns three possible shapes (mirror prod
            # unwrap at bot/_impl.py:15810-15812 + 16419-16421):
            #   1. {"orderbook_fp": {"yes_dollars": [["0.99","48"]...]}}
            #      — current FP schema (Mar 2026 migration)
            #   2. {"orderbook": {"yes": [[99, 48], ...]}} — wrapped legacy
            #   3. {"yes": [[99, 48], ...]} — unwrapped (WS cache, older)
            # Try FP first (matches prod ordering), then wrapped/unwrapped.
            _ob_fp = _ob_raw.get("orderbook_fp")
            if _ob_fp:
                _ob = OpportunityScanner._convert_orderbook_fp(_ob_fp)
            else:
                _ob = _ob_raw.get("orderbook", _ob_raw)
            if not isinstance(_ob, dict):
                logging.info(
                    "LADDER_ESCALATION_OB_MALFORMED: %s strategy=%s — "
                    "skipping retry", ticker, strategy)
                return result
            # YES-side ladder. We're a YES BUYER with limit at
            # escalated_limit. Kalshi will match our IOC against any
            # YES ask priced AT-OR-BELOW our limit. Depth check sums
            # those levels.
            _yes_levels = _ob.get("yes") or []
            _depth_at_or_below_limit = 0
            for lvl in _yes_levels:
                # Tolerate malformed levels: must be (price, qty) pair.
                if not (isinstance(lvl, (list, tuple)) and len(lvl) >= 2):
                    continue
                try:
                    _lp = int(lvl[0])
                    _lq = int(lvl[1])
                except (TypeError, ValueError):
                    continue
                if _lp <= escalated_limit and _lq > 0:
                    _depth_at_or_below_limit += _lq
            if _depth_at_or_below_limit <= 0:
                logging.warning(
                    "LADDER_ESCALATION_PHANTOM_ABORT: %s strategy=%s "
                    "escalated=%dc — fresh orderbook shows 0 depth "
                    "at <= limit; refusing retry",
                    ticker, strategy, escalated_limit)
                return result
        except Exception:
            logging.warning(
                "LADDER_ESCALATION_OB_CHECK_RAISED: %s strategy=%s — "
                "skipping defensively", ticker, strategy, exc_info=True)
            return result
        # Build the retry candidate. Carry _is_ladder_retry=True to
        # block recursive escalation AND recursive maker-tail.
        # Replace position_size with remaining; reset best_yes_ask to
        # the escalated limit so the smart-IOC-picker / drift-checks
        # operate on the right reference price.
        # CRITICAL: do NOT rename strategy. STRATEGY_CLAMP_POLICY and
        # STRATEGY_LIMIT_BUMP_RESERVE_CENTS are looked up by exact
        # string match — renaming silently routes the retry through
        # the default policy, which is top_of_book (not no_clamp). The
        # per-strategy IOC mechanics MUST be preserved on the retry.
        # Telemetry separation lives in the _is_ladder_retry flag and
        # the LADDER_ESCALATION_ATTEMPT log line, NOT the strategy
        # column.
        retry_candidate = dict(candidate)
        retry_candidate["_is_ladder_retry"] = True
        retry_candidate["position_size"] = remaining
        retry_candidate["best_yes_ask"] = escalated_limit
        # Drop the parent's ob_snapshot — its ask_depth value applies
        # to the original price level, not the escalated one. The
        # downstream PHANTOM_ABORT in _submit_taker no-ops on None,
        # but Gate 8 above did the equivalent check explicitly.
        retry_candidate["ob_snapshot"] = None
        logging.info(
            "LADDER_ESCALATION_ATTEMPT: %s strategy=%s original=%dc "
            "escalated=%dc remaining=%d ioc_filled=%d",
            ticker, strategy, original_limit,
            escalated_limit, remaining, ioc_filled)
        self._session_ladder_escalations += 1
        # Submit the retry IOC. Returns None on failure / no fill — we
        # surface that as escalated=True (we attempted) but no fill so
        # the caller still falls through to maker tail at original.
        retry_result = self._submit_taker(retry_candidate)
        result["escalated"] = True
        result["escalated_limit"] = escalated_limit
        result["escalated_filled"] = (
            (retry_result or {}).get("filled_count", 0))
        return result

    def _maybe_post_maker_tail(self, candidate: Dict, ioc_price: int,
                               remaining: int,
                               ioc_filled: int = 1) -> bool:
        """Post the unfilled IOC remainder as a post_only GTC limit
        if all gates pass. Returns True iff a maker order was placed.

        Gates (any failure → silent skip, no exception):
          1. ioc_filled > 0 (zero fill = phantom book, don't rest)
          2. remaining >= MAKER_TAIL_MIN_REMAINDER
          3. STC >= MAKER_TAIL_MIN_STC_SECONDS
          4. strategy in MAKER_TAIL_ELIGIBLE_STRATEGIES
          5. per-asset cap not breached
          6. global cap not breached
          7. NOT a ladder retry (the original IOC owns the tail)
        """
        # Gate 1: zero fill = phantom-book IOC; don't rest into nothing.
        if ioc_filled <= 0:
            return False
        # Gate 7: ladder retries must not post their own maker tail.
        # The original (outer) IOC's _submit_taker will post the tail
        # at the ORIGINAL price after the retry returns. Letting the
        # retry post its own tail at the ESCALATED price would create
        # two overlapping tails on the same ticker — the spec is one
        # tail at the original price.
        if candidate.get("_is_ladder_retry"):
            return False
        # Gate 2: min remainder.
        if remaining < MAKER_TAIL_MIN_REMAINDER:
            return False
        # Gate 3: min STC.
        stc = candidate.get("seconds_to_close")
        if stc is None or stc < MAKER_TAIL_MIN_STC_SECONDS:
            return False
        # Gate 4: eligible strategy.
        strategy = candidate.get("strategy") or ""
        if strategy not in MAKER_TAIL_ELIGIBLE_STRATEGIES:
            return False
        asset = candidate.get("asset") or "?"
        # Gate 5+6: concurrency caps. Active = entries in
        # self._maker_tails. Per-asset and global checked together so
        # a single pass over the dict suffices.
        per_asset_active = sum(
            1 for r in self._maker_tails.values()
            if r.get("asset") == asset)
        global_active = len(self._maker_tails)
        if per_asset_active >= MAKER_TAIL_MAX_PER_ASSET:
            self._session_maker_tails_skipped_cap += 1
            logging.info(
                "MAKER_TAIL_SKIP_CAP_ASSET: %s asset=%s strategy=%s "
                "per_asset_active=%d cap=%d",
                candidate.get("ticker", "?"), asset, strategy,
                per_asset_active, MAKER_TAIL_MAX_PER_ASSET)
            return False
        if global_active >= MAKER_TAIL_MAX_GLOBAL:
            self._session_maker_tails_skipped_cap += 1
            logging.info(
                "MAKER_TAIL_SKIP_CAP_GLOBAL: %s asset=%s strategy=%s "
                "global_active=%d cap=%d",
                candidate.get("ticker", "?"), asset, strategy,
                global_active, MAKER_TAIL_MAX_GLOBAL)
            return False
        # Submit. post_only=True is critical — never let this become
        # an unintended taker (would cross our own scan-time best ask
        # if the book moved).
        ticker = candidate.get("ticker") or ""
        side = candidate.get("side", "yes")
        client_oid = str(uuid.uuid4())
        _price_kwarg = (
            {"no_price": ioc_price} if side == "no"
            else {"yes_price": ioc_price})
        # Settlement-race gate (defense-in-depth): MAKER_TAIL_MIN_STC_SECONDS
        # currently dominates this check, but if that floor is ever lowered
        # below MIN_ORDER_SUBMIT_STC_S, this prevents the regression.
        if self._should_skip_near_close(candidate):
            self._abort_near_close(candidate, path="maker_tail")
            return False
        try:
            resp = self._client.place_order(
                ticker=ticker, side=side, action="buy",
                count=remaining, client_order_id=client_oid,
                time_in_force="good_till_canceled",
                post_only=True, **_price_kwarg)
        except Exception:
            logging.warning(
                "MAKER_TAIL_PLACE_FAILED: %s asset=%s strategy=%s "
                "count=%d price=%d", ticker, asset, strategy,
                remaining, ioc_price, exc_info=True)
            return False
        if resp is None:
            logging.warning(
                "MAKER_TAIL_PLACE_NONE: %s asset=%s strategy=%s "
                "count=%d price=%d (place_order returned None)",
                ticker, asset, strategy, remaining, ioc_price)
            return False
        order_id = (resp.get("order") or {}).get(
            "order_id", client_oid)
        now_mono = time.monotonic()
        self._maker_tails[order_id] = {
            "asset": asset,
            "ticker": ticker,
            "strategy": strategy,
            "count": remaining,
            "price_cents": ioc_price,
            "client_order_id": client_oid,
            "posted_monotonic": now_mono,
            "expires_monotonic": now_mono + MAKER_TAIL_TTL_SECONDS,
        }
        self._session_maker_tails_posted += 1
        logging.info(
            "MAKER_TAIL_POSTED: %s asset=%s strategy=%s count=%d "
            "price=%d¢ ttl=%ds order_id=%s (per_asset_active=%d "
            "global_active=%d)",
            ticker, asset, strategy, remaining, ioc_price,
            MAKER_TAIL_TTL_SECONDS, order_id,
            per_asset_active + 1, global_active + 1)
        return True

    def _sweep_maker_tails(self) -> None:
        """Cancel any maker tail past its TTL. Called from tick().

        Records are dropped from _maker_tails AFTER the cancel call
        completes (success or failure) — this prevents a leaked record
        if cancel raises, and prevents a permanent lock on the per-
        asset cap if Kalshi 404s the order.
        """
        if not self._maker_tails:
            return
        now = time.monotonic()
        expired_oids = [
            oid for oid, rec in self._maker_tails.items()
            if rec.get("expires_monotonic", 0) <= now]
        for oid in expired_oids:
            rec = self._maker_tails.pop(oid, None)
            if rec is None:
                continue
            try:
                self._client.cancel_order(oid)
            except Exception:
                logging.warning(
                    "MAKER_TAIL_CANCEL_FAILED: order_id=%s ticker=%s "
                    "(record dropped from tracker regardless)",
                    oid, rec.get("ticker", "?"), exc_info=True)
            self._session_maker_tails_cancelled_ttl += 1
            logging.info(
                "MAKER_TAIL_CANCELLED_TTL: order_id=%s ticker=%s "
                "asset=%s strategy=%s age=%.1fs",
                oid, rec.get("ticker", "?"), rec.get("asset", "?"),
                rec.get("strategy", "?"),
                now - rec.get("posted_monotonic", now))

    # ── Fill detection ────────────────────────────────────────────────────

    def _check_for_fill(self, order: Dict) -> Optional[Dict]:
        """Check if order has been filled via REST fills endpoint.

        Tracks seen fill IDs on the order dict to avoid double-counting
        partial fills on consecutive polls.
        """
        min_ts = int(order["submit_time"])
        resp = self._client.get_fills(
            ticker=order["ticker"], min_ts=min_ts
        )
        if LOG_RAW_IOC_FILLS and resp:
            _append_raw_api_journal({
                "kind": "ioc_fills",
                "ticker": order["ticker"],
                "order_id": order.get("order_id"),
                "submit_count": order.get("count"),
                "min_ts": min_ts,
                "resp": resp,
            })
        if not resp or not resp.get("fills"):
            return None

        seen = order.setdefault("_seen_fill_ids", set())
        for fill in resp["fills"]:
            fill_id = fill.get("trade_id") or fill.get("id")
            if not fill_id:
                logging.warning(f"REST fill missing trade_id/id for {order['ticker']} — skipping to avoid double-count")
                continue
            if fill.get("order_id") == order["order_id"] and fill_id not in seen:
                seen.add(fill_id)
                return fill
        return None

    # ── Fill handling ─────────────────────────────────────────────────────

    def _on_fill(self, fill: Dict, order: Dict) -> int:
        """Handle fill: update SQLite, log trade, record position.

        Returns the fill_count so callers can track partial vs complete fills.
        """
        order_id = order["order_id"]
        ticker = order["ticker"]
        candidate = order["candidate"]

        # Extract fill details — prefer FP/dollar fields, fall back to legacy
        raw_fill_count = fp_str_to_int(fill.get("count_fp")) or (fill.get("count") or order["count"])
        remaining = order["count"] - order.get("filled_so_far", 0)
        if raw_fill_count > remaining > 0:
            logging.warning(
                f"Fill count {raw_fill_count} exceeds remaining {remaining} for "
                f"{order['ticker']} — capping to {remaining}")
            fill_count = remaining
        else:
            fill_count = raw_fill_count
        # For NO-side orders, Kalshi returns yes_price as 100-no_price (YES-equivalent),
        # which is NOT the cost paid. Read no_price_dollars/no_price for NO fills.
        if order.get("side") == "no":
            fill_price_d = fill.get("no_price_dollars")
            fill_price = dollars_str_to_cents(fill_price_d) if fill_price_d else (fill.get("no_price") or order["price_cents"])
        else:
            fill_price_d = fill.get("yes_price_dollars")
            fill_price = dollars_str_to_cents(fill_price_d) if fill_price_d else (fill.get("yes_price") or order["price_cents"])

        # Track cumulative fills for partial fill detection
        order["filled_so_far"] = min(
            order.get("filled_so_far", 0) + fill_count,
            order["count"]
        )
        is_complete = order["filled_so_far"] >= order["count"]

        # Update order status only when fully filled
        if is_complete:
            self._state.mark_order_status(order_id, "filled")
        else:
            logging.info(
                f"Partial fill: {ticker} {fill_count}/{order['count']} "
                f"(cumulative {order['filled_so_far']}/{order['count']})")

        # Log fill model sample for ML training
        self._log_fill_model_sample(order, "filled", fill=fill)

        # Track fill latency
        fill_latency = round(time.time() - order["submit_time"], 3)
        try:
            if self._ml:
                self._ml._recent_fill_latencies.append(fill_latency)
                self._ml._session_fill_count += 1
                if not order.get("is_taker", True):
                    self._ml._session_maker_fills += 1
        except Exception:
            logging.debug("Fill latency tracking failed", exc_info=True)
        logging.info(f"Fill latency: {fill_latency:.3f}s ({'taker' if order.get('is_taker') else 'maker'})")

        # Record position in SQLite
        self._state.record_position_from_fill(
            ticker=ticker,
            event_ticker=order["event_ticker"],
            asset=order["asset"],
            side=order.get("side", "yes"),
            count=fill_count,
            price_cents=fill_price,
            strategy=candidate.get("strategy"),
            seconds_to_close=order.get("seconds_to_close_at_submit"),
            fill_latency=fill_latency,
            vol_regime=candidate.get("vol_regime"),
            calibrated_prob=candidate.get("calibrated_prob"),
            edge=candidate.get("edge"),
            kelly_f=candidate.get("kelly_f"),
            is_taker=order.get("is_taker", False),
            fill_source=order.get("fill_source", "rest_poll"),
            execution_method=order.get("execution_method", "maker"),
            escalation_type=candidate.get("escalation_type", "none"),
            maker_price_cents=candidate.get("maker_price_cents"),
            maker_wait_seconds=candidate.get("maker_wait_seconds"),
        )

        # Invalidate scanner balance cache so next tick gets fresh balance
        try:
            if self._ml and hasattr(self._ml, 'scanner'):
                self._ml.scanner._balance_cache = (None, 0.0)
        except Exception:
            pass

        # Log trade with all required fields
        is_taker = order.get("is_taker", False)
        cost_cents = fill_count * fill_price
        fee_cents = calculate_fee(fill_count, fill_price, is_taker=is_taker)

        self._logger.log_trade({
            "ticker": ticker,
            "direction": "yes",
            "price": fill_price,
            "count": fill_count,
            "cost": cost_cents,
            "fee": fee_cents,
            "z_score": candidate.get("z_score"),
            "p_calibrated": candidate.get("calibrated_prob"),
            "balance_at_entry": order["balance_at_entry"],
            "tier": "taker" if is_taker else "maker",
            "is_taker": is_taker,
            "is_panic": order.get("is_panic", False),
            "edge": candidate.get("edge"),
            "kelly_f": candidate.get("kelly_f"),
            "asset": order["asset"],
            "event_ticker": order["event_ticker"],
            "order_id": order_id,
            "client_order_id": order["client_order_id"],
            "strategy_used": candidate.get("strategy"),
            "decision_scores": candidate.get("strategy_scores"),
            "orderbook_snapshot": candidate.get("ob_snapshot"),
        })

        logging.info(
            f"FILL: {ticker} {fill_count}x @ {fill_price}¢ "
            f"({'taker' if is_taker else 'maker'}) "
            f"cost={cost_cents}¢ fee={fee_cents}¢"
            f"{'' if is_complete else ' [PARTIAL ' + str(order['filled_so_far']) + '/' + str(order['count']) + ']'}"
        )

        # Lifecycle snapshot at fill — captures the book left behind after
        # our fill. Pairs with the submit snapshot to expose the book delta
        # and explain N→1 destruction patterns (XRP TM-96 case).
        # source = strategy (uniform vocab with submit event); execution tier
        # (taker/maker) is recoverable via order_id join with positions if needed.
        try:
            self._state.insert_order_lifecycle_snapshot(
                order_id=order_id, ticker=ticker,
                event_type=("fill" if is_complete else "partial_fill"),
                source=candidate.get("strategy"))
        except Exception:
            logging.warning("insert_order_lifecycle_snapshot (fill) failed",
                            exc_info=True)

        # ── Telegram trade alert ────────────────────────────────────────
        if _TELEGRAM and is_complete:
            try:
                _strategy = candidate.get("strategy") or order.get("entry_path", "core")
                _product = candidate.get("product_type", "15m")
                _edge = candidate.get("edge")
                _edge_str = f" edge={_edge:.2%}" if _edge is not None else ""
                _prob = candidate.get("calibrated_prob")
                _prob_str = f" prob={_prob:.1%}" if _prob is not None else ""
                _stc = order.get("seconds_to_close_at_submit")
                _stc_str = f" stc={_stc:.0f}s" if _stc is not None else ""
                _side = order.get("side", "yes").upper()
                _TELEGRAM.send(
                    f"TRADE: {order['asset']} {_side} {fill_count}ct @ {fill_price}c "
                    f"({'taker' if is_taker else 'maker'}) "
                    f"[{_product}/{_strategy}]{_prob_str}{_edge_str}{_stc_str} "
                    f"${cost_cents / 100:.2f}",
                    dedup_key=f"fill_{ticker}")
            except Exception:
                logging.debug("Trade telegram alert failed", exc_info=True)

        # ── Sub-floor fill alert ────────────────────────────────────────
        # Monitor fills below asset's MIN_ENTRY_PRICE. Position is already
        # recorded above — this is monitoring only, never blocks.
        _ASSET_FLOOR_MAP = {
            "BTC": BTC_MIN_ENTRY_PRICE, "ETH": ETH_MIN_ENTRY_PRICE,
            "SOL": SOL_MIN_ENTRY_PRICE, "XRP": XRP_MIN_ENTRY_PRICE,
        }
        _fill_asset = order["asset"]
        _fill_floor = _ASSET_FLOOR_MAP.get(_fill_asset, MIN_ENTRY_PRICE)
        if fill_price < _fill_floor:
            _floor_gap = _fill_floor - fill_price
            _nbbo_at_eval = order.get("price_cents", fill_price)
            logging.warning(
                "SUB_FLOOR_FILL: %s %s %dct @ %dc (floor %dc, gap %dc, NBBO %dc)",
                ticker, _fill_asset, fill_count, fill_price,
                _fill_floor, _floor_gap, _nbbo_at_eval)
            if _TELEGRAM:
                try:
                    _TELEGRAM.send(
                        f"\u26a0\ufe0f SUB-FLOOR FILL: {_fill_asset} {fill_price}c "
                        f"(floor {_fill_floor}c) NBBO={_nbbo_at_eval}c gap={_floor_gap}c "
                        f"{fill_count}ct ${cost_cents / 100:.2f} exposure",
                        dedup_key=f"subfloor_{ticker}")
                except Exception:
                    logging.debug("Sub-floor Telegram alert failed", exc_info=True)

        # Register for confirmation addon evaluation (only on complete fills)
        if is_complete:
            try:
                self._register_addon_eligible(order, fill_price, fill_latency)
            except Exception:
                logging.debug("addon registration failed", exc_info=True)

        return fill_count

    # ── Fill Model Logging ────────────────────────────────────────────────

    def _log_fill_model_sample(self, order: Dict, outcome: str,
                               fill: Optional[Dict] = None,
                               cancel_reason: Optional[str] = None):
        """Write one fill_model_sample to FILL_MODEL_JOURNAL for ML training."""
        try:
            candidate = order.get("candidate", {})
            now = time.time()
            elapsed = now - order["submit_time"]
            fill_latency = round(elapsed, 3) if outcome == "filled" else None
            ob_snap = candidate.get("ob_snapshot", {})

            sample = {
                "type": "fill_model_sample",
                "ts": datetime.datetime.utcnow().isoformat() + "Z",
                "ticker": order["ticker"],
                "asset": order["asset"],
                "outcome": outcome,
                "fill_latency_s": fill_latency,
                "fill_source": order.get("fill_source"),
                # Submission context
                "price_cents": order["price_cents"],
                "fair_value": candidate.get("best_yes_ask"),
                "offset_cents": (candidate.get("best_yes_ask", 0) - order["price_cents"])
                    if candidate.get("best_yes_ask") else None,
                "count": order["count"],
                "post_only": not order.get("is_taker", False),
                # Market context at submission
                "seconds_to_close": order.get("seconds_to_close_at_submit"),
                "vol_regime": candidate.get("vol_regime"),
                "blended_rv": candidate.get("blended_rv"),
                "ask_depth": ob_snap.get("ask_depth"),
                "total_ob_depth": ob_snap.get("total_depth"),
                "spread_at_submit": ob_snap.get("spread"),
                "bid_depth": ob_snap.get("bid_depth"),
                "convergence_velocity": candidate.get("convergence_velocity"),
                "z_score": candidate.get("z_score"),
                "edge": candidate.get("edge"),
                "kelly_f": candidate.get("kelly_f"),
                # Queue tracking
                "queue_position_initial": order.get("queue_position_initial"),
                "queue_position_final": order.get("queue_position"),
                # Execution details
                "execution_method": order.get("execution_method", "maker"),
                "entry_path": order.get("entry_path", "maker"),
                "cancel_reason": cancel_reason,
                "elapsed_seconds": round(elapsed, 1),
                # WS state
                "ws_connected": (self._kalshi_feed.is_connected
                                 if self._kalshi_feed else False),
                # Config stamps for regime-filtered analysis
                "maker_only_threshold": MAKER_ONLY_THRESHOLD,
            }

            with open(FILL_MODEL_JOURNAL, "a") as f:
                f.write(json.dumps(sample) + "\n")
        except Exception:
            logging.debug("fill_model_sample write failed", exc_info=True)

    # ── Confirmation Addon ─────────────────────────────────────────────────

    def _register_addon_eligible(self, order: Dict,
                                actual_fill_price: int = 0,
                                fill_latency: float = 0.0):
        """After a fill, register the position for addon evaluation.

        Uses actual fill price (not maker limit price) and corrects STC
        for fill latency so addon timing is accurate.

        Skips if the fill itself is an addon (prevents recursive registration).
        """
        if not ADDON_ENABLED:
            return
        candidate = order.get("candidate", {})
        # Don't re-register addon fills
        if candidate.get("entry_path") in ("confirmation_addon", "dip_addon", "tm_taker", "bracket_no_taker"):
            return

        ticker = order["ticker"]
        # Use actual execution price, not the submitted limit price
        entry_price = actual_fill_price if actual_fill_price > 0 else order["price_cents"]
        fill_count = order.get("filled_so_far", order["count"])

        # Correct STC: subtract fill latency from submit-time STC
        stc_at_submit = order.get("seconds_to_close_at_submit")
        stc_at_fill = (stc_at_submit - fill_latency) if stc_at_submit is not None else None

        meta = {
            "ticker": ticker,
            "event_ticker": order["event_ticker"],
            "asset": order["asset"],
            "entry_price_cents": entry_price,
            "entry_count": fill_count,
            "fill_time": time.time(),
            "seconds_to_close_at_fill": stc_at_fill,
            "threshold": candidate.get("threshold"),
            "blended_rv": candidate.get("blended_rv"),
            "calibrated_prob": candidate.get("calibrated_prob"),
            "product_type": candidate.get("product_type"),
            "candidate": candidate,
        }
        self._addon_eligible[ticker] = meta
        logging.info(
            "addon_registered: %s entry=%d¢ count=%d stc=%.0f",
            ticker, entry_price, fill_count, stc_at_fill or 0)

    def _check_addon_opportunities(self):
        """Evaluate open positions for confirmation addon. Called from _tick."""
        if OBSERVATION_MODE:
            return  # Never execute addons in observation mode
        if not ADDON_ENABLED or not self._addon_eligible:
            return

        now = time.time()
        expired = []

        for ticker, meta in list(self._addon_eligible.items()):
            # Skip hourly fills — addons are for 15M maker-first price improvement only.
            # Hourly uses fixed-size taker IOC; addon would bypass hourly constraints
            # (price cap, fixed sizing, asset exclusion). (Bug fix: Mar 24 2026)
            if meta.get("product_type") == "hourly":
                expired.append(ticker)
                continue

            # Cleanup: remove entries >5min old
            if now - meta["fill_time"] > 300:
                expired.append(ticker)
                continue

            # Already addon'd this position
            if ticker in self._addon_completed:
                continue

            # Elapsed check
            elapsed = now - meta["fill_time"]
            if elapsed < ADDON_MIN_SECONDS_SINCE_FILL:
                continue

            # STC check
            stc_at_fill = meta.get("seconds_to_close_at_fill")
            if stc_at_fill is None:
                continue
            current_stc = stc_at_fill - elapsed
            if current_stc < ADDON_MIN_STC_REMAINING:
                self._session_addon_skipped += 1
                logging.info(
                    "addon_SKIP_stc: %s stc_remaining=%.0f < %.0f",
                    ticker, current_stc, ADDON_MIN_STC_REMAINING)
                expired.append(ticker)
                continue

            # Get current best ask
            current_ask = self._get_addon_best_ask(ticker)
            if current_ask is None:
                continue  # Deferred to next tick

            # Price improvement check
            improvement = current_ask - meta["entry_price_cents"]
            if improvement < ADDON_MIN_PRICE_IMPROVEMENT:
                continue  # Not enough improvement yet

            # Price cap
            if current_ask > ADDON_MAX_ENTRY_PRICE:
                self._session_addon_skipped += 1
                logging.info(
                    "addon_SKIP_price_cap: %s ask=%d¢ > %d¢",
                    ticker, current_ask, ADDON_MAX_ENTRY_PRICE)
                continue

            # Get current spot price
            asset = meta["asset"]
            spot = self._get_addon_spot(asset)
            if spot is None:
                continue

            # Recalculate probability with current spot and STC
            blended_rv = meta.get("blended_rv")
            try:
                if self._ml and hasattr(self._ml, 'vol'):
                    fresh_vol = self._ml.vol._cache.get(asset)
                    if fresh_vol and fresh_vol.get("blended_rv"):
                        blended_rv = fresh_vol["blended_rv"]
            except Exception:
                pass
            threshold = meta.get("threshold")
            if blended_rv is None or threshold is None:
                continue

            prob_result = ProbabilityEngine.compute(
                spot, threshold, current_stc, blended_rv, asset=asset,
                product_type=meta.get("candidate", {}).get("product_type"))
            cal_prob = prob_result.get("calibrated_prob")
            if cal_prob is None:
                continue

            # Taker edge check
            addon_count = max(1, int(meta["entry_count"] * ADDON_SIZE_FRACTION))
            taker_fee = calculate_taker_fee(addon_count, current_ask)
            net_edge = cal_prob - (current_ask / 100.0) - (taker_fee / (addon_count * 100.0))

            if net_edge < MIN_EDGE_PCT / 100.0:
                self._session_addon_skipped += 1
                logging.info(
                    "addon_SKIP_edge: %s net_edge=%.4f < %.4f ask=%d¢ "
                    "prob=%.4f fee=%d¢",
                    ticker, net_edge, MIN_EDGE_PCT / 100.0,
                    current_ask, cal_prob, taker_fee)
                continue

            # Balance check — addon cost capped at 50% of current balance
            balance = self._get_addon_balance()
            if balance is None:
                continue

            addon_cost = addon_count * current_ask
            max_addon_cost = int(balance * 0.50)
            if addon_cost > max_addon_cost:
                # Reduce count to fit within 50% of balance
                if current_ask > 0:
                    addon_count = max_addon_cost // current_ask
                if addon_count < 1:
                    self._session_addon_skipped += 1
                    logging.info(
                        "addon_SKIP_balance: %s cost=%d¢ > 50%% balance=%d¢",
                        ticker, addon_cost, balance)
                    continue
                addon_cost = addon_count * current_ask
                taker_fee = calculate_taker_fee(addon_count, current_ask)
                net_edge = cal_prob - (current_ask / 100.0) - (taker_fee / (addon_count * 100.0))
                if net_edge < MIN_EDGE_PCT / 100.0:
                    self._session_addon_skipped += 1
                    logging.info(
                        "addon_SKIP_edge_after_resize: %s count=%d edge=%.4f",
                        ticker, addon_count, net_edge)
                    continue

            # All checks passed — execute addon
            filled = self._execute_addon(
                meta, addon_count, current_ask, current_stc,
                cal_prob, net_edge, balance, spot)
            if filled:
                self._addon_completed.add(ticker)

        # Cleanup expired entries
        for t in expired:
            self._addon_eligible.pop(t, None)
        # Also clean completed tickers no longer in eligible
        for t in list(self._addon_completed):
            if t not in self._addon_eligible:
                self._addon_completed.discard(t)

    def _execute_addon(self, meta: Dict, count: int, price: int,
                       stc: float, prob: float, edge: float,
                       balance: int, spot: float) -> bool:
        """Submit taker IOC for confirmation addon. Returns True on fill."""
        ticker = meta["ticker"]
        self._session_addon_attempts += 1

        logging.info(
            "addon_TRIGGER: %s %dx @ %d¢ (entry=%d¢ +%d¢) "
            "stc=%.0f edge=%.4f prob=%.4f balance=%d¢ spot=%.2f",
            ticker, count, price, meta["entry_price_cents"],
            price - meta["entry_price_cents"],
            stc, edge, prob, balance, spot)

        # Build addon candidate for _submit_taker
        addon_candidate = {
            "ticker": ticker,
            "event_ticker": meta["event_ticker"],
            "asset": meta["asset"],
            "best_yes_ask": price,
            "position_size": count,
            "calibrated_prob": prob,
            "edge": edge,
            "seconds_to_close": stc,
            "balance_at_scan": balance,
            "entry_path": "confirmation_addon",
            "strategy": "CONFIRMATION_ADDON",
            "blended_rv": meta.get("blended_rv"),
            "threshold": meta.get("threshold"),
            "vol_regime": meta.get("candidate", {}).get("vol_regime"),
            "z_score": meta.get("candidate", {}).get("z_score"),
            "kelly_f": meta.get("candidate", {}).get("kelly_f"),
            "ob_snapshot": {},
            "original_entry_price": meta["entry_price_cents"],
            "original_entry_count": meta["entry_count"],
            "price_improvement": price - meta["entry_price_cents"],
        }

        if OBSERVATION_MODE:
            logging.info(
                "addon_OBSERVATION: %s %dx @ %d¢ — would submit taker IOC",
                ticker, count, price)
            self._logger.log_execution({
                "action": "addon_observation",
                "ticker": ticker,
                "asset": meta["asset"],
                "price": price,
                "count": count,
                "edge": edge,
                "prob": prob,
                "stc": stc,
                "original_entry_price": meta["entry_price_cents"],
                "price_improvement": price - meta["entry_price_cents"],
            })
            return True

        # Live: submit taker IOC
        result = self._submit_taker(addon_candidate)

        if result is not None:
            self._session_addon_fills += 1
            logging.info(
                "addon_FILLED: %s %dx @ %d¢ (+%d¢ from entry)",
                ticker, count, price,
                price - meta["entry_price_cents"])
            if _TELEGRAM:
                try:
                    _addon_cost = count * price / 100
                    _TELEGRAM.send(
                        f"\u2795 Addon: {meta.get('asset', '?')} {count}ct @ {price}c "
                        f"(${_addon_cost:.2f}, +{price - meta['entry_price_cents']}c slip)")
                except Exception:
                    pass

            self._logger.log_execution({
                "action": "addon_filled",
                "ticker": ticker,
                "asset": meta["asset"],
                "price": price,
                "count": count,
                "edge": edge,
                "prob": prob,
                "stc": stc,
                "original_entry_price": meta["entry_price_cents"],
                "price_improvement": price - meta["entry_price_cents"],
                "balance_after": balance - (count * price) - calculate_taker_fee(count, price),
            })
            return True
        else:
            self._session_addon_unfilled += 1
            self._addon_completed.add(ticker)  # Don't retry — single attempt
            logging.warning(
                "addon_UNFILLED: %s %dx @ %d¢", ticker, count, price)
            self._logger.log_execution({
                "action": "addon_unfilled",
                "ticker": ticker,
                "asset": meta["asset"],
                "price": price,
                "count": count,
            })
            return False

    def _get_addon_best_ask(self, ticker: str) -> Optional[int]:
        """Get best YES ask for ticker via scanner cache, then REST fallback."""
        try:
            scanner = self._ml.scanner if self._ml else None
            if scanner:
                ob_data, _ = scanner._get_orderbook_cached(ticker)
                if ob_data:
                    return OpportunityScanner._best_yes_ask_cents(ob_data)
        except Exception:
            logging.debug("addon orderbook cache lookup failed", exc_info=True)

        # REST fallback
        try:
            ob_resp = self._client.get_orderbook(ticker, depth=5)
            if ob_resp:
                orderbook_fp = ob_resp.get("orderbook_fp")
                if orderbook_fp and self._ml and hasattr(self._ml, 'scanner'):
                    ob_data = self._ml.scanner._convert_orderbook_fp(orderbook_fp)
                else:
                    ob_data = ob_resp.get("orderbook", ob_resp)
                if ob_data:
                    return OpportunityScanner._best_yes_ask_cents(ob_data)
        except Exception:
            logging.debug("addon orderbook REST fallback failed", exc_info=True)
        return None

    def _nbbo_fallback_price(self, candidate: Dict) -> Optional[int]:
        """Return NBBO yes_ask price if candidate passes per-asset gates, else None.

        Called when _get_addon_best_ask() returns None (empty orderbook).
        Uses the NBBO price from scan() (candidate["best_yes_ask"]) which was
        sourced from the market listing's yes_ask field.
        """
        asset = candidate.get("asset", "")
        gate = NBBO_FALLBACK_GATES.get(asset)
        if gate is None:
            return None

        min_price, max_price, max_stc = gate
        nbbo_price = candidate.get("best_yes_ask")
        stc = candidate.get("seconds_to_close")

        if nbbo_price is None:
            return None

        # Price gate
        if nbbo_price < min_price or nbbo_price > max_price:
            logging.info(
                "nbbo_fallback_BLOCKED_price: %s asset=%s price=%dc gate=[%d-%d]",
                candidate.get("ticker", "?"), asset, nbbo_price, min_price, max_price)
            self._session_nbbo_fallback_blocked += 1
            return None

        # STC gate (None = no restriction)
        if max_stc is not None and stc is not None and stc >= max_stc:
            logging.info(
                "nbbo_fallback_BLOCKED_stc: %s asset=%s stc=%.0fs gate=<%.0fs",
                candidate.get("ticker", "?"), asset, stc, max_stc)
            self._session_nbbo_fallback_blocked += 1
            return None

        logging.info(
            "nbbo_fallback_USING: %s asset=%s price=%dc stc=%.0fs",
            candidate.get("ticker", "?"), asset, nbbo_price, stc or 0)
        self._session_nbbo_fallback_attempts += 1
        return nbbo_price

    def _get_addon_spot(self, asset: str) -> Optional[float]:
        """Get current spot price for asset via feed."""
        try:
            if self._ml and hasattr(self._ml, 'scanner'):
                return self._ml.scanner._feed.get_price(asset)
        except Exception:
            logging.debug("addon spot price lookup failed", exc_info=True)
        return None

    def _get_addon_balance(self) -> Optional[int]:
        """Get current balance in cents."""
        try:
            if self._ml and hasattr(self._ml, 'scanner'):
                return self._ml.scanner._get_balance_cached()
        except Exception:
            logging.debug("addon balance lookup failed", exc_info=True)
        # Direct API fallback
        try:
            resp = self._client.get_balance()
            if resp:
                return resp.get("balance") or 0
        except Exception:
            logging.debug("addon balance API fallback failed", exc_info=True)
        return None

    # ── Dip Addon ──────────────────────────────────────────────────────────

    def _check_dip_addon_opportunities(self):
        """Check filled positions for dip buy opportunities.

        Two-tier logging:
          1. Shadow tier (>=50c): Every qualifying dip -> evaluated_opportunities
          2. Live tier (>=87c): Execution path (shadow or real)
        """
        if OBSERVATION_MODE:
            return  # Never execute dip addons in observation mode
        if not DIP_ADDON_ENABLED or not self._addon_eligible:
            return

        now = time.time()

        # Cleanup expired tickers from completed set
        for t in list(self._dip_addon_completed):
            if t not in self._addon_eligible:
                self._dip_addon_completed.discard(t)

        for ticker, meta in list(self._addon_eligible.items()):
            # Already dip-addon'd or expired
            if ticker in self._dip_addon_completed:
                continue
            if now - meta["fill_time"] > 300:
                continue

            # Don't dip-addon on addon fills
            if meta.get("candidate", {}).get("entry_path") in (
                    "confirmation_addon", "dip_addon", "tm_taker", "bracket_no_taker"):
                continue

            # Time checks
            elapsed = now - meta["fill_time"]
            if elapsed < DIP_ADDON_MIN_SECONDS_SINCE_FILL:
                continue

            stc_at_fill = meta.get("seconds_to_close_at_fill")
            if stc_at_fill is None:
                continue
            current_stc = stc_at_fill - elapsed
            if current_stc < DIP_ADDON_MIN_STC_REMAINING:
                continue

            # Get current ask
            current_ask = self._get_addon_best_ask(ticker)
            if current_ask is None:
                continue

            # DIP CHECK: ask must drop >= threshold below entry
            drop = meta["entry_price_cents"] - current_ask
            if drop < DIP_ADDON_MIN_DROP_CENTS:
                continue

            # ── Shared computation (needed by both tiers) ──────────
            asset = meta["asset"]
            spot = self._get_addon_spot(asset)
            if spot is None:
                continue

            blended_rv = meta.get("blended_rv")
            try:
                if self._ml and hasattr(self._ml, 'vol'):
                    fresh_vol = self._ml.vol._cache.get(asset)
                    if fresh_vol and fresh_vol.get("blended_rv"):
                        blended_rv = fresh_vol["blended_rv"]
            except Exception:
                pass

            threshold = meta.get("threshold")
            if blended_rv is None or threshold is None:
                continue

            # Recompute probability at current spot/vol/stc
            prob_result = ProbabilityEngine.compute(
                spot, threshold, current_stc, blended_rv, asset=asset,
                product_type=meta.get("candidate", {}).get("product_type"))
            cal_prob = prob_result.get("calibrated_prob")
            if cal_prob is None:
                continue

            # Sizing (computed once, used by both tiers)
            addon_count = max(1, int(
                meta["entry_count"] * DIP_ADDON_SIZE_FRACTION))
            taker_fee = calculate_taker_fee(addon_count, current_ask)
            net_edge = (cal_prob - (current_ask / 100.0)
                        - (taker_fee / (addon_count * 100.0)))

            # ── TIER 1: Shadow observation (50c floor) ─────────────
            if current_ask >= DIP_ADDON_SHADOW_FLOOR:
                self._session_dip_addon_shadow += 1
                # OFT signals for dip addon
                _dip_oft_db = {}
                if self._kalshi_oft is not None:
                    try:
                        _dip_koft = self._kalshi_oft.get_signals(ticker)
                        if _dip_koft:
                            _dip_oft_db = {
                                "oft_prob_adjustment": _dip_koft.get("prob_adjustment"),
                                "oft_imbalance_ratio": _dip_koft.get("imbalance_ratio"),
                                "oft_n_snapshots": _dip_koft.get("n_snapshots"),
                            }
                    except Exception:
                        pass
                try:
                    self._state.insert_evaluated_opportunity(
                        ticker=ticker,
                        event_ticker=meta["event_ticker"],
                        asset=asset,
                        filter_stage="dip_addon_shadow",
                        spot_price=spot,
                        threshold=threshold,
                        volatility=blended_rv,
                        market_price=current_ask,
                        seconds_to_close=current_stc,
                        calibrated_prob=cal_prob,
                        edge=net_edge,
                        strategy="DIP_ADDON_SHADOW",
                        position_size=addon_count,
                        z_score=meta.get("candidate", {}).get("z_score"),
                        vol_regime=meta.get("candidate", {}).get(
                            "vol_regime"),
                        raw_prob=prob_result.get("raw_prob"),
                        fee_adjusted_edge=net_edge,
                        counterfactual=(
                            "entry=%dc drop=%dc orig_count=%d"
                            % (meta["entry_price_cents"], drop,
                               meta["entry_count"])),
                        product_type="dip_addon_shadow",
                        hourly_pre_temp_prob=None, hourly_applied_temp_t=None,
                        hourly_shadow_temp_2_0=None, hourly_shadow_temp_1_0=None,
                        hourly_shadow_temp_2_5=None, hourly_shadow_blend_50=None,
                        hourly_shadow_temp_1_75=None, hourly_shadow_temp_3_0=None,
                        hourly_shadow_blend_20=None, hourly_shadow_blend_30=None,
                        hourly_shadow_blend_60=None, hourly_post_temp_prob=None,
                        **_dip_oft_db,
                    )
                except Exception:
                    logging.debug("dip_addon shadow DB insert failed",
                                  exc_info=True)

                logging.info(
                    "dip_addon_SHADOW_OBS: %s ask=%dc entry=%dc drop=%dc "
                    "edge=%.4f prob=%.4f stc=%.0f count=%d",
                    ticker, current_ask, meta["entry_price_cents"], drop,
                    net_edge, cal_prob, current_stc, addon_count)

            # ── TIER 2: Live execution path (87c floor) ────────────
            # Mark completed after shadow log — one observation per ticker
            self._dip_addon_completed.add(ticker)

            if current_ask < DIP_ADDON_MIN_ENTRY_PRICE:
                logging.info("dip_addon_SKIP_floor: %s ask=%dc < %dc",
                             ticker, current_ask, DIP_ADDON_MIN_ENTRY_PRICE)
                continue

            # Edge check
            if net_edge < MIN_EDGE_PCT / 100.0:
                self._session_dip_addon_skipped += 1
                logging.info(
                    "dip_addon_SKIP_edge: %s edge=%.4f ask=%dc prob=%.4f",
                    ticker, net_edge, current_ask, cal_prob)
                continue

            # Balance + combined exposure check
            balance = self._get_addon_balance()
            if balance is None:
                continue

            original_cost = meta["entry_count"] * meta["entry_price_cents"]
            addon_cost = addon_count * current_ask
            total_exposure = original_cost + addon_cost
            max_allowed = int(
                (balance + original_cost) * DIP_ADDON_MAX_TOTAL_RISK)
            if total_exposure > max_allowed:
                addon_count = max(
                    0, (max_allowed - original_cost) // current_ask)
                if addon_count < 1:
                    self._session_dip_addon_skipped += 1
                    logging.info(
                        "dip_addon_SKIP_exposure: %s total=%dc > %dc",
                        ticker, total_exposure, max_allowed)
                    continue
                addon_cost = addon_count * current_ask
                taker_fee = calculate_taker_fee(addon_count, current_ask)
                net_edge = (cal_prob - (current_ask / 100.0)
                            - (taker_fee / (addon_count * 100.0)))
                if net_edge < MIN_EDGE_PCT / 100.0:
                    continue

            # ── EXECUTE (or shadow-log the live tier) ──────────────
            self._session_dip_addon_attempts += 1

            if DIP_ADDON_SHADOW_MODE:
                logging.info(
                    "dip_addon_LIVE_SHADOW: %s %dx @ %dc (entry=%dc -%dc) "
                    "stc=%.0f edge=%.4f prob=%.4f bal=%dc",
                    ticker, addon_count, current_ask,
                    meta["entry_price_cents"], drop, current_stc,
                    net_edge, cal_prob, balance)
                self._logger.log_execution({
                    "action": "dip_addon_live_shadow",
                    "ticker": ticker, "asset": asset,
                    "entry_price": meta["entry_price_cents"],
                    "dip_price": current_ask, "drop_cents": drop,
                    "addon_count": addon_count, "edge": net_edge,
                    "prob": cal_prob, "stc": current_stc,
                    "balance": balance,
                })
                return  # One per tick

            # LIVE: taker IOC, single attempt
            logging.info(
                "dip_addon_TRIGGER: %s %dx @ %dc (entry=%dc -%dc) "
                "stc=%.0f edge=%.4f prob=%.4f bal=%dc",
                ticker, addon_count, current_ask,
                meta["entry_price_cents"], drop, current_stc,
                net_edge, cal_prob, balance)

            addon_candidate = {
                "ticker": ticker,
                "event_ticker": meta["event_ticker"],
                "asset": asset,
                "best_yes_ask": current_ask,
                "position_size": addon_count,
                "calibrated_prob": cal_prob,
                "edge": net_edge,
                "seconds_to_close": current_stc,
                "balance_at_scan": balance,
                "entry_path": "dip_addon",
                "strategy": "DIP_ADDON",
                "blended_rv": blended_rv,
                "threshold": threshold,
                "vol_regime": meta.get("candidate", {}).get("vol_regime"),
                "z_score": meta.get("candidate", {}).get("z_score"),
                "kelly_f": meta.get("candidate", {}).get("kelly_f"),
                "ob_snapshot": {},
                "original_entry_price": meta["entry_price_cents"],
                "original_entry_count": meta["entry_count"],
                "price_drop": drop,
            }

            result = self._submit_taker(addon_candidate)
            if result is not None:
                self._session_dip_addon_fills += 1
                logging.info("dip_addon_FILLED: %s %dx @ %dc (-%dc)",
                             ticker, addon_count, current_ask, drop)
                if _TELEGRAM:
                    try:
                        _cost = addon_count * current_ask / 100
                        _TELEGRAM.send(
                            f"Dip addon: {asset} {addon_count}ct "
                            f"@ {current_ask}c "
                            f"(${_cost:.2f}, -{drop}c from entry)")
                    except Exception:
                        pass
            else:
                logging.warning("dip_addon_UNFILLED: %s %dx @ %dc",
                                ticker, addon_count, current_ask)
            return  # One per tick max

    # ── Cancel ────────────────────────────────────────────────────────────

    # Allowed sources for _handle_cancel_404 (round-5/6/7 reviews).
    # Bad source values are logged + downgraded to "unknown" rather
    # than raising — _tick_one's broad except would swallow an
    # AssertionError and leave the asset stuck.
    # See kb/decisions/cancel-404-fix-v2-design-may04.md
    _CANCEL_404_SOURCES = ("direct", "reconciliation")

    def _handle_cancel_404(self, order: Dict, asset: str,
                           reason: str, source: str) -> bool:
        """Handle a 404 from cancel API.

        404 *should* mean Kalshi already expired/canceled the order.
        Verify defensively via get_orders to guard against
        wrong-order-id / caller bugs (the conservative cancel_pending
        branch's original purpose).

        Args:
            order: Order dict in self._active_orders[asset].
            asset: Asset key (BTC/ETH/SOL/XRP).
            reason: Free-form trigger label (close_approaching, timeout,
                escalation_*, cancel_pending_retry). Threaded into
                cancel_reason for forensics.
            source: One of _CANCEL_404_SOURCES. Unknown values logged
                and downgraded to "unknown" — must not block the pop.

        Returns True if popped (caller may submit replacement).
        Returns False if held conservatively (order still resting on
        Kalshi — something is wrong).

        Note: pop happens BEFORE audit writes (mark_order_status,
        log_order, _log_fill_model_sample, update_evaluated_opportunity_order)
        so audit failures cannot resurrect the lockout. Of those four,
        only mark_order_status is un-self-guarded (can raise
        sqlite3.OperationalError); the others catch internally
        (bot/_impl.py:2716, 23630, 5089).
        """
        if source not in self._CANCEL_404_SOURCES:
            logging.error(
                f"_handle_cancel_404 unknown source={source!r} — "
                f"falling back to 'unknown' to keep pop priority")
            source = "unknown"
        self._cancel_404_count += 1
        filled = order.get("filled_so_far", 0)

        # Defensive verify: 404 should mean the order is gone, but
        # confirm via get_orders before popping. Three failure modes:
        #   (a) get_orders raises → exception path → log + pop
        #   (b) get_orders returns None (breaker OPEN) → log + pop
        #   (c) get_orders shows order resting → HOLD cancel_pending
        try:
            orders_resp = self._client.get_orders(ticker=order["ticker"])
            if orders_resp is None:
                logging.warning(
                    f"cancel_404_verify_unavailable: {order['ticker']} "
                    f"from {source} — get_orders returned None "
                    f"(breaker open?), falling through to pop.")
            elif orders_resp:
                for o in orders_resp.get("orders", []):
                    if (o.get("order_id") == order["order_id"]
                            and o.get("status") in ("resting", "open")):
                        logging.error(
                            f"cancel_404_but_resting: {order['ticker']} "
                            f"{order['order_id']} from {source} — "
                            f"Kalshi 404'd cancel but order still in "
                            f"/orders. Holding cancel_pending for retry.")
                        order["cancel_pending"] = True
                        return False
        except Exception:
            logging.warning(
                f"cancel_404_verify_failed: {order['ticker']} from "
                f"{source} — falling through to pop based on 404 signal",
                exc_info=True)

        # Preserve partial-fill labeling (kalshi_fill_simulator.py
        # treats partial_canceled as label=1).
        if filled > 0:
            db_status = "partial_canceled"
            outcome = "partial_filled"
            fm_label = "partial_canceled"
        else:
            db_status = "expired"
            outcome = "expired"
            fm_label = "expired"

        cancel_reason_str = f"kalshi_404_{source}_{reason}"

        # POP FIRST. Audit writes must NOT be a prerequisite to the
        # pop — if any audit write raises, the asset would stay stuck
        # and re-create the May 4 lockout.
        self._active_orders.pop(asset, None)

        # Of the four audit writes, only mark_order_status is un-self-
        # guarded (can raise sqlite3.OperationalError on lock
        # contention). log_order/_log_fill_model_sample/
        # update_evaluated_opportunity_order catch internally
        # (bot/_impl.py:2716, 23630, 5089). Single outer try is
        # belt-and-suspenders defense-in-depth — primary protection
        # is the pop above.
        try:
            self._state.mark_order_status(order["order_id"], db_status)
            self._logger.log_order({
                "action": "maker_canceled",
                "ticker": order["ticker"],
                "order_id": order["order_id"],
                "reason": cancel_reason_str,
                "elapsed": round(time.time() - order["submit_time"], 1),
                "filled_so_far": filled,
            })
            self._log_fill_model_sample(
                order, fm_label, cancel_reason=cancel_reason_str)
            if asset not in self._escalating_assets:
                self._state.update_evaluated_opportunity_order(
                    order["ticker"], order_outcome=outcome)
        except Exception:
            logging.error(
                f"cancel_404_audit_failed: {order['ticker']} "
                f"{order['order_id']} — pop already complete, audit "
                f"writes incomplete.",
                exc_info=True)

        logging.warning(
            f"cancel_404_already_gone: {order['ticker']} "
            f"{order['order_id']} filled={filled}/{order['count']} "
            f"from {source} (session count: {self._cancel_404_count})")
        return True

    def _cancel_order(self, asset: str, reason: str) -> bool:
        """Cancel the active maker order for a specific asset.

        Returns True if cancel succeeded (safe to submit replacement).
        Returns False if cancel API failed (order may still be live).
        """
        order = self._active_orders.get(asset)
        if order is None:
            return True  # nothing to cancel

        filled = order.get("filled_so_far", 0)

        cancel_resp = self._client.cancel_order(order["order_id"])
        if cancel_resp is None:
            logging.error(f"Cancel API FAILED for {order['order_id']} — order may still be resting on exchange")
            # Don't mark canceled in DB — order may still be live on Kalshi
            order["cancel_pending"] = True
            # Do NOT pop — order may still be live, prevent double position
            return False

        # 404 sentinel — Kalshi has aged out the order. Route through
        # _handle_cancel_404 (defensive verify + pop-first + correct
        # labeling). See kb/failures/cancel-404-asset-lockout-may04.md
        if isinstance(cancel_resp, dict) and cancel_resp.get("_status_code") == 404:
            return self._handle_cancel_404(order, asset, reason, source="direct")

        # Normal success
        status = "partial_canceled" if filled > 0 else "canceled"
        self._state.mark_order_status(order["order_id"], status)

        # Log fill model sample for canceled order
        self._log_fill_model_sample(order, "canceled", cancel_reason=reason)

        self._logger.log_order({
            "action": "maker_canceled",
            "ticker": order["ticker"],
            "order_id": order["order_id"],
            "reason": reason,
            "elapsed": round(time.time() - order["submit_time"], 1),
            "filled_so_far": filled,
        })
        logging.info(
            f"Maker order canceled: {order['ticker']} reason={reason}"
            f"{' (partial fill: ' + str(filled) + '/' + str(order['count']) + ')' if filled > 0 else ''}"
        )
        self._active_orders.pop(asset, None)
        # Update order outcome — skip if escalating (escalation handler sets outcome)
        if asset not in self._escalating_assets:
            _outcome = "partial_filled" if filled > 0 else "canceled"
            self._state.update_evaluated_opportunity_order(
                order["ticker"], order_outcome=_outcome)
        return True

    def _cancel_active(self, reason: str):
        """Cancel all active maker orders. Used by _reprice_maker compat."""
        for asset in list(self._active_orders):
            self._cancel_order(asset, reason)


# ═════════════════════════════════════════════════════════════════════════════
#  SettlementTracker
# ═════════════════════════════════════════════════════════════════════════════

class SettlementTracker:
    """Incremental settlement poller. API is the single source of truth.

    Polls GET /portfolio/settlements?min_ts={last_check} every 30 seconds.
    On settlement: look up trade in SQLite, record WIN/LOSS from market_result,
    calculate net P&L from revenue, log to settlement_journal.jsonl, update
    running balance.

    Never uses z-score heuristics or balance deltas to determine outcomes.
    """

    def __init__(self, client: KalshiClient, state: StateManager,
                 logger: Logger, main_loop=None):
        self._client = client
        self._state = state
        self._logger = logger
        self._ml = main_loop
        self._last_check_ts: int = 0
        self._last_poll_time: float = 0.0
        self._last_fallback_sweep: float = 0.0
        self._last_order_cleanup: float = 0.0
        self._processed_tickers: Set[str] = set()
        self._pending_rejection_tickers: Set[str] = set()
        self._settled_rejection_tickers: Set[str] = set()
        # Re-entry guard for tick() worker thread. Prevents thread
        # pile-up if a settlement cycle takes longer than
        # SETTLEMENT_CHECK_SECONDS. Apr 25 00:39 incident: synchronous
        # tick was 4.84-5.54s per cycle; threading the body restores
        # main-loop cadence.
        self._worker_running: bool = False

    # ── Startup ──────────────────────────────────────────────────────────

    def startup(self):
        """Initialize watermark to 24h ago, load dedup set, sweep once."""
        self._last_check_ts = int(
            (datetime.datetime.now(timezone.utc) - datetime.timedelta(hours=24)).timestamp()
        )
        self._load_processed_tickers()
        self._load_pending_rejections()
        self._poll()

    def _load_pending_rejections(self):
        """Load unsettled rejected tickers from DB."""
        rows = self._state.get_unsettled_rejections()
        self._pending_rejection_tickers = {r["ticker"] for r in rows}
        logging.info(
            f"SettlementTracker: loaded {len(self._pending_rejection_tickers)} "
            f"pending rejected opportunities"
        )

    def _load_processed_tickers(self):
        """Load already-settled tickers from DB for deduplication."""
        rows = self._state.conn.execute(
            "SELECT ticker FROM settled_trades"
        ).fetchall()
        self._processed_tickers = {row["ticker"] for row in rows}
        logging.info(
            f"SettlementTracker: loaded {len(self._processed_tickers)} "
            f"previously settled tickers"
        )

    # ── Tick (called every main-loop iteration) ──────────────────────────

    def tick(self):
        """Self-throttled: only polls every SETTLEMENT_CHECK_SECONDS.

        The tick body runs in a daemon worker thread to keep the main
        scan loop unblocked. With 400+ pending evaluated_opportunities
        rows, the synchronous version was 4.84-5.54s per cycle (Apr 25
        00:39 SLOW_SCAN_TICK incident). The `_worker_running` flag
        prevents thread pile-up if a cycle exceeds the throttle.
        """
        now = time.time()
        if now - self._last_poll_time < SETTLEMENT_CHECK_SECONDS:
            return
        if self._worker_running:
            # Previous worker still running; skip this cycle. The
            # next call after _last_poll_time advances will spawn fresh.
            return
        self._last_poll_time = now
        self._worker_running = True

        def _worker():
            try:
                self._poll()
                self._poll_rejections()
                self._poll_evaluated_opportunities()
                # Fallback: sweep for positions stuck past market close (every 5 min)
                _wn = time.time()
                if _wn - self._last_fallback_sweep >= 300.0:
                    self._last_fallback_sweep = _wn
                    self._sweep_stuck_positions()
                # Cleanup expired resting orders (every 60s)
                if _wn - self._last_order_cleanup >= 60.0:
                    self._last_order_cleanup = _wn
                    try:
                        self._state.cleanup_expired_resting_orders()
                    except Exception:
                        logging.debug("cleanup_expired_resting_orders failed",
                                      exc_info=True)
            except Exception:
                logging.error("SettlementTracker worker thread failed",
                              exc_info=True)
            finally:
                self._worker_running = False

        try:
            threading.Thread(
                target=_worker,
                daemon=True,
                name="settlement_tracker",
            ).start()
        except Exception:
            self._worker_running = False
            logging.debug(
                "SettlementTracker worker thread spawn failed",
                exc_info=True)

    # ── Core poll ────────────────────────────────────────────────────────

    def _poll(self):
        """Fetch new settlements from API and process them."""
        unsettled = self._state.get_unsettled_positions()
        if not unsettled:
            return

        resp = self._client.get_settlements(min_ts=self._last_check_ts)
        if LOG_RAW_SETTLEMENTS and resp:
            _append_raw_api_journal({
                "kind": "settlements",
                "min_ts": self._last_check_ts,
                "resp": resp,
            })
        if not resp or "settlements" not in resp:
            return

        settlements = resp["settlements"]
        if not settlements:
            return

        our_tickers = {p["ticker"] for p in unsettled}
        processed_any = False

        for s in settlements:
            ticker = s.get("ticker", "")

            # Skip if already processed (dedup)
            if ticker in self._processed_tickers:
                continue

            # Only process settlements for our open positions
            if ticker not in our_tickers:
                continue

            try:
                self._process_settlement(s)
                processed_any = True
            except Exception as e:
                logging.error(f"Settlement processing failed for {ticker}: {e}", exc_info=True)

        # Advance watermark to now (even if nothing processed, to shrink window)
        self._last_check_ts = int(datetime.datetime.now(timezone.utc).timestamp())

        # Refresh balance after processing settlements
        if processed_any:
            balance_resp = self._client.get_balance()
            if balance_resp:
                new_balance = balance_resp.get("balance") or 0
                logging.info(
                    f"Balance after settlements: ${new_balance / 100:.2f}"
                )
            # Invalidate scanner balance cache so next tick's record_balance()
            # gets post-settlement balance. Without this, the 10s cache TTL
            # causes record_balance to record stale pre-settlement balance,
            # compressing drawdown_scaler for one tick. (Learned: 33% of
            # candidates got ds<1.0 from stale cache, Mar 29-30 2026.)
            try:
                if self._ml and hasattr(self._ml, 'scanner'):
                    self._ml.scanner._balance_cache = (None, 0.0)
            except Exception:
                pass

    # ── Fallback sweep for stuck positions ───────────────────────────────

    def _sweep_stuck_positions(self):
        """Detect positions whose market close time has passed and settle via
        individual market lookup.  This catches positions that were skipped by
        the watermark-based settlement poll (e.g. unknown market_result at the
        time, revenue=0 on WIN timing race, etc.).
        """
        import re
        _MONTH_MAP = {"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
                       "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12}
        unsettled = self._state.get_unsettled_positions()
        if not unsettled:
            return
        now_utc = datetime.datetime.now(timezone.utc).replace(tzinfo=None)
        for pos in unsettled:
            ticker = pos["ticker"]
            if ticker in self._processed_tickers:
                continue
            # Parse close time from 15M ticker format
            m = re.match(r'KX\w+15M-(\d{2})([A-Z]{3})(\d{2})(\d{2})(\d{2})-', ticker)
            if not m:
                continue  # Non-15M — hourly/weather have different settlement paths
            yy, mon, dd, hh, mm = m.groups()
            mon_num = _MONTH_MAP.get(mon)
            if not mon_num:
                continue
            try:
                close_et = datetime.datetime(2000 + int(yy), mon_num, int(dd), int(hh), int(mm))
                close_utc = close_et + datetime.timedelta(hours=4)  # ET→UTC (EDT)
            except (ValueError, OverflowError):
                continue
            # Only sweep if market closed >5 min ago (allow normal settlement path time)
            if now_utc < close_utc + datetime.timedelta(minutes=5):
                continue
            # Fetch market result directly from API
            try:
                mkt = self._client.get_market(ticker)
                if not mkt or "market" not in mkt:
                    continue
                market_data = mkt["market"]
                result = market_data.get("result", "")
                if not result:
                    continue  # Not yet settled on Kalshi
                # Capture expiration_value (CFB RTI settlement price) for divergence analysis
                _exp_val = market_data.get("expiration_value")
                logging.warning(
                    "sweep_stuck_positions: recovering %s (result=%s, "
                    "close_utc=%s, stuck >5min, expiration_value=%s)",
                    ticker, result, close_utc, _exp_val)
                # Build a synthetic settlement dict and process it.
                # _from_sweep=True tells _process_settlement to skip the
                # revenue=0/WIN guard (we compute PnL from first principles).
                settlement = {
                    "ticker": ticker,
                    "market_result": result,
                    "revenue_dollars": None,
                    "revenue": 0,
                    "settled_time": market_data.get("close_time", ""),
                    "_from_sweep": True,
                    "_expiration_value": _exp_val,
                }
                self._process_settlement(settlement)
            except Exception as e:
                logging.error("sweep_stuck_positions failed for %s: %s", ticker, e, exc_info=True)

    # ── Process a single settlement ──────────────────────────────────────

    def _process_settlement(self, settlement: Dict):
        """Record outcome, P&L, and log to journal.

        Handles stacked positions: fetches ALL position rows for the ticker,
        computes per-row PnL from first principles, records each to settled_trades,
        then marks all settled in one UPDATE.
        """
        ticker = settlement["ticker"]
        market_result = settlement.get("market_result", "")
        rev_d = settlement.get("revenue_dollars")
        revenue = dollars_str_to_cents(rev_d) if rev_d else (settlement.get("revenue") or 0)

        # Look up ALL position rows for this ticker
        pos_rows = self._state.conn.execute(
            "SELECT * FROM positions WHERE ticker=?", (ticker,)
        ).fetchall()
        if not pos_rows:
            logging.warning(
                f"SettlementTracker: no position found for {ticker}"
            )
            return
        positions = [dict(r) for r in pos_rows]
        is_stacked = len(positions) > 1

        # Determine WIN/LOSS from market_result only (API is truth)
        side = positions[0]["side"]
        if market_result == "yes":
            outcome = "WIN" if side == "yes" else "LOSS"
        elif market_result == "no":
            outcome = "WIN" if side == "no" else "LOSS"
        elif market_result == "all_no":
            outcome = "WIN" if side == "no" else "LOSS"
        elif market_result == "all_yes":
            outcome = "WIN" if side == "yes" else "LOSS"
        else:
            outcome = "UNKNOWN"
            logging.critical(
                f"UNKNOWN market_result '{market_result}' for {ticker} "
                f"— skipping settlement to prevent bad P&L recording"
            )
            return

        # Aggregate count across all position rows for cross-checks
        aggregate_count = sum(p["count"] for p in positions)
        aggregate_cost = sum(p["total_cost_cents"] for p in positions)

        # Cross-check: revenue=0 on a WIN is almost certainly a false position.
        # Skip this guard for sweep-recovered settlements — they always have
        # revenue=0 and compute PnL from first principles.
        from_sweep = settlement.get("_from_sweep", False)
        if outcome == "WIN" and revenue == 0 and aggregate_count > 0 and not from_sweep:
            logging.critical(
                f"SETTLEMENT REVENUE ZERO ON WIN {ticker}: "
                f"market_result={market_result} side={side} count={aggregate_count} "
                f"cost={aggregate_cost}¢ fill_source={positions[0].get('fill_source')} — "
                f"Kalshi likely has no matching position. "
                f"Skipping settlement to prevent false -{aggregate_cost}¢ loss.")
            return

        # Cross-check: detect count mismatch between internal tracking
        # and Kalshi settlement.  For YES wins, revenue = real_count * 100.
        if revenue > 0 and outcome == "WIN" and side == "yes":
            implied_count = revenue // 100
            if implied_count != aggregate_count:
                logging.error(
                    f"SETTLEMENT COUNT MISMATCH {ticker}: "
                    f"internal={aggregate_count} kalshi={implied_count} "
                    f"revenue={revenue}¢ n_rows={len(positions)}")
                if implied_count == 0 and aggregate_count > 0:
                    # Sub-dollar revenue (1-99¢) floors to 0 contracts under
                    # `revenue // 100`. Auto-zeroing a confirmed-filled
                    # position on the basis of a sub-dollar revenue value is
                    # almost always wrong: it fabricates a $0 settled_trade
                    # and silently diverges local cost tracking from reality.
                    # Trust the local fill record; alert and fall through to
                    # per-row PnL computed from first principles.
                    # (Learned: KXXRP15M-26APR241200-00 141ct WIN and
                    # KXSOL15M-26APR230200-00 32ct WIN both silently zeroed
                    # Apr 23-24 2026.)
                    logging.critical(
                        f"SETTLEMENT_REVENUE_SUB_DOLLAR {ticker}: "
                        f"kalshi_revenue={revenue}¢ implied_count=0 vs "
                        f"internal={aggregate_count} — REFUSING to auto-zero. "
                        f"Trusting local count; investigate Kalshi payload.")
                    if _TELEGRAM:
                        try:
                            _TELEGRAM.send(
                                f"🚨 SETTLEMENT_REVENUE_SUB_DOLLAR {ticker}: "
                                f"Kalshi revenue={revenue}¢ on "
                                f"{aggregate_count}ct WIN — refused auto-zero. "
                                f"Check journal for payload.")
                        except Exception:
                            pass
                elif len(positions) == 1:
                    # Single row: auto-correct with strategy_group
                    p = positions[0]
                    sg = p.get("strategy_group", "main")
                    corrected_cost = implied_count * p["avg_price_cents"]
                    self._state.conn.execute(
                        "UPDATE positions SET count=?, total_cost_cents=? "
                        "WHERE ticker=? AND strategy_group=?",
                        (implied_count, corrected_cost, ticker, sg))
                    p["count"] = implied_count
                    p["total_cost_cents"] = corrected_cost
                    aggregate_count = implied_count
                    aggregate_cost = corrected_cost
                else:
                    logging.warning(
                        "SETTLEMENT_MULTI_MISMATCH: %s — NOT auto-correcting stacked positions",
                        ticker)

        # Cross-check on LOSSES: revenue=0 gives no count info, so fetch the
        # authoritative fill count from Kalshi's fills API. Catches IOC-path
        # double-count bugs that the WIN-side check can't see.
        # (Learned: XRP 06:15 Apr 19 2026 recorded 208ct local vs 104ct Kalshi
        # -> $99 over-reported loss; 1 of 2 divergent in 30d/48 IOC losses.)
        if outcome == "LOSS" and len(positions) == 1 and positions[0].get("is_taker"):
            try:
                _fresp = self._client.get_fills(ticker=ticker, limit=200)
                if LOG_RAW_IOC_FILLS and _fresp:
                    _append_raw_api_journal({
                        "kind": "loss_check_fills",
                        "ticker": ticker,
                        "aggregate_count": aggregate_count,
                        "resp": _fresp,
                    })
                if _fresp and _fresp.get("fills"):
                    _local_order_ids = set()
                    for _r in self._state.conn.execute(
                        "SELECT order_id FROM pending_orders WHERE ticker=?",
                        (ticker,)
                    ).fetchall():
                        _oid = _r["order_id"] if isinstance(_r, sqlite3.Row) else _r[0]
                        if _oid:
                            _local_order_ids.add(_oid)
                    _kalshi_count = 0
                    for _f in _fresp["fills"]:
                        if _f.get("order_id") in _local_order_ids:
                            _c = fp_str_to_int(_f.get("count_fp")) or int(_f.get("count") or 0)
                            _kalshi_count += _c
                    if _kalshi_count > 0 and _kalshi_count != aggregate_count:
                        logging.error(
                            f"SETTLEMENT_LOSS_COUNT_MISMATCH {ticker}: "
                            f"internal={aggregate_count} kalshi={_kalshi_count} "
                            f"(loss-side cross-check) — auto-correcting")
                        p = positions[0]
                        sg = p.get("strategy_group", "main")
                        corrected_cost = _kalshi_count * p["avg_price_cents"]
                        self._state.conn.execute(
                            "UPDATE positions SET count=?, total_cost_cents=? "
                            "WHERE ticker=? AND strategy_group=?",
                            (_kalshi_count, corrected_cost, ticker, sg))
                        p["count"] = _kalshi_count
                        p["total_cost_cents"] = corrected_cost
                        aggregate_count = _kalshi_count
                        aggregate_cost = corrected_cost
            except Exception:
                logging.warning(
                    "Loss-side count cross-check failed for %s", ticker,
                    exc_info=True)

        # Process each position row independently
        combined_pnl = 0
        combined_fee = 0
        now = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
        for pos in positions:
            row_count = pos["count"]
            row_cost = pos["total_cost_cents"]
            # Revenue from first principles: WIN yes-side → count*100, LOSS → 0
            if outcome == "WIN":
                if side == "yes":
                    row_revenue = row_count * 100
                else:
                    row_revenue = row_count * 100  # NO-side win: paid (100-p), get 100
            else:
                row_revenue = 0
            row_pnl = row_revenue - row_cost
            row_is_taker = bool(pos.get("is_taker"))
            row_fee = calculate_fee(row_count, pos["avg_price_cents"], is_taker=row_is_taker)

            combined_pnl += row_pnl
            combined_fee += row_fee

            # Record each row to settled_trades (revenue_override prevents
            # stacked positions from each getting the full API aggregate revenue)
            self._state.record_settlement(
                settlement, revenue_override=row_revenue,
                pnl_override=row_pnl, fee_override=row_fee, pos=pos)

        # Mark ALL positions for this ticker as settled (once, outside loop)
        self._state.conn.execute("""
            UPDATE positions SET status='settled', updated_at=?
            WHERE ticker=?
        """, (now, ticker))
        self._state.conn.commit()

        # Mark as processed for dedup (once)
        self._processed_tickers.add(ticker)

        # Fetch expiration_value (CFB RTI settlement price) for divergence analysis.
        # For sweep settlements, it's already in the settlement dict.
        # For normal settlements, one extra API call (non-blocking, after PnL recorded).
        _exp_val = settlement.get("_expiration_value")
        if _exp_val is None:
            try:
                _exp_mkt = self._client.get_market(ticker)
                if _exp_mkt:
                    _exp_val = _exp_mkt.get("market", _exp_mkt).get("expiration_value")
            except Exception:
                pass
        if _exp_val is not None:
            logging.info("EXPIRATION_VALUE: %s expiration_value=%s asset=%s",
                         ticker, _exp_val, positions[0]["asset"])

        # Rich journal entry with combined PnL
        self._logger.log_settlement({
            "ticker": ticker,
            "event_ticker": positions[0]["event_ticker"],
            "asset": positions[0]["asset"],
            "outcome": outcome,
            "market_result": market_result,
            "side": side,
            "count": aggregate_count,
            "entry_price_cents": positions[0]["avg_price_cents"],
            "total_cost_cents": aggregate_cost,
            "revenue_cents": revenue,
            "fee_cents": combined_fee,
            "pnl_cents": combined_pnl,
            "pnl_net_cents": combined_pnl - combined_fee,
            "settled_time": settlement.get("settled_time", ""),
            "is_stacked": is_stacked,
            "n_positions": len(positions),
            "expiration_value": _exp_val,
        })

        stacked_tag = f" [STACKED x{len(positions)}]" if is_stacked else ""
        logging.info(
            f"Settlement: {ticker} -> {outcome}{stacked_tag} "
            f"(market_result={market_result}, "
            f"revenue={revenue}¢, cost={aggregate_cost}¢, "
            f"pnl={combined_pnl}¢, fee={combined_fee}¢)"
        )
        if _TELEGRAM:
            emoji = "\u2705" if outcome == "WIN" else "\u274c"
            sign = "+" if combined_pnl >= 0 else ""
            pnl_dollars = combined_pnl / 100
            bal_str = ""
            try:
                bal_resp = self._client.get_balance()
                if bal_resp:
                    bal_str = f" | Balance: ${bal_resp.get('balance', 0) / 100:.2f}"
            except Exception:
                pass
            _TELEGRAM.send(
                f"{emoji} {outcome} {positions[0]['asset']} {aggregate_count}ct "
                f"@{positions[0]['avg_price_cents']}c {sign}${abs(pnl_dollars):.2f}"
                f"{stacked_tag}{bal_str}"
            )

    # ── Rejection Settlement ─────────────────────────────────────────────

    def register_rejection_ticker(self, ticker: str):
        """Called by scanner when a new rejection is recorded."""
        self._pending_rejection_tickers.add(ticker)

    def _poll_rejections(self):
        """Check if any rejected-opportunity tickers have settled."""
        # Refresh from DB to pick up rejections inserted by scanner since last poll
        db_rows = self._state.get_unsettled_rejections()
        for r in db_rows:
            self._pending_rejection_tickers.add(r["ticker"])

        if not self._pending_rejection_tickers:
            return

        # Snapshot to iterate safely
        tickers_to_check = list(
            self._pending_rejection_tickers - self._settled_rejection_tickers
        )
        for ticker in tickers_to_check:
            try:
                resp = self._client.get_market(ticker)
                if not resp:
                    continue
                market = resp.get("market", resp)
                result = market.get("result", "")
                if result:
                    self._process_rejection_settlement(market, ticker)
            except Exception as e:
                logging.warning(
                    f"Rejection settlement check failed for {ticker}: {e}", exc_info=True)

    def _process_rejection_settlement(self, market: Dict, ticker: str):
        """Compute counterfactual P&L for a rejected opportunity that settled."""
        result = market.get("result", "")

        # Look up the rejection row from SQLite
        row = self._state.conn.execute(
            "SELECT * FROM rejected_opportunities WHERE ticker=?", (ticker,)
        ).fetchone()
        if not row:
            return

        entry_price = row["market_price"]
        # If we never had a market price (pre-filter rejection), skip P&L calc
        if entry_price is None:
            would_have_profit = None
            assumed_fee = 0
            counterfactual_outcome = "unknown_no_price"
        else:
            # Counterfactual: bought 1 YES contract at entry_price (include taker fee)
            # Note: rejected_opportunities are always YES-side. NO-side goes through
            # evaluated_opportunities which has its own side-aware settlement in
            # _poll_evaluated_opportunities().
            assumed_fee = calculate_taker_fee(1, int(entry_price))
            if result in ("yes", "all_yes"):
                would_have_profit = (100 - entry_price) - assumed_fee  # cents
                counterfactual_outcome = "would_have_won"
            elif result in ("no", "all_no"):
                would_have_profit = -(entry_price + assumed_fee)  # cents
                counterfactual_outcome = "would_have_lost"
            else:
                would_have_profit = None
                counterfactual_outcome = f"unknown_result_{result}"

        cf_json = json.dumps({
            "outcome": counterfactual_outcome,
            "would_have_profit_cents": would_have_profit,
            "assumed_fee_cents": assumed_fee,
            "entry_price": entry_price,
        })

        self._logger.log_rejection({
            "type": "rejection_settlement",
            "ticker": ticker,
            "event_ticker": row["event_ticker"],
            "asset": row["asset"],
            "rejection_reason": row["rejection_reason"],
            "market_result": result,
            "entry_price_if_traded": entry_price,
            "counterfactual_outcome": counterfactual_outcome,
            "would_have_profit_cents": would_have_profit,
            "assumed_fee_cents": assumed_fee,
            "assumed_contracts": 1,
            "z_score": row["z_score"],
            "spot_price": row["spot_price"],
            "threshold": row["threshold"],
        })

        self._state.mark_rejection_settled(ticker, market_result=result,
                                           counterfactual=cf_json)
        self._settled_rejection_tickers.add(ticker)
        self._pending_rejection_tickers.discard(ticker)

        logging.info(
            f"Rejection settled: {ticker} -> {counterfactual_outcome} "
            f"(result={result}, would_have_profit={would_have_profit}¢)"
        )

    # ── Evaluated Opportunity Settlement ──────────────────────────────────

    @staticmethod
    def _parse_weather_market_date(ticker: str) -> Optional[str]:
        """Extract the market date from a weather ticker as YYYY-MM-DD.

        Ticker format: KXHIGHNY-26FEB28-T50 → date segment '26FEB28' → '2026-02-28'
        """
        parts = ticker.split("-")
        if len(parts) < 2:
            return None
        raw = parts[1]  # e.g. '26FEB28', '26MAR01', '26MAR03'
        if len(raw) < 7:
            return None
        try:
            dt = datetime.datetime.strptime(raw, "%y%b%d")
            return dt.strftime("%Y-%m-%d")
        except ValueError:
            return None

    @staticmethod
    def _estimate_actual_temp_from_bracket(ticker, threshold, spot_price=None):
        """Estimate actual temperature from a settled weather bracket for bias update.

        B-type: midpoint of bracket (threshold is floor_strike, brackets ~2°F wide)
        T-type: threshold ± 2°F based on tail direction (uses spot_price to disambiguate)
        Returns estimated actual temperature or None.
        """
        parts = ticker.split("-")
        if len(parts) < 3:
            return None
        strike_part = parts[-1]
        if strike_part.startswith("B"):
            # Bracket: threshold is floor_strike, bracket ~2°F wide → midpoint
            return threshold + 1.0
        elif strike_part.startswith("T"):
            # Tail: use spot_price (ensemble mean at evaluation time) to determine direction
            if spot_price is not None:
                if threshold < spot_price:
                    return threshold - 2.0  # lower tail: actual below threshold
                else:
                    return threshold + 2.0  # upper tail: actual above threshold
            return None  # can't determine tail direction without spot_price
        return None

    def _poll_evaluated_opportunities(self):
        """Check if any evaluated opportunities have settled for counterfactual tracking.
        Groups rows by ticker to avoid redundant API calls and batches DB commits."""
        try:
            rows = self._state.get_unsettled_evaluated_opportunities()
        except Exception as e:
            logging.warning(f"get_unsettled_evaluated_opportunities failed: {e}", exc_info=True)
            return

        if not rows:
            return

        # Volume warning — high pending count means observation modes are flooding the table
        if len(rows) > 50:
            logging.warning(
                "eval_opp_settlement: %d pending rows (>50 threshold) — "
                "check observation mode volume (weather=%d, hourly=%d, spx=%d, sports=%d, 15m=%d)",
                len(rows),
                sum(1 for r in rows if r.get("product_type") == "weather"),
                sum(1 for r in rows if r.get("product_type") == "hourly"),
                sum(1 for r in rows if r.get("product_type") == "spx_hourly"),
                sum(1 for r in rows if r.get("product_type") == "sports"),
                sum(1 for r in rows if r.get("product_type") == "15m"),
            )

        # Group rows by ticker — one API call per unique ticker
        from collections import defaultdict
        ticker_groups: dict = defaultdict(list)
        for row in rows:
            ticker_groups[row["ticker"]].append(row)

        # Fetch market result once per unique ticker
        ticker_results: dict = {}
        for ticker in ticker_groups:
            try:
                resp = self._client.get_market(ticker)
                if not resp:
                    continue
                market = resp.get("market", resp)
                result = market.get("result", "")
                if result:
                    ticker_results[ticker] = result
            except Exception as e:
                logging.warning(f"get_market failed for {ticker}: {e}")

        if not ticker_results:
            return

        logging.info("eval_opp_settlement: %d unique tickers settled (from %d pending rows)",
                     len(ticker_results), len(rows))

        # ── Phase 1: Compute settlement results in memory (NO DB writes) ──
        # This avoids holding a write lock during the computation + JSONL logging.
        # Each entry: (opp_id, ticker, result, row, would_have_profit, counterfactual_outcome,
        #              count, taker_fee, maker_fee, pnl_taker, pnl_maker)
        _settlement_batch: list = []
        _cal_observations: list = []  # (raw_p, cal_binary, _opp_pt, asset, filter_stage)
        _weather_updates: list = []   # (opp_id, ticker, row) — need API calls, done after commit
        for ticker, result in ticker_results.items():
            for row in ticker_groups[ticker]:
                opp_id = row["id"]
                try:
                    entry_price = row["market_price"]
                    _opp_pt = row.get("product_type")
                    if entry_price is None:
                        would_have_profit = None
                        taker_fee = 0
                        maker_fee = 0
                        pnl_taker = None
                        pnl_maker = None
                        count = row.get("position_size") or 1
                        counterfactual_outcome = "unknown_no_price"
                    elif _opp_pt == "weather" and entry_price < WEATHER_MIN_ENTRY_PRICE:
                        count = row.get("position_size") or 1
                        would_have_profit = 0
                        counterfactual_outcome = "untradeable_price"
                        taker_fee = 0
                        maker_fee = 0
                        pnl_taker = 0
                        pnl_maker = 0
                    else:
                        count = row.get("position_size") or 1
                        taker_fee = calculate_taker_fee(count, int(entry_price))
                        maker_fee = calculate_maker_fee(count, int(entry_price))
                        _opp_side = row.get("side") or "yes"
                        if _opp_side == "no":
                            _is_win = result in ("no", "all_no")
                            _is_loss = result in ("yes", "all_yes")
                        else:
                            _is_win = result in ("yes", "all_yes")
                            _is_loss = result in ("no", "all_no")
                        if _is_win:
                            pnl_taker = (100 - entry_price) * count - taker_fee
                            pnl_maker = (100 - entry_price) * count - maker_fee
                            counterfactual_outcome = "would_have_won"
                        elif _is_loss:
                            pnl_taker = -(entry_price * count + taker_fee)
                            pnl_maker = -(entry_price * count + maker_fee)
                            counterfactual_outcome = "would_have_lost"
                        else:
                            pnl_taker = None
                            pnl_maker = None
                            taker_fee = 0
                            maker_fee = 0
                            counterfactual_outcome = f"unknown_result_{result}"
                        would_have_profit = pnl_taker

                    # JSONL logging (no DB write)
                    self._logger.log_rejection({
                        "type": "evaluated_settlement",
                        "ticker": ticker,
                        "event_ticker": row["event_ticker"],
                        "asset": row["asset"],
                        "filter_stage": row["filter_stage"],
                        "rejection_reason": row.get("rejection_reason"),
                        "market_result": result,
                        "entry_price_if_traded": entry_price,
                        "counterfactual_outcome": counterfactual_outcome,
                        "would_have_profit_cents": would_have_profit,
                        "assumed_contracts": count,
                        "taker_fee_cents": taker_fee,
                        "maker_fee_cents": maker_fee,
                        "pnl_taker_cents": pnl_taker,
                        "pnl_maker_cents": pnl_maker,
                        "calibrated_prob": row.get("calibrated_prob"),
                        "edge": row.get("edge"),
                        "strategy": row.get("strategy"),
                        "position_size": row.get("position_size"),
                        "kelly_f": row.get("kelly_f"),
                        "vol_regime": row.get("vol_regime"),
                        "z_score": row.get("z_score"),
                        "raw_prob": row.get("raw_prob"),
                        "calibration_method": row.get("calibration_method"),
                        "fee_adjusted_edge": row.get("fee_adjusted_edge"),
                        "old_system_prob": row.get("old_system_prob"),
                    })

                    _settlement_batch.append((opp_id, ticker, result, row,
                                              would_have_profit, counterfactual_outcome))

                    # Prepare CalEngine observations
                    raw_p = row.get("raw_prob")
                    filter_stage = row.get("filter_stage", "")
                    _opp_side = row.get("side") or "yes"
                    if (raw_p is not None and _opp_side == "yes"
                            and result in ("yes", "all_yes", "no", "all_no")
                            and not filter_stage.endswith("_v2")):
                        cal_binary = 1 if result in ("yes", "all_yes") else 0
                        _cal_observations.append((raw_p, cal_binary, _opp_pt,
                                                  row.get("asset"), filter_stage,
                                                  row.get("seconds_to_close")))

                    # Queue weather temp fetches for after commit
                    if (_opp_pt == "weather" and result in ("yes", "all_yes", "no", "all_no")
                            and row.get("wx_actual_high_temp") is None):
                        _weather_updates.append((opp_id, ticker, row))

                    logging.info(
                        f"Evaluated opp settled: {ticker} ({row['filter_stage']}) "
                        f"-> {counterfactual_outcome} (profit={would_have_profit}¢)"
                    )
                except Exception as e:
                    logging.warning(f"Evaluated opp settlement check failed for {ticker}: {e}", exc_info=True)

        # ── Phase 2: Fast DB writes (short lock, no API calls) ──
        # Commit in chunks of 50 to keep write-lock duration short.
        # Large batches (200+) hold the lock long enough to deadlock with
        # supabase_sync reader + WAL checkpoint. (Mar 16 2026)
        _SETTLEMENT_BATCH_SIZE = 50
        _settled_count = 0
        if _settlement_batch:
            for _chunk_start in range(0, len(_settlement_batch), _SETTLEMENT_BATCH_SIZE):
                _chunk = _settlement_batch[_chunk_start:_chunk_start + _SETTLEMENT_BATCH_SIZE]
                try:
                    for (opp_id, ticker, result, row,
                         would_have_profit, counterfactual_outcome) in _chunk:
                        self._state.mark_evaluated_opportunity_settled(
                            opp_id, market_result=result,
                            counterfactual_pnl=would_have_profit,
                            commit=False)
                        _settled_count += 1
                    self._state.conn.commit()
                except Exception as e:
                    try:
                        self._state.conn.rollback()
                    except Exception:
                        pass
                    logging.warning("eval_opp_settlement batch commit failed (chunk %d-%d): %s",
                                    _chunk_start, _chunk_start + len(_chunk), e, exc_info=True)
            if _settled_count:
                logging.info("eval_opp_settlement: committed %d rows in %d chunks",
                             _settled_count,
                             (len(_settlement_batch) + _SETTLEMENT_BATCH_SIZE - 1) // _SETTLEMENT_BATCH_SIZE)

        # ── Phase 3: Post-commit work (CalEngine, shadow settlement, weather) ──
        # These run AFTER the write lock is released.

        # Feed CalEngine observations
        for _cal_item in _cal_observations:
            raw_p, cal_binary, _opp_pt, _asset, filter_stage = _cal_item[0], _cal_item[1], _cal_item[2], _cal_item[3], _cal_item[4]
            _cal_stc = _cal_item[5] if len(_cal_item) > 5 else None
            _settle_engine = _resolve_cal_engine(_opp_pt, _asset)
            if _settle_engine is not None:
                _settle_engine.add_observation(raw_p, cal_binary, filter_stage=filter_stage,
                                              seconds_to_close=_cal_stc)
            # Dual-feed: 15M per-asset engines AND global engine (keeps shadow pipeline working)
            if _opp_pt in (None, "15m") and _CALIBRATION_ENGINE is not None:
                _CALIBRATION_ENGINE.add_observation(raw_p, cal_binary, seconds_to_close=_cal_stc)
            elif (_settle_engine is None
                  and filter_stage in ("candidate", "observation_trade",
                                       "hourly_observation", "spx_observation",
                                       "weather_observation")
                  and get_market_config(_opp_pt).cal_eligible):
                if _CALIBRATION_ENGINE is not None:
                    _CALIBRATION_ENGINE.add_observation(raw_p, cal_binary)

        # Settle shadow signals (per unique settled ticker)
        for ticker, result in ticker_results.items():
            if result not in ("yes", "all_yes", "no", "all_no"):
                continue
            if self._ml and getattr(self._ml, "fifteenm_shadow", None):
                try:
                    self._ml.fifteenm_shadow.settle_signals(ticker, result)
                except Exception:
                    logging.warning("fifteenm_shadow settle failed for %s", ticker, exc_info=True)

            if self._ml and getattr(self._ml, "hourly_alt_shadow", None):
                try:
                    self._ml.hourly_alt_shadow.settle_signals(ticker, result)
                except Exception:
                    logging.warning("hourly_alt_shadow settle failed for %s", ticker, exc_info=True)

            if self._ml and getattr(self._ml, "spx_harrv_shadow", None):
                try:
                    self._ml.spx_harrv_shadow.settle_signals(ticker, result)
                except Exception:
                    logging.warning("spx_harrv_shadow settle failed for %s", ticker, exc_info=True)

            # Settle SOL Path C shadow entry for this ticker
            try:
                _pc_row = self._state.conn.execute(
                    "SELECT * FROM sol_pathc_shadow WHERE ticker=? AND status='pending'",
                    (ticker,)).fetchone()
                if _pc_row:
                    _pc = dict(_pc_row)
                    _is_win = result in ("yes", "all_yes")
                    _live_price = _pc["live_entry_price"]
                    _live_contracts = _pc["live_contracts"]
                    _pos_size = _pc["position_size"]

                    _live_fee = calculate_taker_fee(_live_contracts, _live_price)
                    if _is_win:
                        _live_pnl = (100 - _live_price) * _live_contracts - _live_fee
                    else:
                        _live_pnl = -(_live_price * _live_contracts + _live_fee)

                    _maker_price = _pc["pathc_maker_price"]
                    _maker_depth = _pc["pathc_depth_at_maker"] or 0
                    _maker_touched = _pc["obs_maker_price_touched"] or 0
                    _maker_contracts = min(_pos_size, _maker_depth) if _maker_touched else 0
                    _maker_fee = calculate_maker_fee(_maker_contracts, _maker_price) if _maker_contracts > 0 else 0
                    if _maker_contracts > 0:
                        if _is_win:
                            _maker_pnl = (100 - _maker_price) * _maker_contracts - _maker_fee
                        else:
                            _maker_pnl = -(_maker_price * _maker_contracts + _maker_fee)
                    else:
                        _maker_pnl = 0

                    _esc_ask = _pc["pathc_esc_ask"]
                    _esc_depth = _pc["pathc_esc_depth"] or 0
                    if _esc_ask is not None and _esc_depth > 0:
                        _esc_contracts = min(_pos_size, _esc_depth)
                        _esc_fee = calculate_taker_fee(_esc_contracts, _esc_ask)
                        if _is_win:
                            _esc_pnl = (100 - _esc_ask) * _esc_contracts - _esc_fee
                        else:
                            _esc_pnl = -(_esc_ask * _esc_contracts + _esc_fee)
                    else:
                        _esc_contracts = 0
                        _esc_pnl = 0

                    if _maker_touched and _maker_contracts > 0:
                        _remainder = max(0, _pos_size - _maker_contracts)
                        if _remainder > 0 and _esc_ask is not None and _esc_depth > 0:
                            _rem_contracts = min(_remainder, _esc_depth)
                            _rem_fee = calculate_taker_fee(_rem_contracts, _esc_ask)
                            if _is_win:
                                _rem_pnl = (100 - _esc_ask) * _rem_contracts - _rem_fee
                            else:
                                _rem_pnl = -(_esc_ask * _rem_contracts + _rem_fee)
                        else:
                            _rem_pnl = 0
                        _best_pnl = _maker_pnl + _rem_pnl
                    else:
                        _best_pnl = _esc_pnl

                    self._state.settle_sol_pathc_shadow(
                        ticker=ticker, market_result=result,
                        live_pnl=_live_pnl,
                        pathc_maker_pnl=_maker_pnl,
                        pathc_maker_contracts=_maker_contracts,
                        pathc_esc_pnl=_esc_pnl,
                        pathc_esc_contracts=_esc_contracts,
                        pathc_best_pnl=_best_pnl)
                    logging.info(
                        "sol_pathc_settled: %s result=%s live_pnl=%d maker_pnl=%d esc_pnl=%d best_pnl=%d",
                        ticker, result, _live_pnl, _maker_pnl, _esc_pnl, _best_pnl)
            except Exception:
                logging.warning("sol_pathc_shadow settle failed for %s", ticker, exc_info=True)

        # Settle low_price_shadow_signals
        for ticker, result in ticker_results.items():
            if result not in ("yes", "all_yes", "no", "all_no"):
                continue
            try:
                _lps_rows = self._state.conn.execute(
                    "SELECT id, market_price, full_kelly_contracts, capped_contracts "
                    "FROM low_price_shadow_signals WHERE ticker=? AND status='open'",
                    (ticker,)).fetchall()
                for _lps in _lps_rows:
                    _lps_id = _lps["id"]
                    _lps_price = _lps["market_price"]
                    _is_win = result in ("yes", "all_yes")
                    # Full Kelly PnL
                    _full_ct = _lps["full_kelly_contracts"] or 1
                    _full_fee = calculate_taker_fee(_full_ct, _lps_price)
                    if _is_win:
                        _full_pnl = (100 - _lps_price) * _full_ct - _full_fee
                    else:
                        _full_pnl = -(_lps_price * _full_ct + _full_fee)
                    # Capped Kelly PnL
                    _cap_ct = _lps["capped_contracts"] or 1
                    _cap_fee = calculate_taker_fee(_cap_ct, _lps_price)
                    if _is_win:
                        _cap_pnl = (100 - _lps_price) * _cap_ct - _cap_fee
                    else:
                        _cap_pnl = -(_lps_price * _cap_ct + _cap_fee)
                    self._state.conn.execute(
                        "UPDATE low_price_shadow_signals SET status='settled', "
                        "market_result=?, counterfactual_pnl_full=?, counterfactual_pnl_capped=?, "
                        "settled_at=? WHERE id=?",
                        (result, _full_pnl, _cap_pnl,
                         datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ"),
                         _lps_id))
                if _lps_rows:
                    self._state.conn.commit()
            except Exception:
                logging.warning("low_price_shadow settle failed for %s", ticker, exc_info=True)

        # Settle tm_sweep_shadow rows. Reuses the same ticker_results aggregation
        # as low_price_shadow above. Idempotent — only acts on rows with
        # status='open', so safe if this method is invoked repeatedly.
        if TM_SWEEP_SHADOW_ENABLED:
            for ticker, result in ticker_results.items():
                if result not in ("yes", "all_yes", "no", "all_no"):
                    continue
                try:
                    self._state.update_tm_sweep_shadow_on_settlement(ticker, result)
                except Exception:
                    logging.warning("tm_sweep_shadow settle failed for %s", ticker, exc_info=True)

        # Weather: fetch actual temps (API calls — after lock released)
        _wx_dirty = False
        for (opp_id, ticker, row) in _weather_updates:
            try:
                _wx_city = row["asset"].replace("_TEMP", "")
                _market_date = self._parse_weather_market_date(ticker)
                if _market_date:
                    _today = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%d")
                    if _market_date < _today:
                        _wx_eng = getattr(self._ml, "weather_engine", None) if self._ml else None
                        if _wx_eng:
                            _obs_high = _wx_eng._fetcher.fetch_observed_high(_wx_city, _market_date)
                            if _obs_high is not None:
                                self._state.conn.execute(
                                    "UPDATE evaluated_opportunities SET wx_actual_high_temp=? WHERE id=?",
                                    (_obs_high, opp_id))
                                _wx_dirty = True
                                logging.info("weather_observed_temp: %s %s %.1fF",
                                             _wx_city, _market_date, _obs_high)
                                forecast_mean = row.get("spot_price")
                                if forecast_mean:
                                    _wx_eng._model.update_bias(
                                        _wx_city, _obs_high, forecast_mean,
                                        market_date=_market_date)
                                    logging.info("weather_bias_update: %s %s actual=%.1fF forecast=%.1fF",
                                                 _wx_city, _market_date, _obs_high, forecast_mean)
            except Exception as e:
                logging.warning("weather_observed_temp fetch failed for %s: %s", ticker, e)
        if _wx_dirty:
            self._state.conn.commit()

        # Backfill wx_actual_high_temp for settled weather entries that missed it
        self._backfill_weather_actual_temps()

    def _backfill_weather_actual_temps(self):
        """Retry archive API fetch for settled weather entries missing wx_actual_high_temp."""
        try:
            rows = self._state.conn.execute(
                "SELECT id, ticker, asset, spot_price FROM evaluated_opportunities "
                "WHERE product_type='weather' AND status='settled' "
                "AND wx_actual_high_temp IS NULL LIMIT 10"
            ).fetchall()
        except Exception:
            return
        if not rows:
            return
        _today = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%d")
        _wx_eng = getattr(self._ml, "weather_engine", None) if self._ml else None
        if not _wx_eng:
            return
        for r in rows:
            opp_id, ticker, asset, forecast_mean = r
            try:
                _wx_city = asset.replace("_TEMP", "")
                _market_date = self._parse_weather_market_date(ticker)
                if not _market_date or _market_date >= _today:
                    continue
                _obs_high = _wx_eng._fetcher.fetch_observed_high(_wx_city, _market_date)
                if _obs_high is not None:
                    self._state.conn.execute(
                        "UPDATE evaluated_opportunities SET wx_actual_high_temp=? WHERE id=?",
                        (_obs_high, opp_id))
                    self._state.conn.commit()
                    logging.info("weather_backfill_temp: %s %s %.1fF", _wx_city, _market_date, _obs_high)
                    # Bias update with real observed temp
                    if forecast_mean:
                        _wx_eng._model.update_bias(
                            _wx_city, _obs_high, forecast_mean,
                            market_date=_market_date)
            except Exception as e:
                logging.warning("weather_backfill failed for %s: %s", ticker, e)


# ═════════════════════════════════════════════════════════════════════════════
#  Market Discovery
# ═════════════════════════════════════════════════════════════════════════════

def discover_active_windows(client: KalshiClient) -> List[Dict]:
    """
    Query Kalshi for currently open crypto windows (15M + hourly).

    Uses the events endpoint (GET /events) with status=open and
    with_nested_markets=true to find tradeable markets. The markets
    endpoint (GET /markets) with series_ticker only returns pre-created
    'initialized' markets on production, missing the active ones.

    Returns list of dicts with asset, event_ticker, close_time,
    seconds_to_close, markets list, and product_type.
    """
    now = datetime.datetime.now(timezone.utc)
    windows: List[Dict] = []

    # Build combined series list: 15M always, hourly when enabled
    series_list = [(a, s, "15m") for a, s in SERIES_TICKERS.items()]
    if HOURLY_OBSERVATION_ENABLED:
        series_list += [(a, s, "hourly") for a, s in HOURLY_SERIES_TICKERS.items()]

    for asset, series, product_type in series_list:
        result = client.get_events(
            series_ticker=series,
            status="open",
            with_nested_markets=True,
            limit=100,
        )
        events = result.get("events") if result else None
        if not events:
            logging.warning(
                f"Market discovery: {asset} ({series}) — API returned no data"
            )
            continue
        market_count = 0

        for event in events:
            event_ticker = event.get("event_ticker", "")
            nested_markets = event.get("markets", [])
            if not isinstance(nested_markets, list):
                continue

            # Filter to actual market dicts (not string references)
            mkts = [m for m in nested_markets if isinstance(m, dict)]
            if not mkts:
                continue

            market_count += len(mkts)

            close_time_str = mkts[0].get("close_time", "")
            try:
                close_time = datetime.datetime.fromisoformat(
                    close_time_str.replace("Z", "+00:00")
                )
            except (ValueError, AttributeError):
                continue

            seconds_to_close = (close_time - now).total_seconds()
            if seconds_to_close < 0:
                continue
            windows.append({
                "asset": asset,
                "event_ticker": event_ticker,
                "close_time": close_time,
                "seconds_to_close": seconds_to_close,
                "markets": mkts,
                "product_type": product_type,
            })

        if market_count == 0:
            logging.info(
                f"Market discovery: {asset} ({series}) — 0 open markets"
            )
        else:
            logging.info(
                f"Market discovery: {asset} ({series}) — "
                f"{market_count} markets in {len(events)} windows"
            )

    return windows


# ═════════════════════════════════════════════════════════════════════════════
#  MainLoop
# ═════════════════════════════════════════════════════════════════════════════

class MainLoop:
    """Continuous observation loop. Scans active windows every second."""

    def __init__(self):
        api_key = os.environ.get("KALSHI_API_KEY") or os.environ.get("KALSHI_API_KEY_ID", "")
        private_key_path = os.environ.get("KALSHI_PRIVATE_KEY_PATH", "")
        if not api_key or not private_key_path:
            logging.critical(
                "KALSHI_API_KEY (or KALSHI_API_KEY_ID) and KALSHI_PRIVATE_KEY_PATH must be set"
            )
            sys.exit(1)

        # Loud one-time log of HPSB gate state — distinguishes "VPS env lost the
        # var so gate silently re-disabled" from "no candidates hit the cell" in
        # the absence of HPSB_DROP rows. Grep journal weekly for HPSB_GATE_STATE.
        logging.warning(
            "HPSB_GATE_STATE: enabled=%s bleeders=%s missing_bleeder_strings=%s validator_unavailable=%s",
            HIGH_PRICE_STC_BLOCK_ENABLED,
            sorted(HIGH_PRICE_STC_BLOCK_BLEEDER_STRATEGIES),
            _HPSB_MISSING_BLEEDERS or "none",
            _HPSB_VALIDATOR_UNAVAILABLE_REASON or "no")

        self.client = KalshiClient(api_key, private_key_path)
        self.state = StateManager()
        self.logger = Logger()
        self.feed = CoinbaseFeed()
        self.dvol_fetcher = DeribitDVOLFetcher()
        self.egarch_estimator = EGARCHEstimator()
        self.mz_tracker = MincerZarnowitzTracker()
        self.vol = VolatilityEngine(self.feed, dvol_fetcher=self.dvol_fetcher,
                                    egarch_estimator=self.egarch_estimator,
                                    mz_tracker=self.mz_tracker)
        self.sizer = PositionSizer()
        self.calibration = CalibrationEngine()
        global _CALIBRATION_ENGINE
        _CALIBRATION_ENGINE = self.calibration

        # Per-market CalEngines via registry
        global _CAL_REGISTRY
        _CAL_REGISTRY.clear()  # defensive: ensure clean state on restart
        self._cal_engines = {}
        self._cal_engine_meta = {}  # reg_key → (product_type, subtype_code_or_None)

        for _pt, _cfg in MARKET_CONFIGS.items():
            if _cfg.cal_subtypes:
                # Per-subtype engines (weather cities, sports groups, 15M per-asset)
                # 15M engines train on candidates + cell-block shadow rows.
                # R-bleed-1 R9-H1: bleed-cell blocks intercept candidates and write
                # them under their cell tag instead of 'candidate'. Without
                # including those tags here, the CalEngines stop receiving the
                # observations from EXACTLY the cells we just gated — silently
                # narrowing training signal where the calibrator most needs it.
                _stages = (
                    ("candidate", "observation_trade",
                     HIGH_PRICE_STC_BLOCK_FILTER_STAGE,
                     TM98_HIGHPRICE_BLEED_BLOCK_FILTER_STAGE,
                     SOL_TAKER_LOWPRICE_BLEED_BLOCK_FILTER_STAGE)
                    if _pt == "15m" else None
                )
                for _sub_code, _sub_path in _cfg.cal_subtypes.items():
                    _reg_key = f"{_pt}_{_sub_code}"
                    assert _sub_path != CALIBRATION_STATE_PATH, (
                        f"FATAL: {_reg_key} would share state file with 15M engine!")
                    _engine = CalibrationEngine(
                        state_path=_sub_path,
                        label=f"{_pt.capitalize()}_{_sub_code}Cal",
                        accepted_stages=_stages)
                    self._cal_engines[_reg_key] = _engine
                    _CAL_REGISTRY[_reg_key] = _engine
                    self._cal_engine_meta[_reg_key] = (_pt, _sub_code)
                    logging.info("CalEngine registered for '%s' (state: %s, enabled=%s)",
                                 _reg_key, _sub_path, _cfg.cal_engine_enabled)

            elif _cfg.cal_engine_state_path:
                # Single engine per product_type (hourly, spx_hourly)
                # Always instantiate so settlement can collect observations via add_observation().
                # require_enabled gate in _resolve_cal_engine() prevents disabled engines
                # from affecting predictions.
                assert _cfg.cal_engine_state_path != CALIBRATION_STATE_PATH, (
                    f"FATAL: {_pt} would share state file with 15M engine!")
                _engine = CalibrationEngine(
                    state_path=_cfg.cal_engine_state_path,
                    label=f"{_pt.capitalize()}Cal")
                self._cal_engines[_pt] = _engine
                _CAL_REGISTRY[_pt] = _engine
                self._cal_engine_meta[_pt] = (_pt, None)
                logging.info("CalEngine registered for '%s' (state: %s, enabled=%s)",
                             _pt, _cfg.cal_engine_state_path, _cfg.cal_engine_enabled)

            else:
                logging.info("CalEngine DISABLED for '%s': no state path, passthrough", _pt)

        assert "15m" not in _CAL_REGISTRY, "FATAL: 15M engine must never be in _CAL_REGISTRY"

        # Backward compat for dashboard_snapshot.py
        self.hourly_calibration = self._cal_engines.get("hourly")
        tg_token = os.environ.get("TELEGRAM_BOT_TOKEN", "")
        tg_chat = os.environ.get("TELEGRAM_CHAT_ID", "")
        self.telegram = TelegramNotifier(tg_token, tg_chat)
        global _TELEGRAM
        _TELEGRAM = self.telegram
        self.cross_feed = CrossExchangeFeed(self.feed) if CROSS_EXCHANGE_ENABLED else None
        self.coinglass = CoinGlassFetcher()
        self.kalshi_oft = KalshiOrderFlowTracker() if KALSHI_OFT_ENABLED else None
        self.order_flow = OrderFlowEngine(
            cross_feed=self.cross_feed, coinglass=self.coinglass,
            kalshi_oft=self.kalshi_oft,
        )
        # Kalshi WebSocket feed for real-time fills + orderbook
        try:
            self.kalshi_feed = KalshiFeed(api_key, self.client.private_key)
        except Exception as e:
            logging.warning(f"KalshiFeed init failed: {e}")
            self.kalshi_feed = None
        # ── SPX Engine (conditional) ────────────────────────────────────
        self.spx_engine = None
        if SPX_HOURLY_ENABLED:
            try:
                from spx_engine import SPXEngine
                self.spx_engine = SPXEngine(
                    polygon_key=os.environ.get("POLYGON_API_KEY"),
                    finnhub_key=os.environ.get("FINNHUB_API_KEY"),
                )
                logging.info("SPX engine initialized")
            except Exception as e:
                logging.warning(f"SPX engine unavailable: {e}")

        # ── Weather Engine (conditional) ───────────────────────────────────
        self.weather_engine = None
        if WEATHER_ENABLED:
            try:
                from weather_engine import WeatherEngine
                self.weather_engine = WeatherEngine(db_path=DB_PATH)
                logging.info("Weather engine initialized")
            except Exception as e:
                logging.warning(f"Weather engine unavailable: {e}")

        # ── 15M Shadow Engine (recalibrated EGARCH + LightGBM) ─────────
        self.fifteenm_shadow = None
        try:
            from fifteenm_shadow import FifteenMShadowEngine, FIFTEENM_SHADOW_ENABLED
            if FIFTEENM_SHADOW_ENABLED:
                self.fifteenm_shadow = FifteenMShadowEngine(db_path=DB_PATH)
                logging.info("15M shadow engine initialized (recalibrated EGARCH + LightGBM)")
        except Exception as e:
            logging.warning(f"15M shadow engine unavailable: {e}")

        # ── Hourly Alt Shadow Engine (ETH/SOL/XRP shadow strategies) ──────
        self.hourly_alt_shadow = None
        try:
            from hourly_alt_shadow import HourlyAltShadowEngine, HOURLY_ALT_SHADOW_ENABLED
            if HOURLY_ALT_SHADOW_ENABLED and HOURLY_OBSERVATION_ENABLED:
                self.hourly_alt_shadow = HourlyAltShadowEngine(db_path=DB_PATH)
                logging.info("Hourly alt shadow engine initialized (MM + HAR-RV)")
        except Exception as e:
            logging.warning(f"Hourly alt shadow engine unavailable: {e}")

        # ── H-3a Continuous NBBO Snapshotter ─────────────────────────────
        # Periodic in-memory WS orderbook → market_observations_continuous.
        # Foundation for the deferred H-3 fill simulator. Reads existing WS
        # cache (no new REST traffic). Schema migration MUST run from main
        # thread (not the daemon) to avoid racing other ALTER TABLE migrations
        # at startup. Disabled if kalshi_feed unavailable (nothing to read).
        # See kb/decisions/phase-h3-deferred-needs-nbbo-infra-may02.md.
        self.market_obs_snapshotter = None
        try:
            from market_observations_snapshotter import (
                MarketObservationsSnapshotter,
                ensure_schema as _moc_ensure_schema,
                extract_active_15m_tickers as _moc_extract_15m,
            )
            _moc_ensure_schema(self.state.conn)
            # Round-1 wiring #8: defensive capability check. If the WS
            # client is ever refactored and the deep-copy method is
            # renamed, surface that immediately at init rather than
            # producing 8.6K WARNING/day from per-tick AttributeError.
            if (
                self.kalshi_feed is not None
                and hasattr(self.kalshi_feed, "get_all_orderbooks_snapshot")
            ):
                self.market_obs_snapshotter = MarketObservationsSnapshotter(
                    db_path=DB_PATH,
                    ws_client=self.kalshi_feed,
                    active_tickers_provider=lambda: _moc_extract_15m(
                        self._active_windows
                    ),
                )
                logging.info(
                    "Market observations snapshotter initialized "
                    "(H-3a — continuous NBBO capture for fill simulator)"
                )
            elif self.kalshi_feed is not None:
                logging.warning(
                    "Market observations snapshotter not started — "
                    "kalshi_feed missing get_all_orderbooks_snapshot method "
                    "(WS client API drift; review bot/_impl.py vs "
                    "market_observations_snapshotter.py contract)"
                )
        except Exception as e:
            logging.warning(
                f"Market observations snapshotter unavailable: {e}"
            )
            self.market_obs_snapshotter = None

        # ── SPX HAR-RV Shadow Engine ────────────────────────────────────────
        self.spx_harrv_shadow = None
        if SPX_HOURLY_ENABLED:
            try:
                from spx_harrv_shadow import SPXHARRVShadowEngine, SPX_HARRV_SHADOW_ENABLED
                if SPX_HARRV_SHADOW_ENABLED:
                    self.spx_harrv_shadow = SPXHARRVShadowEngine(db_path=DB_PATH)
                    logging.info("SPX HAR-RV shadow engine initialized")
            except Exception as e:
                logging.warning(f"SPX HAR-RV shadow engine unavailable: {e}")

        # ── Sports Engine (conditional) ────────────────────────────────────
        self.sports_engine = None
        if SPORTS_ENABLED:
            try:
                from sports_engine import SportsEngine
                self.sports_engine = SportsEngine(
                    kalshi_client=self.client,
                    state_manager=self.state,
                    db_path=DB_PATH,
                )
                logging.info("Sports engine initialized")
            except Exception as e:
                logging.warning(f"Sports engine unavailable: {e}")

        # ── Capital Allocator (conditional) ────────────────────────────────
        self.capital_allocator = None
        try:
            from capital_allocator import CapitalAllocator
            _obs_strategies = set()
            for _k, _v in MARKET_CONFIGS.items():
                if _v.observation_only:
                    # Capital allocator uses "crypto_hourly" for hourly, product_type for others
                    _obs_strategies.add("crypto_hourly" if _k == "hourly" else _k)
            self.capital_allocator = CapitalAllocator(observation_strategies=_obs_strategies)
            logging.info("Capital allocator initialized")
        except Exception as e:
            logging.warning(f"Capital allocator unavailable: {e}")

        self.scanner = OpportunityScanner(
            self.client, self.state, self.feed, self.vol, self.logger,
            self.sizer, order_flow=self.order_flow,
            kalshi_oft=self.kalshi_oft,
            kalshi_feed=self.kalshi_feed,
            main_loop=self,
        )
        self.executor = OrderExecutor(
            self.client, self.state, self.logger,
            main_loop=self, kalshi_feed=self.kalshi_feed)
        self.executor._kalshi_oft = self.kalshi_oft
        self.tracker = SettlementTracker(self.client, self.state, self.logger,
                                         main_loop=self)
        self._shutdown = threading.Event()
        self._active_windows: List[Dict] = []
        self._discovery_ob_tickers: set = set()
        self._last_market_refresh: float = 0.0
        # Step #5 cache staleness watchdog: timestamp of last
        # successful `_refresh_active_windows`. Initialized to 0.0
        # so the staleness check reports STALE before the first
        # refresh — we don't trade until the cache is populated.
        self._active_windows_updated_at: float = 0.0
        # Dedup state for CACHE_STALE warnings: log once when the
        # episode has outlived the flicker threshold, then a
        # heartbeat every 60s while still stale, then a recovery
        # line when fresh again. Without dedup, a multi-hour stall
        # floods 3,600+ identical lines/hr.
        # `_episode_started_at` is set on the first stale tick;
        # `_episode_logged` flips True after the start line fires
        # (deferred until the episode outlives the flicker
        # threshold). Recovery only logs if start logged — Round
        # 3 [A4] symmetric flicker dedup.
        self._cache_stale_episode_started_at: float = 0.0
        self._cache_stale_last_heartbeat_at: float = 0.0
        self._cache_stale_episode_logged: bool = False
        # Round 4 [A3]: edge-trigger for the "0 active windows"
        # log so it doesn't fire every 30s during a sustained
        # Kalshi /events outage. CACHE_STALE handles the operator
        # alert after the budget elapses; this is just the
        # transition log.
        self._empty_refresh_in_progress: bool = False
        # Re-entry guard for market-refresh worker thread. Apr 25 00:45
        # incident: refresh_active_windows + subscribe took 1.5-2s on
        # the main thread (9+ REST calls), accounting for the residual
        # SLOW_SCAN_TICK gap after the SettlementTracker fix.
        self._market_refresh_running: bool = False
        # Re-entry guard for EGARCH MLE refit worker thread. Apr 25
        # 01:02 incident: PERIODIC_TASK_SLOW: egarch_refit took 53.30s
        # → SLOW_SCAN_TICK 54.37s. scipy L-BFGS-B optimization across
        # 4 assets is the heaviest periodic task in _tick().
        self._egarch_refit_running: bool = False
        self._last_wal_checkpoint: float = 0.0
        # Phase 2: timestamp of last periodic WS re-snapshot sweep.
        # Triggers force_resubscribe on every active 15M ticker
        # every WS_PERIODIC_RESNAPSHOT_INTERVAL_S — insurance against
        # H3' (server-side msg loss without seq increment).
        self._last_ws_periodic_resnap: float = 0.0
        self._last_error: Optional[str] = None
        self._last_error_time: float = 0.0
        self._start_time: float = time.time()
        self._peak_balance: float = 0.0
        self._balance_history: deque = deque(maxlen=8640)  # ~24h at 10s intervals
        self._recent_fill_latencies: deque = deque(maxlen=100)
        self._session_fill_count: int = 0
        self._session_maker_submissions: int = 0
        self._session_maker_fills: int = 0
        self._last_summary_date: Optional[str] = None
        self._observation_mode: bool = OBSERVATION_MODE
        self._last_db_health_check: float = 0.0
        self._db_locked_count: int = 0
        # Phase H-2: bot microstate forward capture state.
        # `_scan_iter` is the monotonic per-tick counter (incremented at
        # the top of `scan()`). `_open_positions_count_cache` is populated
        # by `_compute_bot_state_features` (60s cache) so the snapshot
        # avoids a per-insert SQL hit. `_scan_loop_start` (pinned to
        # `time.perf_counter()` at top of scan()) lets the helper derive
        # `scan_dt_ms` defensively.
        self._scan_iter: int = 0
        self._open_positions_count_cache: Optional[int] = None
        self._scan_loop_start: Optional[float] = None
        # Phase H-2: wire the bot microstate provider into StateManager.
        # AFTER all MainLoop attributes are initialized (so the provider
        # closure has everything it needs to read). The provider returns
        # the snapshot DICT (not a JSON string) — the insert site patches
        # `lock_wait_ms` in-place and serializes. This decouples the
        # heavy snapshot computation from the writer lock (round-1 wiring
        # review #3). Wrapped in try/except — if the import fails the
        # bot still runs (column stays NULL on every 15M insert).
        try:
            from bot_state_snapshot import compute_bot_state_snapshot as _moc_snap
            def _bot_state_provider():
                """Returns the snapshot dict (lock_wait_ms=None — patched
                in by insert_evaluated_opportunity after BEGIN IMMEDIATE)."""
                return _moc_snap(self, lock_wait_ms=None)
            self.state.set_bot_state_provider(_bot_state_provider)
            logging.info("H-2 bot state provider wired into StateManager")
        except Exception as e:
            logging.warning(f"H-2 bot state provider unavailable: {e}")

    # ── DB Health Watchdog ────────────────────────────────────────────────

    def _check_db_health(self):
        """Run every 5 minutes. Alert via Telegram if DB contention is unhealthy."""
        alerts = []

        # 1. Locked error count since last check
        if self._db_locked_count > 10:
            alerts.append(f"🔒 {self._db_locked_count} locked errors in last 5 min")
        self._db_locked_count = 0  # reset after check

        # 2. WAL file size — alert at 200 MB (cursor-race steady-state is
        # ~140 MB with the unfixed cursor-race; pre-2026-05-08 threshold of
        # 100 MB fired every 5 min in nuisance noise without surfacing real
        # anomalies. 200 MB still leaves comfortable headroom under the
        # operator-set 250 MB hard restart-trigger. Restoring 100 MB
        # threshold makes sense after the cursor-race fix lands.
        try:
            db_path = self.state.conn.execute(
                "PRAGMA database_list").fetchone()[2]
            wal_path = db_path + "-wal"
            if os.path.exists(wal_path):
                wal_mb = os.path.getsize(wal_path) / (1024 * 1024)
                if wal_mb > 200:
                    alerts.append(f"📁 WAL file {wal_mb:.1f} MB (>200 MB)")
        except Exception:
            pass

        # 3. Pending evaluated_opportunities (unsettled backlog)
        try:
            pending = self.state.conn.execute(
                "SELECT COUNT(*) FROM evaluated_opportunities "
                "WHERE status='open' AND filter_stage IN "
                "('candidate','observation_trade','shadow','weather_shadow',"
                "'sports_shadow','spx_observation','no_side_shadow')"
            ).fetchone()[0]
            if pending > 500:
                alerts.append(f"📊 {pending} pending evals (>500)")
        except Exception:
            pass

        if alerts:
            msg = "⚠️ *DB Health Alert*\n" + "\n".join(alerts)
            self.telegram.send(msg, dedup_key="db_health_alert")
            logging.warning("DB health alert: %s", "; ".join(alerts))

    # ── Signal Handling ───────────────────────────────────────────────────

    def _setup_signals(self):
        signal.signal(signal.SIGINT, self._handle_signal)
        signal.signal(signal.SIGTERM, self._handle_signal)

    def _handle_signal(self, signum, _frame):
        name = signal.Signals(signum).name
        logging.info(f"Received {name}, shutting down gracefully...")
        self._shutdown.set()

    # ── Startup ───────────────────────────────────────────────────────────

    # DEPLOY_SAFE_HOURS: 04-06 UTC (midnight-2AM ET).
    # Restarts during 12-22 UTC cause ~5 min RK warmup with degraded edge.
    # Three restarts on Mar 23 during 18-20 UTC cost an estimated 5-18 fills.

    def startup(self):
        logging.info("Bot starting up...")

        # Layer 3 orphan-DB watchdog: detect any non-bot PID holding
        # state.db at startup. Designed to catch the May 3 2026
        # incident pattern (H-4c backfill orphan held writer lock for
        # 2h42m, wedged the bot for 6 min via lock contention on
        # restart). Detection-only; operator triages from the alert.
        # See kb/failures/shape-d-contention-explosion-may03.md.
        try:
            detect_orphan_db_holders(DB_PATH)
        except Exception:
            logging.warning(
                "orphan-DB watchdog raised; ignoring (defense in depth, "
                "must not block startup)", exc_info=True,
            )

        # Warn if starting during peak trading hours
        _start_hour = datetime.datetime.now(timezone.utc).hour
        if 12 <= _start_hour <= 22:
            logging.warning(
                "PEAK_HOURS_START: Bot started at %02d:00 UTC — RK warmup will "
                "degrade edge for ~5 minutes. Deploy during 04-06 UTC to avoid fill loss.",
                _start_hour)

        # R-p7-deploy-r9: start the cal_mlp post-hoc processor here, AFTER
        # StateManager has run migrate_schema (so cal_mlp_request_id column
        # + partial index exist). The processor polls evaluated_opportunities
        # every 10s in its own daemon thread, finds unannotated 15M rows,
        # runs predict, and UPDATEs. Edit 4 in scan() just stamps the uuid.
        # Always start (cheap if env=0 — early-exits at the env check inside
        # _process_one_batch). Stops in _cleanup() before state.close().
        _calmlp_start_posthoc(
            db_path=DB_PATH, predictors=_calmlp_predictors,
            poll_interval_sec=10.0, batch_size=50,
        )

        # Load previously logged fill IDs
        self.logger.load_logged_fill_ids()

        # Verify API connectivity
        balance_resp = self.client.get_balance()
        if balance_resp is None:
            logging.critical("Cannot connect to Kalshi API — check credentials")
            sys.exit(1)
        balance_cents = balance_resp.get("balance") or 0
        self.sizer.starting_balance_cents = balance_cents
        # Seed HWM with CASH balance only (not portfolio value).
        # Kalshi available_balance does NOT drop when position collateral is locked,
        # so cash-only tracking is safe. Portfolio tracking (cash + positions) caused
        # HWM inflation when DC positions opened, compressing drawdown_scaler to 0.25
        # even on profitable accounts. (Learned: HWM spiked to $2,035 from simultaneous
        # DC positions, cash was $1,485, ds=0.25 for ~7 days undetected. Mar 29 2026.)
        # Position exposure is still computed for logging/dashboard visibility.
        try:
            _startup_positions = self.state.get_open_positions()
            _startup_exposure = sum(
                p.get("count", 0) * p.get("avg_price_cents", 0)
                for p in _startup_positions
            )
            logging.info(
                "HWM seed: available=%dc (position_exposure=%dc, NOT added to HWM)",
                balance_cents, _startup_exposure)
        except Exception:
            logging.warning("HWM seed: could not compute position exposure for logging")
        self.sizer.record_balance(balance_cents)
        self._peak_balance = balance_cents / 100
        logging.info(f"Connected to Kalshi. Balance: ${balance_cents / 100:.2f}")
        if _TELEGRAM:
            _TELEGRAM.send(f"\U0001f7e2 Bot started \u2014 Balance: ${balance_cents / 100:.2f}")

        # Reconcile local state with API
        self.state.reconcile_with_api(self.client)

        # Check for settlements that happened while bot was down
        self.tracker.startup()

        # Backfill raw_prob for calibration data
        self._backfill_calibration_data()

        # Load calibration training data from historical settlements
        self.calibration.load_training_data_from_db(self.state)

        # Run adaptive-vs-fixed backtest on startup
        backtest_result = self.calibration.backtest_adaptive_vs_fixed()
        if backtest_result:
            logging.info("Startup backtest result: %s", backtest_result)

        if _TELEGRAM and self.calibration.active_method != "fixed_beta":
            bt_msg = ""
            if backtest_result:
                bt_msg = (
                    f"\nBacktest: Brier {backtest_result['old_brier']:.4f} -> "
                    f"{backtest_result['new_brier']:.4f} "
                    f"({backtest_result['cap_truncated_count']} cap-truncated)"
                )
            _TELEGRAM.send(
                f"\U0001f9e0 Calibration: {self.calibration.active_method} trained "
                f"({len(self.calibration._observations)} obs){bt_msg}"
            )

        # Load per-market calibration training data (separate from 15M)
        for _reg_key, _engine in self._cal_engines.items():
            _load_pt, _sub_code = self._cal_engine_meta[_reg_key]
            _load_asset = _derive_asset_filter(_load_pt, _sub_code) if _sub_code else None
            _engine.load_training_data_from_db(
                self.state, product_type_include=_load_pt, asset_filter=_load_asset)
            _bt = _engine.backtest_adaptive_vs_fixed()
            if _bt:
                logging.info("Startup %s cal backtest: %s", _reg_key, _bt)
            logging.info("CONFIG_VERIFY (%s_cal): method=%s active=%s obs=%d",
                         _reg_key, _engine.active_method,
                         _engine.is_learned_method_active(), len(_engine._observations))

        # Start Coinbase price feed
        self.feed.start()
        logging.info("Coinbase price feed starting...")

        # Start Deribit DVOL fetcher
        self.dvol_fetcher.start()
        logging.info("Deribit DVOL fetcher starting...")

        # Start cross-exchange feeds
        if self.cross_feed:
            self.cross_feed.start()
            logging.info("Cross-exchange feed starting...")

        # Start CoinGlass funding rate fetcher
        self.coinglass.start()

        # Start Kalshi WebSocket feed (fills + orderbook)
        if self.kalshi_feed:
            try:
                self.kalshi_feed.start()
                logging.info("Kalshi WebSocket feed starting...")
            except Exception as e:
                logging.warning(f"Kalshi WebSocket feed failed to start: {e}")

        # Start SPX engine price feed (if enabled)
        if self.spx_engine:
            try:
                self.spx_engine.start()
                logging.info("SPX engine starting...")
            except Exception as e:
                logging.warning(f"SPX engine failed to start: {e}")
                self.spx_engine = None

        # Start Weather engine ensemble fetcher (if enabled)
        if self.weather_engine:
            try:
                self.weather_engine.start()
                logging.info("Weather engine starting...")
            except Exception as e:
                logging.warning(f"Weather engine failed to start: {e}")
                self.weather_engine = None

        # Start Sports engine (if enabled)
        if self.sports_engine:
            try:
                self.sports_engine.start()
                logging.info("Sports engine starting...")
            except Exception as e:
                logging.warning(f"Sports engine failed to start: {e}")
                self.sports_engine = None

        # Dashboard snapshot builder (used by Supabase syncer)
        try:
            from dashboard_snapshot import DashboardSnapshotBuilder
            self.snapshot_builder = DashboardSnapshotBuilder(self)
        except Exception as e:
            logging.info(f"Dashboard snapshot builder not available: {e}")
            self.snapshot_builder = None

        # Start Supabase syncer (if configured)
        try:
            from supabase_sync import SupabaseSyncer
            self.supabase_syncer = SupabaseSyncer(self)
            self.supabase_syncer.start()
        except Exception as e:
            logging.info(f"Supabase sync not available: {e}")
            self.supabase_syncer = None

        # Initial market scan
        self._refresh_active_windows()

        # Start H-3a NBBO snapshotter — AFTER both kalshi_feed.start() (so
        # orderbooks are subscribing) AND _refresh_active_windows() (so
        # the active-tickers provider returns a populated list rather
        # than producing a burst of 'ws_no_data' rows on every restart).
        # Round-1 wiring review #2.
        if self.market_obs_snapshotter is not None:
            try:
                self.market_obs_snapshotter.start()
                logging.info("Market observations snapshotter starting...")
            except Exception as e:
                logging.warning(
                    f"Market observations snapshotter failed to start: {e}"
                )

        logging.info(
            f"Startup complete. Monitoring {len(ASSETS)} assets "
            f"({', '.join(ASSETS)})"
        )

    # ── Periodic Tasks ────────────────────────────────────────────────────

    def _refresh_active_windows(self):
        # Build the merged list LOCALLY, then publish atomically.
        # Round 2 [A2] fix: previously we did
        #   self._active_windows = discover_active_windows(...)
        #   self._active_windows_updated_at = time.time()
        #   self._active_windows.extend(spx_windows)   # main thread
        #   self._active_windows.extend(wx_windows)    # could race
        # The reader (main thread) could observe the freshly-swapped
        # list AFTER the timestamp update but BEFORE SPX/weather
        # were merged in — silently scanning without SPX/weather
        # candidates while the watchdog reported "fresh". And
        # `list.extend()` is GIL-atomic but NOT safe against a
        # `for ... in list` iterator running on another thread.
        # Build-then-swap eliminates both races.
        new_windows = discover_active_windows(self.client)

        # Merge SPX windows (if engine available and market open)
        if self.spx_engine and self.spx_engine.is_market_open():
            try:
                spx_windows = self.spx_engine.get_active_windows(self.client)
                new_windows.extend(spx_windows)
            except Exception as e:
                logging.warning(f"SPX window discovery failed: {e}")

        # Merge weather windows (if engine available)
        if self.weather_engine:
            try:
                wx_windows = self.weather_engine.get_active_windows(self.client)
                new_windows.extend(wx_windows)
            except Exception as e:
                logging.warning(f"Weather window discovery failed: {e}")

        # Atomic ref-swap: main-thread readers see either the
        # previous list or this fully-merged list, never a partial
        # state. Python attribute writes on a list reference are
        # GIL-atomic.
        self._active_windows = new_windows
        n = len(new_windows)
        # Round 3 [A3] empty-list guard: do NOT bump the staleness
        # timestamp if the refresh produced 0 windows. Crypto 15M
        # markets are 24/7 and hourly are continuous, so an empty
        # list is a silent failure — most commonly Kalshi /events
        # returning empty for all 8 series. Leaving the timestamp
        # un-updated lets the staleness watchdog fire CACHE_STALE
        # after the budget elapses, surfacing the failure to
        # operators. We DO publish the empty list (replacing the
        # prior list with []) so scan() doesn't silently trade on
        # ancient windows — the staleness gate then prevents scan
        # from running on the empty list.
        # Round 4 [A3]: edge-triggered logging. Log once on the
        # transition into empty, once on recovery. CACHE_STALE
        # provides the sustained-state operator alert; this just
        # marks the boundaries.
        if n == 0:
            if not self._empty_refresh_in_progress:
                self._empty_refresh_in_progress = True
                logging.warning(
                    "Market refresh returned 0 active windows — "
                    "scanner idle, staleness timestamp NOT updated. "
                    "Watchdog will fire CACHE_STALE after "
                    "budget=%.0fs. (Subsequent empty refreshes "
                    "will not re-log until recovery.)",
                    ACTIVE_WINDOWS_STALENESS_BUDGET_S)
        else:
            if self._empty_refresh_in_progress:
                self._empty_refresh_in_progress = False
                logging.warning(
                    "Market refresh recovered: %d active windows "
                    "after empty-refresh episode.", n)
            # Step #5 freshness signal: timestamp set AFTER the
            # publish. If a reader sees `_active_windows_updated_at`
            # as fresh, it is GUARANTEED to have observed the
            # merged list (because the timestamp write
            # happens-after the ref-swap in program order under
            # the GIL).
            self._active_windows_updated_at = time.time()
            logging.debug(f"Refreshed: {n} active windows")

        self._last_market_refresh = time.time()

    def _subscribe_discovery_orderbooks(self):
        """Subscribe to WS orderbook_delta for all discovered tickers.

        Dashboard visibility ONLY — does NOT affect Scanner.scan(),
        execution, or any trading logic. Called every 30s after
        _refresh_active_windows(). Skips hourly tickers (observation only).
        """
        if not self.kalshi_feed or not self.kalshi_feed.is_connected:
            return
        try:
            active_tickers: set = set()
            for window in self._active_windows:
                if window.get("product_type") == "hourly":
                    continue  # skip hourly tickers from WS subscription
                for mkt in window.get("markets", []):
                    ticker = mkt.get("ticker", "")
                    if ticker:
                        active_tickers.add(ticker)

            # Phase 2.8 [P0]: diff against the AUTHORITATIVE
            # kalshi_feed.get_subscribed_tickers() — NOT the
            # private previous-cycle `_discovery_ob_tickers` view.
            # 5 paths add to _subscribed_tickers (this method,
            # scan(), lazy _get_orderbook ×2, PPO); only 2 paths
            # remove. Pre-fix, tickers added by the other 4 paths
            # (especially after their markets closed) accumulated
            # forever — causing post-close get_snapshot to hit
            # Kalshi code=7 "Unknown subscription ID", driving
            # WS_SUBSCRIBE_STUCK + WS_FORCE_RECONNECT loops.
            # Empirical: KXXRP15M-26APR251500-00 still being
            # snapshotted at 19:00 UTC (4h post-close).
            all_subscribed = set(
                self.kalshi_feed.get_subscribed_tickers())

            # Phase 2.8 R-review A1: empty-active short-circuit
            # MUST use `all_subscribed` (the authoritative set) —
            # NOT `_discovery_ob_tickers` (the now-deprecated
            # previous-cycle view). On the first cycle after a
            # restart where Kalshi /events transiently fails,
            # `_discovery_ob_tickers` is empty too → guard
            # doesn't trigger → mass-unsubscribe of every ticker
            # added by lazy _get_orderbook / scan() / PPO during
            # startup. Empty most commonly = Kalshi /events
            # transient failure; never trigger mass cleanup
            # under that condition.
            if not active_tickers and all_subscribed:
                logging.debug(
                    "discovery_ob_subscribe: skipping cycle — "
                    "active_tickers empty (Kalshi /events likely "
                    "transient-empty), keeping %d prior subs",
                    len(all_subscribed))
                return

            # Unsubscribe expired tickers from previous cycle.
            # Phase 2.8 R-review A2: protect ALL held-position
            # tickers (any product type), not just 15M.
            #
            # Phase 2.8 R2 / P1: protection is NOT gated on
            # POSITION_PRICE_MONITOR_ENABLED. PPO is one reason to
            # keep the WS feed for held tickers, but settlement
            # detection, fill reconciliation, and other
            # position-monitoring paths also depend on having
            # orderbook data while a position is open. Don't yank
            # the feed because a single optional flag is off.
            _held_tickers = set()
            try:
                for _hp in self.state.get_open_positions():
                    if _hp.get("status") == "open":
                        _t = _hp.get("ticker", "")
                        if _t:
                            _held_tickers.add(_t)
            except Exception:
                pass
            expired = all_subscribed - active_tickers - _held_tickers
            for ticker in expired:
                try:
                    self.kalshi_feed.unsubscribe_ticker(ticker)
                except Exception:
                    pass

            # Subscribe to current active tickers (idempotent)
            for ticker in active_tickers:
                try:
                    self.kalshi_feed.subscribe_ticker(ticker)
                except Exception:
                    pass

            if expired:
                # Phase 2.8 R-review A5: log actual ticker names
                # (sorted, capped) on first ship — the whole point
                # is "we don't know which paths leaked." Forensic
                # signal for confirming which sources are leaking.
                _expired_sorted = sorted(expired)
                _sample = _expired_sorted[:10]
                _truncated = "" if len(expired) <= 10 else f" (+{len(expired)-10} more)"
                logging.info(
                    "discovery_ob_cleanup: unsubscribed %d expired "
                    "tickers: %s%s",
                    len(expired), _sample, _truncated)
            # Keep _discovery_ob_tickers tracking for backward-compat
            # diagnostic logs. The actual cleanup diff is now
            # against _subscribed_tickers (authoritative).
            self._discovery_ob_tickers = active_tickers
        except Exception as e:
            logging.warning(f"discovery_ob_subscribe failed: {e}")

    # ── Calibration Backfill ─────────────────────────────────────────────

    def _backfill_calibration_data(self):
        """One-time backfill of raw_prob for calibration training data."""
        try:
            # Step A: Backfill evaluated_opportunities raw_prob
            rows = self.state.conn.execute(
                "SELECT id, asset, spot_price, threshold, volatility, "
                "seconds_to_close, z_score "
                "FROM evaluated_opportunities "
                "WHERE raw_prob IS NULL "
                "AND spot_price IS NOT NULL AND threshold IS NOT NULL "
                "AND volatility IS NOT NULL AND seconds_to_close IS NOT NULL"
            ).fetchall()

            eval_count = 0
            for row in rows:
                z = row["z_score"]
                if z is None:
                    spot = row["spot_price"]
                    thresh = row["threshold"]
                    vol = row["volatility"]
                    ttc = row["seconds_to_close"]
                    if vol <= 0 or ttc <= 0:
                        continue
                    sigma_move = spot * vol * math.sqrt(ttc / 5.0)
                    if sigma_move <= 0:
                        continue
                    z = (thresh - spot) / sigma_move
                raw_prob = ProbabilityEngine._cdf_complement(z, row["asset"])
                self.state.conn.execute(
                    "UPDATE evaluated_opportunities SET raw_prob = ? WHERE id = ?",
                    (raw_prob, row["id"]),
                )
                eval_count += 1
            if eval_count:
                self.state.conn.commit()
                logging.info("Backfill: updated raw_prob for %d evaluated_opportunities", eval_count)

            # Step B: Backfill rejected_opportunities raw_prob + market_result
            rej_results = {}
            if os.path.exists(REJECTION_JOURNAL):
                with open(REJECTION_JOURNAL, "r") as f:
                    for line in f:
                        line = line.strip()
                        if not line:
                            continue
                        try:
                            entry = json.loads(line)
                        except json.JSONDecodeError:
                            continue
                        if entry.get("type") == "rejection_settlement":
                            rej_results[entry["ticker"]] = entry["market_result"]

            rej_rows = self.state.conn.execute(
                "SELECT ticker, asset, z_score FROM rejected_opportunities "
                "WHERE raw_prob IS NULL AND z_score IS NOT NULL"
            ).fetchall()

            rej_count = 0
            for row in rej_rows:
                z = row["z_score"]
                raw_prob = ProbabilityEngine._cdf_complement(z, row["asset"])
                market_result = rej_results.get(row["ticker"])
                self.state.conn.execute(
                    "UPDATE rejected_opportunities SET raw_prob = ?, market_result = ? "
                    "WHERE ticker = ?",
                    (raw_prob, market_result, row["ticker"]),
                )
                rej_count += 1
            if rej_count:
                self.state.conn.commit()
                logging.info("Backfill: updated raw_prob for %d rejected_opportunities", rej_count)

        except Exception as e:
            logging.warning("Backfill calibration data failed: %s", e)

    # ── Daily Summary ─────────────────────────────────────────────────────

    def _log_daily_summary(self):
        """Log aggregated daily performance metrics on date change."""
        try:
            today = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%d")
            if self._last_summary_date is None:
                self._last_summary_date = today
                return
            if today == self._last_summary_date:
                return

            yesterday = self._last_summary_date
            self._last_summary_date = today

            # Aggregate settled trades for yesterday
            rows = self.state.conn.execute(
                "SELECT * FROM settled_trades WHERE settled_at LIKE ?",
                (yesterday + "%",)
            ).fetchall()

            total_pnl = 0
            total_fees = 0
            wins = 0
            losses = 0
            per_asset: Dict[str, Dict] = {}

            for row in rows:
                r = dict(row)
                pnl = r["pnl_cents"]
                total_pnl += pnl
                total_fees += r["fee_cents"]
                if pnl > 0:
                    wins += 1
                else:
                    losses += 1

                a = r["asset"]
                if a not in per_asset:
                    per_asset[a] = {"trades": 0, "wins": 0, "losses": 0, "pnl_cents": 0}
                per_asset[a]["trades"] += 1
                per_asset[a]["pnl_cents"] += pnl
                if pnl > 0:
                    per_asset[a]["wins"] += 1
                else:
                    per_asset[a]["losses"] += 1

            # Rejection counts for yesterday
            rej_rows = self.state.conn.execute(
                "SELECT rejection_reason, COUNT(*) as cnt FROM rejected_opportunities "
                "WHERE rejection_time LIKE ? GROUP BY rejection_reason",
                (yesterday + "%",)
            ).fetchall()
            rejection_counts = {r["rejection_reason"]: r["cnt"] for r in rej_rows}

            # Evaluated opportunity outcomes for yesterday
            eval_rows = self.state.conn.execute(
                "SELECT filter_stage, status, COUNT(*) as cnt FROM evaluated_opportunities "
                "WHERE evaluation_time LIKE ? GROUP BY filter_stage, status",
                (yesterday + "%",)
            ).fetchall()
            eval_counts = {}
            for r in eval_rows:
                stage = r["filter_stage"]
                if stage not in eval_counts:
                    eval_counts[stage] = {}
                eval_counts[stage][r["status"]] = r["cnt"]

            self.logger.log_performance({
                "summary_type": "daily",
                "date": yesterday,
                "total_trades": wins + losses,
                "wins": wins,
                "losses": losses,
                "total_pnl_cents": total_pnl,
                "total_fees_cents": total_fees,
                "per_asset": per_asset,
                "rejection_counts": rejection_counts,
                "evaluated_opportunity_counts": eval_counts,
            })
            logging.info(
                f"Daily summary ({yesterday}): {wins}W/{losses}L, "
                f"PnL={total_pnl}¢, fees={total_fees}¢"
            )
            if _TELEGRAM:
                _TELEGRAM.send(
                    f"\U0001f4c8 Daily ({yesterday}): {wins}W/{losses}L, "
                    f"PnL=${total_pnl / 100:+.2f}, fees=${total_fees / 100:.2f}"
                )
        except Exception as e:
            logging.debug(f"_log_daily_summary failed: {e}")

    # ── Main Tick ─────────────────────────────────────────────────────────

    def _active_windows_is_stale(self) -> bool:
        """Step #5 cache staleness watchdog. True if the Kalshi
        15M/hourly window cache (`_active_windows`) is older than
        ACTIVE_WINDOWS_STALENESS_BUDGET_S — meaning the refresh
        worker thread either hasn't run yet (initial state) or has
        silently died. The scan call site uses this to fail closed
        rather than trade on stale window data.

        Scope and known limits:
          • This is a FRESHNESS watchdog — covers "did the refresh
            worker run recently". It does NOT cover data-quality
            failures: `discover_active_windows` is not atomic
            across its 8 series-level GET /events calls, so a
            mid-loop circuit-breaker trip can publish a partial
            list while keeping the timestamp fresh. Round 3 [A2].
          • Empty-list publication IS protected by the
            non-empty check in `_refresh_active_windows` (Round
            3 [A3]) — an empty refresh result does not bump the
            timestamp, so the watchdog fires CACHE_STALE.
          • Other readers of `self._active_windows` exist outside
            the gate: `_subscribe_discovery_orderbooks` reads it
            from the worker thread (right after the publish, no
            race), and dashboard exporters may read it as a
            snapshot. The gate covers `_tick`'s scan-relevant
            iteration + `scanner.scan()` only. Round 3 [A1].
          • SPX/weather merges share this single timestamp — they
            have no independent freshness signal at this layer.
            Round 2 [A3]."""
        last = self._active_windows_updated_at
        if last <= 0.0:
            return True  # uninitialized
        return (time.time() - last) > ACTIVE_WINDOWS_STALENESS_BUDGET_S

    # Minimum sustained stale duration before the episode-start
    # warning fires. Round 3 [A4]: making start AND recovery use
    # the same threshold makes flicker dedup symmetric. A brief
    # outage (worker recovers in <10s) emits NO log lines on
    # either side; sustained outages emit a coherent
    # start→heartbeat→recovery sequence.
    _CACHE_STALE_MIN_EPISODE_S = 10.0

    def _maybe_log_cache_stale(self) -> None:
        """Emit a CACHE_STALE warning at most once per sustained
        stale episode, with a 60s heartbeat thereafter. Called
        every tick while the cache is stale; without dedup, a
        multi-hour stall logs 3,600+ identical lines/hr and drowns
        out other signals.

        Round 3 [A4]: deferred-start. The episode-start line is
        held back until the episode has lasted
        `_CACHE_STALE_MIN_EPISODE_S` seconds. This makes start
        and recovery symmetric: brief flickers below the
        threshold emit NEITHER a start nor a recovery line. The
        operator only ever sees a coherent pair (or neither).
        `_cache_stale_episode_started_at` records WHEN the stale
        episode began (set on first stale tick); `_cache_stale_episode_logged`
        flips True once the start line fires."""
        now = time.time()
        last = self._active_windows_updated_at
        budget = ACTIVE_WINDOWS_STALENESS_BUDGET_S
        # First stale tick of an episode: record the start time
        # but do NOT log yet — wait for the episode to outlive the
        # flicker threshold.
        if self._cache_stale_episode_started_at <= 0.0:
            self._cache_stale_episode_started_at = now
            self._cache_stale_last_heartbeat_at = now
            self._cache_stale_episode_logged = False
            return
        episode_age = now - self._cache_stale_episode_started_at
        # Emit the deferred episode-start line once the episode
        # outlives the flicker threshold.
        if (not self._cache_stale_episode_logged
                and episode_age >= self._CACHE_STALE_MIN_EPISODE_S):
            self._cache_stale_episode_logged = True
            self._cache_stale_last_heartbeat_at = now
            if last <= 0.0:
                logging.warning(
                    "CACHE_STALE: active_windows never refreshed "
                    "(uninitialized, budget=%.0fs, sustained=%.0fs) "
                    "— skipping scan; settlement and PPO continue. "
                    "Refresh worker may have failed on first run.",
                    budget, episode_age)
            else:
                age = now - last
                logging.warning(
                    "CACHE_STALE: active_windows age=%.1fs > "
                    "budget=%.0fs (sustained=%.0fs) — skipping scan; "
                    "settlement and PPO continue. Worker thread may "
                    "be stuck or dead.",
                    age, budget, episode_age)
            return
        # Heartbeat — only after the start line has fired.
        if (self._cache_stale_episode_logged
                and (now - self._cache_stale_last_heartbeat_at) >= 60.0):
            self._cache_stale_last_heartbeat_at = now
            age_str = (
                "%.1fs" % (now - last) if last > 0.0 else "uninitialized")
            logging.warning(
                "CACHE_STALE_HEARTBEAT: still stale after %.0fs "
                "(active_windows age=%s, budget=%.0fs)",
                episode_age, age_str, budget)

    def _maybe_log_cache_fresh_recovery(self) -> None:
        """Emit one CACHE_FRESH recovery line when the cache returns
        to fresh after a stale episode, then reset dedup state.

        Round 3 [A4]: symmetric with `_maybe_log_cache_stale`'s
        deferred-start. The recovery line ONLY fires if the
        episode-start line fired (i.e., the episode outlived
        `_CACHE_STALE_MIN_EPISODE_S`). Brief flickers leave no
        trace on either side. Sustained stalls produce a
        coherent start→heartbeat→recovery triple."""
        if self._cache_stale_episode_started_at > 0.0:
            if self._cache_stale_episode_logged:
                episode_age = (
                    time.time() - self._cache_stale_episode_started_at)
                logging.warning(
                    "CACHE_FRESH: active_windows recovered after "
                    "%.0fs stale episode — scan re-enabled.",
                    episode_age)
            self._cache_stale_episode_started_at = 0.0
            self._cache_stale_last_heartbeat_at = 0.0
            self._cache_stale_episode_logged = False

    def _tick(self):
        now = time.time()

        # Update peak balance from main thread (dashboard reads only)
        cached_bal = self.scanner._balance_cache[0]
        if cached_bal is not None:
            bal_dollars = cached_bal / 100.0
            if bal_dollars > self._peak_balance:
                self._peak_balance = bal_dollars

        # Per-task timing — emits PERIODIC_TASK_SLOW when any single task
        # exceeds 1.5s. Apr 25 00:30 UTC SLOW_SCAN_TICK still firing after
        # the WS drift probe was threaded — there's another dominant
        # blocker in this cluster. This instrumentation names which task
        # is to blame in the next round of logs.
        _PERIODIC_SLOW_THRESHOLD_S = 1.5

        # Refresh market list periodically — runs in a daemon worker
        # thread so 9+ Kalshi REST calls don't block the main scan
        # loop. _active_windows reassignment is atomic (Python ref
        # write); readers see either the prior list or the new one.
        # `_market_refresh_running` prevents thread pile-up if a
        # cycle exceeds MARKET_REFRESH_SECONDS. (Apr 25 00:45 fix.)
        if (now - self._last_market_refresh >= MARKET_REFRESH_SECONDS
                and not self._market_refresh_running):
            self._last_market_refresh = now
            self._market_refresh_running = True

            def _market_refresh_worker():
                try:
                    _t = time.perf_counter()
                    self._refresh_active_windows()
                    _dt = time.perf_counter() - _t
                    if _dt > _PERIODIC_SLOW_THRESHOLD_S:
                        logging.warning(
                            "PERIODIC_TASK_SLOW: refresh_active_windows "
                            "took %.2fs (worker thread)", _dt)
                    _t = time.perf_counter()
                    self._subscribe_discovery_orderbooks()
                    _dt = time.perf_counter() - _t
                    if _dt > _PERIODIC_SLOW_THRESHOLD_S:
                        logging.warning(
                            "PERIODIC_TASK_SLOW: "
                            "subscribe_discovery_orderbooks took %.2fs "
                            "(worker thread)", _dt)
                except Exception:
                    logging.error(
                        "market_refresh_worker failed", exc_info=True)
                finally:
                    self._market_refresh_running = False

            try:
                threading.Thread(
                    target=_market_refresh_worker,
                    daemon=True,
                    name="market_refresh",
                ).start()
            except Exception:
                self._market_refresh_running = False
                logging.debug(
                    "market_refresh worker spawn failed",
                    exc_info=True)

        # Phase 2: periodic WS re-snapshot of currently-subscribed
        # 15M tickers. Insurance against H3' (msg loss without seq
        # increment) per ws-cache-drift-investigation.md. Industry
        # standard practice: snapshot reset is the only reliable
        # cure for cumulative WS cache drift.
        #
        # We read subscribed tickers from the WS feed via
        # `get_subscribed_tickers()` (R1/A3 [P1] — locked snapshot
        # so the WS thread can mutate the set concurrently). This
        # loop:
        #   (a) doesn't depend on active_windows freshness — runs
        #       even if the staleness gate trips
        #   (b) targets the actual set of tickers whose WS cache
        #       could be drifted
        #   (c) doesn't trigger the Step #5 AST tripwire that
        #       prevents iterating stale window data before vol.update
        #
        # R1 / A2 [P0]: pass purge_cache=False so the periodic sweep
        # does NOT simultaneously evict caches for every 15M ticker
        # (that would create a system-wide ~5s gap every 5 min).
        # Detected-drift callers (flag_ticker_drifted) keep the
        # default purge=True since we KNOW that cache is corrupt.
        #
        # R1 / A7 [P1]: pass bypass_cooldown=True so periodic
        # insurance always runs, even if flag_ticker_drifted fired
        # for the same ticker within WS_FORCE_RESUB_COOLDOWN_S.
        if (now - self._last_ws_periodic_resnap
                >= WS_PERIODIC_RESNAPSHOT_INTERVAL_S):
            self._last_ws_periodic_resnap = now
            if (self.kalshi_feed is not None
                    and self.kalshi_feed.is_connected):
                try:
                    _subscribed = (
                        self.kalshi_feed.get_subscribed_tickers())
                    _resnap_tickers = [
                        t for t in _subscribed if "15M" in t.upper()]
                    for t in _resnap_tickers:
                        self.kalshi_feed.force_resubscribe(
                            t,
                            purge_cache=False,
                            bypass_cooldown=True,
                            track_recovery=False,
                        )
                    if _resnap_tickers:
                        logging.info(
                            "WS_PERIODIC_RESNAP: requested fresh "
                            "snapshots for %d 15M tickers "
                            "(interval=%ds, purge=False)",
                            len(_resnap_tickers),
                            int(WS_PERIODIC_RESNAPSHOT_INTERVAL_S))
                except Exception:
                    logging.warning(
                        "WS_PERIODIC_RESNAP loop failed",
                        exc_info=True)

        # Check settlements periodically (self-throttled)
        _t = time.perf_counter()
        self.tracker.tick()
        _dt = time.perf_counter() - _t
        if _dt > _PERIODIC_SLOW_THRESHOLD_S:
            logging.warning(
                "PERIODIC_TASK_SLOW: tracker_tick took %.2fs", _dt)

        self._log_daily_summary()

        # Periodic WAL checkpoint (every 60s) — prevents WAL bloat that causes
        # "database is locked" across shadow engines with 7 concurrent connections.
        # Uses PASSIVE (not TRUNCATE) — TRUNCATE requires exclusive lock that
        # deadlocks with supabase_sync reader + settlement writer. PASSIVE
        # checkpoints whatever pages it can without blocking. (Mar 16 2026)
        if now - self._last_wal_checkpoint >= 60.0:
            self._last_wal_checkpoint = now  # Update BEFORE attempt — prevents hot retry loop
            _t = time.perf_counter()
            try:
                self.state.conn.execute("PRAGMA wal_checkpoint(PASSIVE)")
            except Exception:
                self._db_locked_count += 1
                logging.debug("WAL checkpoint failed (busy)", exc_info=True)
            _dt = time.perf_counter() - _t
            if _dt > _PERIODIC_SLOW_THRESHOLD_S:
                logging.warning(
                    "PERIODIC_TASK_SLOW: wal_checkpoint took %.2fs", _dt)

        # DB health watchdog (every 5 minutes)
        if now - self._last_db_health_check >= 300.0:
            try:
                self._check_db_health()
            except Exception:
                logging.debug("DB health check failed", exc_info=True)
            self._last_db_health_check = now

        # Periodic calibration retrain check
        _t = time.perf_counter()
        if self.calibration:
            self.calibration.maybe_retrain()
        for _rk, _eng in self._cal_engines.items():
            _eng.maybe_retrain()
        _dt = time.perf_counter() - _t
        if _dt > _PERIODIC_SLOW_THRESHOLD_S:
            logging.warning(
                "PERIODIC_TASK_SLOW: calibration_retrain took %.2fs", _dt)

        # Periodic EGARCH MLE refit — runs in a daemon worker thread.
        # Apr 25 01:02: scipy L-BFGS-B fit across 4 assets blocked the
        # main thread for 53.30s. Same threading pattern as
        # SettlementTracker (8114ddc) and market refresh (f216a8d).
        # `_egarch_refit_running` prevents pile-up if a refit cycle
        # exceeds the next _tick() interval. Thread safety: maybe_refit
        # writes `self._params[asset] = new_params` (atomic dict-item
        # assignment under GIL); EGARCH readers in update() see either
        # old or new params, never partial.
        if self.egarch_estimator and not self._egarch_refit_running:
            self._egarch_refit_running = True

            def _egarch_refit_worker():
                _wt = time.perf_counter()
                try:
                    self.egarch_estimator.maybe_refit()
                    _wdt = time.perf_counter() - _wt
                    if _wdt > _PERIODIC_SLOW_THRESHOLD_S:
                        logging.warning(
                            "PERIODIC_TASK_SLOW: egarch_refit took "
                            "%.2fs (worker thread)", _wdt)
                except Exception:
                    logging.error(
                        "egarch_refit worker thread failed",
                        exc_info=True)
                finally:
                    self._egarch_refit_running = False

            try:
                threading.Thread(
                    target=_egarch_refit_worker,
                    daemon=True,
                    name="egarch_refit",
                ).start()
            except Exception:
                self._egarch_refit_running = False
                logging.debug(
                    "egarch_refit worker spawn failed", exc_info=True)

        # Recompute seconds_to_close and log each window (skip hourly vol diagnostics)
        utc_now = datetime.datetime.now(timezone.utc)
        prices = self.feed.get_all_prices()

        # Feed price data to hourly alt shadow engine for HAR-RV return computation
        if self.hourly_alt_shadow:
            _alt_ts = time.time()
            for _alt_asset, _alt_price in prices.items():
                if _alt_price is not None and _alt_price > 0:
                    try:
                        self.hourly_alt_shadow.ingest_price(_alt_asset, _alt_price, _alt_ts)
                    except Exception:
                        pass

        # Feed SPX price to HAR-RV shadow engine for return computation
        if self.spx_harrv_shadow and self.spx_engine:
            try:
                _spx_spot = self.spx_engine.get_spot_price("SPX")
                if _spx_spot is not None and _spx_spot > 0:
                    self.spx_harrv_shadow.ingest_price(_spx_spot, time.time())
            except Exception:
                pass

        # Per-window iteration (vol.update + scan_journal) is now
        # gated below alongside scanner.scan() so a stale window
        # list can't feed VolatilityEngine negative STCs or pollute
        # the scan journal with stale `seconds_to_close` values.
        # See `_active_windows_is_stale` block below.
        # Poll active executor orders (maker fill check — one per asset)
        self.executor.tick()

        # SOL Path C shadow: check orderbook every tick during escalation window
        try:
            self.executor._tick_sol_pathc_observations()
        except Exception:
            logging.debug("sol_pathc_obs tick failed", exc_info=True)

        # Check confirmation addon opportunities on open positions
        try:
            self.executor._check_addon_opportunities()
        except Exception:
            logging.debug("addon check failed", exc_info=True)

        # Check dip addon opportunities on open positions
        try:
            self.executor._check_dip_addon_opportunities()
        except Exception:
            logging.debug("dip addon check failed", exc_info=True)

        # Process DC IOC retry queue (non-blocking — each retry is <1s)
        try:
            self.executor.process_dc_retries()
        except Exception:
            logging.warning("DC retry processing failed", exc_info=True)

        # Record CASH balance for HWM tracking (once per tick).
        # Uses available cash only — NOT portfolio value (cash + positions).
        # Kalshi available_balance does NOT drop when collateral is locked, so
        # cash-only is safe. Portfolio tracking caused HWM inflation when DC
        # positions opened, compressing ds even on profitable accounts.
        # (Learned: portfolio HWM $2,035 vs cash $1,485 → ds=0.25 for 7 days. Mar 29 2026)
        # Must use full cash balance, NOT fractional bankroll (hourly 10%, SPX 15%).
        # (Learned: fractional bankroll in compute() poisoned HWM for 18h, Mar 25-26 2026)
        try:
            _hwm_balance = self.scanner._get_balance_cached()
            if _hwm_balance and _hwm_balance > 0:
                self.sizer.record_balance(_hwm_balance)
                # Alert on 3+ consecutive spike rejections
                if self.sizer._consecutive_spike_rejections >= 3:
                    if self.sizer._consecutive_spike_rejections == 3:
                        _msg = (
                            "\u26a0\ufe0f HWM spike alert: 3 consecutive rejections. "
                            f"Balance={_hwm_balance}c, "
                            f"last_accepted={self.sizer._balance_history[-1][1] if self.sizer._balance_history else 'none'}c"
                        )
                        logging.warning(_msg)
                        if _TELEGRAM:
                            _TELEGRAM.send(_msg)
        except Exception:
            logging.debug("HWM balance recording failed", exc_info=True)

        # Step #5 cache staleness watchdog: gates ALL code that
        # reads `self._active_windows` for trading decisions. The
        # gated block contains BOTH the per-window iteration (which
        # calls `vol.update(seconds_to_close=...)` — feeding stale
        # negative STC values would corrupt the vol engine) AND the
        # scanner.scan() call. Settlement, executor.tick(), PPO, and
        # weather PPO are NOT gated — they read different state and
        # are time-sensitive in their own right (settlement is
        # idempotent at the DB layer; PPO is observation-only).
        # Scope: covers Kalshi 15M/hourly windows (the cache that
        # `_active_windows_updated_at` actually tracks). SPX and
        # weather merges share the same timestamp but have no
        # independent freshness signal — see Round 2 [A3] follow-up.
        candidates = None
        if self._active_windows_is_stale():
            self._maybe_log_cache_stale()
        else:
            self._maybe_log_cache_fresh_recovery()
            # Take a stable local snapshot of the window list for
            # this tick. The refresh worker does an atomic ref-swap
            # (`_refresh_active_windows` builds locally then
            # publishes — no in-place extend), so the snapshot
            # pins the iterator+scanner to whichever list version
            # was current at load time. A subsequent ref-swap mid-
            # tick produces no surprise: for-loop iterates the OLD
            # list, scan() gets the OLD list, both consistent. The
            # NEXT tick's snapshot picks up the new ref. CPython's
            # GIL makes the ref-load atomic, so `_local_windows` is
            # never partially observed.
            _local_windows = self._active_windows
            for window in _local_windows:
                seconds_to_close = (window["close_time"] - utc_now).total_seconds()
                window["seconds_to_close"] = seconds_to_close

                if window.get("product_type") == "hourly":
                    continue  # volume control: skip scan journal writes for hourly

                in_range = (
                    MIN_SECONDS_BEFORE_CLOSE
                    <= seconds_to_close
                    <= MAX_SECONDS_BEFORE_CLOSE
                )

                asset = window["asset"]
                vol_estimate = self.vol.update(asset, seconds_to_close=seconds_to_close)

                scan_entry = {
                    "asset": asset,
                    "event_ticker": window["event_ticker"],
                    "seconds_to_close": round(seconds_to_close, 1),
                    "in_trading_range": in_range,
                    "num_markets": len(window["markets"]),
                    "spot_price": prices.get(asset),
                    "buffer_len": len(self.feed.get_buffer(asset)),
                }
                if vol_estimate:
                    scan_entry.update({
                        "rv_1min": round(vol_estimate["rv_1min"], 8),
                        "rv_5min": round(vol_estimate["rv_5min"], 8),
                        "rv_15min": round(vol_estimate["rv_15min"], 8),
                        "blended_rv": round(vol_estimate["blended_rv"], 8),
                        "vol_regime": vol_estimate["regime"],
                        "vol_returns": vol_estimate["num_returns"],
                        "bv_1min": round(vol_estimate.get("bv_1min", 0), 8),
                        "jump_component": round(vol_estimate.get("jump_component", 0), 8),
                        "dvol_5s": round(vol_estimate["dvol_5s"], 8) if vol_estimate.get("dvol_5s") is not None else None,
                        "iv_rv_blend_method": vol_estimate.get("iv_rv_blend_method"),
                        "fixed_blend_rv": round(vol_estimate.get("fixed_blend_rv", 0), 8),
                        "jump_multiplier": vol_estimate.get("jump_multiplier", 1.0),
                        "jump_event_count": vol_estimate.get("jump_event_count", 0),
                        "egarch_sigma": round(vol_estimate["egarch_sigma"], 8) if vol_estimate.get("egarch_sigma") is not None else None,
                        "egarch_n_updates": vol_estimate.get("egarch_n_updates", 0),
                        "egarch_log_var": round(vol_estimate.get("egarch_log_var", 0), 4) if vol_estimate.get("egarch_log_var") is not None else None,
                        "egarch_vs_rv_ratio": round(vol_estimate["egarch_sigma"] / vol_estimate["blended_rv"], 4) if vol_estimate.get("egarch_sigma") and vol_estimate.get("blended_rv") and vol_estimate["blended_rv"] > 0 else None,
                        # Adaptive RK bandwidth
                        "omega_sq": vol_estimate.get("omega_sq"),
                        "rk_H_adaptive_5": vol_estimate.get("rk_H_adaptive_5"),
                        "rk_H_adaptive_15": vol_estimate.get("rk_H_adaptive_15"),
                        "rk_H_fixed_5": vol_estimate.get("rk_H_fixed_5"),
                        "rk_H_fixed_15": vol_estimate.get("rk_H_fixed_15"),
                        "ark_5min": round(vol_estimate.get("ark_5min", 0), 8) if vol_estimate.get("ark_5min") is not None else None,
                        "ark_15min": round(vol_estimate.get("ark_15min", 0), 8) if vol_estimate.get("ark_15min") is not None else None,
                        "rk_adaptive_delta_5": vol_estimate.get("rk_adaptive_delta_5", 0),
                        "rk_adaptive_delta_15": vol_estimate.get("rk_adaptive_delta_15", 0),
                        # DVOL diagnostics
                        "dvol_sq_hourly": round(vol_estimate["dvol_sq_hourly"], 10) if vol_estimate.get("dvol_sq_hourly") is not None else None,
                        "vrp": round(vol_estimate["vrp"], 10) if vol_estimate.get("vrp") is not None else None,
                        # Shadow TV RK weights
                        "shadow_tv_blend_rv": round(vol_estimate["shadow_tv_blend_rv"], 8) if vol_estimate.get("shadow_tv_blend_rv") is not None else None,
                        "shadow_tv_weights": vol_estimate.get("shadow_tv_weights"),
                    })
                # Order flow snapshot
                if self.order_flow is not None:
                    try:
                        ofa = self.order_flow.get_signals(asset)
                        scan_entry["ofa_adjustment"] = round(ofa["prob_adjustment"], 6)
                        scan_entry["ofa_confidence"] = ofa["confidence"]
                        cx = ofa["signals"].get("cross_exchange", {})
                        scan_entry["cross_ex_consensus"] = cx.get("consensus_direction")
                        scan_entry["cross_ex_above"] = cx.get("exchanges_above", 0)
                        fn = ofa["signals"].get("funding", {})
                        scan_entry["funding_rate"] = fn.get("rate")
                        scan_entry["funding_level"] = fn.get("level")
                    except Exception:
                        pass
                self.logger.log_scan(scan_entry)

            # Run opportunity scanner (always — execute() rejects if asset already active)
            # Body-duration timing — SCAN_BODY_SLOW fires when scan()'s own
            # execution exceeds 1.5s. Distinguishes "scan body is slow"
            # from "work between scan calls is slow". The latter would
            # show in the SLOW_SCAN_TICK gap measurement without showing
            # here. Apr 25 00:55 incident: SLOW_SCAN_TICK 6.13s with zero
            # PERIODIC_TASK_SLOW means the blocker is in scan() body
            # itself OR in tick body outside the periodic-task cluster.
            _scan_body_start_perf = time.perf_counter()
            try:
                candidates = self.scanner.scan(_local_windows)
            finally:
                _scan_body_dt = time.perf_counter() - _scan_body_start_perf
                if _scan_body_dt > 1.5:
                    logging.warning(
                        "SCAN_BODY_SLOW: scanner.scan body took %.2fs",
                        _scan_body_dt)
            if self.scanner._last_scan_stats:
                try:
                    self.logger.log_scan({
                        "type": "scan_summary",
                        "per_asset": self.scanner._last_scan_stats,
                        "had_candidate": candidates is not None,
                    })
                except Exception:
                    pass
            if candidates:
                for candidate in candidates:
                    logging.info(
                        f"Opportunity: {candidate['ticker']} "
                        f"ask={candidate['best_yes_ask']}¢ "
                        f"edge={candidate['edge']:.2%} "
                        f"size={candidate['position_size']} "
                        f"prob={candidate['calibrated_prob']:.2%}"
                    )
                    self.executor.execute(candidate)

        # ── Post-entry position price monitor (v2: spot-price primary) ─────
        # Logs spot price + Kalshi quotes for held 15M positions every tick.
        # Spot from CoinbaseFeed (always available). Kalshi quotes best-effort.
        # NEVER skips — logs spot even when Kalshi books are empty.
        if POSITION_PRICE_MONITOR_ENABLED:
            try:
                _ppo_positions = self.state.get_open_positions()
                _ppo_wrote = False
                for pos in _ppo_positions:
                    if pos.get("status") != "open":
                        continue
                    _ppo_ticker = pos["ticker"]
                    _ppo_asset = pos.get("asset", "")

                    # Only 15M positions
                    if "15M" not in _ppo_ticker.upper():
                        continue

                    # Ensure held-position ticker is WS-subscribed for orderbook data
                    if self.kalshi_feed and self.kalshi_feed.is_connected:
                        try:
                            self.kalshi_feed.subscribe_ticker(_ppo_ticker)
                        except Exception:
                            pass

                    # 1. SPOT PRICE (always available from CoinbaseFeed)
                    _ppo_spot = None
                    try:
                        _ppo_spot = self.feed.get_price(_ppo_asset)
                    except Exception:
                        pass
                    if _ppo_spot is None:
                        continue  # CoinbaseFeed disconnected — only skip condition

                    # 2. THRESHOLD (cached per position lifecycle)
                    if not hasattr(self, "_ppo_thresholds"):
                        self._ppo_thresholds = {}
                    if _ppo_ticker not in self._ppo_thresholds:
                        try:
                            _t_row = self.state.conn.execute(
                                "SELECT threshold FROM evaluated_opportunities WHERE ticker=? AND threshold IS NOT NULL LIMIT 1",
                                (_ppo_ticker,)).fetchone()
                            self._ppo_thresholds[_ppo_ticker] = _t_row[0] if _t_row else None
                        except Exception:
                            self._ppo_thresholds[_ppo_ticker] = None
                    _ppo_threshold = self._ppo_thresholds.get(_ppo_ticker)

                    # 3. STC (parse from event_ticker — deterministic, no _active_windows dependency)
                    _ppo_stc = None
                    try:
                        _ppo_et = pos.get("event_ticker") or ""
                        _ppo_ts_str = _ppo_et.split("-")[1] if "-" in _ppo_et else ""
                        if len(_ppo_ts_str) >= 11:
                            _ppo_yr = int("20" + _ppo_ts_str[:2])
                            _ppo_mon_str = _ppo_ts_str[2:5].upper()
                            _ppo_months = {"JAN": 1, "FEB": 2, "MAR": 3, "APR": 4, "MAY": 5, "JUN": 6,
                                           "JUL": 7, "AUG": 8, "SEP": 9, "OCT": 10, "NOV": 11, "DEC": 12}
                            _ppo_mon = _ppo_months.get(_ppo_mon_str, 1)
                            _ppo_day = int(_ppo_ts_str[5:7])
                            _ppo_hr = int(_ppo_ts_str[7:9])
                            _ppo_min = int(_ppo_ts_str[9:11])
                            # Ticker time is ET (UTC-4 during EDT). Convert to UTC.
                            _ppo_close_et = datetime.datetime(_ppo_yr, _ppo_mon, _ppo_day,
                                                              _ppo_hr, _ppo_min, 0)
                            _ppo_close_utc = _ppo_close_et.replace(tzinfo=timezone.utc) + datetime.timedelta(hours=4)
                            _ppo_stc = (_ppo_close_utc - datetime.datetime.now(timezone.utc)).total_seconds()
                    except Exception:
                        pass

                    # 4. KALSHI QUOTES (best effort — often None near settlement)
                    _ppo_ask = None
                    _ppo_bid = None
                    _ppo_source = "spot_only"
                    try:
                        _ppo_ob = self.kalshi_feed.get_orderbook(_ppo_ticker) if self.kalshi_feed else None
                        if _ppo_ob and (time.time() - _ppo_ob.get("ts", 0)) < POSITION_PRICE_MONITOR_WS_STALE_SEC:
                            _ppo_ask = OpportunityScanner._best_yes_ask_cents(_ppo_ob)
                            _ppo_bid = OrderExecutor._best_yes_bid(_ppo_ob)
                            if _ppo_ask is not None:
                                _ppo_source = "ws"
                    except Exception:
                        pass
                    if _ppo_ask is None:
                        try:
                            _ppo_mkt = self.client.get_market(_ppo_ticker)
                            if _ppo_mkt:
                                _ppo_mkt_data = _ppo_mkt.get("market", _ppo_mkt)
                                # Use *_dollars fields (FP transition Feb 26 2026)
                                _ppo_ya = _ppo_mkt_data.get("yes_ask_dollars") or _ppo_mkt_data.get("yes_ask")
                                _ppo_yb = _ppo_mkt_data.get("yes_bid_dollars") or _ppo_mkt_data.get("yes_bid")
                                if _ppo_ya is not None:
                                    _ppo_ask = dollars_str_to_cents(_ppo_ya) if isinstance(_ppo_ya, str) else int(_ppo_ya)
                                if _ppo_yb is not None:
                                    _ppo_bid = dollars_str_to_cents(_ppo_yb) if isinstance(_ppo_yb, str) else int(_ppo_yb)
                                # Filter out zero prices (market not yet active)
                                if _ppo_ask == 0:
                                    _ppo_ask = None
                                if _ppo_bid == 0:
                                    _ppo_bid = None
                                if _ppo_ask is not None:
                                    _ppo_source = "rest"
                        except Exception:
                            pass

                    # 5. COMPUTED FIELDS
                    _ppo_buffer = None
                    if _ppo_threshold and _ppo_threshold > 0:
                        _ppo_buffer = round((_ppo_spot - _ppo_threshold) / _ppo_threshold * 100, 4)

                    # 6. INSERT — ALWAYS (never skip when we have spot)
                    _ppo_now_str = datetime.datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%S.%fZ")
                    # Per-level orderbook ladder via shared cache + freshness gate.
                    # Stale entry → NULL (honest); 5-10 ticks of grace at 1-2s/tick.
                    _ppo_ob_ladder = self.state._get_fresh_ob_ladder(_ppo_ticker)
                    self.state.conn.execute(
                        """INSERT INTO position_price_observations
                           (ticker, asset, observation_time, seconds_to_close,
                            spot_price, threshold, spot_buffer_pct,
                            yes_ask_cents, yes_bid_cents,
                            entry_price_cents, position_count, source,
                            orderbook_levels_json)
                           VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                        (_ppo_ticker, _ppo_asset, _ppo_now_str,
                         round(_ppo_stc, 1) if _ppo_stc is not None else None,
                         round(_ppo_spot, 6), _ppo_threshold, _ppo_buffer,
                         _ppo_ask, _ppo_bid,
                         pos.get("avg_price_cents", 0), pos.get("count", 0),
                         _ppo_source, _ppo_ob_ladder))
                    _ppo_wrote = True

                    # 7. SHADOW EXIT SIGNAL — would early exit trigger here?
                    # Track rolling buffer observations per ticker for 30-obs window.
                    # Signal fires once per ticker per hold (deduped via _exit_signal_fired).
                    if _ppo_buffer is not None:
                        if not hasattr(self, "_ppo_buffer_history"):
                            self._ppo_buffer_history = {}
                        if not hasattr(self, "_exit_signal_fired"):
                            self._exit_signal_fired = set()
                        hist = self._ppo_buffer_history.setdefault(_ppo_ticker, [])
                        hist.append(_ppo_buffer)
                        # Keep only last 60 observations (memory bound)
                        if len(hist) > 60:
                            hist[:] = hist[-60:]

                        if _ppo_ticker not in self._exit_signal_fired:
                            _exit_signal = None
                            # Signal 1: buffer below -0.10% (high precision, 68%)
                            if _ppo_buffer < -0.10:
                                _exit_signal = "buffer_below_-0.10"
                            # Signal 2: buffer below -0.05% with STC > 150s gate
                            # Best net benefit (+$383/10d), catches 77% of losses,
                            # kills only 1.2% of wins. SOL uses -0.10% (wider
                            # threshold due to higher volatility / false exit rate).
                            elif _ppo_stc is not None and _ppo_stc > 150:
                                _exit_thresh = -0.10 if _ppo_asset == "SOL" else -0.05
                                if _ppo_buffer < _exit_thresh:
                                    _exit_signal = f"buffer_below_{_exit_thresh:.2f}_stc_gt_150"

                            if _exit_signal:
                                self._exit_signal_fired.add(_ppo_ticker)
                                _entry_cents = pos.get("avg_price_cents", 0)
                                _pos_count = pos.get("count", 0)
                                # Counterfactual: what would exiting at current bid save?
                                _cf_exit_pnl = None
                                if _ppo_bid and _entry_cents and _pos_count:
                                    _sell_revenue = _ppo_bid * _pos_count
                                    _buy_cost = _entry_cents * _pos_count
                                    _sell_fee = calculate_taker_fee(_pos_count, _ppo_bid)
                                    _cf_exit_pnl = _sell_revenue - _buy_cost - _sell_fee
                                _neg30 = sum(1 for b in hist[-30:] if b < 0) / min(len(hist), 30) if hist else None
                                try:
                                    self.state.conn.execute(
                                        """INSERT INTO exit_signal_shadow
                                           (ticker, asset, signal_time, signal_type,
                                            buffer_at_signal, pct_negative_30,
                                            entry_price_cents, yes_bid_at_signal,
                                            position_count, seconds_to_close,
                                            counterfactual_exit_pnl_cents)
                                           VALUES (?,?,?,?,?,?,?,?,?,?,?)""",
                                        (_ppo_ticker, _ppo_asset, _ppo_now_str, _exit_signal,
                                         _ppo_buffer, _neg30,
                                         _entry_cents, _ppo_bid,
                                         _pos_count, round(_ppo_stc, 1) if _ppo_stc else None,
                                         _cf_exit_pnl))
                                except Exception:
                                    logging.warning("exit_signal_shadow insert failed", exc_info=True)
                                logging.info(
                                    "EXIT_SIGNAL_SHADOW: %s %s @%dc signal=%s buf=%.4f%% bid=%s cf_pnl=%s",
                                    _ppo_asset, _ppo_ticker, _entry_cents, _exit_signal,
                                    _ppo_buffer, _ppo_bid, _cf_exit_pnl)

                if _ppo_wrote:
                    self.state.conn.commit()
            except Exception:
                logging.warning("position_price_monitor failed", exc_info=True)

        # ── Weather position price monitor (REST, 15-min cadence) ─────────
        # Separate from 15M PPO: weather holds 18-24h, WS books are empty,
        # must use REST. Runs every 15 min to match ensemble refresh cadence.
        # Zero impact on 15M PPO (different cadence, different code path).
        if POSITION_PRICE_MONITOR_ENABLED:
            _wx_ppo_now = time.time()
            if _wx_ppo_now - getattr(self, '_wx_ppo_last_poll', 0) >= 900:
                try:
                    _wx_positions = [
                        p for p in self.state.get_open_positions()
                        if p.get("status") == "open"
                        and (p.get("ticker") or "").startswith("KXHIGH")
                    ]
                    if _wx_positions:
                        _wx_ppo_wrote = False
                        for pos in _wx_positions:
                            _wx_ticker = pos["ticker"]
                            _wx_asset = pos.get("asset", "")
                            try:
                                _wx_mkt = self.client.get_market(_wx_ticker)
                                if not _wx_mkt:
                                    continue
                                _wx_yes_ask = _wx_mkt.get("yes_ask")
                                _wx_yes_bid = _wx_mkt.get("yes_bid")
                                _wx_no_ask = _wx_mkt.get("no_ask")
                                _wx_no_bid = _wx_mkt.get("no_bid")
                                # For NO-side positions, the relevant prices are NO ask/bid.
                                # Store in yes_ask/yes_bid columns (reuse schema) but tag source.
                                _wx_display_ask = _wx_no_ask if pos.get("side") == "no" else _wx_yes_ask
                                _wx_display_bid = _wx_no_bid if pos.get("side") == "no" else _wx_yes_bid
                                # Get ensemble data for weather-specific context
                                _wx_city = _wx_asset.replace("_TEMP", "")
                                _wx_ens = None
                                if self.weather_engine:
                                    _wx_ens = self.weather_engine._last_ensemble.get(_wx_city)
                                _wx_ens_mean = None
                                _wx_threshold = None
                                _wx_buffer = None
                                if _wx_ens and _wx_ens.get("combined_members"):
                                    _wx_members = _wx_ens["combined_members"]
                                    _wx_ens_mean = sum(_wx_members) / len(_wx_members)
                                # Parse threshold from ticker
                                try:
                                    _wx_threshold = float(
                                        self.state.conn.execute(
                                            "SELECT threshold FROM evaluated_opportunities "
                                            "WHERE ticker=? AND filter_stage='candidate' LIMIT 1",
                                            (_wx_ticker,)).fetchone()[0])
                                except Exception:
                                    pass
                                if _wx_ens_mean is not None and _wx_threshold and _wx_threshold > 0:
                                    _wx_buffer = round(
                                        (_wx_ens_mean - _wx_threshold) / _wx_threshold * 100, 4)
                                _wx_stc = None
                                try:
                                    _wx_close = _wx_mkt.get("close_time") or _wx_mkt.get("expiration_time")
                                    if _wx_close:
                                        _close_dt = datetime.datetime.fromisoformat(
                                            _wx_close.replace("Z", "+00:00"))
                                        _wx_stc = (_close_dt - datetime.datetime.now(timezone.utc)).total_seconds()
                                except Exception:
                                    pass
                                _wx_now_str = datetime.datetime.now(timezone.utc).strftime(
                                    "%Y-%m-%dT%H:%M:%S.%fZ")
                                # Per-level orderbook ladder: weather monitor runs every
                                # 900s, well outside _scan_ob_cache's 10s freshness window
                                # (15M scanner doesn't tick weather tickers). Cache would
                                # be ~always None — fetch fresh via REST instead. Cost: 1
                                # extra get_orderbook per weather position per 15min cycle
                                # (typically ≤5 positions → trivial).
                                _wx_ob_ladder = None
                                try:
                                    _wx_ob_data = self.client.get_orderbook(_wx_ticker)
                                    _wx_ob_ladder = OrderExecutor._extract_book_levels(_wx_ob_data)
                                except Exception:
                                    logging.debug("WEATHER_PPO ladder fetch failed for %s",
                                                  _wx_ticker, exc_info=True)
                                self.state.conn.execute(
                                    """INSERT INTO position_price_observations
                                       (ticker, asset, observation_time, seconds_to_close,
                                        spot_price, threshold, spot_buffer_pct,
                                        yes_ask_cents, yes_bid_cents,
                                        entry_price_cents, position_count, source,
                                        orderbook_levels_json)
                                       VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)""",
                                    (_wx_ticker, _wx_asset, _wx_now_str,
                                     round(_wx_stc, 1) if _wx_stc else None,
                                     _wx_ens_mean, _wx_threshold, _wx_buffer,
                                     _wx_display_ask, _wx_display_bid,
                                     pos.get("avg_price_cents"),
                                     pos.get("count", 1),
                                     "rest_weather", _wx_ob_ladder))
                                _wx_ppo_wrote = True
                                logging.info(
                                    "WEATHER_PPO: %s %s ask=%s bid=%s ens=%.1fF thresh=%s buf=%s stc=%s",
                                    _wx_asset, _wx_ticker,
                                    _wx_display_ask, _wx_display_bid,
                                    _wx_ens_mean if _wx_ens_mean else 0,
                                    _wx_threshold,
                                    f"{_wx_buffer:.3f}%" if _wx_buffer is not None else "N/A",
                                    f"{_wx_stc/3600:.1f}h" if _wx_stc else "N/A")
                            except Exception:
                                logging.warning("WEATHER_PPO: failed for %s", _wx_ticker, exc_info=True)
                        if _wx_ppo_wrote:
                            self.state.conn.commit()
                except Exception:
                    logging.warning("weather_position_monitor failed", exc_info=True)
                self._wx_ppo_last_poll = _wx_ppo_now

    # ── Run ───────────────────────────────────────────────────────────────

    def run(self):
        self._setup_signals()
        self.startup()

        mode = "LIVE" if not OBSERVATION_MODE else "observation"
        logging.info(f"Entering main loop ({mode} mode)...")
        _consecutive_errors = 0
        _incident_alerted = False
        try:
            while not self._shutdown.is_set():
                loop_start = time.time()
                try:
                    self._tick()
                except Exception as e:
                    self._last_error = str(e)
                    self._last_error_time = time.time()
                    _consecutive_errors += 1
                    # Capture deepest frame so first-fire Telegram alerts
                    # are diagnosable without journalctl. Apr 27 2026
                    # incident: a single `tuple index out of range` fired,
                    # self-recovered, and the trace was unrecoverable from
                    # journal retention afterward.
                    err_loc = _extract_tick_error_location(e)
                    logging.error("Tick error (%d consecutive) at %s",
                                  _consecutive_errors, err_loc,
                                  exc_info=True)

                    if _TELEGRAM:
                        if _consecutive_errors <= 1:
                            # First error: standard warning with dedup
                            _TELEGRAM.send(
                                f"\u26a0\ufe0f Tick error at `{err_loc}`: "
                                f"{str(e)[:200]}",
                                dedup_key="tick_error")
                        elif _consecutive_errors == 3 and not _incident_alerted:
                            # 3 consecutive: CRITICAL escalation
                            _TELEGRAM.send(
                                f"\U0001f6a8 *INCIDENT: BOT BLOCKED*\n"
                                f"{_consecutive_errors} consecutive tick "
                                f"errors in {_consecutive_errors * 5}s\n"
                                f"At: `{err_loc}`\n"
                                f"Error: `{str(e)[:150]}`\n"
                                f"Auto-restart in 30s if not resolved.")
                            _incident_alerted = True
                        elif _consecutive_errors % 12 == 0 and _incident_alerted:
                            # Every 60s during sustained outage: update
                            _TELEGRAM.send(
                                f"\U0001f6a8 *INCIDENT ONGOING*: "
                                f"{_consecutive_errors} consecutive errors "
                                f"({_consecutive_errors * 5}s blocked)\n"
                                f"At: `{err_loc}`\n"
                                f"Error: `{str(e)[:150]}`")

                    # Auto-restart: 6 consecutive errors = 30s blocked
                    # systemd Restart=always brings us back up clean
                    if _consecutive_errors >= 6:
                        logging.critical(
                            "AUTO-RESTART: %d consecutive tick errors, "
                            "exiting for systemd restart",
                            _consecutive_errors)
                        if _TELEGRAM:
                            _TELEGRAM.send(
                                f"\U0001f504 *AUTO-RESTART*: "
                                f"{_consecutive_errors} consecutive errors "
                                f"({_consecutive_errors * 5}s blocked). "
                                f"Restarting now.")
                            time.sleep(1)  # let Telegram send
                        os._exit(1)

                    time.sleep(5)
                    continue

                # Successful tick — check for recovery
                if _consecutive_errors > 0:
                    if _incident_alerted and _TELEGRAM:
                        _TELEGRAM.send(
                            f"\u2705 *INCIDENT RECOVERED*: Bot resumed "
                            f"after {_consecutive_errors} consecutive "
                            f"errors ({_consecutive_errors * 5}s blocked)")
                    elif _consecutive_errors >= 2:
                        logging.warning(
                            "Recovered from %d consecutive tick errors",
                            _consecutive_errors)
                    _consecutive_errors = 0
                    _incident_alerted = False

                elapsed = time.time() - loop_start
                sleep_time = max(0, SCAN_INTERVAL_SECONDS - elapsed)
                self._shutdown.wait(timeout=sleep_time)
        finally:
            self._cleanup()

    def _cleanup(self):
        logging.info("Shutting down...")
        if hasattr(self, 'executor'):
            for asset in list(self.executor._active_orders):
                try:
                    self.executor._cancel_order(asset, "shutdown")
                except Exception:
                    pass
        if hasattr(self, 'egarch_estimator'):
            self.egarch_estimator._save_state()
            logging.info(
                "EGARCH buffer saved on shutdown: BTC=%d ETH=%d SOL=%d XRP=%d",
                len(self.egarch_estimator._returns["BTC"]),
                len(self.egarch_estimator._returns["ETH"]),
                len(self.egarch_estimator._returns["SOL"]),
                len(self.egarch_estimator._returns["XRP"]))
        if hasattr(self, 'mz_tracker'):
            self.mz_tracker.save_state()
            logging.info("MZ tracker state saved on shutdown")
        if hasattr(self, 'vol'):
            self.vol.save_rk_state()
            logging.info(
                "RK state saved on shutdown: BTC=%d ETH=%d SOL=%d XRP=%d returns",
                len(self.vol._returns["BTC"]), len(self.vol._returns["ETH"]),
                len(self.vol._returns["SOL"]), len(self.vol._returns["XRP"]))
            self.vol._save_adaptive_state()
            logging.info(
                "Adaptive jump state saved on shutdown: BTC=%d ETH=%d SOL=%d XRP=%d obs",
                len(self.vol._adaptive_returns_15s["BTC"]),
                len(self.vol._adaptive_returns_15s["ETH"]),
                len(self.vol._adaptive_returns_15s["SOL"]),
                len(self.vol._adaptive_returns_15s["XRP"]))
        if hasattr(self, 'kalshi_feed') and self.kalshi_feed:
            self.kalshi_feed.stop()
        # Stop H-3a snapshotter — it holds its OWN sqlite connection
        # (separate from self.state.conn), but if join times out the
        # daemon thread is force-killed at process exit which can leave
        # a partial WAL segment. Bumped to 25s (one tick + commit + slack)
        # and we log if still alive after timeout (round-1 wiring #4).
        if hasattr(self, 'market_obs_snapshotter') and self.market_obs_snapshotter is not None:
            try:
                self.market_obs_snapshotter.stop()
                self.market_obs_snapshotter.join(timeout=25.0)
                if self.market_obs_snapshotter.is_alive():
                    logging.warning(
                        "Market obs snapshotter join timed out — thread still "
                        "alive at shutdown. Daemon will be force-killed; "
                        "WAL recovery on next startup."
                    )
            except Exception as e:
                logging.warning(f"Market obs snapshotter stop failed: {e}")
        # snapshot_builder has no thread — nothing to stop
        if hasattr(self, 'supabase_syncer') and self.supabase_syncer:
            self.supabase_syncer.stop()
        if hasattr(self, 'coinglass'):
            self.coinglass.stop()
        if hasattr(self, 'cross_feed') and self.cross_feed:
            self.cross_feed.stop()
        if hasattr(self, 'dvol_fetcher'):
            self.dvol_fetcher.stop()
        self.feed.stop()
        # R-p7-deploy-r8: drain async predict pool BEFORE closing state.db so
        # in-flight UPDATEs land. Worker holds a sqlite connection that will
        # error if state.close() runs first.
        try:
            _calmlp_drain_pool(timeout_sec=5.0)
        except Exception as e:
            logging.warning(f"cal_mlp pool drain failed: {e}")
        self.state.close()
        if _TELEGRAM:
            _TELEGRAM.send("\U0001f534 Bot shutting down")
        logging.info("Bot stopped.")


# ═════════════════════════════════════════════════════════════════════════════
#  Entrypoint moved to bot/__main__.py — `python -m bot` invokes it.
# ═════════════════════════════════════════════════════════════════════════════
